-- ============================================================
-- 迁移：活动库加内容栏位，写入客户的手册与模组一脚本（Keep 规格 K02／K03，§4.1、§4.2）
-- 日期：2026-09-23
-- ============================================================
--
-- 十一个新栏位加三百句 UPDATE。**完全可以重复执行**：
--   - 加栏位：每一栏先查 information_schema，已经有了就跳过（与 2026-09-10 的 LOGO 同一个写法）。
--   - UPDATE：每一格只在「还没填」时才写，见下面【重跑不盖掉后台填过的东西】。
--
--   node deploy/migrate.mjs            ← 只检查
--   node deploy/migrate.mjs --confirm  ← 真的执行
--
-- 【什么时候跑】
-- **部署新版程式码之前**（与其余 T2 迁移同一条规矩）。反过来也不会坏，但有两个看得见的差别：
--   - 先部署、没跑迁移：家长端读得到活动，新栏位全是空的；后台改新栏位（小提醒、脚本……）会失败。
--   - 先跑迁移、还没部署：旧程式码读步骤时要求每一步都有图，这次写进去的步骤都没有图，
--     于是旧程式码把它们读成「零步」。今天没有任何一支活动填了目标月龄，家长一支都配不到，看不到差别。
--
-- 【这些栏位是什么】（Keep 规格 §4.1）
-- age_label、people、need、trains、easier、harder、tip、deeper：客户手册那张卡的原文
--   （适龄「6个月–3岁」、人物配置、需要什么、练什么、简单／难一点、小提醒、想深入练）。
--   age_min_month／age_max_month 照旧由适龄解析（src/t2/activitySeed.ts 的 parseAgeRange）；
--   这一版三百张卡的适龄与种子的原文逐张相同，所以这里不动那两栏。
-- guide：模组一（A001–A020）的影片导引脚本（JSON，形状见 src/t2/types.ts 的 ActivityGuide）。
--   其余两百八十支是 NULL。脚本的「画面」与「拍摄提示」是给拍片的人看的，不写进来。
-- poster_url、video_seconds：示范片的封面与片长（规格 §6）。**这份迁移不写**：片子放哪里还没定
--   （§9 第 1 题），由票 3 另外补。
-- steps：手册「怎么玩」三到五步写成 [{"imageUrl":null,"instruction":"…"}]。步骤的图改为选填
--   （ADR-0008）：客户的手册只有文字，照旧规则三百支没有一支存得进步骤。
--
-- 【内容从哪里来】
-- 客户的 NEWT2/T2视频_20260923.zip 里的两份 docx，原封不动取出来放在 NEWT2/ 底下（zip 含 mp4，不进 git）。
-- 由 scripts/t2-extract-activity-content.ts 抽成 src/t2/activityContent.ts，再印成底下标记之间的
-- UPDATE。**标记之间的区段不要手改**，test/activityContent.test.ts 会重印一次比对。
-- 原文一个字都不改写，含《用语对照表》的禁字 —— 改不改是客户的决定（规格 §7、§9 第 3 题）。
--
-- 【重跑不盖掉后台填过的东西】
-- migrate.mjs --confirm 每次都把每一份迁移从头跑一遍，所以：
--   - 文字栏位与 guide 用 COALESCE，只填 NULL。后台清掉一格存的是空字串，不是 NULL，
--     重跑不会把它填回来；后台也不提供「整份删掉脚本」。
--   - steps 只填**还是空阵列**的那几支（规格 §4.1）。内容团队在后台写过步骤的不动。
--     反过来说：在后台把一支的步骤全部删光，下一次跑迁移会把手册的步骤填回来。
--
-- 【活动库仍不吃 company_id】
-- 活动是森心康的内容（ADR-0005），列在 test/adminScope.structure.test.ts 的 GLOBAL_TABLES。
--
-- 【只有专案 A 需要】
-- 专案 B 没有深度评估，也就没有活动。两边 schema 保持一致最省事，加了留着无害。

-- ── 加栏位 ────────────────────────────────────────────────────
-- 与 deploy/schema.sql 的 CREATE TABLE `activities` 一致（test/activitySeed.test.ts 比对栏位定义与位置）。

-- 手册标题列的适龄原文「6个月–3岁」。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'age_label'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `age_label` VARCHAR(32) DEFAULT NULL AFTER `age_max_month`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 人物配置「亲子」「亲子或全家」「全家」……
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'people'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `people` VARCHAR(16) DEFAULT NULL AFTER `age_label`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 需要什么（原文）。equipment 阵列照旧，给配对与后台用。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'need'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `need` VARCHAR(255) DEFAULT NULL AFTER `equipment`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 练什么。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'trains'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `trains` VARCHAR(255) DEFAULT NULL AFTER `need`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 简单（「简单／难一点」的前一半）。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'easier'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `easier` TEXT NULL AFTER `steps`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 难一点（后一半）。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'harder'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `harder` TEXT NULL AFTER `easier`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 小提醒。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'tip'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `tip` TEXT NULL AFTER `harder`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 想深入练（不含「想深入练：」这几个字）。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'deeper'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `deeper` VARCHAR(255) DEFAULT NULL AFTER `tip`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 模组一的影片导引脚本（ActivityGuide）。没有脚本是 NULL。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'guide'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `guide` JSON NULL AFTER `deeper`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 示范片的封面。网址规则同 video_url：只收 https:// 或站内 /… 路径。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'poster_url'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `poster_url` VARCHAR(512) DEFAULT NULL AFTER `video_url`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- 示范片长度（秒）。
SET @has_col := (
  SELECT COUNT(*) FROM information_schema.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities' AND COLUMN_NAME = 'video_seconds'
);
SET @sql := IF(@has_col = 0, 'ALTER TABLE `activities` ADD COLUMN `video_seconds` INT DEFAULT NULL AFTER `poster_url`', 'SELECT 1');
PREPARE stmt FROM @sql;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ── 写入手册与脚本 ────────────────────────────────────────────
-- ── 內容 BEGIN（scripts/t2-extract-activity-content.ts 產生，請勿手改）
UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '6个月–3岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块干净的地板或垫子'),
  `trains` = COALESCE(`trains`, '练手脚交替的爬行动作，是走路和协调的基础。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人趴下来当示范，一起手膝着地。"},{"imageUrl":null,"instruction":"在前方放个玩具或大人张手等他。"},{"imageUrl":null,"instruction":"让孩子爬过来拿。"},{"imageUrl":null,"instruction":"距离从很短开始，慢慢加长。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '爬 30 厘米就够'),
  `harder` = COALESCE(`harder`, '爬过整个房间，或绕个弯。'),
  `tip` = COALESCE(`tip`, '别急着让孩子跳过爬行去学走——爬得多的孩子，手臂力量和协调都更好。动作还不熟的孩子，大人可以用手掌抵住他的脚底给一点助力。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组四（爬行与四点跪）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"今天这个活动叫「我们来爬行」。别小看爬这件事——它是走路、拿笔、甚至日后坐得住的共同基础。只要一块干净的地板，六个月到三岁的孩子都能玩。","principles":["爬行时左手和右脚一起往前、右手和左脚一起往前，这叫「跨侧协调」。","跨侧协调会让大脑左右两边不断来回沟通，是日后学习的重要底子。","手掌撑在地上承重时，手腕、肩膀、手臂的肌肉全都在用力。","这些力量将来要用在拿笔、剪纸、提东西、撑住身体上。","抬头看前方练的是颈部和背部的力量，也让眼睛学会在移动中盯住目标。","肚子离地的四点跪姿，核心肌群一直在稳住身体，这是坐得住、站得稳的前提。","很多家长急着让孩子跳过爬行去学走，但爬得少的孩子，日后常出现手臂无力、写字姿势垮掉。","爬行还是孩子第一次能自己决定「我要去哪里」，这份自主感对探索欲很重要。"],"prep":{"场地":"清出两到三米见方的地面，移开桌角、电线和硬物。地板太滑就铺瑜伽垫或爬行垫。","器材":"一块干净的地板或垫子；一两个孩子喜欢、会发出声音的玩具当目标。","安全检查":"给孩子穿长裤保护膝盖，上衣别太长以免踩到。地面别太凉。全程大人在旁，不要让孩子在床上或高处单独爬。","大人位置":"大人趴在孩子正前方约一米处，脸和他同高。这个位置最关键——孩子要看得到你的脸，才有动力爬过来。"},"shots":[{"name":"大人示范姿势","say":"来，我们一起趴下来。手放在肩膀下面，膝盖放在屁股下面。"},{"name":"摆出目标","say":"你看，小车车在这里。"},{"name":"孩子起步","say":"过来拿，妈妈在这里等你。"},{"name":"交替动作","say":"一只手、一只脚，再一只手、一只脚。"},{"name":"拿到玩具","say":"拿到了！你自己爬过来的！"},{"name":"加长距离","say":"我们再远一点点，好不好？"}],"reactions":[{"if":"孩子趴着不动，只是看着你","then":"把玩具挪到他手边一点点，让他伸手就快碰到。先让他成功一次，再慢慢往后退。"},{"if":"孩子用肚子贴地爬（匍匐前进）","then":"这是正常的过渡。可以用手掌轻轻托住他的肚子，帮他把身体撑起来几秒钟，让他感觉「肚子离地」是什么感觉。"},{"if":"孩子爬两下就趴下不动了","then":"代表手臂力气还不够。缩短距离到 20 厘米，多做几次短的，比一次做很长有效。"}],"mistakes":["把玩具放太远——孩子看不到希望就放弃了。永远从「伸手快碰到」的距离开始。","大人站着或坐着叫他——孩子看不到你的脸，动机会少一半。一定要趴下来到他的高度。","孩子爬到一半就把玩具直接递给他——这样他学到的是「不用爬也拿得到」。"],"down":"距离缩到 20–30 厘米；或大人用手掌抵住他的脚底给一点助力，让他有个使力点。","up":"爬过整个房间；中间绕过一个抱枕；或爬上矮矮的斜坡（一块垫子垫高一端）。","progress":["一开始能爬多远？记下来，一周后再量一次。","看手脚是不是交替的——两手同时往前跳着走，代表协调还没建立。","看肚子有没有离地、抬头能维持多久。"],"outro":"爬行不是「走路之前的过渡」，它本身就是很重要的训练。每天在地上爬几趟，累积起来的手臂力量和协调，将来会用在写字和运动上。"}' AS JSON))
WHERE `id` = 'A001';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '两三张椅子＋一条大浴巾或床单'),
  `trains` = COALESCE(`trains`, '在低矮空间中爬行，认识自己身体的大小。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把椅子排成一列，盖上床单做成山洞。"},{"imageUrl":null,"instruction":"大人在另一头呼唤孩子。"},{"imageUrl":null,"instruction":"让他爬过山洞。"},{"imageUrl":null,"instruction":"出来了就击掌欢呼。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '短短一个山洞'),
  `harder` = COALESCE(`harder`, '加长、或做成转弯的山洞。'),
  `tip` = COALESCE(`tip`, '椅子要摆稳、不会倒。怕黑的孩子用透光的薄布，或两头都掀开一点。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组四（爬行与四点跪）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"用两三张椅子和一条浴巾，家里立刻多一个山洞。钻山洞看起来只是好玩，其实孩子正在学一件很重要的事——认识自己身体有多大。","principles":["要钻过一个洞，孩子必须先判断「这个洞我过得去吗」。","这个判断需要的是身体形象概念，也就是知道自己有多高、多宽、多长。","身体形象不清楚的孩子，常常会撞到桌角、挤不进椅子、跟人靠太近。","钻的时候要低头、缩肩膀、弯背，全身的关节和肌肉都在传回「我现在是什么形状」的讯息。","这类讯息叫本体觉，本体觉清楚的孩子，动作才会精准。","在低矮空间移动，颈部和核心必须同时出力，是很好的姿势控制练习。","钻进去、钻出来还有空间概念在里面：里面、外面、穿过去。","对怕黑或胆子小的孩子，山洞也是很好的安全感练习——洞的另一端有妈妈在等。"],"prep":{"场地":"两三张椅子排成一列，中间留出通道，上面盖大浴巾或床单。椅子要稳，别用有滑轮的。","器材":"两三张餐椅＋一条大浴巾或床单；也可以用桌子盖布、纸箱剪开两端代替。","安全检查":"检查椅子不会被撞倒。洞口两端都要开着，别做成封闭的。孩子在里面时大人要看得到他。","大人位置":"大人蹲在出口那一端，让孩子一钻进去就看得到你。"},"shots":[{"name":"一起搭山洞","say":"我们一起来盖一个山洞好不好？"},{"name":"大人先示范","say":"妈妈先钻进去看看。"},{"name":"孩子进洞","say":"你看，妈妈在那边等你。"},{"name":"洞中互动","say":"我看到你了！"},{"name":"出洞欢呼","say":"钻过来了！"},{"name":"变化玩法","say":"这次我们把山洞变矮一点。"}],"reactions":[{"if":"孩子不敢进去","then":"先把布掀开一半，让洞变成半开放的。或者让他先看着玩偶「钻」过去一次。绝不硬推。"},{"if":"孩子进去就不出来了","then":"这很常见，山洞对孩子来说是很舒服的小空间。让他待一会儿，再用玩具或食物引他出来。"},{"if":"孩子直接把布扯下来","then":"把它变成游戏的一部分：「山洞垮了，我们再盖一次！」重盖的过程也是练习。"}],"mistakes":["洞做得太长太暗——一岁多的孩子会怕。刚开始洞只要一张椅子的长度就够。","大人站在洞口外面喊——蹲下来让孩子在洞里就看得到你的脸。","孩子过不去时直接把洞拆掉——先试着把洞调高一点，让他自己过去。"],"down":"洞口做高一点，让孩子手膝着地就能过去；或只用一张椅子，距离很短。","up":"把洞降低，让他要趴着匍匐前进；或做成转弯的、有两个出口的山洞。","progress":["看孩子进洞前会不会先看一下、判断高度——这代表身体形象在建立。","看他钻的时候会不会撞到头或肩膀。","洞可以做到多矮而他还过得去。"],"outro":"钻山洞不用花钱，几张椅子加一条布就行。孩子在里面缩起身体的那几秒钟，正在学会「我有多大」这件很重要的事。"}' AS JSON))
WHERE `id` = 'A002';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '6个月–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块软垫或床'),
  `trains` = COALESCE(`trains`, '练翻身与身体的旋转控制。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子躺在垫子上。"},{"imageUrl":null,"instruction":"把玩具放在他侧边，引导他翻过去拿。"},{"imageUrl":null,"instruction":"两边轮流练。"},{"imageUrl":null,"instruction":"也可以玩「滚寿司」——用浴巾包着轻轻滚。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人轻推髋部帮一把'),
  `harder` = COALESCE(`harder`, '自己连续翻滚几圈。'),
  `tip` = COALESCE(`tip`, '翻身要从「腿带身体」开始，别拉手臂硬翻。玩滚的时候速度要慢，周围留出空间。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组二（翻身与地面移动）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"在垫子上滚来滚去，是孩子最早学会的移动方式之一。这个看起来像在玩的动作，练的是身体旋转的控制力。","principles":["翻身和滚动需要身体上半段和下半段分开动，这叫躯干旋转。","躯干旋转是所有换姿势动作的基础——从躺到坐、从坐到站、走路时的自然摆动都要用到。","滚动时内耳的前庭系统会接收到大量讯息，告诉大脑「我在动、我往哪个方向动」。","前庭讯息整理得好的孩子，平衡比较稳，也比较不容易晕。","成熟的翻身是「腿先带、骨盆跟着转、躯干再转、肩膀最后转过来」。","如果孩子整个身体像木板一样翻过去，代表躯干旋转还没建立，值得多练。","滚动时全身的皮肤接触地面，也是很好的触觉输入，对情绪安定有帮助。","这个活动完全不需要器材，六个月的宝宝到四岁的孩子都能玩。"],"prep":{"场地":"一块软垫、瑜伽垫，或大人的床。范围要够长，至少能滚两三圈。","器材":"不需要器材；可以准备一个玩具放在终点当目标。","安全检查":"床上进行时大人要在外侧挡住。移开枕头、棉被以免闷住。孩子有癫痫或容易呕吐的情况，先问过治疗师。","大人位置":"大人跪在垫子旁边，手可以随时扶住孩子的骨盆或肩膀。"},"shots":[{"name":"起始姿势","say":"我们躺下来，手放在肚子上。"},{"name":"从腿开始带","say":"我们把这只脚跨过去。"},{"name":"骨盆先转","say":"屁股转过去了，身体跟着来。"},{"name":"完成翻身","say":"翻过来了！"},{"name":"连续滚动","say":"我们滚到那边去拿玩具。"},{"name":"两边都练","say":"换另外一边滚回来。"}],"reactions":[{"if":"孩子整个身体像木板一样翻过去","then":"这代表躯干旋转还没建立。用手带着他的膝盖先过去，等一两秒让骨盆先转，再让上半身跟上。"},{"if":"孩子只往同一边翻","then":"把玩具放在他不常翻的那一侧，多引导几次。两侧差太多要跟治疗师提一下。"},{"if":"孩子滚几下就哭或想吐","then":"立刻停下来，让他坐起来安静一会儿。前庭敏感的孩子要循序渐进，一次一两圈就够。"}],"mistakes":["抓着孩子的手把他整个人拉过去——这样他自己完全没出力。要从腿和骨盆带。","一次滚太多圈——前庭刺激过量会让孩子头晕、烦躁，甚至影响接下来一整天的情绪。","只在同一侧练——两边都要做，次数尽量一样。"],"down":"大人全程用手托着骨盆协助转动；或在垫子下垫一点点高度，顺着坡度滚比较省力。","up":"让孩子自己从躺到趴、再从趴到躺，连续换姿势；或滚到指定的位置拿东西再滚回来。","progress":["看有没有出现「腿先、骨盆、躯干、肩膀」的分节顺序。","看两侧翻身的流畅度是不是差不多。","记录能连续滚几圈而不喊停。"],"outro":"滚动是最早的移动方式。让孩子在垫子上多滚一滚，躯干的旋转能力建立起来，日后换姿势、走路、运动都会更顺。"}' AS JSON))
WHERE `id` = 'A003';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '用各种动物走法活动全身，练力量和协调。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"小熊走：手掌脚掌着地、屁股抬高往前走。"},{"imageUrl":null,"instruction":"螃蟹走：仰着身体、手脚撑地横着走。"},{"imageUrl":null,"instruction":"兔子跳：双脚并拢往前跳。"},{"imageUrl":null,"instruction":"青蛙跳：蹲着往前跳。"},{"imageUrl":null,"instruction":"每种走几步就换下一种。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每种走三五步'),
  `harder` = COALESCE(`harder`, '每种走一段距离，或比赛谁走得稳。'),
  `tip` = COALESCE(`tip`, '小熊走特别累，几步就有效果，不用勉强走远。全家一起做，孩子会玩得更起劲。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"熊走、螃蟹走、兔子跳、毛毛虫爬——学动物走路一样器材都不用，却能把全身的肌肉练一遍。","principles":["每一种动物走法用到的肌肉都不一样，换着做等于全身都练到。","熊走（手脚着地、膝盖离地）练的是手臂承重和核心稳定。","螃蟹走（背朝下、用手脚撑起身体）练的是肩膀后侧和屁股的力量，这两个地方现代孩子普遍偏弱。","兔子跳练的是双脚同时推蹬和落地缓冲。","毛毛虫爬（手往前走、脚跟上）练的是核心和肩膀的连动。","模仿动物需要孩子先看懂动作、再用自己的身体做出来，这是动作计划能力。","动作计划不好的孩子，学新动作特别慢，体育课容易跟不上。","这些动作全都是闭锁链运动——手或脚固定在地上出力，对关节的稳定特别有帮助。","加上动物的叫声和表情，孩子会玩得更投入，运动量自然就上去了。"],"prep":{"场地":"客厅或走廊清出一条三到五米的通道，地面防滑。","器材":"不需要任何东西；可以准备动物图卡增加趣味。","安全检查":"地板别太滑，最好光脚或穿防滑袜。螃蟹走时注意手腕，觉得痛就停。孩子手腕受过伤要避开熊走和螃蟹走。","大人位置":"大人和孩子并排做，一边做一边发出动物的声音。"},"shots":[{"name":"熊走示范","say":"我们来当大熊——手脚着地，屁股翘高高。"},{"name":"螃蟹走","say":"螃蟹是这样走的，肚子朝上！"},{"name":"兔子跳","say":"兔子要双脚一起跳。"},{"name":"毛毛虫","say":"手往前走，脚慢慢跟上来。"},{"name":"换他出题","say":"换你决定我们当什么动物！"},{"name":"接力比赛","say":"看谁先熊走到那边！"}],"reactions":[{"if":"孩子熊走时膝盖一直碰地","then":"代表手臂和核心力气还不够。缩短距离到两三步，或先练「手脚着地维持三秒」。"},{"if":"孩子螃蟹走时屁股掉下来","then":"先练「桥式」——躺着把屁股抬起来维持几秒，力量够了再练螃蟹走。"},{"if":"孩子只想做一种动物","then":"先顺着他，让他做熟一种再慢慢加。可以用「今天的动物是什么」的抽卡方式增加新鲜感。"}],"mistakes":["一次做太多种——两三岁的孩子记不住，先练熟一两种就好。","距离拉太长——熊走五步就很累了，宁可多做几趟短的。","只叫孩子做、大人在旁边看——大人一起做，孩子的投入度完全不同。"],"down":"距离缩短到三步；只做最简单的熊走和兔子跳；或在垫子上做减少手腕压力。","up":"加长距离、加上转弯；两种动物交替走（熊走三步换兔子跳三步）；或加上「木头人」的暂停指令。","progress":["熊走时膝盖能离地多久不碰地。","螃蟹走屁股能撑起来走几步。","能记住并做出几种不同的动物走法。"],"outro":"学动物走路不用器材、不用场地，五分钟就能让孩子全身热起来。每天换一种动物，一个星期就把全身肌肉练过一轮。"}' AS JSON))
WHERE `id` = 'A004';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '练「说停就停」的自我控制，也练平衡。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一个人当鬼，背对大家喊「一、二、三，木头人！」"},{"imageUrl":null,"instruction":"其他人趁机往前走，喊完要立刻定住不动。"},{"imageUrl":null,"instruction":"动了的人回到起点。"},{"imageUrl":null,"instruction":"轮流当鬼。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '慢慢走、定住两秒'),
  `harder` = COALESCE(`harder`, '跑着走、定住五秒不能晃。'),
  `tip` = COALESCE(`tip`, '这个游戏练的是「刹车」能力——不只是好玩，对冲动控制和平衡都很有帮助。笑场没关系，能停住就好。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组六（轮流等待·互动规则）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"一二三木头人，是最经典的儿童游戏，也是最好的自我控制训练。孩子要在跑得最开心的时候，突然把自己停住。","principles":["「说停就停」用到的是抑制能力——大脑踩煞车的功能。","抑制能力好的孩子，比较不会冲动、插话、抢东西、想到什么做什么。","这个能力和日后的专注力、情绪控制直接相关。","要停住不动，还需要肌肉同时用力把身体固定在某个姿势，这是很好的核心和平衡练习。","停在奇怪的姿势时，孩子必须知道自己身体现在长什么样，这是身体形象的练习。","听到口令才动、听到口令才停，同时练了听觉注意力。","游戏的规则很简单，但孩子必须记住它并遵守，这也是规则理解的练习。","「停」这个字练到反射，在马路边可能真的会救孩子一命。"],"prep":{"场地":"客厅或户外空地，五到十米的直线距离，地面清空防滑。","器材":"不需要任何东西。","安全检查":"地面别太滑，注意周围没有桌角。孩子急停时可能会跌倒，铺垫子或在草地上更安全。","大人位置":"大人当鬼，背对孩子站在终点，喊完口令再转身。"},"shots":[{"name":"说明规则","say":"我喊一二三木头人，你就要停住不能动。"},{"name":"开始前进","say":"一、二、三——"},{"name":"突然喊停","say":"木头人！"},{"name":"检查动作","say":"我看到你动了喔！"},{"name":"换孩子当鬼","say":"换你来喊。"},{"name":"加难度","say":"这次要用单脚站着停。"}],"reactions":[{"if":"孩子停不住，一直在动","then":"先把节奏放慢，口令喊长一点给他反应时间。也可以先玩「慢动作走」，让他习惯控制速度。"},{"if":"孩子被抓到就生气","then":"游戏开始前先说好「被抓到很正常，我们再来一次」。大人自己也要被抓到几次，让他看到输了没关系。"},{"if":"孩子完全不想停，只想一直跑","then":"先改成大人牵着他一起跑、一起停，用身体带他感觉「停」的动作。"}],"mistakes":["口令喊太快——两三岁的孩子需要一到两秒的反应时间。","抓得太严格——一点点晃动就说他动了，孩子会失去兴趣。刚开始宽松一点。","只让孩子当木头人——换他当鬼，控制感和乐趣完全不一样。"],"down":"距离缩短；口令喊慢一点；允许小幅度晃动；大人牵着一起做。","up":"指定停住的姿势（单脚站、蹲着、手举高）；缩短口令时间；加入「只能走不能跑」的规则。","progress":["从听到口令到真的停住，需要几秒。","能不能维持指定姿势三到五秒不动。","被抓到时的情绪反应有没有比较平稳。"],"outro":"一二三木头人练的是「踩煞车」的能力。孩子在游戏里练到「说停就停」，日后在教室里、在马路边，都用得上。"}' AS JSON))
WHERE `id` = 'A005';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要（也可用红绿色的纸）'),
  `trains` = COALESCE(`trains`, '听信号控制自己的动作，练反应与自控。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"喊「绿灯」孩子往前走，喊「红灯」立刻停。"},{"imageUrl":null,"instruction":"可以加「黄灯」＝慢慢走。"},{"imageUrl":null,"instruction":"信号变换的速度可快可慢。"},{"imageUrl":null,"instruction":"轮流当发号施令的人。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '只用红绿两个信号、慢慢换'),
  `harder` = COALESCE(`harder`, '加快切换，或加上黄灯。'),
  `tip` = COALESCE(`tip`, '玩熟了可以连到真实的过马路，孩子会更懂交通规则。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组九（跑步与变向）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"绿灯走、红灯停、黄灯慢慢走。这个游戏把交通规则变成了自我控制的练习，顺便还教会孩子过马路要看灯。","principles":["和木头人一样，这个游戏练的是抑制能力——听到信号就要改变正在做的事。","不同的是，这里有三种信号对应三种反应，孩子要同时记住三条规则。","同时保有多条规则并快速切换，练的是工作记忆和认知弹性。","认知弹性好的孩子，遇到变化比较不会卡住或崩溃。","用颜色当信号，还练到了视觉注意力和颜色辨识。","如果改用声音当信号，就变成听觉注意力的练习。","黄灯的「慢慢走」比停和走都难，因为要控制速度而不是全开或全关。","这个游戏直接连结到真实生活的交通安全，学到的东西马上用得上。"],"prep":{"场地":"客厅或走廊，五米以上的直线距离。","器材":"不需要器材；也可以用红、黄、绿三张色纸增加视觉提示。","安全检查":"地面防滑、清空障碍物。急停时容易跌倒，注意周围没有硬角。","大人位置":"大人站在孩子前方，手上拿着色纸或用口令发信号。"},"shots":[{"name":"说明三个规则","say":"绿灯走、红灯停、黄灯慢慢走。"},{"name":"绿灯前进","say":"绿灯！"},{"name":"红灯急停","say":"红灯！"},{"name":"黄灯慢走","say":"黄灯——慢慢走。"},{"name":"快速切换","say":"绿灯、红灯、绿灯！"},{"name":"换孩子指挥","say":"换你当交通警察。"}],"reactions":[{"if":"孩子记不住三个颜色的意思","then":"先只玩红灯和绿灯，熟了再加黄灯。规则一次加一条。"},{"if":"孩子红灯还继续走","then":"把色纸举高一点、口令喊大声一点，同时给视觉和听觉提示。"},{"if":"孩子黄灯还是用跑的","then":"黄灯最难。可以改成「黄灯要走得像乌龟一样慢」，给他一个具体的画面。"}],"mistakes":["一开始就三个颜色一起上——先两个，熟了再加。","只用口令不给视觉——搭配色纸，孩子学得快很多。","切换太快让孩子一直失败——刚开始每个信号维持三到五秒。"],"down":"只玩红灯绿灯两种；信号维持久一点；大人牵着手一起做。","up":"加入黄灯；加快切换速度；改用声音当信号（拍手一下走、两下停）；或加上倒退走的蓝灯。","progress":["能不能同时记住并执行三条规则。","从看到信号到反应的时间有没有变快。","黄灯时能不能真的放慢而不是照常走。"],"outro":"红灯停绿灯行，练的是「听信号改变行为」。这个能力在教室里叫听指令，在马路上叫交通安全，都是孩子每天用得到的。"}' AS JSON))
WHERE `id` = 'A006';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '地板上的一条线（磁砖缝、胶带、或一条绳子）'),
  `trains` = COALESCE(`trains`, '练平衡和方向控制。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在地上找一条线，或贴一条胶带。"},{"imageUrl":null,"instruction":"让孩子沿着线走过去。"},{"imageUrl":null,"instruction":"眼睛看前方，不要一直低头看脚。"},{"imageUrl":null,"instruction":"走到底转身再走回来。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '宽一点的线、可以牵手'),
  `harder` = COALESCE(`harder`, '脚跟贴脚尖走，或倒着走。'),
  `tip` = COALESCE(`tip`, '家里的磁砖缝就是现成的平衡木——比买器材方便，效果一样好。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"地板上一条磁砖缝、一条胶带、一根绳子，就是一条平衡木。走直线看起来简单，其实同时在练平衡、方向控制和专注力。","principles":["走直线时支撑面变窄，身体必须不断做微调才不会偏掉。","这些微调靠的是前庭系统、视觉和本体觉三个系统一起工作。","三个系统合作得好，孩子走路才稳、跑步才不会跌倒。","脚跟接脚尖的走法（一步接一步）难度更高，是标准的平衡测验动作。","眼睛要看着前方的目标而不是看脚，这练的是用视觉稳定身体。","一直低头看脚的孩子，通常是对自己的平衡没有信心。","走直线时双手会自然张开帮忙平衡，这是身体自己找到的策略。","这个活动完全不花钱，家里的磁砖缝就是现成的线。"],"prep":{"场地":"地板上找一条现成的线：磁砖缝、地板接缝，或贴一条胶带、放一条绳子。长度两到三米。","器材":"地板上的一条线（磁砖缝、胶带、或一条绳子）；也可以用两条绳子做成「小路」。","安全检查":"两侧留出空间，跌倒时不会撞到东西。光脚或穿防滑袜，别穿袜子在光滑地板上走。","大人位置":"大人走在孩子前方或旁边，可以伸手随时扶一把，但尽量不要真的扶住。"},"shots":[{"name":"准备线","say":"我们来走这条线。"},{"name":"大人示范","say":"眼睛看前面，不要看脚。"},{"name":"孩子起步","say":"慢慢走，踩在线上。"},{"name":"脚跟接脚尖","say":"这次脚跟碰脚尖，像走钢索。"},{"name":"手张开平衡","say":"手打开可以帮忙平衡。"},{"name":"倒着走","say":"我们倒着走回来！"}],"reactions":[{"if":"孩子一直踩到线外","then":"先用两条绳子做成 20 厘米宽的「小路」，走在路里面就算过关。宽度再慢慢缩小。"},{"if":"孩子一直低头看脚","then":"在终点放一个玩具或让大人站着，跟他说「看着妈妈走过来」。给眼睛一个目标。"},{"if":"孩子走两步就跳出去","then":"把距离缩短到一米，先让他成功走完，再慢慢加长。"}],"mistakes":["线拉太长——三岁的孩子走一米就够了，走不完会失去兴趣。","一直提醒「看脚、踩好」——反而让他更低头。要引导他看前方。","孩子晃的时候马上扶住——让他自己找回平衡才是练习。手放在旁边准备着就好。"],"down":"用两条绳子做成宽一点的「小路」；距离缩到一米；牵着一只手走。","up":"脚跟接脚尖走；倒着走；侧着走；头上顶一本书走；或在线上放几个障碍要跨过去。","progress":["能连续踩在线上走几步不偏出去。","走的时候是看前方还是一直低头。","能不能做到脚跟接脚尖的走法。"],"outro":"家里的磁砖缝就是最好的平衡木。每天走个两三趟，孩子的平衡和专注都在进步，什么都不用买。"}' AS JSON))
WHERE `id` = 'A007';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '两条毛巾或两张纸摆在地上'),
  `trains` = COALESCE(`trains`, '练双脚跳和落地的缓冲。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"用两条毛巾在地上摆出一条「小河」。"},{"imageUrl":null,"instruction":"让孩子双脚跳过去，不能掉进河里。"},{"imageUrl":null,"instruction":"落地时提醒「膝盖弯一弯」。"},{"imageUrl":null,"instruction":"河的宽度慢慢加大。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '河很窄，跨过去也行'),
  `harder` = COALESCE(`harder`, '河变宽，要用力跳。'),
  `tip` = COALESCE(`tip`, '落地要屈膝缓冲、轻轻落下——比跳得远更重要。在有弹性的地面（垫子、地毯）玩，别在硬地板上反复跳。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十（跳跃与落地）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"地上摆两条毛巾，中间就是一条小河。跳过去的那一瞬间，孩子练的是双脚同时用力和落地的缓冲。","principles":["双脚同时跳需要两条腿同时出力、同时离地，这比单脚跳更早发展但也需要练。","起跳前要先蹲下蓄力，这个「蹲—伸」的顺序是所有跳跃动作的基础。","落地时膝盖要弯曲缓冲，这个动作保护膝盖和脊椎，也是运动伤害预防的关键。","落地不会缓冲的孩子，跑跳时关节承受的冲击会大很多。","跳跃时全身的肌肉瞬间收缩，是很强的本体觉输入，对身体觉察和情绪安定都有帮助。","要判断「这条河我跳得过去吗」，用到的是距离判断和身体形象。","跳过去需要一点点勇气，成功的经验会累积成自信。","摆宽一点、窄一点，难度随时可以调，一个活动能玩很久。"],"prep":{"场地":"客厅或走廊，地面有弹性最好（瑜伽垫、地毯）。硬地板要铺垫子。","器材":"两条毛巾或两张纸摆在地上，中间的距离就是「河」的宽度。","安全检查":"落地处一定要防滑。硬地板务必铺垫子。孩子有关节问题或体重较重，跳跃次数要减少。","大人位置":"大人站在河的另一边，张开手迎接。"},"shots":[{"name":"摆出小河","say":"这里是一条小河，我们要跳过去。"},{"name":"示范蹲下蓄力","say":"先蹲一下，再跳！"},{"name":"双脚起跳","say":"两只脚一起！"},{"name":"落地缓冲","say":"落地的时候膝盖弯一弯。"},{"name":"加宽","say":"我们把河变宽一点点。"},{"name":"连续跳","say":"这次有三条河喔！"}],"reactions":[{"if":"孩子一只脚先跨过去","then":"这是跨越不是跳跃。先牵着他的双手一起跳，让他感觉双脚同时离地的感觉。"},{"if":"孩子落地时腿是直的、很大声","then":"提醒「落地要像小猫一样轻」。也可以先练原地跳，专门练落地缓冲。"},{"if":"孩子不敢跳","then":"把河缩到只有一条毛巾的宽度，或干脆缩到 5 厘米。先让他成功一次，勇气就出来了。"}],"mistakes":["河摆太宽——孩子跳不过去会变成跨过去，练不到跳。宁可从很窄开始。","在硬地板上跳很多次——膝盖和脚踝会累积负担，一定要铺垫子。","忽略落地的动作——跳得高不重要，落地会不会缓冲才重要。"],"down":"河的宽度缩到 10 厘米甚至更窄；牵着双手一起跳；或改成原地双脚跳。","up":"加宽距离；连续跳过三条河；跳过去之后马上转身跳回来；或改成单脚跳（五岁以上）。","progress":["能跳过多宽的河。","起跳前会不会先蹲下蓄力。","落地时膝盖有没有弯曲缓冲、声音大不大。"],"outro":"跳过小河练的不只是跳得远，更是落地会不会保护自己。两条毛巾就能玩，宽度随时调，孩子每次都有成就感。"}' AS JSON))
WHERE `id` = 'A008';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '练单脚站的平衡能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"站好，抬起一只脚。"},{"imageUrl":null,"instruction":"手可以张开帮忙保持平衡。"},{"imageUrl":null,"instruction":"一起数「一、二、三……」看能撑多久。"},{"imageUrl":null,"instruction":"两只脚都要练。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '扶着墙或椅背站'),
  `harder` = COALESCE(`harder`, '不扶手，或闭上眼睛试试。'),
  `tip` = COALESCE(`tip`, '参考值：三岁能站两三秒、四岁约五秒、五岁约十秒。刷牙的时候顺便站一下，每天两次很快就进步。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"单脚站三秒钟，看起来简单，却是很标准的平衡发展指标。什么都不用准备，随时随地都能玩。","principles":["单脚站时支撑面只剩一只脚，身体必须靠踝关节和髋关节不断微调。","这些微调动作叫平衡反应，是跌倒时能不能救回来的关键。","单脚站也是走路的基础——走路时其实有一半的时间是单脚在支撑。","单脚站不稳的孩子，走路容易拖地、跑步容易跌倒、上下楼梯需要扶。","站的那一侧腿部和臀部的肌肉持续用力，是很好的肌力训练。","闭上眼睛单脚站会更难，因为少了视觉的帮忙，全靠前庭和本体觉。","发展参考：三岁能单脚站约三秒，四岁约五秒，五岁能站十秒左右。","两脚的差异也值得观察——如果一边明显比另一边差很多，值得跟治疗师提一下。"],"prep":{"场地":"平坦防滑的地面，旁边有墙或椅背可以扶。","器材":"不需要任何东西；进阶时可以用软垫增加难度。","安全检查":"旁边留出空间，跌倒时不会撞到。刚开始让孩子靠近墙壁或椅子，需要时可以扶。","大人位置":"大人和孩子面对面一起做，同时数秒数。"},"shots":[{"name":"一起站好","say":"我们来比赛，看谁站得久。"},{"name":"抬起一只脚","say":"把一只脚抬起来。"},{"name":"数秒数","say":"一、二、三、四、五⋯⋯"},{"name":"换脚","say":"换另外一只脚。"},{"name":"进阶玩法","say":"这次我们闭上眼睛试试看。"},{"name":"变成游戏","say":"当一只金鸡，谁先掉下来谁就输！"}],"reactions":[{"if":"孩子站不到一秒就放下来","then":"先扶着墙或椅背练，或让他抬脚的高度低一点（脚尖点地也算）。"},{"if":"孩子一直用同一只脚","then":"刻意提醒换脚。惯用脚会比较稳是正常的，但差太多要留意。"},{"if":"孩子抬脚时膝盖往后勾","then":"提醒「膝盖往前抬，像踏步一样」。往后勾比较省力但练不到。"}],"mistakes":["一开始就要求站很久——三岁能站三秒就很好了，别用大人的标准。","只练惯用脚——两脚都要练，次数一样。","孩子一晃就扶住他——让他自己找回平衡才是练习，手在旁边准备着就好。"],"down":"扶着墙或椅背；抬起的脚脚尖点地；只要求维持一两秒。","up":"闭上眼睛站；站在软垫或枕头上；单脚站着接球或传东西；或单脚站着穿裤子。","progress":["每只脚能站几秒，记录下来每周比一次。","两脚的秒数差多少。","能不能做到闭眼单脚站。"],"outro":"单脚站是很标准的平衡指标。每天刷牙的时候站一下、等电梯的时候站一下，累积起来平衡就稳了。"}' AS JSON))
WHERE `id` = 'A009';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '抱枕、卷起来的棉被'),
  `trains` = COALESCE(`trains`, '练抬脚跨越和单脚站稳的能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在地上放几个抱枕当障碍。"},{"imageUrl":null,"instruction":"让孩子跨过去（不是踩过去）。"},{"imageUrl":null,"instruction":"抬脚的时候另一只脚要站稳。"},{"imageUrl":null,"instruction":"两只脚轮流当先跨的脚。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '很矮的障碍、可以牵手'),
  `harder` = COALESCE(`harder`, '障碍高一点，或连续跨过好几个。'),
  `tip` = COALESCE(`tip`, '障碍一定要软——踢到也不会痛，孩子才敢大胆跨。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组八（上下楼梯与高低差）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把抱枕、棉被卷摆在地上，客厅立刻变成障碍赛道。跨过去的每一步，孩子都在练单脚站稳和抬腿的控制。","principles":["跨越障碍时，一只脚抬起来的那几秒，全身重量都在另一只脚上。","这就是单脚站，只是发生在移动中，难度更高。","抬腿的高度要刚好——太低会绊到，太高会浪费力气，这需要距离判断。","判断「这个障碍有多高、我要抬多高」用到的是视觉和身体形象的整合。","常常绊倒的孩子，通常是这个判断还不够精准。","跨越时身体会稍微往支撑脚那边偏，这是自然的重心转移。","连续跨过几个障碍，还要练到节奏和动作的连贯。","这个活动的难度用障碍高度就能调，从几厘米到膝盖高都可以。"],"prep":{"场地":"客厅清出一条直线通道，两侧留空间。","器材":"抱枕、卷起来的棉被、空的纸盒、绳子——家里任何软的东西都可以当障碍。","安全检查":"障碍一定要用软的、踩到不会滑的东西。别用硬盒子或会滚动的瓶子。旁边留出跌倒的空间。","大人位置":"大人走在孩子旁边，手放在他身旁准备随时扶一把。"},"shots":[{"name":"摆障碍","say":"我们来做一条障碍赛道。"},{"name":"大人示范","say":"脚抬高高，跨过去。"},{"name":"孩子跨第一个","say":"慢慢来，一只脚先过去。"},{"name":"单脚支撑","say":"站稳了，另一只脚再过来。"},{"name":"连续跨越","say":"一个、两个、三个！"},{"name":"加高难度","say":"这次障碍变高了。"}],"reactions":[{"if":"孩子直接踩上去而不是跨过去","then":"障碍太低或太宽。改用窄一点、高一点的东西（卷紧的毛巾）。"},{"if":"孩子跨的时候会晃、要扶东西","then":"代表单脚站还不稳。先单独练金鸡独立，或牵着一只手跨。"},{"if":"孩子一次跨两个、用跳的","then":"把障碍间距拉开，让他必须一个一个跨。"}],"mistakes":["障碍用硬的或会滚的东西——踩到会滑倒，一定要用软的。","障碍摆太高——一岁多的孩子五厘米就够了，太高会跌倒。","间距太密——两个障碍之间至少要有一步的距离，让他能站稳再跨下一个。"],"down":"障碍降到几厘米（一条毛巾平铺）；牵着一只手；障碍之间距离拉大让他有时间站稳。","up":"障碍加高到膝盖；缩短间距；侧着跨；或跨过去之后要转身跨回来。","progress":["能跨过多高的障碍。","跨越时单脚支撑稳不稳、需不需要扶。","能连续跨过几个不停下来。"],"outro":"家里的抱枕和棉被就是最好的障碍。跨过去的那一瞬间，孩子练的是单脚站稳和抬腿的精准控制——这两样正是走路稳不稳的关键。"}' AS JSON))
WHERE `id` = 'A010';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一面墙'),
  `trains` = COALESCE(`trains`, '用力气推东西，全身出力也让身体安定下来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"面对墙站好，双手推墙。"},{"imageUrl":null,"instruction":"用力推十秒，像要把墙推倒一样。"},{"imageUrl":null,"instruction":"休息一下再推。"},{"imageUrl":null,"instruction":"重复三到五次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '轻轻推几秒'),
  `harder` = COALESCE(`harder`, '推久一点，或改成单手推。'),
  `tip` = COALESCE(`tip`, '孩子躁动、静不下来的时候，让他推推墙——这种「出力气」的活动能让身体安定下来，比讲道理有用。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"用力推墙，墙当然不会动，但孩子的身体会因此安定下来。这是最简单也最有效的「本体觉输入」。","principles":["用力推东西时，肌肉和关节会传回大量讯息给大脑，这叫本体觉输入。","本体觉输入有安定神经系统的效果，对停不下来、静不下来的孩子特别有用。","这也是为什么很多孩子在剧烈活动后反而更能坐得住。","推墙时全身从手掌、手臂、肩膀、核心到腿都在同时用力，是全身的等长收缩。","等长收缩（用力但不移动）对关节最安全，任何年龄都适合。","手掌撑在墙上承重，对手腕的稳定很有帮助，这和日后写字的耐力有关。","推的时候需要维持好姿势——脚前后站、身体成一直线，这本身就是姿势练习。","这个活动可以在上课前、写作业前做一分钟，帮孩子把状态调整好。"],"prep":{"场地":"一面结实的墙。避开有挂画、镜子或不稳的隔间墙。","器材":"一面墙就够了；也可以改成推沙发、推大人的手掌。","安全检查":"确认墙是结实的。脚下要防滑。有心脏疾病或血压问题的孩子避免憋气用力，提醒他推的时候要数数（数数就不会憋气）。","大人位置":"大人在旁边一起推，或当孩子的对手手掌对推。"},"shots":[{"name":"站好位置","say":"一只脚在前、一只脚在后，手撑在墙上。"},{"name":"用力推","say":"用力推，我们一起把墙推倒！"},{"name":"数数不憋气","say":"一、二、三、四、五⋯⋯"},{"name":"放松","say":"好，休息一下。"},{"name":"对推游戏","say":"换我们手掌对手掌推。"},{"name":"其他推法","say":"也可以推沙发、推大枕头。"}],"reactions":[{"if":"孩子推的时候憋气、脸涨红","then":"立刻提醒「一边推一边数数」。数数的时候就不可能憋气。"},{"if":"孩子只用手推，身体是软的","then":"提醒「肚子用力、屁股夹紧」，让他感觉全身一起出力。也可以摸摸他的肚子提示。"},{"if":"孩子推两秒就说累了","then":"先从五秒开始，做三次。时间短、次数多，比一次撑很久好。"}],"mistakes":["让孩子憋气用力——务必边推边数数或边说话。","推太久——五到十秒推一次，做三到五次就够，不用一直撑着。","姿势歪掉还继续推——身体要成一直线，塌腰或驼背就先调整姿势。"],"down":"缩短到推三到五秒；改成推沙发或大人的手（比较有回馈感）。","up":"延长到十五秒；改成双手交替单手推；或做「推墙伏地挺身」（身体往墙靠近再推开）。","progress":["能维持正确姿势推多久。","推的时候会不会憋气。","推完之后有没有比较安定、比较坐得住。"],"outro":"推墙一分钟，是最方便的情绪调节工具。上课前、写作业前推一推，孩子的身体安定下来，接下来就坐得住了。"}' AS JSON))
WHERE `id` = 'A011';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块垫子或地毯'),
  `trains` = COALESCE(`trains`, '练手臂和肚子的力气。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子趴下、双手撑地。"},{"imageUrl":null,"instruction":"大人抬起他的大腿（不是脚踝）。"},{"imageUrl":null,"instruction":"孩子用两只手往前走。"},{"imageUrl":null,"instruction":"走几步就放下休息。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '走两三步就好'),
  `harder` = COALESCE(`harder`, '走远一点，或大人抬得更靠近脚踝。'),
  `tip` = COALESCE(`tip`, '抬大腿比抬脚踝省力很多，从大腿开始。手臂有力的孩子，写字才撑得久。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"大人抬着孩子的脚，孩子用两只手往前走——这就是小推车。它是练手臂力量最有效、也最好玩的方式之一。","principles":["用手走路时，全身重量几乎都压在手臂和肩膀上，是很强的承重训练。","手臂和肩膀的力量，直接影响孩子写字的耐力和稳定度。","写几个字就喊手酸的孩子，通常是肩膀和手臂的力气不够。","手掌撑地时手腕呈伸展姿势，这对手腕的稳定性很重要，也和握笔姿势有关。","为了不让肚子垮下去，核心肌群必须全程用力，这是很强的核心训练。","身体要维持一直线，需要肩膀、核心、髋部同时协调，是全身的整合动作。","大量的关节承重也提供了丰富的本体觉输入，有安定情绪的效果。","这个动作还需要孩子信任大人抬着他的脚，是很好的亲子互动。"],"prep":{"场地":"客厅铺垫子或地毯，清出两到三米的通道。","器材":"一块垫子或地毯。","安全检查":"手腕不舒服就停。大人抬脚的高度不要超过孩子的髋部，太高会让腰塌下去。孩子手腕受过伤或有肩膀问题，先问过治疗师。","大人位置":"大人蹲或跪在孩子后方，双手抬住他的大腿（不是脚踝，抬大腿比较省力也比较稳）。"},"shots":[{"name":"起始姿势","say":"趴下来，手撑在肩膀下面。"},{"name":"大人抬腿","say":"我抬起你的脚，你用手走。"},{"name":"开始走","say":"一只手、一只手，慢慢来。"},{"name":"检查腰部","say":"肚子用力，不要掉下来。"},{"name":"短距离完成","say":"走到垫子那一头就赢了！"},{"name":"变化玩法","say":"这次用手推着球走。"}],"reactions":[{"if":"孩子的腰垮下去、屁股翘很高","then":"代表核心力气不够。把抬腿的高度降低（几乎贴地），或缩短距离，先练两三步就好。"},{"if":"孩子手一直弯、撑不住","then":"先练「维持趴撑姿势三秒」，力量够了再走。也可以让他趴在斜坡上（垫高上半身）减轻负担。"},{"if":"孩子说手腕痛","then":"立刻停。改成握拳撑地（减少手腕角度），或改做推墙这类不压手腕的活动。"}],"mistakes":["抬脚踝而不是大腿——抬脚踝会让腰塌下去，也比较不好控制。","距离走太长——三岁的孩子走三到五步就够了。宁可多做几趟短的。","忽略孩子喊手腕痛——手腕不适一定要停，这不是「撑一下就好」的事。"],"down":"抬腿的高度几乎贴地；只走两三步；或改成原地维持趴撑姿势数秒。","up":"加长距离；边走边绕过障碍；走的时候用手推一颗球；或改成孩子自己撑着走（熊走）。","progress":["能走几步而腰不塌下去。","手臂能撑多久不弯。","做完之后有没有喊手酸——酸的时间越来越短代表力气在进步。"],"outro":"小推车是练手臂力气最有效的动作之一。手臂有力了，写字的耐力、拿东西的稳定都会跟着好起来。"}' AS JSON))
WHERE `id` = 'A012';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块垫子或床'),
  `trains` = COALESCE(`trains`, '练屁股和背部的力气，让坐姿站姿更挺。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"躺下、双膝弯起、脚掌踩地。"},{"imageUrl":null,"instruction":"把屁股抬起来，搭成一座小桥。"},{"imageUrl":null,"instruction":"撑住三到五秒再放下。"},{"imageUrl":null,"instruction":"可以让小车从桥下开过去。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '抬一点点就好'),
  `harder` = COALESCE(`harder`, '撑久一点，或抬起一只脚。'),
  `tip` = COALESCE(`tip`, '让小车从桥下开过去，孩子会撑得更久更高——把训练变成游戏，效果自然就来了。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组三（核心稳定与躯干控制）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"躺着把屁股抬起来，身体变成一座小桥。这个动作练的是屁股和背部的力气，直接关系到孩子坐得挺不挺。","principles":["桥式练的是臀大肌和背部伸直肌群，这两组肌肉负责把身体撑直。","这些肌肉没力的孩子，坐着会垮、站着会驼背、走久会喊累。","现代孩子久坐多、活动少，臀部肌肉普遍偏弱。","抬起屁股时核心必须同时收紧，才不会用腰去代偿。","用腰代偿的孩子会腰往上顶而不是屁股用力，这样练不到还可能腰酸。","桥式是闭锁链动作，脚踩在地上、身体固定，对关节很安全。","维持不动的等长收缩，特别能练到肌耐力——也就是撑得久的能力。","这个动作躺着做就行，睡前在床上做几下很方便。"],"prep":{"场地":"垫子或床上，平坦有支撑的表面。太软的床会不好使力。","器材":"一块垫子或床；进阶时可以用一个小球或抱枕夹在膝盖之间。","安全检查":"腰不舒服就停。抬起的高度不用很高，屁股离地就有效。","大人位置":"大人跪在孩子旁边，可以把手放在他的膝盖上给一点提示。"},"shots":[{"name":"躺好准备","say":"躺下来，膝盖弯起来，脚踩在地上。"},{"name":"抬起屁股","say":"屁股夹紧，慢慢抬起来。"},{"name":"维持不动","say":"我们数到五：一、二、三、四、五。"},{"name":"慢慢放下","say":"慢慢放下来，一节一节。"},{"name":"变成游戏","say":"你的桥下面可以开小车喔！"},{"name":"进阶","say":"这次膝盖夹着球。"}],"reactions":[{"if":"孩子抬不起屁股","then":"先把脚往屁股靠近一点（膝盖弯多一点），比较好使力。或大人稍微托一下他的骨盆。"},{"if":"孩子是用腰往上顶，肚子凸出来","then":"提醒「屁股夹紧」而不是「腰用力」。可以让他先夹紧屁股再抬。"},{"if":"孩子撑不到三秒","then":"从一秒开始，抬起来马上放下，做十次。次数多比撑得久更适合刚开始。"}],"mistakes":["要求抬太高——屁股离地、身体成一直线就够了，过高会变成腰反弓。","用腰代替屁股出力——这是最常见的错误，要不断提醒「屁股夹紧」。","放下来太快——慢慢放下的那一段也是训练，别整个人砸下去。"],"down":"脚往屁股靠近；只抬一点点高度；只维持一秒就放下，改成多做几次。","up":"维持十秒；膝盖夹着球；单脚桥（一只脚抬起来）；或在桥的姿势下慢慢左右移动。","progress":["能维持几秒。","身体有没有成一直线（从肩到膝）。","是用屁股出力还是用腰顶。"],"outro":"搭小桥躺着就能做，睡前在床上做个十下。屁股和背有力气了，孩子坐得挺、站得久，写作业的姿势也会跟着好。"}' AS JSON))
WHERE `id` = 'A013';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块垫子'),
  `trains` = COALESCE(`trains`, '练背部的力气，让身体挺得起来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"趴在垫子上，双手往前伸。"},{"imageUrl":null,"instruction":"抬起头、胸口、手和腿，像超人飞一样。"},{"imageUrl":null,"instruction":"撑两三秒放下。"},{"imageUrl":null,"instruction":"重复五次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '只抬头和手'),
  `harder` = COALESCE(`harder`, '手脚一起抬，撑久一点。'),
  `tip` = COALESCE(`tip`, '背部有力的孩子，坐着写字才不容易趴下去。这个动作很累，做五次就够了。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组三（核心稳定与躯干控制）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"趴着把手和脚同时抬起来，像超人在飞。这个动作练的是背部的力气，是让孩子挺得起来的关键。","principles":["超人飞练的是整条背部伸直肌群，从颈部一路到腰部。","这条肌肉负责对抗地心引力，把身体从驼背状态拉直。","背肌无力的孩子，坐着会越坐越垮、写字会趴在桌上、站久会喊腰酸。","抬手抬脚时肩胛骨会往中间收，这个动作对改善圆肩很有帮助。","同时抬起对侧的手和脚（右手左脚），还练到了跨侧协调。","维持姿势时颈部要抬起来，也顺便练了颈部的力量。","这是趴姿动作，对久坐的孩子是很好的姿势平衡——把身体往反方向伸展。","动作本身很像超人，孩子通常很买单，配合度高。"],"prep":{"场地":"垫子或床上，平坦柔软的表面。","器材":"一块垫子；可以准备披风或围巾增加角色扮演的乐趣。","安全检查":"腰不舒服就停。抬起的高度不用高，离地几厘米就有效。有脊椎问题的孩子先问过治疗师。","大人位置":"大人趴在孩子旁边一起做，同时数秒数。"},"shots":[{"name":"趴好准备","say":"趴下来，手往前伸直。"},{"name":"抬手抬脚","say":"超人要起飞了——手和脚一起抬起来！"},{"name":"维持","say":"一、二、三、四、五，飞！"},{"name":"放下休息","say":"降落，休息一下。"},{"name":"对侧版本","say":"这次右手和左脚一起抬。"},{"name":"角色扮演","say":"超人要飞去救人啰！"}],"reactions":[{"if":"孩子只抬得起手、抬不起脚","then":"先只练抬手，或只练抬脚，分开做。力量够了再合起来。"},{"if":"孩子抬起来就憋气","then":"提醒「一边飞一边数数」。数数就不会憋气。"},{"if":"孩子撑不到两秒","then":"从抬起来马上放下开始，做十次。次数多比撑得久更适合起步。"}],"mistakes":["要求抬太高——离地几厘米就够，抬太高腰会不舒服。","憋气用力——一定要边做边数数或边说话。","一次做太久——五秒一次做五次，比一次撑三十秒好。"],"down":"只抬手或只抬脚；抬起来马上放下；在肚子下垫一个薄枕头减轻腰的压力。","up":"维持十秒；对侧手脚抬起；手上拿轻的小物；或在抬起的状态下慢慢左右摆动。","progress":["能维持几秒。","手和脚能不能同时抬起来。","做完之后坐姿有没有比较挺。"],"outro":"超人飞是练背肌最简单的动作。背有力气了，孩子坐着才挺得住、写字才不会越写越趴。"}' AS JSON))
WHERE `id` = 'A014';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几个小玩具、一个篮子'),
  `trains` = COALESCE(`trains`, '练腿的力气，也是收玩具的好方法。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把玩具散在地上，篮子放在桌上。"},{"imageUrl":null,"instruction":"让孩子蹲下捡一个、站起来放进篮子。"},{"imageUrl":null,"instruction":"重复到捡完为止。"},{"imageUrl":null,"instruction":"不要用坐的或跪的，要蹲。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '扶着家具蹲'),
  `harder` = COALESCE(`harder`, '不扶手连续蹲站十次。'),
  `tip` = COALESCE(`tip`, '收玩具的时候顺便练——一次收拾就是几十下蹲站。留意孩子蹲下时脚跟能不能着地。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把玩具散在地上，一个一个蹲下来捡、站起来放进篮子。收玩具的同时，孩子做了几十次深蹲。","principles":["蹲下站起来用到的是大腿前侧、臀部和核心，是下肢最基本的功能性动作。","这个动作每天都在用——捡东西、坐下、起身、上下车。","腿部力气不够的孩子，会用手撑着地板才站得起来，或者干脆坐到地上去捡。","蹲下时膝盖和踝关节要有足够的活动度，长期不蹲的孩子会变得很紧。","站起来的那一瞬间需要重心从后往前移，这是重心转移的练习。","蹲着的时候身体要维持平衡不后倒，核心和脚踝都在工作。","把这个动作藏在「收玩具」里面，孩子做了几十次都不会觉得是在运动。","这也顺便练到了收拾的习惯和任务完成度，一举两得。"],"prep":{"场地":"客厅地板，把玩具散开摆放，篮子放在中间或一侧。","器材":"几个小玩具、一个篮子或箱子。","安全检查":"地面防滑，光脚或穿防滑袜。玩具不要摆在会滑倒的地方。膝盖不舒服的孩子减少次数。","大人位置":"大人和孩子一起收，可以比赛看谁收得多。"},"shots":[{"name":"散开玩具","say":"玩具散得到处都是，我们一起收。"},{"name":"蹲下捡","say":"蹲下来捡，不要坐到地上喔。"},{"name":"站起来","say":"站起来，放进篮子。"},{"name":"重复动作","say":"再来一个、再来一个。"},{"name":"比赛","say":"看谁先收完十个！"},{"name":"进阶","say":"这次捡了要走到那边放。"}],"reactions":[{"if":"孩子直接坐到地上捡","then":"把玩具摆在稍微高一点的地方（矮凳上），让他只能蹲不能坐。或牵着一只手帮他站起来。"},{"if":"孩子站起来要用手撑地","then":"代表腿力还不够。先扶着椅子练蹲站，或减少次数。"},{"if":"孩子蹲下时脚跟离地","then":"脚踝比较紧。可以在脚跟下垫一本薄书，或先做脚踝伸展。"}],"mistakes":["一次要求收太多——十个玩具就是十次深蹲，对小小孩已经够了。","孩子坐下去捡也没关系地放过——坐下去就练不到了，要引导他蹲。","把它讲成「运动」——讲成收玩具的游戏，孩子的抗拒会少很多。"],"down":"玩具摆在矮凳上（不用蹲到底）；只收五个；扶着椅子蹲站。","up":"玩具摆得更散、要走更远；蹲下时要拿两样东西；或加上「蹲着不动数三秒再站起来」。","progress":["能连续蹲站几次不喊累。","站起来需不需要用手撑。","蹲下时脚跟能不能贴地。"],"outro":"收玩具就是最好的深蹲练习。每天玩完收一次，一个月下来孩子做了上千次蹲站，腿的力气自然就出来了。"}' AS JSON))
WHERE `id` = 'A015';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一瓶泡泡水'),
  `trains` = COALESCE(`trains`, '追着泡泡跑跳拍打，练全身活动和眼睛追视。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人吹泡泡。"},{"imageUrl":null,"instruction":"让孩子追着拍破。"},{"imageUrl":null,"instruction":"泡泡高的要跳起来拍，低的要蹲下拍。"},{"imageUrl":null,"instruction":"室内室外都能玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '泡泡吹低一点、慢慢飘'),
  `harder` = COALESCE(`harder`, '吹高吹远，让他跑着追。'),
  `tip` = COALESCE(`tip`, '泡泡是万用道具——躺着看、坐着拍、站着追，每个年龄都好用。注意泡泡水别进眼睛。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十（手眼协调与视动整合）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一瓶泡泡水，就能让孩子跑、跳、拍、追十几分钟。追泡泡看起来只是好玩，其实眼睛和身体都在高速运转。","principles":["泡泡在空中飘动，孩子的眼睛必须一直追着它，这是视觉追踪的最佳练习。","视觉追踪是日后阅读时眼睛沿着行移动的基础，追不好的孩子容易跳行漏字。","要拍破泡泡，眼睛看到的位置要传给手做出动作，这是手眼协调。","泡泡会飘、会变方向，孩子必须预测它会往哪里去，这是动作预判。","追泡泡时会不自觉地跑、跳、伸手、转身，全身都动起来了。","跳起来拍高处的泡泡，练的是跳跃和瞬间发力。","泡泡破掉的瞬间有很强的视觉回馈，这让孩子玩不腻。","对不爱运动的孩子，追泡泡是最容易让他动起来的方式。"],"prep":{"场地":"户外最好（不怕滑）；室内要铺防滑垫，泡泡水会让地板变滑。","器材":"一瓶泡泡水；可以准备两瓶，让孩子也能自己吹。","安全检查":"室内地板会变滑，这是最需要注意的。泡泡水别进眼睛。孩子追泡泡时容易只看上面不看前面，清空周围障碍物。","大人位置":"大人负责吹泡泡，站在孩子侧前方，把泡泡往不同方向吹。"},"shots":[{"name":"吹出泡泡","say":"看，泡泡来了！"},{"name":"眼睛追踪","say":"看着它，它往哪里去？"},{"name":"伸手拍破","say":"拍破它！"},{"name":"跳起来拍","say":"这个好高，要跳起来！"},{"name":"用脚踩","say":"这次用脚踩破。"},{"name":"换他吹","say":"换你吹给妈妈追。"}],"reactions":[{"if":"孩子只看不动手","then":"先吹几个大泡泡、慢慢飘的，让他容易拍到。成功几次就会开始追了。"},{"if":"孩子追泡泡时一直跌倒","then":"室内地板被泡泡水弄滑了。移到户外，或铺防滑垫、勤擦地。"},{"if":"孩子拍不到、开始生气","then":"把泡泡吹低一点、吹到他手边。先让他拍破几个，建立信心。"}],"mistakes":["在光滑的室内地板玩——泡泡水会让地板变得非常滑，这是最常见的意外来源。","泡泡吹太快太多——孩子的眼睛跟不上，反而追不到。慢慢吹、一次几个就好。","只让孩子追，没让他吹——吹泡泡练的是呼吸控制，对说话的气很有帮助，别省略。"],"down":"吹大一点、慢一点的泡泡；吹到孩子手边让他容易拍到；坐着拍也可以。","up":"指定用哪只手拍；指定用脚踩；规定「只能拍红色的」（用彩色泡泡）；或比赛谁拍破得多。","progress":["眼睛能不能一直跟着泡泡不放掉。","拍破的成功率有没有提高。","会不会预测泡泡的去向、提前把手伸到那里。"],"outro":"一瓶泡泡水，可以让孩子跑跳十几分钟，眼睛还练到了追视。玩完记得让孩子自己吹几口——吹气对说话的气很有帮助。"}' AS JSON))
WHERE `id` = 'A016';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '手机放一首有节奏的歌'),
  `trains` = COALESCE(`trains`, '跟着节奏活动全身，让运动变成享受。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"放一首孩子喜欢的歌。"},{"imageUrl":null,"instruction":"跟着节拍跳、摆、转圈。"},{"imageUrl":null,"instruction":"音乐停就定住不动。"},{"imageUrl":null,"instruction":"全家一起跳最好玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着晃动就好'),
  `harder` = COALESCE(`harder`, '跟上节拍，或跟着大人做动作。'),
  `tip` = COALESCE(`tip`, '运动不必正经八百——跳得开心比跳得标准重要。心情不好的时候放首歌一起动，情绪也会好起来。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"放一首有节奏的歌，全家一起动起来。跟着音乐动，是让孩子爱上运动最简单的方法。","principles":["跟着节奏动，需要听觉和动作同时配合，这叫听动协调。","听动协调好的孩子，学舞蹈、打球、跳绳都比较快上手。","音乐的节拍提供了外在的节奏，能帮助动作变得更有组织、更流畅。","有些动作不熟的孩子，配上音乐反而做得比较顺，因为节奏帮他组织了动作。","跟着音乐动通常会持续好几分钟，运动量比单一动作练习大得多。","音乐会带动情绪，孩子在愉快的状态下运动，接受度完全不一样。","模仿大人的舞步，练的是观察和动作模仿能力。","快歌慢歌交替，孩子还要练习调整自己的速度，这是动作调节。"],"prep":{"场地":"客厅清出空间，移开桌角和易碎物。","器材":"手机放一首有节奏的歌；可以准备丝巾、沙铃增加变化。","安全检查":"地面防滑、周围清空。音量别太大，对听觉敏感的孩子从小声开始。","大人位置":"大人一起跳，而且要跳得比孩子夸张——大人放得开，孩子才放得开。"},"shots":[{"name":"放音乐","say":"今天我们跟着音乐动！"},{"name":"大人先动","say":"跟着我做——拍手、踏步！"},{"name":"孩子加入","say":"你也来！"},{"name":"快慢切换","say":"音乐变快了，我们也快一点！"},{"name":"音乐停就定住","say":"停！"},{"name":"换他带","say":"换你想动作，我们跟着你。"}],"reactions":[{"if":"孩子不好意思、站着不动","then":"大人先跳得夸张一点、搞笑一点。也可以先从坐着拍手开始，慢慢站起来。"},{"if":"孩子跟不上节奏","then":"选慢一点的歌，或把动作简化成只有拍手和踏步。节奏感是慢慢建立的。"},{"if":"孩子太兴奋、停不下来","then":"加入「音乐停就定住」的规则，或最后放一首慢歌当缓和。"}],"mistakes":["大人在旁边看着不动——孩子会觉得这是在被要求表演，而不是一起玩。","选太快的歌——一岁到三岁的孩子跟不上，选中等速度的最好。","玩完直接结束——最后放一首慢歌让身体缓下来，孩子比较不会太亢奋。"],"down":"坐着拍手、摇摆就好；选慢歌；动作简化成两三个。","up":"加入固定的舞步顺序要记住；音乐停就定住；换他当领队想动作；或加上丝巾、沙铃等道具。","progress":["能不能跟上音乐的节拍。","能持续动多久不喊累。","会不会自己创造动作。"],"outro":"跟着音乐动，是把运动变成享受最快的方法。每天放一首歌，全家一起动三分钟，比什么都有效。"}' AS JSON))
WHERE `id` = 'A017';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '家里的楼梯或一个矮台阶'),
  `trains` = COALESCE(`trains`, '练腿的力气和上下楼梯的能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在一个矮台阶上，上、下、上、下反复走。"},{"imageUrl":null,"instruction":"两只脚轮流当先上的脚。"},{"imageUrl":null,"instruction":"做二十次休息一下。"},{"imageUrl":null,"instruction":"真的楼梯要扶着扶手慢慢走。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '扶着走十次'),
  `harder` = COALESCE(`harder`, '不扶手，或加快节奏。'),
  `tip` = COALESCE(`tip`, '上楼时大人走在孩子后面、下楼时走在前面——万一失去平衡才接得住。楼梯口平时要装护栏。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组八（上下楼梯与高低差）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"家里的楼梯就是现成的健身器材。上下楼梯练的是腿的力气，还有一个很重要的能力——两只脚轮流出力。","principles":["上楼梯时，一只脚要把整个身体的重量往上推，这是很强的单脚肌力训练。","下楼梯更难——需要那只脚慢慢弯曲控制身体下降，这叫离心收缩。","离心控制不好的孩子，下楼梯会用跳的、会一阶一阶双脚踩，或者一定要扶。","「两脚交替」上下楼梯（一阶一只脚）是重要的发展指标。","发展参考：两岁多能扶着交替上楼，三岁多能不扶交替上楼，四岁左右能交替下楼。","上下楼梯时单脚支撑的时间比走路长，平衡的要求更高。","这个动作每天都在做，把它当成训练，等于每天免费练腿。","楼梯的高度固定，是很稳定的训练条件，进步与否很容易观察。"],"prep":{"场地":"家里的楼梯，或社区、公园的矮台阶。光线要足够。","器材":"家里的楼梯或一个矮台阶；矮凳也可以代替。","安全检查":"这是全篇最需要注意安全的活动。大人必须在孩子下方（上楼时在后面、下楼时在前面）。楼梯要有扶手、防滑条。绝不让孩子单独练习。","大人位置":"上楼时大人在孩子后下方，下楼时在孩子前下方——永远在会跌倒的那一侧。"},"shots":[{"name":"安全提示","say":"练楼梯的时候，大人一定要在下面。"},{"name":"扶着上楼","say":"手扶好，一阶一阶上。"},{"name":"两脚交替","say":"这只脚、换那只脚。"},{"name":"下楼控制","say":"下楼要慢慢来，膝盖弯一弯。"},{"name":"数阶梯","say":"一阶、两阶、三阶⋯⋯"},{"name":"变化玩法","say":"这次我们送东西上去。"}],"reactions":[{"if":"孩子双脚都踩同一阶才上下一阶","then":"这是正常的过渡阶段。牵着一只手，引导他「换一只脚」，慢慢就会交替了。"},{"if":"孩子下楼很怕、一定要坐着滑下来","then":"先从最后两阶开始练，扶着扶手下。成功的经验累积够了，恐惧就会减少。"},{"if":"孩子上楼很喘","then":"代表心肺耐力还在建立。减少阶数，中间休息，别一次爬太多层。"}],"mistakes":["大人站在孩子上方——孩子往下跌的时候完全接不住。上楼在后、下楼在前，永远在下方。","让孩子自己练习——楼梯的意外风险最高，绝对要全程陪同。","一次爬太多层——三到五阶做几趟，比一口气爬三层楼好。"],"down":"只练两三阶；全程牵手或扶扶手；或改用矮凳练上下一阶。","up":"不扶扶手；两脚交替；手上拿东西上楼；或练侧着上下。","progress":["上楼是双脚同阶还是两脚交替。","下楼需不需要扶、是不是两脚交替。","能连续上下几趟不喊累。"],"outro":"楼梯是现成的训练器材，每天上下就在练腿力和平衡。但要记住——大人永远站在孩子的下方。"}' AS JSON))
WHERE `id` = 'A018';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '装了东西的纸箱或购物袋'),
  `trains` = COALESCE(`trains`, '搬、推、拉重一点的东西，练全身力气。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在纸箱里放几本书，重量以他能推动但要用力为准。"},{"imageUrl":null,"instruction":"让他把箱子推到指定的地方。"},{"imageUrl":null,"instruction":"也可以用绳子绑着拖，或用手提。"},{"imageUrl":null,"instruction":"完成了郑重道谢。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '很轻的箱子、短距离'),
  `harder` = COALESCE(`harder`, '重一点，或距离拉长。'),
  `tip` = COALESCE(`tip`, '这类「出力气」的活动除了长力量，还能让孩子的情绪安定下来。重量宁可轻一点，姿势不歪比搬得重重要。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"请孩子帮忙搬东西，他会觉得自己很重要。而搬、推、拉重一点的东西，正是最好的全身力量训练。","principles":["搬重物时全身肌肉一起用力，从手臂、核心到腿都在工作。","负重活动提供的本体觉输入特别强，有明显的安定情绪效果。","很多治疗师会建议在孩子情绪浮躁时，请他去搬东西或推东西。","搬东西时要抱住物品，手臂和胸前的肌肉持续用力，是等长收缩训练。","要判断「这个我搬得动吗」，用到的是对自己力气的认识。","重心会因为抱着东西而改变，身体必须重新调整平衡才走得稳。","「帮忙」这件事本身对孩子的自我价值感很有帮助——他是有用的人。","这是最容易融入日常生活的训练，买菜、收衣服、整理房间都是机会。"],"prep":{"场地":"从起点搬到终点，路线上清空障碍物。","器材":"装了东西的纸箱或购物袋；也可以用装了水瓶的袋子、一叠书、洗好的衣服。","安全检查":"重量是关键——大约孩子体重的十分之一以内最安全。搬的时候要看得到前面的路，箱子别挡住视线。教他蹲下来搬，不要弯腰。","大人位置":"大人一起搬，或在旁边陪着走。"},"shots":[{"name":"请他帮忙","say":"可以帮妈妈搬这个吗？"},{"name":"蹲下来搬","say":"蹲下来，用腿的力气抬起来。"},{"name":"抱好走","say":"抱好，慢慢走。"},{"name":"放下","say":"慢慢放下来。"},{"name":"推和拉","say":"这个太重，我们用推的。"},{"name":"道谢","say":"谢谢你，帮了大忙！"}],"reactions":[{"if":"孩子搬不动还硬撑","then":"立刻减轻重量。教他说「这个太重了，我搬不动」——知道自己的极限也是能力。"},{"if":"孩子弯腰去搬","then":"示范「蹲下来，用腿站起来」。这个姿势习惯要从小建立，保护腰。"},{"if":"孩子搬两趟就不想做了","then":"把它变成游戏或比赛，或给一个明确的目标（「把这五个搬完就好」）。"}],"mistakes":["东西太重——超过孩子体重十分之一就太多了，会造成负担也容易受伤。","让孩子弯腰搬——一定要教蹲下来用腿的力气。","箱子挡住视线还让他走——看不到路很容易绊倒。"],"down":"减轻重量；缩短距离；改成用推的或拉的（比抱着轻松）。","up":"增加重量或距离；搬的时候要绕过障碍；或搬上楼梯（要更小心）。","progress":["能搬多重、走多远。","搬的时候是蹲下来还是弯腰。","会不会判断「这个我搬不动」并说出来。"],"outro":"请孩子当小帮手，他练到了全身的力气，也得到了「我很有用」的感觉。记得——蹲下来搬，不要弯腰。"}' AS JSON))
WHERE `id` = 'A019';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '全龄'),
  `people` = COALESCE(`people`, '全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '把身体活动变成每天的习惯。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"每天找机会让孩子动：走路上下学、公园跑跳、家务帮忙。"},{"imageUrl":null,"instruction":"减少久坐——每坐半小时起来动一动。"},{"imageUrl":null,"instruction":"把活动排进每天的行程。"},{"imageUrl":null,"instruction":"全家一起动最容易持续。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每天累积一小时活动'),
  `harder` = COALESCE(`harder`, '每天两三小时，含跑跳等较费力的活动。'),
  `tip` = COALESCE(`tip`, '学龄前孩子建议每天至少 180 分钟的身体活动——但这不必来自训练课，走路、玩耍、家务全部都算数。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十五（体能耐力与户外生活应用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"前面十九个活动，最后一件事最重要——把身体活动变成每天的习惯。这一集不教新动作，教的是怎么让它持续下去。","principles":["运动的效果来自累积，不是来自某一次做得多认真。","每天十分钟，比周末做两小时有效得多。","规律的身体活动会改善孩子的睡眠品质，而睡得好，白天的情绪和专注就稳。","固定时间的活动还提供了生活的可预期性，对需要结构的孩子特别重要。","把活动绑在既有的生活流程上（起床后、洗澡前、睡前），最容易维持。","全家一起做，孩子不会觉得是「只有我要运动」，配合度完全不同。","让孩子参与决定今天做什么，他的自主感会大幅提高执行率。","看得见的记录（贴纸表、打勾表）会让孩子自己想继续。","重点不是做得标准，而是每天都有动——先建立习惯，品质慢慢来。"],"prep":{"场地":"家里固定的一小块空间，最好是每天都在同一个地方。","器材":"不需要任何东西；可以准备一张活动表和贴纸。","安全检查":"累了就休息，不勉强。孩子生病、精神不好的时候跳过没关系，隔天再继续。","大人位置":"大人一起做，而且要让孩子看到你也在坚持。"},"shots":[{"name":"做一张表","say":"我们来做一张「每天动一动」的表。"},{"name":"让他选","say":"今天你想做哪一个？"},{"name":"固定时间","say":"我们每天洗澡前动一动。"},{"name":"全家一起","say":"爸爸妈妈也要一起做。"},{"name":"打勾","say":"做完了，来打个勾！"},{"name":"一周回顾","say":"你看，这个星期动了五天！"}],"reactions":[{"if":"孩子某天完全不想动","then":"不勉强，跳过就跳过。硬逼一次，可能毁掉整个习惯。隔天再邀请他。"},{"if":"孩子做几天就腻了","then":"换活动、换玩法，或让他自己发明一个动作。新鲜感是持续的关键。"},{"if":"家长自己坚持不下来","then":"把标准降到最低——每天三分钟也算。先让它变成习惯，再谈时间长短。"}],"mistakes":["一开始就订太高的目标——每天三十分钟通常撑不过一周。从五分钟开始。","只要求孩子做、大人不参与——这会让运动变成一种被要求的事。","漏做一天就放弃整个计划——漏了就漏了，隔天继续就好。"],"down":"每天三分钟；一周三天就好；只做一个最简单的活动。","up":"每天十五分钟；固定的活动顺序；加入户外活动；或让孩子自己安排一周的菜单。","progress":["一周能做几天，记录下来。","孩子会不会主动提醒「今天还没动」。","睡眠和情绪有没有变化。"],"outro":"运动的效果来自累积。每天十分钟、全家一起、让孩子自己选，这三件事做到了，习惯就建立起来了。做不做得标准，是后面的事。"}' AS JSON))
WHERE `id` = 'A020';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几个枕头或抱枕'),
  `trains` = COALESCE(`trains`, '在不稳的表面上走路，练脚踝和身体的自动调整。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把枕头排成一条路。"},{"imageUrl":null,"instruction":"让孩子踩着枕头走过去。"},{"imageUrl":null,"instruction":"需要的话牵着一只手。"},{"imageUrl":null,"instruction":"走过去再走回来。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '矮而硬的垫子、牵着手走'),
  `harder` = COALESCE(`harder`, '软一点的枕头、自己走过去。'),
  `tip` = COALESCE(`tip`, '不稳的地面会逼出脚踝和肚子的自动调整——这种练习比在平地上走有效得多。旁边地面也要铺软一点。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把几个枕头排成一条路，让孩子踩着走过去。地面一不稳，脚踝和肚子就得自动出来工作——这种练习比在平地上走有效得多。","principles":["走在平地上，身体几乎不需要调整；走在不稳的表面上，每一步都要重新找平衡。","这些调整主要来自脚踝的细微动作，专业上叫踝策略，是平衡的第一道防线。","脚踝反应快的孩子，走在不平的路面、踩到小石头时比较不会扭到。","枕头会凹陷，脚掌接收到的压力讯息一直在变，这是很丰富的本体觉输入。","本体觉输入让大脑不断更新「我的脚现在在哪里、踩到什么」的资讯。","为了不摔下去，核心肌群必须全程收紧，这是很自然的核心训练。","手会自然张开帮忙平衡，这是身体自己找到的策略，不用特别教。","走在软的东西上比走平衡木安全得多，掉下来也不会受伤，适合刚开始练平衡的孩子。"],"prep":{"场地":"客厅清出三到四米，枕头排成一条直线，间距刚好一步。","器材":"几个枕头或抱枕；沙发垫、折起来的棉被也可以。","安全检查":"枕头两侧的地面也要铺软的（瑜伽垫、地毯），掉下来才不会痛。枕头别叠太高，一层就好。地板太滑要先铺防滑垫。","大人位置":"大人走在孩子侧边，手放在他腰侧附近准备着，但尽量不要真的扶住。"},"shots":[{"name":"铺路","say":"我们来铺一条软软的路。"},{"name":"大人先走","say":"妈妈先走给你看，慢慢踩。"},{"name":"孩子踏上去","say":"一只脚先踩上去，站稳了再换下一只。"},{"name":"中途摇晃","say":"晃了没关系，站稳再走。"},{"name":"走完全程","say":"走到了！"},{"name":"加难度","say":"这次我们把枕头排得远一点。"}],"reactions":[{"if":"孩子不敢踩上去","then":"先让他坐在枕头上、站在枕头上不动，熟悉这个不稳的感觉。再牵着两只手走。"},{"if":"孩子走两步就跳下来","then":"把枕头间距缩到半步，先让他走完三个。成功的经验比走得长重要。"},{"if":"孩子一直要扶着人","then":"改成牵一只手、再改成扶手指、最后改成手在旁边不碰到。一次减一点。"}],"mistakes":["枕头叠太高——一层就够，叠高了掉下来会受伤。","旁边地面没铺软的——掉下来撞到硬地板，孩子下次就不敢了。","孩子一晃就马上扶住——他自己找回平衡的那一秒，才是真正的训练。"],"down":"枕头间距缩到半步；牵着两只手；或改成在一块大垫子上走就好。","up":"间距加大；排成曲线或转弯；枕头堆两层增加不稳定；或边走边端着东西。","progress":["能连续走过几个枕头不掉下来。","晃动时能不能自己稳住，还是一定要扶。","需不需要牵手。"],"outro":"家里的枕头就是最安全的平衡训练器材。每天走个两三趟，孩子的脚踝反应和核心稳定都在进步。"}' AS JSON))
WHERE `id` = 'A021';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几张防滑垫片或旧地垫'),
  `trains` = COALESCE(`trains`, '练精准的落脚控制和单脚站稳。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在地上放几个垫片当「石头」。"},{"imageUrl":null,"instruction":"让孩子只踩石头走过去，不能掉进河里。"},{"imageUrl":null,"instruction":"石头的间隔慢慢加大。"},{"imageUrl":null,"instruction":"必要时牵着手。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '石头放密一点'),
  `harder` = COALESCE(`harder`, '间隔拉开，要跨一步才踩得到。'),
  `tip` = COALESCE(`tip`, '垫片一定要防滑——会滑动的垫子很危险。用旧的浴室防滑垫或瑜伽垫剪成小块最安全。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"地上摆几块防滑垫当石头，中间就是河。只能踩石头不能掉进河里——孩子练的是精准落脚和单脚站稳。","principles":["要踩在指定的位置上，孩子必须先用眼睛判断距离，再控制脚落在那里。","这是视觉和动作的整合，也就是手眼协调的脚部版本。","踩到下一块石头之前，全身重量都在前一只脚上，这就是移动中的单脚站。","单脚支撑的稳定度，直接决定走路稳不稳、上下楼梯需不需要扶。","石头之间的距离要靠自己判断——这一步跨得到吗？这是距离判断与身体形象的结合。","判断不准的孩子，常常会踩空、绊倒，或者跨太大步失去平衡。","石头间距一加大，孩子就必须跨大步，单脚支撑的时间跟着变长，难度自然提升。","这个游戏有明确的输赢（掉进河里了），孩子会自己想再挑战一次。"],"prep":{"场地":"客厅或走廊，清出三到五米的通道，两侧不要有硬物。","器材":"几张防滑垫片或旧地垫；浴室防滑垫、瑜伽垫剪成小块都可以。","安全检查":"垫片一定要防滑——会滑动的垫子非常危险，这是本活动最重要的安全点。别用杂志、纸板或塑胶垫。","大人位置":"大人走在孩子侧边，手在他腰侧附近准备着。"},"shots":[{"name":"摆石头","say":"这些是石头，中间是河，不能掉下去喔。"},{"name":"示范判断","say":"看清楚下一块在哪里。"},{"name":"孩子落脚","say":"慢慢踩，踩准一点。"},{"name":"单脚支撑","say":"站稳了，另一只脚再过去。"},{"name":"加大间距","say":"这次石头离得比较远，要跨大步。"},{"name":"完成庆祝","say":"过河了，一次都没掉下去！"}],"reactions":[{"if":"孩子直接跳过去而不是走过去","then":"把间距缩小，让他跳不起来只能走。或规定「要站稳三秒才能踩下一块」。"},{"if":"孩子一直踩到边缘","then":"换大一点的垫片，或提醒他「先看再踩」。落脚精准度是慢慢练出来的。"},{"if":"孩子踩到一半不敢跨","then":"缩短那一段的距离，或牵着一只手让他跨过去。成功一次之后信心就来了。"}],"mistakes":["用会滑动的垫子——这是最危险的错误，垫片一定要防滑或用双面胶固定。","间距一开始就拉太大——先让他走得过去，再慢慢加。","孩子踩空就说「你怎么又掉下去了」——掉下去是游戏的一部分，笑着再来一次就好。"],"down":"垫片放大、间距缩小到半步；牵着一只手；或先在一块垫片上练站稳。","up":"间距加大；垫片换小；排成弯曲路线；或规定要倒退走回来。","progress":["能连续踩过几块不掉下去。","落脚是不是踩在中央而不是边缘。","能跨过多大的间距。"],"outro":"几块防滑垫就能做出一条河。孩子在「不能掉下去」的游戏里，练的是精准落脚和单脚站稳——走路稳不稳，靠的就是这两样。"}' AS JSON))
WHERE `id` = 'A022';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '地板上的一条线'),
  `trains` = COALESCE(`trains`, '练最窄的支撑面平衡，像走钢丝一样。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"沿着地上的线站好。"},{"imageUrl":null,"instruction":"每走一步，脚跟要碰到前一只脚的脚尖。"},{"imageUrl":null,"instruction":"手张开保持平衡。"},{"imageUrl":null,"instruction":"走十步。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '脚不必完全相接'),
  `harder` = COALESCE(`harder`, '完全脚跟接脚尖，或倒着走。'),
  `tip` = COALESCE(`tip`, '这个动作把左右的支撑宽度缩到最小，能走稳的孩子平衡非常好。走不稳很正常，多练几次就有进步。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"每走一步，后脚的脚跟要碰到前脚的脚尖，像走钢丝一样。这是把支撑面缩到最小的平衡挑战，也是很标准的平衡测验动作。","principles":["一般走路时两脚是左右分开的，支撑面有一个肩膀的宽度。","脚跟接脚尖走的时候，两脚排成一直线，左右的支撑宽度几乎变成零。","支撑面一窄，身体左右晃动的容错空间就没了，必须靠踝关节持续微调。","这个动作在临床上常被用来评估平衡功能，是很标准的测验项目。","走的时候眼睛要看前方而不是看脚，这练的是用视觉稳定身体。","一直低头看脚的孩子，通常是对自己的平衡没信心，也会让姿势更不稳。","双手自然张开可以增加转动惯量，让身体比较不容易晃，这是身体自己找到的策略。","发展参考：四岁的孩子大约能走四到六步，六岁以上可以走十步以上。"],"prep":{"场地":"地板上找一条现成的线：磁砖缝、地板接缝，或贴一条胶带。长度两到三米。","器材":"地板上的一条线（磁砖缝、胶带或绳子）。","安全检查":"两侧留出空间，晃倒时不会撞到东西。光脚或穿防滑袜，别穿一般袜子在光滑地板上走。","大人位置":"大人走在孩子侧边或站在终点，手在旁边准备着但不主动扶。"},"shots":[{"name":"找一条线","say":"我们来走这条线，像走钢丝一样。"},{"name":"示范脚型","say":"脚跟要碰到前面那只脚的脚尖。"},{"name":"眼睛看前方","say":"眼睛看前面，不要看脚。"},{"name":"一步一步走","say":"慢慢来，一步一步。"},{"name":"手张开平衡","say":"手打开可以帮忙。"},{"name":"数步数","say":"一、二、三⋯⋯走了几步？"}],"reactions":[{"if":"孩子两脚还是分开走","then":"先在地上贴两条很近的平行线（约五厘米宽），让他走在里面。习惯了再缩成一条线。"},{"if":"孩子走两步就偏出去","then":"距离缩到一米就好，先让他走完。也可以让他一只手扶着墙走。"},{"if":"孩子一直低头看脚","then":"在终点放一个玩具或让大人站着，跟他说「看着那里走过来」。给眼睛一个目标。"}],"mistakes":["一开始就要求走十步——四岁能走四步就很好了，用大人的标准会让孩子挫折。","一直提醒「看脚、踩好」——这句话会让他更低头。要引导他看前方。","一晃就伸手扶——他自己找回平衡才是训练。"],"down":"贴两条平行线走在中间；距离缩到一米；一只手扶墙走。","up":"走十步以上；倒着走（脚尖碰脚跟）；闭上一只眼睛走；或头上顶一本书走。","progress":["能连续走几步而不偏出线外。","走的时候是看前方还是一直低头。","能不能做到倒着走。"],"outro":"脚跟接脚尖是很标准的平衡测验。走不稳很正常，每天走个两趟，一个月后再数一次步数，进步会很明显。"}' AS JSON))
WHERE `id` = 'A023';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '转晕之后还能站稳，练身体的恢复能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子原地转三圈。"},{"imageUrl":null,"instruction":"停下来后马上站好不动。"},{"imageUrl":null,"instruction":"撑住三秒。"},{"imageUrl":null,"instruction":"两个方向都转转看。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '转一圈、慢慢转'),
  `harder` = COALESCE(`harder`, '转五圈后立刻单脚站。'),
  `tip` = COALESCE(`tip`, '转圈会让人头晕——这正是内耳的平衡系统在工作。周围要清空，大人在旁边保护。圈数不用多，孩子不舒服就停。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"原地转三圈，停下来马上站好不动。转晕之后还能站稳，练的是身体从混乱中恢复过来的能力。","principles":["转圈时内耳里的半规管会被大量刺激，这是前庭系统最直接的输入方式。","转完停下来会晕，是因为内耳里的液体还在流动，大脑收到「我还在转」的错误讯息。","这时候身体必须靠视觉和本体觉来修正，重新判断「我其实是站着不动的」。","这个修正过程，就是前庭系统整合能力的训练。","整合得好的孩子，坐车不容易晕、玩旋转设施不会不舒服、跌倒后也能很快站稳。","有些孩子转很久都不晕，反而一直想转——这可能是前庭系统反应不足，需要更多输入。","有些孩子转一圈就难受，代表前庭比较敏感，圈数要更少、更慢。","两个方向都要转，因为左右的前庭系统是分开的，要平均刺激。"],"prep":{"场地":"周围两米内清空，没有桌角、玻璃或硬物。地面防滑，最好铺垫子。","器材":"不需要任何东西。","安全检查":"这是本模组最需要留意的活动。周围务必清空，大人在旁边随时准备扶。孩子说不舒服、脸色不对就立刻停。有癫痫病史或前庭疾病的孩子，先问过医师或治疗师。","大人位置":"大人站在孩子侧边一步的距离，手张开准备随时接住。"},"shots":[{"name":"安全提示","say":"先看看旁边有没有东西会撞到。"},{"name":"原地转圈","say":"我们来转三圈——一、二、三。"},{"name":"停下站好","say":"停！站好不要动。"},{"name":"撑住三秒","say":"撑住——一、二、三。"},{"name":"换方向","say":"换另外一边转。"},{"name":"休息","say":"好了，坐下来休息一下。"}],"reactions":[{"if":"孩子转完直接跌坐在地上","then":"圈数减到一圈，或改成慢慢转。也可以让他转完扶着椅子站。"},{"if":"孩子说头晕想吐","then":"立刻停止，让他坐下来看着远方的固定物，休息几分钟。下次只转一圈。"},{"if":"孩子转个不停、越转越兴奋","then":"这类孩子前庭反应可能不足。可以给，但要限制次数和时间，转完接一个安静的活动收尾。"}],"mistakes":["让孩子转很多圈——三圈就够了，多不代表好，反而可能引发不适。","周围没清空——转完站不稳时很容易撞到东西，这是最常见的意外。","只转一个方向——两边都要转，次数尽量一样。"],"down":"只转一圈；转慢一点；转完可以扶着椅子站。","up":"转五圈；转完要单脚站；转完马上走直线；或转完要接住丢过来的球。","progress":["转完能不能站住三秒。","晕的感觉多久会消退。","两个方向的表现有没有明显差异。"],"outro":"转圈会晕是正常的，晕完还能站稳才是本事。记住三件事：周围清空、三圈就好、不舒服马上停。"}' AS JSON))
WHERE `id` = 'A024';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '被轻轻推还能站稳，练跌倒前的自我保护反应。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子站好，大人从不同方向轻轻推。"},{"imageUrl":null,"instruction":"他要用踏一步或身体调整来稳住。"},{"imageUrl":null,"instruction":"力气从很小开始。"},{"imageUrl":null,"instruction":"被推倒了就笑一笑扶起来再来。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '双脚站、力气极轻'),
  `harder` = COALESCE(`harder`, '单脚站，或力气稍大一点。'),
  `tip` = COALESCE(`tip`, '「快跌倒时手会自己撑出去、脚会自己踏一步」——这种保护反应是要靠练才会出来的。力气要小，笑声要大。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子站好，大人从不同方向轻轻推一下。他要靠踏一步或身体调整稳住自己——这练的是快跌倒时的自我保护反应。","principles":["人被推的时候，身体会自动做出反应来避免跌倒，这叫平衡反应。","平衡反应有两种：小幅度时靠脚踝和髋部调整，大幅度时靠踏一步出去。","「踏一步」的反应特别重要，很多跌倒受伤就是因为脚没有及时踏出去。","还有一种叫保护性伸手——快撞到地面时手会自己撑出去，保护头和身体。","这些反应不是天生就成熟的，要靠实际经验一次一次练出来。","平时都走平路、很少失衡的孩子，这些反应会比较慢。","从不同方向推，练到的是不同方向的反应——前后左右都要有。","推的力气要很小，重点是引发反应，不是真的把孩子推倒。"],"prep":{"场地":"地面铺垫子或地毯，周围一米内清空。","器材":"不需要任何东西。","安全检查":"力气务必从非常小开始——这个活动的重点是引发反应，不是比力气。绝不从背后突然大力推。地面一定要铺软。","大人位置":"大人站在孩子侧前方，用手掌轻推他的肩膀或骨盆，每次只推一个方向。"},"shots":[{"name":"说明玩法","say":"你要当不倒翁，我轻轻推你，你要站稳。"},{"name":"往前推","say":"往前——站稳！"},{"name":"往侧边推","say":"这次往旁边。"},{"name":"保护反应","say":"手会自己伸出来对不对？"},{"name":"换孩子推","say":"换你推妈妈！"},{"name":"笑着结束","say":"不倒翁赢了！"}],"reactions":[{"if":"孩子被轻轻一推就跌坐","then":"力气再减半，改成只是手放在他肩膀上轻轻施压。先让他能稳住一次。"},{"if":"孩子跌倒时手不会撑出去","then":"这个保护反应值得多练。可以让他跪着，从前方轻推，练手撑地的反应。"},{"if":"孩子觉得被推很不舒服、生气","then":"改成游戏形式：他当大树、大人当风。也可以先让他推大人，建立掌控感。"}],"mistakes":["推太用力——这是最常见也最危险的错误。力气小到几乎只是碰一下就好。","从背后突然推——孩子完全没有心理准备，容易受伤也会害怕。永远让他看得到你。","在硬地板上做——一定要铺垫子或在地毯上。"],"down":"力气减到最小；让孩子扶着椅背站；或从跪姿开始练。","up":"力气稍微加大；从不同方向随机推；闭着眼睛被推；或站在软垫上被推。","progress":["被推时会不会踏一步出去稳住。","快跌倒时手会不会自己撑出去。","哪个方向的反应比较弱。"],"outro":"「快跌倒时脚会自己踏一步、手会自己撑出去」——这些保护反应要靠练才会出来。力气要小，笑声要大。"}' AS JSON))
WHERE `id` = 'A025';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个盘子或托盘＋一个轻的东西'),
  `trains` = COALESCE(`trains`, '端着东西不掉，练稳定的行走。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一个盘子，上面放一个轻的东西。"},{"imageUrl":null,"instruction":"让他端着走一段路不掉下来。"},{"imageUrl":null,"instruction":"可以放个小球增加难度。"},{"imageUrl":null,"instruction":"走直线或绕过障碍。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '放稳固的东西（积木）'),
  `harder` = COALESCE(`harder`, '放会滚的球，或走远一点。'),
  `tip` = COALESCE(`tip`, '手被占住的时候，平衡全靠身体和腿——这是很实用的生活练习。让孩子帮忙端东西上桌，一举两得。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"端着一个盘子走路，上面的东西不能掉。手被占住的时候，平衡就得全靠身体和腿——这是最实用的生活练习。","principles":["平常走路时，双手可以自由摆动帮助平衡。","端东西时双手被占住，身体失去了一个重要的平衡工具，难度立刻提高。","这时候平衡必须靠躯干和下肢来完成，核心的负担明显加重。","为了不让东西掉，走路会自然变慢、变稳，这是很好的速度控制练习。","眼睛要同时注意盘子和前方的路，这是注意力分配的练习。","注意力分配不好的孩子，看着盘子就会撞到东西，看着路就会把东西打翻。","手臂要维持在固定的高度和角度，是持续的等长收缩，也在练手臂的稳定度。","这个能力直接连到生活——端汤、端饭、帮忙上菜，都是同一件事。"],"prep":{"场地":"客厅到餐桌的路线，或走廊三到五米，地面清空防滑。","器材":"一个盘子或托盘＋一个轻的东西（积木、小玩偶、球）。刚开始别用会破的东西。","安全检查":"不要用玻璃或陶瓷盘。不要端热的东西。路线上清空，孩子的视线会被盘子挡住一部分。","大人位置":"大人走在孩子侧边，注意他有没有看路。"},"shots":[{"name":"准备","say":"我们来端东西，不能掉下来喔。"},{"name":"手的高度","say":"盘子端在肚子前面，不要太高。"},{"name":"慢慢走","say":"慢慢走，看着前面的路。"},{"name":"转弯","say":"转弯的时候更要慢。"},{"name":"放下","say":"轻轻放到桌上。"},{"name":"加难度","say":"这次放一颗球，球会滚喔！"}],"reactions":[{"if":"孩子一直盯着盘子看，撞到东西","then":"提醒「用眼角看盘子，眼睛看前面」。或先走一条完全没有障碍的直线。"},{"if":"东西一直掉","then":"换更稳的东西（积木比球稳），或用有边框的托盘。也可以缩短距离。"},{"if":"孩子端得很高、手很紧绷","then":"提醒「手肘靠近身体，盘子放在肚子前面」。端太高手臂会很快累。"}],"mistakes":["用会破的盘子——刚开始一定要用塑胶或木质的。","一开始就放会滚的球——先用积木这类不会动的，成功了再进阶。","路线上有障碍——孩子视线被挡住一部分，要走净空的路线。"],"down":"用有边框的托盘；放不会滚的东西；距离缩短到两三步。","up":"放会滚的球；走曲线或绕障碍；端两个盘子；或端着东西上下一阶台阶（要更小心）。","progress":["能端着走多远而不掉。","走的时候是看路还是一直看盘子。","能不能端着转弯。"],"outro":"端东西走路，练的是手被占住时的平衡。让孩子帮忙端菜上桌，练到了平衡，也让他觉得自己有用——一举两得。"}' AS JSON))
WHERE `id` = 'A026';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '手脚交叉过身体中线，练左右脑的配合。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"站好，抬起右膝，用左手去碰。"},{"imageUrl":null,"instruction":"换左膝、右手。"},{"imageUrl":null,"instruction":"交替做十几次。"},{"imageUrl":null,"instruction":"熟练后可以加快。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '慢慢做、可以扶着'),
  `harder` = COALESCE(`harder`, '加快速度，或闭上眼睛做。'),
  `tip` = COALESCE(`tip`, '「跨过身体中线」的动作对大脑两侧的配合特别有帮助——看起来简单，价值很高。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"抬起右膝，用左手去碰；再换左膝、右手。手脚交叉过身体的中线——这个看起来简单的动作，对大脑两侧的配合特别有帮助。","principles":["身体有一条看不见的中线，从头顶到脚底把身体分成左右两半。","左手去碰右脚，手就必须跨过这条中线，这叫跨中线动作。","跨中线时，大脑左右两个半球必须互相沟通才能完成动作。","这种沟通靠的是连接两个半球的胼胝体，动作练得多，沟通就越顺畅。","不敢跨中线的孩子，常常会出现「右边的东西一定用右手拿」的现象。","这会影响日后写字——写到纸的另一边时，手不敢跨过去，身体就会歪掉。","跨中线也是双手协调的基础，像是一手扶纸一手写字、一手扶碗一手舀。","抬起一只膝盖的同时还要维持平衡，所以这个动作也顺便练了单脚站。"],"prep":{"场地":"客厅空地，旁边有墙或椅子可以扶。","器材":"不需要任何东西；可以在膝盖上贴贴纸当目标增加趣味。","安全检查":"地面防滑。平衡不好的孩子可以先扶着椅背做。","大人位置":"大人面对孩子一起做，注意镜像的问题（你的左手对他来说在右边）。"},"shots":[{"name":"示范动作","say":"抬起右边的膝盖，用左手去碰它。"},{"name":"换边","say":"换边——左膝、右手。"},{"name":"连续交替","say":"一、二、一、二，交替做。"},{"name":"检查是不是对侧","say":"是左手碰右脚喔，不是右手碰右脚。"},{"name":"加快速度","say":"这次快一点！"},{"name":"变化版本","say":"这次用手碰后面的脚。"}],"reactions":[{"if":"孩子变成右手碰右膝（同侧）","then":"放慢速度，一次一边慢慢做。可以在孩子的左手和右膝贴同色贴纸，用颜色提示配对。"},{"if":"孩子抬膝时站不稳","then":"先扶着椅背做，或坐在椅子上做（坐着也能跨中线）。"},{"if":"孩子做几下就乱掉","then":"次数减少到每边三次，慢慢做。这个动作重质不重量。"}],"mistakes":["做成同侧（右手碰右膝）——这就练不到跨中线了，要特别留意。","一开始就求快——速度一快就会变成同侧，先慢慢做对再加速。","大人面对面示范造成镜像混淆——可以站在孩子旁边同向示范。"],"down":"坐在椅子上做；扶着椅背；只做单边，熟了再交替。","up":"加快速度；手碰后方的对侧脚跟；边走边做；或闭上眼睛做。","progress":["能不能稳定做到对侧而不做成同侧。","连续做十次会不会乱掉。","抬膝时站得稳不稳。"],"outro":"左手摸右脚看起来很简单，但它练的是大脑两侧的配合。这个能力和日后写字、双手操作都有关，每天做个十次就够。"}' AS JSON))
WHERE `id` = 'A027';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要（可配音乐）'),
  `trains` = COALESCE(`trains`, '手脚对侧摆动，练走路和跑步的基本模式。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"走路时把膝盖抬得很高。"},{"imageUrl":null,"instruction":"同时对侧的手往前摆（右腿抬、左手前）。"},{"imageUrl":null,"instruction":"像小兵行军一样喊「一二一」。"},{"imageUrl":null,"instruction":"走十几步。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '慢慢走、幅度小'),
  `harder` = COALESCE(`harder`, '快一点，并保持手脚对侧摆动。'),
  `tip` = COALESCE(`tip`, '走路本来就是「右脚出去、左手往前」——高抬腿把这个模式放大来练，孩子的走姿会更协调。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"走路时把膝盖抬得高高的，同时对侧的手往前摆，像小兵行军一样。这是把走路的基本模式放大来练。","principles":["正常走路时，右脚往前的同时左手往前摆，这叫对侧摆动。","对侧摆动可以抵销身体的旋转、让走路更省力、也更稳。","很多孩子走路时手不摆动，或是同手同脚，看起来就不协调。","高抬腿把这个模式夸张化，孩子比较容易感觉到手脚该怎么配合。","膝盖抬高需要髋屈肌用力，这是很多久坐孩子偏弱的肌肉。","抬起一只脚的瞬间是单脚支撑，所以也在练平衡。","手脚对侧配合同样是跨中线的一种形式，对左右脑的整合有帮助。","喊「一二一」的口令能帮孩子抓到节奏，动作会更有组织。"],"prep":{"场地":"客厅或走廊，三到五米的直线，地面清空防滑。","器材":"不需要任何东西；可以配一首有节奏的进行曲。","安全检查":"地面防滑，光脚或穿防滑袜。抬腿时容易失去平衡，旁边留出空间。","大人位置":"大人走在孩子旁边同方向示范，避免面对面造成镜像混淆。"},"shots":[{"name":"示范动作","say":"膝盖抬高高，像小兵走路。"},{"name":"手的配合","say":"右脚抬起来，左手往前摆。"},{"name":"喊口令","say":"一、二、一、二！"},{"name":"检查同手同脚","say":"看看是不是同手同脚了？"},{"name":"加速","say":"快一点，跑步行军！"},{"name":"全家一起","say":"我们排成一列行军！"}],"reactions":[{"if":"孩子变成同手同脚","then":"放慢速度，一步一步来。也可以先只做手的摆动（原地站着摆），再加上脚。"},{"if":"孩子膝盖抬不高","then":"在前方放一条绳子或大人的手当高度目标，让他抬到碰得到。"},{"if":"孩子抬腿时晃得厉害","then":"降低抬腿高度，或扶着墙走。平衡稳了再抬高。"}],"mistakes":["只注意抬腿、忽略手的摆动——手脚配合才是重点。","面对面示范——孩子会照镜像做，容易搞混左右。站旁边同方向最好。","一开始就求快——快了就会变成同手同脚。"],"down":"降低抬腿高度；扶着墙走；先只做手的摆动或只做脚。","up":"加快速度变成高抬腿跑；边走边拍手；配上音乐跟着节拍；或倒退行军。","progress":["手脚是不是对侧配合。","膝盖能抬多高。","能连续走几步不乱掉。"],"outro":"走路本来就是「右脚出去、左手往前」。高抬腿行军把这个模式放大，孩子的走姿会越来越协调。"}' AS JSON))
WHERE `id` = 'A028';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要（可配儿歌）'),
  `trains` = COALESCE(`trains`, '跟着节奏做动作，练双手配合和节奏感。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拍手→拍腿→拍手→拍腿，形成节奏。"},{"imageUrl":null,"instruction":"让孩子跟着做。"},{"imageUrl":null,"instruction":"速度由慢到快。"},{"imageUrl":null,"instruction":"可以加上跺脚变成三段节奏。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两个动作交替'),
  `harder` = COALESCE(`harder`, '三四个动作组成一串。'),
  `tip` = COALESCE(`tip`, '配着儿歌做最好玩。跟得上拍子的孩子，动作的时间控制通常也比较好。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"拍手、拍腿、拍手、拍腿——跟着节奏做动作。这个游戏练的是双手配合和节奏感，配上儿歌最好玩。","principles":["跟着固定的节奏做动作，需要听觉和动作在时间上精准配合。","这种时间上的配合能力，影响的是动作的流畅度和预测能力。","节奏感好的孩子，学跳绳、打球、跳舞都比较快上手。","拍手和拍腿是两个不同的动作，交替做就需要动作的快速切换。","动作切换的能力和大脑的执行功能有关，也和转换活动的适应力有关。","双手同时拍，需要两只手在同一时间做同样的事，这是双侧对称协调。","加上跺脚变成三段节奏后，还要记住顺序，这就变成了动作序列的记忆。","节奏活动还有一个好处——它能让过度活跃的孩子把注意力收拢到一件事上。"],"prep":{"场地":"坐着或站着都可以，客厅、餐桌旁、车上都能玩。","器材":"不需要任何东西；可以配一首熟悉的儿歌。","安全检查":"拍腿的力道别太大。坐着做时注意椅子稳固。","大人位置":"大人面对孩子做，动作放大、节奏清楚。"},"shots":[{"name":"示范节奏","say":"拍手、拍腿、拍手、拍腿。"},{"name":"孩子跟着做","say":"跟着我一起。"},{"name":"慢慢加速","say":"快一点！"},{"name":"配儿歌","say":"我们边唱边拍。"},{"name":"加跺脚","say":"这次加上跺脚——拍手、拍腿、跺脚。"},{"name":"换他带","say":"换你想一个节奏。"}],"reactions":[{"if":"孩子跟不上节奏","then":"大幅放慢速度，慢到他能跟上为止。节奏感是从慢开始建立的。"},{"if":"孩子只会拍手不会切换","then":"先只做拍手，再只做拍腿，分开练熟了再交替。"},{"if":"孩子记不住三段顺序","then":"退回两段。三段对小小孩来说需要动作记忆，不急。"}],"mistakes":["速度太快——孩子跟不上就会放弃。宁可慢到有点无聊，也不要快到做不到。","只让孩子做、大人在旁边看——面对面一起做，孩子才跟得上。","一开始就三段——先两段做熟。"],"down":"只做拍手；速度放到很慢；大人握着孩子的手一起拍。","up":"加到三段、四段；加快速度；两人对拍（拍自己再拍对方）；或跟着不同速度的音乐做。","progress":["能不能跟上固定的节拍。","能记住并做出几段的节奏。","速度加快后还能不能维持。"],"outro":"拍手拍腿随时随地都能玩，等餐、坐车、睡前都行。配着儿歌做，孩子的节奏感和双手配合就在进步。"}' AS JSON))
WHERE `id` = 'A029';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '两只手做不一样的事，练高阶的协调。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一只手拍头（上下拍）。"},{"imageUrl":null,"instruction":"另一只手揉肚子（画圈）。"},{"imageUrl":null,"instruction":"同时进行，慢慢来。"},{"imageUrl":null,"instruction":"成功了就交换双手再试。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两只手做一样的动作'),
  `harder` = COALESCE(`harder`, '两只手做不同的动作。'),
  `tip` = COALESCE(`tip`, '这个游戏大人也常常做不好——全家一起玩，笑声不断。做不好完全正常，好玩最重要。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一只手拍头、另一只手揉肚子，同时进行。这个游戏大人也常常做不好——全家一起玩，笑声不断。","principles":["两只手要做完全不同的动作，一只是上下拍、一只是画圈，这叫双手不对称协调。","不对称协调比两手做同样的事难得多，因为大脑必须同时执行两套不同的指令。","这需要抑制能力——要压住「两只手做一样的事」这个自然倾向。","日常生活中很多动作都是不对称的：一手扶碗一手舀、一手扶纸一手写、一手拿刀一手拿叉。","不对称协调不好的孩子，做这些事时辅助手常常忘记帮忙。","这个游戏还需要高度的注意力，分心一下两只手就会做成一样的。","做不好是正常的，连大人都会卡住，这反而让孩子觉得好玩没压力。","交换双手再试一次，会发现另一个方向更难，这是很有趣的体验。"],"prep":{"场地":"任何地方都可以，坐着或站着都行。","器材":"不需要任何东西。","安全检查":"拍头的力道要轻，用手掌轻拍就好。","大人位置":"大人和孩子一起做，而且要让孩子看到你也会做错。"},"shots":[{"name":"分开示范","say":"先只拍头——上下拍。"},{"name":"另一只手","say":"再只揉肚子——画圈圈。"},{"name":"合起来","say":"现在两只手一起来！"},{"name":"做错了","say":"哎呀，两只手都在拍了！"},{"name":"成功了","say":"成功了！"},{"name":"交换双手","say":"换手再试试看。"}],"reactions":[{"if":"孩子两只手做成一样的","then":"先分开练熟单手动作，再用很慢的速度合起来。也可以先做三下就停。"},{"if":"孩子完全做不到、开始挫折","then":"强调「大人也做不好」，大人故意做错给他看。这个游戏的重点是好玩不是做对。"},{"if":"孩子很快就成功了","then":"交换双手、加快速度，或改成「一手画三角形一手画圆形」。"}],"mistakes":["把它当成必须做对的任务——做不到才是常态，笑一笑就好。","大人只在旁边看——一起做而且一起做错，孩子才放得开。","一开始就两手合做——先分开练熟单手。"],"down":"先只做单手；两手一起做三下就停；速度放到很慢。","up":"交换双手；加快速度；改成一手画三角一手画圆；或一边做一边数数。","progress":["能不能维持两手做不同动作五秒以上。","交换双手后能不能也做到。","需要多久才能切换成功。"],"outro":"一手拍头一手揉肚，是很经典的协调挑战。做不好完全正常，全家一起笑一笑，这个活动就成功了。"}' AS JSON))
WHERE `id` = 'A030';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个球'),
  `trains` = COALESCE(`trains`, '练接和推的基本球感，也练坐姿平衡。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"两人面对面坐着，距离一米左右。"},{"imageUrl":null,"instruction":"把球滚给对方。"},{"imageUrl":null,"instruction":"对方接住再滚回来。"},{"imageUrl":null,"instruction":"距离慢慢加大。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '坐得近、球大一点'),
  `harder` = COALESCE(`harder`, '距离拉开，或改成用脚踢回来。'),
  `tip` = COALESCE(`tip`, '接球的瞬间身体要调整——坐着玩球，平衡和手眼协调一起练。这是最适合小小孩的球类入门。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组五（球类与动作技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"两人面对面坐着，把球滚给对方。这是最适合小小孩的球类入门——不会砸到人，也不用担心接不到。","principles":["滚球比抛球简单，因为球在地上移动，速度慢、轨迹好预测。","孩子有足够的时间用眼睛追踪球，再决定手要放在哪里。","这个「看到—判断—动作」的过程，就是手眼协调的基本回路。","接球的瞬间身体会往前倾，坐着的平衡必须重新调整，这是坐姿平衡的训练。","推球出去时要控制力道——太轻球到不了，太重球会滚过头。","力道控制是很重要的能力，写字太用力、拿东西太大力的孩子通常就是这里比较弱。","你来我往的节奏，其实是最早的轮流概念，也是对话的雏形。","两人面对面坐着，还有很自然的眼神接触和互动。"],"prep":{"场地":"地板清空，两人面对面坐着，距离一米左右。","器材":"一个球；大一点、慢一点的球最好（海滩球、软球）。","安全检查":"球别太硬太小。周围清空，球滚走时孩子可能会突然爬过去捡。","大人位置":"大人坐在孩子正对面，双腿张开形成一个「球道」，球比较不会滚偏。"},"shots":[{"name":"坐好位置","say":"我们面对面坐着，腿打开。"},{"name":"滚球过去","say":"球来啰——"},{"name":"孩子接球","say":"接住了！"},{"name":"滚回来","say":"换你滚给妈妈。"},{"name":"来回节奏","say":"一来一往，你一次我一次。"},{"name":"加大距离","say":"我们坐远一点。"}],"reactions":[{"if":"孩子接不到球","then":"距离缩短、球滚慢一点，或用大一点的球。也可以先直接把球放到他手上几次。"},{"if":"孩子推球太轻，球到不了","then":"距离缩短到半米。也可以示范「用力推」的动作，让他感觉需要多少力气。"},{"if":"孩子拿到球就不还了","then":"这很常见。用「球要回家」的说法，或准备两个球轮流玩。"}],"mistakes":["球太小太硬——小小孩需要大一点、软一点的球才接得住。","距离太远——一米就够了，接不到会失去兴趣。","球滚太快——慢慢滚，让孩子有时间反应。"],"down":"距离缩到半米；用大球；球滚得很慢；或先把球直接放到他手上。","up":"距离加大；用小一点的球；滚到左边右边让他要移动；或改成用脚推。","progress":["能不能用双手拦住滚过来的球。","推球的力道能不能控制到刚好。","能连续来回几次。"],"outro":"滚球是最适合小小孩的球类入门。坐着玩，手眼协调、坐姿平衡和轮流概念一起练。"}' AS JSON))
WHERE `id` = 'A031';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个软球或气球'),
  `trains` = COALESCE(`trains`, '练手眼协调和接球的时间判断。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"两人面对面站着，距离一米。"},{"imageUrl":null,"instruction":"轻轻把球抛给孩子。"},{"imageUrl":null,"instruction":"接住了再抛回来。"},{"imageUrl":null,"instruction":"距离和方向慢慢变化。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '用气球（飘得慢，好接）'),
  `harder` = COALESCE(`harder`, '用球、距离拉远、抛向侧边。'),
  `tip` = COALESCE(`tip`, '接不到很正常——从气球开始最容易成功，因为它飘得慢，孩子有时间反应。有了成功经验再换球。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十（手眼协调与视动整合）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把球轻轻抛给孩子，让他接住。接不到很正常——从气球开始最容易成功，因为它飘得慢，孩子有时间反应。","principles":["接住抛过来的球，比接滚过来的球难很多。","球在空中移动，孩子必须预测它会落到哪里，这叫轨迹预测。","轨迹预测需要视觉追踪、距离判断和时间判断三个能力同时运作。","接球还要抓对时机——手合起来太早球会弹开，太晚就漏掉了。","这个时机的掌握叫时间控制，是所有球类运动的核心。","接球时手臂要有一点缓冲的动作，像是把球「吸」进怀里，而不是硬接。","气球飘得慢，给了孩子大量的反应时间，是建立信心最好的道具。","发展参考：三岁能用身体和手臂一起抱住大球，五岁左右能用双手接住。"],"prep":{"场地":"客厅或户外，两人面对面站着，距离一米。","器材":"一个软球或气球；海滩球、布球都可以。","安全检查":"别用硬球。气球破掉后的碎片要马上收走，小小孩可能会放进嘴里。","大人位置":"大人站在孩子正前方一米处，抛球时手往上托，让球划出一条慢慢的弧线。"},"shots":[{"name":"从气球开始","say":"我们先用气球，它飘得慢。"},{"name":"准备接的姿势","say":"手打开，准备好。"},{"name":"抛过去","say":"来啰——"},{"name":"接住","say":"接住了！"},{"name":"换成球","say":"现在换成软球试试看。"},{"name":"变化方向","say":"这次往左边一点。"}],"reactions":[{"if":"孩子完全接不到","then":"退回气球，或改成大人把球直接放到他手上几次，建立「接住」的感觉。"},{"if":"孩子用身体挡而不是用手接","then":"这是正常的过渡阶段。三到四岁用身体抱住就很好，五岁左右才会用双手接。"},{"if":"孩子怕球、会闪躲","then":"一定要从气球或很软的布球开始。闪躲代表他觉得会痛，硬来会更害怕。"}],"mistakes":["一开始就用球——从气球开始，成功率高太多了。","抛太快太用力——要用往上托的方式，让球慢慢划弧线过去。","距离太远——一米就好，近到几乎一定接得到。"],"down":"用气球；距离缩到半米；球直接放到他手上；或改成滚球。","up":"换成球；距离加大；抛向左右两侧让他移动；或规定只能用单手接。","progress":["是用身体挡还是用双手接。","十次能接到几次。","球抛到侧边时会不会移动去接。"],"outro":"接不到球完全正常。从气球开始，让孩子先成功几次，有了信心再换球——这个顺序不要跳。"}' AS JSON))
WHERE `id` = 'A032';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '球或纸团＋一个篮子或纸箱'),
  `trains` = COALESCE(`trains`, '练投掷的准确度和力度控制。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把篮子放在几步外。"},{"imageUrl":null,"instruction":"让孩子把球丢进去。"},{"imageUrl":null,"instruction":"进了就欢呼。"},{"imageUrl":null,"instruction":"距离慢慢加大，或把篮子换小。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '篮子大、距离近'),
  `harder` = COALESCE(`harder`, '篮子小、距离远。'),
  `tip` = COALESCE(`tip`, '没有球就把纸揉成团——一样好玩。进球的成就感会让孩子丢上一百次都不累。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组五（球类与动作技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把篮子放在几步外，让孩子把球丢进去。没有球就把纸揉成团——进球的成就感会让孩子丢上一百次都不累。","principles":["投掷要同时控制两件事：方向和力道。","方向靠的是手臂挥出去的路径，力道靠的是用多少力气。","这两件事要配合得刚好，球才会落在目标里，这是很精细的动作调节。","丢之前眼睛要先锁定目标，这是视觉定位。","丢的时候身体会自然转动、重心会转移，是全身性的协调动作。","揉纸团这个动作本身就是很好的手部练习，用到手掌和手指的力量。","进球有明确的回馈——进了就是进了，孩子马上知道结果，这让练习变得有趣。","距离和篮子大小随时可以调，同一个游戏能从两岁玩到八岁。"],"prep":{"场地":"客厅或走廊，篮子放在两到五步外。","器材":"球或纸团＋一个篮子或纸箱；洗衣篮、纸箱、水桶都可以。","安全检查":"别在有玻璃、电视或摆饰的方向丢。用软球或纸团最安全。","大人位置":"大人站在孩子旁边，也可以一起比赛。"},"shots":[{"name":"准备材料","say":"没有球没关系，我们来揉纸团。"},{"name":"瞄准","say":"眼睛看着篮子。"},{"name":"丢出去","say":"丢！"},{"name":"进篮","say":"进了！"},{"name":"调整距离","say":"这次站远一点。"},{"name":"换小篮子","say":"或者我们换小一点的篮子。"}],"reactions":[{"if":"孩子怎么丢都进不去","then":"把篮子拿近到一步远，或换大一点的容器。先让他进几球建立信心。"},{"if":"孩子丢得太用力，球飞过头","then":"提醒「轻轻丢」，或把篮子放近一点。力道控制需要慢慢练。"},{"if":"孩子只想用手放进去","then":"把篮子挪远一点，让他放不到只能丢。"}],"mistakes":["距离一开始就太远——进不去会很快失去兴趣。从一两步开始。","篮子太小——大篮子进球率高，孩子才愿意一直玩。","只丢不捡——让孩子自己去捡回来，蹲下站起又是一次运动。"],"down":"篮子放到一步远；用大的洗衣篮；改成站在篮子旁边往下投。","up":"距离加大；篮子换小；改用非惯用手丢；或篮子放在高处要往上抛。","progress":["十球能进几球。","能从多远的距离投进。","丢的力道是不是越来越准。"],"outro":"纸团加纸箱，零成本的投掷练习。孩子在丢进去的成就感里，练到的是方向和力道的精准控制。"}' AS JSON))
WHERE `id` = 'A033';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '球＋两个瓶子当球门'),
  `trains` = COALESCE(`trains`, '练踢球的准确度，也练单脚站稳。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"用两个瓶子摆出一个球门。"},{"imageUrl":null,"instruction":"把球放在几步外。"},{"imageUrl":null,"instruction":"让孩子踢进球门。"},{"imageUrl":null,"instruction":"两只脚轮流踢。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '球门大、球放很近'),
  `harder` = COALESCE(`harder`, '球门缩小、距离拉远，或踢滚动的球。'),
  `tip` = COALESCE(`tip`, '踢球的时候另一只脚要站稳——这其实是很好的单脚平衡训练，孩子却只觉得在玩球。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"两个瓶子摆出一个球门，让孩子把球踢进去。踢球的时候另一只脚要站稳——这其实是很好的单脚平衡训练，孩子却只觉得在玩球。","principles":["踢球时，支撑脚要独自承受全身重量，这就是单脚站。","而且不只是站着不动，还要在另一只脚挥出去的时候保持稳定，难度更高。","踢的那只脚要控制方向和力道，和投掷是同样的道理，只是换成下肢。","踢之前眼睛要看球和球门，这是下肢版本的手眼协调，专业上叫脚眼协调。","踢球时身体会自然往支撑脚那侧倾斜，这是重心转移的练习。","两只脚都要练，因为惯用脚和非惯用脚的差异通常很大。","球门的宽度和距离都可以调，难度控制很容易。","这个动作直接连到踢毽子、跳绳、足球等日后的运动项目。"],"prep":{"场地":"客厅或户外，清出三到五米，球门前方不要有易碎物。","器材":"球＋两个瓶子当球门；宝特瓶、鞋子、抱枕都可以当门柱。","安全检查":"用软球或塑胶球。室内注意不要踢到电视、玻璃或摆饰。门柱用软的或轻的东西，撞倒也不会痛。","大人位置":"大人站在球门后面当守门员，或站在孩子旁边指导。"},"shots":[{"name":"摆球门","say":"两个瓶子就是球门。"},{"name":"支撑脚位置","say":"另一只脚要站在球的旁边。"},{"name":"踢出去","say":"踢！"},{"name":"进门","say":"进球了！"},{"name":"换脚","say":"换另外一只脚踢。"},{"name":"加难度","say":"这次球门变小一点。"}],"reactions":[{"if":"孩子踢空","then":"球先放着不动，让他站好再踢。也可以先练「用脚碰球」不用踢出去。"},{"if":"孩子踢的时候会跌倒","then":"代表单脚支撑不稳。先练金鸡独立，或让他扶着椅子踢。"},{"if":"孩子只用惯用脚踢","then":"刻意把球放在另一侧，或规定「这次只能用左脚」。"}],"mistakes":["球门太小——刚开始一米宽，进球率高才好玩。","支撑脚站太远——要站在球的旁边，站太远会踢不到也容易跌倒。","只练惯用脚——两只脚都要练，差异会很明显但值得练。"],"down":"球门加宽；距离缩到两步；扶着椅子踢；或先练用脚碰球。","up":"球门变窄；距离加大；大人当守门员；或踢滚动中的球。","progress":["十球能进几球。","踢的时候支撑脚稳不稳。","两只脚的表现差多少。"],"outro":"两个瓶子就是球门。孩子以为在玩球，其实每踢一次都在练单脚站稳和下肢的控制。"}' AS JSON))
WHERE `id` = 'A034';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '一个气球'),
  `trains` = COALESCE(`trains`, '练持续的手眼协调和反应。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把气球拍向空中。"},{"imageUrl":null,"instruction":"不让它掉到地上。"},{"imageUrl":null,"instruction":"一起数能拍几下。"},{"imageUrl":null,"instruction":"可以规定只能用手／只能用头。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一个人随便拍'),
  `harder` = COALESCE(`harder`, '全家轮流拍、或规定用身体不同部位。'),
  `tip` = COALESCE(`tip`, '气球飘得慢，是最适合练手眼协调的道具。注意别撞到家具，也别让小小孩把破掉的气球片放进嘴里。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十（手眼协调与视动整合）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一个气球，拍起来不让它掉到地上。气球飘得慢，是最适合练手眼协调的道具，一个就能玩很久。","principles":["气球下落的速度比球慢很多，孩子有充裕的时间看清楚、判断、出手。","这个「充裕的时间」对协调还在发展的孩子非常重要，让他有机会成功。","要持续拍打不让它落地，眼睛必须一直追着气球，这是持续性的视觉追踪。","持续追踪的能力，和日后阅读时眼睛沿着行移动直接相关。","气球会往不同方向飘，孩子必须移动身体去接，这练的是动态平衡。","手要在对的时间、对的位置出现，这是时间与空间的双重判断。","计数「拍了几下」会让孩子自己想要突破纪录，动机很强。","规定只能用手、只能用头，就变成了不同的规则挑战，玩法可以一直变。"],"prep":{"场地":"客厅清出空间，移开桌上的摆饰和易碎物。天花板不要太低。","器材":"一个气球；准备两三个备用，破了可以马上换。","安全检查":"气球破掉的碎片一定要立刻收走，三岁以下的孩子可能会放进嘴里造成窒息风险。注意别撞到家具。对乳胶过敏的孩子要避免。","大人位置":"大人和孩子一起拍，也可以当接应的人。"},"shots":[{"name":"吹气球","say":"我们先来吹一个气球。"},{"name":"往上拍","say":"拍起来，不要让它掉下去！"},{"name":"追着跑","say":"它飘走了，快追！"},{"name":"计数","say":"一、二、三、四⋯⋯"},{"name":"换部位","say":"这次只能用头顶！"},{"name":"全家接力","say":"我们一人拍一下，接力！"}],"reactions":[{"if":"孩子拍不到气球","then":"大人先把气球托高，让它慢慢飘下来。也可以用绳子把气球吊起来，位置固定比较好拍。"},{"if":"气球一直飘到角落","then":"在比较小的空间玩，或规定「只能在这块垫子上」。"},{"if":"孩子太兴奋、乱冲乱撞","then":"改成坐着拍，或规定「脚不能离开这个位置」。"}],"mistakes":["气球破了没马上收碎片——这是真正的窒息风险，务必立刻捡起来。","在摆满东西的房间玩——孩子追气球时不会看路，一定要先清空。","吹太大——太大的气球飘得快也容易破，七八分满最好。"],"down":"用绳子把气球吊起来固定位置；坐着拍；大人帮忙托高。","up":"规定只能用单手／只能用头／只能用脚；两人对拍；或加入「不能落地也不能碰墙」的规则。","progress":["能连续拍几下不落地。","气球飘到侧边时会不会移动去接。","能不能用指定的身体部位拍到。"],"outro":"一个气球就能让孩子动十几分钟，眼睛还一直在追视。记得气球破了要马上收碎片——这是最重要的安全提醒。"}' AS JSON))
WHERE `id` = 'A035';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几个矿泉水瓶或抱枕'),
  `trains` = COALESCE(`trains`, '练跑动中改变方向的能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把瓶子排成一列，间隔一米左右。"},{"imageUrl":null,"instruction":"让孩子S形绕过去。"},{"imageUrl":null,"instruction":"先用走的熟悉路线，再用跑的。"},{"imageUrl":null,"instruction":"碰倒了没关系。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '走着绕、间隔大'),
  `harder` = COALESCE(`harder`, '跑着绕、间隔缩小。'),
  `tip` = COALESCE(`tip`, '一边跑一边改方向，是所有球类运动的基础。用软的东西当障碍，撞到也不痛。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组九（跑步与变向）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"几个瓶子排成一列，孩子用S形绕过去。一边跑一边改变方向，是所有球类运动的基础。","principles":["直线跑和绕着跑是两种不同的能力，后者难度高很多。","转弯时身体必须往内侧倾斜来对抗离心力，这是重心的动态调整。","脚步也要改变——外侧脚要用力推蹬，内侧脚要缩短步伐。","这些调整要在移动中瞬间完成，是很高阶的动作控制。","眼睛要提前看到下一个瓶子，身体才来得及准备转向，这叫视觉先行。","视觉先行的能力不好，孩子跑起来就会撞到东西或紧急煞车。","绕障碍还需要判断「我的身体有多宽、要绕多远才不会撞到」，这是身体形象。","这个能力直接用在球类运动、躲避追逐、还有人多时的行走穿梭。"],"prep":{"场地":"客厅或户外，清出五到八米的通道，两侧留空间。","器材":"几个矿泉水瓶或抱枕；空的宝特瓶最理想，撞倒也不会痛。","安全检查":"障碍物一定要用软的或轻的。地面防滑，跑动时最容易滑倒。周围清空。","大人位置":"大人站在终点，或和孩子比赛。"},"shots":[{"name":"排瓶子","say":"瓶子排成一列，我们要绕过去。"},{"name":"先用走的","say":"先慢慢走一次，认识路线。"},{"name":"转弯的身体","say":"转弯的时候身体要往里面倾。"},{"name":"跑起来","say":"这次跑！"},{"name":"撞倒了","say":"撞倒没关系，扶起来再来。"},{"name":"计时挑战","say":"看这次几秒跑完！"}],"reactions":[{"if":"孩子直接跑直线不绕","then":"先用走的走一次S形路线，用手牵着带他绕。路线熟了再跑。"},{"if":"孩子一直撞倒瓶子","then":"把间距拉大，或把瓶子换成更大的目标（抱枕）。撞倒是正常的，别责备。"},{"if":"孩子跑一跑就滑倒","then":"地面太滑。移到有防滑的地面或户外，或改成用走的。"}],"mistakes":["用玻璃瓶或硬的东西当障碍——撞到会受伤，一定要用软的或空瓶。","间距太密——刚开始一米以上，太密会一直撞倒。","在光滑地板上跑——转弯时最容易滑倒，地面防滑是前提。"],"down":"先用走的；间距拉大；障碍换成大一点的抱枕；或只绕两三个。","up":"加快速度；间距缩小；加上计时；或改成运着球绕。","progress":["能不能完整绕完不撞倒。","跑完的时间有没有变快。","转弯时身体会不会自然倾斜。"],"outro":"一边跑一边转弯，是球类运动的基础。几个空瓶子摆一摆，客厅就变成敏捷训练场。"}' AS JSON))
WHERE `id` = 'A036';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一条软的带子或毛巾'),
  `trains` = COALESCE(`trains`, '和别人同步走路，练配合和节奏。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"用毛巾把大人和孩子相邻的腿轻轻绑起来（不要太紧）。"},{"imageUrl":null,"instruction":"喊「一、二」同步迈步。"},{"imageUrl":null,"instruction":"慢慢走一小段。"},{"imageUrl":null,"instruction":"走稳了再慢慢加长。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '走三五步'),
  `harder` = COALESCE(`harder`, '走远一点，或稍微加快。'),
  `tip` = COALESCE(`tip`, '绑带一定要松、能一拉就开，走的速度要慢——这个游戏重点在配合，不在快。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"用毛巾把大人和孩子相邻的腿轻轻绑在一起，喊着口令一起走。这个游戏重点在配合，不在快。","principles":["两个人的腿绑在一起，走路就必须同步，不然一定跌倒。","要同步，两人都必须调整自己原本的步频和步幅去配合对方。","这种为了配合别人而调整自己的能力，是合作的核心。","喊「一、二」的口令提供了共同的节奏，让同步变得可能。","走的时候两人要互相扶着、感受对方的动作，这是很直接的身体沟通。","被绑住的那只脚会改变原本的走路模式，身体必须重新找平衡。","这是双人的动态平衡，比自己一个人走难得多。","游戏本身有很强的互动和笑点，对亲子关系也有帮助。"],"prep":{"场地":"客厅或户外平坦处，清出三到五米，地面防滑铺软。","器材":"一条软的带子或毛巾；一定要是能一拉就开的，绝不用绳子打死结。","安全检查":"这是本模组绑缚类活动，安全要求最高。绑带务必松、务必能一拉就开。走的速度要慢。地面要软。跌倒时大人要护住孩子。","大人位置":"大人和孩子并肩站，相邻的腿绑在一起，内侧的手互相搭肩或牵手。"},"shots":[{"name":"绑腿","say":"我们把这两只脚轻轻绑起来。"},{"name":"搭肩准备","say":"手搭在对方肩膀上。"},{"name":"喊口令","say":"绑起来的脚先走——一！"},{"name":"换外侧脚","say":"外面的脚——二！"},{"name":"慢慢走","say":"慢慢来，不用快。"},{"name":"跌倒也没关系","say":"哎呀，我们再来！"}],"reactions":[{"if":"两人步调完全对不上","then":"先原地踏步练口令，「一」抬绑着的脚、「二」抬外侧的脚。原地练顺了再往前走。"},{"if":"孩子一直跌倒","then":"速度放到最慢，或改成只绑很松、几乎只是靠在一起走。也可以先手牵手不绑腿练同步。"},{"if":"孩子觉得被绑住很不舒服","then":"不勉强。改成手牵手同步走，或用「跟着我的脚步走」的方式练配合。"}],"mistakes":["绑太紧或打死结——这是最危险的错误，跌倒时解不开会受伤。务必松绑、能一拉就开。","走太快——这个游戏不是比赛，速度慢才练得到配合。","在硬地板上玩——一定要铺垫子或在草地上。"],"down":"不绑腿，改成手牵手同步走；原地踏步练口令；绑得非常松。","up":"加长距离；加快速度；中途要转弯；或三个人一起玩。","progress":["能不能跟上共同的口令节奏。","能连续走几步不跌倒。","会不会主动配合对方的速度。"],"outro":"两人三脚练的是配合，不是速度。绑带一定要松、要能一拉就开——这是玩这个游戏最重要的前提。"}' AS JSON))
WHERE `id` = 'A037';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '记住一串动作再做出来，练观察和动作记忆。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人做一串动作（拍手→转圈→跳一下）。"},{"imageUrl":null,"instruction":"孩子跟着做一遍。"},{"imageUrl":null,"instruction":"动作一次比一次多。"},{"imageUrl":null,"instruction":"轮流当领队。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两个动作'),
  `harder` = COALESCE(`harder`, '四五个动作连成一串。'),
  `tip` = COALESCE(`tip`, '要先看清楚、记住、再做出来——这个游戏同时练了观察、记忆和动作，一举三得。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十三（动作计划与身体觉知）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"大人做一串动作，孩子看完再做一遍。要先看清楚、记住、再做出来——这个游戏同时练了观察、记忆和动作，一举三得。","principles":["要模仿一串动作，孩子必须先用眼睛看清楚每个动作和顺序。","这是视觉观察能力，看得仔细才模仿得像。","看完之后动作已经结束了，他必须把顺序记在脑子里，这是动作记忆。","动作记忆的容量，和课堂上记住老师指令的能力是同一件事。","记住之后还要用自己的身体做出来，这是动作计划。","动作计划不好的孩子，知道要做什么但身体就是做不出来。","动作从一个慢慢加到四五个，练的是记忆广度的扩展。","轮流当领队时，孩子要自己想出动作，这就变成了创造和表达。"],"prep":{"场地":"任何地方都可以，客厅或户外都行。","器材":"不需要任何东西。","安全检查":"动作别设计得太危险（不要有跳上家具之类的）。空间要够。","大人位置":"大人站在孩子对面或旁边，动作做大、做慢、做清楚。"},"shots":[{"name":"一个动作","say":"看好喔——拍手！"},{"name":"孩子模仿","say":"换你做。"},{"name":"加到两个","say":"这次两个——拍手、转圈。"},{"name":"加到三个","say":"拍手、转圈、跳一下！"},{"name":"记错了","say":"哎呀，顺序不对，再看一次。"},{"name":"换他当领队","say":"换你出题考妈妈！"}],"reactions":[{"if":"孩子只记得最后一个动作","then":"退回两个动作。也可以在做的时候一边数「第一个、第二个」，帮他建立顺序感。"},{"if":"孩子做得出来但顺序乱掉","then":"这很常见。可以让他先用嘴巴说一遍顺序再做，说出来能帮助记忆。"},{"if":"孩子不想模仿只想自己乱做","then":"先让他当领队，满足了主导权之后通常就愿意轮流了。"}],"mistakes":["动作一次加太多——两三岁能记两个就很好，四五岁三到四个。","动作做太快——要做慢、做清楚，孩子才看得懂。","记错就说「你没有在看」——重看一次就好，这本来就是在练记忆。"],"down":"一次只做一个动作；动作放慢；做的时候一边说出来。","up":"加到四五个动作；加入方向（往左转、往右跳）；倒着做回来；或隔一段时间再让他做一次。","progress":["能记住并做出几个连续动作。","顺序对不对。","当领队时能不能想出新动作。"],"outro":"跟着我做，同时练了观察、记忆和动作三件事。从两个动作开始，慢慢往上加，孩子的记忆广度就撑开了。"}' AS JSON))
WHERE `id` = 'A038';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '滑步车＋安全帽'),
  `trains` = COALESCE(`trains`, '练平衡和用脚蹬地前进。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选高度合适的车（坐着两脚能踩地）。"},{"imageUrl":null,"instruction":"先让他坐着用脚走。"},{"imageUrl":null,"instruction":"熟练后用力蹬地滑一段。"},{"imageUrl":null,"instruction":"一定要戴安全帽，在平坦无车的地方玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '坐着用脚走'),
  `harder` = COALESCE(`harder`, '蹬地滑行，两脚离地滑一小段。'),
  `tip` = COALESCE(`tip`, '滑步车比辅助轮脚踏车更能练平衡——学会滑步车的孩子，通常很快就能骑两轮车。安全帽不能省。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十四（协调·节律与球类技巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"滑步车比辅助轮脚踏车更能练平衡。学会滑步车的孩子，通常很快就能骑两轮车——因为平衡早就练好了。","principles":["辅助轮脚踏车有四个接地点，孩子其实不需要平衡就能骑。","滑步车没有踏板、没有辅助轮，孩子必须靠自己维持平衡。","这训练的是动态平衡——在移动中不断调整重心不倒下。","双脚蹬地前进的动作，练的是下肢的交替出力。","滑行时双脚离地的那几秒，是纯粹的平衡挑战，时间会越来越长。","转弯时要靠身体倾斜和把手微调，这是很精细的重心控制。","因为双脚随时可以踩地，孩子的安全感很高，愿意尝试。","这个能力会直接转移到两轮脚踏车，通常不需要经过辅助轮阶段。"],"prep":{"场地":"平坦、无车辆、无坡度的地方——公园步道、社区中庭。绝不在马路边或有车的地方。","器材":"滑步车＋安全帽；护膝护肘也建议戴。","安全检查":"这是本模组户外器材活动，安全要求最高。安全帽绝对不能省。车座高度要让孩子坐着时两脚能完全踩到地面。选平坦无坡、无车辆的场地。全程在大人视线内。","大人位置":"大人走在孩子侧后方，可以随时扶住车座或孩子。"},"shots":[{"name":"调车座","say":"坐上去，两只脚要能踩到地。"},{"name":"戴安全帽","say":"安全帽一定要戴好。"},{"name":"坐着用走的","say":"先坐着，用脚慢慢走。"},{"name":"开始蹬地","say":"用力蹬一下，滑一段！"},{"name":"双脚离地","say":"看，你的脚离开地面了！"},{"name":"转弯","say":"我们绕过那棵树。"}],"reactions":[{"if":"孩子不敢滑、只敢用走的","then":"完全没关系，先走几天。用脚走熟了，某一天他自己就会开始滑了。不要催。"},{"if":"孩子滑几步就用脚煞车","then":"这是正常的安全机制。可以在很轻微的缓坡上让他体验滑行的感觉。"},{"if":"孩子重心不稳一直歪","then":"检查车座高度，太高会不稳。也可以大人轻扶车座后方跟着走一段。"}],"mistakes":["不戴安全帽——这是绝对不能妥协的一条。","车座调太高——孩子双脚要能完全踩地才有安全感，这是最常见的设定错误。","在有车或有坡的地方练——场地选择是安全的第一道关卡。"],"down":"先只坐着用脚走；在很短的距离练；大人轻扶车座跟着走。","up":"延长滑行距离；练转弯绕障碍；在很轻微的缓坡滑行；或练单脚点地滑行。","progress":["双脚离地能滑行几秒。","能不能自己转弯。","愿不愿意滑得比较远。"],"outro":"滑步车是通往两轮车最好的桥梁。记住三件事：安全帽戴好、车座调到双脚能踩地、场地要平坦无车。"}' AS JSON))
WHERE `id` = 'A039';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '枕头、线、球'),
  `trains` = COALESCE(`trains`, '把这个模组的活动串起来玩，看看进步了多少。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：走过枕头路。"},{"imageUrl":null,"instruction":"第二关：单脚站十秒。"},{"imageUrl":null,"instruction":"第三关：接住五次球。"},{"imageUrl":null,"instruction":"全部完成盖个章或贴张贴纸。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关降低标准，都给协助'),
  `harder` = COALESCE(`harder`, '连续完成两轮，或加上计时。'),
  `tip` = COALESCE(`tip`, '把训练做成「闯关」，孩子会主动想练。关卡内容每周换一换，就不会腻。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十一（单脚与动态平衡）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"把这个模组的活动串成三个关卡，闯关成功就盖个章。把训练做成闯关，孩子会主动想练。","principles":["把零散的活动组成有结构的关卡，孩子会觉得这是一件「可以完成的事」。","有明确的起点和终点，比「我们来练平衡」更能引发动机。","闯关有清楚的成功标准，孩子知道自己做到没做到，这让努力变得有意义。","盖章或贴纸提供了看得见的累积，是很有效的行为增强。","三个关卡分别对应静态平衡、动态平衡和手眼协调，涵盖面完整。","每周换关卡内容，孩子不会腻，也能看到自己在不同项目上的进步。","闯关还需要孩子记住三个关卡的顺序，顺便练了顺序记忆。","全家一起闯关时，孩子看到大人也会失败，对挫折的接受度会提高。"],"prep":{"场地":"客厅规划出三个区域，分别摆好三关的器材。","器材":"枕头、地上的线、球；再准备一张闯关卡和贴纸或印章。","安全检查":"每一关的安全要求照该活动的原则办理。关卡之间留出走动空间。","大人位置":"大人当关主，负责计时、计数和盖章。"},"shots":[{"name":"介绍关卡","say":"今天有三关，全部过了就盖章！"},{"name":"第一关","say":"第一关：走过枕头路。"},{"name":"第二关","say":"第二关：单脚站十秒。"},{"name":"第三关","say":"第三关：接住五次球。"},{"name":"盖章","say":"三关都过了，盖章！"},{"name":"累积纪录","say":"你看，这个月过了八次！"}],"reactions":[{"if":"孩子某一关一直过不了","then":"当场调整那一关的标准（单脚站改成五秒）。闯关的目的是建立信心，不是考试。"},{"if":"孩子只想玩喜欢的那一关","then":"让他自己排三关的顺序，或让他设计其中一关。自主权能提高配合度。"},{"if":"孩子过关后就不想再玩了","then":"很正常。每天一次就够，不用重复。下次换关卡内容会更有新鲜感。"}],"mistakes":["关卡标准订太高——过不了会打击信心。标准要订在他努力一下就做得到的程度。","关卡一直不换——两三周就换一次内容，保持新鲜感。","只有孩子闯关——大人也来闯一次，让他看到大人也会失败。"],"down":"降低每关的标准；只做两关；关卡改成他最拿手的项目。","up":"提高标准；加到五关；加上计时；或让孩子自己设计关卡。","progress":["每一关的成绩（走几个枕头、站几秒、接几次球）记录下来。","一个月后再测一次，比较进步幅度。","孩子会不会主动要求闯关。"],"outro":"把训练做成闯关，孩子从「被要求练习」变成「想要挑战」。关卡每两三周换一次，这套玩法可以用很久。"}' AS JSON))
WHERE `id` = 'A040';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸箱＋几本书'),
  `trains` = COALESCE(`trains`, '推重一点的东西，全身出力，也让情绪安定下来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在纸箱里放几本书。"},{"imageUrl":null,"instruction":"让孩子把箱子推到指定的地方。"},{"imageUrl":null,"instruction":"身体往前倾、用腿蹬地推。"},{"imageUrl":null,"instruction":"重量以他推得动但要用力为准。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '箱子轻、距离短'),
  `harder` = COALESCE(`harder`, '多放几本书，或推远一点。'),
  `tip` = COALESCE(`tip`, '这类「出力气」的活动除了长力量，还能让躁动的孩子安定下来——比讲道理有用得多。地上要清空、路线要平。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"纸箱里放几本书，让孩子推着走。这类「出力气」的活动除了长力量，还能让躁动的孩子安定下来——比讲道理有用得多。","principles":["推重物时，从手臂、肩膀、核心到腿部的肌肉会同时用力。","这种全身出力的活动会产生大量的本体觉输入，也就是肌肉和关节传给大脑的讯息。","本体觉输入对神经系统有安定的效果，这是它最被低估的价值。","所以很多治疗师会在孩子情绪浮躁时，请他去推东西或搬东西。","推的时候身体要往前倾、用腿蹬地，这是很标准的全身发力模式。","推不动时孩子会自己调整姿势——降低重心、换个角度，这是动作问题解决。","要判断「这个我推得动吗」，用到的是对自己力气的认识。","重量的拿捏是关键：要推得动，但必须真的用力才推得动。"],"prep":{"场地":"客厅到房间的路线，地面平坦清空，最好是硬地板或短毛地毯。","器材":"纸箱＋几本书；也可以用装了衣服的洗衣篮、装了水瓶的袋子。","安全检查":"路线上清空，孩子推箱子时视线会被挡住一部分。重量以他要用力但推得动为准，太重会用错姿势。地毯太厚会推不动，反而容易受伤。","大人位置":"大人走在孩子侧边，注意路线上有没有障碍。"},"shots":[{"name":"装箱","say":"我们放几本书进去。"},{"name":"推的姿势","say":"身体往前倾，用腿蹬地。"},{"name":"开始推","say":"推！"},{"name":"中途调整","say":"推不动就换个姿势试试。"},{"name":"推到终点","say":"到了！搬家完成！"},{"name":"加重量","say":"再加一本书试试看。"}],"reactions":[{"if":"孩子推不动、放弃了","then":"立刻拿掉一两本书。推得动才有成就感，太重只会让他放弃。"},{"if":"孩子用手拉着箱子走而不是推","then":"示范正确的推法：双手撑在箱子上、身体前倾。也可以在箱子后面画一个手印当提示。"},{"if":"孩子推一下就喊累","then":"缩短距离到两三步，多做几趟。短而多比长而少有效。"}],"mistakes":["箱子太重——推不动会用错姿势（弯腰、扭身），反而伤腰。宁可轻一点。","路线上有障碍——孩子的视线被箱子挡住，一定要先清空。","在厚地毯上推——阻力太大推不动，容易用蛮力受伤。"],"down":"减少书本数量；距离缩到两三步；改成推空箱子。","up":"增加重量；加长距离；中途要转弯；或改成推着箱子绕过障碍。","progress":["能推动多重的箱子。","推的姿势是身体前倾还是弯腰。","推完之后情绪有没有比较安定。"],"outro":"推箱子是最方便的全身力量训练，也是最好的情绪调节工具。孩子躁动的时候，请他推个箱子，往往比讲十句道理有效。"}' AS JSON))
WHERE `id` = 'A041';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一条大浴巾或粗绳'),
  `trains` = COALESCE(`trains`, '练手臂和背部的拉力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"两人各握毛巾一端。"},{"imageUrl":null,"instruction":"慢慢往后拉，互相较劲。"},{"imageUrl":null,"instruction":"拉十秒放松一次。"},{"imageUrl":null,"instruction":"让孩子赢几次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '坐着拉、力气小'),
  `harder` = COALESCE(`harder`, '站着拉、时间拉长。'),
  `tip` = COALESCE(`tip`, '千万别突然松手——孩子会往后跌倒。毛巾要粗一点、握得住，力气由大人控制。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一条大浴巾，两人各握一端往后拉。拔河练的是手臂和背部的拉力——但有一件事千万不能做：突然松手。","principles":["拔河用到的是拉的力量，主要是背阔肌、二头肌和握力。","拉的力量和推的力量用的是不同肌群，两种都要练才均衡。","现代孩子普遍缺乏拉的动作——爬树、吊单杠、拉东西的机会都变少了。","拉力不足会影响的是肩胛骨的稳定，进而影响手部的精细动作。","拔河时身体要往后倾、脚要蹬住地面，这是全身的抗阻训练。","持续拉十秒的等长收缩，特别能练到肌耐力。","这是很强的本体觉输入，对安定情绪很有帮助。","两人较劲的过程还有输赢的情绪练习，是很完整的活动。"],"prep":{"场地":"地面铺垫子或地毯，两人身后各留出一两步的空间。","器材":"一条大浴巾或粗绳；浴巾比绳子好——粗、好握、不会磨手。","安全检查":"这个活动最重要的安全点：绝不突然松手。大人要全程控制力道，孩子身后一定要留空间。别用细绳，会勒伤手。","大人位置":"大人半跪或坐着，让高度接近孩子，力道由大人控制。"},"shots":[{"name":"握好毛巾","say":"两只手握紧，握在毛巾的这一端。"},{"name":"站稳姿势","say":"一只脚在前、一只脚在后，站稳。"},{"name":"开始拉","say":"一、二、三，拉！"},{"name":"维持十秒","say":"撑住——数到十。"},{"name":"慢慢放松","say":"好，我们慢慢松开。"},{"name":"让他赢","say":"你赢了！"}],"reactions":[{"if":"孩子一下就被拉过去","then":"大人力道减到最小，让他能撑住。拔河的重点是出力，不是分胜负。"},{"if":"孩子拉一下就放手","then":"毛巾可能太滑或太细。换粗一点的浴巾，或在末端打个结方便握。"},{"if":"孩子输了就生气","then":"赛前先说好「有输有赢」。大人也要输几次，让他看到输了没关系。"}],"mistakes":["突然松手——这是最危险的错误，孩子会往后跌倒撞到头。放松一定要慢。","用细绳——会勒伤手，一定要用粗浴巾或粗绳。","大人用全力——力道要由大人控制在孩子能撑住的程度。"],"down":"大人力道减到最小；坐着拉；拉五秒就好。","up":"延长到十五秒；改成站着拉；两人都站着；或全家分两队拉。","progress":["能持续用力几秒。","拉的时候姿势稳不稳。","输了的情绪反应有没有比较平稳。"],"outro":"拔河练的是拉的力气，这是现代孩子最缺的。记住唯一的铁律——绝不突然松手，放松一定要慢慢来。"}' AS JSON))
WHERE `id` = 'A042';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '装了东西的袋子＋一条绳子'),
  `trains` = COALESCE(`trains`, '练拉的力气，和推的动作正好互补。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把绳子绑在袋子上。"},{"imageUrl":null,"instruction":"让孩子拖着走。"},{"imageUrl":null,"instruction":"身体往后倾、用力拉。"},{"imageUrl":null,"instruction":"距离慢慢加长。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '很轻、走一小段'),
  `harder` = COALESCE(`harder`, '重一点，或拖远一点。'),
  `tip` = COALESCE(`tip`, '推和拉用的是不同的肌肉——两种都要玩，力气才长得均衡。当成「小货车送货」的游戏最好玩。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把绳子绑在袋子上，让孩子拖着走。推和拉用的是不同的肌肉——两种都要玩，力气才长得均衡。","principles":["拖拉时身体要往后倾，用的是背部和腿部的力量。","这和推东西时身体前倾、用胸和手臂的模式正好相反。","两种动作互补，一起练力量的发展才均衡。","拖着东西走时，重心会被往后拉，身体必须重新找平衡。","这是负重状态下的动态平衡，比空手走路难得多。","手要一直握住绳子，是持续的握力训练。","拖的阻力是持续的，不像推东西有时会突然滑动，对肌肉是稳定的负荷。","当成「小货车送货」的游戏，孩子会自己一趟一趟拖不停。"],"prep":{"场地":"客厅或走廊，地面平坦清空，路线三到五米。","器材":"装了东西的袋子＋一条绳子；也可以用有轮子的玩具车、洗衣篮。","安全检查":"绳子长度要够，孩子往前走时袋子不会打到他的脚。绳子别缠在手上或身上。重量以他拖得动为准。","大人位置":"大人走在旁边，注意绳子有没有绊到人。"},"shots":[{"name":"绑绳子","say":"我们把绳子绑在袋子上。"},{"name":"握绳姿势","say":"两只手握好，不要缠在手上。"},{"name":"身体后倾","say":"身体往后一点，用力拉。"},{"name":"拖着走","say":"小货车送货啰！"},{"name":"送到终点","say":"货送到了！"},{"name":"加重量","say":"这次货比较多喔。"}],"reactions":[{"if":"孩子拖不动","then":"减轻重量，或换成表面比较滑的袋子（塑胶袋比布袋好拖）。"},{"if":"孩子把绳子缠在手上","then":"立刻纠正。缠在手上如果被卡住会受伤，一定要用握的。"},{"if":"孩子走两步就回头看","then":"正常的。可以在袋子上放个会响的东西，让他用听的就知道有没有跟上。"}],"mistakes":["绳子缠在手上或腰上——被卡住时很危险，一定要用握的。","绳子太短——袋子会打到脚跟。长度至少要一个手臂以上。","只玩推不玩拉——推拉要搭配，力量才均衡。"],"down":"减轻重量；缩短距离；用比较好拖的袋子。","up":"增加重量；加长距离；中途要转弯；或改成倒退着拖。","progress":["能拖动多重的东西。","拖的时候身体会不会后倾用力。","能拖多远不喊累。"],"outro":"推和拉是互补的两种力量。当成小货车送货的游戏，孩子会自己一趟一趟拖，力气就这样练出来了。"}' AS JSON))
WHERE `id` = 'A043';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个小提袋＋几样轻的东西'),
  `trains` = COALESCE(`trains`, '练握力和身体不歪的稳定。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一个装了轻东西的小袋子。"},{"imageUrl":null,"instruction":"让他提着走一段路。"},{"imageUrl":null,"instruction":"两只手轮流提。"},{"imageUrl":null,"instruction":"身体不要往一边歪。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '很轻、走几步'),
  `harder` = COALESCE(`harder`, '稍重，或走远一点。'),
  `tip` = COALESCE(`tip`, '重量宁可轻——姿势不歪比提得重重要。逛超市时让孩子提一小袋，就是很好的练习。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"给孩子一个小提袋，让他提着走一段路。重量宁可轻——姿势不歪比提得重重要得多。","principles":["提东西时，手指和手掌必须持续用力握住提把，这是最直接的握力训练。","握力和日后拿笔的稳定度、使用剪刀的控制力都有关。","单手提东西时，身体会被重量往那一侧拉，另一侧的核心肌群必须出力对抗。","这种对抗侧向拉力的能力，叫做侧向核心稳定。","侧向稳定不足的孩子，提东西时会整个人往一边歪，久了会影响姿势。","两只手轮流提，可以让两侧的核心平均发展。","提着走还需要维持步态稳定，是负重状态下的行走练习。","这个活动最容易融入生活——逛超市、买东西、回家提袋子都是机会。"],"prep":{"场地":"从家里到楼下、或超市到停车场的一段路，也可以在客厅走来走去。","器材":"一个小提袋＋几样轻的东西；重量抓在孩子体重的十分之一以内。","安全检查":"重量务必轻。提把要好握、不会勒手。袋子不要长到拖地绊倒。观察孩子的身体有没有明显歪斜，歪了就减轻。","大人位置":"大人走在旁边，从后方观察孩子的身体有没有歪。"},"shots":[{"name":"装袋子","say":"我们放几样轻的东西。"},{"name":"提起来","say":"用一只手提起来。"},{"name":"检查身体","say":"身体要正正的，不要歪。"},{"name":"走一段","say":"我们提到那边去。"},{"name":"换手","say":"换另外一只手提。"},{"name":"生活应用","say":"去超市也可以让他提一小袋。"}],"reactions":[{"if":"孩子身体明显往一边歪","then":"立刻减轻重量。歪着走比不提还糟，宁可空手。"},{"if":"孩子提一下就换手或放下","then":"重量太重或提把不好握。减轻重量，或换一个好握的袋子。"},{"if":"孩子只用惯用手提","then":"刻意提醒换手，两边次数尽量一样。"}],"mistakes":["重量太重——这是最常见的错误。姿势歪掉就是太重了。","只用一只手提——两手轮流，核心才会平均发展。","袋子太长拖地——会绊倒，提把长度要合适。"],"down":"减轻重量；改成双手提；缩短距离。","up":"增加一点重量；加长距离；提着上下楼梯（要更小心）；或两手各提一个。","progress":["提着走时身体会不会歪。","能提多远不换手。","两只手的表现差多少。"],"outro":"提袋子练的是握力和身体不歪的稳定。逛超市时让孩子提一小袋，就是最好的练习——记住，宁可轻。"}' AS JSON))
WHERE `id` = 'A044';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一面墙'),
  `trains` = COALESCE(`trains`, '练手臂往前推的力气（伏地挺身的简单版）。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"面对墙站好，双手撑墙、与肩同宽。"},{"imageUrl":null,"instruction":"身体往墙靠近（手肘弯）。"},{"imageUrl":null,"instruction":"再推回来（手肘直）。"},{"imageUrl":null,"instruction":"做八到十次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '站近一点'),
  `harder` = COALESCE(`harder`, '站远一点，或改成撑在矮桌上做。'),
  `tip` = COALESCE(`tip`, '靠墙做比在地板上做伏地挺身安全得多，孩子也做得起来。能做二十次以上，再考虑难一点的版本。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"面对墙撑着，身体往前靠再推回来。这是伏地挺身的简单版，靠墙做安全得多，孩子也做得起来。","principles":["这个动作练的是胸大肌、三头肌和肩膀前侧，也就是「往前推」的力量。","推的力量对孩子来说用在推门、推玩具车、体育课的推撑动作上。","身体要维持一直线，核心必须全程收紧，所以也在练核心。","手掌撑在墙上承重，对手腕的稳定度有帮助，这和握笔的稳定有关。","靠墙做的负重比地板上的伏地挺身轻很多，成功率高。","角度可以调整——站得离墙越远，负重越大，难度越高。","这是闭锁链运动，手固定在墙上，对肩关节比较安全。","能做二十次以上再考虑进阶到斜面或地板版本。"],"prep":{"场地":"一面结实的墙，前方留出空间。避开有挂画或镜子的墙。","器材":"一面墙就够了。","安全检查":"确认墙是结实的。脚下要防滑，脚往后滑是最常见的意外。手腕不舒服就停。","大人位置":"大人在旁边一起做，或从侧面帮孩子看姿势。"},"shots":[{"name":"站好位置","say":"面对墙，手撑在墙上，与肩同宽。"},{"name":"身体一直线","say":"身体要成一直线，屁股不要翘。"},{"name":"往墙靠近","say":"手肘弯，慢慢靠近墙。"},{"name":"推回来","say":"推！"},{"name":"数次数","say":"一、二、三⋯⋯做十次。"},{"name":"加难度","say":"脚站远一点就更难了。"}],"reactions":[{"if":"孩子的屁股翘起来或塌下去","then":"提醒「肚子收紧，身体成一直线」。可以让他先靠着墙站好感觉直线的位置。"},{"if":"孩子只弯脖子不弯手肘","then":"常见的代偿。提醒「是身体整个靠过去，不是头靠过去」。"},{"if":"孩子说手腕痛","then":"停下来。可以改成握拳撑墙（减少手腕角度），或做推墙比赛那类静态动作。"}],"mistakes":["脚站太远——刚开始站近一点（约半步），负重小、姿势才做得对。","只做头的动作——要整个身体一直线移动，不是脖子往前伸。","脚下打滑——地面一定要防滑，这是最常见的意外来源。"],"down":"脚站得离墙近一点；只做五次；手撑高一点（负重更小）。","up":"脚往后站远；做二十次；改成撑在桌沿或沙发（角度更斜）；最后才是地板版本。","progress":["能连续做几次而姿势不垮。","脚能站多远还维持得住直线。","手肘有没有真的弯下去。"],"outro":"靠墙推起来是伏地挺身最安全的入门版。能连续做二十次姿势不垮，再考虑往下一阶进阶。"}' AS JSON))
WHERE `id` = 'A045';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个球或抱枕'),
  `trains` = COALESCE(`trains`, '练腿的力气，抱着东西还能增加难度。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"双手抱一个球在胸前。"},{"imageUrl":null,"instruction":"屁股往后坐、蹲下去。"},{"imageUrl":null,"instruction":"再站起来。"},{"imageUrl":null,"instruction":"做八到十次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '不抱球、只做蹲站'),
  `harder` = COALESCE(`harder`, '抱大一点的球，或次数加倍。'),
  `tip` = COALESCE(`tip`, '蹲的时候「屁股往后坐」，像要坐椅子一样——姿势对了才练得到腿。膝盖不要超过脚尖太多。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"抱着球蹲下再站起来。蹲的时候「屁股往后坐」，像要坐椅子一样——姿势对了才练得到腿。","principles":["深蹲是练下肢最有效的动作，用到大腿前侧、后侧和臀部。","腿部力量决定孩子能不能久站、久走、上下楼梯不用扶。","抱着球在胸前会让重心往前移，核心必须更用力才能稳住。","这个变化叫高脚杯深蹲，好处是姿势比较容易做对。","「屁股往后坐」的动作，能让力量集中在臀部和大腿而不是膝盖。","如果膝盖一直往前顶，压力会集中在膝关节，练不到该练的地方。","蹲下的深度不用很深，蹲到大腿约水平就很够了。","这个动作和生活中的坐下、起身、捡东西是同一个模式。"],"prep":{"场地":"客厅空地，地面防滑，旁边可以放一张椅子当参考。","器材":"一个球或抱枕；装了东西的袋子也可以。","安全检查":"膝盖不舒服就停。不要蹲到底再弹起来。地面防滑。","大人位置":"大人在旁边一起做，或从侧面看孩子的姿势。"},"shots":[{"name":"抱好球","say":"双手抱着球，放在胸前。"},{"name":"屁股往后坐","say":"屁股往后坐，像要坐椅子。"},{"name":"蹲下","say":"慢慢蹲下去。"},{"name":"站起来","say":"用腿的力气站起来。"},{"name":"用椅子提示","say":"后面放张椅子，屁股碰到就站起来。"},{"name":"数次数","say":"我们做十次。"}],"reactions":[{"if":"孩子蹲下时膝盖一直往前顶","then":"在他身后放一张椅子，让他「屁股往后碰椅子」。这个提示最有效。"},{"if":"孩子蹲下时脚跟离地","then":"脚踝比较紧。在脚跟下垫一本薄书，或先做脚踝伸展。"},{"if":"孩子蹲到一半站不起来","then":"不用蹲那么深。蹲到一半就站起来，力气够了再慢慢加深。"}],"mistakes":["膝盖往前顶——压力会跑到膝关节，这是最常见的错误。用椅子提示最好改。","蹲太深——蹲到大腿水平就够，不用蹲到底。","一次做太多——十次就够，姿势垮掉就该停。"],"down":"不抱球；蹲浅一点；屁股真的坐到椅子上再站起来。","up":"抱重一点的东西；蹲深一点；蹲下停三秒再站起；或单脚辅助蹲。","progress":["能连续做几次姿势不垮。","膝盖有没有往前顶。","脚跟能不能贴地。"],"outro":"蹲下站起来是生活里最常用的动作。记住一句话——屁股往后坐，像要坐椅子一样，姿势就对了。"}' AS JSON))
WHERE `id` = 'A046';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '一个球'),
  `trains` = COALESCE(`trains`, '练肩膀的力气。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"双手把球举过头顶。"},{"imageUrl":null,"instruction":"传给旁边或后面的人。"},{"imageUrl":null,"instruction":"接的人再举高传下去。"},{"imageUrl":null,"instruction":"做十次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '球轻、次数少'),
  `harder` = COALESCE(`harder`, '球重一点，或背对背从头顶传。'),
  `tip` = COALESCE(`tip`, '肩膀的力气对写字、穿衣、拿高处的东西都很重要，却很容易被忽略。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"双手把球举过头顶传给后面的人。肩膀的力气对写字、穿衣、拿高处的东西都很重要，却很容易被忽略。","principles":["把手举过头顶需要肩膀的三角肌和上斜方肌用力。","肩膀的力量和稳定度，是手部精细动作的基础——近端稳定，远端才灵活。","肩膀不稳的孩子，写字时手臂会晃、容易累、字会越写越大或越写越歪。","举过头顶的动作还需要肩关节有足够的活动度。","现代孩子很少做过头顶的动作，这个活动度常常不够。","双手同时举起传球，是双侧对称协调的练习。","球有重量，举起来时核心必须稳住，避免腰往前凸。","传给后面的人还需要身体旋转，顺便练到躯干的转动。"],"prep":{"场地":"客厅空地，两人前后站或围成圈。","器材":"一个球；篮球太重，用轻一点的球或抱枕最好。","安全检查":"球别太重。举过头顶时注意天花板高度和吊灯。腰不舒服就停。","大人位置":"大人站在孩子后面接球，或围成圈全家一起传。"},"shots":[{"name":"举起来","say":"双手把球举过头顶。"},{"name":"检查腰部","say":"肚子收紧，腰不要往前凸。"},{"name":"传给后面","say":"传给后面的人！"},{"name":"接住","say":"接到了。"},{"name":"围圈传","say":"我们围成圈，一直传下去。"},{"name":"计数","say":"看能传几次不掉！"}],"reactions":[{"if":"孩子手举不直","then":"球太重，换轻一点的。或先练空手举高，熟了再拿球。"},{"if":"孩子举球时腰往前凸","then":"提醒「肚子收紧」。也可以让他背靠着墙做，腰就不会反弓。"},{"if":"孩子传球时会掉","then":"距离缩短，或用大一点好抓的球。"}],"mistakes":["球太重——举不动会用腰代偿，反而不好。轻球或抱枕最适合。","忽略腰的姿势——举高时腰容易反弓，要提醒收腹。","天花板太低或有吊灯——先看好空间再玩。"],"down":"用抱枕代替球；不举那么高；只做举起放下不传球。","up":"用重一点的球；围成圈连续传；加上「传到后面再传回来」；或边走边传。","progress":["手臂能不能完全举直。","举高时腰会不会反弓。","能连续传几次不掉。"],"outro":"肩膀的力气常被忽略，但它是写字稳不稳的基础。举高高传球全家一起玩，肩膀和核心一起练。"}' AS JSON))
WHERE `id` = 'A047';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块地板'),
  `trains` = COALESCE(`trains`, '手脚着地、膝盖离地往前走，练手臂和肚子。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"手掌和脚掌着地，屁股抬高。"},{"imageUrl":null,"instruction":"像小熊一样往前走。"},{"imageUrl":null,"instruction":"走三五步就休息。"},{"imageUrl":null,"instruction":"也可以试试倒退走。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '走三步'),
  `harder` = COALESCE(`harder`, '走十步以上，或倒着走。'),
  `tip` = COALESCE(`tip`, '这个动作很累——走几步就有效果，不用勉强走远。手臂有力的孩子，写字才撑得久。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"手掌和脚掌着地、屁股抬高，像小熊一样往前走。这个动作很累——走几步就有效果，不用勉强走远。","principles":["熊爬时膝盖离地，手臂要承受比一般爬行更多的重量。","手臂承重直接练到肩膀的稳定度，这是写字耐力的基础。","为了不让肚子垮下去或屁股乱晃，核心肌群必须全程收紧。","手脚交替前进用到的是跨侧协调，和爬行是同一套模式。","手掌撑地时手腕呈伸展姿势，对手腕的稳定很有帮助。","这是全身闭锁链运动，手脚都固定在地上出力，对关节很安全。","大量的关节承重提供强烈的本体觉输入，安定效果很好。","这个动作强度高，走三五步就会累，这就是它有效的证据。"],"prep":{"场地":"客厅铺垫子或在地毯上，清出三到五米。","器材":"一块地板或垫子。","安全检查":"手腕不舒服就停。地面要防滑，手掌打滑很危险。孩子手腕受过伤要先问治疗师。","大人位置":"大人在旁边一起爬，或走在侧边看姿势。"},"shots":[{"name":"起始姿势","say":"手掌和脚掌着地，屁股抬高。"},{"name":"膝盖离地","say":"膝盖不能碰到地板喔。"},{"name":"手脚交替","say":"一只手、一只脚，交替往前。"},{"name":"走三五步","say":"走五步就可以休息了。"},{"name":"倒退走","say":"这次倒着走试试看！"},{"name":"比赛","say":"看谁先爬到那边！"}],"reactions":[{"if":"孩子膝盖一直碰地","then":"代表手臂和核心力气不够。先练「维持熊爬姿势三秒不动」，力量够了再走。"},{"if":"孩子走两步就趴下来","then":"很正常，这个动作真的很累。走两步就够了，多做几趟。"},{"if":"孩子说手腕痛","then":"立刻停。可以改成握拳撑地，或改做其他不压手腕的活动。"}],"mistakes":["要求走太远——三五步就很有效果了，走太远姿势会垮掉。","膝盖碰地还继续——膝盖离地才是熊爬，碰地就变成爬行了。","在光滑地板上做——手掌打滑很危险，一定要铺垫子或在地毯上。"],"down":"先练维持姿势三秒；只走两步；在垫子上做减少手腕压力。","up":"加长距离；倒退走；侧着走；或边走边推一颗球。","progress":["能连续走几步而膝盖不碰地。","维持姿势能撑几秒。","走完之后多久不喊手酸。"],"outro":"熊爬是练手臂和核心最有效的动作之一，也最累。走五步就有效果——重质不重量。"}' AS JSON))
WHERE `id` = 'A048';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块垫子或地毯'),
  `trains` = COALESCE(`trains`, '蹲着往前跳，练腿的爆发力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"蹲下，双手放膝盖上。"},{"imageUrl":null,"instruction":"像青蛙一样往前跳。"},{"imageUrl":null,"instruction":"跳三五下休息。"},{"imageUrl":null,"instruction":"配上「呱呱」的叫声更好玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跳两三下'),
  `harder` = COALESCE(`harder`, '跳八到十下，或跳远一点。'),
  `tip` = COALESCE(`tip`, '跳几下腿就酸了，这就是力量训练。落地要屈膝缓冲，在有弹性的地面上玩。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十（跳跃与落地）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"蹲下，双手放膝盖上，像青蛙一样往前跳。跳几下腿就酸了——这就是力量训练。","principles":["青蛙跳是从深蹲姿势爆发跳起，练的是下肢的爆发力。","爆发力和一般的肌力不同，它强调的是「在短时间内产生最大力量」。","跑步起跑、跳跃、快速改变方向都需要爆发力。","起跳时双腿要同时用力蹬地，是很好的双侧对称训练。","落地时膝盖要弯曲缓冲，这是保护关节最重要的动作。","蹲姿本身就需要脚踝和髋关节有足够的活动度。","连续跳几下心跳就会上来，也是很有效率的心肺训练。","配上「呱呱」的叫声，孩子会玩得更投入，运动量自然上去。"],"prep":{"场地":"垫子、地毯或草地——一定要有弹性的地面。","器材":"一块垫子或地毯。","安全检查":"这个动作对膝盖有冲击，一定要在有弹性的地面做。次数不要多。膝盖或脚踝不舒服就停。体重较重的孩子要减少次数。","大人位置":"大人在旁边一起跳，示范落地要轻。"},"shots":[{"name":"蹲好姿势","say":"蹲下来，双手放在膝盖上。"},{"name":"蓄力","say":"准备——"},{"name":"跳出去","say":"呱！"},{"name":"落地缓冲","say":"落地的时候膝盖弯一弯，轻轻的。"},{"name":"连续跳","say":"跳三下就休息。"},{"name":"比远","say":"看谁跳得远！"}],"reactions":[{"if":"孩子跳的时候是一只脚先离地","then":"先练原地双脚跳，感觉双脚同时用力。也可以牵着双手一起跳。"},{"if":"孩子落地很大声、腿是直的","then":"提醒「像青蛙一样轻轻落地，膝盖弯一弯」。落地技巧比跳得远重要。"},{"if":"孩子跳几下就说腿酸","then":"这很正常，代表有练到。休息一下再跳，不要连续跳太多。"}],"mistakes":["在硬地板上跳——对膝盖和脚踝的冲击太大，一定要在垫子或草地上。","一次跳太多下——三到五下就休息，这是高强度动作。","只看跳得远不管落地——落地会不会缓冲才是重点。"],"down":"只做原地蹲跳不往前；跳的距离缩短；牵着双手一起跳。","up":"跳得更远；连续跳五下；跳过小障碍；或跳一下转个方向。","progress":["能跳多远。","落地时膝盖有没有弯曲缓冲。","能连续跳几下而姿势不垮。"],"outro":"青蛙跳练的是腿的爆发力，跳几下就很有效。记住两件事——在有弹性的地面上跳，落地要轻。"}' AS JSON))
WHERE `id` = 'A049';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '抹布'),
  `trains` = COALESCE(`trains`, '用擦的动作练手臂力气，顺便做家务。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一块抹布。"},{"imageUrl":null,"instruction":"让他擦桌子、擦窗户，画大圈用力擦。"},{"imageUrl":null,"instruction":"擦完一起看成果。"},{"imageUrl":null,"instruction":"郑重道谢。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '擦一小块'),
  `harder` = COALESCE(`harder`, '擦大范围，或擦比较用力才干净的地方。'),
  `tip` = COALESCE(`tip`, '家务是最实用的力量训练——孩子既长了力气，也学会照顾环境、被需要的感觉很好。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"给孩子一块抹布，让他画大圈用力擦。家务是最实用的力量训练——既长了力气，也学会照顾环境。","principles":["擦的动作需要手臂持续施压并且来回移动，是很好的上肢肌耐力训练。","画大圈的动作用到的是整个肩膀，而不只是手腕。","肩膀带动的大动作，是日后写字这类小动作的基础——先练大再练小。","擦窗户时手要举高，还多了一个过头顶的动作和肩膀活动度的练习。","手掌压在抹布上持续用力，是手部的本体觉输入。","要把脏的地方擦干净，孩子必须看清楚哪里还没擦到，这练到了视觉搜寻。","来回擦拭的动作还需要跨过身体中线，对左右协调有帮助。","做家务带来的「我有用」的感觉，对自我价值感的建立很有帮助。"],"prep":{"场地":"餐桌、茶几、落地窗——任何需要擦的平面。","器材":"抹布；小朋友用的抹布拧干一点比较好握。","安全检查":"不要站在椅子上擦高处。清洁剂要用安全的或只用清水。窗户玻璃要确认稳固。","大人位置":"大人一起擦，示范画大圈的动作。"},"shots":[{"name":"拧抹布","say":"先把抹布拧干。"},{"name":"画大圈","say":"用力画大圈圈擦。"},{"name":"用力压","say":"要压下去才擦得干净。"},{"name":"擦窗户","say":"擦窗户要举高高。"},{"name":"检查成果","say":"看看哪里还没擦到？"},{"name":"道谢","say":"谢谢你，桌子好干净！"}],"reactions":[{"if":"孩子只用手腕小幅度擦","then":"示范「画大圈圈」，或在桌上用手指画一个大圈让他跟着擦。"},{"if":"孩子擦一下就说累","then":"正常的，这个动作很耗力气。缩小范围，擦一小块就好。"},{"if":"孩子擦不干净","then":"别急着重擦。先谢谢他，再一起看看哪里可以再擦一次。"}],"mistakes":["嫌孩子擦不干净就自己重做——这会让他觉得帮忙没意义。先道谢，再一起补。","让孩子站在椅子上擦高处——很危险，高处让大人擦。","抹布太湿——会滴水也不好握，拧干一点。"],"down":"只擦一小块；抹布小一点好握；只擦水平的桌面不擦窗。","up":"擦更大的面积；擦窗户（要举高）；规定要画大圈；或计时挑战。","progress":["是用肩膀画大圈还是只用手腕。","能连续擦多久。","能不能自己发现没擦到的地方。"],"outro":"擦桌子是最实用的力量训练。孩子长了力气，也得到「我有用」的感觉——记得擦完要郑重道谢。"}' AS JSON))
WHERE `id` = 'A050';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '小拖把或湿抹布'),
  `trains` = COALESCE(`trains`, '用推拉的动作练全身力气。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一个适合他身高的小拖把。"},{"imageUrl":null,"instruction":"让他拖一小块地。"},{"imageUrl":null,"instruction":"前后推拉要用力。"},{"imageUrl":null,"instruction":"做完一起欣赏干净的地板。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '拖一小块'),
  `harder` = COALESCE(`harder`, '拖一整个房间。'),
  `tip` = COALESCE(`tip`, '工具大小要适合孩子——太长的拖把他使不上力，也容易撞到东西。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"给孩子一个适合他身高的小拖把，让他拖一小块地。工具大小要合适——太长的拖把他使不上力。","principles":["拖地的推拉动作，同时用到手臂的推力和拉力。","身体要跟着拖把前后移动，重心不断转换，是全身性的动作。","双手要一前一后握住拖把杆，这是双手不对称的协调。","不对称握持还需要两只手做不同的事——一只主要出力、一只负责导向。","要把地拖干净，孩子必须注意哪里拖过、哪里还没拖，这是空间记忆。","拖把有重量和阻力，是持续的负荷训练。","身体要维持稳定不被拖把带着晃，核心也在工作。","工具的长度很关键——太长使不上力，太短要弯腰，都会让动作变形。"],"prep":{"场地":"一小块地板，先把地上的东西收走。","器材":"小拖把或湿抹布；拖把杆的高度约到孩子的胸口最合适。","安全检查":"地板湿了会滑，这是最主要的风险。范围要小，拖完马上擦干或提醒不要跑。拖把杆别太长，转身时会打到人或东西。","大人位置":"大人在旁边，负责换水和注意地板湿滑。"},"shots":[{"name":"选对工具","say":"拖把要选适合他高度的。"},{"name":"握把姿势","say":"两只手一前一后握好。"},{"name":"前后推拉","say":"往前推、往后拉，要用力。"},{"name":"有系统地拖","say":"从这边开始，一条一条拖。"},{"name":"检查","say":"看看哪里还没拖到？"},{"name":"欣赏成果","say":"地板好干净！"}],"reactions":[{"if":"孩子使不上力","then":"检查拖把高度。太长的话换短的，或让他握在杆子中段。"},{"if":"孩子乱拖一通","then":"教他「一条一条来」，或在地上贴条胶带当分区参考。"},{"if":"孩子拖两下就不想做","then":"范围缩小到一小块（一块地砖就好），做完立刻道谢。"}],"mistakes":["拖把太长——这是最常见的问题，孩子使不上力也容易撞到东西。","范围太大——一小块就好，太大会累也会失去兴趣。","地板湿了没提醒——湿地板很滑，要提醒孩子不要跑。"],"down":"改用湿抹布跪着擦；范围缩到一块地砖；握在杆子中段。","up":"扩大范围；要求拖得有顺序不重复；或加上先扫再拖的完整流程。","progress":["能不能有系统地拖而不是乱拖。","能拖多大的范围。","会不会自己检查哪里没拖到。"],"outro":"拖地练的是推拉的力量和双手的不对称协调。工具选对高度，孩子才使得上力，也才做得开心。"}' AS JSON))
WHERE `id` = 'A051';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '大积木或纸箱'),
  `trains` = COALESCE(`trains`, '一边搬一边盖，力气和创造力一起练。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把积木放在房间一端。"},{"imageUrl":null,"instruction":"让孩子一次搬一块到另一端盖房子。"},{"imageUrl":null,"instruction":"要蹲下拿、站起来走。"},{"imageUrl":null,"instruction":"盖好了一起欣赏。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '轻积木、盖五块'),
  `harder` = COALESCE(`harder`, '重一点，或盖十五块以上。'),
  `tip` = COALESCE(`tip`, '每搬一块就是一次蹲站加负重走路——孩子专心在盖房子，身体却做了几十次训练。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把积木放在房间一端，让孩子一次搬一块到另一端盖房子。孩子专心在盖房子，身体却做了几十次蹲站和负重走路。","principles":["每搬一块积木，孩子就要蹲下拿、站起来、走过去、再蹲下放。","这一趟下来就是两次深蹲加一次负重行走。","搬十块就是二十次深蹲，但孩子完全不觉得自己在做运动。","把训练藏在有意义的任务里，是最高明的做法——动机来自任务本身。","抱着积木走路时重心会改变，身体要重新找平衡。","盖房子需要规划：先放哪一块、怎么堆才稳，这是建构和空间规划。","来回走动本身就是很好的心肺活动，累积下来运动量不小。","完成一个作品的成就感，会让孩子想再搬下一趟。"],"prep":{"场地":"房间两端，中间清出走道。距离三到五米。","器材":"大积木或纸箱；枕头、装了东西的小盒子都可以。","安全检查":"积木不要太重（孩子体重的十分之一以内）。走道清空。堆高的积木要注意会不会倒下来砸到。","大人位置":"大人可以当「工地监工」，或一起搬一起盖。"},"shots":[{"name":"设定任务","say":"积木在那边，我们要把它搬过来盖房子。"},{"name":"蹲下拿","say":"蹲下来拿，用腿的力气。"},{"name":"抱着走","say":"抱好，走过来。"},{"name":"蹲下放","say":"轻轻放下来。"},{"name":"来回几趟","say":"一趟、两趟、三趟⋯⋯"},{"name":"房子盖好","say":"房子盖好了！"}],"reactions":[{"if":"孩子一次想搬很多块","then":"规定「一次只能搬一块」——这样来回次数才多，运动量才够。"},{"if":"孩子弯腰去搬","then":"示范「蹲下来，用腿站起来」。这个姿势习惯要从小建立。"},{"if":"孩子搬两趟就不想搬了","then":"把目标说清楚（「搬五块就可以盖好了」），有终点比较撑得住。"}],"mistakes":["让孩子一次搬很多——搬得少、走得多，运动量才大。","积木太重——蹲站的姿势会跑掉，宁可轻一点。","大人帮他搬——搬运本身才是训练，盖房子只是动机。"],"down":"距离缩短；积木轻一点；只搬五块。","up":"距离加长；积木重一点；中途要绕过障碍；或规定要照颜色顺序搬。","progress":["能来回搬几趟不喊累。","搬的时候是蹲下还是弯腰。","盖出来的结构有没有越来越复杂。"],"outro":"孩子以为在盖房子，其实做了几十次蹲站和负重走路。把训练藏在任务里，这是最不费力的做法。"}' AS JSON))
WHERE `id` = 'A052';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '5–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一条跳绳'),
  `trains` = COALESCE(`trains`, '练手脚配合和体力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一步：绳子放地上，练双脚跳过去。"},{"imageUrl":null,"instruction":"第二步：大人慢慢摇绳，孩子跨过。"},{"imageUrl":null,"instruction":"第三步：自己摇绳，绳到脚前时跳过。"},{"imageUrl":null,"instruction":"一步一步来，不急着连续跳。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跳过地上的绳子'),
  `harder` = COALESCE(`harder`, '连续跳三到五下。'),
  `tip` = COALESCE(`tip`, '跳绳通常要五六岁才跳得连续——跳不起来很正常，先把分解动作练熟就好。绳长：踩住绳子中间，握把到腋下刚好。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十（跳跃与落地）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"跳绳通常要五六岁才跳得连续。跳不起来很正常——先把分解动作练熟就好，这一集教的是三个步骤。","principles":["跳绳是很复杂的动作，需要手摇绳和脚跳跃在时间上精准配合。","这种手脚在不同节奏下的配合，是相当高阶的协调能力。","孩子必须预测绳子什么时候到脚前，提前起跳，这是时间预测。","连续跳还需要维持稳定的节奏，节奏一乱就会绊到。","跳跃本身是很好的心肺和下肢训练，跳绳的运动强度很高。","手腕要用小幅度快速转动来摇绳，而不是整个手臂在挥。","把动作拆成三步分开练，是学习复杂动作最有效的方法。","绳长的检查有个标准：踩住绳子中间，握把拉起来到腋下刚好。"],"prep":{"场地":"户外或室内挑高够的地方，头上和四周都要有空间。地面有弹性最好。","器材":"一条跳绳；长度要调整过。","安全检查":"绳子会打到人，四周一定要清空。地面太硬对膝盖不好，草地或有弹性的地面最佳。跳绳强度高，别一次跳太久。","大人位置":"大人先示范，第二步时负责慢慢摇绳。"},"shots":[{"name":"量绳长","say":"踩住绳子中间，握把到腋下刚好。"},{"name":"第一步","say":"绳子放地上，练双脚跳过去。"},{"name":"第二步","say":"我慢慢摇，你跨过去。"},{"name":"第三步","say":"自己摇，绳子到脚前就跳。"},{"name":"手腕动作","say":"用手腕转，不是整只手臂挥。"},{"name":"跳成功","say":"跳过去了！"}],"reactions":[{"if":"孩子完全跳不起来","then":"退回第一步或第二步，多练几天。跳绳急不得，分解动作熟了自然会。"},{"if":"孩子跳得太高、很快就累","then":"提醒「跳一点点就好，绳子过得去就行」。跳太高很耗体力。"},{"if":"孩子用整只手臂在挥绳","then":"示范手腕转动的动作。可以让他先不拿绳、只练手腕画小圈。"}],"mistakes":["绳长没调整——太长会绊脚、太短会打到头，这是最常见的问题。","直接要求连续跳——一定要分三步走，跳不起来会挫折。","在硬地板上跳很久——对膝盖负担大，要选有弹性的地面。"],"down":"退回第一步（绳子放地上跳过）；第二步由大人摇绳；改成单脚跨过。","up":"连续跳五下、十下；加快速度；单脚跳；或两人一起跳。","progress":["目前在三个步骤的哪一步。","能连续跳几下。","摇绳是用手腕还是整只手臂。"],"outro":"跳绳跳不起来很正常，五六岁才连续得起来。把三个分解步骤练熟，剩下的时间会帮你完成。"}' AS JSON))
WHERE `id` = 'A053';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '一块地板'),
  `trains` = COALESCE(`trains`, '用各种动物走法把全身力气练一遍。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"熊爬、螃蟹走、青蛙跳、兔子跳、毛毛虫爬。"},{"imageUrl":null,"instruction":"每种走一小段。"},{"imageUrl":null,"instruction":"轮流当动物、互相猜。"},{"imageUrl":null,"instruction":"全家一起做。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每种走三五步'),
  `harder` = COALESCE(`harder`, '每种走远一点，或连续做完五种。'),
  `tip` = COALESCE(`tip`, '「动物运动会」是最受欢迎的力量训练——孩子笑着做完，全身都练到了。累了就休息。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"熊爬、螃蟹走、青蛙跳、兔子跳、毛毛虫爬——把这些串起来办一场动物运动会。孩子笑着做完，全身都练到了。","principles":["每种动物走法练到的肌群都不一样，串起来就是全身训练。","熊爬练手臂和核心，螃蟹走练肩膀后侧和臀部，这两个部位现代孩子普遍偏弱。","青蛙跳和兔子跳练下肢爆发力，毛毛虫爬练核心和肩膀的连动。","不同部位轮流工作，可以在不过度疲劳的情况下累积总运动量。","模仿动物需要先看懂动作再用身体做出来，这是动作计划能力。","轮流当动物、互相猜，还加入了模仿、观察和表达。","这些全是闭锁链动作，手脚固定在地上出力，对关节的稳定很有帮助。","把训练包装成运动会，孩子的配合度和持续时间都会大幅提高。"],"prep":{"场地":"客厅或户外，清出三到五米的通道，地面防滑铺软。","器材":"一块地板或垫子；可以准备动物图卡抽签。","安全检查":"螃蟹走要注意手腕，觉得痛就停。青蛙跳要在有弹性的地面。每种动物做一小段就换，避免过度疲劳。","大人位置":"大人一起做，而且要做得夸张搞笑。"},"shots":[{"name":"抽动物卡","say":"今天第一个是——熊！"},{"name":"熊爬","say":"膝盖离地，屁股翘高。"},{"name":"螃蟹走","say":"肚子朝上，横着走！"},{"name":"青蛙跳","say":"呱——跳！"},{"name":"毛毛虫","say":"手往前走，脚慢慢跟上。"},{"name":"全家接力","say":"我们来接力比赛！"}],"reactions":[{"if":"孩子只想做同一种动物","then":"先顺着他做熟一种，再用抽卡的方式引入新的。"},{"if":"孩子螃蟹走屁股掉下来","then":"先练桥式（躺着抬屁股），力量够了再练螃蟹走。"},{"if":"孩子做几种就累了","then":"很正常，这是全身运动。做三种就休息，明天换另外三种。"}],"mistakes":["一次做太多种——三种就很够，做太多会累到失去兴趣。","每种做太长——每种走三五步就换，轮流才不会过度疲劳。","大人在旁边看——大人一起做而且做得夸张，孩子才玩得开。"],"down":"只做两三种；每种距离缩短；选比较简单的（兔子跳、毛毛虫）。","up":"加入更多动物；加长距离；两种动物交替走；或加上「木头人」的暂停指令。","progress":["能做出几种不同的动物走法。","每种能走多远而姿势不垮。","能不能自己发明新的动物走法。"],"outro":"动物运动会是最受欢迎的力量训练。每种做一小段、三种就休息，孩子笑着做完，全身都练到了。"}' AS JSON))
WHERE `id` = 'A054';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '垫子、球、矮台阶'),
  `trains` = COALESCE(`trains`, '几个动作轮流做，练全身也练耐力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一站：蹲站十次。"},{"imageUrl":null,"instruction":"第二站：靠墙推起来十次。"},{"imageUrl":null,"instruction":"第三站：熊爬五步。"},{"imageUrl":null,"instruction":"第四站：台阶上下十次。"},{"imageUrl":null,"instruction":"做完休息一分钟，再来一轮。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每站减半、只做一轮'),
  `harder` = COALESCE(`harder`, '次数加倍，或做三轮。'),
  `tip` = COALESCE(`tip`, '不同部位轮流工作，既有效率又不会太累。姿势垮掉就该停——做对比做多重要。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"四个站轮流做：蹲站、推墙、熊爬、上下台阶。不同部位轮流工作，既有效率又不会太累。","principles":["这种轮流做不同动作的方式，叫循环训练。","循环训练的好处是：某个部位在休息时，另一个部位在工作，总运动量可以拉高。","四个站分别练下肢、上肢、核心和心肺，涵盖面完整。","每站之间的转换也是活动，不会有完全停下来的空档。","固定次数（十次）让孩子知道「做完就好」，比「做到累」更容易接受。","做完一轮休息一分钟再来一轮，这个结构接近真正的体能训练。","孩子可以清楚看到自己做了几轮，成就感很具体。","姿势垮掉就该停——做对比做多重要，这是所有力量训练的铁律。"],"prep":{"场地":"客厅规划四个区域，中间留出走动空间。","器材":"垫子、球、矮台阶（或楼梯最下面一阶）。","安全检查":"每站的安全要求照该活动的原则。姿势垮掉就停。孩子喊累要让他休息，不要求「撑完」。","大人位置":"大人当关主，负责计数和看姿势。"},"shots":[{"name":"介绍四站","say":"今天有四站，每站十次。"},{"name":"第一站","say":"第一站：蹲站十次。"},{"name":"第二站","say":"第二站：靠墙推起来十次。"},{"name":"第三站","say":"第三站：熊爬五步。"},{"name":"第四站","say":"第四站：台阶上下十次。"},{"name":"休息再来","say":"休息一分钟，我们再来一轮！"}],"reactions":[{"if":"孩子做到一半姿势垮了","then":"立刻停下来休息。姿势垮掉还继续做，练错了也容易受伤。"},{"if":"孩子觉得四站太多","then":"减到两三站。或每站减到五次。"},{"if":"孩子想跳过不喜欢的那一站","then":"可以换成同部位的其他动作，但不要整个跳过。"}],"mistakes":["追求次数不看姿势——姿势垮了就该停，这是最重要的原则。","中间不休息——每轮之间要休息一分钟，不然后面的姿势一定会垮。","一次做太多轮——两轮就很够了。"],"down":"减到两站；每站五次；只做一轮。","up":"加到五站；每站十五次；做三轮；或加上计时。","progress":["能做几轮姿势还维持得住。","哪一站最快垮掉（代表该部位比较弱）。","休息后恢复的速度。"],"outro":"四个站轮流做，不同部位交替工作，效率高又不会太累。记住一句话——姿势垮掉就该停，做对比做多重要。"}' AS JSON))
WHERE `id` = 'A055';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '每天出门走一段，累积体力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"每天带孩子出门走走。"},{"imageUrl":null,"instruction":"能自己走的路段就别抱、别坐推车。"},{"imageUrl":null,"instruction":"路上聊天、看风景、捡树叶。"},{"imageUrl":null,"instruction":"距离慢慢加长。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '走十分钟'),
  `harder` = COALESCE(`harder`, '走半小时，或走有坡的路。'),
  `tip` = COALESCE(`tip`, '孩子的体力是靠日复一日走出来的，不是靠一周一次的课。每天多走的几百步，累积起来差很多。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十五（体能耐力与户外生活应用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子的体力是靠日复一日走出来的，不是靠一周一次的课。每天多走的几百步，累积起来差很多。","principles":["心肺耐力的建立需要持续、规律的活动，而不是偶尔的高强度运动。","走路是最容易持续、最不需要器材的有氧活动。","每天多走几百步，一年累积下来就是很可观的运动量。","户外走路时地面不完全平整，脚踝和平衡系统一直在工作。","阳光照射对钙质吸收和睡眠节律都有帮助。","户外的视野开阔，眼睛看远处对视力发展有好处。","走路时的亲子对话，是很自然的语言输入机会。","能自己走的路段就别抱、别坐推车——这是最关键的一句话。"],"prep":{"场地":"社区、公园、上学的路上——任何安全的户外路线。","器材":"不需要任何东西；水壶和帽子建议带着。","安全检查":"注意交通安全，靠边走、牵好手。天气太热要避开正午、补充水分。孩子真的累了要休息，不要勉强。","大人位置":"大人配合孩子的速度走，不要一直催。"},"shots":[{"name":"出门","say":"我们今天走路去。"},{"name":"边走边聊","say":"你看，那边有什么？"},{"name":"捡树叶","say":"我们捡几片叶子回家。"},{"name":"不平的路面","say":"这里有点不平，慢慢走。"},{"name":"累了休息","say":"累了我们坐一下。"},{"name":"记录距离","say":"今天走了三百步！"}],"reactions":[{"if":"孩子走一点就要抱","then":"不要立刻抱。可以说「再走到那棵树就休息」，给一个近的目标。"},{"if":"孩子觉得走路很无聊","then":"加入任务：找红色的东西、数几只狗、捡不同的叶子。有任务就不无聊了。"},{"if":"孩子真的累了","then":"该休息就休息，该抱就抱。判断标准是「真的累」还是「不想走」，前者要尊重。"}],"mistakes":["一喊累就抱起来——先给一个近的目标，试着让他自己走完。","一直催「快一点」——配合他的速度，走路的目的是累积不是赶路。","只在假日走很久——每天走一点，比一周走一次有效得多。"],"down":"缩短距离；中间多休息几次；分段走（走一段坐一段）。","up":"加长距离；走有坡度的路线；带着背包走；或设定每天的步数目标。","progress":["每天能走多远不喊累。","要求被抱的频率有没有减少。","走完之后的恢复速度。"],"outro":"体力是每天累积出来的。能自己走的路段就别抱、别坐推车——这一句话，就是这一集的全部重点。"}' AS JSON))
WHERE `id` = 'A056';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '社区的游乐场'),
  `trains` = COALESCE(`trains`, '爬、攀、荡、滑，全身能力一次练齐。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子自由玩各项设施。"},{"imageUrl":null,"instruction":"攀爬架、溜滑梯、荡秋千都试试。"},{"imageUrl":null,"instruction":"大人在旁保护但不代劳。"},{"imageUrl":null,"instruction":"鼓励他试试没玩过的。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '玩熟悉的低矮设施'),
  `harder` = COALESCE(`harder`, '挑战攀爬架等需要力气的设施。'),
  `tip` = COALESCE(`tip`, '游乐场是最好的健身房——完全免费，而且孩子自己会玩到满头大汗。爬攀爬架时教他「三只手脚抓稳了，才移动第四只」。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十五（体能耐力与户外生活应用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"游乐场是最好的健身房——完全免费，而且孩子自己会玩到满头大汗。爬、攀、荡、滑，全身能力一次练齐。","principles":["攀爬架练的是手臂拉力、抓握力和全身协调，是很完整的上肢训练。","溜滑梯的爬上去比滑下来更有价值——爬楼梯是很好的下肢训练。","荡秋千提供强烈的前庭刺激，对平衡系统的整合很有帮助。","摇摇板、平衡木练的是动态平衡。","游乐场的设施高低起伏，孩子要不断判断距离和高度，练的是空间感。","和其他孩子一起玩，还有轮流、等待、协商这些社交练习。","孩子在游乐场是自发地玩，动机和持续时间都远超过安排好的运动。","爬攀爬架时有个重要的安全原则：三只手脚抓稳了，才移动第四只。"],"prep":{"场地":"社区或公园的游乐场，先看一下设施是否完好。","器材":"不需要；带水壶和毛巾。","安全检查":"先检查设施有没有损坏、地面铺面是否完整。高处要在旁边保护但不代劳。教孩子「三点固定」的攀爬原则。注意其他孩子，避免碰撞。","大人位置":"大人在旁保护，站在孩子可能掉落的那一侧，但不要帮他爬。"},"shots":[{"name":"检查设施","say":"我们先看看设施有没有坏掉。"},{"name":"攀爬架","say":"三只手脚抓稳了，才移动第四只。"},{"name":"溜滑梯","say":"爬上去比滑下来更有价值喔。"},{"name":"荡秋千","say":"荡秋千练的是平衡。"},{"name":"试新的","say":"这个没玩过，要不要试试看？"},{"name":"玩到满头汗","say":"玩得好开心！"}],"reactions":[{"if":"孩子不敢爬高","then":"不要推他。从低的开始，站在旁边陪着。恐惧要靠成功经验慢慢化解。"},{"if":"孩子只玩同一个设施","then":"先让他玩够。玩熟了再邀请「要不要试试那个」，不要硬拉。"},{"if":"孩子和别的小孩抢设施","then":"这是很好的社交练习机会。引导他「我们先排队」或「玩完换他」。"}],"mistakes":["大人帮孩子爬上去——他自己爬不上去，就代表还没准备好。帮他上去反而危险。","不检查设施就让孩子玩——损坏的器材是意外的主因。","一直喊「小心」——过度提醒反而让孩子分心。站在保护位置就好。"],"down":"玩低矮的设施；大人陪着一起爬；只玩他熟悉的。","up":"尝试更高的攀爬架；练习自己爬上溜滑梯；或挑战没玩过的设施。","progress":["能爬多高的攀爬架。","愿不愿意尝试新的设施。","能自己玩多久。"],"outro":"游乐场是免费的健身房，孩子自己就会玩到满头大汗。记住教他一句话——三只手脚抓稳了，才移动第四只。"}' AS JSON))
WHERE `id` = 'A057';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会运动前的热身，保护身体。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先慢走或原地踏步两分钟。"},{"imageUrl":null,"instruction":"转一转：脖子、肩膀、腰、膝盖、脚踝。"},{"imageUrl":null,"instruction":"动一动：抬腿、摆腿、扭腰。"},{"imageUrl":null,"instruction":"再小跑几步就可以开始了。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着大人做'),
  `harder` = COALESCE(`harder`, '自己完整做完一套。'),
  `tip` = COALESCE(`tip`, '运动前热身、运动后伸展——这个习惯从小养成，能保护孩子一辈子的关节。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十五（体能耐力与户外生活应用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"运动前热身、运动后伸展——这个习惯从小养成，能保护孩子一辈子的关节。这一集教的是热身。","principles":["热身的目的是让肌肉温度上升、血流增加，让身体准备好用力。","温度高的肌肉延展性比较好，比较不容易拉伤。","热身还会让关节分泌滑液，减少摩擦和磨损。","心跳和呼吸慢慢上来，比突然剧烈运动对心肺温和得多。","热身时的关节活动，也让神经系统先「唤醒」相关的肌肉。","热身要用动态的方式——边动边伸展，而不是停着不动拉筋。","运动前做静态拉筋（停住不动）其实会暂时降低肌肉的爆发力。","整个热身只要三到五分钟就够，但这几分钟能省下很多伤害。"],"prep":{"场地":"运动的场地就地进行，空间够转动手脚即可。","器材":"不需要任何东西。","安全检查":"动作幅度从小到大，不要一开始就做大幅度。转动关节时不要弹震或用力甩。","大人位置":"大人一起做，把顺序带一遍。"},"shots":[{"name":"先慢走","say":"先慢走或原地踏步两分钟。"},{"name":"转脖子肩膀","say":"转一转脖子、肩膀。"},{"name":"转腰和膝盖","say":"腰转一转、膝盖转一转。"},{"name":"转脚踝","say":"脚踝也要转。"},{"name":"动态伸展","say":"抬抬腿、摆摆腿、扭扭腰。"},{"name":"小跑几步","say":"最后小跑几步，就可以开始了！"}],"reactions":[{"if":"孩子觉得热身很无聊","then":"配上音乐，或做成「机器人启动」的游戏——从头到脚一个一个关节启动。"},{"if":"孩子想直接开始运动","then":"把热身说成「让身体开机」。也可以缩短到两分钟，但不要跳过。"},{"if":"孩子甩手甩脚很用力","then":"提醒「慢慢转，不要甩」。快速甩动反而可能拉伤。"}],"mistakes":["完全跳过热身——这是最常见也最伤身体的错误。","运动前做静态拉筋停很久——运动前要动态热身，静态拉筋留到运动后。","动作太快太用力——热身要慢、要温和。"],"down":"只做慢走和转关节；时间缩到两分钟。","up":"加入更多动态伸展；配上音乐做成固定的热身操；或让孩子自己带热身。","progress":["能不能记住热身的顺序。","会不会主动在运动前热身。","动作是慢慢转还是用甩的。"],"outro":"热身只要三到五分钟，但能省下很多伤害。记住顺序：先慢走、再转关节、然后动态伸展、最后小跑几步。"}' AS JSON))
WHERE `id` = 'A058';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一块垫子'),
  `trains` = COALESCE(`trains`, '学会运动后的缓和，隔天不酸痛。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先慢走两三分钟，让心跳慢下来。"},{"imageUrl":null,"instruction":"伸展小腿：面对墙，一脚往后踩住地面。"},{"imageUrl":null,"instruction":"伸展大腿后侧：坐着伸直腿，慢慢摸脚。"},{"imageUrl":null,"instruction":"每个动作停二十秒。"},{"imageUrl":null,"instruction":"喝水休息。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '慢走加一两个伸展'),
  `harder` = COALESCE(`harder`, '完整做完一套。'),
  `tip` = COALESCE(`tip`, '伸展要「慢慢进入、停二十秒、正常呼吸、感觉紧但不能痛」——记住这四句就不会做错。绝对不要弹震或用力扳。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十三（柔韧度与关节活动度）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"运动完直接坐下来，隔天容易酸痛。伸展要记住四句话：慢慢进入、停二十秒、正常呼吸、感觉紧但不能痛。","principles":["运动后肌肉处于收缩紧绷的状态，伸展可以帮助它恢复长度。","慢慢让心跳降下来，比突然停止对心血管更温和。","伸展能改善柔软度，长期下来减少受伤的机会。","这时候肌肉温度高，是伸展效果最好的时机。","伸展要「停住」二十秒——太短没效果，弹震反而会引发保护性收缩。","弹震或用力扳是最危险的做法，可能造成肌肉拉伤。","「感觉紧但不能痛」是判断力道的标准，痛就代表太过了。","正常呼吸很重要，憋气会让肌肉更紧绷，伸展不下去。"],"prep":{"场地":"运动的场地或家里，铺一块垫子。","器材":"一块垫子；水杯。","安全检查":"这一集的安全原则就是活动本身的重点：绝对不要弹震或用力扳。感觉痛就是太过了，要马上减轻。","大人位置":"大人一起做，示范正确的力道和呼吸。"},"shots":[{"name":"先慢走","say":"先慢走两三分钟，让心跳慢下来。"},{"name":"伸展小腿","say":"面对墙，一脚往后踩住地面。"},{"name":"数二十秒","say":"停住——数到二十，不要憋气。"},{"name":"伸展大腿后侧","say":"坐着伸直腿，慢慢往前摸脚。"},{"name":"力道提醒","say":"感觉紧就好，不能痛喔。"},{"name":"喝水休息","say":"喝口水，休息一下。"}],"reactions":[{"if":"孩子伸展时弹来弹去","then":"立刻制止。示范「停住不动」，可以用数数帮他维持。"},{"if":"孩子说痛","then":"马上减轻力道。痛代表太过了，伸展应该是「紧」而不是「痛」。"},{"if":"孩子伸展时憋气","then":"提醒「一边数一边呼吸」。数数的时候就不会憋气。"}],"mistakes":["弹震或用力扳——这是最危险的做法，可能拉伤肌肉。","停的时间太短——少于十秒几乎没效果，要停二十秒。","憋气——会让肌肉更紧，伸展不下去。"],"down":"每个动作停十秒；力道减轻；只做两个动作。","up":"停三十秒；增加伸展的部位（肩膀、背部、髋部）；或做成固定的伸展流程。","progress":["能不能停住二十秒不弹动。","会不会自己判断「紧」和「痛」的差别。","隔天有没有比较不酸痛。"],"outro":"伸展记住四句话：慢慢进入、停二十秒、正常呼吸、感觉紧但不能痛。绝对不要弹震或用力扳。"}' AS JSON))
WHERE `id` = 'A059';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会分辨累了、喘了、痛了，懂得保护自己。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"运动中问「你现在觉得怎么样？」"},{"imageUrl":null,"instruction":"教他分辨：有点喘（正常）、很喘（该休息）、痛（要停）。"},{"imageUrl":null,"instruction":"累了可以说「我要休息」。"},{"imageUrl":null,"instruction":"痛了一定要说出来。"},{"imageUrl":null,"instruction":"尊重他说的休息需求。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '会说「我累了」'),
  `harder` = COALESCE(`harder`, '能分辨不同程度，自己调整。'),
  `tip` = COALESCE(`tip`, '会听身体声音的孩子，才不会练到受伤。判断运动强度有个简单方法：还能说话但不能唱歌，这个强度刚刚好。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十五（体能耐力与户外生活应用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"会听身体声音的孩子，才不会练到受伤。这一集教孩子分辨三件事：有点喘、很喘、还有痛。","principles":["孩子常常不知道怎么描述身体的感觉，也不知道什么时候该停。","教他分辨「有点喘」和「很喘」，他才知道什么时候该休息。","「痛」和「累」是完全不同的两件事——累可以撑一下，痛一定要停。","很多运动伤害是因为孩子忍着痛继续做造成的。","能说出「我要休息」是自我照顾的能力，不是软弱。","大人尊重孩子说的休息需求，他下次才敢说出来。","判断运动强度有个简单的方法：还能说话但不能唱歌，这个强度刚刚好。","这个能力会跟着孩子一辈子，比任何一个动作都重要。"],"prep":{"场地":"在运动当中进行，不需要另外安排时间。","器材":"不需要任何东西。","安全检查":"这一集本身就是安全教育。重点是建立「痛就要停、累可以说」的观念。","大人位置":"大人要真的尊重孩子说的休息需求，说了却不理会，下次他就不说了。"},"shots":[{"name":"运动中提问","say":"你现在觉得怎么样？"},{"name":"三个等级","say":"有点喘、很喘、还是痛？"},{"name":"说话测试","say":"你还能跟我说话吗？"},{"name":"很喘要休息","say":"很喘的时候就该休息了。"},{"name":"痛要马上停","say":"痛的话一定要马上说、马上停。"},{"name":"尊重他的需求","say":"你说要休息，那我们就休息。"}],"reactions":[{"if":"孩子说不出感觉","then":"给他选项：「有点喘还是很喘？」二选一比开放式问题容易回答。"},{"if":"孩子一直说要休息","then":"先尊重他。但可以观察是真的累还是不想做，用「再做三下就休息」来分辨。"},{"if":"孩子忍着痛不说","then":"观察表情和动作有没有改变。平时就要说「痛了一定要说，说了才安全」。"}],"mistakes":["孩子说累却要他撑完——这样他下次就不说了，反而更危险。","把「痛」当成「累」处理——痛一定要停，这两个不能混为一谈。","只在受伤后才教——平时运动中就要不断问、不断练习。"],"down":"只分「还好」和「不舒服」两个等级；用表情图卡辅助。","up":"用一到十的数字描述强度；学会说出是哪里不舒服；或自己主动报告身体状态。","progress":["能不能分辨有点喘、很喘和痛。","会不会主动说「我要休息」。","痛的时候会不会说出来。"],"outro":"会听身体声音的孩子，才不会练到受伤。记住那个简单的判断法——还能说话但不能唱歌，这个强度刚刚好。"}' AS JSON))
WHERE `id` = 'A060';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '面团、黏土或橡皮泥'),
  `trains` = COALESCE(`trains`, '用手捏、揉、压，练手指的力气。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一块面团。"},{"imageUrl":null,"instruction":"一起捏、揉、搓、压。"},{"imageUrl":null,"instruction":"做成小球、长条、饼饼。"},{"imageUrl":null,"instruction":"用手指戳洞、用手掌压扁。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '软一点的面团、随意捏'),
  `harder` = COALESCE(`harder`, '硬一点的面团，或做出指定的形状。'),
  `tip` = COALESCE(`tip`, '自己用面粉加水就能做面团，比买黏土便宜也更安全。捏面团是手指力气最好的入门练习。小小孩注意别放进嘴里。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组七（手部精细·抓握与力量）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一块面团，捏、揉、搓、压。自己用面粉加水就能做，比买黏土便宜也更安全——这是手指力气最好的入门练习。","principles":["面团有阻力，手指必须用力才捏得动，这是最直接的手指肌力训练。","手指的力气不够，握笔时就会握得死紧或握得太松，两种都写不久。","捏、揉、搓、压是四种不同的手部动作，用到的肌肉都不一样。","捏用到的是指尖，揉用到的是整个手掌，搓需要双手配合，压则是手掌根部出力。","面团会随着施力改变形状，这个即时的回馈让孩子知道自己用了多少力。","力道的感觉叫做本体觉，手部本体觉好的孩子，拿东西不会太用力也不会掉。","面团的触感对触觉敏感的孩子是很好的减敏材料，可以循序适应。","自制面团只有面粉和水，就算放进嘴里也相对安全，适合年纪很小的孩子。"],"prep":{"场地":"餐桌或矮桌，铺一块桌垫或旧报纸方便收拾。","器材":"面团、黏土或橡皮泥；自制面团＝面粉两杯＋水半杯＋一点点盐，揉一揉就好。","安全检查":"小小孩注意别放进嘴里，全程要看着。市售黏土要选无毒的。对面粉过敏的孩子改用米黏土或市售无麸质黏土。玩完洗手。","大人位置":"大人坐在孩子旁边一起捏，示范各种手法。"},"shots":[{"name":"做面团","say":"面粉加水，我们自己做面团。"},{"name":"捏","say":"用手指捏捏看。"},{"name":"揉和搓","say":"用手掌揉一揉、搓成长条。"},{"name":"压扁","say":"用手掌压成饼饼。"},{"name":"戳洞","say":"用食指戳几个洞。"},{"name":"做成东西","say":"我们做一条小虫！"}],"reactions":[{"if":"孩子捏不动面团","then":"面团太硬。加一点水揉软，或先微波几秒变软。软到他捏得动才有成就感。"},{"if":"孩子只会整只手抓","then":"示范单根手指戳洞、两根手指捏。从「戳」开始最容易分化出手指。"},{"if":"孩子想把面团放进嘴里","then":"一岁多的孩子很常见。全程看着，并且用自制的安全面团。可以给他一小块另外的食物满足口欲。"}],"mistakes":["面团太硬——捏不动就失去意义了，宁可软一点。","只让孩子自由玩不给示范——示范几种手法，他才知道手可以怎么用。","小小孩玩时离开视线——误食风险，务必全程在旁。"],"down":"面团调软；只做压和戳这两个最简单的动作；给大一块比较好抓。","up":"面团调硬一点；用工具压出形状；搓很细的长条；或捏出指定的东西（小猫、花）。","progress":["能不能用单根手指戳洞。","能不能搓出长条（需要双手配合）。","捏的力气有没有变大。"],"outro":"面粉加水就是最便宜的手部训练材料。捏、揉、搓、压四种手法都做一遍，手指的力气就练到了。"}' AS JSON))
WHERE `id` = 'A061';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '废纸、旧广告单'),
  `trains` = COALESCE(`trains`, '双手配合撕纸，练两只手一起工作。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一张废纸。"},{"imageUrl":null,"instruction":"教他两只手一起用力撕开。"},{"imageUrl":null,"instruction":"撕成小片、撕成长条。"},{"imageUrl":null,"instruction":"撕完的纸片可以拿来贴画。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '撕软一点的纸、随便撕'),
  `harder` = COALESCE(`harder`, '沿着画好的线撕。'),
  `tip` = COALESCE(`tip`, '撕纸需要两只手往不同方向出力——这是双手配合的重要练习，别急着阻止孩子撕纸，给他废纸尽情撕。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"给孩子一张废纸，让他尽情撕。撕纸需要两只手往不同方向出力——这是双手配合的重要练习，别急着阻止。","principles":["撕纸时一只手往上、一只手往下，两只手做的是完全相反的动作。","这叫双手不对称协调，比两手做同样的事难得多。","日常生活中很多动作都是不对称的：开包装、拧瓶盖、一手扶纸一手写。","撕的时候手指要捏紧纸张不滑掉，这是指尖的捏握力训练。","纸被撕开的瞬间有清楚的触觉和听觉回馈，孩子会觉得很有成就感。","撕成小片需要更精准的控制，撕成长条则需要持续且方向一致的力道。","很多家长看到孩子撕纸就阻止，其实那是很重要的发展需求。","给他专用的废纸，他就不会去撕书和重要文件。"],"prep":{"场地":"地板或桌上，准备一个袋子装碎纸。","器材":"废纸、旧广告单；不要用会掉色的报纸给太小的孩子。","安全检查":"纸片可能被放进嘴里，小小孩要全程看着。纸张边缘可能割手，动作别太快。撕完的纸屑要收好。","大人位置":"大人坐在旁边一起撕，示范两手方向相反。"},"shots":[{"name":"给废纸","say":"这些纸都可以撕，尽情撕吧！"},{"name":"两手方向相反","say":"一只手往上、一只手往下。"},{"name":"撕开","say":"撕！"},{"name":"撕长条","say":"这次撕成一条一条。"},{"name":"撕小片","say":"撕成小小片。"},{"name":"拿来贴画","say":"撕完的纸可以拿来贴一幅画。"}],"reactions":[{"if":"孩子撕不开","then":"先在纸上剪一个小口，让他从缺口开始撕。或换薄一点的纸。"},{"if":"孩子只用一只手拉","then":"大人握住纸的一端，让他用两只手撕。或示范两手抓着的姿势。"},{"if":"孩子把纸放进嘴里","then":"全程看着，及时拿出来。也可以用比较厚、不容易碎的纸。"}],"mistakes":["看到孩子撕纸就阻止——这是重要的发展需求，给他专用的废纸就好。","纸太厚太硬——撕不开会挫折，广告单或影印纸最合适。","撕完不收拾——让孩子一起把碎纸收进袋子，也是收拾的练习。"],"down":"先剪一个缺口让他起头；用薄一点的纸；大人扶住一端。","up":"撕成细长条；沿着画好的线撕；撕出指定的形状；或撕成一样大小的小片。","progress":["能不能两只手一起撕。","能不能撕出长条而不断掉。","撕的控制有没有越来越精准。"],"outro":"撕纸是双手配合最好的入门练习。准备一叠专用的废纸，孩子就能撕得很开心，也不会去动你的书。"}' AS JSON))
WHERE `id` = 'A062';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '晒衣夹＋一个纸盘或纸箱边'),
  `trains` = COALESCE(`trains`, '练手指捏的力气（和握笔用的是同一组肌肉）。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子几个晒衣夹。"},{"imageUrl":null,"instruction":"让他夹在纸盘边缘、纸箱边、或绳子上。"},{"imageUrl":null,"instruction":"可以做成小太阳（圆盘＋一圈夹子）。"},{"imageUrl":null,"instruction":"用大拇指和食指捏开。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '松一点的夹子、夹在厚边上'),
  `harder` = COALESCE(`harder`, '紧一点的夹子，或用非惯用手夹。'),
  `tip` = COALESCE(`tip`, '夹子用到的正是握笔的那组手指肌肉——玩夹子的孩子，握笔的力气会更好。夹子别太紧，夹到手会痛。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组七（手部精细·抓握与力量）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"几个晒衣夹，夹在纸盘边上做成一个小太阳。夹子用到的正是握笔的那组手指肌肉——玩夹子的孩子，握笔的力气会更好。","principles":["捏开夹子用的是大拇指、食指和中指，这三根手指的组合叫三指抓握。","三指抓握正是握笔的姿势，所以夹子被称为握笔的前置训练。","捏开夹子需要持续施力几秒钟，这是手指的等长收缩训练。","夹到指定的位置还需要手眼配合和精准控制。","两只手会各自工作——一只手扶住纸盘，一只手操作夹子，这是双手分工。","夹子有不同的紧度，可以很自然地调整难度。","做成小太阳、做成刺猬，让重复的动作变成有意义的作品。","这个活动材料便宜、随处可得，是性价比最高的手部训练之一。"],"prep":{"场地":"餐桌或地板，把夹子和纸盘摆好。","器材":"晒衣夹（塑胶的比木头的轻）＋一个纸盘或纸箱边；也可以夹在绳子上。","安全检查":"夹子别太紧，夹到手指会痛。木头夹子可能有木刺，检查一下。小小孩注意夹子的弹簧别夹到手。","大人位置":"大人坐在对面，示范三指捏开的动作。"},"shots":[{"name":"三指捏开","say":"用大拇指和食指捏开。"},{"name":"夹在盘边","say":"夹在盘子边边上。"},{"name":"另一手扶住","say":"另一只手要扶好盘子。"},{"name":"夹成一圈","say":"夹成一个小太阳！"},{"name":"按颜色夹","say":"这次照颜色的顺序夹。"},{"name":"拆下来","say":"拆下来也要用力喔。"}],"reactions":[{"if":"孩子捏不开夹子","then":"换松一点的夹子，或用两只手一起捏。手指力气是慢慢练出来的。"},{"if":"孩子用整只手抓着捏","then":"示范只用三根手指。可以把其他两根手指压住，逼他用三指。"},{"if":"孩子夹不准位置","then":"先夹在比较厚、比较好夹的地方（纸箱边）。精准度会随着练习提高。"}],"mistakes":["夹子太紧——捏不开会放弃，也可能夹到手很痛。要选松一点的。","让孩子用整只手抓——这样就练不到三指抓握了，要示范正确手势。","只夹不拆——拆下来也很费力，两个动作都要做。"],"down":"用松一点的夹子；用两只手捏；夹在好夹的厚边缘上。","up":"用紧一点的夹子；夹在薄的地方；按颜色规律排列；或用非惯用手夹。","progress":["能不能用三根手指捏开。","一分钟能夹几个。","夹的位置准不准。"],"outro":"夹子练的就是握笔的那组手指。做成小太阳、做成刺猬，孩子会一个接一个夹，手指的力气就这样出来了。"}' AS JSON))
WHERE `id` = 'A063';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '筷子或夹子＋豆子＋两个碗'),
  `trains` = COALESCE(`trains`, '用工具把小东西夹到另一个碗，练手眼配合和手指控制。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"两个碗，一个装豆子。"},{"imageUrl":null,"instruction":"让孩子用夹子（或筷子）把豆子夹到空碗里。"},{"imageUrl":null,"instruction":"一次夹一颗。"},{"imageUrl":null,"instruction":"看看一分钟能夹几颗。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '用大夹子夹大的东西（棉花球、乒乓球）'),
  `harder` = COALESCE(`harder`, '用筷子夹小豆子。'),
  `tip` = COALESCE(`tip`, '三岁以下不玩豆子——小东西容易误吞。可以改用棉花球、小方块积木，一样好玩。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组九（工具使用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"用夹子或筷子把豆子一颗一颗夹到另一个碗。三岁以下不玩豆子——小东西容易误吞，可以改用棉花球。","principles":["夹起小东西需要非常精准的手指控制和手眼配合。","豆子又小又滑，力道太轻夹不起来、太重会滑掉，这是很精细的力道调节。","这种「刚刚好」的力道控制，和写字时笔压的控制是同一件事。","用筷子夹更难——需要手指分工：无名指小指稳住下面那根，拇指食指中指操作上面那根。","这正是日后使用筷子吃饭的动作，在游戏里练熟了，餐桌上就顺了。","把豆子送到另一个碗的路径中，手要保持稳定不能抖。","计时挑战「一分钟夹几颗」会让孩子自己想突破纪录。","这个活动的难度可以用夹子种类和物品大小精细地调整。"],"prep":{"场地":"餐桌，两个碗并排放好，中间不要太远。","器材":"筷子或夹子＋豆子＋两个碗；三岁以下改用棉花球、小方块积木或毛球。","安全检查":"这是本模组最需要注意的活动：三岁以下绝不用豆子，误吞和呛入气管都有生命危险。全程看着。玩完立刻收好。","大人位置":"大人坐在旁边，示范正确的夹法。"},"shots":[{"name":"安全提醒","say":"三岁以下我们用棉花球，不用豆子。"},{"name":"握夹子","say":"用三根手指握住夹子。"},{"name":"夹起来","say":"轻轻夹住，不要太用力。"},{"name":"送过去","say":"稳稳送到另一个碗。"},{"name":"计时","say":"看一分钟能夹几颗！"},{"name":"换筷子","say":"厉害的话可以换筷子试试。"}],"reactions":[{"if":"孩子夹不起来","then":"换大一点、不滑的东西（棉花球、小积木）。或用夹取面积大的夹子。"},{"if":"孩子夹到一半掉了","then":"很正常。提醒「慢慢送」，或把两个碗放近一点缩短路径。"},{"if":"孩子想用手直接拿","then":"规定「只能用夹子」。也可以把这变成游戏规则的一部分。"}],"mistakes":["三岁以下用豆子——这是有生命危险的错误，务必用大的替代物。","东西太小太滑——夹不起来会挫折，从大的、有摩擦力的开始。","玩完没收好——豆子散落在地上，小小孩捡起来就危险了。"],"down":"用棉花球或大积木；用夹取面积大的夹子；两个碗放很近。","up":"换成豆子或小珠子；改用筷子；增加距离；或按颜色分类夹到不同碗。","progress":["一分钟能夹几颗。","掉落的次数有没有减少。","能不能用筷子夹起来。"],"outro":"夹豆子练的是力道的精准控制，和写字的笔压是同一件事。但记住——三岁以下一定要用棉花球，不能用豆子。"}' AS JSON))
WHERE `id` = 'A064';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '吸管剪成小段＋鞋带或粗线'),
  `trains` = COALESCE(`trains`, '两只手配合把东西串起来，练精准和耐心。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把吸管剪成一小段一小段。"},{"imageUrl":null,"instruction":"给孩子一条鞋带（头端硬的比较好穿）。"},{"imageUrl":null,"instruction":"让他把吸管一个个串上去。"},{"imageUrl":null,"instruction":"串成项链或手环。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大孔的东西（切片吸管、通心粉）'),
  `harder` = COALESCE(`harder`, '小珠子，或按颜色顺序串。'),
  `tip` = COALESCE(`tip`, '吸管剪一剪就是免费的串珠材料。这个活动一只手拿线、一只手拿珠，是很好的双手分工练习。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"吸管剪成一小段一小段，就是免费的串珠材料。一只手拿线、一只手拿珠，这是很好的双手分工练习。","principles":["串珠需要两只手做完全不同的事：一手固定线、一手拿珠子对准洞口。","这种双手分工，专业上叫一手稳定、一手操作。","生活中很多动作都是这个模式：一手扶碗一手舀、一手压纸一手写。","要把线穿过小洞，需要很精准的手眼配合和空间对位。","穿过去之后还要把珠子拉到底，是持续的双手协调。","串珠需要耐心，一颗一颗慢慢来，是很好的持续性专注练习。","完成一条项链或手环，孩子会有明确的成就感。","吸管剪一剪就有，比买串珠玩具便宜得多，长度还可以自己调。"],"prep":{"场地":"餐桌，把吸管段和线摆好，最好用有边的托盘防止滚落。","器材":"吸管剪成小段＋鞋带或粗线；鞋带头端是硬的，最好穿。","安全检查":"吸管段和珠子都是小东西，三岁以下要特别注意误吞。线不要太长，避免缠绕脖子。玩完立刻收好。","大人位置":"大人坐在旁边，必要时帮忙固定线头。"},"shots":[{"name":"剪吸管","say":"吸管剪一剪就是珠子。"},{"name":"双手分工","say":"一只手拿线，一只手拿珠子。"},{"name":"对准洞口","say":"对准洞口，慢慢穿进去。"},{"name":"拉到底","say":"穿过去了，拉到底。"},{"name":"串一整条","say":"一颗一颗，串成一条。"},{"name":"做成手环","say":"打个结，变成手环！"}],"reactions":[{"if":"孩子穿不过去","then":"换粗一点的吸管段（洞大），或用硬头的鞋带。也可以大人帮忙扶着线头。"},{"if":"孩子拿不稳线","then":"把线的一端用胶带固定在桌上，孩子只要专心穿珠就好。"},{"if":"孩子串两颗就不想串了","then":"目标订小一点（「串五颗就好」），或让他串在短一点的线上。"}],"mistakes":["洞太小、线太软——穿不过去会挫折。吸管要粗、线要硬头。","线太长——串很久都串不满，也有缠绕风险。二三十厘米就够。","小小孩玩时离开——吸管段是标准的误吞大小，务必全程看着。"],"down":"用粗吸管（洞大）；线的一端用胶带固定在桌上；只串三五颗。","up":"换细一点的吸管或真的珠子；按颜色排出规律；串成指定长度；或用细线穿。","progress":["能不能自己对准洞口穿进去。","能连续串几颗。","两只手会不会各自分工。"],"outro":"吸管剪一剪就是串珠。一手拿线、一手拿珠，这个「一手稳、一手动」的能力，生活中到处用得到。"}' AS JSON))
WHERE `id` = 'A065';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几个不同大小的瓶子和盖子'),
  `trains` = COALESCE(`trains`, '练手腕转动和两只手配合。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把瓶盖都打开、混在一起。"},{"imageUrl":null,"instruction":"让孩子帮每个瓶子找到对的盖子。"},{"imageUrl":null,"instruction":"再拧紧。"},{"imageUrl":null,"instruction":"大小不同的瓶子增加挑战。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大瓶大盖'),
  `harder` = COALESCE(`harder`, '小瓶小盖，或盖子种类多一点。'),
  `tip` = COALESCE(`tip`, '一只手固定瓶子、一只手转盖子——这是很典型的「一手稳、一手动」的配合，生活中到处用得到。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把瓶盖都打开混在一起，让孩子帮每个瓶子找到对的盖子再拧紧。一手固定瓶子、一手转盖子——生活中到处用得到。","principles":["拧瓶盖需要手腕做旋转动作，这是很多孩子较少练到的动作方向。","手腕的旋转能力，和日后转钥匙、拧水龙头、用螺丝起子都有关。","一只手要牢牢固定瓶子不让它转，另一只手转盖子，这是典型的双手分工。","大小不同的瓶盖需要不同的抓握方式——大盖用整只手，小盖用指尖。","这种依物品调整抓握方式的能力，叫抓握模式的适应。","帮瓶子找对的盖子，还练到了大小配对和视觉辨识。","拧紧需要持续施力到「转不动为止」，这是力道的判断。","材料全部是回收瓶罐，完全不用花钱。"],"prep":{"场地":"餐桌，瓶子排成一排，盖子混在一起放旁边。","器材":"几个不同大小的瓶子和盖子；洗干净的饮料瓶、调味罐都可以。","安全检查":"瓶子要洗干净、没有残留。玻璃瓶不适合，用塑胶瓶。小盖子注意误吞。","大人位置":"大人坐在旁边，必要时帮忙固定瓶子。"},"shots":[{"name":"打乱盖子","say":"我们把盖子都打开、混在一起。"},{"name":"找对的盖子","say":"哪个盖子是这个瓶子的？"},{"name":"一手固定","say":"一只手抓紧瓶子不要让它转。"},{"name":"转盖子","say":"另一只手转盖子。"},{"name":"拧紧","say":"转到转不动为止。"},{"name":"全部完成","say":"全部找对了！"}],"reactions":[{"if":"孩子转不动盖子","then":"选松一点的盖子，或大人先松开一点。太紧会挫折。"},{"if":"孩子瓶子跟着一起转","then":"提醒「一只手抓紧瓶子」。也可以把瓶子放在防滑垫上，或大人帮忙扶。"},{"if":"孩子找不对盖子","then":"先减少到两三个瓶子，大小差异明显一点。"}],"mistakes":["盖子拧太紧——孩子打不开会放弃，要先松一点。","瓶子太滑固定不住——放在防滑垫上或用有纹路的瓶子。","瓶子数量太多——三四个就够，太多会眼花。"],"down":"只用两三个瓶子；大小差异明显；盖子先松开；瓶子放防滑垫上。","up":"增加瓶子数量；大小相近不好分辨；用需要对准螺纹的盖子；或计时挑战。","progress":["能不能一手固定、一手转。","能不能自己找对大小的盖子。","拧紧的力道够不够。"],"outro":"回收的瓶罐就是最好的教具。一手固定、一手转动，这个配合模式在生活中天天用得到。"}' AS JSON))
WHERE `id` = 'A066';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '废纸＋一个纸箱'),
  `trains` = COALESCE(`trains`, '单手把纸揉成球，练手掌里的小肌肉。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一张废纸。"},{"imageUrl":null,"instruction":"请他用「一只手」把纸揉成球（另一只手不能帮忙）。"},{"imageUrl":null,"instruction":"揉好了丢进纸箱。"},{"imageUrl":null,"instruction":"两只手轮流揉。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '软的薄纸、两只手一起揉'),
  `harder` = COALESCE(`harder`, '硬一点的纸、单手揉紧。'),
  `tip` = COALESCE(`tip`, '单手揉纸练的是手掌里那些很难练到的小肌肉——揉完再投篮，孩子会一张接一张揉不停。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一张废纸，用「一只手」揉成球——另一只手不能帮忙。单手揉纸练的是手掌里那些很难练到的小肌肉。","principles":["单手揉纸时，手掌必须反复收缩、手指要把纸往掌心收拢。","这用到的是手掌里的内在肌，包括大鱼际和小鱼际的肌肉群。","内在肌负责手指的精细动作和手掌的弓形结构，却很难单独训练。","手掌弓不够的孩子，握笔时手掌会摊平，笔的控制就不稳。","揉纸的过程中，纸会越来越紧实，需要的力气越来越大，是渐进式的阻力。","手掌里的动作还需要手指在掌心内移动物品，这叫掌内操作。","掌内操作是很高阶的手部能力，例如手里握着几个铜板还能一个一个拿出来。","揉好了投篮，给了这个练习一个有趣的收尾，孩子会一张接一张揉。"],"prep":{"场地":"客厅或餐桌，纸箱放在两三步外。","器材":"废纸＋一个纸箱；影印纸、广告单都可以。","安全检查":"纸球很轻很安全。投掷方向避开玻璃和摆饰。小小孩注意纸球别放进嘴里。","大人位置":"大人在旁边一起揉，示范单手的动作。"},"shots":[{"name":"规则说明","say":"只能用一只手揉喔，另一只手放背后。"},{"name":"单手揉","say":"用手掌把纸收进来。"},{"name":"越揉越紧","say":"越揉越紧、越揉越小。"},{"name":"完成纸球","say":"揉好了！"},{"name":"投篮","say":"丢进箱子！"},{"name":"换手","say":"换另外一只手揉。"}],"reactions":[{"if":"孩子忍不住用两只手","then":"把另一只手放到背后，或让他坐着把另一只手压在屁股下面。"},{"if":"孩子揉不紧","then":"用薄一点、软一点的纸。或先把纸稍微搓皱再给他。"},{"if":"孩子只用惯用手","then":"规定「这次只能用左手」。非惯用手会比较吃力，但值得练。"}],"mistakes":["让孩子用两只手揉——两只手揉就练不到掌内的小肌肉了，单手是关键。","纸太厚太硬——揉不动会放弃，用一般影印纸或广告单。","只揉不投——投篮是动机来源，两个环节都要有。"],"down":"用薄一点的纸；纸先稍微搓皱；允许用两只手先试一次。","up":"用厚一点的纸；揉得更紧更小；两只手同时各揉一个；或增加投篮距离。","progress":["能不能单手揉成球。","揉出来的球紧不紧。","非惯用手能不能也做到。"],"outro":"单手揉纸练的是手掌里最难练到的小肌肉。规则只有一条——另一只手不能帮忙。"}' AS JSON))
WHERE `id` = 'A067';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '儿童安全剪刀＋废纸'),
  `trains` = COALESCE(`trains`, '学会用剪刀，是重要的工具使用能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先教握剪刀：大拇指在上面的洞。"},{"imageUrl":null,"instruction":"从「剪一刀」开始——剪细长条的纸最容易。"},{"imageUrl":null,"instruction":"再练剪直线（在纸上画一条粗线）。"},{"imageUrl":null,"instruction":"最后练剪曲线和形状。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '剪一刀就断的细纸条'),
  `harder` = COALESCE(`harder`, '沿着直线剪、剪出形状。'),
  `tip` = COALESCE(`tip`, '「大拇指朝上」是握剪刀的关键。剪的时候另一只手要转纸，不是转剪刀。全程大人陪着，剪完收好。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组九（工具使用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"学用剪刀，「大拇指朝上」是关键。剪的时候另一只手要转纸，不是转剪刀——这一集把顺序讲清楚。","principles":["使用剪刀需要手指做开合动作，用的是拇指和其他手指的对抗。","这个开合动作和握笔、捏东西用的是同一组肌肉。","「大拇指朝上」的握法能让手腕维持在中立位置，出力最有效率。","如果大拇指朝下或手腕扭转，剪起来会很费力，也剪不准。","剪的时候另一只手要转动纸张来对准剪刀，这是双手分工的高阶表现。","很多孩子会转剪刀而不是转纸，这样手腕会扭成很奇怪的角度。","剪直线、剪曲线、剪形状的难度是递增的，要按顺序练。","剪刀是重要的工具使用能力，也是幼儿园和小学常用的技能。"],"prep":{"场地":"餐桌，坐着操作，桌面高度让手肘能自然弯曲。","器材":"儿童安全剪刀＋废纸；剪刀要选圆头、刀刃短的。左撇子的孩子要用左手剪刀。","安全检查":"这是本模组工具类活动，安全要求最高。全程大人陪着。教「剪刀不能对着人、不能拿着走」。用完立刻收好放高处。剪刀要选圆头安全款。","大人位置":"大人坐在孩子旁边（同侧，不要面对面），示范握法和转纸。"},"shots":[{"name":"安全规则","say":"剪刀不能对着人，也不能拿着走。"},{"name":"握剪刀","say":"大拇指放上面的洞，其他手指放下面。"},{"name":"剪一刀","say":"先从剪一刀开始，剪细长条最容易。"},{"name":"另一手转纸","say":"另一只手转纸，不是转剪刀。"},{"name":"剪直线","say":"沿着这条粗线剪。"},{"name":"剪形状","say":"厉害的话可以剪一个圆形。"}],"reactions":[{"if":"孩子大拇指朝下握剪刀","then":"立刻纠正。可以在剪刀上贴一张笑脸贴纸，规定「笑脸要朝上」。"},{"if":"孩子转剪刀不转纸","then":"大人扶住他的剪刀手不让它转，引导另一只手去转纸。"},{"if":"孩子剪不开","then":"剪刀可能太钝或太大。换小一点的儿童剪刀，或从很细的纸条开始。"}],"mistakes":["大拇指朝下握——这是最常见的错误，会让手腕扭转、剪不准也很费力。","转剪刀不转纸——手腕会扭成奇怪的角度，要教另一只手转纸。","一开始就剪形状——顺序是：剪一刀→剪直线→剪曲线→剪形状，不能跳。"],"down":"剪细长条（一刀就断）；用弹簧辅助剪刀；大人扶住纸。","up":"剪直线、剪曲线、剪出圆形和三角形；剪出可以拼贴的形状。","progress":["大拇指是不是朝上。","另一只手会不会转纸。","目前能剪到哪一个阶段（一刀／直线／曲线／形状）。"],"outro":"学剪刀记住两句话：大拇指朝上，另一只手转纸。顺序是剪一刀、剪直线、剪曲线、剪形状，不要跳。"}' AS JSON))
WHERE `id` = 'A068';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '贴纸＋一张纸'),
  `trains` = COALESCE(`trains`, '撕下贴纸再贴上去，练手指的精细动作。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一张贴纸。"},{"imageUrl":null,"instruction":"让他自己撕下来（这一步最练手指）。"},{"imageUrl":null,"instruction":"贴到指定的位置。"},{"imageUrl":null,"instruction":"可以贴成一幅画。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大贴纸、随便贴'),
  `harder` = COALESCE(`harder`, '小贴纸，或贴在画好的圈圈里。'),
  `tip` = COALESCE(`tip`, '「撕下贴纸」需要指尖捏住薄薄的边角——这个动作对手指的精细度要求很高，比贴上去更有价值。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"撕下贴纸再贴上去。「撕下来」这一步需要指尖捏住薄薄的边角——这个动作对手指的精细度要求很高，比贴上去更有价值。","principles":["要把贴纸从底纸上撕下来，必须用指甲或指尖捏住很薄的边缘。","这需要非常精准的指尖捏握，专业上叫指尖对指尖的抓握。","这是最精细的抓握方式，也是握笔和拿小东西的基础。","撕的时候还需要控制角度和力道，撕太快会破、太慢会黏住。","贴到指定位置需要手眼配合和空间定位。","撕下来之后贴纸会黏在手指上，孩子要想办法把它放到纸上，这是掌内操作。","贴纸的大小可以调整难度——大贴纸好撕，小贴纸需要更精细的控制。","贴成一幅画让重复的动作有了意义，孩子会一张一张贴很久。"],"prep":{"场地":"餐桌或地板，把贴纸和纸摆好。","器材":"贴纸＋一张纸；也可以准备画好的图案让他贴在指定位置。","安全检查":"小小孩注意贴纸别放进嘴里。贴纸别贴在家具或墙上——先约定好只能贴在纸上。","大人位置":"大人坐在旁边，必要时帮忙翘起贴纸的边角。"},"shots":[{"name":"撕下贴纸","say":"先用手指把边边翘起来。"},{"name":"完整撕下","say":"慢慢撕下来。"},{"name":"贴上去","say":"贴到这里。"},{"name":"贴在圈圈里","say":"贴在圆圈里面。"},{"name":"贴成一幅画","say":"我们贴成一朵花！"},{"name":"小贴纸挑战","say":"这次换小一点的贴纸。"}],"reactions":[{"if":"孩子撕不下贴纸","then":"大人先帮他把一个角翘起来，让他接手撕完。这样他还是练到了主要的动作。"},{"if":"孩子贴不准位置","then":"画大一点的圈圈当目标。定位精准度是慢慢练的。"},{"if":"孩子把贴纸贴得到处都是","then":"事先约定「只能贴在这张纸上」。给他专用的纸，他就不会贴家具。"}],"mistakes":["大人帮他全部撕下来——撕的那一步才是最有价值的，让他自己撕。","贴纸太小——一岁多的孩子撕不下来会挫折，从大贴纸开始。","没约定贴的范围——先说清楚只能贴在纸上。"],"down":"用大一点的贴纸；大人先帮忙翘起一角；不要求贴在指定位置。","up":"用小贴纸；贴在画好的小圈圈里；按颜色排出规律；或贴成指定的图案。","progress":["能不能自己撕下贴纸。","贴的位置准不准。","能处理多小的贴纸。"],"outro":"贴贴纸最有价值的一步是「撕下来」——那需要指尖捏住薄薄的边角。别急着帮他撕，让他自己来。"}' AS JSON))
WHERE `id` = 'A069';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '两个杯子＋米、豆子或水'),
  `trains` = COALESCE(`trains`, '练手腕控制和两手配合，是自己倒水的前身。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"两个杯子，一个装米（或豆子、水）。"},{"imageUrl":null,"instruction":"让孩子倒到另一个杯子里。"},{"imageUrl":null,"instruction":"从大杯倒到大杯，再练倒到小杯。"},{"imageUrl":null,"instruction":"洒出来没关系，一起收拾。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '干的东西（米、豆）、大杯子'),
  `harder` = COALESCE(`harder`, '倒水，或倒到小口的瓶子里。'),
  `tip` = COALESCE(`tip`, '先练倒米倒豆，洒了好收拾；熟练了再练倒水。在托盘上进行，收拾更方便。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"两个杯子，把米倒来倒去。先练倒米倒豆，洒了好收拾；熟练了再练倒水——顺序不要反过来。","principles":["倒东西需要手腕做精准的角度控制，倾斜太多会倒太快，太少倒不出来。","这个角度的持续微调，是很细致的手腕控制练习。","倒的过程中眼睛要一直盯着目标杯，这是持续的手眼协调。","一只手拿着倒、另一只手可能要扶住接的杯子，这是双手分工。","倒到快满的时候要慢下来甚至停住，这需要预判和即时调整。","米和豆子洒出来只要扫一扫，水洒了要擦，所以先练干的再练湿的。","倒进小口的杯子难度更高，需要更精准的对位。","这个动作直接连到生活——自己倒水、倒牛奶、盛饭。"],"prep":{"场地":"餐桌，下面垫一个托盘，洒出来好收拾。","器材":"两个杯子＋米、豆子或水；杯子选不易破、有点重量的（不容易被碰倒）。","安全检查":"三岁以下用豆子要注意误吞，可以改用米或大颗的通心粉。玻璃杯不适合。水的话温度要常温。","大人位置":"大人坐在旁边，必要时扶住接的杯子。"},"shots":[{"name":"摆托盘","say":"下面放个托盘，洒了好收拾。"},{"name":"从米开始","say":"我们先练倒米，洒了扫一扫就好。"},{"name":"慢慢倾斜","say":"慢慢斜过去。"},{"name":"对准杯口","say":"眼睛看着下面的杯子。"},{"name":"快满了要停","say":"快满了，慢慢停。"},{"name":"再练倒水","say":"熟练了我们再来倒水。"}],"reactions":[{"if":"孩子倒得太快洒出来","then":"提醒「慢慢斜」。也可以用开口小一点的杯子倒，流速自然变慢。"},{"if":"孩子对不准杯口","then":"用大口的碗当目标，或大人扶住接的杯子。"},{"if":"孩子洒了觉得很挫折","then":"一起收拾并说「洒出来很正常，我们再来」。收拾本身也是生活练习。"}],"mistakes":["一开始就练倒水——洒了要擦很麻烦，孩子压力也大。先练米和豆。","没垫托盘——洒得到处都是，大人会开始紧张，孩子就不敢玩了。","杯子太轻——容易被碰倒，选有点重量的。"],"down":"倒进大口的碗；用有把手的杯子；量少一点；大人扶住接的容器。","up":"倒进小口的杯子；改成倒水；倒到指定的刻度；或用壶倒。","progress":["能不能控制速度不洒出来。","能不能倒进小口的容器。","能不能在快满时停住。"],"outro":"先练倒米、再练倒水，这个顺序能省下很多擦地的时间。下面垫个托盘，孩子和大人都轻松。"}' AS JSON))
WHERE `id` = 'A070';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '汤匙＋两个碗＋米或豆子'),
  `trains` = COALESCE(`trains`, '练握汤匙和舀的动作，直接连到自己吃饭。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一个碗装米，一个空碗。"},{"imageUrl":null,"instruction":"让孩子用汤匙把米舀到空碗。"},{"imageUrl":null,"instruction":"舀满一匙、稳稳送过去。"},{"imageUrl":null,"instruction":"洒了没关系。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大汤匙舀大颗的东西'),
  `harder` = COALESCE(`harder`, '小汤匙、或舀水。'),
  `tip` = COALESCE(`tip`, '舀的动作和吃饭一模一样——在游戏里练熟了，吃饭时就不容易洒。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一个碗装米、一个空碗，用汤匙舀过去。舀的动作和吃饭一模一样——在游戏里练熟了，吃饭时就不容易洒。","principles":["舀东西需要手腕做旋转和倾斜的组合动作。","这正是吃饭时把食物从碗里舀起来送进嘴里的动作。","在游戏中练习，没有「快点吃」的时间压力，孩子学得比较好。","舀满一匙需要判断「舀多少刚好」——太满会洒、太少送不到。","送的过程中手要保持水平不倾斜，这是持续的稳定控制。","握汤匙的方式也在这个过程中成熟，从整手抓到三指握。","另一只手可以扶住碗，这是双手分工的自然练习。","洒出来没关系，这是练习不是吃饭，压力小成功率就高。"],"prep":{"场地":"餐桌，下面垫托盘，两个碗并排。","器材":"汤匙＋两个碗＋米或豆子；汤匙选短柄、宽头的儿童汤匙。","安全检查":"三岁以下用米或大颗通心粉，避免小豆子误吞。碗用不易破的。","大人位置":"大人坐在旁边，示范舀的动作。"},"shots":[{"name":"握汤匙","say":"这样握汤匙。"},{"name":"舀起来","say":"舀满一匙。"},{"name":"稳稳送过去","say":"稳稳地送到另一个碗。"},{"name":"倒进去","say":"倒进去。"},{"name":"另一手扶碗","say":"另一只手扶住碗。"},{"name":"连结到吃饭","say":"吃饭的时候就是这个动作。"}],"reactions":[{"if":"孩子舀不起来","then":"把碗稍微倾斜，或用底部有弧度的碗。也可以在碗下垫一块布让它固定。"},{"if":"孩子送到一半就洒了","then":"提醒「舀少一点」。半匙比满匙好送，成功率高。"},{"if":"孩子整只手抓着汤匙","then":"这是正常的发展阶段。用短柄汤匙，慢慢就会变成三指握。"}],"mistakes":["汤匙太长太大——孩子握不好也舀不准，要用儿童尺寸。","要求舀满——半匙比较好送，先求成功再求量。","碗会滑动——在碗下垫湿布或防滑垫，固定住比较好操作。"],"down":"碗下垫防滑垫；舀半匙就好；用有弧度的碗比较好舀；大人扶住碗。","up":"舀满匙；换小汤匙；舀比较难舀的东西（小豆子、水）；或舀到小口的容器。","progress":["能不能舀起来不洒。","握汤匙的方式有没有从整手抓变成三指握。","另一只手会不会扶碗。"],"outro":"舀的动作和吃饭一模一样。在游戏里练熟了，餐桌上就不容易洒——而且没有「快点吃」的压力。"}' AS JSON))
WHERE `id` = 'A071';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '颜料或印泥＋纸'),
  `trains` = COALESCE(`trains`, '用手指作画，练指尖的控制和感觉。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把颜料倒在盘子里。"},{"imageUrl":null,"instruction":"让孩子用食指沾一点，点在纸上。"},{"imageUrl":null,"instruction":"点成一朵花、一串葡萄。"},{"imageUrl":null,"instruction":"每根手指都试试。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '整只手掌印'),
  `harder` = COALESCE(`harder`, '单根手指点出小点、或点在指定位置。'),
  `tip` = COALESCE(`tip`, '用食指单独点，比整只手抓着画更能练指尖控制。手指印画完记得洗手。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"用食指沾一点颜料，点在纸上。用食指单独点，比整只手抓着画更能练指尖控制。","principles":["用单根手指做动作，需要把那根手指从其他手指中分离出来。","这叫手指分化，是精细动作发展的重要指标。","手指分化不好的孩子，做动作时其他手指会跟着一起动。","这会影响握笔——握笔时只有三根手指该动，其他两根要稳住。","指尖沾颜料点在纸上时，要控制力道，太用力会变成一团。","颜料的触感对触觉敏感的孩子是很好的减敏机会，但要循序渐进。","每根手指都试试，可以看出哪根手指的控制比较差。","点成一朵花、一串葡萄，让重复的动作变成有意义的创作。"],"prep":{"场地":"餐桌铺报纸或塑胶垫，准备湿纸巾。","器材":"颜料或印泥＋纸；用可水洗的儿童颜料最安全。","安全检查":"用无毒可水洗的颜料。小小孩会把手指放进嘴里，要全程看着。对颜料气味敏感的孩子要注意通风。玩完洗手。","大人位置":"大人坐在旁边，示范用单根手指点。"},"shots":[{"name":"准备颜料","say":"颜料倒在盘子里，薄薄一层就好。"},{"name":"单根手指","say":"只用食指沾一点点。"},{"name":"点在纸上","say":"轻轻点一下。"},{"name":"点成图案","say":"点成一串葡萄！"},{"name":"换手指","say":"每根手指都试试看。"},{"name":"洗手","say":"玩完记得洗手。"}],"reactions":[{"if":"孩子整只手抓着按下去","then":"示范「只伸出一根手指」。可以帮他把其他手指轻轻握起来。"},{"if":"孩子不敢碰颜料","then":"触觉敏感的孩子很常见。先用棉花棒代替手指，或用比较干的印泥。绝不强迫。"},{"if":"孩子把手指放进嘴里","then":"全程看着，用无毒可水洗的颜料。也可以用食用色素调的颜料。"}],"mistakes":["让孩子整只手抓着玩——那就练不到手指分化了，单根手指才是重点。","强迫触觉敏感的孩子碰颜料——会造成更强的抗拒，要循序渐进。","用不可水洗的颜料——清理困难，大人会紧张，孩子就玩不尽兴。"],"down":"用棉花棒代替手指；用比较干的印泥；先在手背上试触感。","up":"每根手指分别点；点在指定的小圈圈里；用不同颜色排出规律；或点成指定的图案。","progress":["能不能只伸出一根手指。","每根手指都能独立控制吗。","点的位置准不准。"],"outro":"用单根手指点点画，练的是手指分化——这直接影响握笔时手指能不能各司其职。"}' AS JSON))
WHERE `id` = 'A072';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '小毛巾＋水'),
  `trains` = COALESCE(`trains`, '两只手往相反方向转，练手腕力气和双手配合。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把小毛巾弄湿。"},{"imageUrl":null,"instruction":"教孩子两只手抓住两端，往相反方向拧。"},{"imageUrl":null,"instruction":"把水拧出来。"},{"imageUrl":null,"instruction":"拧完拿去擦桌子。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '小毛巾、大人帮一只手'),
  `harder` = COALESCE(`harder`, '大一点的毛巾、自己拧干。'),
  `tip` = COALESCE(`tip`, '两只手做相反的动作是高阶的双手配合——洗手洗脸时顺便练，一天好几次。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组六（双侧协调与跨中线）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"两只手抓住毛巾两端，往相反方向拧。两只手做相反的动作是高阶的双手配合——洗手洗脸时顺便练，一天好几次。","principles":["拧毛巾时，左手顺时针转、右手逆时针转，两只手做的是完全相反的动作。","这是双手协调中最难的一种，叫双手反向协调。","大脑左右两个半球必须同时执行不同的动作指令并且协调时机。","拧的动作需要前臂做旋转，这个动作叫旋前和旋后。","前臂旋转的能力，和转门把、用螺丝起子、转钥匙都有关。","同时还需要很强的握力，才能抓住湿滑的毛巾不松手。","把水拧出来给了明确的目标和回馈——水越多代表拧得越用力。","这个动作每天洗手洗脸都会用到，是最容易融入生活的练习。"],"prep":{"场地":"洗手台或水槽边，孩子要构得到（必要时垫脚凳）。","器材":"小毛巾＋水；小毛巾比大毛巾好拧。","安全检查":"水温要适中。垫脚凳要稳。地板湿了会滑，要及时擦干。","大人位置":"大人站在旁边，示范两手反向的动作。"},"shots":[{"name":"弄湿毛巾","say":"先把毛巾弄湿。"},{"name":"抓住两端","say":"两只手抓住毛巾的两端。"},{"name":"反方向拧","say":"一只手往前转、一只手往后转。"},{"name":"水流出来","say":"看，水出来了！"},{"name":"用力一点","say":"再用力一点，把水拧干。"},{"name":"拿去擦桌子","say":"拧干了拿去擦桌子。"}],"reactions":[{"if":"孩子两只手往同一个方向转","then":"大人握住他的一只手固定不动，只让另一只手转。感觉到了再两手一起。"},{"if":"孩子拧不出水","then":"用小一点的毛巾，或先由大人拧一半再给他。"},{"if":"孩子抓不住湿毛巾","then":"毛巾拧成条状比较好抓。也可以先用比较不滑的布。"}],"mistakes":["两手同方向转——那只是把毛巾卷起来，拧不出水。要强调反方向。","毛巾太大——小小的手抓不住也拧不动，用小毛巾。","水太热——洗脸的温度就好。"],"down":"用小毛巾；大人固定一端让他单手转；先拧半干的毛巾。","up":"用大一点的毛巾；要求拧到几乎不滴水；或拧完直接拿去擦指定的地方。","progress":["两只手能不能反方向转。","能拧出多少水。","能不能自己完成不用帮忙。"],"outro":"两只手往相反方向转，是双手配合里最难的一种。每天洗手洗脸时顺便拧一下毛巾，一天就练好几次。"}' AS JSON))
WHERE `id` = 'A073';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一本书'),
  `trains` = COALESCE(`trains`, '一页一页翻，练指尖捏取薄东西的能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"共读的时候让孩子来翻页。"},{"imageUrl":null,"instruction":"从硬页书开始（好翻）。"},{"imageUrl":null,"instruction":"再换成一般的纸页书。"},{"imageUrl":null,"instruction":"一次只翻一页。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '硬页书'),
  `harder` = COALESCE(`harder`, '薄的纸页书，一次只翻一张。'),
  `tip` = COALESCE(`tip`, '翻薄薄的书页需要指尖很细的控制——每天共读的时候顺手就练了。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"共读的时候让孩子来翻页。翻薄薄的书页需要指尖很细的控制——每天共读顺手就练了。","principles":["翻书页需要用指尖捏住很薄的一张纸，这是最精细的指尖抓握。","要只翻起一页而不是好几页，还需要控制施力的大小和角度。","这个动作叫指尖对指尖的对捏，是握笔和拿小东西的基础。","翻的时候手腕要配合做小幅度的旋转，把书页带过去。","另一只手要压住书让它不合起来，这是双手分工。","硬页书比较好翻，一般纸页书需要更精细的控制，难度是递增的。","让孩子翻页，他在共读中就从被动听变成主动参与。","这个动作每天都有机会做，是最自然的日常练习。"],"prep":{"场地":"沙发或床上，孩子坐在大人腿上或旁边。","器材":"一本书；小小孩从硬页书开始，大一点用一般纸页书。","安全检查":"纸页可能割到手，动作慢一点。小小孩注意别撕破书——可以先给他一本「可以随便翻」的旧书。","大人位置":"大人坐在孩子旁边，把书拿在两人都看得到的位置。"},"shots":[{"name":"从硬页书开始","say":"小小孩先用硬页书，比较好翻。"},{"name":"指尖捏住边角","say":"用手指捏住书页的边边。"},{"name":"翻过去","say":"轻轻翻过去。"},{"name":"另一手压住","say":"另一只手压住书。"},{"name":"一次一页","say":"一次只翻一页喔。"},{"name":"换纸页书","say":"大一点可以换一般的书。"}],"reactions":[{"if":"孩子一次翻好几页","then":"正常的。可以在页角贴一个小贴纸当抓握点，或用硬页书先练。"},{"if":"孩子翻不起来","then":"大人先把页角翘起一点点，让他接手。或换硬页书。"},{"if":"孩子把书撕破","then":"给他一本专门的旧书随便翻。好书先由大人翻，慢慢再让他试。"}],"mistakes":["一开始就用薄纸页的书——翻不起来会挫折，从硬页书开始。","大人一直帮他翻——翻页是很好的练习机会，让他来。","孩子撕破就不让他碰书——给他专用的旧书，保护好书就行。"],"down":"用硬页书；在页角贴小贴纸当抓握点；大人先翘起一角。","up":"换一般纸页书；要求一次只翻一页；翻到指定的页数；或倒着往回翻。","progress":["能不能一次只翻一页。","能不能翻薄的纸页。","另一只手会不会压住书。"],"outro":"共读的时候把翻页的工作交给孩子。每天几次，指尖的控制就在不知不觉中练出来了。"}' AS JSON))
WHERE `id` = 'A074';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '有扣子和拉链的衣服'),
  `trains` = COALESCE(`trains`, '练两只手配合，也是自己穿衣的关键。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先在脱下来的衣服上练（放桌上比较好操作）。"},{"imageUrl":null,"instruction":"扣子：一只手把扣子塞进洞，另一只手拉。"},{"imageUrl":null,"instruction":"拉链：先对准下面的插销，再往上拉。"},{"imageUrl":null,"instruction":"熟练了再穿在身上练。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大扣子、粗拉链'),
  `harder` = COALESCE(`harder`, '小扣子、细拉链，或穿在身上自己扣。'),
  `tip` = COALESCE(`tip`, '衣服放在桌上比穿在身上好练——先学会动作，再搬到自己身上。早上出门前时间紧，可以留到假日慢慢练。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"先在脱下来的衣服上练，放桌上比较好操作。衣服放在桌上比穿在身上好练——先学会动作，再搬到自己身上。","principles":["扣扣子需要两只手做不同的事：一手把扣子塞进洞、一手拉住布。","这是双手分工中难度较高的一种，还需要在看不太清楚的角度操作。","拉链更复杂——要先把插销对准并插到底，才拉得上去。","插销对位需要很精准的双手配合和视觉定位。","穿在身上时角度是反的、看不清楚，难度会大幅提高。","所以先在桌上练，把动作学会了再搬到身上，这个顺序很重要。","这两个动作是自己穿衣服的关键，直接影响孩子的生活自理。","早上出门时间紧，练习最好留到假日慢慢来，不然大人会忍不住接手。"],"prep":{"场地":"餐桌，把衣服平放在桌上。","器材":"有扣子和拉链的衣服；扣子大一点、洞松一点的最好练。","安全检查":"拉链可能夹到皮肤或下巴，穿在身上练时要提醒「下巴抬高」。扣子松脱要注意误吞。","大人位置":"大人坐在孩子同一侧（不要面对面），示范时角度才一致。"},"shots":[{"name":"衣服放桌上","say":"先把衣服放桌上练，比较好看清楚。"},{"name":"扣扣子","say":"一只手把扣子塞进洞，另一只手拉。"},{"name":"拉出来","say":"从另一边把扣子拉出来。"},{"name":"拉链对插销","say":"先把下面的插销插到底。"},{"name":"往上拉","say":"一只手拉住下面，一只手往上拉。"},{"name":"穿在身上练","say":"学会了再穿在身上试试。"}],"reactions":[{"if":"孩子扣不进去","then":"换大扣子、松扣洞的衣服。也可以在扣洞旁边贴个记号标示方向。"},{"if":"孩子拉链插销对不准","then":"这是最难的一步。大人可以先帮他插好，让他练往上拉。熟了再练对插销。"},{"if":"孩子在身上就做不到","then":"退回桌上练。角度反过来确实难很多，不用急着搬到身上。"}],"mistakes":["一开始就穿在身上练——角度反、看不清楚，难度太高。先在桌上。","早上出门前才练——时间压力下大人会忍不住接手，孩子也焦虑。留到假日。","扣子太小、扣洞太紧——先用好操作的衣服建立成功经验。"],"down":"在桌上练；用大扣子松扣洞的衣服；拉链由大人插好插销让他只拉。","up":"穿在身上操作；用小扣子；练背后的扣子；或计时挑战。","progress":["能不能在桌上完成。","能不能穿在身上完成。","拉链的插销能不能自己对准。"],"outro":"先在桌上把动作学会，再搬到身上。而且留到假日练——早上出门前时间紧，大人一定会忍不住接手。"}' AS JSON))
WHERE `id` = 'A075';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '厚纸板打几个洞＋鞋带'),
  `trains` = COALESCE(`trains`, '把线穿过洞，练手眼配合和精准。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在厚纸板上打一排洞（或用洞洞板）。"},{"imageUrl":null,"instruction":"让孩子把鞋带穿过去。"},{"imageUrl":null,"instruction":"可以穿成一条线，或来回穿。"},{"imageUrl":null,"instruction":"进阶：沿着画好的图形穿。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大洞、少数几个'),
  `harder` = COALESCE(`harder`, '小洞、洞多，或穿出图案。'),
  `tip` = COALESCE(`tip`, '纸盘剪个形状、打几个洞，就是免费的穿线板。鞋带的硬头端最好穿。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十（手眼协调与视动整合）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"纸盘剪个形状、打几个洞，就是免费的穿线板。鞋带的硬头端最好穿。","principles":["把线穿过洞需要精准的手眼配合和空间定位。","线是软的，孩子必须捏住靠近头端的位置才控制得住方向。","这需要对工具特性的理解——捏太后面就没办法对准。","穿过去之后要从另一面把线拉出来，这是双手在看不见处的配合。","沿着图形穿需要按顺序找到下一个洞，这是视觉追踪和顺序执行。","洞的大小和线的粗细可以精细地调整难度。","这个动作和日后穿鞋带、缝纫是同一个模式。","材料完全可以自制，纸盘打几个洞就好。"],"prep":{"场地":"餐桌，把洞洞板和鞋带摆好。","器材":"厚纸板打几个洞＋鞋带；纸盘、鞋盒盖都可以拿来打洞。","安全检查":"鞋带不要太长，避免缠绕脖子。纸板的洞边缘要平滑，必要时用胶带包边。","大人位置":"大人坐在旁边，必要时帮忙从背面把线拉出来。"},"shots":[{"name":"自制洞洞板","say":"纸盘打几个洞就可以了。"},{"name":"捏住硬头","say":"捏住鞋带硬硬的那一头。"},{"name":"对准洞口","say":"对准洞，穿进去。"},{"name":"从背面拉出","say":"从后面把它拉出来。"},{"name":"连续穿","say":"一个洞、一个洞，穿下去。"},{"name":"沿着图形穿","say":"这次沿着这个星星穿。"}],"reactions":[{"if":"孩子穿不进去","then":"把洞打大一点，或用更硬的线（鞋带、包塑料的绳子）。"},{"if":"孩子捏得太后面控制不住","then":"示范「捏住靠近头的地方」。可以在鞋带上做个记号提示捏的位置。"},{"if":"孩子穿一两个就不想穿了","then":"洞少一点（三四个就好），或做成有意义的图案增加动机。"}],"mistakes":["洞太小、线太软——穿不过去会挫折。洞要大、线要硬。","鞋带太长——难操作也有缠绕风险，三十厘米左右就好。","洞太多——刚开始三五个就够，太多会失去耐心。"],"down":"洞打大一点；洞只有三四个；用很硬的线；大人帮忙从背面拉。","up":"洞变小；洞的数量增加；沿着图形按顺序穿；或穿出交叉的图案。","progress":["能不能自己对准洞口穿进去。","能连续穿几个洞。","能不能按顺序沿着图形穿。"],"outro":"纸盘打几个洞，就是免费的穿线板。记得教他捏住鞋带硬硬的那一头，才控制得住方向。"}' AS JSON))
WHERE `id` = 'A076';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '积木、乐高或拼插玩具'),
  `trains` = COALESCE(`trains`, '一只手固定、一只手操作，练双手分工。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"玩需要两只手的玩具：拼乐高、组积木、开盒子。"},{"imageUrl":null,"instruction":"一只手拿着底座，一只手装上去。"},{"imageUrl":null,"instruction":"注意他是不是只用一只手。"},{"imageUrl":null,"instruction":"做不到就帮他扶住底座。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大块好组的积木'),
  `harder` = COALESCE(`harder`, '小块的、需要用力压紧的。'),
  `tip` = COALESCE(`tip`, '「一手稳、一手动」是很多生活动作的基础——写字时压住纸、吃饭时扶住碗，都是这个能力。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组六（双侧协调与跨中线）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"玩需要两只手的玩具：一只手拿着底座，一只手装上去。「一手稳、一手动」是很多生活动作的基础。","principles":["双手分工的基本模式是：一只手稳定物品，另一只手进行操作。","这个模式在生活中无所不在——写字时压住纸、吃饭时扶住碗、开瓶盖时握住瓶子。","稳定手的工作看起来不重要，但它决定了操作手能不能精准。","稳定手不会帮忙的孩子，写字时纸会滑、吃饭时碗会移动。","拼乐高、组积木、开盒子，都需要这两只手同时工作。","要注意孩子是不是只用一只手做全部的事，另一只手完全没参与。","如果发现这个现象，可以先由大人帮他扶住底座，让他专心练操作手。","随着能力提升，再慢慢把稳定的工作交还给他。"],"prep":{"场地":"餐桌或地板，把玩具摆好。","器材":"积木、乐高或拼插玩具；任何需要两只手的玩具都可以。","安全检查":"小零件注意误吞，三岁以下用大颗粒。检查玩具没有尖锐边缘。","大人位置":"大人坐在旁边，观察孩子的另一只手有没有参与。"},"shots":[{"name":"观察双手","say":"看看他的另一只手在做什么。"},{"name":"一手拿底座","say":"一只手拿着底座。"},{"name":"一手装上去","say":"另一只手把积木装上去。"},{"name":"两手配合","say":"两只手一起工作。"},{"name":"大人帮忙扶","say":"做不到就先帮他扶住底座。"},{"name":"连结生活","say":"写字压住纸，也是同一件事。"}],"reactions":[{"if":"孩子只用一只手，另一只手放着","then":"大人先帮他扶住底座，让他专心用操作手。熟练了再引导另一只手来扶。"},{"if":"孩子的底座一直滑动","then":"在底座下垫防滑垫，或选有重量的底座。"},{"if":"孩子两只手都在动、乱成一团","then":"明确指定「这只手不能动，只有这只手可以动」。"}],"mistakes":["大人一直帮他扶——刚开始可以，但要慢慢把工作交还给他。","忽略另一只手的状态——这个活动的重点就在稳定手有没有参与。","玩具太难——一手就能完成的玩具练不到双手分工。"],"down":"大人帮忙扶住底座；底座下垫防滑垫；选大颗粒好操作的玩具。","up":"底座换成不稳的（要真的扶住）；玩更精细的拼插玩具；或两手各操作不同的东西。","progress":["另一只手会不会主动去扶。","能不能维持稳定不让底座移动。","需不需要大人帮忙。"],"outro":"「一手稳、一手动」是很多生活动作的基础。玩玩具时多看一眼——他的另一只手，有没有在工作？"}' AS JSON))
WHERE `id` = 'A077';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '面团、饼干模具、擀面棍'),
  `trains` = COALESCE(`trains`, '在做点心的过程中练一整套手部动作。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一起揉面团。"},{"imageUrl":null,"instruction":"用擀面棍擀平。"},{"imageUrl":null,"instruction":"用模具压出形状。"},{"imageUrl":null,"instruction":"进烤箱（或就当玩面团）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '只揉和压'),
  `harder` = COALESCE(`harder`, '擀平、压模、装饰全套来。'),
  `tip` = COALESCE(`tip`, '做点心把揉、压、擀、捏全部练一遍，最后还能吃——这是孩子最有动力的手部训练。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组七（手部精细·抓握与力量）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"一起揉面团、擀平、用模具压出形状。做点心把揉、压、擀、捏全部练一遍，最后还能吃——这是孩子最有动力的手部训练。","principles":["揉面团用到整只手掌和手指，是全手的肌力训练。","擀面棍需要双手同时施力并且力道均匀，才擀得平。","这是双手对称协调加上力道控制的综合练习。","用模具压形状需要垂直下压并且稳住，这是手掌根部的用力。","把压好的饼干拿起来放到烤盘上，需要很轻的指尖控制，不然会变形。","这四个动作涵盖了手部从粗到细的完整范围。","整个过程有明确的目标和顺序，也是很好的步骤执行练习。","最后能吃到自己做的东西，动机是所有活动里最强的。"],"prep":{"场地":"厨房或餐桌，铺一块干净的桌垫，孩子要构得到（必要时垫脚凳）。","器材":"面团、饼干模具、擀面棍；不烤的话用玩面团也可以。","安全检查":"烤箱一定由大人操作，孩子不能碰。垫脚凳要稳。生面团别让孩子吃太多（生面粉有食安风险）。事先洗手。","大人位置":"大人和孩子一起做，烤箱的部分由大人负责。"},"shots":[{"name":"洗手准备","say":"做点心前要先洗手。"},{"name":"揉面团","say":"用手掌用力揉。"},{"name":"擀平","say":"两只手一起推，力气要一样大。"},{"name":"压模具","say":"用力往下压。"},{"name":"轻轻拿起","say":"轻轻拿起来，不要弄坏。"},{"name":"烤好开吃","say":"烤好了！"}],"reactions":[{"if":"孩子擀不平","then":"面团先压扁一点再擀。或大人握着他的手一起擀，感觉双手同时用力。"},{"if":"孩子压模具压不断","then":"面团擀薄一点，或选边缘锐利一点的模具。"},{"if":"孩子拿起来就变形","then":"用薄的铲子帮忙托起来。或把面团冰一下变硬比较好拿。"}],"mistakes":["让孩子碰烤箱——绝对由大人操作，这是不能妥协的。","大人主导全部流程——每个步骤都让孩子参与，他才练得到。","让孩子吃太多生面团——生面粉有食安风险，提醒「烤好才能吃」。"],"down":"只做揉和压两个步骤；面团先由大人擀好；用大的模具。","up":"自己擀到指定厚度；用小的、复杂的模具；或自己调面团的配方。","progress":["能不能擀得平均。","压模具能不能一次压断。","拿起来会不会变形。"],"outro":"做点心把揉、擀、压、捏全部练一遍，从大力气到小力气都涵盖了。最后还能吃——动机最强的手部训练。"}' AS JSON))
WHERE `id` = 'A078';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '活动每一根手指，为写字画画热身。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"手指数数：一根一根伸出来、再一根一根收回去。"},{"imageUrl":null,"instruction":"比手势：比一、二、三、OK、爱心。"},{"imageUrl":null,"instruction":"手指走路：食指中指当腿在桌上走。"},{"imageUrl":null,"instruction":"开合手掌十次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着做几个'),
  `harder` = COALESCE(`harder`, '单根手指独立动作，或两只手做不同手势。'),
  `tip` = COALESCE(`tip`, '写字或画画前先做一下手指操，手会灵活很多——就像运动前要热身一样。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组八（手指操作与灵巧）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"写字或画画前先做一下手指操，手会灵活很多——就像运动前要热身一样。","principles":["手部和身体一样，活动前先热身能提高灵活度和控制力。","手指操让每一根手指都活动到，增加血流和关节活动度。","手指数数需要把手指一根一根分开，这是手指分化的直接练习。","比手势（一、二、三、OK、爱心）需要不同手指的组合，难度递增。","手指走路让食指和中指交替移动，是很好的手指独立控制练习。","开合手掌是手部内在肌的收缩放松，能改善手部的紧绷。","整套做下来只要一两分钟，却能明显改善接下来的书写表现。","这个习惯养成之后，孩子写作业前会自己做，是很好的自我准备。"],"prep":{"场地":"书桌前或任何地方，坐着站着都可以。","器材":"不需要任何东西。","安全检查":"动作要慢、不要用力扳手指。关节不舒服就停。","大人位置":"大人面对孩子一起做，动作放大放慢。"},"shots":[{"name":"手指数数","say":"一根一根伸出来——一、二、三、四、五。"},{"name":"收回去","say":"再一根一根收回去。"},{"name":"比手势","say":"比一、比二、比 OK、比爱心。"},{"name":"手指走路","say":"食指和中指当腿，在桌上走路。"},{"name":"开合手掌","say":"手张开、握起来，做十次。"},{"name":"接着写字","say":"做完手指操，我们来写字。"}],"reactions":[{"if":"孩子手指分不开","then":"用另一只手帮忙把手指一根一根按下去。慢慢就能自己分开了。"},{"if":"孩子比不出 OK 或爱心","then":"先做简单的一、二、三。复杂手势需要更成熟的分化能力。"},{"if":"孩子觉得无聊","then":"配上儿歌或口令，或做成「跟着我比」的模仿游戏。"}],"mistakes":["用力扳手指——关节会不舒服，动作要轻要慢。","做太久——一两分钟就够，这是热身不是训练。","写字前不做——就像运动前不热身，效果会差很多。"],"down":"只做手指数数和开合手掌；用另一只手帮忙分开手指。","up":"加入复杂手势；两只手同时做不同手势；加快速度；或倒着数回来。","progress":["能不能一根一根分开手指。","能比出几种手势。","会不会自己在写字前做。"],"outro":"写字前做一两分钟手指操，手会灵活很多。就像运动前要热身——这个习惯值得从小养成。"}' AS JSON))
WHERE `id` = 'A079';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '夹子、豆子、纸、面团'),
  `trains` = COALESCE(`trains`, '把这个模组的活动串起来玩一轮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：夹十个夹子。"},{"imageUrl":null,"instruction":"第二关：夹二十颗豆子到另一个碗。"},{"imageUrl":null,"instruction":"第三关：单手揉三个纸球投篮。"},{"imageUrl":null,"instruction":"第四关：捏面团做一个东西。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关减半'),
  `harder` = COALESCE(`harder`, '加上计时，或用非惯用手做。'),
  `tip` = COALESCE(`tip`, '手部能力要练得多、练得杂——不同的抓法、不同的力道，手才会灵活。每天十分钟就够。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组七～九（手部精细 · 手指灵巧 · 工具使用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"把这个模组的活动串成四关闯一轮。手部能力要练得多、练得杂——不同的抓法、不同的力道，手才会灵活。","principles":["手部能力不是靠单一动作练出来的，而是靠多样的抓握经验累积。","捏夹子用三指、揉纸球用整个手掌、夹豆子用工具、捏面团用指尖——每种都不一样。","这种多样性让手部的各种肌肉和控制模式都得到刺激。","四关涵盖了不同的力道：夹子要大力、夹豆子要轻巧、揉纸要持续、捏面团要变化。","力道的范围越广，孩子在真实生活中的适应力就越好。","闯关的形式让重复的练习有了结构和终点，孩子比较撑得住。","每关有明确的次数目标，做完就好，不会变成没完没了的练习。","每天十分钟就够——手部训练重在频率而不是单次时长。"],"prep":{"场地":"餐桌上摆四个区域，或依序进行。","器材":"夹子、豆子（或棉花球）、废纸、面团、纸箱、两个碗。","安全检查":"每关的安全要求照该活动的原则。三岁以下用棉花球代替豆子。","大人位置":"大人当关主，负责计数和准备材料。"},"shots":[{"name":"介绍四关","say":"今天有四关，全部过了就成功！"},{"name":"第一关夹夹子","say":"第一关：夹十个夹子。"},{"name":"第二关夹豆子","say":"第二关：夹二十颗到另一个碗。"},{"name":"第三关揉纸球","say":"第三关：单手揉三个纸球投篮。"},{"name":"第四关捏面团","say":"第四关：捏一个东西出来。"},{"name":"全部完成","say":"四关都过了！"}],"reactions":[{"if":"孩子某一关做不完","then":"当场降低次数。闯关是为了建立信心，不是考试。"},{"if":"孩子只想做喜欢的那一关","then":"让他自己排顺序，或让他设计其中一关的规则。"},{"if":"孩子做到一半手酸了","then":"休息一下再继续。手部肌肉小、容易累，这很正常。"}],"mistakes":["次数订太多——每关十到二十次就够，太多会手酸也会失去兴趣。","每天做很久——十分钟就够，频率比时长重要。","四关都是同一种抓法——要刻意涵盖不同的抓握和力道。"],"down":"减到两三关；每关次数减半；选他比较拿手的项目。","up":"加到五关；提高次数；加上计时；或让孩子自己设计关卡。","progress":["每关的成绩记录下来（夹几个、几秒完成）。","一个月后再测一次，比较进步。","手酸的时间有没有变长。"],"outro":"手部能力要练得多、练得杂。四关不同的抓法和力道，每天十分钟——频率比时长重要。"}' AS JSON))
WHERE `id` = 'A080';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '大张的纸＋胶带＋蜡笔'),
  `trains` = COALESCE(`trains`, '站着在墙上画，练手臂的稳定（比坐着画更基础）。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把大张的纸贴在墙上。"},{"imageUrl":null,"instruction":"让孩子站着涂鸦。"},{"imageUrl":null,"instruction":"画大大的圈、长长的线。"},{"imageUrl":null,"instruction":"画多久都可以。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '随意涂鸦'),
  `harder` = COALESCE(`harder`, '画指定的形状或跟着大人画。'),
  `tip` = COALESCE(`tip`, '「先站后坐、先大后小」——站着在墙上画能练到肩膀和手臂的稳定，这是握笔稳的基础。别急着让孩子坐在桌前写小字。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把大张的纸贴在墙上，让孩子站着画。「先站后坐、先大后小」——站着在墙上画能练到肩膀和手臂的稳定，这是握笔稳的基础。","principles":["在垂直面上画画时，手腕必须维持在伸展的位置，这是握笔最理想的手腕角度。","在水平桌面上画，手腕容易垂下来或压在桌上，反而练不到这个姿势。","站着画时手臂要对抗重力，肩膀的肌肉必须持续用力稳定。","肩膀稳定是手部精细动作的前提——近端稳了，远端才灵活。","肩膀不稳的孩子写字时手臂会晃、容易累、字会越写越歪。","画大动作用到的是整个肩膀和手臂，而不只是手指。","发展的顺序是从大动作到小动作，先练得动肩膀，才练得动手指。","很多家长急着让孩子坐在桌前写小字，跳过了这一步，反而事倍功半。"],"prep":{"场地":"一面可以贴纸的墙，孩子站着时纸的中心约在他的胸口到眼睛高度。","器材":"大张的纸（海报纸、月历纸背面）＋胶带＋蜡笔；也可以用白板或浴室的磁砖墙。","安全检查":"胶带要贴牢，纸掉下来会吓到孩子。用可水洗的蜡笔，万一画到墙上好清理。地面清空避免绊倒。","大人位置":"大人站在孩子旁边一起画，示范画大圈大线。"},"shots":[{"name":"贴纸上墙","say":"我们把纸贴在墙上。"},{"name":"手腕角度","say":"站着画，手腕自然就翘起来了。"},{"name":"画大圈","say":"画一个好大好大的圈！"},{"name":"画长线","say":"从这边画到那边。"},{"name":"上上下下","say":"往上画、往下画。"},{"name":"尽情画","say":"画多久都可以。"}],"reactions":[{"if":"孩子只在小范围画","then":"大人示范画很大的圈，或在纸的四个角贴贴纸，请他「画到贴纸那里」。"},{"if":"孩子画到墙上","then":"把纸贴大一点、范围超出他画得到的区域。用可水洗蜡笔就不怕。"},{"if":"孩子站不久","then":"站三五分钟就很好了。累了可以坐在小板凳上，但纸还是贴在墙上（保持垂直面）。"}],"mistakes":["纸贴太低——孩子要弯腰，手腕的角度就跑掉了。纸要贴在胸口到眼睛的高度。","纸太小——限制了大动作。要用大张的纸，让他画得开。","急着让孩子坐在桌前写小字——先站后坐、先大后小，顺序不能跳。"],"down":"纸贴更大张；用粗的蜡笔比较好握；不要求画什么，随意涂鸦就好。","up":"画指定的形状；画满整张纸；或画到指定的位置（贴纸当目标）。","progress":["画的范围有多大——只在中间一小块还是会画满整张。","是用整只手臂画还是只动手指。","能站着画多久。"],"outro":"「先站后坐、先大后小」——站着在墙上画，练的是肩膀和手臂的稳定。这一步做够了，握笔自然就稳。"}' AS JSON))
WHERE `id` = 'A081';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '折断的短蜡笔（约一节手指长）'),
  `trains` = COALESCE(`trains`, '用短蜡笔自然练出正确的握笔方式。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把蜡笔折成一小段（约3厘米）。"},{"imageUrl":null,"instruction":"给孩子用这个短蜡笔画画。"},{"imageUrl":null,"instruction":"太短了握不住整只，手指自然会捏着用。"},{"imageUrl":null,"instruction":"画什么都可以。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '短一点的蜡笔、随意画'),
  `harder` = COALESCE(`harder`, '画细一点的线条。'),
  `tip` = COALESCE(`tip`, '这是最简单也最有效的握笔矫正法——蜡笔太短，孩子只能用三根手指捏着，握姿自然就对了。比一直提醒「手要这样拿」有用得多。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把蜡笔折成一小段，大约三厘米。太短了握不住整只，手指自然会捏着用——这是最简单也最有效的握笔矫正法。","principles":["正确的握笔姿势是用大拇指、食指、中指三根手指捏住笔。","无名指和小指要弯起来靠在手掌里，负责稳定整只手。","孩子握整只长蜡笔时，五根手指容易全部抓上去，变成整手抓握。","蜡笔只有三厘米时，物理上就放不下五根手指，只能用三根捏着。","这叫环境限制法——用工具的设计逼出正确的动作，而不是靠口头提醒。","一直说「手要这样拿」会让孩子觉得画画有压力，效果也不好。","短蜡笔让正确的握姿自然发生，孩子完全不觉得自己在被矫正。","这个方法对两到六岁的孩子几乎都有效，是最值得推荐的一招。"],"prep":{"场地":"餐桌或墙上贴纸，都可以用短蜡笔。","器材":"折断的短蜡笔（约3厘米）＋纸；粗一点的蜡笔折起来比较好握。","安全检查":"折断的蜡笔可能有尖角，先磨圆一点。太短的蜡笔（不到2厘米）小小孩可能误吞，三厘米是安全又有效的长度。","大人位置":"大人也用短蜡笔一起画，不要只有孩子用。"},"shots":[{"name":"折蜡笔","say":"我们把蜡笔折成一小段。"},{"name":"长蜡笔的握法","say":"你看，长的蜡笔容易整只手抓住。"},{"name":"短蜡笔的握法","say":"换成短的，只能用三根手指捏着。"},{"name":"开始画","say":"就这样画，什么都可以。"},{"name":"看手指","say":"另外两根手指会自己弯起来。"},{"name":"不用提醒","say":"完全不用一直说「手要这样拿」。"}],"reactions":[{"if":"孩子觉得短蜡笔不好用","then":"先让他自由画，别要求画什么。用惯了就好。也可以用粗一点的短蜡笔。"},{"if":"孩子还是整手抓","then":"再折短一点（2.5厘米）。短到物理上抓不住，姿势就会改。"},{"if":"孩子抗议「为什么蜡笔断掉」","then":"一开始就折成短的给他，别在他面前折断他喜欢的蜡笔。"}],"mistakes":["一直口头提醒握笔姿势——效果差又伤画画的兴致。用短蜡笔让它自然发生。","蜡笔留太长——超过五厘米就失去效果了，三厘米最理想。","只有孩子用短蜡笔——大人一起用，孩子不会觉得是被针对。"],"down":"用粗一点的短蜡笔比较好握；不要求画什么，自由涂鸦。","up":"换成短的彩色铅笔（更细，需要更精准的控制）；或用短蜡笔画指定的形状。","progress":["拿短蜡笔时是不是三指捏握。","换回长笔时姿势还维持得住吗。","无名指和小指有没有自然弯进掌心。"],"outro":"蜡笔折成三厘米，孩子只能用三根手指捏着——握姿自然就对了。这比一直提醒「手要这样拿」有用得多。"}' AS JSON))
WHERE `id` = 'A082';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '托盘＋一层薄薄的米、沙或面粉'),
  `trains` = COALESCE(`trains`, '用手指在沙上画，先感觉线条再用笔画。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在托盘里铺一层薄薄的米或面粉。"},{"imageUrl":null,"instruction":"让孩子用食指在上面画线、画圈。"},{"imageUrl":null,"instruction":"摇一摇就能重来。"},{"imageUrl":null,"instruction":"可以画简单的图形或字。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '随意画'),
  `harder` = COALESCE(`harder`, '跟着画出指定的线条或形状。'),
  `tip` = COALESCE(`tip`, '用手指先感觉「怎么画」，之后拿笔就容易多了——写错了摇一摇就消失，孩子完全没有压力。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"托盘里铺一层薄薄的米或面粉，用食指在上面画。写错了摇一摇就消失，孩子完全没有压力。","principles":["用手指直接画，少了「握笔」这一层，孩子可以专心感觉线条的路径。","画的时候指尖接触沙或米，有丰富的触觉回馈，能加强动作的记忆。","这种多感官的输入，让「怎么画出一个圆」这件事记得更牢。","摇一摇就消失的设计，去掉了「画错了」的心理压力。","很多孩子怕写错、怕被擦掉，沙盘完全没有这个问题。","用单根食指画，同时也是手指分化的练习。","可以先在沙盘上练会某个形状或字，再拿笔在纸上画，成功率会高很多。","材料就是家里的米或面粉，玩完还能收回去。"],"prep":{"场地":"餐桌，托盘放在孩子正前方。","器材":"一个有边的托盘＋一层薄薄的米、沙或面粉；铺约0.5厘米厚就够。","安全检查":"小小孩注意别抓起来放进嘴里或撒出来。用米或面粉比沙子安全。对面粉过敏的孩子改用米。玩完洗手。","大人位置":"大人坐在旁边，示范用食指画。"},"shots":[{"name":"铺沙盘","say":"托盘里铺一层薄薄的米。"},{"name":"单指画线","say":"用食指画一条线。"},{"name":"画圈","say":"画一个圈圈。"},{"name":"摇一摇消失","say":"摇一摇，就不见了！"},{"name":"再画一次","say":"我们再画一次。"},{"name":"练形状或字","say":"也可以练形状，或写自己的名字。"}],"reactions":[{"if":"孩子把米抓起来撒","then":"很正常，这也是触觉探索。规定「米要留在托盘里」，撒出来一起扫。"},{"if":"孩子画不出线","then":"米铺太厚了。薄一点，看得到托盘底部的颜色最好。"},{"if":"孩子只想玩米不想画","then":"先让他玩够触感。玩熟了再引导画线，不用急。"}],"mistakes":["米铺太厚——画不出清楚的线，薄薄一层最好。","用没有边框的盘子——米会撒得到处都是，一定要用有边的托盘。","要求画得像——沙盘的价值在于零压力，别在这里要求品质。"],"down":"只画自由的线条不要求形状；托盘小一点范围缩小。","up":"画指定的形状；练写简单的字；闭上眼睛画；或用两根手指同时画。","progress":["能不能用单根食指画出清楚的线。","能画出哪些形状。","在沙盘上会画了，拿笔在纸上画得出来吗。"],"outro":"先用手指感觉「怎么画」，之后拿笔就容易多了。摇一摇就重来，孩子画得毫无压力。"}' AS JSON))
WHERE `id` = 'A083';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋笔'),
  `trains` = COALESCE(`trains`, '练最基本的线条控制（横线、竖线）。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在纸的两边画两个点。"},{"imageUrl":null,"instruction":"让孩子把两点连起来。"},{"imageUrl":null,"instruction":"先画横线，再画竖线。"},{"imageUrl":null,"instruction":"可以说成「帮小车开到家」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两点很近、线很短'),
  `harder` = COALESCE(`harder`, '距离拉长，或在两条平行线中间画不出界。'),
  `tip` = COALESCE(`tip`, '直线是所有字的基本笔画。用「把小车开回家」「帮蚂蚁搭桥」的说法，孩子会更投入。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"在纸的两边画两个点，让孩子把它们连起来。用「把小车开回家」的说法，孩子会更投入。","principles":["直线是所有字和图形最基本的笔画。","要画出直线，手必须朝一个固定方向持续移动而不偏离。","这需要动作的方向控制和持续的稳定度。","眼睛要一直盯着终点，手才会朝那个方向走，这是视觉引导动作。","一直看着笔尖而不看终点的孩子，线条会歪来歪去。","横线和竖线用到的手部动作不同——横线靠手腕和前臂，竖线靠整只手臂。","两种都要练，因为字里面两种笔画都有。","给一个故事情境（小车开回家、蚂蚁过桥），孩子的动机会高很多。"],"prep":{"场地":"餐桌，纸放正对孩子，另一只手压住纸。","器材":"纸＋笔；粗一点的蜡笔或彩色笔比较好画。","安全检查":"笔不要太尖。提醒孩子不要把笔放进嘴里。","大人位置":"大人坐在孩子旁边（同侧），先示范一次。"},"shots":[{"name":"画两个点","say":"这里有一台车，这里是家。"},{"name":"眼睛看终点","say":"眼睛看着家，不要看笔。"},{"name":"画横线","say":"把小车开回家。"},{"name":"另一手压纸","say":"另一只手要压住纸。"},{"name":"画竖线","say":"这次是从上往下。"},{"name":"加长距离","say":"这次车子要开更远。"}],"reactions":[{"if":"孩子的线歪得很厉害","then":"距离缩短。也提醒「眼睛看终点」，这一句通常立刻见效。"},{"if":"孩子的纸一直滑动","then":"提醒另一只手压住纸。或在纸下垫防滑垫。"},{"if":"孩子不想画","then":"加故事情境：「小车要回家」「蚂蚁要过桥」「帮小鸟找妈妈」。"}],"mistakes":["一开始距离就拉很长——线越长越难画直，从短的开始。","忘记提醒压住纸——纸会滑，线一定歪。","只练横线不练竖线——两种用到的动作不同，都要练。"],"down":"两点距离缩短；在两点之间先画一条淡淡的引导线；用粗笔比较好控制。","up":"距离加长；画斜线；画两点之间的线要经过中间的小圈；或画平行的好几条线。","progress":["线的歪斜程度有没有改善。","会不会看着终点画。","另一只手会不会压住纸。"],"outro":"直线是所有字的基本笔画。教他一句话——眼睛看着终点，不要看笔尖，线自然就直了。"}' AS JSON))
WHERE `id` = 'A084';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋笔'),
  `trains` = COALESCE(`trains`, '练画圆的控制，是很多字和图形的基础。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人先画一个大圈示范。"},{"imageUrl":null,"instruction":"让孩子跟着画。"},{"imageUrl":null,"instruction":"画成太阳、气球、脸。"},{"imageUrl":null,"instruction":"从大圈慢慢画到小圈。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '画大圈、不必闭合'),
  `harder` = COALESCE(`harder`, '画小一点的圈，或圈要接得起来。'),
  `tip` = COALESCE(`tip`, '三岁左右能画出接得起来的圆圈是常见的发展指标。画不圆很正常，多画几次会越来越好。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"画一个圈，接起来就好。三岁左右能画出接得起来的圆圈是常见的发展指标——画不圆很正常，多画几次会越来越好。","principles":["画圆需要手做连续的曲线运动并且回到起点。","这比画直线难，因为方向要持续改变而不是固定。","手腕、前臂和肩膀要协调配合，才画得出平顺的弧线。","能画出封闭的圆圈（起点和终点接起来），代表动作的计划和控制已经成熟到一定程度。","发展参考：两岁多能画出乱圈，三岁左右能画出接得起来的圆。","圆是很多字和图形的基础，画得出圆才画得出更复杂的形状。","把圆变成太阳、气球、脸，让练习有意义也有成品。","从大圈慢慢画到小圈，难度自然递增——小圈需要更精细的控制。"],"prep":{"场地":"餐桌或墙上贴纸；先在墙上画大圈更容易。","器材":"纸＋笔；大张的纸让他画得开。","安全检查":"笔不要太尖。","大人位置":"大人坐在孩子旁边，先画一个大圈示范。"},"shots":[{"name":"大人示范","say":"看我画一个大圈圈。"},{"name":"孩子画大圈","say":"换你画一个好大的圈。"},{"name":"接起来","say":"要接起来喔，绕回原点。"},{"name":"变成太阳","say":"加上光线，变成太阳！"},{"name":"画小圈","say":"这次画小一点的圈。"},{"name":"画很多圈","say":"画满整张纸的圈圈！"}],"reactions":[{"if":"孩子画的圈接不起来","then":"完全正常。先在墙上画大圈（比较容易），或大人用手指在他手背上带一次感觉路径。"},{"if":"孩子只会画螺旋不会停","then":"提醒「绕一圈就停」。可以在起点画个记号，回到记号就停。"},{"if":"孩子画得很小很挤","then":"用大张的纸，或先在墙上画。空间大了动作自然会放开。"}],"mistakes":["要求画圆——三岁能接起来就很好了，圆不圆是后面的事。","纸太小——限制了动作范围，圆更难画好。","一直擦掉重画——擦掉会打击信心，画歪了就当成另一个图案。"],"down":"在墙上画大圈；大人先画淡淡的圆让他描；用手指在沙盘上先画。","up":"画小圈；画一串大小不同的圈；画同心圆；或画成指定的图案（脸、气球）。","progress":["圈能不能接起来。","圆的形状有没有越来越接近圆。","能画出多小的圈。"],"outro":"三岁左右能画出接得起来的圆圈，是常见的发展指标。画不圆很正常——多画几次，自然会越来越好。"}' AS JSON))
WHERE `id` = 'A085';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋笔（自己画简单迷宫）'),
  `trains` = COALESCE(`trains`, '控制笔在通道里走，练精准的运笔。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"画一条弯弯曲曲的宽通道。"},{"imageUrl":null,"instruction":"让孩子用笔从这头画到那头，不要碰到边。"},{"imageUrl":null,"instruction":"通道慢慢变窄。"},{"imageUrl":null,"instruction":"也可以画简单的迷宫。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '宽通道、短距离'),
  `harder` = COALESCE(`harder`, '窄通道、有转弯。'),
  `tip` = COALESCE(`tip`, '通道从很宽开始——碰到边就要重来的话，孩子会挫折。宽一点让他成功，再慢慢缩窄。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"画一条弯弯曲曲的宽通道，让孩子用笔从这头画到那头不碰到边。通道从很宽开始——碰到边就要重来的话，孩子会挫折。","principles":["在通道里画线，需要持续控制笔的位置不超出两条边界。","这是很精准的运笔控制，专业上叫线条的空间限制。","孩子必须一直用眼睛监控笔尖和边界的距离，并即时调整。","这种「边做边看边修正」的能力，叫视觉动作回馈调节。","转弯的地方最难，因为方向要改变而且不能出界。","通道的宽度是最直接的难度控制——宽一点简单，窄一点困难。","这个能力和日后在格子里写字、在线上画线是同一件事。","成功走完会有明确的成就感，孩子会想再挑战更窄的。"],"prep":{"场地":"餐桌，纸放正，另一只手压住。","器材":"纸＋笔；大人先画好宽通道。","安全检查":"笔不要太尖。","大人位置":"大人先画通道，再在旁边陪着走。"},"shots":[{"name":"画宽通道","say":"我们先画一条很宽的路。"},{"name":"从起点出发","say":"从这里出发，不要碰到边边。"},{"name":"慢慢走","say":"慢慢来，不用快。"},{"name":"转弯","say":"转弯的地方要更慢。"},{"name":"到达终点","say":"到了！都没碰到边！"},{"name":"通道变窄","say":"这次路变窄一点。"}],"reactions":[{"if":"孩子一直碰到边","then":"通道画宽一点。宽到他一定过得去，先建立成功经验。"},{"if":"孩子画得太快出界","then":"提醒「慢慢来，慢的人才会赢」。速度是精准度的最大敌人。"},{"if":"孩子碰到边就想放弃","then":"改成「碰到边没关系，继续走完」。不要求零失误。"}],"mistakes":["通道一开始就太窄——碰到边就重来会让孩子挫折，宁可宽一点。","迷宫太复杂——简单的单一通道就好，不用真的做成迷宫。","要求零失误——碰到几次没关系，走完才是重点。"],"down":"通道画很宽；路线画直一点少转弯；距离缩短。","up":"通道变窄；增加转弯；画成真正的迷宫有岔路；或加上计时。","progress":["能通过多窄的通道。","碰到边的次数有没有减少。","转弯处的控制有没有改善。"],"outro":"通道从很宽开始，让孩子先成功几次。慢慢走才走得准——速度是精准度最大的敌人。"}' AS JSON))
WHERE `id` = 'A086';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋笔'),
  `trains` = COALESCE(`trains`, '把点连起来变成图，练手眼配合和顺序。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在纸上点几个点，标上数字。"},{"imageUrl":null,"instruction":"让孩子按顺序连起来。"},{"imageUrl":null,"instruction":"连完变成一个图形。"},{"imageUrl":null,"instruction":"点数慢慢增加。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三五个点'),
  `harder` = COALESCE(`harder`, '十几个点，或点排得比较散。'),
  `tip` = COALESCE(`tip`, '连连看同时练了数数、顺序和运笔——连完出现一个图案，孩子会很有成就感。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十（手眼协调与视动整合）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"在纸上点几个点、标上数字，按顺序连起来变成一个图案。连完出现图案的那一刻，孩子会很有成就感。","principles":["连连看需要先找到下一个数字在哪里，这是视觉搜寻。","找到之后要把笔从现在的位置移过去，这是精准的定位运笔。","按数字顺序连，同时练到了数字辨识和顺序概念。","孩子必须一直记得「我现在到几了」，这是工作记忆。","点与点之间要画出直线，也在练线条控制。","连到最后会出现一个图案，这个「揭晓」的设计让孩子很有动机。","点的数量可以从五个慢慢加到二十个，难度递增很自然。","这个活动把运笔、数数、顺序、搜寻四件事整合在一起。"],"prep":{"场地":"餐桌，纸放正。","器材":"纸＋笔；大人先画好点和数字。","安全检查":"笔不要太尖。","大人位置":"大人先画好点阵图，再在旁边陪着连。"},"shots":[{"name":"画点标数字","say":"我们在纸上点几个点，写上数字。"},{"name":"从1开始","say":"从 1 开始，找找 2 在哪里？"},{"name":"连起来","say":"把 1 和 2 连起来。"},{"name":"继续连","say":"3 在哪里？4 呢？"},{"name":"图案出现","say":"哇，是一只小猫！"},{"name":"涂颜色","say":"我们帮它涂上颜色。"}],"reactions":[{"if":"孩子找不到下一个数字","then":"大人用手指一下大概的区域，让他自己找到。或减少点的数量。"},{"if":"孩子连错顺序","then":"不用擦掉。提醒「我们回到刚才的地方」，继续连下去。"},{"if":"孩子还不认得数字","then":"改用颜色或图案代替数字（红点连红点），或用大人手指引导顺序。"}],"mistakes":["点太多——刚开始五到八个就够，太多会失去耐心。","数字写太小——要写清楚够大，找不到会挫折。","连错就擦掉重来——不用追求完美，连完出现图案才是重点。"],"down":"点减少到五个；数字写大一点；用颜色代替数字；点排成简单的形状。","up":"点增加到二十个；点排得比较密集；用字母顺序；或让孩子自己设计点阵图。","progress":["能连几个点的图。","找下一个数字的速度。","连出来的线直不直。"],"outro":"连连看把运笔、数数、顺序、搜寻四件事练在一起。图案揭晓的那一刻，孩子会想再来一张。"}' AS JSON))
WHERE `id` = 'A087';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋笔'),
  `trains` = COALESCE(`trains`, '沿着虚线描，练笔画的准确度。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人用铅笔画虚线（线条、形状、简单的字）。"},{"imageUrl":null,"instruction":"让孩子用彩笔描上去。"},{"imageUrl":null,"instruction":"从粗虚线开始。"},{"imageUrl":null,"instruction":"描完可以涂色。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '粗的虚线、简单形状'),
  `harder` = COALESCE(`harder`, '细虚线、复杂形状。'),
  `tip` = COALESCE(`tip`, '虚线画粗一点，孩子容易描得准、也更有信心。描的时候提醒他「慢慢来」——快了就出界。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"大人用铅笔画虚线，让孩子用彩笔描上去。虚线画粗一点，孩子容易描得准、也更有信心。","principles":["描虚线时，孩子有明确的路径可以跟随，不用自己规划线条。","这降低了动作计划的负担，让他可以专心在运笔的控制上。","这是学写字前很重要的中间步骤——从描到仿写再到自己写。","要描得准，眼睛必须一直盯着前方的虚线，而不是笔尖。","这个「看前面一点」的习惯，和日后写字时的视觉引导是一样的。","虚线的粗细直接决定难度——粗虚线容易描准，细虚线要求更高。","描的时候要慢，快了一定出界，这也是速度控制的练习。","从线条描到形状再描到字，是很自然的难度递进。"],"prep":{"场地":"餐桌，纸放正，另一只手压住。","器材":"纸＋笔；大人用铅笔先画粗虚线，孩子用彩笔描。","安全检查":"笔不要太尖。","大人位置":"大人先画虚线，粗一点、间隔大一点。"},"shots":[{"name":"画粗虚线","say":"虚线画粗一点，比较好描。"},{"name":"从头开始描","say":"从这里开始，慢慢描。"},{"name":"眼睛看前面","say":"眼睛看前面的线，不要看笔尖。"},{"name":"描完线条","say":"描好了！"},{"name":"描形状","say":"这次描一个形状。"},{"name":"描完涂色","say":"描完可以涂上颜色。"}],"reactions":[{"if":"孩子描得偏离虚线很多","then":"虚线画更粗，或改成淡淡的实线让他描。先求成功。"},{"if":"孩子描得太快","then":"提醒「慢慢来」。可以说「我们比慢的，谁描得慢又准谁赢」。"},{"if":"孩子不想描想自己画","then":"很好，让他自己画。描虚线只是中间步骤，能自己画更好。"}],"mistakes":["虚线画太细太淡——孩子看不清楚也描不准。要粗要清楚。","一开始就描字——顺序是线条→形状→字，不要跳。","一直纠正「描歪了」——描得差不多就好，这是练习不是考试。"],"down":"虚线画更粗；改成淡淡的实线让他描；线条短一点。","up":"虚线变细；描复杂的形状；描字；或虚线间隔拉大（要自己补上更多）。","progress":["描的线和虚线的贴合度。","能描到哪一个阶段（线条／形状／字）。","会不会看着前面的线而不是笔尖。"],"outro":"虚线画粗一点，孩子描得准、也更有信心。顺序是线条、形状、字——一步一步来。"}' AS JSON))
WHERE `id` = 'A088';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '简单的着色图＋蜡笔'),
  `trains` = COALESCE(`trains`, '在框框里涂色，练控制力道和范围。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"找一张图案简单、区块大的着色图。"},{"imageUrl":null,"instruction":"让孩子涂色，尽量不涂出线外。"},{"imageUrl":null,"instruction":"先涂大区块，再涂小区块。"},{"imageUrl":null,"instruction":"涂满不留白也是一种练习。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大区块、出界一点没关系'),
  `harder` = COALESCE(`harder`, '小区块、要涂得均匀不出界。'),
  `tip` = COALESCE(`tip`, '图案越简单越好——密密麻麻的着色本会让孩子放弃。涂出界不必一直纠正，多涂几次自然会好。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"找一张图案简单、区块大的着色图。图案越简单越好——密密麻麻的着色本会让孩子放弃。","principles":["涂色要控制笔停在轮廓线内，这是空间范围的控制。","接近边界时要减速、转向，这需要预判和即时调整。","涂满整个区块需要持续来回移动，是很好的运笔耐力练习。","涂色时的施力要均匀，太轻颜色不够、太重会破纸，这是力道控制。","大区块先练，因为边界少、成功率高；小区块需要更精细的控制。","涂色还需要持续的专注——涂完一个区块要好几十秒。","涂出界是很正常的，多涂几次自然会改善，不需要一直纠正。","选择颜色和完成作品的过程，对孩子来说是有创造感的。"],"prep":{"场地":"餐桌，图放正，另一只手压住。","器材":"简单的着色图＋蜡笔；区块大、线条粗的最好。","安全检查":"笔不要太尖。","大人位置":"大人可以一起涂另一张，不要在旁边指点。"},"shots":[{"name":"选对图","say":"选区块大、图案简单的。"},{"name":"从大区块开始","say":"先涂大的地方。"},{"name":"接近边界减速","say":"快到边边的时候慢一点。"},{"name":"来回涂满","say":"来回涂，涂满不留白。"},{"name":"涂小区块","say":"这次涂小一点的地方。"},{"name":"完成作品","say":"涂好了，好漂亮！"}],"reactions":[{"if":"孩子涂得到处出界","then":"换区块更大的图。也可以在轮廓线上用粗笔描一遍，边界更明显。"},{"if":"孩子涂几笔就不涂了","then":"区块太大太费时。选小一点的图，或只要求涂一两个区块。"},{"if":"孩子涂得很用力把纸弄破","then":"提醒「轻一点」，或换软一点的蜡笔。也可以在纸下多垫几张。"}],"mistakes":["选太复杂的着色本——密密麻麻的图会让孩子放弃，这是最常见的问题。","一直纠正涂出界——多涂几次自然会好，纠正只会让他不想涂。","要求涂满每一块——涂一两块就很好了，不用完成整张。"],"down":"选区块很大的图；用粗笔描一遍轮廓让边界更明显；只涂一个区块。","up":"选区块小一点的图；要求不出界；涂满不留白；或自己画图再涂。","progress":["出界的程度有没有减少。","能涂多小的区块。","涂色的均匀度和饱满度。"],"outro":"选图是关键——区块大、图案简单的最好。涂出界不用一直纠正，多涂几次自然就会好。"}' AS JSON))
WHERE `id` = 'A089';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋笔'),
  `trains` = COALESCE(`trains`, '练画基本图形（圆、方、三角），是写字的前置能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人示范画一个形状。"},{"imageUrl":null,"instruction":"让孩子跟着画。"},{"imageUrl":null,"instruction":"从圆形开始，再方形、三角形。"},{"imageUrl":null,"instruction":"画完可以变成图（方形变房子、三角变屋顶）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着描'),
  `harder` = COALESCE(`harder`, '看着范例自己画出来。'),
  `tip` = COALESCE(`tip`, '发展顺序大致是：圆（3岁）→方（4岁）→三角（5岁）。画不出来不必急，先多玩画线画圈。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"从圆形开始，再方形、三角形。发展顺序大致是：圆三岁、方四岁、三角五岁——画不出来不必急。","principles":["画基本图形是写字的直接前置能力，因为字就是由线条和转角组成的。","圆形只需要连续的曲线，不需要停顿和转向，所以最早发展。","方形需要在四个角停下来、改变方向再继续，难度高很多。","这个「停—转—继续」的能力，正是写字时笔画转折需要的。","三角形的角度是斜的，比方形的直角更难控制，所以最晚。","发展参考：圆约三岁、方约四岁、三角约五岁能画得出来。","画不出来通常不是不会，而是动作计划还没成熟到那个程度。","这时候多玩画线画圈，基础够了形状自然就出来了。"],"prep":{"场地":"餐桌或墙上贴纸。","器材":"纸＋笔；大张的纸让他画得开。","安全检查":"笔不要太尖。","大人位置":"大人坐在孩子旁边，一个形状一个形状慢慢示范。"},"shots":[{"name":"示范画圆","say":"先画圆——绕一圈接起来。"},{"name":"示范画方","say":"方形要在角角停一下，再转弯。"},{"name":"孩子跟着画","say":"换你试试看。"},{"name":"画三角形","say":"三角形有三个角。"},{"name":"变成图案","say":"方形变房子、三角变屋顶！"},{"name":"发展参考","say":"画不出来不用急，圆三岁、方四岁、三角五岁。"}],"reactions":[{"if":"孩子画方形的角变成圆角","then":"很正常。示范时刻意在角落停两秒，说「停、转弯、再走」。"},{"if":"孩子画不出三角形","then":"五岁前画不出来很正常。多练圆和方，基础够了自然会。"},{"if":"孩子画的形状很歪","then":"不用要求工整。能看出是什么形状就很好了。"}],"mistakes":["超前要求——三岁要他画三角形，是超出发展的要求。","一直擦掉重画——打击信心，画歪了就当成另一个图案。","跳过圆和方直接练字——形状是字的基础，顺序不能跳。"],"down":"先描形状再自己画；只练圆形；在墙上画大的形状。","up":"画更多形状（菱形、星形）；把形状组合成图案；或画指定大小的形状。","progress":["目前能画出哪些形状。","方形的角是尖的还是圆的。","形状的比例有没有越来越接近。"],"outro":"圆三岁、方四岁、三角五岁——这是大致的发展顺序。画不出来不必急，先多玩画线画圈就好。"}' AS JSON))
WHERE `id` = 'A090';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '图画书或「找一找」类的绘本'),
  `trains` = COALESCE(`trains`, '在复杂的画面中找出指定的东西，练视觉搜寻。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"翻开一张东西很多的图。"},{"imageUrl":null,"instruction":"说「找找看小狗在哪里」。"},{"imageUrl":null,"instruction":"让孩子指出来。"},{"imageUrl":null,"instruction":"可以比赛谁先找到。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '目标明显、画面简单'),
  `harder` = COALESCE(`harder`, '目标藏在复杂背景里。'),
  `tip` = COALESCE(`tip`, '「找一找」的能力和将来在课本上找答案、在黑板上找位置是同一种能力。绘本、超市货架都能玩。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"翻开一张东西很多的图，说「找找看小狗在哪里」。这个能力和将来在课本上找答案、在黑板上找位置是同一种。","principles":["在复杂画面中找出特定目标，叫视觉搜寻。","搜寻时大脑要把目标的特征记住，再一区一区比对。","有方法地看（从左到右、一区一区）比随便乱看快得多。","这个能力和阅读时在一行字里找关键字是同一套机制。","也和在课本上找答案、在黑板上找到老师讲的位置有关。","视觉搜寻不好的孩子，写作业时常常「找不到题目在哪」。","背景越复杂，难度越高——这是很自然的难度调整。","绘本、超市货架、马路上的招牌，到处都能玩。"],"prep":{"场地":"任何地方，沙发上、车上、超市都可以。","器材":"图画书或「找一找」类的绘本；也可以用超市货架、街景。","安全检查":"在户外玩时注意交通安全。","大人位置":"大人和孩子一起看，可以比赛谁先找到。"},"shots":[{"name":"翻开复杂的图","say":"这张图东西好多。"},{"name":"出题","say":"找找看，小狗在哪里？"},{"name":"教方法","say":"从这边一区一区看。"},{"name":"找到了","say":"找到了！"},{"name":"换他出题","say":"换你出题考我。"},{"name":"生活应用","say":"在超市也可以玩。"}],"reactions":[{"if":"孩子找很久找不到","then":"教他「一区一区看」的方法，或缩小范围（「在这一半里面」）。"},{"if":"孩子随便乱指","then":"先确认他记住目标了吗。可以先给他看一下目标的图片再找。"},{"if":"孩子失去兴趣","then":"换他出题。出题比找更有主导感，孩子通常很买单。"}],"mistakes":["图太复杂——刚开始用元素少一点的图，成功了再加难度。","只说「找找看」不教方法——教「一区一区看」，效率差很多。","孩子找不到就直接指给他——先给提示（「在上面」），让他自己找到。"],"down":"用元素少的图；缩小搜寻范围；先看目标图片再找。","up":"用元素更多的图；一次找两三样；限时找；或找出所有的某类物品（全部的红色东西）。","progress":["找到目标的速度。","会不会用有系统的方法搜寻。","能处理多复杂的画面。"],"outro":"「找一找」的能力，和将来在课本上找答案是同一种。记得教他方法——一区一区看，比乱找快得多。"}' AS JSON))
WHERE `id` = 'A091';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '两张相似的图（报纸广告、找不同游戏）'),
  `trains` = COALESCE(`trains`, '比对两张图找差异，练视觉分辨。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿两张几乎一样的图。"},{"imageUrl":null,"instruction":"让孩子找出哪里不一样。"},{"imageUrl":null,"instruction":"找到就圈起来。"},{"imageUrl":null,"instruction":"从明显的差异开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三处明显不同'),
  `harder` = COALESCE(`harder`, '五处以上、差异细微。'),
  `tip` = COALESCE(`tip`, '教孩子「一区一区看」而不是随便乱找——有方法地看，找得又快又准。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"两张几乎一样的图，找出哪里不一样。教孩子「一区一区看」而不是随便乱找——有方法地看，找得又快又准。","principles":["找不同需要在两张图之间来回比对，这是视觉分辨能力。","要发现差异，孩子必须注意到细节而不只是看整体。","这种对细节的注意力，和日后辨认相似的字（日和目、天和夫）直接相关。","来回比对时眼睛要快速移动并且记住刚才看到的，这用到工作记忆。","有系统地一区一区比对，比随机乱看有效得多。","教方法本身就是很重要的学习——策略比努力重要。","差异的明显程度可以调整难度，从很明显到很细微。","报纸广告、两张相似的照片都能拿来玩。"],"prep":{"场地":"餐桌或沙发，两张图并排放。","器材":"两张相似的图；报纸广告、找不同游戏书，或自己画两张。","安全检查":"无特殊风险。","大人位置":"大人坐在旁边，教一区一区比对的方法。"},"shots":[{"name":"并排两张图","say":"这两张图几乎一样，但有几个地方不同。"},{"name":"教方法","say":"我们从左上角开始，一区一区比。"},{"name":"来回比对","say":"看这里，再看那里。"},{"name":"找到不同","say":"找到了！这里不一样。"},{"name":"继续找","say":"还有几个，继续找。"},{"name":"全部找到","say":"五个全部找到了！"}],"reactions":[{"if":"孩子随便乱找找不到","then":"教他分区。可以用笔把图分成四格，一格一格比。"},{"if":"孩子找到一两个就放弃","then":"给提示（「在上半部」），让他有方向。找到就大力肯定。"},{"if":"孩子觉得太难","then":"换差异更明显的图，或减少差异的数量。"}],"mistakes":["差异太细微——刚开始要明显，让他找得到才有兴趣。","不教方法——随便乱找效率很低，一定要教一区一区比。","直接告诉他答案——给方向提示就好，让他自己找到。"],"down":"差异更明显；差异数量减少到两三个；把图分成四格一格一格比。","up":"差异更细微；数量增加到八到十个；限时找；或自己画两张相似的图考大人。","progress":["能找出几个差异。","找的速度有没有变快。","会不会用分区比对的方法。"],"outro":"找不同练的是对细节的注意力，这和日后辨认相似的字有关。记得教方法——一区一区比，别随便乱找。"}' AS JSON))
WHERE `id` = 'A092';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '成对的卡片、袜子、积木'),
  `trains` = COALESCE(`trains`, '把一样的东西配成对，是视觉辨别的基础。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把成对的东西打乱。"},{"imageUrl":null,"instruction":"让孩子把一样的配起来。"},{"imageUrl":null,"instruction":"可以用袜子、图卡、积木。"},{"imageUrl":null,"instruction":"配对时说出名称。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三对、差异大'),
  `harder` = COALESCE(`harder`, '多对、或形状颜色相近。'),
  `tip` = COALESCE(`tip`, '收衣服时让孩子配袜子——家务和训练一起完成，孩子还觉得自己在帮忙。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把成对的东西打乱，让孩子配成对。收衣服时让孩子配袜子——家务和训练一起完成，孩子还觉得自己在帮忙。","principles":["配对需要辨认两个物品是否相同，这是最基本的视觉辨别。","要判断「一样」，孩子必须比对颜色、形状、大小、花纹等特征。","这是分类和概念形成的基础——先能分辨异同，才能分类。","配袜子时还要处理立体的、皱皱的物品，比平面的图卡难。","配对的过程中要记住手上那一只的样子，去找另一只，这是视觉记忆。","差异越小越难配——两双花色相近的袜子就是很好的挑战。","这个能力和日后辨认相似的字、找出规律都有关。","把它融进收衣服的家务里，孩子觉得自己有用，动机完全不一样。"],"prep":{"场地":"客厅地板或床上，把成对的东西摊开。","器材":"成对的卡片、袜子、积木；洗好的袜子最实用。","安全检查":"小物件注意误吞。袜子要洗干净的。","大人位置":"大人和孩子一起配，也可以比赛。"},"shots":[{"name":"打乱摊开","say":"袜子都混在一起了，我们来配对。"},{"name":"拿起一只","say":"先拿一只起来看清楚。"},{"name":"找另一只","say":"找找看它的好朋友在哪里。"},{"name":"配成对","say":"找到了！一模一样。"},{"name":"说出特征","say":"这双是蓝色有条纹的。"},{"name":"全部配完","say":"全部配好了，谢谢你帮忙！"}],"reactions":[{"if":"孩子配错","then":"把两只并排放，问「这两只一样吗？哪里不一样？」让他自己发现。"},{"if":"孩子配不出来","then":"减少数量到三四双，且花色差异明显。"},{"if":"孩子不想配","then":"把它变成比赛，或让他负责其中一部分（「你配爸爸的，我配妈妈的」）。"}],"mistakes":["数量太多——一堆袜子会让孩子眼花，先给三四双。","花色太相近——刚开始要差异明显，才配得出来。","只当成训练不当成帮忙——强调「你在帮忙」，动机差很多。"],"down":"数量减到三四双；花色差异明显；先两两并排让他判断一不一样。","up":"数量增加；花色相近不好分辨；配完还要按颜色分类；或配对后折好收进抽屉。","progress":["能配对几双不出错。","能处理多相近的花色。","会不会说出配对的依据（颜色、花纹）。"],"outro":"收衣服时让孩子配袜子——家务和训练一起完成，而且他还觉得自己在帮忙。"}' AS JSON))
WHERE `id` = 'A093';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几样小东西＋一块布'),
  `trains` = COALESCE(`trains`, '记住看过的东西，练视觉记忆。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在桌上摆三样东西，让孩子看十秒。"},{"imageUrl":null,"instruction":"用布盖住，偷偷拿走一样。"},{"imageUrl":null,"instruction":"打开问「少了什么？」"},{"imageUrl":null,"instruction":"东西慢慢加到五六样。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三样、差异大'),
  `harder` = COALESCE(`harder`, '六样以上，或换位置不拿走。'),
  `tip` = COALESCE(`tip`, '答对了追问一句「你怎么记住的？」——让孩子发现自己用了什么方法，记忆力会进步更快。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"桌上摆三样东西看十秒，盖住后偷偷拿走一样。答对了追问一句「你怎么记住的？」——让孩子发现自己用了什么方法。","principles":["这个游戏练的是视觉记忆——把看到的画面记在脑中。","视觉记忆的容量和日后记住黑板上的字、记住题目的内容有关。","要记住三样东西，孩子会自然发展出一些策略：默念名称、编故事、分区记。","追问「你怎么记住的」，是让他意识到自己的策略，这叫后设认知。","意识到策略的孩子，会主动把这个方法用在别的地方，学习效率会提高。","东西的数量可以从三样加到五六样，难度递增很自然。","换成「改变位置」或「多了什么」，可以练到不同的记忆面向。","这个游戏不需要任何特别的教具，桌上现成的东西就能玩。"],"prep":{"场地":"餐桌，东西排成一排。","器材":"几样小东西＋一块布；汤匙、杯子、玩具、水果都可以。","安全检查":"小物件注意误吞。","大人位置":"大人负责盖布和拿走东西。"},"shots":[{"name":"摆出三样","say":"桌上有三样东西，看清楚十秒。"},{"name":"盖上布","say":"盖起来！"},{"name":"偷拿一样","say":"我偷偷拿走一样。"},{"name":"打开问","say":"少了什么？"},{"name":"追问方法","say":"你怎么记住的？"},{"name":"增加难度","say":"这次摆五样。"}],"reactions":[{"if":"孩子答不出来","then":"减到两样，或给更长的观察时间。先让他成功一次。"},{"if":"孩子说不出自己怎么记的","then":"给他选项：「你是在心里念名字，还是记位置？」帮他把策略说出来。"},{"if":"孩子每次都答对觉得太简单","then":"加到五六样，或改成「改变了什么位置」。"}],"mistakes":["一开始就摆太多——三样最合适，太多会挫折。","观察时间太短——给足十秒，让他好好看。","答对就结束——追问「你怎么记住的」才是最有价值的一步。"],"down":"只摆两样；观察时间拉长；东西差异明显。","up":"增加到五六样；改成「多了什么」；改成「位置换了哪两样」；或隔一段时间再问。","progress":["能记住几样东西。","能不能说出自己的记忆方法。","观察时间可以缩短到多少。"],"outro":"答对了别急着结束，追问一句「你怎么记住的」——让孩子发现自己的方法，记忆力会进步更快。"}' AS JSON))
WHERE `id` = 'A094';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '积木或彩色小物'),
  `trains` = COALESCE(`trains`, '照着范例排出一样的，练视觉分析和空间。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人用积木排一个简单的样式（红蓝红蓝）。"},{"imageUrl":null,"instruction":"让孩子照着排一样的。"},{"imageUrl":null,"instruction":"样式慢慢变复杂。"},{"imageUrl":null,"instruction":"也可以排成图形。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三块、简单交替'),
  `harder` = COALESCE(`harder`, '多块、有上下排列。'),
  `tip` = COALESCE(`tip`, '「照着做出一样的」是很重要的能力——将来抄黑板、照说明书组装，用的都是这个。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"大人用积木排一个简单的样式，让孩子照着排一样的。「照着做出一样的」是很重要的能力——将来抄黑板、照说明书组装，用的都是这个。","principles":["照着范例做出一样的，需要先看懂范例的结构和顺序。","这叫视觉分析——把看到的东西拆解成可以复制的元素。","排的时候还要记住范例的样子，这是视觉记忆的应用。","颜色的规律（红蓝红蓝）需要发现并延续，这是规律辨识。","规律辨识是数学思维的基础，也和日后找出规则、归纳有关。","空间位置的复制（哪个在左、哪个在上）练的是空间概念。","这个能力直接用在抄黑板、照图组装、仿写字上。","样式可以从两色交替慢慢加到复杂的图形排列。"],"prep":{"场地":"餐桌，两人各有一堆积木。","器材":"积木或彩色小物；颜色种类不要太多，两三种就好。","安全检查":"小积木注意误吞。","大人位置":"大人先排出范例，让孩子照着排在旁边。"},"shots":[{"name":"排出范例","say":"我排一个，你照着排一样的。"},{"name":"观察范例","say":"先看清楚，是什么顺序？"},{"name":"开始排","say":"红色、蓝色、红色⋯⋯"},{"name":"比对","say":"排好了，我们比比看一不一样。"},{"name":"加难度","say":"这次三种颜色。"},{"name":"换他出题","say":"换你排，我照着做。"}],"reactions":[{"if":"孩子排错顺序","then":"不用马上说错。请他「比比看一不一样」，让他自己发现。"},{"if":"孩子记不住范例","then":"把范例放在他正前方，可以随时看。不要求记住。"},{"if":"孩子觉得太简单","then":"加颜色种类、加长度，或改成立体的堆叠。"}],"mistakes":["规律太复杂——刚开始两色交替就好。","直接说「你排错了」——请他自己比对，发现错误比被告知有效。","范例收起来要他凭记忆排——刚开始让他看得到，记忆是后面的事。"],"down":"只用两种颜色；长度缩短到四个；范例放在正前方随时看。","up":"增加颜色种类；加长；改成立体堆叠；或看完就收起来凭记忆排。","progress":["能照着排多复杂的规律。","会不会自己比对检查。","能不能凭记忆排出来。"],"outro":"「照着做出一样的」将来会用在抄黑板、照说明书组装上。从两色交替开始，慢慢加难度就好。"}' AS JSON))
WHERE `id` = 'A095';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '拼图'),
  `trains` = COALESCE(`trains`, '练视觉分析、空间概念和耐心。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"从块数少的拼图开始。"},{"imageUrl":null,"instruction":"教他先找边角、再拼中间。"},{"imageUrl":null,"instruction":"拼不出来给一点提示，别直接帮他拼好。"},{"imageUrl":null,"instruction":"完成了一起欣赏。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '四到六块'),
  `harder` = COALESCE(`harder`, '二十块以上，或先分类再拼。'),
  `tip` = COALESCE(`tip`, '教「策略」比帮他拼更有价值——先找边边、先按颜色分堆，这些方法可以用一辈子。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"从块数少的拼图开始。教「策略」比帮他拼更有价值——先找边边、先按颜色分堆，这些方法可以用一辈子。","principles":["拼图需要分析每一片的形状和图案，判断它属于哪里。","这是视觉分析和空间推理的综合练习。","要把一片转到正确的角度才放得进去，这练到了心理旋转能力。","心理旋转和日后的几何、立体空间理解有关。","找边角、按颜色分堆，是很有效的解题策略。","教策略比帮他拼有价值得多——策略可以迁移到别的问题上。","拼图需要持续的专注和忍受挫折的能力，这是很好的心性训练。","完成一幅拼图的成就感很强，孩子会想挑战更多块的。"],"prep":{"场地":"餐桌或地板，铺一块布或托盘避免拼图片散落。","器材":"拼图；从四到六块开始，慢慢增加。","安全检查":"小拼图片注意误吞。","大人位置":"大人坐在旁边，给提示但不代劳。"},"shots":[{"name":"倒出拼图","say":"我们先把拼图倒出来。"},{"name":"策略一找边角","say":"先找有直边的，那是边边。"},{"name":"策略二分颜色","say":"再按颜色分成几堆。"},{"name":"拼边框","say":"先把外框拼起来。"},{"name":"转角度","say":"转一转看看能不能放进去。"},{"name":"完成","say":"完成了！"}],"reactions":[{"if":"孩子拼不出来想放弃","then":"给提示但不要拼给他看：「这一片是什么颜色？那它可能在哪一区？」"},{"if":"孩子乱塞硬压","then":"提醒「形状要刚好才放得进去，转一转试试」。"},{"if":"孩子只想拼同一幅","then":"完全可以。拼熟了再换，重复本身也有价值。"}],"mistakes":["直接帮他拼好——他就学不到策略了。给提示，不代劳。","块数太多——从四到六块开始，成功了再加。","没教策略——找边角、分颜色这些方法，教一次受用很久。"],"down":"块数减少；选图案简单、区块分明的；先拼一半让他完成另一半。","up":"增加块数；选图案复杂的；限时完成；或反面朝上只靠形状拼。","progress":["能完成几块的拼图。","会不会自己用找边角、分颜色的策略。","遇到困难时的持续时间有多长。"],"outro":"教策略比帮他拼有价值得多。先找边边、先按颜色分堆——这些方法可以用一辈子。"}' AS JSON))
WHERE `id` = 'A096';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '自己画的物品和影子图'),
  `trains` = COALESCE(`trains`, '从轮廓认出东西，练形状辨认。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在纸上画几样东西，旁边画出它们的黑影子。"},{"imageUrl":null,"instruction":"让孩子把东西和影子连起来。"},{"imageUrl":null,"instruction":"也可以用实物在墙上投影玩。"},{"imageUrl":null,"instruction":"猜猜这是什么的影子。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '形状差很多'),
  `harder` = COALESCE(`harder`, '形状相近的东西。'),
  `tip` = COALESCE(`tip`, '用手电筒在墙上做手影，也是同一种能力的练习——晚上关灯玩，孩子超喜欢。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"在纸上画几样东西，旁边画出它们的黑影子，让孩子连起来。用手电筒在墙上做手影，也是同一种能力的练习。","principles":["从轮廓认出物品，需要只靠形状而不靠颜色和细节来辨认。","这叫形状恒常性——不管颜色、大小、角度怎么变，都认得出是同一个东西。","形状恒常性是阅读的重要基础——不同字体、大小的同一个字都要认得出来。","影子把物品简化成纯粹的轮廓，逼孩子专注在形状上。","要配对成功，孩子必须在脑中把实物和轮廓做比对。","这个比对过程用到的是视觉分析和心理表征。","用手电筒做手影时，孩子还要理解光和影的因果关系。","关灯玩手影是孩子很喜欢的活动，动机完全不用担心。"],"prep":{"场地":"餐桌做纸上配对；晚上关灯在墙边做手影。","器材":"自己画的物品和影子图；或手电筒＋一面墙。","安全检查":"手电筒不要照眼睛。关灯时地面要清空避免绊倒。","大人位置":"大人先画好图，或负责拿手电筒。"},"shots":[{"name":"画物品和影子","say":"左边画东西，右边画它的黑影子。"},{"name":"观察轮廓","say":"看看这个影子是什么形状？"},{"name":"连起来","say":"把它和对的影子连起来。"},{"name":"实物投影","say":"我们用手电筒照照看。"},{"name":"猜影子","say":"猜猜这是什么的影子？"},{"name":"做手影","say":"我们来做手影！"}],"reactions":[{"if":"孩子认不出影子","then":"把实物和影子并排比对，或用轮廓更特别的东西（剪刀、汤匙）。"},{"if":"孩子觉得纸上配对无聊","then":"直接玩手电筒投影，实物变影子的过程本身就很有趣。"},{"if":"孩子怕黑","then":"不用全暗，留一盏小灯就好。也可以在有点暗的角落玩。"}],"mistakes":["选的物品轮廓太相似——要选形状特征明显的东西。","只做纸上配对——手电筒投影更有趣也更好理解光影关系。","手电筒照到眼睛——要提醒方向。"],"down":"物品轮廓差异明显；数量减到三样；实物和影子并排比对。","up":"轮廓相近不好分辨；数量增加；从不同角度投影（影子会变形）；或做复杂的手影。","progress":["能不能只靠轮廓认出物品。","能处理多相近的轮廓。","能不能理解角度会让影子变形。"],"outro":"从轮廓认出东西，练的是形状恒常性——这和日后认字有关。晚上关灯做手影，孩子会玩到不想睡。"}' AS JSON))
WHERE `id` = 'A097';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋笔'),
  `trains` = COALESCE(`trains`, '从最有意义的字开始学写——自己的名字。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把孩子的名字写大一点，让他描。"},{"imageUrl":null,"instruction":"一个字一个字慢慢来。"},{"imageUrl":null,"instruction":"写在他的画上、书上、作品上。"},{"imageUrl":null,"instruction":"写歪了没关系。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '描写'),
  `harder` = COALESCE(`harder`, '看着范例自己写，或不看范例写。'),
  `tip` = COALESCE(`tip`, '名字是孩子最有动力写的字。从描开始、字写大一点、笔画少的字先学——别一开始就要求工整。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"名字是孩子最有动力写的字。从描开始、字写大一点、笔画少的字先学——别一开始就要求工整。","principles":["名字是孩子最有意义、最有动机去写的字。","从有意义的内容开始学，动机远高于练习无意义的笔画。","写名字会用到笔画、结构、比例，是很完整的书写练习。","从描开始，让孩子先感受笔画的路径和顺序。","描熟了再仿写（旁边有范例照着写），最后才是自己写。","字写大一点，孩子的动作控制还不成熟，小格子会写得很挫折。","笔画少的字先学，成功经验会带来继续写的意愿。","写在自己的画上、作品上，让名字有实际的用途。"],"prep":{"场地":"餐桌，纸放正，坐姿调整好（脚要踩得到地）。","器材":"纸＋笔；大人先把名字写大一点当范例。","安全检查":"笔不要太尖。写字时间不要太长，十分钟就休息。","大人位置":"大人坐在孩子旁边（同侧），先写好范例。"},"shots":[{"name":"写大范例","say":"我把名字写大一点。"},{"name":"先描","say":"先描，感觉一下怎么写。"},{"name":"笔顺","say":"先这一笔，再这一笔。"},{"name":"仿写","say":"看着旁边，自己写一次。"},{"name":"写歪没关系","say":"写歪了没关系，写得出来最重要。"},{"name":"写在作品上","say":"写在你的画上面！"}],"reactions":[{"if":"孩子写得歪七扭八","then":"不要一直擦掉重写。先肯定「你写出来了」，工整是后面的事。"},{"if":"孩子说太难不想写","then":"退回描的阶段，或只写名字中笔画最少的那个字。"},{"if":"孩子写得很小很挤","then":"把格子画大一点，或用大张的纸。空间够了动作才放得开。"}],"mistakes":["一开始就要求工整——会浇熄动机。先求写得出来。","格子太小——孩子的控制还不成熟，要写大一点。","一直擦掉重写——擦掉会打击信心，写完整个再说。"],"down":"只描不写；只写笔画最少的一个字；格子画很大。","up":"不看范例自己写；写在正常大小的格子里；写全名；或写得工整一点。","progress":["目前在哪一个阶段（描／仿写／自己写）。","能写出几个字。","字的大小有没有慢慢符合格子。"],"outro":"名字是孩子最有动力写的字。从描开始、字写大一点、笔画少的先学——写得出来比写得工整重要。"}' AS JSON))
WHERE `id` = 'A098';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '合适的桌椅'),
  `trains` = COALESCE(`trains`, '把写字的环境和姿势调对，让孩子写得久也写得好。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"椅子高度：坐下时脚能平踩地面。"},{"imageUrl":null,"instruction":"桌子高度：手肘放桌上约90度。"},{"imageUrl":null,"instruction":"背靠椅背、屁股坐到底。"},{"imageUrl":null,"instruction":"纸放正、另一只手压住纸。"},{"imageUrl":null,"instruction":"写之前先做手指操。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '坐好五分钟'),
  `harder` = COALESCE(`harder`, '维持二十分钟姿势不垮。'),
  `tip` = COALESCE(`tip`, '**脚一定要踩得到地**——脚悬空的孩子坐不到十分钟就会歪。脚构不着就垫个小凳子，这一招立刻见效。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十二（书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"脚一定要踩得到地——脚悬空的孩子坐不到十分钟就会歪。脚构不着就垫个小凳子，这一招立刻见效。","principles":["写字的稳定来自身体的稳定，而身体的稳定来自脚有支撑。","脚悬空时，身体没有着力点，核心必须一直出力维持平衡。","这会让孩子很快就累，然后开始趴桌子、扭来扭去、换姿势。","很多被认为「坐不住」的孩子，其实只是脚构不到地。","垫一个小凳子让脚能平踩，这个改变往往立刻见效。","桌子高度要让手肘自然弯曲约九十度，太高会耸肩、太低会驼背。","纸要放正、另一只手压住纸，这样写起来才稳。","写之前做一下手指操，手会灵活很多——就像运动前要热身。"],"prep":{"场地":"孩子写字的桌椅，先量一下高度。","器材":"合适的桌椅；必要时准备一个小板凳垫脚、一个坐垫调高。","安全检查":"垫脚的凳子要稳固不会滑。椅子不要有滑轮。","大人位置":"大人帮忙调整桌椅高度，检查坐姿。"},"shots":[{"name":"脚要踩到地","say":"脚一定要踩得到地。"},{"name":"垫小凳子","say":"构不到就垫个小凳子。"},{"name":"桌子高度","say":"手肘放在桌上大约九十度。"},{"name":"背靠椅背","say":"屁股坐到底，背靠着椅背。"},{"name":"纸放正压住","say":"纸放正，另一只手压住。"},{"name":"先做手指操","say":"写之前先做一下手指操。"}],"reactions":[{"if":"孩子写没几分钟就趴下来","then":"先检查脚有没有踩到地。这是最常见也最容易解决的原因。"},{"if":"孩子一直耸肩","then":"桌子太高。降低桌子或把椅子垫高（同时记得脚也要有支撑）。"},{"if":"孩子的纸一直歪","then":"提醒另一只手压住纸。也可以在桌上贴胶带标示纸的位置。"}],"mistakes":["忽略脚有没有踩到地——这是最常被忽略、影响却最大的一点。","只调桌子不调椅子——两个要一起看，而且脚一定要有支撑。","只提醒坐姿不调环境——环境对了，姿势自然就对了。"],"down":"先只要求脚踩到地和纸放正；写的时间缩短到五分钟。","up":"加上背靠椅背、手肘角度的要求；延长写字时间；或让孩子自己检查坐姿。","progress":["脚能不能平踩地面。","能维持正确坐姿写多久。","会不会自己调整坐姿。"],"outro":"脚踩得到地、手肘九十度、纸放正压住、写前做手指操——这四件事做到了，孩子写得久也写得好。"}' AS JSON))
WHERE `id` = 'A099';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸、笔、蜡笔'),
  `trains` = COALESCE(`trains`, '把这个模组的能力串起来练一轮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：画三条直线、三个圈。"},{"imageUrl":null,"instruction":"第二关：走一次迷宫不碰边。"},{"imageUrl":null,"instruction":"第三关：描一个形状。"},{"imageUrl":null,"instruction":"第四关：涂色不出界。"},{"imageUrl":null,"instruction":"最后自由画一幅画。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关降低标准'),
  `harder` = COALESCE(`harder`, '加上时间限制或提高精准度。'),
  `tip` = COALESCE(`tip`, '写字前的能力要慢慢来——手臂稳了、握笔对了、看得懂形状了，写字自然就顺。急着练写字，反而容易养成错误习惯。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一～十二（视知觉 · 书写前技能与运笔）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"把这个模组串成四关玩一轮。写字前的能力要慢慢来——手臂稳了、握笔对了、看得懂形状了，写字自然就顺。","principles":["写字是很多能力整合起来的结果，不是单独练写就会的。","肩膀和手臂的稳定、握笔的姿势、线条的控制、形状的辨认，缺一不可。","急着练写字，反而容易养成错误的握笔和姿势习惯。","错误的习惯一旦养成，日后矫正要花好几倍的力气。","四关分别对应线条控制、运笔精准、形状仿画和范围控制。","闯关的形式让练习有结构和终点，孩子比较撑得住。","最后留一段自由画画的时间，让活动收在愉快的感觉上。","每次记录成绩，一个月后对照，进步会看得很清楚。"],"prep":{"场地":"餐桌，坐姿先调整好（脚要踩得到地）。","器材":"纸、笔、蜡笔；大人先画好迷宫和虚线形状。","安全检查":"写字时间不要太长，四关做完就休息。","大人位置":"大人当关主，负责准备材料和记录。"},"shots":[{"name":"先调坐姿","say":"先检查——脚有没有踩到地？"},{"name":"第一关","say":"第一关：画三条直线、三个圈。"},{"name":"第二关","say":"第二关：走迷宫不碰边。"},{"name":"第三关","say":"第三关：描一个形状。"},{"name":"第四关","say":"第四关：涂色不出界。"},{"name":"自由画画","say":"最后，自由画一幅画！"}],"reactions":[{"if":"孩子某一关做不好","then":"当场降低标准。闯关是为了看进步，不是考试。"},{"if":"孩子做完四关就累了","then":"自由画画可以留到下次。四关做完就很好了。"},{"if":"孩子只想自由画不想闯关","then":"先让他画。画够了再提议「我们来闯个关」。"}],"mistakes":["把它当成考试——这是复习不是测验，标准要宽松。","省略最后的自由画画——收在愉快的感觉上很重要。","急着让孩子练写字——前面的能力够了，写字自然会顺。"],"down":"减到两三关；每关标准降低；只做他比较拿手的。","up":"提高每关标准；加上计时；增加关卡；或让孩子自己设计一关。","progress":["每一关的表现记录下来。","一个月后再做一次，对照进步。","整体的握笔姿势和坐姿有没有改善。"],"outro":"写字前的能力要慢慢来——手臂稳了、握笔对了、看得懂形状了，写字自然就顺。急着练写字，反而容易养成错误习惯。"}' AS JSON))
WHERE `id` = 'A100';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '合适的汤匙＋不易打翻的碗'),
  `trains` = COALESCE(`trains`, '学会用汤匙自己吃饭。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选短柄、宽头的儿童汤匙。"},{"imageUrl":null,"instruction":"碗选底部有防滑的、或垫一块湿布。"},{"imageUrl":null,"instruction":"先给容易舀的食物（粥、饭团）。"},{"imageUrl":null,"instruction":"洒出来没关系，围兜和地垫备好。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人扶着他的手一起舀'),
  `harder` = COALESCE(`harder`, '全程自己吃完一餐。'),
  `tip` = COALESCE(`tip`, '弄得一团乱是学习的必经过程——铺张报纸、穿件旧衣服，让他放心练。一直喂的孩子，学会自己吃会晚很多。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"弄得一团乱是学习的必经过程——铺张报纸、穿件旧衣服，让他放心练。一直喂的孩子，学会自己吃会晚很多。","principles":["自己吃饭需要手眼协调：眼睛看碗、手把汤匙送到嘴巴。","舀的动作需要手腕做旋转和倾斜的组合控制。","送到嘴边的路径中，手要保持水平不倾斜，这是持续的稳定控制。","握汤匙的方式会从整手抓慢慢成熟到三指握，这个过程急不来。","另一只手扶住碗，是很自然的双手分工练习。","自己吃饭还牵涉到食量的自我调节——吃多少由自己决定。","一直被喂的孩子，这些能力都没有机会练，学会自己吃就会晚很多。","洒出来是学习过程的一部分，大人能接受混乱，孩子才敢练。"],"prep":{"场地":"餐椅上，桌面高度让手肘能自然弯曲，脚最好有踏板支撑。","器材":"短柄宽头的儿童汤匙＋底部防滑的碗；围兜、地垫、旧衣服。","安全检查":"碗要用不易破的。餐椅要有安全带或稳固的靠背。食物温度先测过。注意别让孩子边吃边跑。","大人位置":"大人坐在旁边一起吃，不要一直帮他擦、帮他扶。"},"shots":[{"name":"环境准备","say":"先铺好地垫、穿上围兜。"},{"name":"选对汤匙","say":"用短柄、宽头的儿童汤匙。"},{"name":"碗要防滑","say":"碗底下垫块湿布，不会滑。"},{"name":"舀起来","say":"舀半匙就好，比较好送。"},{"name":"送到嘴巴","say":"稳稳送过来。"},{"name":"洒了没关系","say":"洒出来很正常，我们一起收。"}],"reactions":[{"if":"孩子洒得到处都是","then":"这是必经过程。铺好地垫、穿旧衣服，让大人自己也放松，孩子才敢练。"},{"if":"孩子舀不起来","then":"碗底垫湿布固定，或用有弧度的碗。也可以先给好舀的食物（粥、饭团）。"},{"if":"孩子整手抓汤匙","then":"正常的发展阶段。用短柄汤匙，慢慢就会变成三指握。"}],"mistakes":["嫌乱就接手喂——这是孩子学不会自己吃最主要的原因。","汤匙太长太大——孩子握不好也舀不准，要用儿童尺寸。","碗会滑动——一定要固定住，不然怎么舀都舀不起来。"],"down":"大人握着他的手一起舀几口；只给最后几口让他自己吃；给好舀的食物。","up":"给比较难舀的食物；用小一点的汤匙；或练用叉子。","progress":["一餐能自己吃几口。","握汤匙是整手抓还是三指握。","洒出来的量有没有减少。"],"outro":"弄得一团乱是必经过程。铺张报纸、穿件旧衣服——大人放松了，孩子才敢放心练。"}' AS JSON))
WHERE `id` = 'A101';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–3岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '小杯子（不要吸管杯）'),
  `trains` = COALESCE(`trains`, '学会用一般杯子喝水，练手部控制和吞咽。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"用小小的杯子，一次只装一点点水。"},{"imageUrl":null,"instruction":"让孩子双手拿着喝。"},{"imageUrl":null,"instruction":"慢慢过渡到单手拿。"},{"imageUrl":null,"instruction":"洒了一起擦。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '双手拿、水装很少'),
  `harder` = COALESCE(`harder`, '单手拿、水装多一点。'),
  `tip` = COALESCE(`tip`, '水装少一点，洒了也不心疼。太依赖吸管杯的孩子，用一般杯子喝会比较晚学会。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"用小小的杯子，一次只装一点点水。水装少一点，洒了也不心疼——太依赖吸管杯的孩子，用一般杯子喝会比较晚学会。","principles":["用一般杯子喝水，需要控制杯子倾斜的角度。","倾斜太快水会冲出来，太慢喝不到，这是很精细的手腕控制。","喝的时候还要控制吞咽的节奏，不然会呛到。","吸管杯的水是被吸出来的，不需要控制角度，练不到这个能力。","用杯子喝水时嘴唇要贴住杯缘形成密合，这也是口腔动作的练习。","嘴唇的闭合能力和日后的构音、进食都有关。","双手拿杯比单手容易，可以先从双手开始。","水装少一点，洒了大人不心疼，孩子也不会有压力。"],"prep":{"场地":"餐桌，下面铺毛巾或托盘。","器材":"小杯子（不要吸管杯）；不易破、杯口不厚的最好。","安全检查":"不用玻璃杯。水温适中。水装少量，一次一两口的量。孩子呛到要立刻处理。","大人位置":"大人坐在旁边，必要时扶一下杯底。"},"shots":[{"name":"选小杯子","say":"用小小的杯子，装一点点水。"},{"name":"双手拿","say":"两只手拿好。"},{"name":"慢慢倾斜","say":"慢慢倾过来。"},{"name":"喝一口","say":"喝一小口。"},{"name":"放下","say":"放回桌上。"},{"name":"换单手","say":"熟练了可以用一只手。"}],"reactions":[{"if":"孩子喝到一半水就洒了","then":"水装更少，一次一口的量就好。少量多次比一次装满好。"},{"if":"孩子会呛到","then":"水量减少、倾斜慢一点。也可以用杯口有缺口的学习杯（能看到水位）。"},{"if":"孩子一直要吸管杯","then":"逐步替换——在家用杯子、外出用吸管杯，慢慢过渡。"}],"mistakes":["水装太满——洒了大人会紧张，孩子就不敢练。","一直用吸管杯——会延后学会用一般杯子的时间。","用玻璃杯——破了很危险。"],"down":"水装更少；用双手拿；大人扶住杯底一起喝。","up":"水装多一点；用单手拿；用大一点的杯子；或练自己倒水再喝。","progress":["能不能不洒地喝完。","能不能用单手拿杯。","会不会呛到。"],"outro":"小杯子、少量水，洒了也不心疼。太依赖吸管杯的孩子，用一般杯子喝会比较晚学会。"}' AS JSON))
WHERE `id` = 'A102';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '儿童筷或练习筷'),
  `trains` = COALESCE(`trains`, '学会用筷子，是重要的手部精细能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先玩夹的游戏（夹棉花球、积木）。"},{"imageUrl":null,"instruction":"再用练习筷夹容易夹的食物。"},{"imageUrl":null,"instruction":"最后换成一般筷子。"},{"imageUrl":null,"instruction":"不要求一次到位，慢慢来。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '用练习筷夹大块的东西'),
  `harder` = COALESCE(`harder`, '一般筷子夹滑一点的食物。'),
  `tip` = COALESCE(`tip`, '大约四五岁能用筷子。急不来——先把夹子、汤匙用熟，手指有力气了，筷子自然学得会。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组九（工具使用）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"大约四五岁能用筷子。急不来——先把夹子、汤匙用熟，手指有力气了，筷子自然学得会。","principles":["用筷子需要手指的高度分化：无名指小指稳住下面那根，拇指食指中指操作上面那根。","两根筷子要做不同的事，一根不动、一根动，这是很精细的分工。","手指力气不够的孩子，筷子会一直滑掉或两根一起动。","所以顺序是：先玩夹子（三指抓握）→汤匙（握持稳定）→练习筷→一般筷。","练习筷的辅助环帮忙定位手指，让孩子先掌握开合的动作。","从大块、好夹的食物开始，成功率高才有信心继续。","发展参考：大约四五岁能使用筷子，六岁左右较熟练。","不要求一次到位——先夹得起来，再要求姿势，最后才是效率。"],"prep":{"场地":"餐桌，先在游戏中练，熟了再上餐桌。","器材":"儿童筷或练习筷＋好夹的东西（棉花球、积木、大块食物）。","安全检查":"筷子不要太长太尖。提醒不要拿着筷子走动或玩闹。","大人位置":"大人坐在旁边示范，注意不要面对面（镜像会混淆）。"},"shots":[{"name":"先玩夹子","say":"先用夹子玩，练手指的力气。"},{"name":"练习筷","say":"再用有辅助环的练习筷。"},{"name":"夹大块的","say":"先夹大块、好夹的东西。"},{"name":"换一般筷","say":"换成一般筷子——下面那根不动，上面那根动。"},{"name":"两根一起动","say":"如果两根一起动，就夹不起来了。"},{"name":"上餐桌","say":"练熟了就可以用来吃饭。"}],"reactions":[{"if":"孩子两根筷子一起动","then":"退回练习筷。或大人帮他把下面那根固定在正确位置，只让他动上面那根。"},{"if":"孩子筷子一直滑掉","then":"手指力气还不够。多玩夹子和捏面团，力气够了再回来。"},{"if":"孩子不想用筷子想用汤匙","then":"不勉强。吃饭时用汤匙，游戏时练筷子，压力小成功率高。"}],"mistakes":["太早要求用筷子——三岁前手指还不够成熟，急了反而养成错误姿势。","跳过夹子和练习筷——顺序是夹子→汤匙→练习筷→一般筷，不要跳。","在吃饭时练——有时间压力和饥饿感，效果差。先在游戏中练。"],"down":"退回夹子或练习筷；夹大块不滑的东西；只在游戏中练。","up":"夹小块或滑的食物（豆子、面条）；用一般筷；或在餐桌上实际使用。","progress":["目前在哪一阶段（夹子／练习筷／一般筷）。","下面那根筷子能不能固定不动。","能夹起多小的东西。"],"outro":"筷子急不来，四五岁才用得起来。顺序是夹子、汤匙、练习筷、一般筷——手指有力气了，自然就会。"}' AS JSON))
WHERE `id` = 'A103';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '宽松的衣服'),
  `trains` = COALESCE(`trains`, '从最容易的「脱」开始学穿脱（脱比穿简单）。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"从脱袜子、脱裤子开始（最容易）。"},{"imageUrl":null,"instruction":"再练脱上衣（先拉出一只手臂）。"},{"imageUrl":null,"instruction":"大人可以起个头，让他完成最后一步。"},{"imageUrl":null,"instruction":"每次都留一点让他自己做。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人脱到一半、他拉下来'),
  `harder` = COALESCE(`harder`, '全程自己脱完。'),
  `tip` = COALESCE(`tip`, '「脱」永远比「穿」简单——先让孩子在脱衣服上尝到成功，他才有信心学穿。倒着教（大人做前面、他做最后一步）成功率最高。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「脱」永远比「穿」简单——先让孩子在脱衣服上尝到成功，他才有信心学穿。倒着教成功率最高。","principles":["脱衣服比穿衣服简单，因为不需要对准袖口和领口。","从简单的开始能建立成功经验，孩子才有信心挑战穿。","脱袜子、脱裤子最容易，脱上衣需要手臂做比较复杂的动作。","脱的过程中需要双手配合，还要有身体的觉察（知道衣服卡在哪里）。","「倒着教」是很有效的教学法——大人做前面的步骤，让孩子完成最后一步。","完成最后一步的感觉是「我做到了」，成就感最强。","随着能力提升，大人做的部分越来越少，孩子做的越来越多。","这个方法专业上叫倒向连锁，对学习多步骤的自理任务特别有效。"],"prep":{"场地":"房间或客厅地板，坐着操作比较稳。","器材":"宽松的衣服；洗澡前是最自然的练习时机。","安全检查":"脱上衣时衣服可能蒙住脸，要在旁边看着。地板要防滑。","大人位置":"大人在旁边，做前面的步骤、留最后一步给孩子。"},"shots":[{"name":"从袜子开始","say":"先从最简单的开始——脱袜子。"},{"name":"脱裤子","say":"坐着，两只手把裤子往下拉。"},{"name":"倒着教","say":"我帮你脱到一半，你完成最后一步。"},{"name":"脱上衣","say":"先拉出一只手臂。"},{"name":"成功了","say":"你自己脱掉了！"},{"name":"收进洗衣篮","say":"脱下来的衣服放进篮子。"}],"reactions":[{"if":"孩子脱上衣时卡住","then":"先帮他把一只手臂拉出来，剩下的让他自己完成。倒着教最有效。"},{"if":"孩子完全不想自己脱","then":"从最后一步开始要求（袜子只剩一半，请他拉下来）。成功一次就会想再试。"},{"if":"孩子脱得很慢","then":"洗澡前时间比较充裕，在这个时段练。赶时间就先帮忙。"}],"mistakes":["先教穿再教脱——顺序反了。脱比较简单，要先教。","每次都全部帮他脱——留最后一步给他，成就感差很多。","在赶时间的时候练——大人会忍不住接手，孩子也焦虑。"],"down":"大人做到剩最后一小步；从袜子开始；坐着操作。","up":"自己从头脱到尾；练脱比较难的（有扣子的、套头的）；脱完还要折好。","progress":["能自己脱哪些（袜子／裤子／上衣）。","需要大人做到哪一步。","脱完会不会自己收好。"],"outro":"先教脱、再教穿。大人做前面、留最后一步给孩子——这个「倒着教」的方法，成功率最高。"}' AS JSON))
WHERE `id` = 'A104';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '宽松、好穿的衣服'),
  `trains` = COALESCE(`trains`, '学会自己穿上衣和裤子。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"裤子：坐着穿两只脚，再站起来拉上去。"},{"imageUrl":null,"instruction":"上衣：先套头，再一只手一只手伸进袖子。"},{"imageUrl":null,"instruction":"衣服摊平放好，标签在后面。"},{"imageUrl":null,"instruction":"早上时间紧就先帮忙，假日再慢慢练。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人摆好方向、他套进去'),
  `harder` = COALESCE(`harder`, '自己拿衣服、分清前后自己穿好。'),
  `tip` = COALESCE(`tip`, '教一个小诀窍：衣服的标签在后面——孩子看到标签就知道怎么穿。站着穿裤子还能顺便练单脚平衡。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"教一个小诀窍：衣服的标签在后面——孩子看到标签就知道怎么穿。站着穿裤子还能顺便练单脚平衡。","principles":["穿衣服比脱衣服难，因为要对准袖口、领口、裤管。","这需要空间概念——理解衣服的哪一面对应身体的哪一边。","「标签在后面」给了孩子一个可以自己判断的具体线索。","有了这个线索，他不用每次都问大人，自主性大幅提高。","穿裤子时先坐着把两只脚伸进去，再站起来拉，这个顺序最稳。","站着拉裤子时会有短暂的单脚支撑，顺便练到平衡。","上衣先套头再伸手臂，比先伸手臂容易。","早上时间紧就先帮忙，假日再慢慢练——这个安排很重要。"],"prep":{"场地":"房间，衣服摊平放在床上或地上。","器材":"宽松、好穿的衣服；领口大、没有扣子的最容易。","安全检查":"套头时衣服会蒙住脸，要在旁边看着。站着穿裤子时旁边要有东西可以扶。","大人位置":"大人在旁边，把衣服摊平放好、标签朝上。"},"shots":[{"name":"标签在后面","say":"看到标签了吗？标签要在后面。"},{"name":"摊平放好","say":"先把衣服摊平。"},{"name":"穿裤子","say":"坐着把两只脚伸进去。"},{"name":"站起来拉","say":"再站起来拉上去。"},{"name":"上衣套头","say":"先套头，再一只手一只手伸进去。"},{"name":"穿好了","say":"自己穿好了！"}],"reactions":[{"if":"孩子穿反了","then":"不用急着重穿。指着标签问「标签在前面还是后面？」让他自己发现。"},{"if":"孩子找不到袖口","then":"大人先把袖口撑开一点。或选袖口宽松的衣服。"},{"if":"孩子站着穿裤子会跌倒","then":"先坐着或靠着墙穿。平衡稳了再站着穿。"}],"mistakes":["早上出门前才练——时间压力下大人一定接手，孩子也焦虑。留到假日。","衣服太合身——领口小、袖子紧的衣服很难穿，先用宽松的。","直接说「穿反了」——用标签的线索让他自己判断，自主性差很多。"],"down":"大人把衣服摊平、方向摆好；先只练裤子；坐着穿。","up":"自己拿衣服、自己判断正反；练有扣子的衣服；或计时挑战。","progress":["会不会用标签判断正反。","能自己穿哪些（裤子／上衣／外套）。","需要多少帮忙。"],"outro":"教他看标签——标签在后面。有了这个线索，孩子就不用每次都问大人，自己判断得出来。"}' AS JSON))
WHERE `id` = 'A105';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '好穿脱的鞋'),
  `trains` = COALESCE(`trains`, '学会分左右、自己穿上鞋。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先练穿上（黏扣带的鞋最容易）。"},{"imageUrl":null,"instruction":"教分左右：两只鞋并在一起，中间像一个「山」就是对的。"},{"imageUrl":null,"instruction":"可以在鞋垫上画半个图案，穿对了图案才完整。"},{"imageUrl":null,"instruction":"最后练黏扣带或鞋带。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '不分左右穿上就好'),
  `harder` = COALESCE(`harder`, '自己分左右、自己黏好。'),
  `tip` = COALESCE(`tip`, '在两只鞋垫上各画半个图案（合起来是一个完整的图），孩子一看就知道左右——比说一百次「这只是左脚」有用。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"在两只鞋垫上各画半个图案，合起来是一个完整的图——孩子一看就知道左右，比说一百次「这只是左脚」有用。","principles":["分辨左右对学龄前孩子来说很困难，因为左右是相对概念。","给一个视觉线索（合起来的图案），把抽象的左右变成看得见的判断。","这叫视觉提示策略，比口头提醒有效得多。","另一个方法是把两只鞋并在一起，中间形成一个「山」形就是对的。","穿鞋还需要手脚配合——手要撑开鞋口，脚要对准伸进去。","脚跟卡住时要用手指或鞋拔把鞋跟拉上来，这是精细动作。","黏扣带最容易，鞋带最难，中间可以用弹力鞋带过渡。","穿鞋是出门的必要步骤，练会了大人每天省很多时间。"],"prep":{"场地":"玄关或房间，坐着穿比较稳。","器材":"好穿脱的鞋（黏扣带最好）；贴纸或笔在鞋垫上做记号。","安全检查":"坐着穿避免跌倒。鞋子要合脚，太紧穿不进去。","大人位置":"大人在旁边，先在鞋垫上做好记号。"},"shots":[{"name":"画半个图案","say":"在两只鞋垫上各画半个图案。"},{"name":"合起来看","say":"摆对了，图案就完整了。"},{"name":"山形判断","say":"或者看中间像不像一座山。"},{"name":"撑开鞋口","say":"手把鞋子撑开。"},{"name":"脚伸进去","say":"脚伸进去，把鞋跟拉上来。"},{"name":"黏好","say":"黏扣带黏好就完成了！"}],"reactions":[{"if":"孩子老是穿反","then":"用鞋垫画图案的方法。这个视觉提示几乎立刻见效。"},{"if":"孩子脚跟卡住拉不上来","then":"教他用食指勾住鞋后跟往上拉。或用鞋拔。"},{"if":"孩子穿不进去","then":"检查鞋子是不是太紧。也可以先把鞋带或黏扣带完全松开。"}],"mistakes":["一直口头说「这只是左脚」——左右是抽象概念，视觉提示有效得多。","一开始就学绑鞋带——先练黏扣带，鞋带是最后的阶段。","在赶时间时练——留到有余裕的时候。"],"down":"鞋垫画图案当提示；用黏扣带的鞋；大人先把鞋撑开。","up":"不用提示自己分左右；练弹力鞋带；最后练绑鞋带。","progress":["能不能自己分辨左右。","能不能自己把脚跟拉上来。","能处理哪种鞋（黏扣带／弹力带／鞋带）。"],"outro":"鞋垫上各画半个图案，合起来才完整——孩子一看就知道左右。这比说一百次有用。"}' AS JSON))
WHERE `id` = 'A106';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '洗手台＋垫脚凳'),
  `trains` = COALESCE(`trains`, '学会完整的洗手流程。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"三步版：打湿→搓泡泡→冲干净擦干。"},{"imageUrl":null,"instruction":"在洗手台旁贴三张步骤图。"},{"imageUrl":null,"instruction":"唱一首二十秒的歌当计时。"},{"imageUrl":null,"instruction":"垫个凳子让他构得到。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着大人做'),
  `harder` = COALESCE(`harder`, '自己看图完成全部步骤。'),
  `tip` = COALESCE(`tip`, '把步骤图贴在洗手台边——孩子看图就会做，不用大人在旁边一直提醒。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把步骤图贴在洗手台边——孩子看图就会做，不用大人在旁边一直提醒。","principles":["洗手是多步骤的任务，孩子容易漏掉其中几步。","把步骤画成图贴在现场，孩子可以自己对照，不用依赖大人提醒。","这叫视觉提示，能大幅减少大人的口头指令。","减少口头提醒的好处是：孩子的自主性提高，亲子的拉锯也减少。","搓泡泡的动作需要双手互相搓揉，是很好的双手协调练习。","要搓到手背、指缝、手腕，还需要身体部位的觉察。","唱一首二十秒的歌当计时，让「洗多久」变得具体好懂。","垫脚凳让孩子构得到水龙头，这是能不能自己做的前提。"],"prep":{"场地":"洗手台，孩子构得到（必要时垫脚凳）。","器材":"洗手台＋垫脚凳＋三张步骤图（打湿、搓泡泡、冲干净擦干）。","安全检查":"垫脚凳要稳固防滑。水温先调好，避免烫伤。地板湿了要擦干。","大人位置":"大人第一次示范，之后让孩子看图自己做。"},"shots":[{"name":"贴步骤图","say":"我们把三张图贴在洗手台旁边。"},{"name":"垫脚凳","say":"构不到就垫个凳子。"},{"name":"打湿","say":"第一步：把手打湿。"},{"name":"搓泡泡","say":"第二步：搓泡泡，手心手背指缝都要搓。"},{"name":"唱歌计时","say":"我们唱一首歌，唱完就够了。"},{"name":"冲干净擦干","say":"第三步：冲干净、擦干。"}],"reactions":[{"if":"孩子只冲水不搓泡泡","then":"指着步骤图问「第二步是什么？」让图来提醒他，不用大人一直说。"},{"if":"孩子搓几下就冲掉","then":"用唱歌计时。唱完一首二十秒的歌才能冲。"},{"if":"孩子构不到水龙头","then":"垫脚凳。这是能不能自己洗手最基本的条件。"}],"mistakes":["只用口头提醒——贴步骤图，孩子看图就会做，省下大量的唠叨。","没有垫脚凳——构不到就一定要大人抱，永远学不会自己洗。","搓的时间太短——用唱歌计时，时间才够。"],"down":"简化成两步（打湿搓泡泡、冲干净）；大人握着手一起搓。","up":"要求搓到手背、指缝、手腕；自己调水温；或加上「洗完擦干水龙头」。","progress":["能不能看图完成三个步骤。","搓的时间够不够。","会不会搓到手背和指缝。"],"outro":"把步骤图贴在洗手台边，孩子看图就会做。垫个脚凳让他构得到——这两件事做了，他就能自己洗手。"}' AS JSON))
WHERE `id` = 'A107';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '儿童牙刷＋镜子'),
  `trains` = COALESCE(`trains`, '学会刷牙的动作与流程。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子先自己刷一遍。"},{"imageUrl":null,"instruction":"大人再帮他刷一次（六岁前都需要大人补刷）。"},{"imageUrl":null,"instruction":"对着镜子刷，看得到才刷得到。"},{"imageUrl":null,"instruction":"放首两分钟的歌当计时。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '自己刷几下、大人刷完'),
  `harder` = COALESCE(`harder`, '自己按顺序刷完（上下左右内外）。'),
  `tip` = COALESCE(`tip`, '六岁以前孩子的手部控制还不足以刷干净——让他自己刷是练能力，大人补刷是保护牙齿，两件事都要做。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"六岁以前孩子的手部控制还不足以刷干净——让他自己刷是练能力，大人补刷是保护牙齿，两件事都要做。","principles":["刷牙需要在看不见的口腔内做精细的动作，难度很高。","要刷到每一颗牙的内侧、外侧、咬合面，需要手腕做多种角度的转动。","六岁以前的孩子，手部控制还不足以把牙齿刷干净。","所以「孩子自己刷」和「大人补刷」是两件不同的事，都要做。","自己刷是练手部能力和自理习惯，补刷是真正把牙齿清洁干净。","对着镜子刷很重要——看得到才刷得到，能大幅提高涵盖率。","放一首两分钟的歌当计时，让「刷多久」变得具体。","按固定顺序刷（右上→左上→左下→右下）可以避免漏掉。"],"prep":{"场地":"洗手台前，孩子要看得到镜子（必要时垫脚凳）。","器材":"儿童牙刷＋镜子；牙膏用量按年龄（三岁以下米粒大、三岁以上豌豆大）。","安全检查":"牙膏用量要控制，太多会吞下去。垫脚凳要稳。提醒不要拿着牙刷走动（跌倒会戳伤口腔）。","大人位置":"大人站在旁边，孩子刷完后负责补刷。"},"shots":[{"name":"牙膏用量","say":"三岁以下米粒大，三岁以上豌豆大。"},{"name":"对着镜子","say":"对着镜子刷，看得到才刷得到。"},{"name":"固定顺序","say":"从右上开始，一圈一圈刷。"},{"name":"放歌计时","say":"放一首两分钟的歌。"},{"name":"大人补刷","say":"刷完妈妈再帮你刷一次。"},{"name":"漱口收好","say":"漱口，牙刷放回原位。"}],"reactions":[{"if":"孩子刷两下就说好了","then":"用两分钟的歌计时。歌没结束不能停。"},{"if":"孩子抗拒大人补刷","then":"让他先刷（有掌控感），再说「换妈妈检查一下」。用「检查」比「重刷」好接受。"},{"if":"孩子刷牙时乱跑","then":"规定「刷牙要站在洗手台前」。拿着牙刷跑动跌倒会戳伤口腔，这很危险。"}],"mistakes":["只让孩子自己刷不补刷——六岁前刷不干净，蛀牙风险高。","牙膏挤太多——孩子会吞下去，用量要按年龄控制。","让孩子拿着牙刷走动——跌倒会造成口腔穿刺伤，这是真实的意外。"],"down":"大人握着他的手一起刷；只要求刷前面看得到的牙；时间缩短到一分钟。","up":"按固定顺序刷完全口；刷到内侧和咬合面；自己控制牙膏用量；或自己看计时器。","progress":["能刷到哪些区域。","能刷多久。","会不会按顺序刷而不是乱刷。"],"outro":"自己刷是练能力，大人补刷是保护牙齿——六岁以前，这两件事都要做。"}' AS JSON))
WHERE `id` = 'A108';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '沐浴用品'),
  `trains` = COALESCE(`trains`, '学会洗自己的身体，练身体部位认识与动作范围。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"教他从上到下洗：头→脖子→手臂→肚子→腿→脚。"},{"imageUrl":null,"instruction":"边洗边说身体部位的名字。"},{"imageUrl":null,"instruction":"难洗到的地方（背）大人帮忙。"},{"imageUrl":null,"instruction":"洗完自己擦干。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '洗前面看得到的地方'),
  `harder` = COALESCE(`harder`, '连背后、脚趾缝都洗到。'),
  `tip` = COALESCE(`tip`, '洗澡时说身体部位名称，顺便练了语言和身体认识。全程大人要在旁边，浴室要防滑。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"教他从上到下洗：头、脖子、手臂、肚子、腿、脚。边洗边说身体部位的名字，顺便练了语言和身体认识。","principles":["洗澡需要洗到全身各个部位，是很完整的身体部位认识练习。","从上到下的固定顺序，能避免漏掉某些地方。","洗背部需要手臂往后伸，是很好的肩关节活动度练习。","洗脚要弯腰或抬脚，需要平衡和柔软度。","边洗边说部位名称，让语言和身体经验连结在一起。","涂抹沐浴乳的动作是很好的触觉输入，对触觉敏感的孩子是减敏机会。","洗澡是完整的多步骤流程，也是很好的顺序执行练习。","浴室湿滑，这是全篇最需要注意安全的自理项目。"],"prep":{"场地":"浴室，地面铺防滑垫，水温先调好。","器材":"沐浴用品；长柄沐浴刷可以帮忙洗背。","安全检查":"这是本模组安全要求最高的活动。浴室务必防滑、水温先测、全程大人在旁。绝不让孩子单独在浴室。注意地上的水随时擦干。","大人位置":"大人全程在浴室内，帮忙洗不到的地方。"},"shots":[{"name":"安全准备","say":"地上铺防滑垫，水温先调好。"},{"name":"从上到下","say":"从头开始，一路往下洗。"},{"name":"说部位名称","say":"洗脖子、洗手臂、洗肚子。"},{"name":"洗背","say":"背后可以用毛巾两手拉着搓。"},{"name":"洗脚","say":"脚也要洗，脚趾缝也要。"},{"name":"冲干净擦干","say":"冲干净，自己擦干。"}],"reactions":[{"if":"孩子洗不到背","then":"用毛巾两手拉着搓，或用长柄沐浴刷。洗不到的地方大人帮忙。"},{"if":"孩子怕水冲到脸","then":"用毛巾先擦脸，或用洗发帽。不要硬冲，会造成对洗澡的抗拒。"},{"if":"孩子洗得乱七八糟漏东漏西","then":"用「从上到下」的固定顺序，或在浴室贴一张身体部位的图当检查表。"}],"mistakes":["让孩子单独在浴室——这是绝对不行的，溺水和滑倒的风险都很高。","浴室没铺防滑垫——这是最常见的意外来源。","水温没先测——孩子的皮肤比大人敏感，务必先测。"],"down":"大人洗大部分、孩子洗看得到的地方；用固定顺序；只要求洗身体前面。","up":"自己洗全身包括背；自己洗头；自己调水温；或自己完成全部流程。","progress":["能自己洗到哪些部位。","会不会按顺序洗而不遗漏。","能不能自己洗头。"],"outro":"从上到下洗，边洗边说部位的名字。记住——浴室要防滑，大人一定要在旁边。"}' AS JSON))
WHERE `id` = 'A109';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '收纳箱＋照片标签'),
  `trains` = COALESCE(`trains`, '学会把东西放回固定的地方。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"每种玩具有固定的箱子。"},{"imageUrl":null,"instruction":"在箱子上贴该玩具的照片。"},{"imageUrl":null,"instruction":"玩完说「玩具要回家了」。"},{"imageUrl":null,"instruction":"一起收，别只叫他收。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一种玩具归位'),
  `harder` = COALESCE(`harder`, '三四种分类归位。'),
  `tip` = COALESCE(`tip`, '箱子上贴照片，孩子不认字也知道放哪里。「收玩具」还是很好的蹲站运动——一次收拾几十下。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十五（作息时间安排与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"箱子上贴照片，孩子不认字也知道放哪里。「收玩具」还是很好的蹲站运动——一次收拾几十下。","principles":["每种玩具有固定的位置，孩子才知道该放哪里。","在箱子上贴该玩具的照片，是最有效的视觉提示。","不认字的孩子看照片就知道，完全不需要大人指挥。","收玩具的过程中，蹲下捡、站起来放，就是几十次的蹲站运动。","还要走来走去，也是很好的活动量。","把东西按类别放回去，练的是分类概念。","「玩完要收」的习惯，是日后自我管理的基础。","一起收而不是只叫他收——大人参与，孩子的配合度完全不同。"],"prep":{"场地":"孩子玩玩具的区域，收纳箱放在固定位置。","器材":"收纳箱＋照片标签；用手机拍玩具照片印出来贴上。","安全检查":"收纳箱不要太重太高。箱子边缘要平滑。","大人位置":"大人一起收，不要站在旁边指挥。"},"shots":[{"name":"贴照片标签","say":"在箱子上贴该玩具的照片。"},{"name":"宣布收拾","say":"玩具要回家了。"},{"name":"蹲下捡","say":"蹲下来捡起来。"},{"name":"找对箱子","say":"积木要放哪个箱子？"},{"name":"一起收","say":"我们一起收，比较快。"},{"name":"收完欣赏","say":"地板好干净！"}],"reactions":[{"if":"孩子不愿意收","then":"一起收，或用游戏的方式（「看谁收得多」「只收红色的」）。不要只叫他收。"},{"if":"孩子不知道放哪里","then":"贴照片标签。这个方法对不认字的孩子特别有效。"},{"if":"孩子收到一半跑掉","then":"目标订小一点（「先收这十个」），或设定计时器增加趣味。"}],"mistakes":["只叫孩子收、大人在旁边看——配合度会差很多，一起收最有效。","没有固定的位置——不知道放哪里，孩子当然收不好。","嫌他收得慢就自己收——他就永远学不会了。"],"down":"只收一种玩具；箱子数量减少；大人收大部分、他收一部分。","up":"自己按类别分好；收完还要摆整齐；或负责整个房间的收拾。","progress":["能不能自己找对箱子。","能收多少不用提醒。","玩完会不会主动收。"],"outro":"箱子上贴照片，孩子不认字也知道放哪里。而且一起收——大人参与了，配合度完全不同。"}' AS JSON))
WHERE `id` = 'A110';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '书包＋物品清单（图片）'),
  `trains` = COALESCE(`trains`, '学会准备自己的东西，练组织能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"做一张图片清单（水壶、餐袋、联络簿）。"},{"imageUrl":null,"instruction":"让孩子照着清单一样一样放进书包。"},{"imageUrl":null,"instruction":"放一样勾一样。"},{"imageUrl":null,"instruction":"检查完自己背上。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三样'),
  `harder` = COALESCE(`harder`, '五样以上，还要自己检查有没有漏。'),
  `tip` = COALESCE(`tip`, '用照片做清单，孩子不识字也能对照。让他自己准备、自己背——这是责任感的开始。书包别太重。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十五（作息时间安排与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"用照片做清单，孩子不识字也能对照。让他自己准备、自己背——这是责任感的开始。","principles":["准备自己的东西需要记住清单并逐一核对，这是组织能力。","用照片做清单，把记忆的负担转成视觉对照，孩子做得到。","放一样勾一样，是很清楚的完成回馈。","这个流程培养的是「自己的事自己准备」的责任概念。","自己准备的孩子，比较不会忘东忘西，因为他真的经手过。","大人全部准备好，孩子对自己有什么东西完全没概念。","背书包本身也是负重行走的练习，但书包不能太重。","书包重量的建议是不超过体重的百分之十到十五。"],"prep":{"场地":"房间或客厅，把书包和要带的东西摊开。","器材":"书包＋图片清单；用手机拍每样东西印出来做成清单。","安全检查":"书包重量不超过体重的一成到一成五。肩带要调整到合适长度，两边一起背。","大人位置":"大人在旁边，负责做清单和最后检查。"},"shots":[{"name":"做图片清单","say":"把要带的东西拍照，做成清单。"},{"name":"对照清单","say":"看清单，第一样是水壶。"},{"name":"放一样勾一样","say":"放进去了，打个勾。"},{"name":"全部核对","say":"全部都放进去了吗？"},{"name":"检查重量","say":"书包别太重，不超过体重的一成。"},{"name":"自己背上","say":"两边肩带一起背。"}],"reactions":[{"if":"孩子漏掉东西","then":"不要直接放进去。请他「再看一次清单」，让他自己发现。"},{"if":"孩子不想自己准备","then":"先从一两样开始（「你只要负责水壶和餐袋」），做到了再增加。"},{"if":"书包太重","then":"和老师沟通哪些可以留在学校。或用有腰带的书包分担重量。"}],"mistakes":["大人全部准备好——孩子对自己有什么东西完全没概念，也不会有责任感。","孩子漏掉就直接帮他放——让他自己核对发现，才学得到。","书包太重——会影响姿势发育，重量要控制。"],"down":"清单只有两三样；大人念清单他来放；一起准备。","up":"完整清单自己准备；前一晚就准备好；或自己列清单。","progress":["能不能对照清单准备完整。","漏掉的次数有没有减少。","会不会主动在前一晚准备。"],"outro":"用照片做清单，孩子不识字也能对照。自己准备、自己背——责任感就是这样开始的。"}' AS JSON))
WHERE `id` = 'A111';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '碗筷、餐垫'),
  `trains` = COALESCE(`trains`, '帮忙摆餐桌，练分配与生活参与。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子数人数、拿对应数量的碗筷。"},{"imageUrl":null,"instruction":"一人一份摆好。"},{"imageUrl":null,"instruction":"可以在餐垫上画出碗筷的位置当参考。"},{"imageUrl":null,"instruction":"摆好了全家道谢。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '摆两人份'),
  `harder` = COALESCE(`harder`, '全家份，还要分清谁的杯子。'),
  `tip` = COALESCE(`tip`, '摆餐具同时练了数数、对应和责任感——被需要的孩子，做得特别起劲。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"让孩子数人数、拿对应数量的碗筷，一人一份摆好。摆餐具同时练了数数、对应和责任感——被需要的孩子，做得特别起劲。","principles":["数人数再拿对应数量的碗筷，练的是一对一对应的概念。","一对一对应是数学最基础的概念，比背数字更重要。","把碗筷摆到每个人的位置，还需要空间安排的概念。","在餐垫上画出碗筷的位置当参考，是很好的视觉提示。","拿取和摆放碗筷需要小心，是很好的精细动作和控制力练习。","摆餐具是全家都看得到的贡献，孩子的价值感很强。","这个任务每天都有，是最容易固定下来的家务。","摆好之后全家道谢，这个回馈会让他明天还想做。"],"prep":{"场地":"餐桌，碗筷放在孩子拿得到的地方。","器材":"碗筷、餐垫；可以在餐垫上画出碗筷的位置。","安全检查":"不要用玻璃或陶瓷的（会破）。筷子不要拿着跑。热的食物由大人端。","大人位置":"大人在旁边，负责端热的东西。"},"shots":[{"name":"数人数","say":"今天几个人吃饭？"},{"name":"拿对应数量","say":"那要拿几个碗？"},{"name":"餐垫做记号","say":"餐垫上画好位置，照着摆。"},{"name":"一人一份","say":"一个人一份，摆好。"},{"name":"检查","say":"看看每个位置都有了吗？"},{"name":"全家道谢","say":"谢谢你摆好餐桌！"}],"reactions":[{"if":"孩子拿错数量","then":"请他再数一次人数、再数一次碗。让他自己发现差异。"},{"if":"孩子不知道怎么摆","then":"在餐垫上画出位置。照着摆就不会错。"},{"if":"孩子摆一半就跑掉","then":"先只负责一部分（「你负责摆碗就好」），做到了再加。"}],"mistakes":["用会破的碗盘——摔破会吓到孩子也危险，用不易破的。","嫌他摆得慢就自己摆——他就没机会练了。","摆好了没道谢——回馈是动机的来源，一定要说。"],"down":"只负责摆碗或只摆筷子；餐垫画好位置；人数少的时候练。","up":"负责全部餐具；自己数人数并准备；或加上摆菜和倒水。","progress":["能不能数对人数拿对数量。","能不能自己摆到正确位置。","会不会主动帮忙。"],"outro":"数人数、拿碗筷、一人一份——数数、对应和责任感一起练。摆好了记得郑重道谢。"}' AS JSON))
WHERE `id` = 'A112';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '小件衣物（毛巾、内衣）'),
  `trains` = COALESCE(`trains`, '练双手配合和对称概念。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"从最简单的方巾开始：对折、再对折。"},{"imageUrl":null,"instruction":"再练小内衣、小裤子。"},{"imageUrl":null,"instruction":"可以在桌上画折线当参考。"},{"imageUrl":null,"instruction":"折好一起放进衣柜。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '折方巾对折两次'),
  `harder` = COALESCE(`harder`, '折上衣（要折袖子）。'),
  `tip` = COALESCE(`tip`, '折衣服要两只手配合、还要对齐——是很好的双手协调练习。折得不整齐没关系，别重折给他看。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组六（双侧协调与跨中线）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"从最简单的方巾开始：对折、再对折。折得不整齐没关系，别重折给他看——那会让他觉得帮忙没意义。","principles":["折衣服需要两只手同时抓住两个角，往中间对齐。","这是双手对称协调，两只手要做镜像的动作。","对齐边角需要视觉判断和精准的手部控制。","对折的概念本身就是对称，这和数学的对称概念相通。","方巾最简单，因为是正方形、对折两次就好。","衣服有袖子，折起来更复杂，要分几个步骤。","在桌上画折线当参考，是很有效的视觉提示。","折好了自己放进衣柜，完整的流程比只折不收有意义。"],"prep":{"场地":"餐桌或床上，平坦的表面比较好折。","器材":"小件衣物（方巾、毛巾、内衣）；可以在桌上贴胶带标示折线。","安全检查":"无特殊风险。","大人位置":"大人坐在旁边一起折，示范但不重折他的。"},"shots":[{"name":"从方巾开始","say":"先从最简单的方巾开始。"},{"name":"双手抓两角","say":"两只手抓住两个角。"},{"name":"对折","say":"对齐了，折过来。"},{"name":"再对折","say":"再折一次，就好了。"},{"name":"画折线辅助","say":"桌上画线当参考也可以。"},{"name":"放进衣柜","say":"折好了自己放进去。"}],"reactions":[{"if":"孩子折得歪七扭八","then":"不要重折。先说「谢谢你帮忙」，整齐是慢慢练的。"},{"if":"孩子对不准边角","then":"在桌上用胶带贴出折线当参考。或先折小一点的方巾。"},{"if":"孩子不想折","then":"只负责折自己的衣服，或只折最简单的方巾。"}],"mistakes":["当着孩子的面重折——这会让他觉得自己做得不好、帮忙没意义。","一开始就折衣服——衣服有袖子很复杂，先折方巾。","只让他折不让他收——完整的流程（折好放进去）比较有意义。"],"down":"只折方巾；桌上画折线当参考；大人折一半他折一半。","up":"折有袖子的衣服；折裤子；或负责整篮衣服。","progress":["能折哪些（方巾／内衣／上衣）。","边角对得准不准。","会不会自己收进衣柜。"],"outro":"从方巾开始，对折再对折。折得不整齐没关系——别当着他的面重折，那会让他觉得帮忙没意义。"}' AS JSON))
WHERE `id` = 'A113';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '抹布'),
  `trains` = COALESCE(`trains`, '负责自己的空间，练手臂动作与责任感。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"吃完饭或画完画，让孩子擦自己的桌面。"},{"imageUrl":null,"instruction":"教他从一边擦到另一边，不要乱擦。"},{"imageUrl":null,"instruction":"擦完检查有没有漏。"},{"imageUrl":null,"instruction":"郑重道谢。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '擦一小块'),
  `harder` = COALESCE(`harder`, '整张桌子都擦干净，包含边角。'),
  `tip` = COALESCE(`tip`, '「有系统地擦」（从左到右、一排一排）比乱擦有效——这个习惯将来在看书、找东西时也用得上。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"教他从一边擦到另一边，不要乱擦。「有系统地擦」比乱擦有效——这个习惯将来在看书、找东西时也用得上。","principles":["有系统地擦（从左到右、一排一排）比随机乱擦有效得多。","这个「有系统」的概念，可以迁移到看书、找东西、检查作业上。","擦的动作需要手臂持续施压并来回移动，是上肢的肌耐力训练。","要擦干净必须用力压下去，这是力道的控制。","另一只手可能要扶住桌子或移开东西，是双手分工。","擦完检查有没有漏，练的是自我检核的习惯。","负责自己的桌子，是最小单位的「负责自己的空间」。","这个概念会延伸到负责自己的房间、自己的物品。"],"prep":{"场地":"孩子吃饭或画画的桌子。","器材":"抹布；拧干一点比较好握。","安全检查":"抹布要干净。桌面上的东西先移开。不要站在椅子上擦。","大人位置":"大人在旁边，示范有系统的擦法。"},"shots":[{"name":"先清空","say":"先把桌上的东西移开。"},{"name":"从一边开始","say":"从这一边开始，一排一排擦。"},{"name":"用力压","say":"要压下去才擦得干净。"},{"name":"乱擦的对照","say":"乱擦的话会有地方漏掉。"},{"name":"检查","say":"看看有没有漏掉的地方？"},{"name":"道谢","say":"谢谢你，桌子好干净！"}],"reactions":[{"if":"孩子乱擦一通","then":"示范「一排一排」的擦法。可以在桌上贴胶带分区，一区一区擦。"},{"if":"孩子擦不干净","then":"别急着重擦。先道谢，再一起看看哪里可以再擦一次。"},{"if":"孩子擦一下就说好了","then":"请他检查「有没有漏掉的地方」，让他自己发现。"}],"mistakes":["嫌他擦不干净就自己重做——先道谢，再一起补。","不教方法只叫他擦——有系统地擦是可以迁移的能力，一定要教。","让孩子站在椅子上擦——很危险，高处让大人擦。"],"down":"只擦一小块；桌上贴胶带分区；大人擦一半他擦一半。","up":"擦整张桌子；擦完还要擦椅子；或负责餐后的整个清理。","progress":["会不会有系统地擦而不是乱擦。","能不能自己检查有没有漏。","会不会主动擦自己的桌子。"],"outro":"一排一排擦，不要乱擦。这个「有系统」的习惯，将来看书、找东西、检查作业都用得上。"}' AS JSON))
WHERE `id` = 'A114';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要特别准备'),
  `trains` = COALESCE(`trains`, '帮忙跑腿，练记住任务和完成任务。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"请孩子帮忙：把这个拿给爸爸、把垃圾丢掉。"},{"imageUrl":null,"instruction":"一次一件事，说清楚。"},{"imageUrl":null,"instruction":"完成了郑重道谢。"},{"imageUrl":null,"instruction":"慢慢增加成两件事。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一件事、目标就在眼前'),
  `harder` = COALESCE(`harder`, '两三件事，或要走到别的房间。'),
  `tip` = COALESCE(`tip`, '跑腿同时练了记忆、听指令和责任感——「妈妈需要你帮忙」这句话，对孩子的价值感很重要。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十（指令理解与执行）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"请孩子帮忙跑腿，一次一件事、说清楚。「妈妈需要你帮忙」这句话，对孩子的价值感很重要。","principles":["跑腿需要记住指令的内容并执行到完成，这是工作记忆的实际运用。","一次一件事，是因为学龄前孩子的工作记忆容量有限。","任务完成后回来报告，是完整的任务闭环。","移动、搬运、开关门，都是身体活动，运动量不小。","「妈妈需要你帮忙」这句话，让孩子感受到自己是有用的。","被需要的感觉，是自我价值感最直接的来源。","完成任务后的郑重道谢，会让他下次更愿意帮忙。","慢慢增加成两件事，可以自然地扩展工作记忆的容量。"],"prep":{"场地":"家里任何地方，路线清空。","器材":"不需要特别准备；日常的东西就好。","安全检查":"不要请孩子搬太重或易碎的东西。倒垃圾时注意垃圾袋里没有尖锐物。路线上清空。","大人位置":"大人说清楚任务，完成后郑重道谢。"},"shots":[{"name":"请求帮忙","say":"可以帮妈妈一个忙吗？"},{"name":"说清楚任务","say":"把这个拿给爸爸。"},{"name":"复述一次","say":"你要拿给谁？"},{"name":"去执行","say":"去吧！"},{"name":"完成回报","say":"我拿给爸爸了！"},{"name":"郑重道谢","say":"谢谢你，帮了大忙！"}],"reactions":[{"if":"孩子走到一半忘记要做什么","then":"让他出发前先复述一次。说出来能大幅提高记住的机会。"},{"if":"孩子不想帮忙","then":"用「妈妈需要你」的说法，而不是命令。被需要比被要求好接受得多。"},{"if":"孩子做到一半跑去玩","then":"任务简单一点、距离近一点。先从一步就到的任务开始。"}],"mistakes":["一次交代好几件事——学龄前的孩子记不住，一次一件。","完成了没道谢——回馈是动机的来源，一定要说。","用命令的语气——「妈妈需要你帮忙」比「去把这个拿过去」有效得多。"],"down":"一次一件、距离很近；出发前复述一次；大人陪着走。","up":"一次两件事；距离加长；或加上「回来告诉我爸爸说什么」。","progress":["能记住并完成几件事。","会不会走到一半忘记。","会不会主动问「有什么要我帮忙的」。"],"outro":"一次一件事、说清楚、完成后郑重道谢。「妈妈需要你帮忙」这句话，对孩子的价值感很重要。"}' AS JSON))
WHERE `id` = 'A115';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '简单的食材'),
  `trains` = COALESCE(`trains`, '参与做食物的过程，练手部动作与步骤概念。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选步骤简单的：涂果酱、夹三明治、洗水果、搅拌。"},{"imageUrl":null,"instruction":"一步一步来，让他做得到的都自己做。"},{"imageUrl":null,"instruction":"做好了全家一起吃。"},{"imageUrl":null,"instruction":"过程中念出步骤。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '做一个步骤（涂酱）'),
  `harder` = COALESCE(`harder`, '三个步骤连着完成。'),
  `tip` = COALESCE(`tip`, '做点心把手部动作、步骤概念和成就感全包了——最后还能吃，孩子的动机满分。用刀的部分由大人来。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2–3 分钟","intro":"选步骤简单的：涂果酱、夹三明治、洗水果、搅拌。做点心把手部动作、步骤概念和成就感全包了——最后还能吃。","principles":["做点心有明确的步骤顺序，是很好的流程执行练习。","每个步骤用到不同的手部动作：涂、夹、洗、搅、压。","涂果酱需要控制力道和范围，和涂色是类似的能力。","搅拌需要手腕持续转动，是很好的前臂旋转练习。","过程中念出步骤，让语言和动作连结在一起。","孩子参与制作的食物，吃的意愿会明显提高。","这对挑食的孩子特别有用——自己做的比较愿意尝试。","最后能吃到成品，是动机最强的活动之一。"],"prep":{"场地":"厨房或餐桌，孩子要构得到（必要时垫脚凳）。","器材":"简单的食材：吐司、果酱、水果、优格；不需要用火的最好。","安全检查":"用刀和用火的部分由大人负责。垫脚凳要稳。事先洗手。注意食材过敏。","大人位置":"大人负责危险的步骤，其他都让孩子做。"},"shots":[{"name":"洗手","say":"做东西吃之前要先洗手。"},{"name":"念步骤","say":"我们先涂果酱，再放水果，最后夹起来。"},{"name":"涂果酱","say":"涂平一点，涂到边边。"},{"name":"放水果","say":"水果放上去。"},{"name":"夹起来","say":"盖上去，压一压。"},{"name":"一起吃","say":"我们做的！"}],"reactions":[{"if":"孩子涂得乱七八糟","then":"没关系，能吃就好。这是练习不是比赛。"},{"if":"孩子想用刀","then":"给儿童安全刀切软的东西（香蕉、吐司），真正的刀由大人用。"},{"if":"孩子做到一半不想做了","then":"步骤再简化。选三个步骤以内的点心。"}],"mistakes":["让孩子用火或用真正的刀——这两件事由大人负责，不能妥协。","步骤太复杂——三个步骤以内最适合，太复杂会做不完。","大人主导全部——每个安全的步骤都让孩子做。"],"down":"步骤减到两个；只做最简单的（涂果酱、洗水果）；大人准备好材料。","up":"步骤增加；自己看图谱做；或负责整道点心的制作。","progress":["能完成几个步骤。","会不会按顺序做。","愿不愿意尝试自己做的食物。"],"outro":"做点心把手部动作、步骤概念和成就感全包了。用刀和用火的部分由大人来——其他都让孩子做。"}' AS JSON))
WHERE `id` = 'A116';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸笔或照片'),
  `trains` = COALESCE(`trains`, '照着固定流程完成睡前的事，练自我管理。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"和孩子一起列睡前要做的事：洗澡→刷牙→换睡衣→讲故事→睡觉。"},{"imageUrl":null,"instruction":"画成图或拍成照片贴在墙上。"},{"imageUrl":null,"instruction":"每天照着做，做完一项打个勾。"},{"imageUrl":null,"instruction":"慢慢让他自己看图完成。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三个步骤'),
  `harder` = COALESCE(`harder`, '五六个步骤自己完成。'),
  `tip` = COALESCE(`tip`, '固定的流程能减少每天的拉锯战——「不是妈妈叫你去刷牙，是流程表说该刷牙了」，孩子的抗拒会少很多。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十五（作息时间安排与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把睡前要做的事画成图贴在墙上。「不是妈妈叫你去刷牙，是流程表说该刷牙了」——孩子的抗拒会少很多。","principles":["固定的流程能减少每天的拉锯战，因为没有讨价还价的空间。","把指令从「妈妈说」变成「流程表说」，冲突的对象就不是人了。","这个转移能大幅减少亲子之间的权力斗争。","流程图提供了可预期性，孩子知道接下来会发生什么，安全感更好。","对需要结构的孩子（如自闭症特质）特别有帮助。","照着图完成一项打一个勾，是清楚的进度回馈。","和孩子一起列流程，他的参与感会提高执行的意愿。","慢慢让他自己看图完成，这就是自我管理的开始。"],"prep":{"场地":"孩子看得到的墙上，最好在房间门口或浴室旁。","器材":"纸笔或照片；用孩子自己的照片做流程图最有效。","安全检查":"无特殊风险。","大人位置":"大人和孩子一起列流程、一起做图。"},"shots":[{"name":"一起列流程","say":"睡前我们要做哪些事？"},{"name":"做成图","say":"我们把它画成图（或拍成照片）。"},{"name":"贴在墙上","say":"贴在看得到的地方。"},{"name":"照着做","say":"流程表说，现在该刷牙了。"},{"name":"打勾","say":"做完一项打个勾。"},{"name":"全部完成","say":"全部做完，可以睡觉了。"}],"reactions":[{"if":"孩子还是不愿意做","then":"指着流程图说「表上说该做什么了？」把焦点从人转到表上。"},{"if":"孩子跳过其中一项","then":"请他看图核对「都做完了吗？」让图来提醒。"},{"if":"孩子觉得流程太多","then":"减到三四项。太多会失去效果。"}],"mistakes":["大人自己列流程——和孩子一起列，他的参与感和配合度差很多。","流程项目太多——三到五项最合适。","做了图却不用——每天都要指着图，习惯才建立得起来。"],"down":"流程减到三项；用照片而非文字；大人陪着一项一项做。","up":"增加项目；自己看图完成不用提醒；或加上时间的安排。","progress":["能不能照着流程完成。","需要多少提醒。","会不会主动去看流程图。"],"outro":"「不是妈妈叫你去刷牙，是流程表说该刷牙了」——把指令转移到表上，孩子的抗拒会少很多。"}' AS JSON))
WHERE `id` = 'A117';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '流程图'),
  `trains` = COALESCE(`trains`, '照流程完成出门前的准备，练时间概念与效率。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"列出早上要做的事：起床→穿衣→吃早餐→刷牙→背书包。"},{"imageUrl":null,"instruction":"画成流程图贴在显眼的地方。"},{"imageUrl":null,"instruction":"前一晚先把衣服和书包准备好。"},{"imageUrl":null,"instruction":"做完一项就打勾。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着大人一项一项做'),
  `harder` = COALESCE(`harder`, '自己看图完成大部分。'),
  `tip` = COALESCE(`tip`, '前一晚准备好，早上就少一半的兵荒马乱。孩子慢不是故意的——给他多一点时间，比一直催有用。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十五（作息时间安排与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"前一晚先把衣服和书包准备好，早上就少一半的兵荒马乱。孩子慢不是故意的——给他多一点时间，比一直催有用。","principles":["早上的混乱大多来自准备不足和时间不够。","前一晚准备好衣服和书包，能消除早上最大的两个变量。","流程图让孩子知道下一步要做什么，不用大人一直指挥。","孩子动作慢是发展的正常现象，不是故意拖延。","一直催促会让孩子焦虑，焦虑反而让动作更慢。","提早十五分钟起床，比催十五次有效得多。","做完一项打勾，让进度变得可见，孩子也有掌控感。","这个流程练的是时间概念和自我管理，是很重要的能力。"],"prep":{"场地":"房间和客厅，流程图贴在显眼的地方。","器材":"流程图；前一晚准备好的衣服和书包。","安全检查":"无特殊风险。","大人位置":"大人前一晚陪着准备，早上少催多等。"},"shots":[{"name":"前一晚准备","say":"前一天晚上先把衣服和书包准备好。"},{"name":"流程图","say":"早上的流程贴在这里。"},{"name":"照着做","say":"第一项，穿衣服。"},{"name":"打勾","say":"做完打个勾。"},{"name":"不催促","say":"慢慢来，时间还够。"},{"name":"准时出门","say":"准备好了，出发！"}],"reactions":[{"if":"孩子每天早上都很慢","then":"提早十五分钟起床，比催十五次有效。也检查前一晚有没有准备好。"},{"if":"孩子一直分心","then":"把玩具和电视收起来。环境单纯了，效率自然提高。"},{"if":"大人忍不住一直催","then":"指着流程图问「下一项是什么？」把催促换成提问。"}],"mistakes":["早上才开始找东西——前一晚准备，能省下一半的混乱。","一直催促——催会让孩子焦虑，动作反而更慢。","时间抓太紧——提早起床，比什么方法都有效。"],"down":"流程减到三项；大人陪着一项一项做；前一晚准备得更完整。","up":"自己看流程完成；自己前一晚准备；或加上看时钟的时间管理。","progress":["早上需要提醒几次。","能不能照流程自己完成。","会不会前一晚主动准备。"],"outro":"前一晚准备好，早上少一半混乱。孩子慢不是故意的——提早十五分钟起床，比催十五次有用。"}' AS JSON))
WHERE `id` = 'A118';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '日常家务'),
  `trains` = COALESCE(`trains`, '每天有一件固定负责的事，建立责任感。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"和孩子讨论他可以负责什么（浇花、摆碗筷、收自己的玩具）。"},{"imageUrl":null,"instruction":"做成一张「小帮手任务卡」。"},{"imageUrl":null,"instruction":"每天完成就打勾。"},{"imageUrl":null,"instruction":"完成一周给个小庆祝。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一项简单的任务'),
  `harder` = COALESCE(`harder`, '两三项，或需要记得时间的任务。'),
  `tip` = COALESCE(`tip`, '让孩子有一件「这是我负责的事」——被需要的感觉，比任何奖励都能养出责任感。做不好也别收回来，教他做好就行。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四（日常生活自理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"让孩子有一件「这是我负责的事」——被需要的感觉，比任何奖励都能养出责任感。做不好也别收回来，教他做好就行。","principles":["有一件固定负责的事，孩子才会产生「这是我的责任」的概念。","责任感不是靠说教养出来的，而是靠实际承担。","和孩子讨论他可以负责什么，让他有选择权，承担的意愿会更高。","任务要选他做得到的，成功经验才能持续。","每天完成打勾，累积的记录会带来成就感。","做不好就把任务收回来，会传达「你做不到」的讯息。","正确的做法是教他做好，而不是替他做。","一周完成给个小庆祝，让坚持有个看得见的里程碑。"],"prep":{"场地":"家里，任务卡贴在显眼处。","器材":"一张「小帮手任务卡」＋贴纸或印章。","安全检查":"任务要选安全的，不涉及用火、用刀、爬高。","大人位置":"大人和孩子一起讨论任务，完成后认真肯定。"},"shots":[{"name":"一起讨论","say":"你想负责什么呢？"},{"name":"做任务卡","say":"我们做一张小帮手任务卡。"},{"name":"每天执行","say":"今天的任务：浇花。"},{"name":"打勾","say":"做完了，打个勾！"},{"name":"做不好就教","say":"做不好没关系，我们一起看看怎么做更好。"},{"name":"一周庆祝","say":"一整个星期都做到了！"}],"reactions":[{"if":"孩子做几天就忘了","then":"把任务卡贴在显眼处，或和固定的时间绑在一起（吃完晚餐就浇花）。"},{"if":"孩子做得不好","then":"教他做好，不要收回任务。收回来会传达「你做不到」的讯息。"},{"if":"孩子想换任务","then":"可以换。一段时间换一次也能保持新鲜感。"}],"mistakes":["做不好就收回任务——这会打击他的信心，正确做法是教他做好。","大人指定任务——和他讨论，让他选，承担的意愿差很多。","任务太难——选他做得到的，成功经验才能持续。"],"down":"任务简单一点；一周只做三天；大人陪着一起做。","up":"增加任务数量；任务难度提高；或让他自己想新的任务。","progress":["一周能完成几次。","需不需要提醒。","会不会主动做。"],"outro":"让孩子有一件「这是我负责的事」。做不好别收回来——教他做好，责任感就是这样长出来的。"}' AS JSON))
WHERE `id` = 'A119';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一张记录表'),
  `trains` = COALESCE(`trains`, '检视孩子已经会哪些自理，定出下一个目标。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"列出这个模组的项目：吃饭、喝水、脱衣、穿衣、穿鞋、洗手、刷牙、收玩具……"},{"imageUrl":null,"instruction":"一起打勾：已经会的、需要帮忙的、还不会的。"},{"imageUrl":null,"instruction":"从「需要帮忙的」里挑一两项当这个月的目标。"},{"imageUrl":null,"instruction":"会了就贴一张贴纸。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '先看会不会'),
  `harder` = COALESCE(`harder`, '记录进步的程度（从需要帮忙到完全独立）。'),
  `tip` = COALESCE(`tip`, '自理能力是一步一步长出来的，不必和别的孩子比。每个月盯一两项，一年下来就是十几项新能力。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十四～十五（日常生活自理 · 作息与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"列出这个模组的项目，一起打勾：已经会的、需要帮忙的、还不会的。每个月盯一两项，一年下来就是十几项新能力。","principles":["把自理能力列成清单，可以清楚看到孩子目前的状态。","分成三类（会了、需要帮忙、还不会）比只分会不会更精准。","「需要帮忙的」那一类，就是最适合当下练习的目标。","一次只挑一两项，专注练习的效果比什么都练好。","每个月一两项，一年下来就是十几项新能力，累积很可观。","和孩子一起打勾，他能看到自己的进步，成就感很强。","自理能力的发展速度个别差异很大，不需要和别人比。","重点是「比上个月的自己进步」，而不是「和别的孩子一样」。"],"prep":{"场地":"餐桌，和孩子一起坐下来看清单。","器材":"一张记录表＋贴纸；把模组里的项目都列上去。","安全检查":"无特殊风险。","大人位置":"大人和孩子一起检视，态度要正向。"},"shots":[{"name":"列出清单","say":"我们把这些事都列出来。"},{"name":"一起打勾","say":"这个你会了吗？"},{"name":"分三类","say":"会了、需要帮忙、还不会。"},{"name":"挑目标","say":"我们这个月来练这一项。"},{"name":"会了贴贴纸","say":"会了就贴一张贴纸。"},{"name":"一年回顾","say":"你看，今年学会了这么多！"}],"reactions":[{"if":"孩子会的项目很少","then":"不用焦虑。挑一两项开始练就好，一年下来会很可观。"},{"if":"孩子不想被检视","then":"把它讲成「看看你长大了多少」，而不是「检查你会不会」。"},{"if":"家长忍不住和别人比","then":"自理能力的个别差异很大。看的是「比上个月进步」，不是和别人比。"}],"mistakes":["一次想练很多项——专注一两项，效果好得多。","和别的孩子比——个别差异很大，比较只会带来焦虑。","只看还不会的——先肯定已经会的，孩子才有动力。"],"down":"清单缩短到十项；这个月只挑一项；标准放宽。","up":"完整清单；一次挑两三项；或让孩子自己设定目标。","progress":["会了的项目数量。","每个月新增几项。","会不会主动想学新的。"],"outro":"自理能力是一步一步长出来的，不必和别的孩子比。每个月盯一两项，一年下来就是十几项新能力。"}' AS JSON))
WHERE `id` = 'A120';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '6个月–3岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '听到自己的名字会转头看，是社交回应的第一步。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在孩子侧后方温和地叫他的名字。"},{"imageUrl":null,"instruction":"他转头看你就立刻笑、抱抱、或给个小惊喜。"},{"imageUrl":null,"instruction":"名字后面永远接好事。"},{"imageUrl":null,"instruction":"不同的人、不同的地方都叫叫看。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '近距离叫、他没在专心时叫'),
  `harder` = COALESCE(`harder`, '他专心玩的时候叫，也能回应。'),
  `tip` = COALESCE(`tip`, '叫名字后面一定要接好事（拥抱、玩具、举高高）——千万别用名字来骂人，不然孩子会学会「装作没听到」。持续叫不应，建议带去评估听力与发展。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组一（社交起点·关注与回应）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"叫孩子的名字，他转头看你——这是社交回应的第一步。但有一条铁律：名字后面永远要接好事，千万别用名字来骂人。","principles":["听到自己的名字会转头，代表孩子知道「这个声音在叫我」。","这是自我概念和社交回应最早的表现之一。","名字是最早被辨认出来的语音之一，因为重复的次数最多。","转头看人还包含了眼神接触，这是社交互动的起点。","如果名字后面常常接的是责骂，孩子会学会「装作没听到」。","这叫做名字的负向连结，一旦形成很难扭转。","所以名字后面一定要接拥抱、玩具、举高高这些好事。","持续叫不应，或是六个月后仍完全没有反应，建议带去评估听力与发展。"],"prep":{"场地":"安静一点的环境，背景音量小，孩子才听得清楚。","器材":"不需要任何东西；可以准备一个小玩具当惊喜。","安全检查":"无特殊风险。若孩子对声音完全没反应，务必尽早就医评估听力。","大人位置":"大人站或蹲在孩子侧后方约一两步的距离。"},"shots":[{"name":"侧后方叫","say":"（轻声叫孩子的名字）"},{"name":"孩子转头","say":""},{"name":"立刻给好事","say":"你来啦！抱抱！"},{"name":"换个方向","say":"（从另一侧叫）"},{"name":"换个人叫","say":"换爸爸叫叫看。"},{"name":"铁律提醒","say":"名字后面永远接好事。"}],"reactions":[{"if":"孩子完全不转头","then":"先靠近一点、声音大一点，同时轻拍他的肩膀。有反应了再慢慢拉远距离。"},{"if":"孩子有时应有时不应","then":"看看是不是在专心做别的事。专注时不回应是正常的，可以先走到他面前。"},{"if":"持续叫都没有反应","then":"这是重要的警讯。建议尽早带去评估听力与发展，越早发现越好处理。"}],"mistakes":["用名字来骂人——这是最伤的做法，孩子会学会「装作没听到」。","一直重复叫很多次——叫两三次没反应就走过去，一直叫会让名字失去效力。","孩子回应了却没给回馈——回应之后一定要有好事发生。"],"down":"距离近一点、声音大一点；同时轻拍肩膀给触觉提示。","up":"距离拉远；在有背景音的环境叫；或从看不见的地方叫。","progress":["叫几次会转头。","在有背景音的环境还有没有反应。","不同的人叫是不是都有反应。"],"outro":"叫名字后面一定要接好事——拥抱、玩具、举高高。千万别用名字来骂人，不然孩子会学会装作没听到。"}' AS JSON))
WHERE `id` = 'A121';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '顺着大人的手指看过去，练「一起注意同一件事」。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"指着近处有趣的东西说「你看！」"},{"imageUrl":null,"instruction":"他看过去就一起惊叹、一起笑。"},{"imageUrl":null,"instruction":"看完记得对望一眼（这一步很关键）。"},{"imageUrl":null,"instruction":"从近到远、从明显到不明显。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '指近处明显的东西'),
  `harder` = COALESCE(`harder`, '指远处的，看完还要回头和你交流。'),
  `tip` = COALESCE(`tip`, '「一起看、一起开心」是语言发展的核心地基——散步时多指东西给孩子看（小狗、花、车），看完对视笑一笑。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组一（共同注意与互动基础）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"指着东西说「你看！」，孩子顺着看过去，然后你们对望一眼——这一眼是语言发展的核心地基。","principles":["顺着别人的手指看过去，叫做跟随共同注意。","这代表孩子理解「别人的注意力可以被引导」，是社会认知的重要一步。","看完之后回头看大人的那一眼，叫做注意力的交替。","这一眼最关键——它代表孩子在确认「我们是不是在看同一件事」。","共同注意是语言发展最强的预测指标之一。","因为语言学习需要「我说的这个词，指的是我们都在看的那个东西」。","没有共同注意，孩子就很难把词和物连结起来。","散步时多指东西给孩子看，是最自然的练习方式。"],"prep":{"场地":"户外散步或室内，环境中要有值得看的东西。","器材":"不需要任何东西；环境本身就是教材。","安全检查":"户外注意交通安全，牵好手。","大人位置":"大人蹲下到孩子的高度，手臂伸直指向目标。"},"shots":[{"name":"蹲下指","say":"你看，小狗！"},{"name":"孩子看过去","say":""},{"name":"一起惊叹","say":"哇——好可爱！"},{"name":"对望一眼","say":""},{"name":"从近到远","say":"那边还有一只！"},{"name":"换他指","say":"你看到什么？指给妈妈看。"}],"reactions":[{"if":"孩子只看你的手不看目标","then":"很常见。可以先指很近的东西，或直接把东西拿到他面前，再慢慢拉远。"},{"if":"孩子看了但不回头看你","then":"看完主动发出声音吸引他回头。这一眼的交替是重点。"},{"if":"孩子完全不跟随手指","then":"加上声音和夸张的表情。若长期都不跟随，值得跟治疗师提一下。"}],"mistakes":["站着指——孩子看不到你的脸也看不清方向，一定要蹲下。","只指不惊叹——「一起开心」才是重点，指完要有情绪的分享。","忽略回头对望的那一眼——这一步最关键，别急着指下一个。"],"down":"指很近的东西；目标很明显（会动、会响）；加上声音。","up":"指远处的目标；目标不明显；只用眼神看不用手指。","progress":["会不会顺着手指看过去。","看完会不会回头看你。","会不会主动指东西给你看。"],"outro":"「一起看、一起开心」是语言发展的核心地基。散步时多指东西给孩子看——看完记得对视笑一笑。"}' AS JSON))
WHERE `id` = 'A122';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子有兴趣的东西'),
  `trains` = COALESCE(`trains`, '孩子主动把东西拿给你看，是很珍贵的沟通动机。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子拿到新奇的东西时问「哇，给妈妈看看？」"},{"imageUrl":null,"instruction":"他举起来或拿过来，就热情惊叹「哇——好棒！」"},{"imageUrl":null,"instruction":"回应他的人比回应东西更重要（看他的眼睛）。"},{"imageUrl":null,"instruction":"你也拿东西给他看，示范一下。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '在引导下拿给你看'),
  `harder` = COALESCE(`harder`, '主动拿过来炫耀。'),
  `tip` = COALESCE(`tip`, '孩子拿东西给你看的时候，放下手机热烈回应——他分享的不是东西，是开心。这是沟通动机最珍贵的表现。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组一（社交起点·关注与回应）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子拿东西给你看的时候，放下手机热烈回应——他分享的不是东西，是开心。这是沟通动机最珍贵的表现。","principles":["主动把东西拿给别人看，叫做展示行为。","展示和「要东西」不同——他不是想要什么，只是想分享。","这种纯粹为了分享而进行的沟通，叫做社会性沟通。","社会性沟通是最难教也最珍贵的沟通动机。","孩子愿意分享他的发现，代表他把你当成可以分享心情的对象。","这时候回应「他这个人」比回应「那个东西」更重要——要看他的眼睛。","如果每次分享都被敷衍，这个动机会慢慢消失。","大人也要主动拿东西给孩子看，示范这个行为。"],"prep":{"场地":"任何地方，孩子在玩的时候最自然。","器材":"孩子有兴趣的东西；不需要特别准备。","安全检查":"无特殊风险。","大人位置":"大人放下手上的事，专注回应。"},"shots":[{"name":"孩子发现东西","say":""},{"name":"邀请分享","say":"哇，给妈妈看看？"},{"name":"拿过来","say":""},{"name":"看他的眼睛","say":"哇——好棒！"},{"name":"放下手机","say":""},{"name":"大人示范","say":"你看我找到什么！"}],"reactions":[{"if":"孩子从来不主动分享","then":"大人先示范——常常拿东西给他看。也可以在他发现东西时主动问「给妈妈看看？」"},{"if":"孩子拿过来就走了不看你","then":"蹲下到他的高度，先看他的眼睛再看东西。眼神接触是重点。"},{"if":"孩子拿了又不给","then":"不要抢。看着就好，说「好漂亮」。分享的重点不是交出来。"}],"mistakes":["一边滑手机一边说「嗯，很棒」——这是最伤动机的回应方式。","只看东西不看孩子——要看他的眼睛，他分享的是开心不是物品。","嫌他一直拿东西来烦——这个动机很珍贵，别浇熄它。"],"down":"大人主动邀请「给我看看」；大人先示范分享的行为。","up":"等他完全主动地拿来；鼓励他也说出物品名称；或分享给其他家人。","progress":["会不会主动拿东西给你看。","拿来时会不会看你的眼睛。","一天大概分享几次。"],"outro":"孩子拿东西给你看的时候，放下手机、看着他的眼睛热烈回应——他分享的不是东西，是开心。"}' AS JSON))
WHERE `id` = 'A123';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '6个月–3岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '球或简单的玩具'),
  `trains` = COALESCE(`trains`, '体验「你一次、我一次」的来回，是对话的雏形。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"和孩子来回滚球、来回传玩具。"},{"imageUrl":null,"instruction":"边玩边说「给你」「给我」。"},{"imageUrl":null,"instruction":"玩躲猫猫、拍手歌也算。"},{"imageUrl":null,"instruction":"熟练后故意停一下，等他主动示意再继续。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着玩几个回合'),
  `harder` = COALESCE(`harder`, '他主动发起或维持很多回合。'),
  `tip` = COALESCE(`tip`, '「停下来等一等」是引发主动沟通的妙招——他会用眼神、声音或动作要求你继续，那就是最早的「说话」。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组一（共同注意与互动基础）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"滚球来回、传玩具来回。玩熟了之后故意停一下——他用眼神、声音或动作要你继续，那就是最早的「说话」。","principles":["你一次、我一次的来回，是对话结构最早的雏形。","对话的本质就是轮流——我说完你说，你说完我说。","在还不会说话的阶段，用动作来练这个轮流的节奏。","这个节奏建立了，日后的语言轮替会自然很多。","玩熟之后故意停下来，会制造一个「缺口」。","孩子为了让游戏继续，必须主动做出某种表示——这就是沟通的发起。","这个技巧叫做中断惯例，是引发主动沟通最有效的方法之一。","他的任何表示（看你、发声、伸手、拍你）都要立刻被回应。"],"prep":{"场地":"地板上，两人面对面坐着，距离一米。","器材":"球或简单的玩具；也可以完全不用道具（躲猫猫、拍手歌）。","安全检查":"球不要太硬太小。周围清空。","大人位置":"大人坐在孩子正对面，双腿张开形成球道。"},"shots":[{"name":"面对面坐","say":"我们来滚球。"},{"name":"来回滚球","say":"给你——给我——"},{"name":"建立节奏","say":"你一次、我一次。"},{"name":"故意停下来","say":"（拿着球不动，期待地看着孩子）"},{"name":"孩子主动示意","say":""},{"name":"立刻回应","say":"好！球来啰！"}],"reactions":[{"if":"孩子拿到球就不还","then":"准备两个球轮流玩，或用「球要回家」的说法。也可以先玩大人滚、他接就好。"},{"if":"停下来时孩子没有反应","then":"再等久一点（五到十秒）。等待的时间要够长，孩子才有机会发起。"},{"if":"孩子失去兴趣走开","then":"换个更有吸引力的玩具，或改成身体游戏（举高高、躲猫猫）。"}],"mistakes":["停下来后马上又继续——等待的时间不够，孩子来不及发起。要等五到十秒。","孩子表示了却没马上回应——一有表示就要立刻回应，他才知道「这样有用」。","只有大人在主导——来回的节奏要真的轮流，不是大人一直做。"],"down":"先玩大人主导的来回；用更有吸引力的玩具；不用停顿。","up":"停顿时间拉长；改成需要更明确表示才继续；或加入简单的词（「还要」）。","progress":["能来回几次。","停下来时会不会主动表示。","用什么方式表示（眼神／声音／动作）。"],"outro":"「停下来等一等」是引发主动沟通的妙招。他用眼神、声音或动作要你继续——那就是最早的说话。"}' AS JSON))
WHERE `id` = 'A124';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '会响的玩具或手机'),
  `trains` = COALESCE(`trains`, '循着声音找出声源，练听觉的定位与专注。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把会响的东西藏起来（不要太隐密）。"},{"imageUrl":null,"instruction":"让孩子循着声音找。"},{"imageUrl":null,"instruction":"找到就欢呼。"},{"imageUrl":null,"instruction":"藏得慢慢难一点。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '藏在明显的地方、声音大'),
  `harder` = COALESCE(`harder`, '藏得隐密一点、声音小。'),
  `tip` = COALESCE(`tip`, '用手机放音乐藏起来最方便。这个游戏同时练了听觉专注和搜寻能力。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组一（共同注意与互动基础）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"用手机放音乐藏起来最方便。循着声音找出来，同时练了听觉定位和搜寻能力。","principles":["循着声音找到来源，需要判断声音从哪个方向来。","这叫听觉定位，靠的是两只耳朵接收到声音的微小时间差。","听觉定位好的孩子，在吵杂的环境中比较容易找到说话的人。","这和上课时能不能注意到老师在哪里说话有关。","找的过程中还要移动、搜寻、判断，是完整的问题解决。","藏得越隐密，需要越仔细地聆听和判断。","两边都要藏，让左右耳都有练习的机会。","手机放音乐是最方便的道具，随时都能玩。"],"prep":{"场地":"客厅或房间，藏的地方不要太隐密。","器材":"会响的玩具或手机；手机放循环播放的音乐最方便。","安全检查":"藏的地方不要有危险（高处、缝隙）。移动时地面要清空。","大人位置":"大人负责藏，然后在旁边陪着找。"},"shots":[{"name":"准备音源","say":"手机放音乐，我们把它藏起来。"},{"name":"藏起来","say":"（当着孩子的面藏，或请他闭眼）"},{"name":"开始找","say":"听听看，声音从哪里来？"},{"name":"循声移动","say":"越来越大声了！"},{"name":"找到了","say":"找到了！"},{"name":"换他藏","say":"换你藏，我来找。"}],"reactions":[{"if":"孩子找不到","then":"藏在比较明显的地方，或把音量调大。也可以给「热一点、冷一点」的提示。"},{"if":"孩子只在同一区找","then":"藏在不同的方向，前后左右都要有。"},{"if":"孩子随便乱找不听声音","then":"先请他站着不动听三秒，再开始找。"}],"mistakes":["藏得太隐密——找不到会挫折，一开始要很明显。","背景太吵——电视、音响要关掉，不然听不出方向。","只藏同一个方向——四个方向都要藏，左右耳才平均练到。"],"down":"藏在明显的地方；音量调大；当着孩子的面藏。","up":"藏得隐密；音量调小；藏在不同高度；或藏两样让他依序找。","progress":["能不能判断声音的方向。","找到需要多久。","能处理多小的音量。"],"outro":"手机放音乐藏起来，就是最方便的听觉游戏。记得四个方向都要藏，左右耳才平均练到。"}' AS JSON))
WHERE `id` = 'A125';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '生活中的声音（或手机放音效）'),
  `trains` = COALESCE(`trains`, '分辨不同的声音，练听觉辨别。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"听到声音时问「这是什么声音？」（门铃、洗衣机、狗叫、车子）。"},{"imageUrl":null,"instruction":"一起猜、一起找出来源。"},{"imageUrl":null,"instruction":"也可以闭上眼睛听三种声音，说出是什么。"},{"imageUrl":null,"instruction":"室内室外都能玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '差别很大的声音'),
  `harder` = COALESCE(`harder`, '相近的声音，或一次听三种。'),
  `tip` = COALESCE(`tip`, '生活里到处是声音——听得出声音差别的孩子，学说话时也比较容易分辨相近的音。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组一（共同注意与互动基础）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"听到门铃、洗衣机、狗叫，就问「这是什么声音？」。听得出声音差别的孩子，学说话时也比较容易分辨相近的音。","principles":["分辨不同的声音，叫做听觉辨别。","听觉辨别是语音学习的基础——要先听得出差别，才发得出差别。","例如「ㄅ」和「ㄆ」的差别在于送气，听不出来就发不准。","生活中的声音差异比语音大得多，是很好的入门练习。","猜声音还需要把声音和记忆中的经验做比对，这是听觉记忆。","一起去找出声音的来源，还能建立因果概念。","闭上眼睛听，能排除视觉干扰，专注在听觉上。","室内室外的声音都不一样，换个环境就有新的素材。"],"prep":{"场地":"家里或户外，任何有声音的环境。","器材":"不需要任何东西；生活中的声音就是教材。","安全检查":"户外注意交通安全。闭眼时要坐着，避免跌倒。","大人位置":"大人在旁边，听到声音就提问。"},"shots":[{"name":"听到声音","say":"咦，这是什么声音？"},{"name":"一起猜","say":"你觉得是什么？"},{"name":"去找来源","say":"我们去看看。"},{"name":"找到答案","say":"原来是洗衣机！"},{"name":"闭眼听","say":"闭上眼睛，听三种声音。"},{"name":"户外的声音","say":"外面有什么声音？"}],"reactions":[{"if":"孩子猜不出来","then":"给两个选项让他选。或直接带他去看，下次就认得了。"},{"if":"孩子对声音没兴趣","then":"从他有兴趣的声音开始（车子、动物）。或用手机放音效玩猜谜。"},{"if":"孩子对某些声音很害怕","then":"先在远处听，慢慢靠近。也可以让他自己控制声音（自己按门铃）。"}],"mistakes":["只在安排好的时间玩——生活中随时听到声音都可以问，这才自然。","直接告诉答案——先让他猜，猜错也没关系。","强迫怕声音的孩子靠近——要循序渐进，让他有控制权。"],"down":"给两个选项让他选；从最熟悉的声音开始；直接带去看来源。","up":"闭眼听并说出三种；分辨相似的声音；或用声音玩猜谜比赛。","progress":["能认出几种生活中的声音。","能不能分辨相似的声音。","会不会主动说「我听到什么声音」。"],"outro":"生活里到处是声音。听得出声音差别的孩子，学说话时也比较容易分辨相近的音。"}' AS JSON))
WHERE `id` = 'A126';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '听到指定的词就做动作，练听觉专注。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说好「听到『苹果』就拍手」。"},{"imageUrl":null,"instruction":"然后念一串词：香蕉、桌子、苹果（拍手！）、椅子……"},{"imageUrl":null,"instruction":"念错的时候笑一笑再来。"},{"imageUrl":null,"instruction":"换目标词、换动作。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一个目标词、念得慢'),
  `harder` = COALESCE(`harder`, '两个目标词，或藏在句子里。'),
  `tip` = COALESCE(`tip`, '这个游戏练的是「从一堆声音里抓到重点」——上课时听老师讲话，用的就是这个能力。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组一（共同注意与互动基础）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"说好「听到苹果就拍手」，然后念一串词。这个游戏练的是「从一堆声音里抓到重点」——上课听老师讲话用的就是这个能力。","principles":["从一连串的词里抓出指定的那一个，需要持续的听觉专注。","这叫做选择性听觉注意——把注意力锁定在特定的目标上。","上课时老师讲一大段话，孩子要抓出重点，用的就是这个能力。","同时还要抑制住「听到别的词也想反应」的冲动。","所以这个游戏也在练抑制控制。","念词的速度可以调整难度——慢一点简单，快一点困难。","目标词出现的频率也可以调——常出现比较简单。","换孩子出题时，他要自己记住目标词并监控大人的反应，难度更高。"],"prep":{"场地":"任何地方，坐着玩最专注。","器材":"不需要任何东西。","安全检查":"无特殊风险。","大人位置":"大人念词，速度先慢后快。"},"shots":[{"name":"说好规则","say":"听到「苹果」就拍手，其他词不要动。"},{"name":"开始念","say":"香蕉、桌子、椅子⋯⋯"},{"name":"目标出现","say":"苹果！"},{"name":"反应错了","say":"哎呀，那不是苹果！"},{"name":"加快速度","say":"这次念快一点！"},{"name":"换他出题","say":"换你念，我来拍手。"}],"reactions":[{"if":"孩子每个词都拍手","then":"念慢一点，目标词之间隔久一点。也可以先只念五六个词。"},{"if":"孩子漏掉目标词","then":"念慢一点，目标词说清楚一点。或减少词的总数。"},{"if":"孩子觉得太简单","then":"加快速度；换成两个目标词；或换成不同的动作（听到苹果拍手、听到香蕉跺脚）。"}],"mistakes":["念太快——孩子来不及反应就会放弃，先慢后快。","词太多——一次十个词以内，太多会失去专注。","错了就纠正——笑一笑再来就好，这是游戏不是考试。"],"down":"念慢一点；词总数减少；目标词出现频率提高。","up":"加快速度；两个目标词配两个动作；或在有背景音的情况下玩。","progress":["能不能准确抓到目标词。","误判的次数有没有减少。","能处理多快的速度。"],"outro":"「从一堆声音里抓到重点」——上课时听老师讲话，用的就是这个能力。饭桌上两分钟就能玩。"}' AS JSON))
WHERE `id` = 'A127';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '日常物品'),
  `trains` = COALESCE(`trains`, '听懂并完成一个动作的指令。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说简单清楚的一句话：「把球给我」「坐下」「拿鞋子」。"},{"imageUrl":null,"instruction":"说的时候和他有眼神接触。"},{"imageUrl":null,"instruction":"做到了热烈称赞。"},{"imageUrl":null,"instruction":"做不到就示范一次，再让他做。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '指令配合手势'),
  `harder` = COALESCE(`harder`, '不用手势、只靠听的。'),
  `tip` = COALESCE(`tip`, '指令要短、要具体——「把书放桌上」比「把东西收好」好懂。说完给他几秒钟反应，别急着重复。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十（指令理解与执行）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"指令要短、要具体——「把书放桌上」比「把东西收好」好懂。说完给他几秒钟反应，别急着重复。","principles":["听懂并执行一个指令，需要理解词汇、记住内容、再转成动作。","这三个步骤对刚学语言的孩子来说已经很不容易。","指令越短越具体，孩子要处理的讯息就越少，成功率越高。","「把东西收好」这种指令太抽象——什么东西？收到哪里？","「把书放桌上」就很具体——目标物、动作、位置都清楚。","说完之后要给几秒钟的处理时间，孩子的反应速度比大人慢。","一直重复会让孩子来不及处理，反而更听不懂。","搭配眼神接触，能确保孩子真的在听。"],"prep":{"场地":"日常生活中随时进行。","器材":"日常物品；不需要特别准备。","安全检查":"指令内容要安全，不涉及危险动作。","大人位置":"大人蹲下到孩子的高度，确认有眼神接触再说。"},"shots":[{"name":"先有眼神接触","say":"（蹲下来，看着孩子）"},{"name":"说出指令","say":"把球给我。"},{"name":"等几秒","say":"（安静等待，不重复）"},{"name":"孩子执行","say":""},{"name":"热烈称赞","say":"谢谢！你听懂了！"},{"name":"抽象 vs 具体","say":"「把书放桌上」比「把东西收好」好懂。"}],"reactions":[{"if":"孩子没有反应","then":"先确认他有在听（有眼神接触吗）。再示范一次动作，然后让他做。"},{"if":"孩子做错了","then":"不用说「错了」。直接示范正确的，再让他试一次。"},{"if":"孩子只做一半","then":"指令可能太长。拆成更短的（先说「拿球」，做到了再说「给我」）。"}],"mistakes":["指令太抽象——「收好」「乖一点」孩子听不懂，要具体。","说完马上重复——给他几秒钟处理，一直说反而更听不懂。","在远处喊——走到他面前、蹲下来、有眼神接触再说。"],"down":"指令更短（两个字）；搭配手势；示范一次再让他做。","up":"指令不搭配手势；在他没看着你时说；或加上形容词（「把红色的球给我」）。","progress":["能听懂几种指令。","需不需要搭配手势。","需要重复几次才做。"],"outro":"指令要短、要具体，说完给他几秒钟反应。「把书放桌上」比「把东西收好」好懂太多了。"}' AS JSON))
WHERE `id` = 'A128';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '日常物品'),
  `trains` = COALESCE(`trains`, '记住并完成两个连续的动作。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说「先……再……」：「先拿杯子，再放到桌上」。"},{"imageUrl":null,"instruction":"只说一遍，让他复述一次。"},{"imageUrl":null,"instruction":"做完两步就称赞。"},{"imageUrl":null,"instruction":"熟练后试试三步。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两步、动作在眼前'),
  `harder` = COALESCE(`harder`, '三步，或要走到别的房间完成。'),
  `tip` = COALESCE(`tip`, '让孩子「复述一遍再做」——说出来的过程会帮他记住，这个方法在学校也很好用。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十（指令理解与执行）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「先拿杯子，再放到桌上」——只说一遍，让他复述一次。说出来的过程会帮他记住，这个方法在学校也很好用。","principles":["两步指令需要同时记住两件事并按顺序执行。","这考验的是工作记忆——在脑中暂存讯息并加以运用。","工作记忆容量和日后的学习表现有密切关系。","让孩子复述一遍，是很有效的记忆策略。","复述的过程中，讯息会被重新编码，记忆的强度会提高。","这个策略孩子学会了，在学校听老师交代事情时也用得上。","用「先……再……」的句型，能帮助孩子建立顺序概念。","两步熟了再加到三步，容量是慢慢撑开的。"],"prep":{"场地":"日常生活中，或安排一个简单的任务。","器材":"日常物品。","安全检查":"任务内容要安全。","大人位置":"大人说清楚指令，然后请孩子复述。"},"shots":[{"name":"说两步指令","say":"先拿杯子，再放到桌上。"},{"name":"请他复述","say":"你要做什么？"},{"name":"第一步","say":""},{"name":"第二步","say":""},{"name":"完成称赞","say":"两件事都做到了！"},{"name":"试试三步","say":"熟练了可以试试三步。"}],"reactions":[{"if":"孩子只做第一步","then":"退回一步指令，或让他复述后再做。复述通常立刻改善。"},{"if":"孩子顺序颠倒","then":"强调「先…再…」的顺序词。也可以用手势比出一、二。"},{"if":"孩子复述不出来","then":"和他一起说一遍。说过的话记得比听过的牢。"}],"mistakes":["不请他复述——这是最有效的策略，别省略。","一次说三四件事——先把两步做稳，再往上加。","孩子做一半就提醒下一步——先等他自己想起来。"],"down":"退回一步指令；两步之间有明显的关联；搭配手势。","up":"加到三步；两步之间没有关联；或延迟一段时间再让他做。","progress":["能完成几步的指令。","会不会自己复述。","顺序对不对。"],"outro":"让孩子「复述一遍再做」——说出来的过程会帮他记住。这个方法在学校听老师交代事情时也很好用。"}' AS JSON))
WHERE `id` = 'A129';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个小玩具'),
  `trains` = COALESCE(`trains`, '听方位指令找东西，练理解位置词。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把玩具藏起来。"},{"imageUrl":null,"instruction":"用方位词给提示：「在桌子下面」「在盒子的右边」。"},{"imageUrl":null,"instruction":"让孩子照着找。"},{"imageUrl":null,"instruction":"找到了换他来藏、他来说。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一个提示、近距离'),
  `harder` = COALESCE(`harder`, '两三个提示连着说。'),
  `tip` = COALESCE(`tip`, '上面、下面、里面、旁边、前面、后面——这些位置词是数学和阅读的基础，用寻宝游戏练最自然。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十（指令理解与执行）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"上面、下面、里面、旁边、前面、后面——这些位置词是数学和阅读的基础，用寻宝游戏练最自然。","principles":["位置词是空间概念的语言表现。","空间概念是数学的基础——图形、方位、几何都需要它。","也是阅读的基础——字的部件在上面还是下面，会影响辨认。","听懂位置词需要把语言转换成空间的心理图像。","这个转换能力，和日后看懂图表、地图都有关。","寻宝游戏有明确的目标和回馈，孩子的动机很强。","位置词要一个一个教，一次教太多会混淆。","换孩子来藏、他来说位置词，是更高阶的表达练习。"],"prep":{"场地":"客厅或房间，藏的地方要符合位置词的描述。","器材":"一个小玩具。","安全检查":"不要藏在危险的地方（高处、缝隙、电器旁）。","大人位置":"大人负责藏并给位置提示。"},"shots":[{"name":"藏起来","say":"我把小熊藏起来啰。"},{"name":"给位置提示","say":"它在桌子下面。"},{"name":"孩子理解","say":""},{"name":"找到了","say":"找到了！"},{"name":"换个位置词","say":"这次在盒子的旁边。"},{"name":"换他来说","say":"换你藏，你来说在哪里。"}],"reactions":[{"if":"孩子听不懂位置词","then":"先示范：把玩具放在桌子下面，同时说「在下面」。看到和听到一起，比较好理解。"},{"if":"孩子随便乱找","then":"请他先重复一次位置词再找。也可以缩小搜寻范围。"},{"if":"孩子说不出位置词","then":"给他选项：「在上面还是下面？」二选一比开放式容易。"}],"mistakes":["一次用太多位置词——一次一个，熟了再加。","位置词用得不精确——「那边」「那里」不算，要用具体的位置词。","藏在不符合描述的地方——说「下面」就真的要在下面，不然孩子会混淆。"],"down":"一次只用一个位置词；藏的范围缩小；示范位置词的意思。","up":"用两个位置词组合（「在桌子下面的盒子里」）；换孩子说；或加入左右。","progress":["能听懂几个位置词。","能说出几个位置词。","能不能理解组合的位置描述。"],"outro":"上面、下面、里面、旁边——这些位置词是数学和阅读的基础，用寻宝游戏练最自然。"}' AS JSON))
WHERE `id` = 'A130';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '听到名称能指出对应的身体部位。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"问「鼻子在哪里？」让孩子指。"},{"imageUrl":null,"instruction":"从最明显的开始：眼睛、鼻子、嘴巴、手、脚。"},{"imageUrl":null,"instruction":"再加：耳朵、头发、肚子、膝盖。"},{"imageUrl":null,"instruction":"洗澡穿衣时顺便玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '指五个大部位'),
  `harder` = COALESCE(`harder`, '十个以上，包含手肘、脚踝等。'),
  `tip` = COALESCE(`tip`, '洗澡的时候边洗边说部位名称——一天洗一次，一个月就练了三十次。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组四（名词与生活词汇）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"洗澡的时候边洗边说部位名称——一天洗一次，一个月就练了三十次。这是最不费力的练习方式。","principles":["身体部位是最早学会的一批名词，因为孩子随时都能接触到。","指认身体部位代表孩子把「听到的词」和「身体的位置」连结起来了。","这也是身体形象发展的一部分——知道自己身体有哪些部分。","身体形象清楚的孩子，动作比较精准，也比较不会撞到东西。","从最明显的开始（眼睛、鼻子、嘴巴），再到比较难的（手肘、膝盖、脚踝）。","洗澡和穿衣时是最自然的练习时机，不用另外找时间。","边洗边说，把语言和身体的感觉一起输入，记得更牢。","会指认之后再练说出名称，理解永远走在表达前面。"],"prep":{"场地":"洗澡时、穿衣时，或任何时候。","器材":"不需要任何东西。","安全检查":"洗澡时注意防滑和水温。","大人位置":"大人在旁边，边洗边说部位名称。"},"shots":[{"name":"从明显的开始","say":"鼻子在哪里？"},{"name":"洗澡时说","say":"我们洗手臂、洗肚子。"},{"name":"加难的部位","say":"膝盖在哪里？手肘呢？"},{"name":"穿衣时说","say":"手伸进来、头钻出来。"},{"name":"换他问","say":"换你问妈妈。"},{"name":"唱儿歌","say":"头儿肩膀膝脚趾！"}],"reactions":[{"if":"孩子指错","then":"不用说错。直接指正确的位置说「这是鼻子」，再问一次。"},{"if":"孩子只会指自己的不会指别人的","then":"先在娃娃或大人身上练，再回到自己身上。"},{"if":"孩子不想玩","then":"融进洗澡穿衣的流程里，不用特别安排时间。"}],"mistakes":["一次教太多部位——先把五个学会，再加新的。","另外安排时间练——洗澡穿衣时顺便说，最自然也最不费力。","急着要他说出名称——先会指认，说是后面的事。"],"down":"只练三到五个明显的部位；在娃娃身上先练；搭配儿歌。","up":"加入较难的部位（手肘、脚踝、下巴）；在别人身上指认；或说出部位的功能。","progress":["能指认几个部位。","能说出几个部位的名称。","能不能在别人身上指认。"],"outro":"洗澡的时候边洗边说部位名称——一天一次，一个月就是三十次。最不费力的练习就是融进生活里。"}' AS JSON))
WHERE `id` = 'A131';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '图卡或绘本'),
  `trains` = COALESCE(`trains`, '听到词能指出对的图，是理解词汇的表现。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"摊开三四张图卡。"},{"imageUrl":null,"instruction":"说「小狗在哪里？」让他指。"},{"imageUrl":null,"instruction":"指对了就说出名称肯定他。"},{"imageUrl":null,"instruction":"从熟悉的东西开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三张卡、差异大'),
  `harder` = COALESCE(`harder`, '六张以上、或相近的东西（杯子和碗）。'),
  `tip` = COALESCE(`tip`, '「能指出来」代表他懂了，就算还不会说也一样。理解永远走在表达前面——先让他听懂很多，说才会跟上来。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组四（名词与生活词汇）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「能指出来」代表他懂了，就算还不会说也一样。理解永远走在表达前面——先让他听懂很多，说才会跟上来。","principles":["指认图卡是检验「理解词汇」最直接的方式。","孩子能指出来，就代表他把这个词和这个图连结起来了。","理解词汇的数量，永远远多于能说出来的数量。","这个现象叫做理解先于表达，是语言发展的正常规律。","所以不会说话的孩子，不代表他听不懂。","家长要做的是持续输入词汇，而不是急着要他说。","输入的量够多了，表达自然会冒出来。","从三四张开始，选他熟悉的东西，成功率最高。"],"prep":{"场地":"餐桌或地板，图卡摊开。","器材":"图卡或绘本；写实的照片比卡通好懂。","安全检查":"小图卡注意误吞。","大人位置":"大人坐在旁边，一次说一个词。"},"shots":[{"name":"摊开图卡","say":"我们来看看这些图。"},{"name":"说出一个词","say":"小狗在哪里？"},{"name":"孩子指认","say":""},{"name":"肯定","say":"对，这是小狗！"},{"name":"增加张数","say":"这次有六张。"},{"name":"理解先于表达","say":"能指出来，就代表他懂了。"}],"reactions":[{"if":"孩子指错","then":"不用说错。直接指正确的说「这是小狗」，再重新问一次。"},{"if":"孩子随便乱指","then":"减少张数到两张，差异明显一点。先让他成功。"},{"if":"孩子会指但不会说","then":"完全正常。理解先于表达，继续输入就好，别逼他说。"}],"mistakes":["图卡太多——先三四张，太多会眼花。","急着要他说出名称——先会指认就很好了。","用太抽象的图——写实的照片比卡通图好懂。"],"down":"张数减到两张；差异明显；用写实的照片。","up":"张数增加到六到八张；图案相近；或加上形容词（「红色的球在哪里」）。","progress":["能从几张中正确指认。","能听懂几个词。","开始会说出哪些词。"],"outro":"「能指出来」就代表他懂了，就算还不会说也一样。先让他听懂很多，说才会自然跟上来。"}' AS JSON))
WHERE `id` = 'A132';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本'),
  `trains` = COALESCE(`trains`, '听故事时能找出对应的画面，练听觉理解。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"共读时说「找找看小熊在哪里」。"},{"imageUrl":null,"instruction":"让孩子在图上指出来。"},{"imageUrl":null,"instruction":"问「谁在吃东西？」"},{"imageUrl":null,"instruction":"从一句话一个目标开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '找一个明显的角色'),
  `harder` = COALESCE(`harder`, '找出正在做某个动作的角色。'),
  `tip` = COALESCE(`tip`, '共读时多问几个「在哪里」，孩子会听得更专心——比一路念到底效果好很多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十（指令理解与执行）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"共读时多问几个「在哪里」，孩子会听得更专心——比一路念到底效果好很多。","principles":["在故事中找出对应的画面，需要听懂内容并在图上定位。","这把听觉理解和视觉搜寻结合起来，是很完整的理解练习。","共读时如果只是一路念，孩子容易变成被动听。","提问会让他从被动听变成主动找，专注度完全不同。","「谁在做什么」的问题，练的是理解句子的结构。","找到答案的成就感，会让孩子更喜欢共读。","一开始一句话问一个目标，不要一次问太多。","共读是语言输入最密集的时段，值得好好利用。"],"prep":{"场地":"沙发或床上，孩子坐在大人旁边或腿上。","器材":"绘本；图案清楚、内容简单的最好。","安全检查":"无特殊风险。","大人位置":"大人拿着书，念到一段就提问。"},"shots":[{"name":"开始共读","say":"我们来看这本书。"},{"name":"念一句","say":"小熊在吃蜂蜜。"},{"name":"提问","say":"找找看小熊在哪里？"},{"name":"孩子指出","say":""},{"name":"进阶提问","say":"谁在吃东西？"},{"name":"继续共读","say":"我们看下一页。"}],"reactions":[{"if":"孩子找不到","then":"缩小范围（「在这一半里面」），或把图放近一点。"},{"if":"孩子不想被打断","then":"先念完一页再问。或只在他有兴趣的页面提问。"},{"if":"孩子只想翻页","then":"让他翻。共读的形式可以很自由，翻页本身也是练习。"}],"mistakes":["一页问太多问题——一页一两个就好，太多会变成考试。","一路念到底不提问——孩子会变成被动听，专注度会下降。","孩子答不出就急着说答案——先给提示，让他自己找到。"],"down":"一页只问一个；范围缩小；图案简单的书。","up":"问「谁在做什么」的句子理解；问「为什么」；或问书上没直接画出来的（推论）。","progress":["能不能在图上找到指定的角色或物品。","能不能回答「谁在做什么」。","共读时的专注时间有多长。"],"outro":"共读时多问几个「在哪里」，孩子会听得更专心——比一路念到底效果好很多。"}' AS JSON))
WHERE `id` = 'A133';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '两样东西'),
  `trains` = COALESCE(`trains`, '从两个选项中选，练理解和表达意愿。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿出两样东西问「要苹果还是香蕉？」"},{"imageUrl":null,"instruction":"让他指或说出来。"},{"imageUrl":null,"instruction":"给他真的选到的那个。"},{"imageUrl":null,"instruction":"一天中制造很多选择的机会。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '指出来就好'),
  `harder` = COALESCE(`harder`, '说出名称，或说完整句「我要××」。'),
  `tip` = COALESCE(`tip`, '多给孩子选择的机会——穿哪件衣服、吃哪个水果、玩哪个玩具。会表达意愿的孩子，哭闹会少很多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「要苹果还是香蕉？」多给孩子选择的机会——会表达意愿的孩子，哭闹会少很多。","principles":["从两个选项中选择，需要听懂两个词并做出比较和决定。","这是理解和决策的结合，也是最早的自主表达。","孩子指出或说出他要的，就是一次成功的沟通。","成功的沟通经验累积多了，他会更愿意用语言表达。","反过来说，从来没有选择权的孩子，只能用哭闹来表达不满。","所以给选择其实是在减少行为问题。","选项要真的都可以接受，不要给假选择。","一天中制造很多小选择的机会：穿哪件、吃哪个、玩哪个。"],"prep":{"场地":"日常生活中随时进行。","器材":"两样东西；两样都是可以接受的选项。","安全检查":"两个选项都要是安全、可以接受的。","大人位置":"大人拿着两样东西，让孩子看清楚。"},"shots":[{"name":"拿出两样","say":"要苹果还是香蕉？"},{"name":"等他选","say":"（安静等待）"},{"name":"孩子选择","say":""},{"name":"给他选的","say":"好，给你苹果。"},{"name":"生活中的选择","say":"穿哪一件？"},{"name":"更多机会","say":"玩哪一个？去哪里？"}],"reactions":[{"if":"孩子两个都要","then":"可以说「先玩这个，等一下换那个」。或坚持「只能选一个」，两种做法都可以。"},{"if":"孩子不选","then":"把两样拿近一点，或换成差异更大的选项。也可以示范「妈妈选这个」。"},{"if":"孩子选了又反悔","then":"小小孩很常见。可以让他换，或说「这次先这个，下次换」。"}],"mistakes":["给假选择——两个选项都要是真的可以接受的，不然就不是选择。","孩子选了却不给——这会摧毁他对选择的信任。","选项太多——两个就好，三个以上对小小孩太难。"],"down":"两个选项差异明显；东西拿近一点；示范如何选。","up":"三个选项；选项差异小；或用语言而非实物（「要去公园还是超市？」）。","progress":["会不会做出选择。","用什么方式表达（指／看／说）。","能从几个选项中选。"],"outro":"多给孩子选择的机会——穿哪件衣服、吃哪个水果、玩哪个玩具。会表达意愿的孩子，哭闹会少很多。"}' AS JSON))
WHERE `id` = 'A134';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子想要的东西'),
  `trains` = COALESCE(`trains`, '制造机会让他主动表达需求。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把他想要的东西放在看得到、拿不到的地方。"},{"imageUrl":null,"instruction":"等他用眼神、手指、声音或说话来要求。"},{"imageUrl":null,"instruction":"有任何表示就立刻给他。"},{"imageUrl":null,"instruction":"别急着帮他拿。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '他伸手就给'),
  `harder` = COALESCE(`harder`, '等他发出声音或说出词。'),
  `tip` = COALESCE(`tip`, '什么都先帮他准备好的孩子，反而没机会学表达。制造一点「需要开口」的机会——但他一表达就要马上回应。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组一（共同注意与互动基础）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"什么都先帮他准备好的孩子，反而没机会学表达。制造一点「需要开口」的机会——但他一表达就要马上回应。","principles":["孩子不需要表达就能得到一切时，就没有沟通的动机。","制造一个小小的「需要」，才会激发他主动表达。","把想要的东西放在看得到、拿不到的地方，是最经典的方法。","这个技巧在专业上叫做诱发沟通的环境安排。","重点是「看得到」——他要知道那里有东西，才会想要。","任何形式的表达都要立刻回应：眼神、手指、发声、说话都算。","立刻回应是关键，让他学到「表达有用」。","如果表达了却要等很久，这个动机就会消退。"],"prep":{"场地":"孩子的游戏区或餐桌。","器材":"孩子想要的东西；透明的盒子或高一点的架子。","安全检查":"不要放在会掉下来砸到人的地方。不要让孩子爬高去拿。","大人位置":"大人在旁边等待，一有表示就回应。"},"shots":[{"name":"放在看得到拿不到的地方","say":"（把玩具放在架子上）"},{"name":"孩子注意到","say":""},{"name":"大人等待","say":"（不主动帮忙，安静等待）"},{"name":"孩子表达","say":""},{"name":"立刻给","say":"好！你要这个对不对！"},{"name":"说出他的意思","say":"你说「要」。"}],"reactions":[{"if":"孩子直接哭闹","then":"哭也是表达，先回应。给的时候说「你要这个」，帮他把哭转成词。"},{"if":"孩子放弃走开","then":"等待时间太长或东西不够吸引。换更想要的东西，或早一点回应。"},{"if":"孩子自己想办法爬上去拿","then":"这是很好的问题解决，但要注意安全。放在他爬不到的地方。"}],"mistakes":["什么都先准备好——孩子就没有机会学表达了。","等太久才回应——他一表示就要马上给，不然动机会消退。","放在他完全看不到的地方——要看得到才会想要。"],"down":"东西放近一点；等待时间缩短；大人先示范怎么要求。","up":"等待更明确的表达（要有声音、要说出词）；或加上「说要才给」。","progress":["会不会主动表达需求。","用什么方式表达（哭／眼神／手指／发声／说话）。","表达的方式有没有越来越明确。"],"outro":"制造一点「需要开口」的机会——但他一表达就要马上回应。让他学到「说了有用」，这是沟通最重要的一课。"}' AS JSON))
WHERE `id` = 'A135';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '角色互换，孩子当发号施令的人。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子来下指令，大人做。"},{"imageUrl":null,"instruction":"「妈妈跳三下」「爸爸摸头」。"},{"imageUrl":null,"instruction":"大人夸张地照做。"},{"imageUrl":null,"instruction":"做错了让他纠正你。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一个动作的指令'),
  `harder` = COALESCE(`harder`, '两三步的指令。'),
  `tip` = COALESCE(`tip`, '当「发号施令」的人对孩子超有吸引力——为了指挥大人，他会努力把话说清楚。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"让孩子来下指令、大人照做。当「发号施令」的人对孩子超有吸引力——为了指挥大人，他会努力把话说清楚。","principles":["要指挥别人，孩子必须把想法转成清楚的语言。","如果说不清楚，大人就做不出来，这是很直接的回馈。","这个回馈会推动他把话说得更完整、更精确。","角色互换让孩子从被动接受指令变成主动发出指令。","主导权对孩子有很强的吸引力，动机完全不用担心。","大人夸张地照做，会让孩子觉得自己的话很有力量。","故意做错让他纠正，能练到他的表达修正能力。","这个游戏同时练了表达、词汇和自信。"],"prep":{"场地":"客厅空地，有空间做动作。","器材":"不需要任何东西。","安全检查":"孩子下的指令要安全，大人可以过滤（「这个太危险，换一个」）。","大人位置":"大人认真照做，而且要夸张一点。"},"shots":[{"name":"说明玩法","say":"现在换你当老师，你说我做。"},{"name":"孩子下指令","say":"（孩子说）妈妈跳三下！"},{"name":"大人照做","say":"（夸张地跳三下）"},{"name":"故意做错","say":"（跳了五下）"},{"name":"孩子纠正","say":"（孩子）不对！是三下！"},{"name":"全家一起","say":"爸爸也要听你的！"}],"reactions":[{"if":"孩子说不出指令","then":"先给示范：「你可以说『妈妈拍手』」。也可以给选项让他选。"},{"if":"孩子的指令不清楚","then":"故意做错或做出困惑的表情，让他补充说明。"},{"if":"孩子下危险的指令","then":"说「这个太危险，换一个好吗」。可以事先说好有哪些不行。"}],"mistakes":["大人敷衍照做——要夸张、要认真，孩子才觉得自己的话有力量。","纠正孩子的说法——先照做，说不清楚时用「做错」来引导他补充。","不给他主导权——这个游戏的价值就在角色互换。"],"down":"大人先示范可以说什么；给选项让他选；只做简单的动作指令。","up":"要求两步指令；加上位置词（「站到椅子后面」）；或指挥多个人。","progress":["能不能说出清楚的指令。","指令的复杂度（一步／两步／带位置词）。","会不会纠正大人的错误。"],"outro":"当「发号施令」的人对孩子超有吸引力。为了指挥大人，他会努力把话说清楚——这就是最好的表达练习。"}' AS JSON))
WHERE `id` = 'A136';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '听不懂的时候会问「什么意思」，是重要的沟通能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"故意说一个他听不懂的词或说得很快。"},{"imageUrl":null,"instruction":"教他问「什么意思？」「再说一次好吗？」"},{"imageUrl":null,"instruction":"他一问就放慢、换简单的话说。"},{"imageUrl":null,"instruction":"日常他一脸茫然时提醒「可以问呀」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '提示下会问'),
  `harder` = COALESCE(`harder`, '没听懂就主动问。'),
  `tip` = COALESCE(`tip`, '会问「你说什么」的孩子，误会少一半。孩子问了绝对不能嫌烦——嫌一次，他下次就不敢问了。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"会问「你说什么」的孩子，误会少一半。孩子问了绝对不能嫌烦——嫌一次，他下次就不敢问了。","principles":["听不懂的时候会主动发问，是很重要的沟通能力。","这叫做沟通修补——发现沟通出问题时主动修正。","不敢问的孩子会用猜的，猜错就造成误会和挫折。","在学校，不敢问的孩子会漏掉很多讯息。","要会问，孩子必须先意识到「我没听懂」，这是后设认知。","然后还要有勇气开口，这需要安全的环境。","大人的反应决定了他敢不敢问——嫌烦一次，他就不问了。","孩子一问，大人要立刻放慢、换简单的话说，让发问有好结果。"],"prep":{"场地":"日常对话中随时进行。","器材":"不需要任何东西。","安全检查":"无特殊风险。","大人位置":"大人故意说得快一点或用难一点的词，然后教他发问。"},"shots":[{"name":"故意说不清楚","say":"（用很快的速度或难懂的词说一句话）"},{"name":"孩子困惑","say":""},{"name":"教他问","say":"可以说「什么意思？」"},{"name":"孩子发问","say":"（孩子）什么意思？"},{"name":"立刻放慢","say":"我是说——（放慢、换简单的话）"},{"name":"肯定他问","say":"你问得很好！"}],"reactions":[{"if":"孩子不敢问只是发呆","then":"主动问「你听懂了吗？听不懂可以问我」。要让他知道问是被欢迎的。"},{"if":"孩子用猜的","then":"不用说他猜错。直接说「我再说一次」，并示范「你可以问我什么意思」。"},{"if":"孩子一直问同一件事","then":"不要嫌烦。换个方式说，或用画的、用比的。"}],"mistakes":["孩子问了嫌烦——这是最伤的，嫌一次他下次就不敢问了。","说「这个刚才说过了」——这等于告诉他「不该问」。","孩子不问就以为他懂了——主动确认「你听懂了吗」。"],"down":"大人主动问「听懂了吗」；教一句固定的发问用语；用手势提示可以问。","up":"教更多发问方式（「再说一次好吗」「你的意思是⋯⋯吗」）；或在团体中练习发问。","progress":["会不会主动说听不懂。","用什么方式发问。","在别人面前敢不敢问。"],"outro":"会问「你说什么」的孩子，误会少一半。孩子问了绝对不能嫌烦——嫌一次，他下次就不敢问了。"}' AS JSON))
WHERE `id` = 'A137';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '儿歌'),
  `trains` = COALESCE(`trains`, '跟着歌词做动作，把听和动作连起来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选有动作的儿歌（头儿肩膀膝脚趾、小星星）。"},{"imageUrl":null,"instruction":"一起唱、一起做动作。"},{"imageUrl":null,"instruction":"唱熟了故意停一句，看他会不会接。"},{"imageUrl":null,"instruction":"每天唱固定几首。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着大人做'),
  `harder` = COALESCE(`harder`, '自己听着歌词做对动作。'),
  `tip` = COALESCE(`tip`, '重复的儿歌是语言的好朋友——听得多、唱得熟，词汇和句子就悄悄进去了。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组三（声音与仿说）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"重复的儿歌是语言的好朋友——听得多、唱得熟，词汇和句子就悄悄进去了。唱熟了故意停一句，看他会不会接。","principles":["儿歌的旋律和节奏，让语言变得更容易记忆。","重复的歌词提供了大量的语言输入，而且孩子不会觉得无聊。","配合动作时，语言和身体的经验连结在一起，记得更牢。","这叫做多感官学习——听觉、动作、视觉一起进来。","唱熟之后故意停一句，孩子会自然接下去。","这个「填空」的反应，代表他已经把歌词记住了。","这也是引发主动表达的好方法——他为了接下去而开口。","固定唱几首，重复的次数够多，效果才会出来。"],"prep":{"场地":"客厅或任何地方，有空间做动作最好。","器材":"儿歌；选有动作的（头儿肩膀膝脚趾、小星星、两只老虎）。","安全检查":"做动作时注意周围空间。","大人位置":"大人一起唱一起做，动作要大要清楚。"},"shots":[{"name":"选有动作的歌","say":"我们来唱头儿肩膀膝脚趾。"},{"name":"边唱边做","say":"头儿、肩膀、膝、脚趾！"},{"name":"孩子跟着做","say":""},{"name":"故意停一句","say":"头儿肩膀膝——（停住，期待地看着孩子）"},{"name":"孩子接下去","say":"（孩子）脚趾！"},{"name":"每天唱","say":"每天唱固定几首。"}],"reactions":[{"if":"孩子不跟着唱","then":"先只做动作不要求唱。听得够多了，自然会开始跟着哼。"},{"if":"孩子接不上停住的那一句","then":"再唱几天。熟悉度不够就接不上，多唱几次就好。"},{"if":"孩子只想听不想动","then":"大人自己做动作就好。看久了他会自己加入。"}],"mistakes":["一直换新歌——重复才是关键，固定唱几首效果最好。","要求孩子一定要唱——先让他听、让他做动作，唱是后面的事。","大人不参与——一起唱一起做，孩子才投入。"],"down":"只做动作不要求唱；选最简单的歌；大人带着他的手做动作。","up":"故意停在不同的地方；换他带唱；或加入新的动作。","progress":["会不会跟着做动作。","会不会跟着唱。","停住时能不能接上。"],"outro":"重复的儿歌是语言的好朋友。唱熟了故意停一句，看他会不会接——那代表歌词已经进去了。"}' AS JSON))
WHERE `id` = 'A138';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '记住并复述听到的一串东西，练听觉记忆。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说三样东西：「苹果、汽车、小狗」。"},{"imageUrl":null,"instruction":"让孩子复述一遍。"},{"imageUrl":null,"instruction":"做对了增加到四样、五样。"},{"imageUrl":null,"instruction":"也可以变成「去拿三样东西」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三样'),
  `harder` = COALESCE(`harder`, '五样以上，或倒着说回来。'),
  `tip` = COALESCE(`tip`, '听觉记忆好的孩子，上课听讲、听指令都比较轻松。饭桌上就能玩，一次两分钟。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十（指令理解与执行）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"说三样东西，让孩子复述。听觉记忆好的孩子，上课听讲、听指令都比较轻松。饭桌上两分钟就能玩。","principles":["记住并复述一串东西，练的是听觉记忆的广度。","听觉记忆广度和上课听讲、记住老师交代的事情直接相关。","发展参考：三岁能记两三样，五岁能记三四样，七岁能记四五样。","孩子会自然发展出记忆策略：默念、编故事、分组。","追问「你怎么记住的」，能让他意识到自己的策略。","意识到策略的孩子，会把这个方法用到别的地方。","换成「去拿三样东西」，就变成实际的任务执行。","这个游戏不需要任何道具，饭桌上、车上都能玩。"],"prep":{"场地":"任何地方，饭桌上或车上都可以。","器材":"不需要任何东西。","安全检查":"无特殊风险。","大人位置":"大人说出一串词，速度适中、清楚。"},"shots":[{"name":"说三样","say":"苹果、汽车、小狗。"},{"name":"孩子复述","say":"（孩子）苹果、汽车、小狗。"},{"name":"增加数量","say":"这次四样。"},{"name":"追问策略","say":"你怎么记住的？"},{"name":"变成任务","say":"去拿三样东西：杯子、书、袜子。"},{"name":"饭桌上玩","say":"吃饭的时候就能玩。"}],"reactions":[{"if":"孩子只记得最后一样","then":"减到两样。也可以教他「一边听一边在心里念一次」。"},{"if":"孩子顺序颠倒","then":"先不要求顺序，记得就好。顺序是更高阶的要求。"},{"if":"孩子说不出记忆方法","then":"给选项：「你是在心里念，还是想成一个画面？」帮他把策略说出来。"}],"mistakes":["一开始就说太多样——三样最合适，太多会挫折。","说太快——要清楚、适中，让他听得清楚每一个词。","答对就结束——追问「你怎么记住的」才是最有价值的一步。"],"down":"减到两样；说慢一点；用他熟悉的东西。","up":"增加到五六样；要求按顺序；变成实际取物任务；或隔一段时间再问。","progress":["能记住几样。","顺序对不对。","能不能说出自己的记忆方法。"],"outro":"发展参考：三岁记两三样、五岁记三四样、七岁记四五样。答对了别忘了追问「你怎么记住的」。"}' AS JSON))
WHERE `id` = 'A139';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '日常物品'),
  `trains` = COALESCE(`trains`, '把这个模组的能力串起来玩一轮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：叫名字要回应。"},{"imageUrl":null,"instruction":"第二关：完成一个两步指令。"},{"imageUrl":null,"instruction":"第三关：听三样东西复述出来。"},{"imageUrl":null,"instruction":"第四关：听方位提示找到藏起来的玩具。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关降低难度、给提示'),
  `harder` = COALESCE(`harder`, '不给提示，或指令加长。'),
  `tip` = COALESCE(`tip`, '「听得懂」是语言的地基——听懂的量够多了，说才会自然冒出来。别急着要孩子说，先让他听懂很多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组一 · 模组十（共同注意 · 指令理解与执行）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"把这个模组串成四关玩一轮。「听得懂」是语言的地基——别急着要孩子说，先让他听懂很多。","principles":["语言发展的顺序是：先听懂，才说得出来。","理解词汇的数量永远远多于能表达的数量。","所以家长要做的是持续输入，而不是一直追问「这是什么」。","输入的量够多了，表达自然会冒出来。","四关分别对应回应、指令、记忆和空间理解，涵盖面完整。","闯关的形式让练习有结构和终点，孩子比较撑得住。","每关有清楚的成功标准，孩子知道自己做到没做到。","记录成绩，一个月后再测一次，进步会看得很清楚。"],"prep":{"场地":"客厅，准备好四关的材料。","器材":"日常物品＋一个小玩具；闯关卡和贴纸。","安全检查":"每关的安全要求照该活动的原则。","大人位置":"大人当关主，负责出题和记录。"},"shots":[{"name":"介绍四关","say":"今天有四关！"},{"name":"第一关","say":"第一关：叫名字要回应。"},{"name":"第二关","say":"第二关：完成两步指令。"},{"name":"第三关","say":"第三关：听三样东西复述出来。"},{"name":"第四关","say":"第四关：听方位提示找到玩具。"},{"name":"全部完成","say":"四关都过了！"}],"reactions":[{"if":"孩子某一关过不了","then":"当场降低标准。闯关是为了看进步，不是考试。"},{"if":"孩子只想玩某一关","then":"让他自己排顺序，或让他设计其中一关。"},{"if":"孩子做完就累了","then":"四关做完就很好了，不用重复。"}],"mistakes":["把它当成测验——这是复习不是考试，标准要宽松。","急着要孩子说话——先确保他听得懂，说是后面的事。","关卡一直不换——两三周换一次内容，保持新鲜感。"],"down":"减到两三关；每关标准降低；只做他拿手的。","up":"提高标准；加到五关；加上计时；或让孩子设计关卡。","progress":["每一关的表现记录下来。","一个月后再测一次，比较进步。","整体的听觉理解能力有没有提升。"],"outro":"「听得懂」是语言的地基——听懂的量够多了，说才会自然冒出来。别急着要孩子说，先让他听懂很多。"}' AS JSON))
WHERE `id` = 'A140';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '6个月–3岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '模仿声音是说话的第一步。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"学动物叫：汪汪、喵喵、哞哞。"},{"imageUrl":null,"instruction":"学车子声：滴滴、呜呜、噗噗。"},{"imageUrl":null,"instruction":"学生活声：啊呜（吃）、掰掰、抱抱。"},{"imageUrl":null,"instruction":"孩子发出任何声音都热情模仿回去。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着发出一个音'),
  `harder` = COALESCE(`harder`, '听到就说出对的声音。'),
  `tip` = COALESCE(`tip`, '孩子咿咿呀呀的时候，学他的声音回应他——这个来回就是最早的「对话」，比教他说话更重要。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组三（声音与仿说）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子还不会说话之前，先会玩声音。汪汪、滴滴、啊呜——这些不是幼稚，这是说话的第一步。今天我们不教词，我们先陪他玩声音。","principles":["模仿声音是语言发展最早出现的能力，比说出第一个有意义的词更早。","孩子要先能控制自己的嘴唇、舌头和气流，才有办法把词说清楚。","动物叫、车子声这类拟声词只有一两个音节，重复性高，孩子最容易上手。","这些声音还带着情绪和趣味，孩子愿意一再重复，练习量自然就上去了。","大人模仿孩子发出的声音，孩子会发现「我发出声音，别人会回应我」。","这个发现比学会任何一个词都重要，它是沟通动机的起点。","一来一往地模仿，同时也在练轮流——你一次、我一次，这是对话的雏形。","孩子先模仿你，再自己主动发声，最后才把声音对应到东西上，顺序不能跳。","如果孩子一岁半仍完全没有任何模仿发声，建议尽早做发展与听力评估。"],"prep":{"场地":"安静、没有电视和背景音乐的地方，孩子看得到你的脸。","器材":"不需要任何东西；可以准备一两个动物玩偶或小车增加趣味。","安全检查":"无特殊风险。全程不强迫孩子发声，他不想出声就先由大人继续玩。","大人位置":"大人和孩子面对面、同高度，脸的距离约三十到五十公分，让他看得清楚你的嘴形。"},"shots":[{"name":"面对面","say":"（脸对着孩子，笑着）汪——汪——"},{"name":"等待","say":"（说完停住，看着孩子，安静等三秒）"},{"name":"孩子出声","say":"（孩子发出任何声音，立刻热情回应）对！汪汪！"},{"name":"换车子声","say":"滴滴——滴滴——车车来了！"},{"name":"生活声音","say":"啊呜——（假装吃）掰掰——（挥手）"},{"name":"先模仿他","say":"（孩子发出「巴巴巴」，大人马上跟着「巴巴巴」）"}],"reactions":[{"if":"孩子完全不出声","then":"先不要求他，大人自己玩得开心一点，多做几天。孩子先要觉得有趣，才会想加入。"},{"if":"孩子发出的音不对","then":"不纠正、不重来。把他发的音接住，再自然地说一次正确的版本就好。"},{"if":"孩子只会一直重复同一个音","then":"那就先陪他重复，玩熟了再在同一个游戏里悄悄加进第二个音。"}],"mistakes":["要求孩子「跟我说一次」——这会让发声变成考试，孩子反而闭嘴。","孩子发音不标准就立刻纠正——这个阶段要的是量，不是准。","大人一直说、不留空档——没有停顿，孩子就没有轮到自己的机会。"],"down":"大人先模仿孩子正在发出的声音，让他先体验「被回应」，不要求他模仿你。","up":"不做示范，直接拿出小狗玩偶问「小狗怎么叫？」，让孩子自己说出对应的声音。","progress":["会不会跟着你发出至少一个声音。","你停下来等的时候，他会不会主动出声。","看到对应的东西（狗、车）时，能不能自己说出那个声音。"],"outro":"记得两件事：第一，先模仿他，再引导他；第二，说完一定要停下来等三秒。孩子的声音，是等出来的，不是催出来的。"}' AS JSON))
WHERE `id` = 'A141';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子正在玩的玩具'),
  `trains` = COALESCE(`trains`, '在玩的时候自然输入词汇，是最有效的方式。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子玩什么，你就说什么。"},{"imageUrl":null,"instruction":"「你在推车车」「车车开得好快」「车车停下来了」。"},{"imageUrl":null,"instruction":"不必要求他跟着说。"},{"imageUrl":null,"instruction":"说的时候慢一点、简单一点。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说单词（车车）'),
  `harder` = COALESCE(`harder`, '说短句（车车开走了）。'),
  `tip` = COALESCE(`tip`, '最有效的语言输入就是「跟着他的兴趣说」——他在看什么、玩什么，就说什么。比拿着卡片教有用一百倍。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组四（名词与生活词汇）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"很多家长问：我该怎么教孩子说话？答案是——不要教，用说的陪他玩。他玩什么，你就说什么。","principles":["孩子学词汇最有效的时机，是他正在注意那样东西的当下。","这叫做跟随孩子的兴趣，研究上一再证实它比大人主导的教学有效。","因为孩子的注意力已经在那里了，你说的词就能直接和眼前的东西对上。","相反地，拿着字卡教词，孩子得先把注意力搬过来，效率低很多。","把他正在做的事说出来，等于帮他的动作配上旁白，词就有了意义。","不要求他跟着说，这一点非常关键——理解永远走在表达前面。","孩子要听过一个词很多次，才会开始说它，中间这段沉默期是正常的。","说的时候放慢、句子简短，孩子才有时间处理你说的内容。","这个方法不需要额外时间，玩什么都能做，所以最容易每天累积。"],"prep":{"场地":"孩子平常玩的地方就好，地上、桌上都可以。","器材":"孩子当下正在玩的玩具，不另外准备，也不换成你想教的东西。","安全检查":"无特殊风险。全程不抢走孩子的玩具，不打断他正在进行的游戏。","大人位置":"大人坐在孩子旁边或对面，跟他同高度，眼睛跟着他的手看。"},"shots":[{"name":"先观察","say":"（不说话，先看孩子在玩什么，约五秒）"},{"name":"说出他在做的事","say":"你在推车车。"},{"name":"加一点点","say":"车车开得好快。"},{"name":"说结果","say":"车车停下来了。"},{"name":"不要求他说","say":"（孩子没有回应，大人继续自然地玩和说）"},{"name":"慢下来","say":"车——车——上——去——了。"}],"reactions":[{"if":"孩子不理你，自己玩自己的","then":"这是正常的，继续说就好。你的任务是输入，不是拿到回应。"},{"if":"孩子把玩具抢走不给你碰","then":"不用碰玩具也能说。手不动，嘴巴动，一样有效。"},{"if":"孩子换来换去玩很多东西","then":"他换你就跟着换，每样东西说一两句。跟着他，不要把他拉回来。"}],"mistakes":["边说边问「这是什么？跟我说一次」——一问，游戏就变考试。","说的句子太长太复杂，孩子听不到重点词。","抢过玩具示范「正确玩法」——孩子的兴趣一断，词就进不去了。"],"down":"只说单词，一次一个：「车车」「推」「快」。句子越短，孩子越抓得到。","up":"说出三到四个词的句子，并加入形容词和位置词：「红色的车车开到桌子下面去了」。","progress":["孩子在玩的时候，会不会偶尔抬头看你或看你指的东西。","他会不会开始跟着说出其中一两个词。","同一个词你说过几天后，他能不能在别的场合用出来。"],"outro":"记住这句话：他玩什么，你就说什么；不要求他跟着说。词汇不是教会的，是听多了自己长出来的。"}' AS JSON))
WHERE `id` = 'A142';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '家里的东西'),
  `trains` = COALESCE(`trains`, '认识日常物品的名称，是词汇量的主力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"日常做事时说出东西的名字：「拿杯子」「穿袜子」「开冰箱」。"},{"imageUrl":null,"instruction":"吃饭时说食物名、洗澡时说身体部位。"},{"imageUrl":null,"instruction":"出门时说看到的东西。"},{"imageUrl":null,"instruction":"一天说几十次，不刻意教。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出名称让他听'),
  `harder` = COALESCE(`harder`, '问「这是什么？」让他说。'),
  `tip` = COALESCE(`tip`, '名词是最好学的一类词——生活里到处都是。别用「教学时间」教，用「生活时间」说，孩子吸收得更好。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组四（名词与生活词汇）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子的词汇量，不是靠上课上出来的，是靠一天几十次的生活对话堆出来的。今天教你怎么把家里变成词汇教室。","principles":["名词是孩子最早也最大量学会的词类，是词汇量的主力。","日常物品每天都会出现，重复次数远高于任何教材。","孩子在真实情境里学词，同时学到这个东西怎么用、什么时候出现。","这种带着情境的词，记得比较牢，也比较会用。","一天说几十次听起来很多，但穿衣、吃饭、洗澡加起来自然就到了。","不刻意教，孩子不会有压力，也不会把说话和被考试连在一起。","先大量说给他听，等他熟了再问「这是什么」，顺序不要颠倒。","一次专注在同一类词（今天衣物、明天食物），孩子比较容易归类。","词汇量在两到三岁间成长最快，这段时间的输入量影响最明显。"],"prep":{"场地":"家里任何一个日常场景：餐桌、浴室、玄关、冰箱前。","器材":"家里现有的东西，不需要买字卡或教具。","安全检查":"厨房与浴室拍摄时注意热水、刀具与地面湿滑，孩子全程有人在旁。","大人位置":"大人做事、孩子在旁边看，一边做一边说，不特地停下来上课。"},"shots":[{"name":"穿衣服","say":"穿袜子，袜子。穿鞋子，鞋子。"},{"name":"吃饭","say":"这是碗，这是汤匙，我们吃面。"},{"name":"洗澡","say":"洗手手，洗肚子，洗脚脚。"},{"name":"开冰箱","say":"开冰箱，拿牛奶，关冰箱。"},{"name":"出门看到什么说什么","say":"公车、红灯、小狗。"},{"name":"进阶：换他说","say":"这是什么呀？"}],"reactions":[{"if":"孩子说错名字","then":"不要说「不对」。直接把正确的说一次：「这是汤匙喔，汤匙。」示范比纠正有效。"},{"if":"孩子都不回答","then":"回到只说不问。多说一两个星期，等他熟了再问。"},{"if":"孩子只对某几样东西有兴趣","then":"就从那几样开始，先把他喜欢的说到滚瓜烂熟，再慢慢往外扩。"}],"mistakes":["把说名字变成考试，一天问很多次「这是什么」。","一次教太多新词，孩子来不及消化。","孩子说错就纠正、要求重说——这最容易让孩子不想开口。"],"down":"只说名称给他听，完全不问问题，让他先累积听觉经验。","up":"说出完整词组：「蓝色的杯子」「爸爸的鞋子」，再问「你要哪一个？」让他用词表达选择。","progress":["孩子听到名称时，会不会去看或去拿那样东西。","他主动说出的物品名称有没有变多。","在不同场合看到同一样东西，能不能用同一个词说出来。"],"outro":"不必买字卡，也不必排时间。穿衣服、吃饭、洗澡的时候，把东西的名字说出来就好。一天几十次，一个月就是上千次。"}' AS JSON))
WHERE `id` = 'A143';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会动词，句子才组得起来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"做动作配上词：跑、跳、坐、站、吃、喝、开、关。"},{"imageUrl":null,"instruction":"玩「我说你做」：说一个动词，孩子做出来。"},{"imageUrl":null,"instruction":"再换他说、大人做。"},{"imageUrl":null,"instruction":"绘本里的动作也一起说。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '听词做动作'),
  `harder` = COALESCE(`harder`, '自己做动作说出动词。'),
  `tip` = COALESCE(`tip`, '很多孩子名词会很多、动词很少——但没有动词就组不出句子。刻意多说动作词，句子才长得出来。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组五（动词与动作词汇）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"很多孩子会说很多名词，却讲不出一句话。原因通常只有一个——动词太少。今天专门补动词。","principles":["句子的核心是动词，没有动词就组不成句子。","很多孩子名词一大堆，动词很少，所以只能一个词一个词蹦。","动词比名词难学，因为它看不见、摸不到，只存在于动作发生的那一瞬间。","所以动词一定要在动作正在发生的当下说出来，孩子才对得上。","让孩子用身体做出来，动作和词就会绑在一起，记得更牢。","「我说你做」这个游戏同时练了听指令理解和动词理解。","换孩子出题、大人做，他就从理解转成表达，难度自然提高一阶。","绘本里的动作也一起说，可以把动词带到更多情境中。","动词量一上来，孩子的句子长度通常会跟着明显变长。"],"prep":{"场地":"有空间可以跑跳的客厅或户外，地面清空防滑。","器材":"不需要任何东西；有绘本可以在最后一个镜头使用。","安全检查":"跑跳动作前先清掉地上的杂物与桌角尖锐处，孩子赤脚或穿防滑袜。","大人位置":"大人站在孩子前方，先做示范，再退到旁边下指令。"},"shots":[{"name":"做什么说什么","say":"跑！跳！坐！站！"},{"name":"我说你做","say":"我说你做喔——跳！"},{"name":"生活动词","say":"吃、喝、开、关。"},{"name":"换他说","say":"换你说，我来做。"},{"name":"绘本里的动作","say":"你看，小熊在爬！在睡觉！"},{"name":"连起来说","say":"哥哥在跑，妹妹在跳。"}],"reactions":[{"if":"孩子听词做不出动作","then":"大人先做一次给他看，再说一次词。示范比解释快得多。"},{"if":"孩子只会做不会说","then":"这是正常的中间阶段。继续做，边做边由你说出动词，说的部分会慢慢跟上来。"},{"if":"孩子玩到太兴奋停不下来","then":"穿插「停」和「坐下」这两个动词当刹车，既收得回来又多学两个词。"}],"mistakes":["只教名词不教动词——孩子的句子会一直长不出来。","动作做完才说词，时间对不上，孩子连不起来。","一次丢出七八个动词，孩子记不住，反而都没学到。"],"down":"一次只练两个对比强烈的动词（跑／停、坐／站），先听词做动作就好。","up":"把动词放进句子里说：「小狗在跑」「妈妈在喝水」，并让孩子自己描述别人正在做什么。","progress":["听到动词能不能正确做出动作。","自己做动作时会不会同时说出动词。","句子里有没有开始出现「谁在做什么」的组合。"],"outro":"名词多、动词少的孩子，句子长不出来。每天陪他做几个动作、说几个动词，句子就会自己长长。"}' AS JSON))
WHERE `id` = 'A144';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个袋子＋几样触感不同的东西'),
  `trains` = COALESCE(`trains`, '学形容词（大小、软硬、冷热、粗滑）。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把东西放进袋子里。"},{"imageUrl":null,"instruction":"让孩子伸手摸，说出感觉：软软的、硬硬的、毛毛的。"},{"imageUrl":null,"instruction":"拿出来看看对不对。"},{"imageUrl":null,"instruction":"一次只教一组对比词（软／硬）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '从两个词里选一个'),
  `harder` = COALESCE(`harder`, '自己说出形容词。'),
  `tip` = COALESCE(`tip`, '形容词要「先感觉、再给词」——摸过冰的东西才懂「冰冰的」。一次教一组对比词，别一口气教太多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组六（形容词与概念词）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"软软的、硬硬的、毛毛的——形容词不是用眼睛学的，是用手摸出来的。今天我们做一个神秘袋。","principles":["形容词描述的是性质，比名词抽象，孩子需要先有身体经验才学得会。","触觉是最直接的经验来源，摸到了，词就有了实感。","把手伸进看不见的袋子里，孩子必须专心用触觉判断，感觉会更清楚。","这同时也在练触觉辨识，对手部操作与书写前技巧都有帮助。","一次只教一组对比词，因为对比最容易凸显差异。","软对硬、粗对滑、冷对热，成对出现的词孩子学得最快。","摸完拿出来看，是让触觉经验和视觉经验对上，理解才完整。","形容词一多，孩子的句子就从「车车」变成「红色的大车车」。","这个活动也自然练到轮流和等待，因为要一个一个来。"],"prep":{"场地":"桌边坐着进行，光线充足但袋口不让孩子看见内容。","器材":"一个不透明的布袋或纸袋，加上四到六样触感明显不同的东西（棉花、积木、绒毛玩偶、塑胶球、汤匙）。","安全检查":"放进袋子的东西不可有尖角、锐边，也不可小到能吞下；三岁以下全程大人握着袋口。","大人位置":"大人坐在孩子侧边，一手扶袋、一手随时可以把东西拿出来对答案。"},"shots":[{"name":"介绍神秘袋","say":"这里面有东西喔，用手摸摸看，不可以偷看。"},{"name":"伸手摸","say":"摸到了吗？是软软的还是硬硬的？"},{"name":"说出感觉","say":"软软的！对，是软软的棉花。"},{"name":"换一组对比","say":"这个呢？毛毛的还是滑滑的？"},{"name":"二选一的提示法","say":"是硬硬的，还是软软的？"},{"name":"加进句子","say":"这是硬硬的积木。"}],"reactions":[{"if":"孩子说不出形容词","then":"给两个选项让他选：「软软的还是硬硬的？」选对了再由你说一次完整句。"},{"if":"孩子直接说出物品名称","then":"先肯定他：「对，是积木。」再问「那积木摸起来是什么感觉？」把焦点带回形容词。"},{"if":"孩子不敢把手伸进去","then":"先把袋口打开让他看着摸，等他习惯了再盖起来。"}],"mistakes":["一次放进太多种触感，孩子分不出来，什么词都没学到。","孩子说错就说「不对」——改成直接示范正确的说法。","大人急着替他讲完，孩子没有机会开口。"],"down":"不用袋子，把两样东西直接放在桌上摸，一次只比一组对比词。","up":"摸完之后要求说完整句：「这是毛毛的、软软的小熊」，或让孩子出题考大人。","progress":["能不能从两个选项中选出正确的形容词。","会不会主动说出形容词而不只是物品名称。","同一个形容词能不能用在别的东西上（软软的面包、软软的枕头）。"],"outro":"形容词要先摸到，才说得出来。先感觉、再给词，这个顺序一颠倒，孩子就只是在背书。"}' AS JSON))
WHERE `id` = 'A145';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '家里的物品'),
  `trains` = COALESCE(`trains`, '学颜色和形状的词，也练分类概念。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"找出红色的东西：「红色的苹果、红色的车」。"},{"imageUrl":null,"instruction":"找出圆形的东西：「圆圆的盘子、圆圆的球」。"},{"imageUrl":null,"instruction":"一次专注一个颜色或形状。"},{"imageUrl":null,"instruction":"出门时也玩「找红色」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '认三种基本颜色'),
  `harder` = COALESCE(`harder`, '说出「红色的××」完整词组。'),
  `tip` = COALESCE(`tip`, '颜色和形状常常是孩子最早会说的形容词——用「找一找」的游戏形式，比拿色卡问「这是什么颜色」有趣得多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组六（形容词与概念词）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"今天只找红色的东西。一次专注一个颜色，孩子学得最快——这比一次教七种颜色有效太多了。","principles":["颜色和形状都是属性词，孩子必须把它从物品本身抽离出来才学得会。","这对幼儿来说不容易，因为苹果既是苹果、又是红色、又是圆的。","一次专注一个颜色，孩子才能发现「这些东西不一样，但有同一个特征」。","这个发现就是分类概念的起点，也是日后学习逻辑思考的基础。","说「红色的苹果」而不只说「红色」，是把属性和名词绑在一起的关键说法。","形状词比颜色更抽象一点，通常从圆形开始最容易。","出门时玩「找红色」，可以把学到的词带到不同情境，泛化才算真的学会。","颜色词通常在三岁前后才稳定，之前会说但对不准是正常现象。","这个活动同时练到视觉搜寻，对日后阅读时找字也有帮助。"],"prep":{"场地":"家里客厅或孩子的房间，东西种类多一点的地方。","器材":"家里现有的物品；不需要色卡，真实物品的效果更好。","安全检查":"找东西时注意别让孩子爬高或拉扯桌布，会倒的东西先移开。","大人位置":"大人和孩子一起走动找，不要坐着指挥。"},"shots":[{"name":"宣布主题","say":"今天我们只找红色！"},{"name":"一起找","say":"红色的苹果，红色的车车，红色的袜子。"},{"name":"排在一起","say":"你看，全部都是红色的。"},{"name":"换形状","say":"今天找圆圆的——圆圆的盘子、圆圆的球。"},{"name":"说完整词组","say":"这是红色的球，也是圆圆的球。"},{"name":"出门找","say":"看到红色就喊红色！"}],"reactions":[{"if":"孩子把颜色说错","then":"直接示范正确说法：「这是蓝色的喔，蓝色。」不用要求他重说一次。"},{"if":"孩子只会指不会说","then":"他指对就先给肯定，然后由你说出完整词组，让他多听几次。"},{"if":"孩子把所有东西都说成同一个颜色","then":"这很常见。回到一次只玩一个颜色，并大量说给他听，不急着考。"}],"mistakes":["一次教七种颜色，孩子全部混在一起。","只说「红色」不说「红色的苹果」，孩子学不会怎么把词用进句子。","用考试的方式一直问「这是什么颜色」，孩子会开始逃避。"],"down":"只做两个差异最大的颜色（红和蓝），用同一样东西的两个版本来比。","up":"玩「红色而且是圆的」这种双条件搜寻，或让孩子自己出题指定颜色形状。","progress":["拿得出你指定颜色的东西吗。","会不会自己说出「红色的××」这样的词组。","在外面看到东西时，会不会主动说出颜色或形状。"],"outro":"一次一个颜色，说的时候记得带上东西的名字——「红色的苹果」。这样孩子学到的不只是词，是怎么用。"}' AS JSON))
WHERE `id` = 'A146';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–4岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '从单词进步到两个词的组合。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子说「车」，你回应「红色车」「车开了」。"},{"imageUrl":null,"instruction":"把他的一个词扩成两个词。"},{"imageUrl":null,"instruction":"不要求他跟着说，听多了自然会。"},{"imageUrl":null,"instruction":"日常一直这样回应。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '听你扩句'),
  `harder` = COALESCE(`harder`, '自己说出两个词的组合。'),
  `tip` = COALESCE(`tip`, '这叫「扩展」——孩子说一个词，你回一个稍长的。不是纠正他，是给他下一步的示范。这是最有效的语言技巧之一。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组七（功能词与词语组合）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子说「车」，你可以回「对，车」——也可以回「红色的车」。差别看起来很小，累积起来就是他会不会说句子。","principles":["从单词进步到两个词的组合，是语言发展的一个重要关卡。","大人把孩子说的词加长一点点再说回去，这个方法叫做扩展。","扩展的原则是永远比他多一点点，不是多很多。","他说一个词，你回两个词；他说两个词，你回三到四个词。","多太多孩子接不住，多一点点他才吸收得了。","扩展时不要求他跟着说，要求会让他闭嘴，听多了自然会用。","同时你也示范了正确的语法，孩子是从你的句子里学结构的。","这个方法随时随地都能做，不需要额外时间和教具。","通常先出现「名词＋动词」和「形容词＋名词」这两种组合。"],"prep":{"场地":"日常任何场景，孩子正在玩或正在看东西的时候最好。","器材":"不需要任何东西，用孩子当下说出的词来接。","安全检查":"无特殊风险。全程不打断孩子说话，不替他把话讲完。","大人位置":"大人蹲下与孩子同高，眼神接触后再回应。"},"shots":[{"name":"孩子说一个词","say":"（孩子指着车说）车！"},{"name":"扩成两个词","say":"红色车。"},{"name":"换一种扩法","say":"车开了。"},{"name":"不要求跟说","say":"（说完不追问，继续陪他玩）"},{"name":"孩子说两个词","say":"（孩子说「车开」）大人接：红色车开走了。"},{"name":"多一点点原则","say":"比他多一点点就好。"}],"reactions":[{"if":"孩子说的词听不清楚","then":"依当下情境猜他的意思，然后把你猜的用完整说法说出来。猜错了他通常会纠正你。"},{"if":"孩子完全不说，只用手指","then":"一样扩展——他指着车，你说「车」，再说「红色车」。指也是沟通。"},{"if":"孩子重复你扩展的句子","then":"很好，但不要因此开始要求他重复。自发的重复才有价值。"}],"mistakes":["一次把句子扩太长，孩子接不住。","扩完就要求「你说一次」，把对话变成练习。","只重复他说的词而不加长，孩子就一直停在单词阶段。"],"down":"先只做单纯的重复加一个字：「车」→「车车」「大车」，让长度只增加一点点。","up":"扩展到四到五个词，并加入位置或时间：「红色的车开到桌子下面去了」。","progress":["孩子自己说出的词组有没有变成两个词。","他说话时会不会开始加上形容词或动词。","同一个东西，他能不能用不同的组合描述。"],"outro":"回应孩子的时候，永远比他多一点点。他说一个词，你说两个；他说两个，你说四个。不用要求他跟着念，听多了就会了。"}' AS JSON))
WHERE `id` = 'A147';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '图画书或照片'),
  `trains` = COALESCE(`trains`, '说出「谁＋做什么」的完整句。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"看一张图问「谁在做什么？」"},{"imageUrl":null,"instruction":"示范说「弟弟在吃饭」。"},{"imageUrl":null,"instruction":"让孩子照着说。"},{"imageUrl":null,"instruction":"再看下一张。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出两个元素（弟弟吃）'),
  `harder` = COALESCE(`harder`, '说完整句加上东西（弟弟在吃苹果）。'),
  `tip` = COALESCE(`tip`, '「谁＋做什么＋什么」是句子的基本骨架。孩子说得不完整时，把完整版说一遍让他跟着说，别说「你说错了」。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组八（简单句表达）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子会说很多词了，但还讲不成一句话？那就从最简单的句型开始——谁，在做什么。","principles":["「谁＋做什么」是最基本的句型，几乎所有句子都从这个骨架长出来。","孩子必须同时注意到人物和动作，才说得出这样的句子。","看图说话比看实景容易，因为画面是静止的，孩子有时间观察。","大人先示范一次完整句，孩子才知道目标长什么样子。","示范之后再让他说，比直接问「这是什么」有效得多。","从两个元素（弟弟吃）开始，再加上宾语（弟弟吃苹果）。","这个句型练熟之后，叙事能力才有基础，才讲得出发生了什么事。","用孩子自己的照片效果最好，因为他对画面里的人有情感连结。","这个活动也同时练到观察与注意力的分配。"],"prep":{"场地":"安静的桌边或沙发上，两人并肩看同一个画面。","器材":"图画书、家庭照片，或手机里孩子熟悉的照片。","安全检查":"无特殊风险。使用孩子的照片拍摄时，注意影片中不出现全名与学校。","大人位置":"大人坐在孩子旁边，手指可以点到画面上的人物。"},"shots":[{"name":"看图发问","say":"你看这一张，谁在做什么？"},{"name":"大人先示范","say":"弟弟在吃饭。"},{"name":"换孩子说","say":"（等待，不催）"},{"name":"接住并加长","say":"对，弟弟在吃饭——弟弟在吃苹果。"},{"name":"换一张","say":"这一张呢？"},{"name":"用家人照片","say":"这是谁？他在做什么？"}],"reactions":[{"if":"孩子只说出人物不说动作","then":"你把动作补上：「对，是弟弟——弟弟在吃饭。」示范完整句，不要求重说。"},{"if":"孩子说错人物","then":"温和地说出正确的：「这是哥哥喔，哥哥在跑步。」不做纠正式的来回。"},{"if":"孩子不愿意说","then":"改成二选一：「他在吃饭还是在睡觉？」有选项就容易开口。"}],"mistakes":["连续问太多张，变成看图考试。","孩子答对了就急着翻下一页，没有把句子再说一次加长。","问题问得太开放（「你看到什么？」），孩子不知道要回答什么。"],"down":"只要求说出两个元素：「弟弟吃」。先有骨架，再补细节。","up":"加上地点和形容词：「弟弟在厨房里吃红色的苹果」，或让孩子连说两张图编成一小段故事。","progress":["会不会自己说出「谁＋做什么」的组合。","句子里有没有开始出现宾语（吃苹果、玩球）。","看到新的图片，能不能不用示范就说出句子。"],"outro":"每天看一两张图，问一句「谁在做什么」。这个最简单的句型练熟了，孩子才讲得出后面的故事。"}' AS JSON))
WHERE `id` = 'A148';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子想要的东西'),
  `trains` = COALESCE(`trains`, '学会用说的表达需求，减少哭闹。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子伸手要东西时，示范「说：我要饼干」。"},{"imageUrl":null,"instruction":"他说了（或说出一部分）就给他。"},{"imageUrl":null,"instruction":"从单词「要」开始，慢慢到完整句。"},{"imageUrl":null,"instruction":"他一开口就要回应，别让他白说。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说一个词「要」'),
  `harder` = COALESCE(`harder`, '说完整句「我要××」。'),
  `tip` = COALESCE(`tip`, '「说了有用」是表达最大的动力——孩子一说就回应他。很多哭闹其实是「说不出来」，会说了就少一大半。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组八（简单句表达）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子一哭你就懂、一指你就给——他就没有理由开口。今天教你怎么创造说话的机会，又不让孩子崩溃。","principles":["孩子会开口，是因为他发现说话有用、比哭比指更有效。","如果每一次伸手你都立刻给，说话对他就没有好处。","所以要留一个小小的空档，让他有机会用说的。","这个空档要短，大约三到五秒，太久孩子会挫折甚至崩溃。","示范「说：我要饼干」，让他知道要说什么，不是让他自己猜。","他说了一部分也算数，说出「要」就要给，不能要求一次到位。","一开口就立刻给，是最重要的一条——让他确认说话真的有效。","从单词到完整句要慢慢来，通常是「要」→「要饼干」→「我要饼干」。","这是功能性沟通的核心，也是减少哭闹最有效的方法之一。"],"prep":{"场地":"孩子熟悉的生活场景，点心时间或玩玩具时最自然。","器材":"孩子真心想要的东西（点心、玩具），放在看得到但拿不到的地方。","安全检查":"不使用会让孩子极度焦虑的方式（如长时间不给）。孩子明显崩溃就立刻给予并安抚，不继续要求。","大人位置":"大人蹲下与孩子同高，手上拿着东西，脸和东西在同一个视线方向。"},"shots":[{"name":"制造机会","say":"（把饼干放在孩子看得到、拿不到的地方）"},{"name":"孩子伸手","say":"（孩子伸手、发出声音）"},{"name":"示范说法","say":"说：我要饼干。"},{"name":"说了就给","say":"（孩子说出「要」）好！给你饼干！"},{"name":"说一部分也算","say":"（孩子只说「饼」）好，饼干给你。"},{"name":"慢慢加长","say":"我——要——饼干。"}],"reactions":[{"if":"孩子开始哭闹","then":"立刻给他并安抚，不要在哭的时候继续要求说话。等他平静了下一次再试。"},{"if":"孩子只发出声音不说词","then":"那就算成功，把东西给他，同时由你把词说一次。声音也是沟通的开始。"},{"if":"孩子说完了你却慢了一步","then":"一定要快。慢了，他就学到说话没有用。"}],"mistakes":["要求孩子说完整句才给，标准太高，孩子放弃开口。","等太久才给，把练习变成折磨。","孩子说了却没有立刻回应，说话的效力就被破坏了。"],"down":"只要有任何发声或手势就给，先建立「表达→得到」的连结。","up":"要求完整句「我要××」，并加上礼貌词或数量：「我要两片饼干，谢谢」。","progress":["孩子想要东西时，会不会主动发声或说词。","说出的内容有没有从一个字慢慢变长。","哭闹要东西的次数有没有减少。"],"outro":"最重要的一句话：他一开口，就要立刻给。说了有用，他才会一直说下去。绝对不要让孩子觉得白说了。"}' AS JSON))
WHERE `id` = 'A149';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会用说的拒绝，替代尖叫和赖皮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子抗拒时示范「你可以说：我不要」。"},{"imageUrl":null,"instruction":"他说了就认真对待（能商量就商量）。"},{"imageUrl":null,"instruction":"教他「不喜欢」「等一下」。"},{"imageUrl":null,"instruction":"尊重他合理的拒绝。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说「不要」'),
  `harder` = COALESCE(`harder`, '说「我不喜欢××，我想要××」。'),
  `tip` = COALESCE(`tip`, '会好好说「不」的孩子，才不用靠尖叫来拒绝。允许他说不要，并认真回应——这是很重要的表达权利。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组三（情绪表达·说出感受）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子尖叫、推开、躺地上——他其实是在说「我不要」，只是他还不会用说的。今天我们教他这三个字。","principles":["拒绝是每个孩子都需要的沟通功能，而且出现得很早。","不会用说的拒绝，孩子只好用尖叫、推开、躺地上来表达。","所以教「我不要」不是在教他顶嘴，是在换掉一个更麻烦的行为。","孩子说了「不要」，大人要认真对待，这句话才有效力。","能商量的就商量，不能的要说明并给替代方案。","如果说了都没用，孩子会退回去用尖叫，因为尖叫比较有效。","同时教「不喜欢」「等一下」，让他有更多层次的表达方式。","尊重合理的拒绝，也是在教孩子自己的感受可以被表达。","这对日后的自我保护能力同样重要——会说不的孩子比较不容易被欺负。"],"prep":{"场地":"日常生活中孩子真的会想拒绝的场景（不想吃、不想收玩具）。","器材":"不需要任何东西，用真实情境即可。","安全检查":"安全相关的事情（过马路牵手、坐安全座椅）不开放拒绝，要明确说明并坚持。","大人位置":"大人蹲下与孩子同高，保持平稳语气，不用威胁的口吻。"},"shots":[{"name":"孩子抗拒","say":"（孩子推开碗、转头）"},{"name":"给他词","say":"你可以说：我不要。"},{"name":"认真对待","say":"好，你说不要，那我们等一下再吃。"},{"name":"能商量就商量","say":"你不要青菜，那要不要先吃一口就好？"},{"name":"更多说法","say":"你可以说：我不喜欢。也可以说：等一下。"},{"name":"安全的事不能拒绝","say":"过马路一定要牵手，这件事不能选。"}],"reactions":[{"if":"孩子说不要之后大人还是硬来","then":"那他下次就不说了。除非是安全问题，否则说了要算数。"},{"if":"孩子什么都说不要","then":"正常，这是他刚拿到新工具在试用。多给选择题，让他有机会说要。"},{"if":"孩子还是用尖叫","then":"在他尖叫的时候平静示范一次说法，等他平静一点再回应他的要求。"}],"mistakes":["教了「我不要」却从来不接受——这会让这句话失去意义。","把孩子的拒绝当成挑衅，用更大的音量压回去。","所有事情都开放协商，包括安全相关的事。"],"down":"先只教一个词「不要」，并在他用身体拒绝时替他说出来。","up":"教完整表达：「我不喜欢青菜，我想要吃胡萝卜」，把拒绝和替代方案连在一起。","progress":["孩子会不会用说的表达拒绝。","尖叫、推开的次数有没有减少。","会不会说出替代方案而不只是拒绝。"],"outro":"会好好说不的孩子，才不用靠尖叫。他说了不要，请你认真对待——除非是安全的事，那就要坚持。"}' AS JSON))
WHERE `id` = 'A150';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '稍微有点难度的东西'),
  `trains` = COALESCE(`trains`, '学会求助，把挫折转成沟通。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给一个他打不开的盒子或转不开的盖子。"},{"imageUrl":null,"instruction":"他卡住快烦躁时，示范「说：帮帮我」。"},{"imageUrl":null,"instruction":"他一说就立刻帮忙。"},{"imageUrl":null,"instruction":"把「卡住→求助」变成反射。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着说「帮帮我」'),
  `harder` = COALESCE(`harder`, '卡住时主动求助而不发脾气。'),
  `tip` = COALESCE(`tip`, '会求助的孩子，挫折不容易变成崩溃。「帮帮我」这三个字，值得反复练到自动化。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组八（简单句表达）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子打不开盒子就把它摔掉——他不是脾气坏，是不知道可以求助。今天我们把「卡住」变成「帮帮我」。","principles":["求助是一项独立的沟通功能，不会自己长出来，需要教。","不会求助的孩子，遇到困难只能用生气、放弃或破坏来处理。","把挫折转成沟通，是情绪调节和语言能力的交会点。","要抓在他快烦躁、但还没爆炸的那一刻示范，时机很关键。","已经爆炸了就先安抚，那时候教什么都进不去。","他一说「帮帮我」就立刻帮，让这句话的效果非常明确。","重复够多次之后，「卡住→求助」会变成反射反应。","这项能力会一路用到学校，不敢举手问问题的孩子学习会吃亏。","同时也在练忍受挫折——求助本身就是一种有建设性的应对。"],"prep":{"场地":"桌边进行，孩子坐稳，东西放在他面前。","器材":"一个他打得开一半但打不开全部的盒子，或转不太开的瓶盖。","安全检查":"容器不可为玻璃材质，盖子不可有锐利边缘；不使用密封到需要用力过猛的容器。","大人位置":"大人坐在旁边，手可以随时伸过去帮忙，但先不动。"},"shots":[{"name":"给一个小难题","say":"（把盒子递给孩子）里面有你的饼干喔。"},{"name":"他卡住了","say":"（孩子用力转，转不开，开始皱眉）"},{"name":"抓住时机示范","say":"说：帮帮我。"},{"name":"立刻帮忙","say":"（孩子说出来）好，我帮你！"},{"name":"手势也算","say":"（孩子把盒子递过来）你是要我帮忙对不对？帮帮我。"},{"name":"变成反射","say":"卡住的时候，就说帮帮我。"}],"reactions":[{"if":"孩子直接生气把东西丢掉","then":"先安抚情绪，捡回来，等他平静再重来一次。生气的时候不教新词。"},{"if":"孩子不出声只是把东西推过来","then":"接受这个手势，同时替他说出「帮帮我」，下次再等一下看他会不会说。"},{"if":"孩子每次都马上求助不自己试","then":"先鼓励他试三下：「你先试试看，试三下再叫我。」再给帮助。"}],"mistakes":["难度设得太高，孩子还没开口就先崩溃。","等到孩子大哭了才开始教说法，那时候什么都听不进去。","孩子说了却拖着不帮，让求助变得没有用。"],"down":"孩子只要把东西递过来或看你一眼，就当作求助并立刻帮忙，同时替他说出那句话。","up":"教更明确的求助：「妈妈，这个太紧了，可以帮我打开吗？」并练习在别人面前开口。","progress":["卡住的时候会不会主动求助而不是发脾气。","求助的方式有没有从手势变成说话。","在其他场合（穿鞋、拿高处东西）会不会也用同一句话。"],"outro":"难度要刚刚好，时机要在他爆炸之前。他一说「帮帮我」，你就立刻帮。几十次之后，这会变成他的反射动作。"}' AS JSON))
WHERE `id` = 'A151';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '家人的物品'),
  `trains` = COALESCE(`trains`, '学会「我的、你的、他的」，练所有格。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿起东西问「这是谁的？」"},{"imageUrl":null,"instruction":"答「这是爸爸的鞋」「这是我的书」。"},{"imageUrl":null,"instruction":"收衣服时特别好玩：分给每个人。"},{"imageUrl":null,"instruction":"连到「我的」「你的」的概念。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出人名（爸爸）'),
  `harder` = COALESCE(`harder`, '说完整（这是爸爸的鞋）。'),
  `tip` = COALESCE(`tip`, '收衣服、分东西的时候顺便玩——孩子还能顺便学会尊重别人的东西。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组七（功能词与词语组合）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"收衣服的时候别急着自己折——这是练「我的、你的、爸爸的」最好的时机，而且孩子超爱玩。","principles":["所有格是孩子早期需要掌握的语法概念之一。","「我的、你的、他的」牵涉到视角转换，比一般名词难。","因为同一件衣服，对我来说是我的，对你来说是你的。","从具体的家人物品开始最容易，因为归属关系很明确。","收衣服时分给每个人，孩子有动作、有结果，学得特别快。","「这是爸爸的鞋」是一个完整词组，同时练到所有格和名词。","这个概念连结到物权观念，对减少抢玩具的冲突也有帮助。","先练「爸爸的、妈妈的」这种第三人称，再练「我的、你的」。","孩子说得出「这是我的」，才有办法开始谈「那是别人的」。"],"prep":{"场地":"客厅地板或床上，衣服堆得开的地方。","器材":"刚收进来的衣物、家人的鞋子或杯子。","安全检查":"避免使用有细绳、小配件的衣物给三岁以下孩子操作。","大人位置":"大人和孩子一起坐在衣服堆旁，一件一件拿起来。"},"shots":[{"name":"拿起一件","say":"这是谁的？"},{"name":"孩子回答","say":"（孩子说「爸爸」）"},{"name":"补成完整句","say":"对，这是爸爸的裤子。"},{"name":"分堆","say":"爸爸的放这边，你的放这边。"},{"name":"我的你的","say":"这是我的杯子，这是你的杯子。"},{"name":"送去给人","say":"把爸爸的拿给爸爸。"}],"reactions":[{"if":"孩子把「我的」和「你的」搞反","then":"这非常常见，是视角转换还不成熟。直接示范正确说法，不必解释规则。"},{"if":"孩子只说人名不说完整句","then":"先接受，再由你说一次完整的：「对，这是爸爸的——爸爸的裤子。」"},{"if":"孩子坚持所有东西都是他的","then":"不争辩。玩「送去给人」的动作版，用行动建立归属概念。"}],"mistakes":["一开始就教「我的、你的」，视角太难，孩子容易混乱。","孩子说错时长篇解释语法规则，他听不懂。","把它变成问答游戏，失去了生活中一边做一边学的自然感。"],"down":"只做两个人的物品分类（爸爸的／宝宝的），并用动作把东西送过去。","up":"加入「他的、她的」以及不在现场的人，并要求说完整句「这是姐姐的红色外套」。","progress":["能不能正确说出东西属于谁。","会不会自己说出「××的××」的完整词组。","「我的、你的」用得对不对。"],"outro":"收衣服的时候顺便玩，一件一件问「这是谁的」。孩子学到的不只是词，还有东西是有主人的这件事。"}' AS JSON))
WHERE `id` = 'A152';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '玩具'),
  `trains` = COALESCE(`trains`, '学会位置词（上下里外前后旁边）。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把玩具放在不同位置。"},{"imageUrl":null,"instruction":"问「小熊在哪里？」教他答「在桌子上面」。"},{"imageUrl":null,"instruction":"再换他藏、你猜。"},{"imageUrl":null,"instruction":"日常收东西时也说位置。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说「上面」「下面」'),
  `harder` = COALESCE(`harder`, '说完整句「在桌子的下面」。'),
  `tip` = COALESCE(`tip`, '位置词是数学和阅读的基础——藏东西找东西的游戏最好练，孩子也玩不腻。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组六（形容词与概念词）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"上面、下面、里面、旁边——这些词看起来简单，却是孩子听懂指令、看懂题目的基础。今天用藏玩具来练。","principles":["位置词是空间概念的语言表现，同时牵涉认知与语言两个面向。","孩子要先能在空间中找到东西，才说得出它在哪里。","听懂位置词，孩子才听得懂「把书放在桌子上面」这类日常指令。","这些词到了学龄期会直接影响数学与阅读理解的题目。","藏玩具、找玩具让位置词有了实际用途，学起来更有动机。","先练最容易的上面、下面，再练里面、外面，最后才是前后左右。","换孩子藏、大人猜，他就从理解转成表达，难度自然提高。","日常收东西时说出位置，是最不花时间的练习方式。","前后左右通常要到四、五岁之后才稳定，不必急。"],"prep":{"场地":"客厅或房间，有桌子、椅子、箱子等可以藏东西的家具。","器材":"一个孩子喜欢的小玩偶或小车。","安全检查":"不把玩具藏在需要爬高、开抽屉或伸进缝隙才拿得到的地方。","大人位置":"大人蹲下与孩子同高，藏的时候让孩子看得见过程。"},"shots":[{"name":"藏起来","say":"我要把小熊藏起来喔——"},{"name":"问位置","say":"小熊在哪里？"},{"name":"示范说法","say":"在桌子上面。"},{"name":"换位置","say":"现在呢？在箱子里面。"},{"name":"换他藏","say":"换你藏，我来猜。"},{"name":"日常也说","say":"鞋子放在鞋柜下面。"}],"reactions":[{"if":"孩子只会用手指不会说","then":"他指对就先肯定，再由你把位置词说出来。指对代表他已经听懂了。"},{"if":"孩子把上面下面说反","then":"用身体演一次：把玩具举高说上面、放地上说下面，动作会比解释清楚。"},{"if":"孩子找不到玩具就着急","then":"降低难度，藏在很明显的地方，先让他成功几次。"}],"mistakes":["一次教太多位置词，上下里外前后一起上。","藏得太隐密，孩子的注意力全在找，没有在学词。","孩子说不出来就直接公布答案，没有给他二选一的机会。"],"down":"只做上面和下面两个词，并且藏的时候让孩子全程看着。","up":"说完整句「小熊在桌子的下面」，并加入旁边、中间、后面等较难的词。","progress":["听到位置词能不能正确把东西放对地方。","会不会自己说出位置词。","能不能说出完整句而不只是「上面」两个字。"],"outro":"先练上面下面，熟了再加里面外面。收东西的时候顺口说一句位置，孩子每天都在练。"}' AS JSON))
WHERE `id` = 'A153';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '任何可以数的东西'),
  `trains` = COALESCE(`trains`, '学数字词，也练一对一对应。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"生活中数东西：楼梯、饼干、玩具、手指。"},{"imageUrl":null,"instruction":"一个一个点着数（一对一对应）。"},{"imageUrl":null,"instruction":"数完说「一共三个」。"},{"imageUrl":null,"instruction":"从五以内开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '数三个'),
  `harder` = COALESCE(`harder`, '数十个以上，或数完说出总数。'),
  `tip` = COALESCE(`tip`, '数数不是背「1234」，是要能一个一个点着数——点一下说一个数字，这才是真的会数。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组六（数学能力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子会从一背到二十，不代表他会数数。真正的关键，是他能不能一个一个点着数。","principles":["很多孩子会背数字，但拿三颗糖给他，他数不出来。","因为背数字是语音记忆，数数是数量概念，两件事不一样。","真正的数数要做到一对一对应：点一个、说一个，不能跳也不能重复。","手指点到哪、嘴巴说到哪，这个同步是关键技巧。","数完要说出总数（一共三个），这叫基数概念，代表他懂最后一个数字代表全部。","很多孩子数得出来却说不出总数，那就还没真的懂。","从五以内开始，数量小才容易做到一对一对应。","生活中数东西比用教材有效，因为数量是真实的、有用途的。","数概念是日后所有数学学习的地基，急不得也跳不过。"],"prep":{"场地":"餐桌边、楼梯上或收玩具的地方。","器材":"饼干、积木、手指、楼梯——任何可以一个一个点的东西。","安全检查":"在楼梯上数数时，大人一定站在孩子下方一阶；不使用可吞入的小物给三岁以下孩子。","大人位置":"大人握着或轻扶孩子的手指，带着他一个一个点。"},"shots":[{"name":"摆出来","say":"我们来数饼干。"},{"name":"带着点","say":"一、二、三。"},{"name":"说出总数","say":"一共三个！"},{"name":"数楼梯","say":"一阶、两阶、三阶。"},{"name":"数手指","say":"数数看你有几根手指。"},{"name":"检查一对一","say":"（孩子跳着数）我们慢慢来，点一个说一个。"}],"reactions":[{"if":"孩子数得比东西多或少","then":"握着他的手带着点，速度放到很慢，让手和嘴同步。"},{"if":"孩子数完说不出总数","then":"你替他说：「一、二、三——一共三个。」多示范几次他就会跟上。"},{"if":"孩子只会背不会点","then":"减少到两三个东西，并且把它们分开摆，让每一个都很清楚。"}],"mistakes":["以为会背数字就是会数数，直接跳到十以上。","数得太快，手和嘴对不上，一对一对应练不到。","数完不说总数，孩子学不到基数概念。"],"down":"只数两三个，并且握着孩子的手带着点，每点一下停一下。","up":"数到十以上，或数完之后拿走一个再问「现在剩几个」，带入加减的前置概念。","progress":["点一个说一个，有没有对得上。","数完会不会自己说出总数。","能正确数到几个（先看准确度，再看数量）。"],"outro":"数数不是背一二三四，是要能一个一个点着数，而且数完说得出一共几个。从三个开始，慢慢来。"}' AS JSON))
WHERE `id` = 'A154';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学成对的概念词，词汇量成倍增加。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说一个词，让孩子说相反的：大→小、高→矮、快→慢。"},{"imageUrl":null,"instruction":"可以用身体演出来（站高高／蹲低低）。"},{"imageUrl":null,"instruction":"从最具体的开始。"},{"imageUrl":null,"instruction":"轮流出题。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '从两个选项中选'),
  `harder` = COALESCE(`harder`, '自己说出反义词。'),
  `tip` = COALESCE(`tip`, '成对学习效率最高——用身体演出来（大大／小小、快快／慢慢），孩子记得特别牢。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组六（形容词与概念词）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"教一个词只学到一个，教一对词等于学到两个——反义词是扩充词汇量最快的方法。","principles":["成对出现的概念词，孩子学起来比单独一个词快得多。","因为对比会让每一个词的意义更清楚：有大才知道什么是小。","这也是抽象思考的起点，孩子开始处理关系而不只是物品。","用身体演出来，抽象的词就有了身体记忆，记得更牢。","从最具体的开始：大小、高矮、快慢，这些看得见也做得出来。","再进阶到冷热、软硬这类要靠感觉的，最后才是多少、前后这类更抽象的。","轮流出题会让孩子从被动回答转成主动提取，难度提高一阶。","反义词在学龄期会直接出现在语文考题里，提早熟悉有帮助。","这个活动完全不需要教具，走路、等车都能玩。"],"prep":{"场地":"任何地方都可以，有空间能站高蹲低更好。","器材":"不需要任何东西；可以用两样大小差很多的物品辅助。","安全检查":"做「高／矮」「快／慢」的身体动作时，注意周围没有桌角与障碍物。","大人位置":"大人站在孩子对面，可以一起做出动作。"},"shots":[{"name":"出题","say":"我说大，你说——"},{"name":"孩子接","say":"（孩子说「小」）对！小。"},{"name":"用身体演","say":"高高——低低——"},{"name":"快慢","say":"快快跑——慢慢走——"},{"name":"二选一提示","say":"冷的相反是热还是大？"},{"name":"换他出题","say":"换你考我！"}],"reactions":[{"if":"孩子说不出相反词","then":"给两个选项让他选。选对了再由你把这一对词说一次。"},{"if":"孩子说出的是不相干的词","then":"用身体演一次给他看，动作会比解释有效。"},{"if":"孩子只想一直出题不想回答","then":"那就先让他出，他出题时其实也在提取词汇，一样有练到。"}],"mistakes":["一开始就用抽象的反义词（勤劳／懒惰），孩子抓不到。","只用嘴巴说不用身体演，词留不住。","孩子答错就说「不对」，让游戏变成考试。"],"down":"从两个选项中选，并且每一对都用身体做出来。","up":"加入较抽象的成对词（多／少、干净／脏、危险／安全），并要求造一个短句。","progress":["能不能从选项中选出正确的反义词。","会不会自己说出相反的词。","能处理到多抽象的词对。"],"outro":"从大小、高矮、快慢这种看得见的开始，用身体做出来。一次学一对，词汇量是成倍在长。"}' AS JSON))
WHERE `id` = 'A155';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '日常物品或图卡'),
  `trains` = COALESCE(`trains`, '把东西分成一类一类，练概念和词汇的组织。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把东西分类：吃的／玩的、水果／动物、穿的／用的。"},{"imageUrl":null,"instruction":"问「苹果和香蕉是什么？」（水果）。"},{"imageUrl":null,"instruction":"收玩具时顺便分类。"},{"imageUrl":null,"instruction":"慢慢加入更细的分类。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '分成两大类'),
  `harder` = COALESCE(`harder`, '分成三四类，或说出类别名称。'),
  `tip` = COALESCE(`tip`, '会分类的孩子，记单词也记得比较有条理——大脑喜欢有组织的东西。收纳整理时天天都能练。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组四（名词与生活词汇）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"苹果和香蕉是什么？——水果。能说出这个类别名称，代表孩子的脑袋开始把词整理成一格一格的抽屉了。","principles":["分类是把零散的词组织起来的能力，是认知与语言的交会点。","词汇如果只是一堆散的词，提取时会很慢也容易卡住。","分好类之后，孩子要用某个词时可以从类别里快速找出来。","能说出类别名称（水果、动物、交通工具）是更高一层的抽象能力。","先从功能最明显的两大类开始：吃的／玩的，差异大最好分。","再进到水果／动物、穿的／用的这类，最后才是更细的分类。","收玩具时顺便分类，让这件事有实际用途，孩子也更愿意收。","同一样东西可以属于不同类别（苹果是水果也是红色的），这是更难的一层。","分类能力和日后的阅读理解、写作组织直接相关。"],"prep":{"场地":"地板或大桌面，有空间把东西分成好几堆。","器材":"日常物品或图卡；玩具、水果、餐具都可以。","安全检查":"避免使用玻璃或易碎物品；三岁以下不使用可吞入的小物。","大人位置":"大人和孩子一起蹲坐在东西旁边，一样一样拿起来讨论。"},"shots":[{"name":"摆出一堆","say":"我们把这些东西分一分。"},{"name":"分两大类","say":"可以吃的放这边，可以玩的放这边。"},{"name":"说出类别名","say":"苹果和香蕉，是什么？水果。"},{"name":"换一组","say":"狗、猫、兔子——都是动物。"},{"name":"收玩具时分类","say":"积木放这箱，车车放这箱。"},{"name":"加一层","say":"水果里面，哪些是红色的？"}],"reactions":[{"if":"孩子分得跟你想的不一样","then":"先问他为什么这样分。只要说得出理由，那就是有效的分类。"},{"if":"孩子说不出类别名称","then":"你先说出来，让他多听几次；下次再问时给二选一。"},{"if":"孩子只想把东西排成一排不想分","then":"那就先陪他排，排好之后再问「这一排有什么一样的地方」。"}],"mistakes":["一开始就分四五类，孩子做不到就放弃。","坚持只有一种正确的分法，压掉孩子自己的思考。","只分不命名，孩子学不到类别词。"],"down":"只分两大类，而且两类差异极大（吃的／玩的），每一类先各放一样当范例。","up":"分三到四类，说出类别名称，并做到次分类（水果里的红色水果）。","progress":["能不能把东西分成正确的两类以上。","会不会说出类别的名称。","能不能说出自己这样分的理由。"],"outro":"收玩具的时候顺便分类，分完记得问一句「这些是什么？」。能说出类别名称，孩子的词汇就从一堆变成一格一格的抽屉。"}' AS JSON))
WHERE `id` = 'A156';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会说原因，回答「为什么」。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"从最熟悉的生活因果问起：「为什么要洗手？」"},{"imageUrl":null,"instruction":"示范回答「因为手脏脏」。"},{"imageUrl":null,"instruction":"答不出来就给两个选项让他选。"},{"imageUrl":null,"instruction":"日常多问几个为什么。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '二选一选出原因'),
  `harder` = COALESCE(`harder`, '自己说出「因为……」。'),
  `tip` = COALESCE(`tip`, '「为什么」是很难的问题——先从他熟悉的生活因果开始，答不出来给选项，别让他挫折。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十三（描述·解释与推理语言）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"为什么要洗手？——因为手脏脏。能说出原因，代表孩子开始会推理了。今天从最熟悉的生活因果问起。","principles":["因果关系是逻辑思考最基本的形式，也是语言中最重要的连接概念。","「为什么」的问题对孩子来说不容易，因为答案看不见、摸不到。","所以一定要从他最熟悉的生活事件问起：洗手、穿外套、关门。","这些事他每天做，因果链条短，比较容易连起来。","大人先示范完整的答法「因为手脏脏」，孩子才知道答案长什么样子。","答不出来就给两个选项，选择比自由回答容易得多。","会说「因为」的孩子，讲故事时才讲得出事情为什么会发生。","这也是学龄期阅读理解最常考的能力之一。","日常多问几个为什么，但一次一个，问太多会变成疲劳轰炸。"],"prep":{"场地":"生活场景中进行，洗手台、玄关、餐桌都可以。","器材":"不需要任何东西，用正在发生的事情当题目。","安全检查":"无特殊风险。避免用「为什么你又……」这种带责备的问法。","大人位置":"大人和孩子一起做那件事，边做边问。"},"shots":[{"name":"边做边问","say":"我们要洗手了——为什么要洗手呢？"},{"name":"先示范","say":"因为手脏脏。"},{"name":"换一题","say":"今天为什么要穿外套？"},{"name":"二选一","say":"因为很冷，还是因为很热？"},{"name":"孩子自己说","say":"（孩子说「因为很冷」）对，因为外面很冷。"},{"name":"反过来问","say":"那如果不穿外套会怎样？"}],"reactions":[{"if":"孩子答「不知道」","then":"立刻给两个选项。选对了再由你把完整句说一次。"},{"if":"孩子的答案不合逻辑","then":"不要否定。先接住他的想法，再说出你的版本让他听。"},{"if":"孩子被问烦了","then":"一天一两个就好。问太多会让孩子对「为什么」产生反感。"}],"mistakes":["问太抽象的为什么（为什么天空是蓝的），孩子没有经验可以连。","孩子答不出来就一直追问，变成压力。","用「为什么你又打翻了」这种责备句，孩子会关起来不回答。"],"down":"只用二选一的方式回答，并且每次都由大人把完整句说一次。","up":"反过来练「所以」：「外面很冷，所以我们要——」，并练习说两句以上的因果串连。","progress":["能不能从两个选项中选出合理的原因。","会不会自己说出「因为……」。","能不能处理到比较不那么具体的因果问题。"],"outro":"从他每天都做的事问起，答不出来就给两个选项。会说「因为」的孩子，以后才讲得出完整的故事。"}' AS JSON))
WHERE `id` = 'A157';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '儿歌或童谣'),
  `trains` = COALESCE(`trains`, '在重复的韵文中自然吸收词汇和句型。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选简单重复的儿歌，每天唱几遍。"},{"imageUrl":null,"instruction":"唱熟了故意停一个字，让他接。"},{"imageUrl":null,"instruction":"配上动作更容易记。"},{"imageUrl":null,"instruction":"同一首唱到滚瓜烂熟再换。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着唱一两个字'),
  `harder` = COALESCE(`harder`, '自己唱完一段，或接上停顿的地方。'),
  `tip` = COALESCE(`tip`, '重复是语言学习的好朋友——同一首儿歌唱一百遍，比一百首各唱一遍有效。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组三（声音与仿说）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"同一首儿歌唱一百遍，比一百首各唱一遍有效。今天教你一个小技巧——唱到一半，故意停住。","principles":["儿歌有强烈的节奏和押韵，这些结构会帮助记忆。","重复的句型让孩子在不知不觉中吸收语法，不用刻意教。","唱歌时的语速比说话慢，孩子有更多时间处理每一个字。","旋律和情绪连在一起，孩子愿意一再重复，练习量自然够。","唱熟之后故意停一个字让他接，叫做填空法，是最有效的引导技巧之一。","因为前面的旋律和句型已经把答案推到嘴边，孩子几乎不需要额外提示。","配上动作，把听觉、动作和语言绑在一起，记忆更稳固。","同一首唱到滚瓜烂熟再换，熟悉度比新鲜感更重要。","儿歌也是最早的音韵觉识练习，和日后的识字能力有关。"],"prep":{"场地":"任何地方，洗澡、车上、睡前都可以。","器材":"一首简单、重复性高的儿歌或童谣；不需要播放设备，大人唱更好。","安全检查":"无特殊风险。音量适中，不使用耳机播放给幼儿听。","大人位置":"大人面对孩子，脸和手都要让孩子看得见。"},"shots":[{"name":"一起唱","say":"（唱一首简单的儿歌，配上动作）"},{"name":"加上动作","say":"（每一句配一个固定动作）"},{"name":"唱熟了","say":"（同一首连续唱，剪辑呈现唱了很多天）"},{"name":"故意停住","say":"两只老虎，两只——"},{"name":"孩子接上","say":"（孩子接「老虎」）对！"},{"name":"停在不同位置","say":"跑得——快！"}],"reactions":[{"if":"孩子不接话","then":"停住之后等三到五秒，还不接就自己唱完，下次再试。不要催也不要追问。"},{"if":"孩子只会做动作不唱","then":"动作先出来是正常的，继续唱，声音会慢慢跟上。"},{"if":"孩子每天都要听同一首","then":"这是好事。重复正是他在学的证据，不要急着换新的。"}],"mistakes":["一直换新歌，每首都不熟，填空法就用不上。","停住之后马上自己接完，没有给孩子时间。","用播放器代替大人唱，少了嘴型和眼神的互动。"],"down":"不要求接词，孩子只要跟着做动作或发出一两个音就好。","up":"停在句中较难的位置，或让孩子自己完整唱完一段，再挑战改编歌词。","progress":["会不会跟着做动作。","停住时会不会接上词。","能不能自己唱完一整段。"],"outro":"同一首唱到滚瓜烂熟，然后唱到一半停住，眼睛看着他，等三秒。这个小停顿，比唱一百首新歌有用。"}' AS JSON))
WHERE `id` = 'A158';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要（可用玩具麦克风）'),
  `trains` = COALESCE(`trains`, '在问答中练表达，也练回答问题。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿个东西当麦克风，采访孩子。"},{"imageUrl":null,"instruction":"问简单的：「你叫什么名字？」「你几岁？」「你喜欢什么？」"},{"imageUrl":null,"instruction":"答完换他采访你。"},{"imageUrl":null,"instruction":"可以录下来一起听。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '回答一两个问题'),
  `harder` = COALESCE(`harder`, '回答开放式问题，或自己想问题问人。'),
  `tip` = COALESCE(`tip`, '录下来放给孩子听——听到自己会说话，是最好的鼓励。也可以录给远方的亲人听。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"拿个东西当麦克风，孩子立刻变得很愿意说话。今天我们做一场小小采访——而且最后一定要换他来问你。","principles":["问答是最基本的对话形式，孩子要先会回答，才谈得上聊天。","拿着麦克风会让孩子进入一个角色，心理压力比被大人问小很多。","从最简单、答案固定的问题开始：名字、年纪、喜欢什么。","这些问题他答得出来，成功经验会让他更愿意继续。","再慢慢加入开放式问题，那需要他自己组织内容，难度高一阶。","换他采访大人，是从回答转成发问，这是更高层次的语言使用。","会问问题的孩子，在学校和同侪互动时明显占优势。","录下来一起听，孩子听到自己的声音会很有成就感，也会更注意发音。","这个活动同时练到轮流、眼神接触和等待，是完整的对话练习。"],"prep":{"场地":"安静的角落，两人面对面坐着。","器材":"玩具麦克风，或用任何长形物品代替（卷起来的纸、汤匙）。","安全检查":"当麦克风的东西不可有尖端，也不可放进嘴里；不使用硬质细长物。","大人位置":"大人坐在孩子对面，视线同高，把麦克风递到孩子面前再发问。"},"shots":[{"name":"开场","say":"哈啰，我是记者，请问你叫什么名字？"},{"name":"简单问题","say":"你几岁呀？"},{"name":"喜欢什么","say":"你最喜欢什么？"},{"name":"开放式问题","say":"今天在学校做了什么？"},{"name":"换他采访","say":"换你当记者，你要问我什么？"},{"name":"一起回放","say":"我们来听听刚刚录的。"}],"reactions":[{"if":"孩子不回答只是笑","then":"先从他一定答得出来的问题开始，例如名字。成功一次之后就容易了。"},{"if":"孩子回答得很短","then":"用「然后呢」「还有呢」接下去，不要一直换新问题。"},{"if":"孩子不知道要问什么","then":"给他三个问题让他选一个来问，选择比自己想容易。"}],"mistakes":["一开始就问开放式问题，孩子答不出来就退缩。","孩子回答后立刻纠正发音或用词，采访的气氛就没了。","大人一直问，没有换孩子来问，少掉最重要的一半。"],"down":"只问三个固定答案的问题（名字、几岁、喜欢什么），并接受单词回答。","up":"问开放式问题并要求说两三句，或让孩子自己设计问题去采访家里其他人。","progress":["愿不愿意对着麦克风开口。","回答的长度有没有变长。","会不会自己想出问题来问人。"],"outro":"先问他答得出来的，再问需要想一想的。最后一定要换他来采访你——会问问题的孩子，才真的会聊天。"}' AS JSON))
WHERE `id` = 'A159';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '用游戏形式复习学过的词。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说类别接龙：「说出三种水果」「说出三种动物」。"},{"imageUrl":null,"instruction":"说特征猜东西：「圆圆的、红红的、可以吃」。"},{"imageUrl":null,"instruction":"比一比谁说得多。"},{"imageUrl":null,"instruction":"全家一起玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出一两个'),
  `harder` = COALESCE(`harder`, '说出五个以上，或自己出题给别人猜。'),
  `tip` = COALESCE(`tip`, '词汇要「用得出来」才算真的会——猜谜和接龙让孩子主动去搜寻脑袋里的词，比问「这是什么」有效。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组四～六（名词 · 动词 · 形容词）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"这是模组八的总复习。用比赛的方式把学过的词全部拿出来用一次——而且全家都可以一起玩。","principles":["复习不是重教，而是让孩子把已经学会的词主动提取出来。","主动提取比被动听讲更能巩固记忆，这是学习心理学上很稳定的结论。","用游戏和比赛的形式，孩子的动机会明显提高。","「说出三种水果」练的是从类别里找词，直接用到分类能力。","「圆圆的、红红的、可以吃」练的是从特征反推物品，难度更高。","这两种方向合起来，孩子的词汇网络就被双向走过一遍。","全家一起玩会有同侪效果，孩子听到别人说的词也在学。","比谁说得多要注意分寸，让孩子赢得到，不然会失去兴趣。","这个活动可以当成模组八的成果检核，看哪些词还没稳。"],"prep":{"场地":"客厅或餐桌，全家人围坐。","器材":"不需要任何东西；可以准备纸笔记录谁说了几个。","安全检查":"无特殊风险。注意比赛气氛，避免孩子因为输而受挫。","大人位置":"大人当主持人，出题并控制节奏，必要时放水。"},"shots":[{"name":"宣布规则","say":"词汇大挑战开始！说出三种水果——"},{"name":"类别接龙","say":"苹果、香蕉、葡萄！"},{"name":"换类别","say":"说出三种动物。"},{"name":"特征猜物","say":"圆圆的、红红的、可以吃——是什么？"},{"name":"换他出题","say":"换你出题考我们。"},{"name":"计分收尾","say":"今天冠军是——"}],"reactions":[{"if":"孩子说不出三个","then":"降到说出一个就好，或由大人先说一个当提示。"},{"if":"孩子输了不开心","then":"改成全家合作制：大家一起凑满十个词，不分输赢。"},{"if":"孩子重复说同一个词","then":"不指正，先接受，再把他说过的词复述一次帮他记住。"}],"mistakes":["题目出得太难，孩子一直答不出来就不玩了。","大人认真比赛把孩子比下去，孩子失去兴趣。","只玩类别接龙，没玩特征猜物，少掉一半的练习方向。"],"down":"一次只要求说出一个，并且从他最熟的类别（水果、动物）开始。","up":"要求说出五个以上，加入较抽象的类别（会飞的、圆形的、在厨房里的），并让孩子自己出题。","progress":["一个类别能说出几个词。","能不能从特征猜出物品。","会不会自己出题给别人猜。"],"outro":"这是模组八的总复习。玩的时候记得让孩子赢得到，输太多次他就不玩了。玩得开心，词才留得住。"}' AS JSON))
WHERE `id` = 'A160';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '别人问就回答，把「接话」变成习惯。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"从他答得出来的问题开始：「你几岁？」「午餐吃什么？」"},{"imageUrl":null,"instruction":"答了就热情回应。"},{"imageUrl":null,"instruction":"答不出来给两个选项：「吃面还是吃饭？」"},{"imageUrl":null,"instruction":"每天问几个小问题。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '从选项中选一个'),
  `harder` = COALESCE(`harder`, '开放式问题也能答。'),
  `tip` = COALESCE(`tip`, '问了没回应也别急——先给选项让他成功回答几次，建立「被问会答」的习惯。一个词的回答也算数。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子会说很多词，但别人问他话他就不理——这不是没礼貌，是「接话」这件事还没变成习惯。今天我们从最简单的问题开始练。","principles":["回答问题是对话最基本的单位，别人问、我答，一来一往才叫沟通。","很多孩子不是不会答，是还没养成「被问了就要回应」的反射。","所以一开始要从他百分之百答得出来的问题问起。","答得出来就会有成功经验，成功经验才会让他愿意继续答。","一开始就问难的，孩子答不出来，下次就更不想开口。","答不出来时给两个选项，是最好用的一招——选择比自由回答容易太多。","他答了就要热情回应，让他知道回答是有回馈的。","每天问几个小问题，分散在生活里，比一次问二十个有效。","这项能力直接影响他在幼儿园能不能回应老师和同学。"],"prep":{"场地":"日常场景就好：餐桌、车上、散步路上。","器材":"不需要任何东西。","安全检查":"无特殊风险。不在孩子情绪不好或专心做别的事时连续发问。","大人位置":"大人蹲下或坐下与孩子同高，问完看着他，安静等待。"},"shots":[{"name":"从简单的问起","say":"你几岁呀？"},{"name":"答了热情回应","say":"（孩子回答）哇，三岁了！好棒。"},{"name":"再问一题","say":"今天午餐吃什么？"},{"name":"答不出来","say":"（孩子愣住不答）"},{"name":"给两个选项","say":"吃面还是吃饭？"},{"name":"每天几个就好","say":"（快剪：早上、放学、睡前各问一题）"}],"reactions":[{"if":"孩子完全不回答","then":"先降到二选一，而且两个选项都要是他喜欢的。答对了立刻给热烈回应。"},{"if":"孩子答得很小声或含糊","then":"不要求重说，先接住内容：「哦，吃面呀。」内容被听懂比说清楚更重要。"},{"if":"孩子答非所问","then":"先接住他说的，再把原本的问题用更简单的方式问一次。"}],"mistakes":["一口气问太多问题，变成审问。","孩子一停顿就替他回答，他就没有机会开口。","一开始就问「你今天在学校做了什么」这种开放式大题。"],"down":"只用二选一的问题，而且选项就在眼前看得到。","up":"改问开放式问题（你今天觉得怎么样），并要求答两句以上。","progress":["被问到时会不会有回应（点头、出声都算）。","能不能回答二选一的问题。","开放式问题答得出来了吗。"],"outro":"从他答得出来的问起，答不出来就给两个选项。每天问几个小问题就好——接话是习惯，不是本事。"}' AS JSON))
WHERE `id` = 'A161';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '答完会反问对方，让对话变成双向。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"问他「你喜欢什么水果？」"},{"imageUrl":null,"instruction":"他答完，教他问「你呢？」"},{"imageUrl":null,"instruction":"你认真回答，让他知道问了有收获。"},{"imageUrl":null,"instruction":"把「你呢？」练成口头禅。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着说「你呢」'),
  `harder` = COALESCE(`harder`, '主动问完整的问题。'),
  `tip` = COALESCE(`tip`, '「你呢？」这两个字，是让对话变双向最省力的一招——只答不问的聊天像单行道，会反问就通了。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子答完就没了，对话马上断掉。今天教他两个字，让对话自己转回来——「你呢？」","principles":["会回答只是对话的一半，会反问才让对话变成双向。","很多孩子答完就结束，不是不想聊，是不知道该换他问。","「你呢」是最短、最好学的反问句，几乎不需要组织语言。","它可以接在任何回答后面，适用范围非常广。","孩子问了之后，大人一定要认真回答，让他知道问了有收获。","如果反问没有得到回应，这个习惯就建立不起来。","把「你呢」练成口头禅，孩子在同侪互动时会明显占优势。","因为会反问的人，别人跟他聊天比较不累。","熟了之后再进阶到完整的反问句，「那你喜欢什么？」"],"prep":{"场地":"餐桌或睡前聊天时最自然。","器材":"不需要任何东西。","安全检查":"无特殊风险。不在孩子不想说话时强迫他反问。","大人位置":"大人和孩子面对面，问完等他答，答完再提示反问。"},"shots":[{"name":"先问他","say":"你喜欢什么水果？"},{"name":"他回答","say":"（孩子说「香蕉」）香蕉呀，很好吃。"},{"name":"教反问","say":"然后你可以问我——你呢？"},{"name":"他问了","say":"（孩子说「你呢」）我喜欢草莓，酸酸甜甜的。"},{"name":"让他有收获","say":"（继续聊草莓）你要不要也吃吃看？"},{"name":"练成口头禅","say":"（快剪几个场景，孩子每次都接「你呢」）"}],"reactions":[{"if":"孩子答完就跑掉","then":"先不追。下次在他还坐着的时候提示一次就好，不要变成规定。"},{"if":"孩子只会重复「你呢」不懂意思","then":"那也很好用。先让他习惯这个节奏，意思会在反复中慢慢懂。"},{"if":"孩子反问了但大人随便敷衍","then":"这是最伤的。请认真回答，而且答得有趣一点。"}],"mistakes":["孩子问了，大人敷衍两个字带过——反问就失去意义。","要求孩子每次都要反问，变成规矩，孩子会反感。","一开始就要求完整的反问句，难度太高。"],"down":"只练「你呢」两个字，并且由大人先示范说一次再请他跟着说。","up":"练完整的反问句：「那你最喜欢哪一个？」并在不同话题上自由反问。","progress":["会不会在回答后说「你呢」。","有没有从提示后才说，变成自己主动说。","能不能问出完整的反问句。"],"outro":"教孩子两个字：你呢。他问了，你一定要认真回答——问了有收获，他才会一直问下去。"}' AS JSON))
WHERE `id` = 'A162';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '回答后再加一句，让话题接得下去。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"他答「去公园了」，引导他加一句「玩了滑梯，好好玩」。"},{"imageUrl":null,"instruction":"教三种加法：加感受、加原因、加细节。"},{"imageUrl":null,"instruction":"问一句「还有呢？」就能引出更多。"},{"imageUrl":null,"instruction":"大人也示范丰富的回答。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '提示下加一句'),
  `harder` = COALESCE(`harder`, '习惯性地答两三句。'),
  `tip` = COALESCE(`tip`, '多出来的那一句，常常就是下一个话题——回答从一句变两句，对话就从问答变成聊天了。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「今天去哪里了？」「公园。」——然后就没了。今天教你三个加法，让孩子的回答从一个词变成一段话。","principles":["只答一个词，对话就接不下去，因为对方没有东西可以回应。","回答后再加一句，话题才有材料可以往下走。","加什么有三个方向：加感受、加原因、加细节，这三种最好教。","加感受是「好好玩」，加原因是「因为溜滑梯很高」，加细节是「还遇到小狗」。","有方向可循，孩子就不会卡在「还要说什么」。","问一句「还有呢」是最简单的引导，几乎不需要技巧。","大人自己也要示范丰富的回答，孩子是照着你的样子学的。","如果大人回答都只有两个字，孩子不会突然变得很会讲。","这项能力是叙事的基础，讲得出细节才讲得出故事。"],"prep":{"场地":"放学路上、餐桌、睡前都可以。","器材":"不需要任何东西。","安全检查":"无特殊风险。不在孩子累了或情绪低落时追问细节。","大人位置":"大人和孩子并肩或面对面，语气是聊天不是查勤。"},"shots":[{"name":"只有一个词","say":"今天去哪里了？（孩子答「公园」）"},{"name":"加感受","say":"公园呀——好玩吗？「玩了滑梯，好好玩！」"},{"name":"加原因","say":"为什么好玩？「因为滑梯好高。」"},{"name":"加细节","say":"还有呢？「还看到一只狗。」"},{"name":"万用句「还有呢」","say":"还有呢？"},{"name":"大人先示范","say":"我今天去了超市，买了西瓜，因为天气好热。"}],"reactions":[{"if":"孩子怎么问都只答一个词","then":"改由大人示范。你连讲三天丰富的回答，他会开始模仿。"},{"if":"孩子加的那句跟主题无关","then":"先接受，再把话题轻轻带回来：「那我们再说说滑梯。」"},{"if":"孩子被问到不耐烦","then":"停。改成大人分享自己的一天，让他当听众几天再说。"}],"mistakes":["连续追问变成查勤，孩子会关起来。","大人自己回答都只有两个字，却要求孩子讲很多。","孩子加了一句就急着纠正内容或用词。"],"down":"只练一种加法（加感受），并由大人给半句让他接完。","up":"不用提示就能自己答两三句，并在不同话题上都做得到。","progress":["提示之后会不会加一句。","有没有开始不用提示就多说。","加的内容有没有从感受扩到原因和细节。"],"outro":"教他三个加法：加感受、加原因、加细节。不知道怎么引导的时候，问一句「还有呢」就够了。"}' AS JSON))
WHERE `id` = 'A163';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个球'),
  `trains` = COALESCE(`trains`, '把「轮流说话」变得看得见。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"规则：拿着球的人才能说话。"},{"imageUrl":null,"instruction":"说完一句就把球传给对方。"},{"imageUrl":null,"instruction":"球在对方手上时要听、不插话。"},{"imageUrl":null,"instruction":"故意一直抱着球说，让他发现不对劲。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着球的节奏说和听'),
  `harder` = COALESCE(`harder`, '不用球也保持来回。'),
  `tip` = COALESCE(`tip`, '「球在谁手上谁说话」——抽象的轮流规则一下就看懂了。爱插话的孩子玩几次就会改善。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组七（维持互动·对话与延续）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子讲起来停不下来，或是一直插话打断别人？今天用一颗球，把看不见的「轮流」变成看得见的东西。","principles":["轮流是对话的骨架，你一句、我一句，少了它对话就垮了。","但轮流是抽象的，孩子看不见也摸不到，所以很难学。","用一颗球代表「现在换谁说」，抽象的规则就变成具体的动作。","拿着球才能说话，球不在手上就是听的时候。","这同时练到两件事：说的时候要说，听的时候要忍住不插话。","忍住不插话对冲动型的孩子特别难，有球在手会容易一点。","大人故意一直抱着球不放，孩子会立刻感觉到不对劲。","让他亲身体验被剥夺发言权的感觉，比讲道理有效得多。","练熟之后把球拿掉，节奏通常还会留着一段时间。"],"prep":{"场地":"客厅地板或沙发上，两人面对面坐着。","器材":"一颗软球或布偶，好抓好传、掉了不会痛。","安全检查":"使用软质球，不使用硬球或弹力过强的球；坐着传，不站起来抛接。","大人位置":"大人坐在孩子对面，距离一个手臂可以传到球。"},"shots":[{"name":"说明规则","say":"拿着球的人才可以说话喔。"},{"name":"说一句传一次","say":"我今天很开心。（把球传过去）"},{"name":"换他说","say":"（孩子拿着球说话）"},{"name":"球不在手上要听","say":"（大人手上没球，安静点头听）"},{"name":"故意一直抱着球","say":"（大人一直讲不传球）"},{"name":"拿掉球","say":"这次我们不用球，也要记得换人说。"}],"reactions":[{"if":"孩子拿到球不放","then":"不抢。轻轻提醒「说完要传给我喔」，并用手掌摊开等待。"},{"if":"孩子没球时一直插话","then":"先不说话，指一指球在谁手上。手势提示比口头制止有效。"},{"if":"孩子觉得规则太麻烦","then":"改成短回合：一人说一句就好，三个来回就结束，先让他觉得好玩。"}],"mistakes":["大人自己一直讲不传球，示范的就是错的。","用球来惩罚孩子（不给球当处罚），游戏会变成控制。","一开始玩太久，孩子失去耐性。"],"down":"只做三个来回就结束，每人一次只说一句话。","up":"拿掉球，只靠眼神和停顿维持轮流，并延长到六个来回以上。","progress":["会不会说完就把球传出去。","球不在手上时能不能忍住不插话。","不用球的时候还保得住轮流吗。"],"outro":"轮流是看不见的，用一颗球就看见了。说完把球传出去，球不在手上就是听的时候——大人也要遵守。"}' AS JSON))
WHERE `id` = 'A164';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '顺着对方说的内容回应，不跳到别的事。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"你说「我今天看到一只小狗」。"},{"imageUrl":null,"instruction":"引导他接小狗的话（什么颜色？我也想看）。"},{"imageUrl":null,"instruction":"跳题了温和拉回「我们在说小狗呀」。"},{"imageUrl":null,"instruction":"玩「话题接力」：围着一个话题每人说一句。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '熟悉的话题接一句'),
  `harder` = COALESCE(`harder`, '不熟的话题也能接两三轮。'),
  `tip` = COALESCE(`tip`, '接得住别人的话，才叫真的在聊天。孩子老是跳回自己有兴趣的事，可以温和约定「先聊完这个，再聊你的」。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组七（维持互动·对话与延续）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"你说小狗，他说恐龙——话题一直跳，聊天就散了。今天练一件事：顺着对方说的接下去。","principles":["维持同一个话题，是对话能不能延续的关键。","孩子常常跳题，因为他脑中浮现什么就说什么。","要接住话题，他必须先真的听进对方说了什么。","所以这个练习同时在练倾听，不只是在练说话。","跳题时温和地拉回来，比责备有效：「我们在说小狗呀。」","不要用「你怎么又乱讲」这种说法，孩子会不敢开口。","从他熟悉又有兴趣的话题开始，接得住的机会最高。","话题接力（围着一个主题每人说一句）是很好的结构化练习。","能维持三个来回以上的话题，社交互动就会顺很多。"],"prep":{"场地":"安静一点的地方，两人面对面，减少环境干扰。","器材":"不需要任何东西。","安全检查":"无特殊风险。不用责备的口气纠正跳题。","大人位置":"大人面对孩子，眼神接触，语速放慢。"},"shots":[{"name":"起一个话题","say":"我今天看到一只小狗。"},{"name":"引导他接","say":"（孩子没接）它是白色的，你猜它在做什么？"},{"name":"他接住了","say":"（孩子说「我也想看」）对呀，下次带你去。"},{"name":"跳题了","say":"（孩子突然说恐龙）"},{"name":"温和拉回","say":"恐龙等一下说，我们先说小狗。"},{"name":"话题接力","say":"我们来玩接力，每个人说一句关于小狗的话。"}],"reactions":[{"if":"孩子完全接不上","then":"把话题换成他最有兴趣的东西，再多给一点内容让他好接。"},{"if":"孩子一直跳回自己的主题","then":"先让他说完他的，再邀请他回来：「说完恐龙，我们回来说小狗好不好？」"},{"if":"孩子只回「嗯」","then":"改用问句给他方向：「你觉得它是想回家还是在找人？」"}],"mistakes":["用责备的语气纠正跳题，孩子会不敢再开口。","话题选得太冷门，孩子根本没有东西可以接。","大人自己也一直换话题，示范就是错的。"],"down":"只要求接一句，而且话题是他最熟最爱的东西。","up":"在不熟悉的话题上也能来回两三轮，并自己把话题延伸下去。","progress":["会不会针对对方说的内容回应。","同一个话题能维持几个来回。","跳题之后经提醒能不能回来。"],"outro":"跳题的时候不要骂，温和地说一句「我们在说小狗呀」就好。接得住话题，聊天才接得下去。"}' AS JSON))
WHERE `id` = 'A165';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会用点头、嗯嗯、看着对方表示在听。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"示范听人说话的样子：点头、说「嗯嗯」「真的呀」。"},{"imageUrl":null,"instruction":"你说话时请他练习「听的样子」。"},{"imageUrl":null,"instruction":"对比实验：先不理他、再认真听，问他哪种舒服。"},{"imageUrl":null,"instruction":"教他「跟谁说话就转向谁」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '会点头说嗯嗯'),
  `harder` = COALESCE(`harder`, '自然地表现出在听。'),
  `tip` = COALESCE(`tip`, '孩子说话时你先做最好的听众（放下手机、点头回应）——「被听」的感觉，他会学着还给别人。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组七（维持互动·对话与延续）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"听人说话的时候，要让对方知道你在听。点头、嗯嗯、看着对方——这些不是礼貌，这是让别人愿意继续跟你说话的技术。","principles":["倾听不只是脑袋在听，还要让对方看得出来你在听。","这些看得见的信号叫做倾听反应：点头、嗯嗯、看着对方。","没有这些信号，说话的人会以为你没兴趣，就不想说了。","很多孩子其实有在听，但因为没有表现出来，常被误会成不理人。","「跟谁说话就转向谁」是最简单也最有效的一条。","做一个对比实验：先不理他、再认真听，让他亲身感受差别。","亲身体验比讲一百次道理有用，因为那个不舒服的感觉他记得住。","这项能力对交朋友影响很大，会听的孩子比较受欢迎。","同时也在练社交注意力，把注意力放在人身上而不是东西上。"],"prep":{"场地":"安静的地方，两人面对面坐着，没有电视和玩具干扰。","器材":"不需要任何东西。","安全检查":"做「先不理他」的对比实验时时间要很短（十秒内）并立刻说明，避免孩子真的受伤。","大人位置":"大人坐在孩子正对面，身体转向他，眼神接触。"},"shots":[{"name":"示范听的样子","say":"（孩子说话，大人点头、嗯嗯、看着他）"},{"name":"拆解三个动作","say":"点头、说嗯嗯、看着对方。"},{"name":"换他练","say":"现在换我说，你来练习听的样子。"},{"name":"对比实验（不理）","say":"（大人低头看手机，孩子说话没回应，仅十秒）"},{"name":"对比实验（认真听）","say":"（大人放下手机，转身认真听）"},{"name":"问他感觉","say":"刚刚哪一种比较舒服？"}],"reactions":[{"if":"孩子做得太夸张一直点头","then":"不用纠正。夸张是学习初期的正常现象，熟了自然会收敛。"},{"if":"孩子做不到眼神接触","then":"改成看对方的鼻子或嘴巴，一样有效，不要强迫对视。"},{"if":"孩子在对比实验中真的难过了","then":"立刻停下来抱抱他，明确说「刚刚是演的，妈妈一直都在听」。"}],"mistakes":["对比实验做太久或做太真，孩子会真的受伤。","要求孩子听，但大人自己滑手机。","强迫孩子看着眼睛，对部分孩子来说压力很大。"],"down":"只练一个动作：跟谁说话就把身体转向谁。","up":"加上口语回应（真的吗、后来呢），让倾听从动作升级到内容。","progress":["听人说话时会不会转向对方。","有没有出现点头或嗯嗯这类回应。","别人说话时能不能不打断。"],"outro":"点头、嗯嗯、看着对方——这三件事让别人愿意继续跟他说话。还有一条最重要：大人自己要先做到。"}' AS JSON))
WHERE `id` = 'A166';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '回想并说出今天发生的事，是最实用的叙事练习。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"睡前问「今天做了什么？」"},{"imageUrl":null,"instruction":"答不出来给线索：「早上我们去了哪里？」"},{"imageUrl":null,"instruction":"引导用「先……然后……最后……」。"},{"imageUrl":null,"instruction":"大人也分享自己的一天。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出一件事'),
  `harder` = COALESCE(`harder`, '按顺序说出三件事。'),
  `tip` = COALESCE(`tip`, '「今天怎么样？」太抽象，孩子答不出来——问具体一点：「今天最好玩的是什么？」「谁跟你一起玩？」'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十二（叙事与复述）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「今天做了什么？」「不知道。」——不是他不记得，是他不知道从哪里开始说。今天教你怎么给线索。","principles":["说出今天发生的事，是最实用也最常被要求的叙事能力。","它牵涉到三件事：回想、挑选、按顺序说出来。","孩子说不出来，通常卡在回想这一步，因为范围太大了。","给线索就是帮他缩小范围：「早上我们去了哪里？」","有了起点，后面的事情就比较容易一件一件带出来。","用「先……然后……最后……」这三个词，顺序就有了骨架。","这个骨架日后写作文、报告事情都用得上。","大人也分享自己的一天，示范一个完整的版本给他听。","固定在睡前做，变成仪式，孩子会开始预期并且事先准备。"],"prep":{"场地":"睡前的床边，灯光调暗，环境安静。","器材":"不需要任何东西。","安全检查":"无特殊风险。孩子不想说就不勉强，改由大人分享。","大人位置":"大人坐或躺在孩子旁边，不打开手机。"},"shots":[{"name":"睡前开场","say":"今天做了什么呀？"},{"name":"他说不知道","say":"（孩子摇头说不知道）"},{"name":"给线索","say":"早上我们先去了哪里？"},{"name":"串起顺序","say":"先去了公园，然后呢？最后呢？"},{"name":"大人也分享","say":"我今天先上班，然后去买菜，最后回家煮饭。"},{"name":"变成仪式","say":"（快剪几个夜晚，同一个床边场景）"}],"reactions":[{"if":"孩子说不知道","then":"给具体线索，从最早的时间点问起，一段一段往后带。"},{"if":"孩子只说一件事","then":"就接受这一件。问「还有呢」一次，没有就到此为止，不要逼。"},{"if":"孩子顺序讲颠倒","then":"不纠正。用「所以是先……再……对吗？」把顺序复述一次即可。"}],"mistakes":["问题太大（今天怎么样），孩子无从答起。","孩子说了之后开始追问细节或检讨，睡前分享变成审问。","大人自己边听边滑手机，孩子就不想说了。"],"down":"只问一个时段（放学后做了什么），并由大人给两个选项让他选。","up":"按顺序说出三件事以上，并加上感受和原因。","progress":["有线索时能不能说出一件事。","会不会自己用「先、然后、最后」。","一次能说出几件事。"],"outro":"他说不知道的时候，不是忘了，是范围太大。给他一个线索：「早上我们先去了哪里？」然后用先、然后、最后串起来。"}' AS JSON))
WHERE `id` = 'A167';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '三张有先后顺序的图（自己画或用绘本）'),
  `trains` = COALESCE(`trains`, '按开始、经过、结果讲一段故事。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把三张图打乱，让孩子排出正确顺序。"},{"imageUrl":null,"instruction":"再照着顺序说一遍。"},{"imageUrl":null,"instruction":"大人先完整示范一次。"},{"imageUrl":null,"instruction":"一张图说一句就够。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每张图说一句'),
  `harder` = COALESCE(`harder`, '用连接词串成一段完整的故事。'),
  `tip` = COALESCE(`tip`, '故事有「开始—经过—结果」的骨架，孩子讲事情才不会东一句西一句。自己画三张简笔图就能玩。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十二（叙事与复述）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"讲故事有个骨架：开始、经过、结果。今天用三张图把这个骨架具体化，孩子一看就懂。","principles":["故事最基本的结构就是三段：开始、经过、结果。","把这三段变成三张图，抽象的结构就看得见、摸得到。","先请孩子排顺序，是在练因果与时间的先后判断。","排对了才代表他理解事件之间的关系，不只是看图说话。","排好之后再照着说一遍，图就变成了他的提词卡。","一张图说一句就够，目标是完整，不是精彩。","大人要先完整示范一次，孩子才知道成品长什么样。","熟了之后用连接词串起来，故事就从三句变成一段。","这个三段结构会一路用到小学的看图作文。"],"prep":{"场地":"桌面或地板，三张图并排摊开的空间。","器材":"三张有明确先后顺序的图（自己画的简笔画，或从绘本影印裁开）。","安全检查":"使用圆角纸卡或护贝，避免纸缘割手；剪裁工作由大人完成。","大人位置":"大人坐在孩子旁边，图放在孩子正前方。"},"shots":[{"name":"打乱三张图","say":"这三张图的顺序乱掉了，你帮我排排看。"},{"name":"孩子排序","say":"（孩子移动图卡）"},{"name":"大人先示范","say":"小熊肚子饿了，他去找东西吃，最后吃到蜂蜜。"},{"name":"换他说","say":"换你说一次。"},{"name":"一张一句就好","say":"（孩子每张说一句）"},{"name":"串起来","say":"一开始……后来……最后……"}],"reactions":[{"if":"孩子排错顺序","then":"不要直接改。问他「为什么这张排在前面？」听他的理由，再一起看图找线索。"},{"if":"孩子只说单词不说句","then":"先接受，由你把他的词扩成句子说一次，让他听见目标的样子。"},{"if":"孩子跳过中间那张","then":"把中间那张单独拿出来问：「这里发生了什么事？」补上经过。"}],"mistakes":["图片选得太复杂，孩子看不出先后关系。","孩子排错就直接帮他排好，少掉最有价值的思考过程。","要求故事讲得精彩，孩子压力太大。"],"down":"只用两张图（前和后），并由大人先排好，孩子只负责说。","up":"增加到五张图，并要求用连接词串成一段完整流畅的故事。","progress":["能不能排出正确顺序。","会不会每张图说出一句话。","有没有开始使用连接词。"],"outro":"故事就是三段：开始、经过、结果。一张图说一句就够了，先做到完整，再谈精彩。"}' AS JSON))
WHERE `id` = 'A168';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本或短故事'),
  `trains` = COALESCE(`trains`, '听完故事用自己的话讲一遍，练记忆和组织。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"讲一个短短的故事。"},{"imageUrl":null,"instruction":"问「刚才的故事在说什么？」"},{"imageUrl":null,"instruction":"让他用自己的话讲一遍。"},{"imageUrl":null,"instruction":"讲不完整就问引导问题（后来呢？）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '回答几个问题'),
  `harder` = COALESCE(`harder`, '完整复述整个故事。'),
  `tip` = COALESCE(`tip`, '复述比背诵有价值——用自己的话说出来，代表他真的懂了。讲给没听过的人（爸爸、爷爷）最有动力。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十二（叙事与复述）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"听完一个故事，能不能用自己的话讲一遍？这一件事，同时练了记忆、理解和组织——是所有学习的基本功。","principles":["复述不是背诵，是听懂之后用自己的话重新组织。","所以它同时考验三件事：记得住、听得懂、说得出来。","故事要短，一开始三到四句就好，太长孩子记不住。","记不住就会挫折，挫折了就不想再听故事。","讲不完整时用引导问题帮他：「后来呢？」「谁来了？」","引导问题是鹰架，等他熟了再慢慢拿掉。","孩子讲的版本会跟原本不一样，这完全没关系。","只要主要事件和顺序对了，用词不同反而代表他真的懂了。","这项能力直接对应到学校的阅读理解与口头报告。"],"prep":{"场地":"安静的地方，两人并肩坐着看同一本书。","器材":"一本短绘本，或一个三到四句的自编小故事。","安全检查":"无特殊风险。故事内容避免惊吓或悲伤情节，睡前尤其注意。","大人位置":"大人拿着书，讲完后把书合上再请孩子说。"},"shots":[{"name":"讲一个短故事","say":"（讲一个三四句的小故事）"},{"name":"合上书","say":"刚才的故事在说什么？"},{"name":"孩子复述","say":"（孩子用自己的话讲）"},{"name":"卡住了","say":"后来呢？谁来了？"},{"name":"用词不一样没关系","say":"（孩子说法不同，大人点头接受）"},{"name":"再讲给别人听","say":"等一下讲给爸爸听好不好？"}],"reactions":[{"if":"孩子几乎说不出来","then":"故事再缩短到两三句，并在讲的时候加上动作和声音，帮助他记住。"},{"if":"孩子只记得最后一段","then":"正常。用「一开始呢？」把他带回故事开头，一段一段补。"},{"if":"孩子逐字背诵原文","then":"也可以，但可以问他「那小熊为什么要去？」引导他用理解而不只是记忆。"}],"mistakes":["故事太长，孩子记不住就放弃。","孩子用词不同就纠正，复述变成背书。","一边翻着书一边问，孩子只是在念不是在回想。"],"down":"不要求完整复述，只回答三个引导问题（谁、做什么、后来怎样）。","up":"复述较长的故事，并说出角色的想法或故事的道理。","progress":["能不能回答关于故事的问题。","能说出几个主要事件。","顺序对不对、能不能讲成一段。"],"outro":"故事要短，讲完先把书合上。他讲的版本跟原本不一样很好——用自己的话讲得出来，才是真的听懂了。"}' AS JSON))
WHERE `id` = 'A169';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本'),
  `trains` = COALESCE(`trains`, '猜故事接下来的发展，练推理和想象。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"读到一半停下来问「接下来会怎样？」"},{"imageUrl":null,"instruction":"让孩子猜。"},{"imageUrl":null,"instruction":"翻页验证。"},{"imageUrl":null,"instruction":"猜错了也很好玩。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '从两个可能中选'),
  `harder` = COALESCE(`harder`, '自己想出可能的发展并说原因。'),
  `tip` = COALESCE(`tip`, '共读时多停下来问一句，孩子会听得更专心——比一路念到底效果好很多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十三（描述·解释与推理语言）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"读绘本读到一半，先别翻页。问他一句「接下来会怎样？」——这一句，练的是推理。","principles":["预测故事发展，需要孩子整合已知讯息再往前推一步。","这是推理能力最早的形式，也是阅读理解的核心。","孩子必须先听懂前面发生了什么，才猜得出后面。","所以猜测本身就是理解程度的检查。","翻页验证让这件事有了结果，孩子会想知道自己猜对没有。","猜错了完全没关系，甚至更好玩，重点是他有在想。","如果因为猜错被笑或被纠正，孩子下次就不敢猜了。","猜不出来就给两个可能让他选，选择永远是最好的降阶。","进阶版是猜完还要说原因，那就练到因果推理了。"],"prep":{"场地":"沙发或床边，光线足够看清楚绘本。","器材":"一本孩子没看过的绘本，情节有明显转折的最好。","安全检查":"无特殊风险。避免情节惊吓的绘本，尤其是睡前阅读。","大人位置":"大人拿书，读到转折处停下来，眼睛看向孩子。"},"shots":[{"name":"读到一半","say":"（读绘本，读到转折处）"},{"name":"停下来问","say":"接下来会怎样？"},{"name":"孩子猜","say":"（孩子说出他的猜测）"},{"name":"翻页验证","say":"我们来看看——"},{"name":"猜错也很好","say":"哈哈，不一样耶！你想的那个也很好玩。"},{"name":"给两个可能","say":"你觉得他会回家，还是继续找？"}],"reactions":[{"if":"孩子猜不出来","then":"给两个可能让他选，选完问一句「为什么？」就够了。"},{"if":"孩子的猜测天马行空","then":"接受并且觉得有趣。想象力和推理可以并存，不必急着拉回现实。"},{"if":"孩子只想快点翻页","then":"那就少停几次。一本书停一两次就好，不要每一页都问。"}],"mistakes":["每一页都停下来问，阅读的乐趣被打断。","猜错时说「不对」，孩子下次就不敢猜。","大人自己先把答案讲出来，剥夺了他思考的机会。"],"down":"从两个可能中选一个，不要求说原因。","up":"自己说出可能的发展并说明原因：「我猜他会回家，因为天黑了。」","progress":["愿不愿意说出猜测。","猜测跟前面的情节有没有关系。","能不能说出猜测的理由。"],"outro":"读到一半停下来，问一句「接下来会怎样」。猜错了也很好玩——重点不是猜对，是他有在想。"}' AS JSON))
WHERE `id` = 'A170';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本或自编故事'),
  `trains` = COALESCE(`trains`, '自己想出故事的结尾，练想象和组织。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"讲一个故事，讲到一半停住。"},{"imageUrl":null,"instruction":"让孩子编出结尾。"},{"imageUrl":null,"instruction":"没有标准答案，合理就好。"},{"imageUrl":null,"instruction":"编完请他讲给家人听。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '从两个结尾中选一个'),
  `harder` = COALESCE(`harder`, '自己完整编出来。'),
  `tip` = COALESCE(`tip`, '孩子编的结尾可能很天马行空——别急着说「不对」，先听完再一起聊。想象力是要被接住才长得出来的。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十二（叙事与复述）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"讲故事讲到一半，停住，然后说：「后面你来编。」——这是想象力和组织能力一起上场的时刻。","principles":["编结尾比复述难，因为没有现成的内容可以拿。","孩子必须自己产出内容，同时还要跟前面接得起来。","这就是创作最基本的形式：在限制条件下想出新东西。","没有标准答案，只要合理就好，这一点一定要先讲清楚。","如果孩子担心答错，他就不敢编，创造力会先关机。","编不出来时给两个结尾让他选，一样是最好的降阶方式。","编完请他讲给家人听，重复叙述会让内容变得更完整。","而且被认真听完，是孩子愿意继续创作最大的动力。","这项能力日后直接对应到写作与问题解决。"],"prep":{"场地":"安静舒服的地方，睡前或周末下午都合适。","器材":"一本绘本，或大人自编的一个短故事。","安全检查":"无特殊风险。不评价孩子编的内容好不好，只回应有趣的地方。","大人位置":"大人讲故事，讲到高潮处停住，把发言权交出去。"},"shots":[{"name":"讲到一半停住","say":"小熊走到河边，河上没有桥……"},{"name":"交给他","say":"后面你来编。"},{"name":"孩子编","say":"（孩子开始讲自己的版本）"},{"name":"没有标准答案","say":"（大人点头听，不打断也不纠正）"},{"name":"编不出来","say":"他可以游过去，还是找一根大木头？"},{"name":"讲给家人听","say":"等一下讲给爸爸听好不好？"}],"reactions":[{"if":"孩子说不知道","then":"给两个结尾让他选，选完问一句「然后呢？」把他往下带一步。"},{"if":"孩子编的内容不合逻辑","then":"不纠正。可以用好奇的方式问：「哇，他怎么办到的？」让他自己补。"},{"if":"孩子编得很短","then":"问「然后小熊心情怎么样？」用感受和细节把结尾撑长。"}],"mistakes":["评价孩子的故事好不好，创作马上变成考试。","大人忍不住接着讲下去，把发言权拿回来。","停的位置不对（停在没有悬念的地方），孩子没有东西可以接。"],"down":"从两个现成的结尾中选一个，并说出为什么选它。","up":"编出完整的结尾并说给不同的人听，或替同一个故事编两个不同的结尾。","progress":["愿不愿意开口编。","编出来的内容跟前面接不接得起来。","结尾有没有从一句话变成一小段。"],"outro":"记得先说清楚：没有标准答案，合理就好。编完请他讲给爸爸听一次——被认真听完，他才会想继续编。"}' AS JSON))
WHERE `id` = 'A171';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '说清楚一样东西的特征，让别人猜出来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"想一样东西不说出来。"},{"imageUrl":null,"instruction":"用特征描述：「圆圆的、红红的、可以吃」。"},{"imageUrl":null,"instruction":"让对方猜。"},{"imageUrl":null,"instruction":"猜对了换他描述。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说两个特征'),
  `harder` = COALESCE(`harder`, '说三四个特征，或描述比较抽象的东西。'),
  `tip` = COALESCE(`tip`, '「说清楚」的能力很重要——描述得越清楚，对方越猜得到。这个游戏在车上、排队时都能玩。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十三（描述·解释与推理语言）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"圆圆的、红红的、可以吃——是什么？这个游戏练的是一件很难的事：把脑袋里的东西，说到别人也看得见。","principles":["描述一样东西，需要先在脑中提取它的特征再说出来。","而且要挑出关键的特征，讲了对方才猜得到。","这就是有效沟通的核心：站在对方的角度组织讯息。","猜的人猜不到，就代表描述得不够清楚，回馈非常即时。","这种即时回馈让孩子自己学会调整，不需要大人纠正。","从具体可见的东西开始：形状、颜色、大小、用途。","熟了之后再描述抽象的东西，难度会跳一大阶。","轮流当描述者和猜的人，两个角色练到的能力不一样。","当猜的人时，他练的是听取讯息并整合推理。"],"prep":{"场地":"任何地方，餐桌、车上、排队等候时都能玩。","器材":"不需要任何东西；也可用家里现有物品当题库。","安全检查":"无特殊风险。避免用孩子会有压力的题目（例如考他不熟的词）。","大人位置":"大人先当描述者示范一轮，再交换。"},"shots":[{"name":"大人先示范","say":"我想到一样东西，圆圆的、红红的、可以吃。"},{"name":"孩子猜","say":"（孩子喊「苹果！」）答对了！"},{"name":"换他描述","say":"换你来，不要说出名字喔。"},{"name":"说两个特征","say":"（孩子说「长长的、黄黄的」）"},{"name":"猜不到就再加一个","say":"再给我一个提示。"},{"name":"描述抽象的","say":"这次描述一件事情，不是东西喔。"}],"reactions":[{"if":"孩子直接说出名字","then":"笑着说「那我就猜到啦」，再玩一次。用游戏的方式提醒规则。"},{"if":"孩子只说得出一个特征","then":"给他方向：「它是什么颜色？什么形状？可以做什么？」用问题当鹰架。"},{"if":"孩子描述得太模糊","then":"诚实地说「我猜不到耶」，让他自己补充。这个回馈比纠正有效。"}],"mistakes":["大人明明猜不到却假装猜到，孩子学不到调整。","孩子描述不清楚就直接替他讲完。","题目出得太难，孩子挫折感大。"],"down":"从三样摆在眼前的东西中选一样来描述，范围看得见就容易多了。","up":"描述抽象的概念（一种感觉、一件事情），或说出四个以上的特征。","progress":["一次能说出几个特征。","说的特征关不关键（别人猜不猜得到）。","猜不到时会不会自己补充讯息。"],"outro":"猜不到的时候，请诚实说「我猜不到耶」。让他自己发现要讲得更清楚——这个回馈，比你纠正一百次有用。"}' AS JSON))
WHERE `id` = 'A172';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸笔'),
  `trains` = COALESCE(`trains`, '用话把图形描述清楚，练精确的表达。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子拿一张简单的图（不给大人看）。"},{"imageUrl":null,"instruction":"他用话描述，大人照着画。"},{"imageUrl":null,"instruction":"画完对照原图，看哪里不一样。"},{"imageUrl":null,"instruction":"再交换角色。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '描述一个简单图形'),
  `harder` = COALESCE(`harder`, '描述位置关系（左边有个圆）。'),
  `tip` = COALESCE(`tip`, '画出来不一样就知道「哪里没说清楚」——这个游戏把「说得清楚」变得看得见，效果非常直接。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十三（描述·解释与推理语言）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"他说、你画，画完一对照——差多少，就是他的表达差多少。这是我知道最有效的「说清楚」训练。","principles":["这个游戏把「说得清不清楚」变成一张看得见的图。","差异有多大，一眼就知道，不需要任何评语。","孩子必须把空间关系说出来：在上面、在左边、有多大。","位置词和大小词在这里变成非说不可的工具，学得特别快。","他还得考虑顺序：先说整体再说细节，不然对方画不出来。","这就是组织讯息的能力，和日后写说明文、报告事情同一条肌肉。","大人要诚实地照着话画，不要用猜的补足，否则回馈就失真了。","对照的时候不评价谁对谁错，只看「哪里不一样、为什么」。","交换角色之后，孩子还会练到听取指令并执行。"],"prep":{"场地":"桌边，两人并排但看不到对方的纸，中间可立一本书当挡板。","器材":"两张纸、两支笔；一张画好的简单图形（三角形加圆形之类）。","安全检查":"使用无毒蜡笔或粗芯彩色笔，不使用尖头美工刀或细尖笔给幼儿。","大人位置":"大人坐在孩子旁边，中间有挡板，只靠听来画。"},"shots":[{"name":"立起挡板","say":"你看得到你的图，我看不到喔。"},{"name":"孩子开始描述","say":"（孩子说「中间有一个圆圆的」）"},{"name":"大人照着画","say":"（大人只照话画，不猜不补）"},{"name":"需要位置词","say":"圆圆的旁边还有什么？在左边还是右边？"},{"name":"对照","say":"我们来比比看——"},{"name":"交换角色","say":"换我说，你来画。"}],"reactions":[{"if":"孩子描述得太笼统","then":"诚实地画出你听到的版本。对照时他自己就会发现问题。"},{"if":"孩子急着要看你画得对不对","then":"先挡住，让他讲完整段再看。中途偷看就没有练到了。"},{"if":"对照结果差很多孩子不开心","then":"把焦点放在「哪一句话讲清楚了就会一样」，而不是画得像不像。"}],"mistakes":["大人用猜的把图补完整，回馈就假了。","把重点放在画得好不好看，而不是说得清不清楚。","图形一开始就太复杂，孩子讲到一半就放弃。"],"down":"只用一个图形（一个圆），并由大人问引导问题：「多大？在纸的哪里？」","up":"使用三到四个图形并包含位置关系，或描述一张实际照片。","progress":["会不会说出位置和大小。","两张图的相似度有没有提高。","有没有开始先说整体再说细节。"],"outro":"大人要诚实：他说什么你就画什么，不要用猜的补。对照的时候不比谁画得好，只看哪一句话可以讲得更清楚。"}' AS JSON))
WHERE `id` = 'A173';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子＋亲友'),
  `need` = COALESCE(`need`, '电话或视频通话'),
  `trains` = COALESCE(`trains`, '只靠声音沟通，练听清楚和说清楚。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先玩「假装打电话」。"},{"imageUrl":null,"instruction":"再真的打给爷爷奶奶。"},{"imageUrl":null,"instruction":"事先备好三句：问好→说一件事→再见。"},{"imageUrl":null,"instruction":"通完话夸他说得清楚。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '照准备好的三句说'),
  `harder` = COALESCE(`harder`, '接住对方的问题多聊几轮。'),
  `tip` = COALESCE(`tip`, '电话没有表情和手势帮忙，全靠听和说——是很好的语言练习。每周打一次两分钟的小电话就够。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"讲电话比面对面难很多——没有表情、没有手势，全靠声音。但正因为难，它是最好的表达训练。","principles":["电话拿掉了表情、手势和眼神，只剩下声音。","所以孩子必须把话说清楚，对方才听得懂。","同时他也必须专心听，因为没有嘴形和表情可以辅助。","这对说话不清楚的孩子是很好的自然回馈情境。","先玩假装打电话，把流程走熟，真的打时才不会紧张。","事先备好三句话（问好→说一件事→再见），孩子就有安全感。","有稿子可以照念，是降低社交焦虑最有效的方法。","通完话一定要夸他说得清楚，让这件事变成愉快的经验。","和长辈通话还有一个附加价值：维系关系，孩子会感受到自己被期待。"],"prep":{"场地":"安静的房间，背景没有电视或音乐，否则听不清楚。","器材":"电话或视频通话；先用玩具电话或积木假装。","安全检查":"真实通话前先确认对方方便接听；不让孩子自行拨打不熟悉的号码。","大人位置":"大人坐在孩子旁边，必要时可以小声提示，但不抢话。"},"shots":[{"name":"先假装","say":"喂？你好——我们先来练习。"},{"name":"准备三句话","say":"第一句问好，第二句说一件事，第三句再见。"},{"name":"真的拨出去","say":"（拨给爷爷奶奶）"},{"name":"说一件事","say":"我今天去公园玩滑梯。"},{"name":"大人在旁小声提示","say":"（大人指着字条，不出声抢话）"},{"name":"夸他说得清楚","say":"你刚刚讲得好清楚，爷爷都听懂了！"}],"reactions":[{"if":"孩子不敢开口","then":"先由大人讲，让他只说最后一句「再见」。成功一次之后再往前加。"},{"if":"孩子讲到一半忘词","then":"指着事先写好的字条，不要直接替他说。"},{"if":"孩子讲太小声对方听不到","then":"不要求大声，而是把手机拿近一点。压力小了声音自然会出来。"}],"mistakes":["没有事先准备就直接叫孩子讲，容易造成挫折。","孩子讲不出来时大人抢过电话讲完，练习就没了。","通话后检讨他哪里讲不好，下次他就不想讲了。"],"down":"只说一句话（你好，或再见），其余由大人完成。","up":"不用讲稿，能接住对方的问题并多聊三四轮。","progress":["愿不愿意拿起电话说话。","能不能完成准备好的三句。","会不会回应对方提出的问题。"],"outro":"事先准备三句话：问好、说一件事、再见。讲完一定要夸他说得清楚——讲电话这件事，要先变成愉快的经验。"}' AS JSON))
WHERE `id` = 'A174';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '过家家道具'),
  `trains` = COALESCE(`trains`, '在扮演中练完整的多轮对话。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"开「小商店」：他当老板，你当客人。"},{"imageUrl":null,"instruction":"走完流程：你好→要买什么→多少钱→给你→谢谢→再见。"},{"imageUrl":null,"instruction":"换角色再玩一次。"},{"imageUrl":null,"instruction":"再换场景（餐厅、医院）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '照固定台词走一遍'),
  `harder` = COALESCE(`harder`, '自由应对客人的新问题。'),
  `tip` = COALESCE(`tip`, '一场买卖就是一次完整的多轮对话——孩子玩着玩着就把「开始、中间、结束」的对话结构练熟了。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"开一间小商店，他当老板你当客人。在扮演里，孩子会说出平常说不出来的整段对话——因为那不是他，是角色。","principles":["角色扮演把对话放进一个有脚本的情境里，孩子压力小很多。","因为说话的是角色，说错了也是角色说错，不是他说错。","商店、餐厅这些场景有固定流程，对话有骨架可以依循。","固定流程让孩子知道下一句大概要说什么，不容易卡住。","走完一整套流程，他练到的是多轮对话，不只是一问一答。","交换角色很重要：当客人和当老板，说的话完全不同。","当老板要主动询问，当客人要表达需求，两种能力都练到。","换场景（餐厅、医院）可以把同一套结构迁移到新情境。","这些情境本来就是生活中会遇到的，练了就能直接用。"],"prep":{"场地":"客厅一角布置成商店，用桌子当柜台。","器材":"过家家道具：玩具食物、纸钞或纸片、购物袋。","安全检查":"道具不使用可吞入的小零件给三岁以下孩子；纸钞用大张纸片自制即可。","大人位置":"大人当客人，站在柜台前，完整走完对话流程。"},"shots":[{"name":"布置场景","say":"我们来开一间小商店，你当老板。"},{"name":"走流程","say":"你好！我要买苹果。"},{"name":"孩子当老板","say":"（孩子说「三块钱」）"},{"name":"完整收尾","say":"谢谢，再见！"},{"name":"交换角色","say":"换我当老板，你来买东西。"},{"name":"换场景","say":"下次我们开餐厅好不好？"}],"reactions":[{"if":"孩子不知道要说什么","then":"先把台词讲给他听，让他照着说一遍。熟了再让他自由发挥。"},{"if":"孩子只想玩道具不想对话","then":"先让他玩道具几分钟。玩够了再开始，不要一开始就要求讲话。"},{"if":"孩子答不出你临时加的问题","then":"把问题简化成二选一：「要大的还是小的？」"}],"mistakes":["大人太快加入变化球，孩子跟不上就不玩了。","只让孩子当一种角色，少掉另一半的练习。","纠正孩子的说法，扮演的乐趣马上消失。"],"down":"照固定台词走一遍，由大人先说一句他跟一句。","up":"大人临时加入新状况（东西卖完了、钱不够），让孩子自由应对。","progress":["能不能完整走完一轮流程。","交换角色后说得出对应的台词吗。","面对临时状况会不会自己想办法回应。"],"outro":"一定要交换角色——当老板和当客人，练到的能力完全不一样。熟了之后再换餐厅、医院，同一套结构可以一直用。"}' AS JSON))
WHERE `id` = 'A175';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '别人没听懂时，换个说法再说一次。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"他说话时你说「嗯？妈妈没听懂」。"},{"imageUrl":null,"instruction":"教他三招：说慢一点／换个说法／用手指一指。"},{"imageUrl":null,"instruction":"听懂了就说「哦～原来是这样！」"},{"imageUrl":null,"instruction":"让修正有成就感。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '原样再说一次'),
  `harder` = COALESCE(`harder`, '换个说法或加上手势。'),
  `tip` = COALESCE(`tip`, '没被听懂是孩子挫折的常见来源——教他「说不通还有别的办法」，能减少很多情绪爆发。别急着猜他要说什么。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一（提问与对话轮替）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"别人没听懂他的话，他就生气或放弃——今天教他三招，把「没听懂」变成可以处理的小状况。","principles":["别人听不懂是一定会发生的事，重点是孩子怎么处理。","不会处理的孩子会生气、会哭、会干脆不说了。","这叫做沟通修补，是很重要但常被忽略的能力。","三招最好用：说慢一点、换个说法、用手指一指。","有具体的方法，孩子才不会只能重复同一句更大声。","大人要偶尔真的表示没听懂，制造练习机会。","但不要太频繁，否则孩子会觉得自己讲话很失败。","修补成功的时候要有明显的反应：「哦～原来是这样！」","让修正这件事有成就感，孩子才愿意一再尝试。"],"prep":{"场地":"日常对话情境，不需要特别安排。","器材":"不需要任何东西。","安全检查":"无特殊风险。装作没听懂的次数要节制，孩子情绪不好时不要玩。","大人位置":"大人面对孩子，表情是困惑不是不耐烦。"},"shots":[{"name":"装作没听懂","say":"嗯？妈妈没听懂耶。"},{"name":"第一招慢一点","say":"你可以说慢一点。"},{"name":"第二招换说法","say":"或者换个说法讲讲看。"},{"name":"第三招用手指","say":"也可以指给我看。"},{"name":"修补成功","say":"哦～原来是这样！我懂了！"},{"name":"别太频繁","say":"（字幕提醒：一天一两次就好）"}],"reactions":[{"if":"孩子生气或哭了","then":"立刻停止，改成「我猜你是说……对吗？」帮他把话补上，先把情绪接住。"},{"if":"孩子只是重复得更大声","then":"直接示范一招：「你指给我看好不好？」用行动教比用嘴教快。"},{"if":"孩子干脆不说了","then":"这表示次数太多了。接下来几天先专心听懂他，把信心补回来。"}],"mistakes":["太常装作没听懂，孩子会对自己的表达失去信心。","露出不耐烦的表情，孩子会觉得是自己的问题。","孩子修补成功却没有明显反应，努力没有被看见。"],"down":"只练第三招：用手指一指。动作最简单，成功率最高。","up":"不用提示就会自己换说法或补充说明，并能对不同的人调整讲法。","progress":["别人没听懂时会不会再试一次。","会不会换说法或用手势补充。","遇到这种状况时情绪稳不稳。"],"outro":"三招：说慢一点、换个说法、用手指一指。听懂的时候记得夸张一点说「哦～原来是这样」——让修正这件事有成就感。"}' AS JSON))
WHERE `id` = 'A176';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸卡或小盒子'),
  `trains` = COALESCE(`trains`, '准备一些「可以聊什么」的话题，没话说时有得拿。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一起列话题：今天做的事、喜欢的东西、看过的动画、好玩的见闻。"},{"imageUrl":null,"instruction":"写或画在卡片上，放进盒子。"},{"imageUrl":null,"instruction":"吃饭时抽一张来聊。"},{"imageUrl":null,"instruction":"常常加新话题进去。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '抽卡照着聊'),
  `harder` = COALESCE(`harder`, '不用卡也能想出话题。'),
  `tip` = COALESCE(`tip`, '「不知道聊什么」是很多孩子卡住的地方——话题有库存，就不怕冷场。饭桌上抽一张，全家一起聊。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组七（维持互动·对话与延续）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「没话说」不是因为没东西聊，是因为想不到。今天做一个盒子，把话题存起来，需要的时候抽一张。","principles":["想不到话题，是孩子（和大人）聊天最常卡住的地方。","把话题先想好写下来，等于把「想」和「说」这两件事分开。","需要的时候只要抽一张，认知负担大幅下降。","一起列话题的过程本身就是练习，他会开始意识到什么可以聊。","话题分四类最好用：今天做的事、喜欢的东西、看过的动画、好玩的见闻。","写不出来的孩子可以用画的，画图一样有效。","吃饭时抽一张来聊，把聊天变成固定的家庭仪式。","常常加新话题进去，盒子会跟着孩子的兴趣一起长大。","熟了之后把盒子收起来，孩子脑中已经有一份话题清单了。"],"prep":{"场地":"餐桌，全家人都在的时候效果最好。","器材":"纸卡或便条纸、笔、一个小盒子或罐子。","安全检查":"使用圆角纸卡，剪裁由大人完成；盒子不使用玻璃材质。","大人位置":"大人和孩子一起写、一起画，不要由大人单方面决定话题。"},"shots":[{"name":"一起列话题","say":"我们来想想，可以聊些什么？"},{"name":"四大类","say":"今天做的事、喜欢的东西、看过的动画、好玩的见闻。"},{"name":"写不出来就画","say":"不会写字就用画的。"},{"name":"放进盒子","say":"（把卡片一张张放进盒子）"},{"name":"吃饭时抽一张","say":"今天抽到——最喜欢的动画！"},{"name":"常常加新的","say":"今天有新的话题吗？写进去。"}],"reactions":[{"if":"孩子想不出话题","then":"从他今天做过的事开始写，每一件事都可以是一张卡。"},{"if":"抽到的话题孩子不想聊","then":"可以换一张。让他有选择权，盒子才不会变成作业。"},{"if":"孩子只想抽卡不想聊","then":"那就一餐只抽一张，抽完聊两句就好，短而愉快比长而勉强好。"}],"mistakes":["由大人单方面决定话题，孩子没有参与感。","规定每餐都要抽，变成任务就不好玩了。","抽到不想聊的话题还硬要聊完。"],"down":"只准备五张卡片，而且全部都是他最爱的主题。","up":"不用盒子也能自己想出话题，并主动开启对话。","progress":["会不会自己提出可以聊的话题。","抽到卡片后能聊几句。","有没有开始不用卡片就能开启话题。"],"outro":"一起写、一起画，盒子才是他的。吃饭时抽一张聊两句就好——短而愉快，比长而勉强有用得多。"}' AS JSON))
WHERE `id` = 'A177';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会开场和收尾的话，让互动有头有尾。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"见面：「你好」「早安」。"},{"imageUrl":null,"instruction":"离开：「我要回家了，再见」「明天见」。"},{"imageUrl":null,"instruction":"不玩了：「我先不玩了，你们玩」。"},{"imageUrl":null,"instruction":"每天进出门都练。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说再见挥手'),
  `harder` = COALESCE(`harder`, '主动好好收尾再离开。'),
  `tip` = COALESCE(`tip`, '玩着玩着就突然走掉，别的孩子会觉得莫名其妙——教他说一声再走，人缘会好很多。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组七（维持互动·对话与延续）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子玩一玩突然走掉，别的孩子会觉得他很奇怪。其实他只是不知道「离开也要说一声」。今天补上开场和收尾。","principles":["互动有头有尾，别人才知道现在是开始还是结束。","突然走掉会让对方困惑，甚至觉得被拒绝。","开场的话很短：你好、早安、我可以一起玩吗。","收尾的话一样短：我要回家了、再见、明天见。","这些都是固定句型，不需要临场组织，最容易学会。","「我先不玩了，你们玩」是很实用的一句，专门用来退出团体。","会好好退出的孩子，下次别人还是欢迎他加入。","每天进出门都练，一天就有好几次自然的机会。","这项能力看起来小，却直接影响别人对他的第一印象。"],"prep":{"场地":"家门口、电梯口、公园离开时，都是现成的练习场景。","器材":"不需要任何东西。","安全检查":"无特殊风险。不强迫孩子和陌生人打招呼。","大人位置":"大人先做给孩子看，每次自己都确实说出口。"},"shots":[{"name":"进门打招呼","say":"我回来了！奶奶早安。"},{"name":"孩子跟着说","say":"（孩子跟着说「早安」）"},{"name":"离开要说一声","say":"我要回家了，再见！"},{"name":"退出团体","say":"我先不玩了，你们玩。"},{"name":"突然走掉的对比","say":"（示范默默走掉，其他人一脸疑惑）"},{"name":"每天都练","say":"（快剪：出门、进门、离开公园）"}],"reactions":[{"if":"孩子害羞不敢说","then":"改成挥手就好。动作先出来，声音慢慢会跟上。"},{"if":"孩子只对熟人说","then":"很正常。先从熟人练稳，不要急着推到陌生人。"},{"if":"孩子玩到一半还是默默走掉","then":"当下不责备，走到他旁边小声提醒一次，下次再试。"}],"mistakes":["强迫孩子跟陌生人打招呼，会造成反效果。","孩子不说就当众说他没礼貌，伤自尊又没帮助。","大人自己进出门都不打招呼，却要求孩子做到。"],"down":"只用动作：挥手、点头，不要求说话。","up":"能主动开场（我可以一起玩吗）并好好退出（我先不玩了，你们玩）。","progress":["会不会挥手或点头。","会不会说出招呼语和道别语。","离开团体时会不会主动说一声。"],"outro":"教他一句最实用的话：「我先不玩了，你们玩。」会好好退出的孩子，下次别人还是欢迎他。"}' AS JSON))
WHERE `id` = 'A178';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '每天固定的分享时间，让说话变成习惯。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"睡前问「今天最开心的一件事？」"},{"imageUrl":null,"instruction":"再问「有没有不开心的事？」"},{"imageUrl":null,"instruction":"两样都认真听、不急着评论。"},{"imageUrl":null,"instruction":"大人也分享自己的。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说一件事'),
  `harder` = COALESCE(`harder`, '说出事情经过和感受。'),
  `tip` = COALESCE(`tip`, '每天几分钟的固定分享，孩子的心事就不会积成山。这段时间只倾听、不说教——他才愿意一直说下去。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组三（情绪表达·说出感受）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"每天睡前五分钟，问两个问题：今天最开心的事，和不开心的事。两样都要问——这是我认为最值得坚持的一个习惯。","principles":["固定的分享时间，会把说话变成一件理所当然的事。","孩子知道每天都有这个时段，会开始在白天就留意「等一下要说什么」。","问开心的事，孩子愿意开口，气氛也轻松。","但一定也要问不开心的事，否则负面情绪没有出口。","两样都问，孩子才会知道不开心也是可以说的。","最难的是「不急着评论」——听完先接住，不要马上给建议或讲道理。","一旦开始检讨，孩子下次就只会挑安全的事情说。","大人也分享自己的一天，示范大人也会有不开心的事。","这个习惯维持到青春期，会是亲子之间最重要的一条通道。"],"prep":{"场地":"床边，灯光调暗，手机放在房间外。","器材":"不需要任何东西。","安全检查":"孩子说出让人担心的事时，先接住情绪，隔天再处理，不在睡前深谈。","大人位置":"大人躺或坐在孩子身边，身体朝向他，不看手机。"},"shots":[{"name":"固定时间","say":"（灯光调暗，大人坐到床边）"},{"name":"问开心的事","say":"今天最开心的一件事是什么？"},{"name":"认真听","say":"（大人点头、不打断）"},{"name":"也问不开心的","say":"那有没有不开心的事？"},{"name":"先接住","say":"哦，这样确实会难过。"},{"name":"大人也分享","say":"我今天也有一件事有点烦……"}],"reactions":[{"if":"孩子说没有不开心的事","then":"不追问。说「那很好」就好，把空间留着，他想说的时候会说。"},{"if":"孩子说的事让你很想纠正","then":"先忍住。今天只负责听，明天白天再找机会谈。"},{"if":"孩子每天都说一样的事","then":"那可能就是他最在意的。多问一句「今天的那件事怎么样了？」"}],"mistakes":["听完立刻开始检讨或给建议，孩子下次就只讲安全的事。","只问开心的事，负面情绪没有出口。","大人一边听一边滑手机，分享就变成敷衍。"],"down":"只问一个问题（今天最开心的事），说出一件事就够。","up":"说出事情的经过、当时的感受，以及自己怎么处理的。","progress":["愿不愿意说出一件事。","会不会主动说出不开心的事。","能不能说出经过和感受，而不只是结果。"],"outro":"两个问题：最开心的事、不开心的事。最难的是听完先不要评论——今天只负责听，明天再谈。"}' AS JSON))
WHERE `id` = 'A179';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本、纸笔'),
  `trains` = COALESCE(`trains`, '把这个模组的能力串起来练一轮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：一问一答五个问题，每次都加一句。"},{"imageUrl":null,"instruction":"第二关：三张图说出一个故事。"},{"imageUrl":null,"instruction":"第三关：描述一样东西让人猜。"},{"imageUrl":null,"instruction":"第四关：说说今天做了什么。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关给提示'),
  `harder` = COALESCE(`harder`, '独立完成，说得完整流畅。'),
  `tip` = COALESCE(`tip`, '聊天和说故事是上学后最常用的语言能力——问答、接话、讲清楚一件事，练熟了在教室里会轻松很多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十一～十三（对话轮替 · 叙事复述 · 描述解释）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"这是模组九的总复习。四关，把这个模组练过的能力串起来走一遍——一问一答、说故事、描述、讲今天。","principles":["把分开练过的能力串起来用一次，才知道哪一项还不稳。","分项练熟不代表能整合，整合本身就是一种能力。","第一关一问一答加一句，练的是对话的基本单位。","第二关三张图说故事，练的是叙事结构。","第三关描述给人猜，练的是精确表达。","第四关说说今天做了什么，练的是回想与顺序。","四关涵盖了这个模组最核心的四种能力。","过关的形式会提高动机，但不要计较分数和输赢。","哪一关卡住，就知道接下来要回去补哪一个活动。"],"prep":{"场地":"客厅或餐桌，一个不受打扰的半小时。","器材":"绘本或三张顺序图、纸笔；其余不需要。","安全检查":"无特殊风险。孩子累了就分两天做完，不要一次硬走完四关。","大人位置":"大人当主持人，每一关先说明规则，必要时给提示。"},"shots":[{"name":"宣布四关","say":"今天有四关，我们一关一关来。"},{"name":"第一关问答","say":"我问五个问题，每一题你都要多说一句。"},{"name":"第二关说故事","say":"三张图，排好顺序说一个故事。"},{"name":"第三关描述","say":"想一样东西，说三个特征让我猜。"},{"name":"第四关说今天","say":"用先、然后、最后说说今天。"},{"name":"收尾肯定","say":"四关都完成了！你今天讲了好多话。"}],"reactions":[{"if":"孩子某一关完全卡住","then":"给提示直接过关，记下来，之后回去单独练那个活动。"},{"if":"孩子失去耐心","then":"分两天做完。四关不必一次走完，完成比连续更重要。"},{"if":"孩子表现比平常差","then":"不比较。今天状态不好很正常，换个时间再玩一次。"}],"mistakes":["把它当成考试，孩子就不想玩了。","四关硬要一次走完，最后一关草草结束。","卡住的那一关一直重复，把挫折放大。"],"down":"每一关都给提示，只要求完成不要求完整。","up":"四关全部独立完成，并且每一关都说得完整流畅。","progress":["四关各自完成到什么程度。","哪一关需要最多提示（那就是接下来要补的）。","整体说话的长度和流畅度和一个月前比起来如何。"],"outro":"四关走完，哪一关卡住就知道接下来要补哪里。记得这是游戏不是考试——孩子愿意一直说，才是真正的目标。"}' AS JSON))
WHERE `id` = 'A180';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '表情图卡或自己画的脸'),
  `trains` = COALESCE(`trains`, '认得出开心、难过、生气、害怕四种基本情绪。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"画四张脸：开心（嘴角上扬）、难过（嘴角向下）、生气（皱眉）、害怕（睁大眼）。"},{"imageUrl":null,"instruction":"一次教一种，说出名字。"},{"imageUrl":null,"instruction":"问「哪一张是开心的？」"},{"imageUrl":null,"instruction":"连到孩子的真实经历。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '认两种（开心、难过）'),
  `harder` = COALESCE(`harder`, '四种都能指认并说出名称。'),
  `tip` = COALESCE(`tip`, '从最容易的「开心」开始教。指出线索会更好懂——「你看他的嘴角往上翘」比只说「他很开心」有用。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子要先认得出情绪，才谈得上处理情绪。今天从最基本的四种开始：开心、难过、生气、害怕。","principles":["情绪管理的第一步不是控制，是辨认——认不出来的东西没办法处理。","开心、难过、生气、害怕是四种基本情绪，全世界的孩子都最早认得这四种。","它们的表情特征最明显，所以最容易从脸上看出来。","画成简单的四张脸，把复杂的表情简化成几条线，孩子更抓得住重点。","一次只教一种，教完再加下一种，混在一起孩子会分不清。","教的时候一定要说出情绪的名字，让感觉有一个词可以挂上去。","有了词，情绪才能被讨论，否则孩子只能用哭和打来表达。","最重要的一步是连到孩子的真实经历：「上次玩具坏掉，你就是这种脸。」","光认图卡没有用，要连到他自己的经验，这个词才活起来。"],"prep":{"场地":"桌边坐着，光线明亮看得清楚表情图。","器材":"四张表情图卡，或大人当场用纸笔画的四张脸。","安全检查":"无特殊风险。不用负面情绪的图卡吓孩子，也不把「生气」画得狰狞。","大人位置":"大人坐在孩子旁边，图卡放在他正前方，一次只拿出一张。"},"shots":[{"name":"当场画四张脸","say":"我们来画心情。"},{"name":"开心","say":"嘴角往上，这是开心。"},{"name":"难过","say":"嘴角往下，这是难过。"},{"name":"生气与害怕","say":"眉毛皱起来是生气；眼睛睁得大大的是害怕。"},{"name":"问他指认","say":"哪一张是开心的？"},{"name":"连到真实经历","say":"上次你的积木倒了，你就是这一张对不对？"}],"reactions":[{"if":"孩子四种混在一起分不清","then":"退回只教两种（开心、难过），这两种差异最大，练稳再加。"},{"if":"孩子只会指不会说","then":"指对就代表已经认得了。名称由你说出来，多听几次自然会说。"},{"if":"孩子对生气的图卡有抗拒","then":"把图画得柔和一点，并强调「生气是正常的，每个人都会」。"}],"mistakes":["一次把四种都摊出来教，孩子记不住也分不清。","只教认图卡，没有连到孩子自己的经验。","把负面情绪说成不好的事，孩子会不敢承认自己生气。"],"down":"只教开心和难过两种，并且用大人的真脸做给他看，不用图卡。","up":"加入更细的情绪词（紧张、失望、兴奋），并让孩子自己画出对应的脸。","progress":["听到情绪名称能不能指出对的图。","会不会自己说出情绪的名字。","能不能把图和自己的真实经历连起来。"],"outro":"四种就够了：开心、难过、生气、害怕。一次教一种，最重要的是连到他自己的事——上次积木倒了，你就是这一张。"}' AS JSON))
WHERE `id` = 'A181';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '镜子'),
  `trains` = COALESCE(`trains`, '用自己的脸做出表情，把感受和表情连起来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"和孩子一起照镜子。"},{"imageUrl":null,"instruction":"轮流做表情：开心、难过、生气、害怕。"},{"imageUrl":null,"instruction":"看看自己的表情长什么样。"},{"imageUrl":null,"instruction":"玩「我说情绪你来做」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '模仿大人的表情'),
  `harder` = COALESCE(`harder`, '听到情绪词就做出对的表情。'),
  `tip` = COALESCE(`tip`, '洗漱的时候顺便玩——用自己的脸做过一次，认别人的表情就容易多了。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"认得别人的表情，不代表知道自己的脸长什么样。今天带他照镜子，把感受和自己的脸连起来。","principles":["孩子看得到别人的脸，却几乎看不到自己的脸。","所以他常常不知道自己现在的表情传达了什么。","照镜子做表情，是把感受和自己的面部动作连起来最直接的方法。","做出表情的同时，身体也会跟着产生一点相应的感觉。","这叫做表情回馈，做出笑脸真的会让人心情好一点点。","轮流做表情让这件事变成游戏，孩子愿意一再重复。","「我说情绪你来做」把词和动作绑在一起，比单纯认图卡更深一层。","照镜子还有一个好处：孩子会开始注意自己，这是自我觉察的起点。","对表情比较少的孩子，这个练习可以扩大他的表情幅度。"],"prep":{"场地":"浴室或房间的镜子前，两人都照得到的高度。","器材":"一面镜子；手持小镜子也可以。","安全检查":"使用不易破碎的镜子或壁挂式镜子；不让孩子拿着玻璃镜跑动。","大人位置":"大人蹲下与孩子同高，两张脸一起出现在镜子里。"},"shots":[{"name":"一起照镜子","say":"我们来看看自己的脸。"},{"name":"大人先做","say":"这是开心的脸——"},{"name":"孩子模仿","say":"（孩子跟着做）"},{"name":"四种轮流","say":"难过、生气、害怕。"},{"name":"我说你做","say":"生气！（孩子做出生气脸）"},{"name":"看看自己","say":"你生气的时候，原来长这样。"}],"reactions":[{"if":"孩子做不出表情","then":"大人做得更夸张一点，并用手轻轻示范（指指自己的嘴角）。"},{"if":"孩子只顾着玩镜子","then":"先让他玩一分钟。玩够了再开始，镜子本身就很吸引人。"},{"if":"孩子做出的表情都一样","then":"一次只练一种，用力练熟一种再换下一种。"}],"mistakes":["表情做得太含蓄，孩子看不出差别。","一次练四种，孩子做到后来全部混在一起。","孩子做不像就笑他，他会不想再做。"],"down":"只练开心和生气两种，并由大人握着他的手指指自己的嘴角当提示。","up":"加入细微的表情（紧张、惊讶），并在没有镜子的情况下听词做表情。","progress":["会不会模仿大人的表情。","听到情绪词能不能做出对的表情。","做出来的表情彼此有没有区别。"],"outro":"孩子很少看到自己的脸。带他照镜子做表情，让他知道——原来我生气的时候长这样。"}' AS JSON))
WHERE `id` = 'A182';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '看真人的表情猜情绪，比看图卡更接近真实。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人做一个表情（不说话）。"},{"imageUrl":null,"instruction":"让孩子猜是什么心情。"},{"imageUrl":null,"instruction":"猜对了换他做、你猜。"},{"imageUrl":null,"instruction":"提示看哪里：「看我的嘴巴」「看我的眉毛」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '夸张的表情'),
  `harder` = COALESCE(`harder`, '自然、细微的表情。'),
  `tip` = COALESCE(`tip`, '真人的脸比图卡微妙得多——先做夸张一点，孩子猜对了有信心，再慢慢自然化。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"图卡上的脸和真人的脸差很多。今天不用图卡，直接看我的脸——这才是他在真实世界里要读的东西。","principles":["图卡的表情是静止、夸张、单一的，真人的脸不是。","真实的表情会动、会混合、会很细微，难度高很多。","所以认完图卡一定要过渡到真人，否则学到的东西用不出来。","大人先做夸张的表情，成功率高，孩子有信心。","熟了之后逐渐做得自然，难度就自动往上走。","给提示的时候要指出看哪里：嘴巴、眉毛、眼睛。","教他看特定部位，是把「读表情」这件事变成可学的技巧。","换孩子做表情、大人猜，他就要主动制造表情，练到表达端。","全家一起玩会有更多不同的脸可以读，效果更好。"],"prep":{"场地":"光线充足的地方，看得清楚彼此的脸。","器材":"不需要任何东西。","安全检查":"无特殊风险。做害怕、生气的表情时不要吓到孩子，先说明这是游戏。","大人位置":"大人面对孩子，距离约一个手臂，不说话只做表情。"},"shots":[{"name":"说明游戏","say":"我不说话，你猜我是什么心情。"},{"name":"夸张的表情","say":"（做一个很明显的难过脸）"},{"name":"孩子猜","say":"（孩子说「难过」）答对了！"},{"name":"给看哪里的提示","say":"看我的嘴巴——看我的眉毛。"},{"name":"自然的表情","say":"（做一个很细微的表情）"},{"name":"换他做","say":"换你做，我来猜。"}],"reactions":[{"if":"孩子猜不出来","then":"把表情做得更夸张，并指出关键部位：「你看我的嘴角。」"},{"if":"孩子每次都猜同一种","then":"改成二选一：「我是生气还是难过？」缩小范围。"},{"if":"孩子做的表情大人猜不出","then":"诚实说「我猜不到耶，再做一次更清楚一点」，这个回馈很有价值。"}],"mistakes":["一开始就做自然细微的表情，孩子完全读不出来。","猜错时纠正得太快，没有教他看哪里。","只让孩子猜，没有换他做，少掉表达的练习。"],"down":"只做两种差异最大的表情（开心／难过），而且做得非常夸张。","up":"做混合或细微的表情（有点担心、有点无聊），并让孩子说出他从哪里看出来的。","progress":["能不能猜出夸张的表情。","能不能猜出比较自然的表情。","会不会说出自己是从哪里看出来的。"],"outro":"图卡认完了，一定要过渡到真人的脸。给提示的时候教他看哪里——看嘴巴、看眉毛，读表情是可以学的技巧。"}' AS JSON))
WHERE `id` = 'A183';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '孩子有情绪时，大人帮他命名。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子难过时说「你很难过对不对」。"},{"imageUrl":null,"instruction":"生气时说「你在生气」。"},{"imageUrl":null,"instruction":"开心时说「你好开心！」"},{"imageUrl":null,"instruction":"不急着讲道理，先说中他的感受。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人命名他点头'),
  `harder` = COALESCE(`harder`, '他自己说出情绪名称。'),
  `tip` = COALESCE(`tip`, '被说中的情绪会小一半——这比任何道理都有效。先接纳感受，再谈行为，顺序不能反。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子在哭、在闹的时候，先别急着讲道理。先说一句：「你很难过对不对。」——这一句，比十句道理有用。","principles":["孩子的情绪来的时候，他自己也不知道那是什么。","大人帮他把感觉说出来，叫做情绪命名，是最基础也最有效的一招。","被说中的那一刻，孩子会觉得「有人懂我」，情绪强度就会下降一些。","这在大脑上是有依据的：把感觉转成语言，会降低情绪脑的激动程度。","所以命名不只是沟通技巧，它本身就有安抚作用。","顺序很重要：先说中感受，再谈道理，颠倒过来两件事都做不成。","情绪高涨的时候讲道理，孩子根本听不进去。","长期这样做，孩子会慢慢学会自己说出情绪的名字。","这是从「大人帮他命名」走到「他自己命名」的必经之路。"],"prep":{"场地":"孩子出现情绪的当下，任何地方。","器材":"不需要任何东西。","安全检查":"孩子有危险行为（打人、丢东西）时先确保安全，再做命名。","大人位置":"大人蹲下与孩子同高，语气平稳，不急不凶。"},"shots":[{"name":"孩子有情绪","say":"（孩子哭着推开东西）"},{"name":"先命名","say":"你很难过对不对。"},{"name":"孩子安静下来","say":"（孩子哭声变小、抬头看大人）"},{"name":"不急着讲道理","say":"（大人只是陪着，不说教）"},{"name":"生气时也一样","say":"你在生气。"},{"name":"开心时也要命名","say":"你好开心！"}],"reactions":[{"if":"孩子说「不是」","then":"换一个词试试：「那是生气吗？」猜错没关系，他会告诉你对的那个。"},{"if":"孩子哭得更大声","then":"那通常是被理解了。继续陪着，不要因此停止命名。"},{"if":"大人自己也快爆炸了","then":"先深呼吸，或先离开一下再回来。命名需要平稳的语气才有效。"}],"mistakes":["一开口就讲道理，孩子的情绪还没被接住。","用「有什么好哭的」否定感受，孩子会学会隐藏情绪。","只命名负面情绪，正面的开心从来不说。"],"down":"只做一件事：说出「你很难过」，说完就安静陪着，什么都不加。","up":"命名之后加上原因：「你很难过，因为积木倒了。」并等他自己接话。","progress":["被命名时孩子的情绪有没有缓下来。","他会不会点头或回应。","有没有开始自己说出情绪的名字。"],"outro":"先说中他的感受，再谈道理——顺序颠倒，两件事都做不成。开心的时候也要命名，不要只在他哭的时候才说。"}' AS JSON))
WHERE `id` = 'A184';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '从最容易的正面情绪开始，学会说出感受。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子开心时引导他说「我很开心！」"},{"imageUrl":null,"instruction":"他说了就热情回应「妈妈也开心！」"},{"imageUrl":null,"instruction":"玩得高兴时问「你现在什么心情？」"},{"imageUrl":null,"instruction":"从跟着说到主动说。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着说「开心」'),
  `harder` = COALESCE(`harder`, '主动说「我很开心，因为……」。'),
  `tip` = COALESCE(`tip`, '表达从正面情绪入手最容易——先让孩子习惯「说出心情」这件事，难过生气才说得出口。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组三（情绪表达·说出感受）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"教说情绪，要从开心开始——因为开心的时候他心情好、愿意说，成功率最高。","principles":["学说情绪要从最容易的开始，正面情绪的门槛最低。","孩子在开心的时候心情放松，比较愿意开口。","负面情绪来的时候人是慌的，那不是学新技能的好时机。","所以先在开心时把「说出感受」这个动作练熟。","练熟之后，遇到难过生气时才有机会用得上。","他说了要热情回应：「妈妈也开心！」让说出感受变成一件愉快的事。","在他玩得高兴时问一句「你现在什么心情」，时机最自然。","从跟着说到主动说，中间需要很多次的示范，不要急。","进阶是加上原因「我很开心，因为……」，那就连到因果表达了。"],"prep":{"场地":"孩子正在开心玩耍的任何场景。","器材":"不需要任何东西。","安全检查":"无特殊风险。不打断孩子正在进行的游戏来问问题。","大人位置":"大人在旁边一起玩，找游戏的自然停顿点发问。"},"shots":[{"name":"他玩得正开心","say":"（孩子笑着玩）"},{"name":"大人先示范","say":"我好开心！"},{"name":"引导他说","say":"你呢？你现在什么心情？"},{"name":"他说了","say":"（孩子说「开心」）妈妈也开心！"},{"name":"加上原因","say":"我很开心，因为跟你一起玩。"},{"name":"从跟说到主动说","say":"（快剪：孩子主动说「我好开心」）"}],"reactions":[{"if":"孩子不回答只是继续玩","then":"不勉强。由大人说出自己的感受就好，示范本身就是教学。"},{"if":"孩子只重复你的话","then":"很好，这就是学习的开始。多几次之后他会开始自己说。"},{"if":"孩子说不出原因","then":"由你替他说一次：「因为滑梯很好玩对不对？」让他听见句型。"}],"mistakes":["在孩子玩到最专心的时候打断他发问。","孩子说了却只是「嗯」一声带过，回应太冷淡。","从负面情绪开始教，难度太高。"],"down":"只跟着说「开心」两个字，由大人先说他再重复。","up":"主动说出「我很开心，因为……」，并能在不同情境说出不同的正面情绪（兴奋、满足）。","progress":["会不会跟着说出情绪词。","有没有开始主动说。","能不能加上原因。"],"outro":"从开心开始教，因为他心情好的时候最愿意说。等这个动作练熟了，难过生气的时候才用得上。"}' AS JSON))
WHERE `id` = 'A185';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '生气时能说出来，是替代打人摔东西的第一句话。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在他刚有点生气（还没爆）时引导「说：我生气了！」"},{"imageUrl":null,"instruction":"他说了就认真回应「妈妈听到了，怎么了？」"},{"imageUrl":null,"instruction":"平静时用玩偶演一次：「小熊生气了，它说：我生气了」。"},{"imageUrl":null,"instruction":"强调「生气可以说，不可以打」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着说'),
  `harder` = COALESCE(`harder`, '生气的当下先说而不是先动手。'),
  `tip` = COALESCE(`tip`, '在情绪还小的时候练最有效——等到爆炸了才教，孩子听不进去。他每次用说的，都要大力肯定。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组三（情绪表达·说出感受）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子生气就动手打人——他不是坏，是那一刻只有这一个办法。今天给他第一句话：「我生气了。」","principles":["会说「我生气了」，是替代打人、摔东西最关键的第一句话。","孩子动手不是因为坏，是因为当下没有别的工具可用。","给他一句话，就是给他一个新工具。","时机非常关键：要在他刚有点生气、还没爆炸的时候引导。","已经爆了才教，他什么都听不进去，那时候只能先确保安全。","他说了之后大人一定要认真回应：「妈妈听到了，怎么了？」","如果说了没有用，他下次还是会回去用打的，因为打比较有效。","平静的时候用玩偶演一次，是最好的预演方式，压力最小。","最后要讲清楚那条界线：生气可以说，但不可以打人。"],"prep":{"场地":"平静时的演练在客厅；真实引导则在情绪发生的当下。","器材":"一个玩偶（演练用）。","安全检查":"孩子已经动手时，先用身体温和挡住并确保双方安全，再谈说话；不在孩子暴怒当下讲道理。","大人位置":"大人蹲下与孩子同高，侧身不正面对峙，语气稳定不提高音量。"},"shots":[{"name":"平静时用玩偶演","say":"小熊的积木被拿走，它很生气——它说：我生气了！"},{"name":"真实情境刚起火","say":"（孩子皱眉、身体紧绷，还没爆）"},{"name":"给他那句话","say":"说：我生气了！"},{"name":"认真回应","say":"妈妈听到了，怎么了？"},{"name":"界线","say":"生气可以说，不可以打人。"},{"name":"已经爆了怎么办","say":"（先确保安全，安静陪着，不说教）"}],"reactions":[{"if":"孩子已经动手了","then":"先温和挡住确保安全，不在这时讲道理。等平静了再回头谈那句话。"},{"if":"孩子说了但还是很生气","then":"那也是成功。说出来不代表气会马上消，但他用了语言而不是手。"},{"if":"孩子说完发现没人理","then":"这是最伤的。请务必停下手边的事回应他，哪怕只有十秒。"}],"mistakes":["在孩子暴怒的当下教他说话，那时候根本听不进去。","他说了「我生气了」却被回一句「生什么气」，工具立刻作废。","只讲不可以打，没有给他可以做的替代方式。"],"down":"只用玩偶演，不要求孩子在真实情境中做到；先让他熟悉这句话。","up":"生气的当下先说再处理，并能说出生气的原因：「我生气，因为他拿走我的车。」","progress":["平静时会不会说这句话。","生气时有没有出现「先说」的迹象。","动手的次数有没有减少。"],"outro":"两件事：第一，在他还没爆的时候教；第二，他说了你一定要认真回应。生气可以说，不可以打——这条线要一直很清楚。"}' AS JSON))
WHERE `id` = 'A186';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '难过时能说出来，用语言替代只会哭。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子难过时先共情「你很难过」。"},{"imageUrl":null,"instruction":"再引导他说「我难过」。"},{"imageUrl":null,"instruction":"他说了就立刻抱抱、安慰。"},{"imageUrl":null,"instruction":"传达「说出来，妈妈就懂了」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '点头承认难过'),
  `harder` = COALESCE(`harder`, '主动说出难过和原因。'),
  `tip` = COALESCE(`tip`, '目标不是「不许哭」，而是让「说」慢慢走到眼泪前面。哭也没关系——说出来只是多一条被理解的路。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组三（情绪表达·说出感受）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子难过只会哭，因为哭最快。今天教他一句话，让他知道——说出来，也一样会被抱住。","principles":["哭是最早、最本能的表达方式，所以孩子一难过就哭。","要用语言取代哭，语言必须一样有效，甚至更有效。","所以顺序是：先共情，再引导说，说了就立刻抱抱。","第一步的共情不能省：「你很难过。」被理解了，孩子才有余力说话。","如果直接要求「不要哭，用说的」，那是在要求一个正在淹水的人先游泳。","他说了就立刻抱住、安慰，让这个新方法的回馈比哭还好。","要传达的讯息是：说出来，妈妈就懂了，而且会来。","不要说「男生不能哭」这类话，那会让孩子把难过藏起来。","藏起来的难过不会消失，只会在别的地方冒出来。"],"prep":{"场地":"孩子难过的当下，任何地方；事后回顾则在安静的地方。","器材":"不需要任何东西。","安全检查":"无特殊风险。不用「不准哭」压制情绪；孩子持续低落数周应寻求专业协助。","大人位置":"大人蹲下或坐下，与孩子同高，身体保持开放可以随时拥抱。"},"shots":[{"name":"孩子在哭","say":"（孩子难过地哭）"},{"name":"先共情","say":"你很难过。"},{"name":"再引导","say":"你可以说：我难过。"},{"name":"说了就抱","say":"（孩子说出来，大人立刻抱住）"},{"name":"传达讯息","say":"你说出来，妈妈就懂了。"},{"name":"不要压制","say":"（字幕：不要说「有什么好哭的」）"}],"reactions":[{"if":"孩子哭到说不出话","then":"先抱着，什么都不要求。等呼吸平稳了再说那句话。"},{"if":"孩子说了还是继续哭","then":"完全正常。说出来和不哭是两件事，先肯定他说出来了。"},{"if":"孩子把难过藏起来说没事","then":"不拆穿。说一句「如果想说随时可以跟我说」，把门留着。"}],"mistakes":["一开口就说「不要哭」，感受被否定了。","要求孩子先停止哭才愿意听他说。","用「这有什么好难过的」比较他的感受。"],"down":"不要求说话，只要点头承认「你很难过对不对」就算成功。","up":"主动说出难过和原因：「我难过，因为他不跟我玩。」","progress":["难过时会不会点头承认。","会不会说出「我难过」。","能不能说出难过的原因。"],"outro":"先共情，再引导，说了就立刻抱住。要让他知道——说出来，妈妈一样会来，而且更快。"}' AS JSON))
WHERE `id` = 'A187';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '害怕时会说出来、会找大人，是重要的自我保护。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子害怕时先保护「妈妈在」。"},{"imageUrl":null,"instruction":"引导他说「我害怕」。"},{"imageUrl":null,"instruction":"说了就抱紧、陪伴。"},{"imageUrl":null,"instruction":"聊聊「什么时候会害怕」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '躲向大人'),
  `harder` = COALESCE(`harder`, '说出「我害怕××」。'),
  `tip` = COALESCE(`tip`, '别说「这有什么好怕的」——被嘲笑的害怕会藏起来，被接住的害怕会变小。害怕被接纳，孩子才敢面对。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组三（情绪表达·说出感受）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"会说「我害怕」、会跑向大人——这不是胆小，这是很重要的自我保护能力。","principles":["害怕是保护机制，它让人远离危险，本身是好事。","会表达害怕的孩子，比较容易在危险来临时求助。","所以我们不教孩子「不要怕」，而是教他「怕了要说、要找大人」。","第一步永远是保护：「妈妈在。」先给安全感，再谈其他。","安全感不足的时候，孩子没办法学任何东西。","他说了「我害怕」就要抱紧、陪着，让求助真的有用。","事后在平静时聊「什么时候会害怕」，把恐惧具体化。","说得出来的恐惧，比说不出来的好处理很多。","绝对不要嘲笑孩子的害怕，被笑过的孩子下次就不说了。"],"prep":{"场地":"孩子害怕的当下；事后讨论选在明亮、安全的地方。","器材":"不需要任何东西。","安全检查":"不用吓唬的方式做「脱敏」；孩子出现持续、影响生活的恐惧应寻求专业评估。","大人位置":"大人靠近、蹲下，身体接触（牵手或搂肩）先建立安全感。"},"shots":[{"name":"孩子害怕","say":"（听到大声响，孩子往大人身后躲）"},{"name":"先保护","say":"妈妈在。"},{"name":"引导说出来","say":"你可以说：我害怕。"},{"name":"说了就抱紧","say":"（孩子说出来，大人抱紧）"},{"name":"事后聊聊","say":"什么时候你会害怕呢？"},{"name":"不嘲笑","say":"（字幕：不要说「这有什么好怕的」）"}],"reactions":[{"if":"孩子怕到说不出话","then":"先抱紧、先陪着。等身体放松了再说，不急着要他开口。"},{"if":"孩子怕的东西大人觉得没什么","then":"仍然要接住。对他来说是真的可怕，感受不需要合理。"},{"if":"孩子怕到不敢去某些地方","then":"不硬推。一小步一小步陪着靠近，每一步都让他有退路。"}],"mistakes":["说「这有什么好怕的」，孩子学会不说。","用恐吓当管教工具（再不听话就让警察抓走），会破坏安全感。","强迫孩子面对害怕的东西，反而加深恐惧。"],"down":"不要求说话，只要他会跑向大人求助就算成功。","up":"说出具体的害怕对象：「我害怕黑黑的房间」，并一起想办法（开小灯）。","progress":["害怕时会不会找大人。","会不会说出「我害怕」。","能不能说出害怕的是什么。"],"outro":"会说害怕、会找大人，这是自我保护，不是胆小。绝对不要笑他怕的东西——被笑过一次，他下次就不说了。"}' AS JSON))
WHERE `id` = 'A188';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '觉察情绪来的时候身体的变化。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"聊「生气的时候，你的身体有什么感觉？」"},{"imageUrl":null,"instruction":"帮他找词：手握紧、脸热热、心跳快、想大叫。"},{"imageUrl":null,"instruction":"害怕时（腿软、想躲）、开心时（想跳）也聊。"},{"imageUrl":null,"instruction":"情绪来时引导「摸摸看，拳头是不是握紧了？」"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出一个身体感觉'),
  `harder` = COALESCE(`harder`, '说出好几个身体信号。'),
  `tip` = COALESCE(`tip`, '身体的变化是情绪的「预报」——在爆发前就能发现它。说不出「我生气」的孩子，说「我的手好紧」也很棒。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"情绪来之前，身体会先有反应——拳头握紧、脸热热的、心跳变快。学会读这些信号，就能在爆炸之前先踩煞车。","principles":["情绪不是突然出现的，身体通常会先给信号。","拳头握紧、脸变热、心跳加快、想大叫，都是生气的早期信号。","孩子如果能觉察这些信号，就有机会在爆炸前先处理。","这是情绪调节的关键一步：从「事后收拾」变成「事前拦截」。","要练这个，得先在平静的时候把词准备好。","帮他找词：手握紧、脸热热、心跳快、肚子怪怪的。","有了词，情绪来的时候他才描述得出自己的状态。","不只负面情绪，害怕（腿软、想躲）和开心（想跳、坐不住）也一起聊。","情绪来的当下引导他摸摸自己：「拳头是不是握紧了？」把觉察变成动作。"],"prep":{"场地":"平静时的讨论在舒服的地方；实际觉察则在情绪发生的当下。","器材":"不需要任何东西；可用纸笔画一个人形标注身体感觉。","安全检查":"无特殊风险。不在孩子暴怒当下做长篇讨论，只做一句提示。","大人位置":"大人坐在孩子旁边，可以摸到他的手和肩膀。"},"shots":[{"name":"平静时先聊","say":"生气的时候，你的身体有什么感觉？"},{"name":"帮他找词","say":"手会握紧？脸会热热的？心跳很快？"},{"name":"画在人形上","say":"我们把它画下来。"},{"name":"害怕的身体","say":"害怕的时候呢？腿软软的？想躲起来？"},{"name":"开心的身体","say":"开心的时候会想跳、坐不住。"},{"name":"情绪来时提示","say":"摸摸看，拳头是不是握紧了？"}],"reactions":[{"if":"孩子说不出身体感觉","then":"由你先说自己的：「我生气的时候胸口会闷闷的。」示范之后他比较说得出来。"},{"if":"孩子在情绪当下不理会提示","then":"只说一次就好，不重复。事后平静时再回顾。"},{"if":"孩子说的身体感觉很奇怪","then":"接受。每个人的身体信号不一样，他说的就是他的。"}],"mistakes":["在孩子暴怒当下做长篇的身体觉察教学。","替孩子决定他应该有什么感觉。","只谈生气，没有谈害怕和开心的身体感觉。"],"down":"只找一个身体信号（拳头握紧），并由大人握着他的手让他感觉。","up":"能说出三个以上的身体信号，并在情绪刚起来时自己发现。","progress":["能不能说出至少一个身体感觉。","情绪来时经提示会不会去感觉身体。","有没有开始自己发现身体的变化。"],"outro":"情绪来之前，身体会先说话。平静的时候把词准备好，情绪来的时候只要提示一句：摸摸看，拳头是不是握紧了？"}' AS JSON))
WHERE `id` = 'A189';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸笔（画一个温度计）'),
  `trains` = COALESCE(`trains`, '知道情绪有大有小，学会分级。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"画一个温度计，从1（有一点）到5（很大很大）。"},{"imageUrl":null,"instruction":"举例：被碰一下＝1分生气；玩具被抢＝4分生气。"},{"imageUrl":null,"instruction":"请孩子给事情打分。"},{"imageUrl":null,"instruction":"情绪来时问「现在几分？」"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '分成「大」和「小」两级'),
  `harder` = COALESCE(`harder`, '用1到5打分。'),
  `tip` = COALESCE(`tip`, '很多孩子的情绪是「全有或全无」——一来就满分。温度计把程度变得看得见，能分级才谈得上「怎么降一格」。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子常常小事也大爆炸，因为在他的世界里情绪只有「有」和「没有」。今天我们给情绪装上刻度。","principles":["情绪有强度差别，但孩子一开始感受不到这个差别。","所以一点小事和一件大事，他的反应可能一样激烈。","把情绪画成温度计，从1到5，抽象的强度就变成看得见的刻度。","有了刻度，孩子才能开始区分「有一点生气」和「非常生气」。","举具体的例子来对应分数，孩子才知道刻度怎么用。","被碰一下是1分，玩具被抢是4分——例子越贴近生活越好。","请孩子自己给事情打分，是在练自我评估。","情绪来的时候问一句「现在几分」，能把注意力从情绪拉到观察上。","这个转换本身就有降温的效果，因为思考会抑制情绪冲动。"],"prep":{"场地":"桌边，两人一起画得到的位置。","器材":"纸和笔，画一个从1到5的温度计；可以贴在墙上长期使用。","安全检查":"无特殊风险。不用分数评价孩子（不说「你太容易5分了」）。","大人位置":"大人和孩子一起画，让他参与上色和标记。"},"shots":[{"name":"一起画温度计","say":"我们来画一个心情温度计。"},{"name":"举小分数的例子","say":"不小心被碰一下，大概几分？"},{"name":"举大分数的例子","say":"玩具被抢走呢？"},{"name":"换他打分","say":"那排队要等很久是几分？"},{"name":"贴在墙上","say":"我们把它贴起来。"},{"name":"情绪来时问几分","say":"现在几分？"}],"reactions":[{"if":"孩子什么事都说5分","then":"先接受。再问「那上次积木倒了是几分？」用比较帮他分出差别。"},{"if":"孩子不理解分数","then":"改成「大生气」和「小生气」两级，先有差别的概念再谈刻度。"},{"if":"孩子在情绪当下不肯回答","then":"不追问。事后平静时再一起回顾那件事是几分。"}],"mistakes":["用分数评价孩子（你怎么什么都5分），温度计变成批评工具。","一开始就用1到5，对小小孩太细，先用大小两级。","只在孩子爆炸时才拿出来，平时没有练过就用不出来。"],"down":"只分「大」和「小」两级，用手比大小就可以，不用数字。","up":"用1到5打分，并能说出「因为……所以是4分」的理由。","progress":["能不能区分大生气和小生气。","会不会用数字给事情打分。","情绪来时问得出「现在几分」吗。"],"outro":"先在平静的时候练熟刻度，情绪来的时候才问得出「现在几分」。问这一句本身，就已经在降温了。"}' AS JSON))
WHERE `id` = 'A190';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸笔或照片'),
  `trains` = COALESCE(`trains`, '把情绪和引发它的事连起来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"聊「什么事会让你开心？」"},{"imageUrl":null,"instruction":"列出「我的开心清单」（画的也行）。"},{"imageUrl":null,"instruction":"看照片回忆开心的时刻。"},{"imageUrl":null,"instruction":"贴在墙上，心情不好时拿出来看。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说一件开心事'),
  `harder` = COALESCE(`harder`, '说出好几件，并说「因为……」。'),
  `tip` = COALESCE(`tip`, '「开心清单」不只是练情绪认知，还是情绪低落时的「快乐处方」——不知道要做什么，就照清单挑一件。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"做一张「我的开心清单」，贴在墙上。心情不好的时候拿出来看——这是孩子自己的情绪急救包。","principles":["把情绪和引发它的事连起来，孩子才知道情绪是有来源的。","知道来源，才有机会主动去制造好心情。","列开心清单的过程，本身就是一次愉快的回忆重温。","回忆开心的事会真的带来正向情绪，这不只是心理作用。","写不出来可以用画的，或直接贴照片，形式不重要。","贴在墙上是关键：心情不好时看得到，才用得上。","这是孩子自己的资源清单，日后难过时可以从中挑一件来做。","常常加新的进去，清单会跟着他一起长大。","进阶是说出「因为……」，把情绪和原因的连结讲清楚。"],"prep":{"场地":"桌边或地板，有空间摊开纸张。","器材":"大张纸、笔、贴纸；有照片更好。","安全检查":"使用无毒画笔；剪贴由大人操作剪刀。","大人位置":"大人和孩子一起写、一起画，大人也列自己的清单。"},"shots":[{"name":"开场提问","say":"什么事情会让你很开心？"},{"name":"一件一件列","say":"（孩子说，大人写或他自己画）"},{"name":"用画的也可以","say":"不会写就画出来。"},{"name":"贴照片回忆","say":"你看，这是上次去海边。"},{"name":"贴在墙上","say":"我们贴在这里。"},{"name":"心情不好时拿出来","say":"心情不好的时候，来看看这张。"}],"reactions":[{"if":"孩子只想得到一两件","then":"由大人提示：「上次去公园呢？吃冰淇淋呢？」提示之后通常会源源不绝。"},{"if":"孩子列的都是买东西","then":"先全部接受。再问「有没有不用买东西也很开心的？」慢慢扩。"},{"if":"孩子不想写","then":"改成大人写、他口述，或全部用照片贴。"}],"mistakes":["大人替孩子决定什么事应该让他开心。","列完就收起来，没有贴出来就用不上。","要求孩子写字，写字变成障碍，乐趣就没了。"],"down":"只说一件开心的事，由大人画下来贴起来。","up":"列出五件以上并说出「因为……」，还能在心情不好时自己挑一件去做。","progress":["能说出几件开心的事。","会不会说出为什么开心。","心情不好时会不会想到去看清单。"],"outro":"一定要贴在墙上——看得到才用得上。心情不好的时候，让他自己挑一件去做，这就是他的情绪急救包。"}' AS JSON))
WHERE `id` = 'A191';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '在平静时聊聊什么会让他生气难过。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在心情好的时候聊「什么事会让你生气？」"},{"imageUrl":null,"instruction":"接纳地听，不评论、不说教。"},{"imageUrl":null,"instruction":"帮他说清楚「因为……所以你难过」。"},{"imageUrl":null,"instruction":"告诉他「大家都会有难过生气的时候」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出一件事'),
  `harder` = COALESCE(`harder`, '说清原因，并知道这很正常。'),
  `tip` = COALESCE(`tip`, '要在「平静的时候」聊，不是爆炸当下——当下只需要陪伴，聊天留到后来。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"要聊不开心的事，一定要挑心情好的时候聊。今天示范怎么问，以及更重要的——怎么忍住不说教。","principles":["情绪来的当下，孩子说不清楚，大人也听不下去。","所以关于不开心的讨论，要挑双方都平静的时候进行。","平静时聊，孩子才有能力回想和描述。","接纳地听，不评论也不说教，是这个活动最难的部分。","一旦开始说教，孩子下次就只会说安全的事。","帮他把话说清楚：「因为他抢了你的车，所以你很生气。」","这个句型同时练了因果表达，也让感受被确认。","最后一定要告诉他：大家都会有难过生气的时候，这很正常。","知道自己的情绪是正常的，孩子才不会因为有情绪而自责。"],"prep":{"场地":"安静舒服的地方，睡前或周末散步时都合适。","器材":"不需要任何东西。","安全检查":"孩子提到被欺负、被伤害的事要认真对待并后续追踪；不在这个情境处理管教问题。","大人位置":"大人坐在孩子旁边或并肩走，不正面盯着他，压力较小。"},"shots":[{"name":"挑心情好的时候","say":"（阳光下散步，气氛轻松）"},{"name":"开口问","say":"什么事情会让你生气呢？"},{"name":"接纳地听","say":"（孩子说，大人点头不插话）"},{"name":"帮他说清楚","say":"因为他抢了你的车，所以你很生气。"},{"name":"忍住不说教","say":"（大人张口又停住，只是点头）"},{"name":"这很正常","say":"大家都会有生气难过的时候。"}],"reactions":[{"if":"孩子说不出来","then":"由大人举例：「像是有人插队的时候？」用具体情境勾出来。"},{"if":"孩子说的事让你很想纠正","then":"先记下来，今天只听。管教留到别的时间，不要混在一起。"},{"if":"孩子说到一半情绪上来","then":"停下来先安抚。今天聊到这里就好，不必聊完。"}],"mistakes":["在孩子正在生气时问他为什么生气。","听完立刻检讨他的行为，这个对话就废了。","说「那是你自己的问题」，孩子会关上门。"],"down":"只说出一件让他不开心的事，不要求说原因。","up":"说清楚事情经过和原因，并能说出当时身体和心里的感觉。","progress":["愿不愿意说出不开心的事。","能不能说出原因。","知不知道有这些情绪是正常的。"],"outro":"两个原则：挑心情好的时候聊，听完不要说教。今天只负责听——管教留到别的时间，不要混在一起。"}' AS JSON))
WHERE `id` = 'A192';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本'),
  `trains` = COALESCE(`trains`, '在故事里认情绪，是最安全的情绪课。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"读绘本时停下来问「他现在什么感觉？」"},{"imageUrl":null,"instruction":"从画面找线索（表情、动作）。"},{"imageUrl":null,"instruction":"问「他为什么难过？」"},{"imageUrl":null,"instruction":"再问「如果是你，你会怎样？」"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '认出明显的情绪'),
  `harder` = COALESCE(`harder`, '从情节推断情绪和原因。'),
  `tip` = COALESCE(`tip`, '绘本把情绪「定格」下来慢慢看，还连着原因和后果——每天共读时多问一句，就是一堂情绪课。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"绘本是最安全的情绪课——因为难过的是书里的角色，不是他。孩子可以放心地讨论。","principles":["谈自己的情绪有压力，谈别人的情绪没有。","所以绘本是最好的入口：角色的情绪可以被安全地讨论。","读到情绪转折处停下来问「他现在什么感觉」，把注意力带到情绪上。","再从画面找线索（表情、动作、姿势），教他情绪是可以观察的。","问「他为什么难过」，就从辨认进到了推理。","最后一句「如果是你，你会怎样」，把故事连回他自己的经验。","这一步是关键，否则学到的东西留在书里出不来。","同一本书可以读很多次，每次问的问题可以不一样。","孩子会自然地把书中角色的处理方式拿来用在自己身上。"],"prep":{"场地":"沙发或床边，两人并肩看同一本书。","器材":"一本有明显情绪起伏的绘本。","安全检查":"避免情节过于悲伤或惊吓的绘本，尤其在睡前阅读时。","大人位置":"大人拿书，读到情绪转折处停下来，手指可以点到角色的脸。"},"shots":[{"name":"读到情绪处停下","say":"（读绘本，停在角色难过的那一页）"},{"name":"问感觉","say":"他现在什么感觉？"},{"name":"找线索","say":"你怎么知道？看他的嘴巴、看他的肩膀。"},{"name":"问原因","say":"他为什么难过？"},{"name":"连回自己","say":"如果是你，你会怎样？"},{"name":"同一本读很多次","say":"（快剪同一本书在不同日子被读）"}],"reactions":[{"if":"孩子答不出角色的情绪","then":"给二选一：「他是开心还是难过？」并指出画面中的线索。"},{"if":"孩子说不出原因","then":"翻回前一页：「刚刚发生了什么事？」帮他把因果接起来。"},{"if":"孩子不想被打断","then":"那就读完再问。一本书只停一两次，不要破坏阅读的乐趣。"}],"mistakes":["每一页都停下来问，阅读变成考试。","只问情绪不问原因，停在辨认层次。","没有连回孩子自己的经验，学到的东西用不出来。"],"down":"只问「他开心还是难过」，并由大人指出画面中的线索。","up":"从情节推断情绪（画面没有明显表情时），并说出角色可能会怎么做。","progress":["能不能说出角色的情绪。","会不会说出判断的线索。","能不能说出情绪的原因。"],"outro":"绘本最安全，因为难过的是书里的角色。但记得最后一定要问一句：如果是你，你会怎样？"}' AS JSON))
WHERE `id` = 'A193';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要（观察真实的人）'),
  `trains` = COALESCE(`trains`, '养成留意别人心情的习惯。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"生活中问「你看妹妹现在开心吗？」"},{"imageUrl":null,"instruction":"问「你怎么知道的？」（她在笑）。"},{"imageUrl":null,"instruction":"留意家人的状态：「爸爸今天好像很累」。"},{"imageUrl":null,"instruction":"猜对猜错都好，重点是「去看」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '判断明显的开心难过'),
  `harder` = COALESCE(`harder`, '看出累了、无聊了这些细微状态。'),
  `tip` = COALESCE(`tip`, '同理心的第一步不是技巧，是「习惯性地看一眼别人」——每天问一句，慢慢就成了习惯。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十（理解他人·观点与同理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"从书里走到真实的人。今天的练习只有一件事：养成「去看别人现在怎么样」的习惯。","principles":["留意别人的情绪，是社交能力的地基。","很多孩子不是不在乎别人，是根本没有想到要去看。","所以要练的不是判断准不准，而是「有没有去看」。","在生活中随口问一句「你看妹妹现在开心吗」，就是在启动这个习惯。","接着问「你怎么知道的」，让他说出判断的依据。","说得出依据，这个能力才能迁移到新的人和新的情境。","也要留意家人的状态：「爸爸今天好像很累。」示范给他看。","猜对猜错都好，重点是他有去注意、有去想。","进阶是看出累了、无聊了这种细微状态，那难度高很多。"],"prep":{"场地":"家里或户外，有其他人在的场合。","器材":"不需要任何东西，观察真实的人。","安全检查":"不在当事人面前大声评论他人情绪；不对陌生人指指点点。","大人位置":"大人在孩子旁边，用轻松的语气随口问，不要像在考试。"},"shots":[{"name":"随口问一句","say":"你看妹妹现在开心吗？"},{"name":"孩子判断","say":"（孩子说「开心」）"},{"name":"问依据","say":"你怎么知道的？"},{"name":"他说出线索","say":"（孩子说「她在笑」）对，她在笑。"},{"name":"示范留意家人","say":"爸爸今天好像很累。"},{"name":"猜错也没关系","say":"（孩子猜错，大人笑着说没关系）"}],"reactions":[{"if":"孩子完全没注意别人","then":"从最亲近、表情最明显的家人开始问，成功率最高。"},{"if":"孩子判断错误","then":"不纠正对错，一起再看一次：「我们再看看，她的嘴巴是什么样子？」"},{"if":"孩子说不出依据","then":"由你先说：「我觉得她开心，因为她在笑。」示范判断的语言。"}],"mistakes":["把它变成考试，一直问一直考。","在当事人面前大声讨论他的情绪，会让人不舒服。","只问判断不问依据，能力就迁移不出去。"],"down":"只判断表情非常明显的人（正在大笑或正在哭）。","up":"看出累了、无聊了、有点烦这类细微状态，并说出判断的线索。","progress":["会不会主动去看别人。","判断明显情绪的准确度。","能不能说出判断的依据。"],"outro":"重点不是猜得准，是有没有去看。问完记得再问一句「你怎么知道的」——说得出依据，这个能力才带得走。"}' AS JSON))
WHERE `id` = 'A194';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本或真实情境'),
  `trains` = COALESCE(`trains`, '想想别人情绪背后的原因。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"看到有人有情绪时问「他为什么难过？」"},{"imageUrl":null,"instruction":"一起找原因（东西掉了、被骂了）。"},{"imageUrl":null,"instruction":"用「因为……所以他……」说出来。"},{"imageUrl":null,"instruction":"不确定就一起猜几种可能。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '明显的原因'),
  `harder` = COALESCE(`harder`, '需要推理的原因。'),
  `tip` = COALESCE(`tip`, '知道情绪有原因，别人的哭闹就不再莫名其妙——也才知道该怎么帮他。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十（理解他人·观点与同理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"看出别人难过是第一步，想出他为什么难过是第二步。这一步，就是同理心开始的地方。","principles":["从辨认情绪进到推理原因，是同理心发展的关键一步。","孩子必须把观察到的情绪和前面发生的事连起来。","这需要记得刚才发生什么，还要判断哪一件事是原因。","用「因为……所以他……」的句型说出来，思路会更清楚。","这个句型同时练到因果表达，和语言课的内容是同一条肌肉。","不确定的时候一起猜几种可能，示范「我也不确定」是可以的。","这很重要：真实世界里我们常常不知道别人为什么难过。","能想出几种可能，比硬要一个正确答案更接近真实的同理。","绘本和真实情境都可以用，真实情境的效果更直接。"],"prep":{"场地":"绘本阅读时，或生活中遇到有人有情绪的场合。","器材":"绘本；或利用真实情境，不需要道具。","安全检查":"讨论真实的人时压低音量、不在当事人面前；不猜测涉及隐私的原因。","大人位置":"大人在孩子旁边，用讨论的语气而非考试的语气。"},"shots":[{"name":"看到有人难过","say":"你看，那个小朋友好像在哭。"},{"name":"问原因","say":"他为什么难过？"},{"name":"一起找线索","say":"刚刚发生了什么事？"},{"name":"用句型说出来","say":"因为气球飞走了，所以他很难过。"},{"name":"不确定就猜几种","say":"也可能是跌倒了，或是找不到妈妈。"},{"name":"真实情境也用","say":"（生活中低声讨论）"}],"reactions":[{"if":"孩子说不出原因","then":"把范围缩到两个可能让他选，选完问一句「为什么这样想」。"},{"if":"孩子的推理不合理","then":"不否定。说「也有可能」，再提出另一种可能让他比较。"},{"if":"孩子对别人的情绪没兴趣","then":"换成他在意的人（好朋友、家人），动机会高很多。"}],"mistakes":["一定要一个标准答案，真实世界并没有。","在当事人面前大声讨论，不礼貌也是坏示范。","只问原因不给线索，孩子无从推起。"],"down":"原因非常明显的情境（东西掉了、跌倒了），并给两个选项。","up":"需要推理的情境（没有直接线索），并能提出两种以上的可能。","progress":["能不能说出明显的原因。","会不会用「因为……所以……」说出来。","不确定时能不能提出几种可能。"],"outro":"不一定要有标准答案。不确定的时候一起猜几种可能——真实世界里，我们本来就常常不知道别人为什么难过。"}' AS JSON))
WHERE `id` = 'A195';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '绘本或生活小事'),
  `trains` = COALESCE(`trains`, '把自己放进别人的处境，体会对方的感受。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"看到情境（别人的气球飞走了）问「如果是你的气球飞了，你什么感觉？」"},{"imageUrl":null,"instruction":"他说出感受后连回去「他现在就是这种感觉」。"},{"imageUrl":null,"instruction":"正面的事也用：「如果你收到礼物呢？」"},{"imageUrl":null,"instruction":"随时随地都能问。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出自己会难过'),
  `harder` = COALESCE(`harder`, '主动连结「所以他也难过」。'),
  `tip` = COALESCE(`tip`, '「如果是你呢？」这五个字，是随身携带的同理心开关——自己的感受，就是理解别人的字典。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十（理解他人·观点与同理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"同理心不是天生的，是练出来的。练的方法只有一句话：如果是你，你什么感觉？","principles":["同理心的核心动作，是把自己放进别人的处境。","孩子最容易理解的是自己的感受，所以从自己出发最有效。","「如果是你的气球飞走了，你什么感觉？」他一下子就懂了。","他说出自己的感受之后，一定要连回去：「他现在就是这种感觉。」","这一步是关键，否则只练到想自己，没有连到别人。","正面的事也要用：「如果你收到礼物呢？」同理不只用在难过上。","这个问题随时随地都能问，不需要任何准备。","问得多了，孩子会开始自己做这个转换。","能主动说出「所以他也很难过」，就代表同理心真的长出来了。"],"prep":{"场地":"任何场合：读绘本时、路上看到、听别人说事情时。","器材":"不需要任何东西。","安全检查":"无特殊风险。不用负面情境反复让孩子代入，避免过度共感造成负担。","大人位置":"大人在孩子旁边，语气是好奇不是考试。"},"shots":[{"name":"看到一个情境","say":"你看，他的气球飞走了。"},{"name":"问如果是你","say":"如果是你的气球飞走了，你什么感觉？"},{"name":"他说出感受","say":"（孩子说「我会很难过」）"},{"name":"连回去","say":"对，他现在就是这种感觉。"},{"name":"正面的也用","say":"如果你收到礼物呢？那他一定很开心。"},{"name":"随时都能问","say":"（快剪几个不同场景都问同一句）"}],"reactions":[{"if":"孩子说「我不会难过」","then":"接受。再问「那你什么时候会难过？」从他自己的经验找连结点。"},{"if":"孩子说完就不管别人了","then":"由你把连结说出来：「所以他现在也很难过对不对？」多示范几次。"},{"if":"孩子对负面情境代入太深","then":"停一下，换个正面的情境，不要让他一直泡在难过里。"}],"mistakes":["只问「如果是你」，没有连回对方，同理就断在半路。","一直用难过的情境，孩子会觉得这个游戏很沉重。","用道德评价代替同理（你要懂得体谅别人）。"],"down":"用他亲身经历过的类似事件来问，代入最容易。","up":"不用提问就能主动说出「他一定很难过」，并在真实冲突中用得上。","progress":["能不能说出自己在那个处境的感受。","经提示会不会连回对方。","有没有开始主动说出对方的感受。"],"outro":"问完「如果是你」，一定要接一句「他现在就是这种感觉」。少了这一句，就只练到想自己，没有连到别人。"}' AS JSON))
WHERE `id` = 'A196';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '玩偶（演练用）'),
  `trains` = COALESCE(`trains`, '学几句安慰人的话。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"用玩偶演「小熊摔倒哭了」。"},{"imageUrl":null,"instruction":"教三句：「你还好吗？」「别难过」「我陪你」。"},{"imageUrl":null,"instruction":"对玩偶练、对家人练。"},{"imageUrl":null,"instruction":"真的有人难过时提醒他用。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说一句安慰话'),
  `harder` = COALESCE(`harder`, '看情况选合适的话。'),
  `tip` = COALESCE(`tip`, '也告诉孩子：不知道说什么的时候，轻轻拍拍、递张纸巾、坐在旁边陪着，都是很好的安慰。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十（理解他人·观点与同理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"看到别人难过，孩子常常愣在那里——不是冷漠，是不知道要说什么。今天给他三句话。","principles":["想安慰别人却不知道怎么开口，是很多孩子的真实处境。","给他现成的句子，就是给他一个可以立刻用的工具。","三句就够：「你还好吗？」「别难过。」「我陪你。」","这三句涵盖了关心、安抚和陪伴三种功能。","用玩偶演练最好，因为对玩偶说话完全没有压力。","演练过的话，真实情境中才叫得出来。","对家人练是第二步，真实但安全。","真的有人难过时提醒他用，但不要逼他一定要说。","陪在旁边不说话也是一种安慰，这一点要让他知道。"],"prep":{"场地":"客厅地板，两人和玩偶围坐。","器材":"一两个玩偶。","安全检查":"玩偶无小零件脱落风险；不强迫孩子去安慰正在崩溃的人。","大人位置":"大人操作玩偶，先示范一次完整的安慰。"},"shots":[{"name":"玩偶摔倒了","say":"小熊跌倒了，呜呜——"},{"name":"示范第一句","say":"你还好吗？"},{"name":"第二句","say":"别难过。"},{"name":"第三句","say":"我陪你。"},{"name":"换他安慰玩偶","say":"换你安慰小熊。"},{"name":"陪着也是安慰","say":"不知道说什么，就坐在旁边陪他。"}],"reactions":[{"if":"孩子不知道说哪一句","then":"先固定用一句（你还好吗），熟了再加。三句一起太多。"},{"if":"孩子安慰的方式很笨拙","then":"不纠正。心意到了就好，技巧会慢慢变好。"},{"if":"孩子不愿意去安慰别人","then":"不勉强。告诉他「你想的时候再去」，也可以先只是陪着。"}],"mistakes":["逼孩子去安慰正在崩溃的人，两边都会更糟。","嫌孩子说得不好，下次他就不说了。","只教说话，没教「陪着也是一种安慰」。"],"down":"只教一句「你还好吗」，并且只对玩偶练。","up":"看情况选合适的话，并能加上动作（拍拍肩、递面纸）。","progress":["会不会对玩偶说出安慰的话。","会不会对家人说。","真实情境中会不会主动去关心。"],"outro":"三句话就够：你还好吗、别难过、我陪你。还有一句最重要——不知道说什么的时候，坐在旁边陪着也是安慰。"}' AS JSON))
WHERE `id` = 'A197';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸笔或贴纸'),
  `trains` = COALESCE(`trains`, '每天记录心情，养成觉察的习惯。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"做一张心情表，每天贴一个表情。"},{"imageUrl":null,"instruction":"睡前打卡「今天什么心情？」"},{"imageUrl":null,"instruction":"简单聊聊「为什么是这个心情」。"},{"imageUrl":null,"instruction":"一周回顾一次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '选一个表情'),
  `harder` = COALESCE(`harder`, '说出心情和原因。'),
  `tip` = COALESCE(`tip`, '每天两分钟，情绪觉察就成了习惯。不评价孩子的心情——只是看见，不需要「今天为什么不开心，你应该……」。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"每天睡前贴一个表情，一周回顾一次。这张表会让孩子第一次看见——原来我的心情是有变化的。","principles":["每天记录心情，会把觉察这件事变成习惯。","习惯比技巧重要，因为情绪管理是长期的事。","贴表情比写字容易太多，年纪小的孩子也做得到。","睡前打卡的时间固定，和睡前分享可以接在一起。","贴完简单聊两句「为什么是这个心情」，就连到了原因。","一周回顾一次，孩子会看到心情是会变的，不是永远这样。","这个发现对情绪低落的孩子特别重要：难过会过去。","也能看出规律：星期一都不太好，可能和上学有关。","这些规律对大人来说是很有用的线索。"],"prep":{"场地":"床边或墙上固定的位置，每天看得到。","器材":"一张画好格子的心情表、表情贴纸或彩色笔。","安全检查":"无特殊风险。不因为贴了负面表情而责备或追问过久。","大人位置":"大人和孩子一起贴，大人也贴自己的那一栏。"},"shots":[{"name":"做一张心情表","say":"我们来做一张心情表。"},{"name":"睡前打卡","say":"今天什么心情？"},{"name":"贴上去","say":"（贴上一个笑脸）"},{"name":"聊两句","say":"为什么是这个心情呢？"},{"name":"大人也贴","say":"我今天是这个。"},{"name":"一周回顾","say":"你看，这一周有开心也有不开心。"}],"reactions":[{"if":"孩子每天都贴同一个","then":"不追问。可以问「有没有哪一刻不太一样？」慢慢拉出细节。"},{"if":"孩子连续贴负面表情","then":"温和地多陪伴，并观察是否有具体事件。持续两周以上建议寻求专业协助。"},{"if":"孩子忘记贴","then":"不责备。补贴或跳过都可以，维持轻松才持续得下去。"}],"mistakes":["看到负面表情就追问或说教，孩子下次只敢贴笑脸。","规定每天一定要贴，变成作业就不想做了。","只让孩子贴，大人不贴，少了示范也少了亲近感。"],"down":"只用两种表情（笑脸／哭脸），一天贴一个就好。","up":"使用更多种表情并写下一句原因，一周回顾时自己说出规律。","progress":["会不会每天主动去贴。","选的表情有没有变化（代表觉察变细）。","能不能说出为什么是这个心情。"],"outro":"一周回顾的时候，让他自己看整张表——有开心也有不开心，这就是最重要的一课：心情会变，难过会过去。"}' AS JSON))
WHERE `id` = 'A198';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '建立一个重要的观念：情绪没有对错。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"告诉孩子：每个人都会生气、难过、害怕，这很正常。"},{"imageUrl":null,"instruction":"大人也分享自己的情绪：「妈妈今天很烦」。"},{"imageUrl":null,"instruction":"强调「感觉没有对错，但做法有」。"},{"imageUrl":null,"instruction":"「可以生气，但不可以打人」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '知道大家都会有情绪'),
  `harder` = COALESCE(`harder`, '能区分「感觉」和「行为」。'),
  `tip` = COALESCE(`tip`, '大人愿意说自己的情绪，孩子才敢说他的。这个观念是所有情绪教育的地基：**感受都可以，行为要选择**。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二（情绪认识·辨识与命名）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"这一支影片只讲一件事，但它是整个模组最重要的一课：感觉没有对错，但做法有。","principles":["很多孩子会因为自己生气、害怕而觉得自己不好。","那是因为大人常说「不可以生气」「这有什么好怕的」。","情绪本身没有对错，它只是身体的反应，不需要被审判。","需要被规范的是行为，不是感觉。","所以那条线要说得非常清楚：可以生气，但不可以打人。","把感觉和行为分开，孩子才不会因为有情绪而自责。","大人也要分享自己的情绪：「妈妈今天很烦。」","看到大人也会有情绪、也能好好处理，孩子学到的是完整的示范。","这一课立得住，后面所有的情绪处理技巧才有地基。"],"prep":{"场地":"安静舒服的地方，睡前或饭后都合适。","器材":"不需要任何东西。","安全检查":"无特殊风险。大人分享自己的情绪时避免涉及夫妻冲突或让孩子担忧的内容。","大人位置":"大人坐在孩子旁边，语气平常，不严肃也不说教。"},"shots":[{"name":"说出核心讯息","say":"每个人都会生气、难过、害怕，这很正常。"},{"name":"大人也分享","say":"妈妈今天也很烦。"},{"name":"孩子的反应","say":"（孩子惊讶地看着大人）"},{"name":"感觉没有对错","say":"感觉没有对错——"},{"name":"做法有","say":"但做法有。可以生气，不可以打人。"},{"name":"大人的示范","say":"我很烦的时候，会先去阳台站一下。"}],"reactions":[{"if":"孩子说「那我可以一直生气吗」","then":"可以。生气可以一直有，但打人不行。把两件事再说一次分清楚。"},{"if":"孩子觉得大人不会有情绪","then":"那更要分享。说一件今天真实的小烦恼就好，不必是大事。"},{"if":"孩子用「情绪是正常的」当借口","then":"温和地重申：感觉正常，行为还是有界线，两件事不冲突。"}],"mistakes":["说「不可以生气」，把感觉本身变成错的。","大人从不承认自己有情绪，孩子会以为只有他这样。","分享自己的情绪时讲得太重，让孩子担忧。"],"down":"只讲一句：「每个人都会生气，这很正常。」不谈行为界线。","up":"能自己说出「我可以生气，但我不可以打人」，并举出自己的处理方式。","progress":["知不知道每个人都会有情绪。","能不能区分「感觉」和「做法」。","有没有因为自己有情绪而自责。"],"outro":"整个模组最重要的一句话：感觉没有对错，但做法有。可以生气，不可以打人——这条线要一直很清楚。"}' AS JSON))
WHERE `id` = 'A199';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '表情卡、镜子、绘本'),
  `trains` = COALESCE(`trains`, '把这个模组的能力串起来练一轮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：认出四种表情。"},{"imageUrl":null,"instruction":"第二关：说出「我现在觉得……」。"},{"imageUrl":null,"instruction":"第三关：说出生气时身体的感觉。"},{"imageUrl":null,"instruction":"第四关：看绘本说出角色的心情和原因。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关给提示'),
  `harder` = COALESCE(`harder`, '独立完成，并说出原因。'),
  `tip` = COALESCE(`tip`, '认得出情绪、说得出感受，孩子才有可能管理情绪。这一步走稳了，下一个模组就来学「情绪来了怎么办」。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组二～三（情绪认识 · 情绪表达）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"这是模组十的总复习，四关走一遍。走完你会知道——他在哪一层已经稳了，哪一层还要再练。","principles":["情绪能力是分层的：认得出、说得出、感觉得到、看得懂别人。","四关刚好对应这四层，一层一层往上走。","第一关认表情，是最基础的辨认层。","第二关说出「我现在觉得……」，进到自我表达层。","第三关说出生气时身体的感觉，进到身体觉察层。","第四关看绘本说角色的心情和原因，进到理解他人层。","哪一关卡住，就知道要回去补哪几个活动。","不要求四关都完美，能走完就已经很好。","这个模组是后面「情绪来了怎么办」的地基，地基稳了再往上盖。"],"prep":{"场地":"客厅或桌边，一个不受打扰的半小时。","器材":"表情卡、一面镜子、一本绘本。","安全检查":"无特殊风险。孩子累了就分两天做完；不把结果当成评价。","大人位置":"大人当主持人，每关先说明，必要时给提示。"},"shots":[{"name":"宣布四关","say":"今天四关，我们一关一关来。"},{"name":"第一关认表情","say":"哪一张是生气？"},{"name":"第二关说自己","say":"你现在觉得怎么样？"},{"name":"第三关身体感觉","say":"生气的时候身体什么感觉？"},{"name":"第四关看绘本","say":"他为什么难过？"},{"name":"收尾","say":"四关都完成了！"}],"reactions":[{"if":"某一关完全卡住","then":"给提示直接过关，记下来，之后回去单独练那几个活动。"},{"if":"孩子不想玩了","then":"分两天做完。完成比连续重要。"},{"if":"孩子表现比平常差","then":"不比较。今天状态不好很正常，换个时间再来。"}],"mistakes":["把它当成测验，孩子有压力就表现不出真实水准。","四关硬要一次走完，最后草草结束。","把卡住的那一关当成问题反复练，挫折被放大。"],"down":"每关都给提示，只要求参与不要求正确。","up":"四关独立完成，并且每一关都能说出理由。","progress":["四关各自完成到什么程度。","哪一层最需要补（那就是接下来的重点）。","和一个月前比，说得出的情绪词多了吗。"],"outro":"四关对应四层能力：认得出、说得出、感觉得到、看得懂别人。哪一层卡住就回去补——这是下一个模组的地基。"}' AS JSON))
WHERE `id` = 'A200';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要（想象一根蜡烛）'),
  `trains` = COALESCE(`trains`, '学会最简单有效的平静方法——深呼吸。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"伸出一根手指当蜡烛。"},{"imageUrl":null,"instruction":"用鼻子慢慢吸气（闻花香）。"},{"imageUrl":null,"instruction":"用嘴巴慢慢吹气（吹蜡烛）。"},{"imageUrl":null,"instruction":"连做三次。"},{"imageUrl":null,"instruction":"平静的时候先练熟。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '吹三次'),
  `harder` = COALESCE(`harder`, '情绪来的时候自己想起来用。'),
  `tip` = COALESCE(`tip`, '「闻花香、吹蜡烛」比说「你深呼吸」好懂太多——一定要在心情好的时候先练熟，情绪来了才用得出来。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"情绪来的时候叫孩子「深呼吸」，他通常做不到——因为他不知道深呼吸长什么样子。今天把它变成吹蜡烛。","principles":["深呼吸是最简单、最随身、也最有实证支持的平静方法。","慢而深的呼气会启动副交感神经，让心跳和肌肉张力降下来。","但「深呼吸」三个字对孩子太抽象，他不知道要怎么做。","伸出一根手指当蜡烛，抽象的动作就变成一个看得见的目标。","用鼻子吸气叫「闻花香」，用嘴巴吹气叫「吹蜡烛」，两个比喻孩子一听就懂。","重点在吐气要比吸气长，吹蜡烛这个动作自然就做到了。","连做三次，时间够长才有效果，一次通常不够。","最关键的一条：一定要在平静的时候先练熟。","没练过的方法，情绪来的时候绝对想不起来，这是所有情绪技巧的通则。"],"prep":{"场地":"安静的地方，孩子坐着或站着都可以。","器材":"不需要任何东西；伸出一根手指当蜡烛。","安全检查":"不要求快速用力呼吸，避免过度换气造成头晕；孩子头晕就停下来正常呼吸。","大人位置":"大人和孩子面对面，同高度，一起做。"},"shots":[{"name":"伸出蜡烛","say":"把手指伸出来，这是我们的蜡烛。"},{"name":"闻花香","say":"用鼻子慢慢吸——闻花香。"},{"name":"吹蜡烛","say":"用嘴巴慢慢吹——把蜡烛吹熄。"},{"name":"吐气要长","say":"吹长一点，慢慢吹。"},{"name":"连做三次","say":"再来一次——第三次。"},{"name":"平静时先练","say":"不生气的时候就要练，生气的时候才用得出来。"}],"reactions":[{"if":"孩子吹得太快太用力","then":"握着他的手放在肚子上，说「慢慢来，吹到肚子扁下去」。把速度带下来。"},{"if":"孩子说头晕","then":"立刻停止，改成正常呼吸，坐一下。下次减少次数和深度。"},{"if":"情绪来的时候孩子不肯做","then":"大人自己做给他看，不要求他。他看着看着通常会跟上。"}],"mistakes":["只在孩子生气时才叫他深呼吸，平常没练过就用不出来。","要求孩子用力快速呼吸，容易头晕反而更不舒服。","一次只做一下就放弃，时间太短没有效果。"],"down":"只做吹的部分，不强调吸气；吹一次就算成功。","up":"情绪来的时候自己想起来用，并能自己数到三次。","progress":["平静时会不会照着做。","吐气有没有比吸气长。","情绪来时经提示会不会做，或自己想起来做。"],"outro":"记住一条通则：不生气的时候练，生气的时候才用得出来。每天练三次，只要一分钟。"}' AS JSON))
WHERE `id` = 'A201';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个角落＋抱枕、玩偶、绘本'),
  `trains` = COALESCE(`trains`, '设一个可以自己冷静下来的地方。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"和孩子一起布置一个舒服的小角落。"},{"imageUrl":null,"instruction":"放几样他喜欢的东西（抱枕、玩偶、书）。"},{"imageUrl":null,"instruction":"约定：心情不好可以自己去待一下。"},{"imageUrl":null,"instruction":"冷静了再出来聊。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人陪着去'),
  `harder` = COALESCE(`harder`, '自己主动去、平静了自己出来。'),
  `tip` = COALESCE(`tip`, '平静角**不是处罚区**——不能用「你给我去角落反省」的语气。这是「帮助自己冷静的地方」，大人也可以用。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"平静角不是处罚，是一个让他自己回神的地方。这两件事差一条线，但结果差很远。","principles":["情绪上来的时候，环境刺激越少，恢复得越快。","所以有一个固定、安静、舒服的角落，对孩子帮助很大。","这个角落必须是他自己的，所以要和他一起布置。","放他喜欢的东西：抱枕、玩偶、绘本，让那里是舒服的。","最关键的界线：平静角不是处罚角，不能用来罚站或隔离。","一旦变成处罚，孩子就再也不会主动去，这个工具就毁了。","约定好：心情不好可以自己去待一下，想出来就出来。","大人一开始可以陪着去，等他熟了再让他自己去。","能自己察觉、自己去、自己回来，是很高阶的自我调节能力。"],"prep":{"场地":"家里一个安静的角落，最好离主要活动区有一点距离。","器材":"抱枕、玩偶、几本绘本、小地垫；不放电子产品。","安全检查":"角落不可关门上锁，大人要看得到；不放会遮盖口鼻的大型软垫给三岁以下孩子。","大人位置":"布置时和孩子一起挑东西、一起摆，让他有主权感。"},"shots":[{"name":"一起挑地方","say":"我们找一个你觉得舒服的角落。"},{"name":"一起布置","say":"你想放什么进去？"},{"name":"说清楚用途","say":"心情不好的时候，可以自己来这里待一下。"},{"name":"大人陪着去","say":"我们一起去坐一下好不好？"},{"name":"自己去","say":"（孩子情绪来时自己走进角落）"},{"name":"平静了再聊","say":"你好了吗？我们来聊聊。"}],"reactions":[{"if":"孩子不肯去","then":"不推不拖。大人自己去坐一下，说「妈妈去平静角一下」，示范给他看。"},{"if":"孩子在里面待很久","then":"那没关系，让他待到自己想出来。中途可以去看一眼但不催。"},{"if":"孩子把它当成玩耍的地方","then":"很好。平常就喜欢待在那里，情绪来的时候才会想去。"}],"mistakes":["把平静角当处罚角，叫孩子「去那边反省」。","强迫孩子进去或不准他出来。","放电子产品在里面，那就变成娱乐区不是平静区。"],"down":"大人全程陪着一起待在角落，不要求他自己去。","up":"自己察觉情绪来了就主动去，平静了自己出来说「我好了」。","progress":["愿不愿意进去。","情绪来时经提示会不会去。","有没有开始自己主动去、自己出来。"],"outro":"一条线要守住：平静角不是处罚角。他想去就去、想出来就出来——有主权，他才会用。"}' AS JSON))
WHERE `id` = 'A202';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '用拥抱平复情绪，也补充安全感。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子情绪来时问「要不要抱一下？」"},{"imageUrl":null,"instruction":"紧紧抱住，安静地陪着。"},{"imageUrl":null,"instruction":"不急着说道理。"},{"imageUrl":null,"instruction":"等他平静了再聊。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '接受拥抱'),
  `harder` = COALESCE(`harder`, '自己说「我要抱抱」来求安慰。'),
  `tip` = COALESCE(`tip`, '深深的拥抱有真实的安抚作用。但要问过他——有些孩子情绪来的时候不想被碰，这时候安静地待在旁边就好。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子情绪来的时候，最有效的工具其实不是技巧，是你的怀抱。但有一个前提——先问他要不要。","principles":["拥抱会带来深层压力觉输入，这对神经系统有直接的镇定作用。","同时也补充安全感，让孩子知道「有情绪也不会被推开」。","这是所有情绪工具中最快、最简单、也最不需要练习的一个。","但要先问「要不要抱一下」，因为有些孩子在激动时不想被碰。","被强抱的孩子会更激动，因为身体失去了控制感。","他答应了就紧紧抱住，紧一点比轻拍更有效。","抱着的时候安静就好，不要一边抱一边讲道理。","讲道理会让孩子觉得拥抱是有条件的，效果就打折了。","等他身体放松、呼吸变慢了，再开始聊刚刚发生的事。"],"prep":{"场地":"孩子情绪发生的当下，任何地方。","器材":"不需要任何东西。","安全检查":"一定要先征得孩子同意；抗拒被碰时改为坐在旁边陪伴，不强行拥抱。","大人位置":"大人蹲下或坐下，把自己降到孩子的高度再张开手。"},"shots":[{"name":"孩子情绪来了","say":"（孩子哭着或生气）"},{"name":"先问","say":"要不要抱一下？"},{"name":"紧紧抱住","say":"（孩子扑进怀里，大人紧紧抱住）"},{"name":"安静陪着","say":"（什么都不说，只是抱着）"},{"name":"等身体放松","say":"（孩子呼吸变慢、身体松下来）"},{"name":"平静了再聊","say":"好一点了吗？刚刚怎么了？"}],"reactions":[{"if":"孩子推开不要抱","then":"尊重他。改成坐在旁边说「我在这里，你想抱的时候告诉我」。"},{"if":"孩子抱着抱着哭更大声","then":"那是情绪在释放，继续抱着就好，不要因此松手。"},{"if":"孩子抱很久不放","then":"就抱着。他需要多久就多久，时间到了他自己会松开。"}],"mistakes":["不问就强行抱住，孩子会更激动。","一边抱一边说教，拥抱的效果就被抵消了。","要求孩子「不哭了才抱你」，把拥抱变成条件交换。"],"down":"不要求孩子说什么，只要他愿意靠过来就算成功。","up":"孩子自己说出「我要抱抱」来求安慰，主动使用这个工具。","progress":["情绪来时愿不愿意接受拥抱。","抱完情绪有没有缓下来。","会不会自己说「我要抱抱」。"],"outro":"先问要不要，抱了就安静陪着——不要一边抱一边讲道理。等他身体松下来了，再聊刚刚发生的事。"}' AS JSON))
WHERE `id` = 'A203';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '用数数争取冷静的时间。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"生气的时候一起慢慢数「一、二、三……十」。"},{"imageUrl":null,"instruction":"数的时候配合深呼吸。"},{"imageUrl":null,"instruction":"可以数手指、数楼梯、数东西。"},{"imageUrl":null,"instruction":"数完通常就没那么气了。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着大人数'),
  `harder` = COALESCE(`harder`, '自己想起来数。'),
  `tip` = COALESCE(`tip`, '数数争取的是「冲动过去的那几秒」——很多情绪爆发就发生在那几秒里，撑过去就好办了。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"生气的时候数到十——这句老话其实有道理，但要加一个条件才有用：要慢，而且要配上呼吸。","principles":["数数能争取时间，让冲动的高峰先过去。","情绪冲动通常在几十秒内达到顶点，撑过去就会自然下降。","同时数数需要动用思考，而思考会抑制情绪脑的冲动反应。","所以这个方法是同时踩了两个煞车。","但是快速地数完十个数没有用，必须慢。","配上呼吸，每一个数字吸或吐一次，效果会好很多。","可以数手指、数楼梯、数眼前的东西，有实物更容易专注。","一开始由大人带着数，孩子跟着，不要求他自己发起。","练熟了才有机会在情绪来的时候自己想起来用。"],"prep":{"场地":"任何地方；有楼梯或看得到的物品更好。","器材":"不需要任何东西；可用手指或眼前的东西当数的对象。","安全检查":"无特殊风险。不在孩子暴怒动手的当下要求数数，先确保安全。","大人位置":"大人蹲在孩子旁边，用平稳缓慢的声音带着数。"},"shots":[{"name":"生气的时候","say":"（孩子明显在生气）"},{"name":"一起慢慢数","say":"我们一起数——一……二……三……"},{"name":"配上呼吸","say":"（每个数字配一次吸气或吐气）"},{"name":"数手指","say":"我们数手指。"},{"name":"数到十","say":"……九、十。"},{"name":"自己想起来数","say":"（另一次情绪中，孩子自己开始数）"}],"reactions":[{"if":"孩子数得飞快","then":"握着他的手一根一根扳，把速度带慢。快数没有效果。"},{"if":"孩子不肯数","then":"大人自己慢慢数给他听。你的声音本身就有安定作用。"},{"if":"数完还是很生气","then":"那就再数一次，或换一个工具（抱抱、平静角）。一次不成不代表没用。"}],"mistakes":["快速数完十个数，等于什么都没做。","用命令的语气叫孩子「去数到十」，变成惩罚。","只在爆发时用，平常从来没练过。"],"down":"只数到三，并由大人握着他的手一根根扳开。","up":"情绪来时自己想起来数，并能配合呼吸数完十下。","progress":["愿不愿意跟着数。","数的速度有没有慢下来。","有没有开始自己主动数。"],"outro":"关键是慢，而且配上呼吸。数完还是气？那就再数一次，或换一招——工具本来就要有好几个。"}' AS JSON))
WHERE `id` = 'A204';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '抱枕、纸、墙'),
  `trains` = COALESCE(`trains`, '用安全的方式把力气发出来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"教几个安全的发泄法：捶抱枕、撕废纸、推墙、用力跺脚。"},{"imageUrl":null,"instruction":"约定「可以捶枕头，不可以打人」。"},{"imageUrl":null,"instruction":"发泄完再聊。"},{"imageUrl":null,"instruction":"大人陪着一起做。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人带着做'),
  `harder` = COALESCE(`harder`, '自己选一个方式用。'),
  `tip` = COALESCE(`tip`, '「出力气」能有效降低情绪强度——给他一个安全的出口，比要求他忍住有用。捶抱枕、推墙都很好。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"生气的时候身体是有力气要出来的。堵住没有用，要给它一个安全的出口——捶抱枕可以，打人不行。","principles":["生气时身体会分泌肾上腺素，肌肉紧绷，这股能量真的需要出口。","硬压下去，能量不会消失，只会换个地方跑出来。","所以与其禁止，不如提供安全的替代管道。","捶抱枕、撕废纸、推墙、用力跺脚，都是安全又有效的方式。","推墙这类等长收缩的动作特别好，力气出得掉又不会伤到东西。","界线要非常清楚：可以捶枕头，不可以打人、不可以摔东西。","大人陪着一起做，孩子才不会觉得自己被隔离在一旁发泄。","发泄完一定要再聊，否则只是把能量放掉，没有处理事情。","这一招不适合单独使用，要和命名、呼吸一起搭配。"],"prep":{"场地":"客厅有空间的地方，周围清空。","器材":"一个大抱枕、一叠废纸、一面结实的墙。","安全检查":"抱枕不可有硬芯或拉链扣；撕纸不用有钉书针的纸；推墙用手掌不用拳头；不使用玻璃门或隔间板墙。","大人位置":"大人和孩子一起做，同时守在旁边确保方向安全。"},"shots":[{"name":"说明规则","say":"生气的时候，可以捶枕头，不可以打人。"},{"name":"捶抱枕","say":"（用力捶抱枕）"},{"name":"撕废纸","say":"撕！用力撕！"},{"name":"推墙","say":"用手掌推墙，用力推十秒。"},{"name":"大人一起做","say":"我们一起！"},{"name":"发泄完再聊","say":"好一点了吗？刚刚怎么了？"}],"reactions":[{"if":"孩子越捶越激动","then":"改成推墙或用力抱紧自己这类静态出力，动态发泄有时会越做越亢奋。"},{"if":"孩子把发泄对象转向真人或物品","then":"立刻温和挡住，把抱枕递到他手上，重申界线。"},{"if":"孩子不想做","then":"不勉强。换一个工具，发泄只是众多选项之一。"}],"mistakes":["只教发泄，没有回头聊事情，问题没解决。","没有讲清楚界线，孩子以为生气就可以乱捶。","让孩子一个人去发泄，大人不在场，既不安全也少了连结。"],"down":"只做一种最安全的方式（用力抱紧自己或推墙），大人全程带着做。","up":"情绪来时自己选一个方式使用，做完自己说「我好了」。","progress":["会不会跟着做。","发泄完情绪有没有降下来。","会不会自己选方式而不是动手打人。"],"outro":"力气要有出口，但出口要安全。捶枕头可以，打人不行——发泄完记得回来聊，不然事情还在那里。"}' AS JSON))
WHERE `id` = 'A205';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸＋蜡笔'),
  `trains` = COALESCE(`trains`, '用画画把说不出来的情绪表达出来。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"邀请他「把现在的心情画出来」。"},{"imageUrl":null,"instruction":"怎么画都对：乱线是生气、太阳是开心。"},{"imageUrl":null,"instruction":"生气时可以用力涂，「把气画掉」。"},{"imageUrl":null,"instruction":"画完请他说说（愿意的话）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '随便涂颜色'),
  `harder` = COALESCE(`harder`, '画完能说说画的是什么感觉。'),
  `tip` = COALESCE(`tip`, '画纸能接住语言接不住的感受。「把气画掉」这一招对说不清楚情绪的孩子特别好用。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组三（情绪表达·说出感受）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"有些情绪说不出来，但画得出来。今天给他一张纸——怎么画都对，乱线也是一种答案。","principles":["语言不是唯一的表达管道，对孩子来说画画有时更直接。","特别是复杂或强烈的情绪，常常找不到对应的词。","画画不需要组织语言，情绪可以直接从手上流出来。","所以一定要说清楚：怎么画都对，没有标准答案。","乱线是生气，太阳是开心，全黑也是一种表达。","生气的时候可以用力涂，涂的动作本身就有发泄的效果。","画完请他说说，但他不想说就不要逼——画本身已经完成了表达。","大人绝对不要评价画得好不好，一评价，表达就停止了。","把画留下来，过一阵子一起看，孩子会看到自己的变化。"],"prep":{"场地":"桌边或地板，铺一块可以弄脏的垫子。","器材":"纸和蜡笔或粗彩色笔；纸要大一点。","安全检查":"使用无毒蜡笔；不使用尖锐笔尖；用力涂时注意笔不要戳到自己。","大人位置":"大人坐在旁边，自己也拿一张纸画，不看他的画也不指导。"},"shots":[{"name":"递上纸笔","say":"把现在的心情画出来。"},{"name":"怎么画都对","say":"乱画也可以，没有对错。"},{"name":"用力涂","say":"（孩子用力涂黑一片）"},{"name":"大人也画","say":"（大人在旁边画自己的心情）"},{"name":"画完问一句","say":"要不要跟我说说这是什么？"},{"name":"留下来","say":"我们把它收起来，过一阵子再看。"}],"reactions":[{"if":"孩子画得很暗很乱","then":"不评价也不担心。那是表达，不是症状。接住它：「你今天心里是这样的。」"},{"if":"孩子不想画","then":"大人自己画。不勉强，画笔放在那里，他想画的时候会拿。"},{"if":"孩子画完不想说","then":"完全可以。说「好，那我们放着」，表达已经完成了。"}],"mistakes":["评价画得好不好，表达立刻停止。","追问「你为什么画这个」，变成审问。","看到暗色的画就紧张追究，孩子会学会只画开心的。"],"down":"只涂颜色，不要求画出具体的东西。","up":"画完能说出这张画代表什么感觉，并说出原因。","progress":["愿不愿意画。","画完情绪有没有缓下来。","会不会说出画的是什么感觉。"],"outro":"怎么画都对，乱线也是答案。不要评价画得好不好，也不要追问为什么——画出来，本身就已经完成了。"}' AS JSON))
WHERE `id` = 'A206';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子喜欢的东西'),
  `trains` = COALESCE(`trains`, '用转移注意力度过情绪，但不是忽略他的感受。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"先说中他的感受「你很想要那个对不对」。"},{"imageUrl":null,"instruction":"再提议「我们来玩别的好不好？」"},{"imageUrl":null,"instruction":"换一个他也喜欢的活动。"},{"imageUrl":null,"instruction":"转移之后记得回来聊两句。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人主动转移'),
  `harder` = COALESCE(`harder`, '他自己找到别的事做。'),
  `tip` = COALESCE(`tip`, '转移不等于忽略——**要先接住感受，再转移**。跳过第一步直接说「不要哭了，我们去玩」，孩子会觉得没被理解。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"转移注意力很好用，但顺序错了就变成敷衍。正确的顺序是：先说中他的感受，再换。","principles":["转移注意力对幼儿特别有效，因为他们的注意力本来就容易被牵动。","但直接转移会让孩子觉得感受被忽略了。","所以顺序是关键：先命名感受，再提议换一个。","「你很想要那个对不对」——这一句让他知道你懂。","被懂了之后，他才有余裕接受别的选项。","换的活动必须是他也真心喜欢的，随便给一个是没用的。","转移之后要记得回来聊两句，让事情有个交代。","如果每次都只转移不回头，孩子会学到「情绪是被绕过去的」。","年纪越大，转移的效果越弱，要慢慢过渡到其他工具。"],"prep":{"场地":"孩子情绪发生的当下，任何地方。","器材":"孩子喜欢的另一样东西或活动，事先想好一两个备案。","安全检查":"无特殊风险。不用零食或电子产品当固定的转移工具。","大人位置":"大人蹲下与孩子同高，先接住再提议。"},"shots":[{"name":"孩子要不到东西","say":"（孩子指着橱窗里的玩具哭）"},{"name":"先说中感受","say":"你很想要那个对不对。"},{"name":"等他被接住","say":"（孩子点头，哭声变小）"},{"name":"再提议","say":"我们来玩别的好不好？"},{"name":"换一个他也爱的","say":"我们去看那边的喷水池！"},{"name":"回来聊两句","say":"刚刚那个玩具你很喜欢齁。"}],"reactions":[{"if":"孩子不接受转移","then":"那就先不转移。回到陪伴和拥抱，等情绪自己下来。"},{"if":"孩子被转移后又想起来","then":"正常。再说一次「你还是很想要对不对」，接住就好。"},{"if":"孩子每次都用哭来换东西","then":"那要检查是不是转移时常常给了替代的物品。改成给活动，不给东西。"}],"mistakes":["一开口就转移，感受没被接住，孩子会更坚持。","用零食或手机当转移工具，久了会变成习惯。","转移完就没事了，从来不回头聊。"],"down":"只做前半段：说中他的感受，然后陪着，不急着转移。","up":"孩子自己找到别的事做，并能说出「那我改玩这个」。","progress":["被说中感受时情绪有没有缓下来。","愿不愿意接受转移。","有没有开始自己找替代的活动。"],"outro":"先说中他的感受，再换。顺序颠倒，转移就变成敷衍——而且孩子分得出来。"}' AS JSON))
WHERE `id` = 'A207';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '沙漏或计时器'),
  `trains` = COALESCE(`trains`, '练习等待，忍住「现在就要」的冲动。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"想要的东西不马上给，说「等一下下」。"},{"imageUrl":null,"instruction":"用沙漏或数数让等待看得见。"},{"imageUrl":null,"instruction":"从五秒开始，慢慢拉长。"},{"imageUrl":null,"instruction":"等到了大力称赞「你等到了！」"},{"imageUrl":null,"instruction":"说等多久就等多久，绝不食言。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '等五到十秒'),
  `harder` = COALESCE(`harder`, '等一分钟以上不催不闹。'),
  `tip` = COALESCE(`tip`, '让等待「看得见」（沙漏、计时器）比空口说「等一下」有效得多。最重要的是说到做到——食言一次，下次就等不住了。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组六（轮流等待·互动规则）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"等待是可以练的。但有一条规矩大人必须守住——说等多久就等多久，绝不食言。","principles":["忍住「现在就要」的冲动，是情绪调节最核心的能力之一。","这个能力和日后的专注、学习、人际关系都高度相关。","等待之所以难，是因为时间对孩子来说是看不见的。","用沙漏或计时器把时间变成看得见的东西，等待就容易多了。","从五秒开始，短到他一定等得到，先建立成功经验。","成功了再慢慢拉长，每次多一点点，不要跳太快。","等到了要大力称赞，而且要称赞「等」这件事：「你等到了！」","最关键的一条：说等多久就等多久，绝不食言。","只要食言过一次，孩子就学到「等是没有用的」，之后会更难。"],"prep":{"场地":"日常生活中孩子想要东西的场景。","器材":"沙漏或手机计时器；孩子想要的东西。","安全检查":"不用长时间等待折磨孩子；孩子明显崩溃就缩短或结束，不硬撑。","大人位置":"大人拿着沙漏，和孩子一起看着它流完。"},"shots":[{"name":"孩子要东西","say":"（孩子伸手要饼干）"},{"name":"说等一下下","say":"等一下下，等沙漏流完。"},{"name":"一起看着","say":"（两人一起盯着沙漏）"},{"name":"从五秒开始","say":"（沙漏流完）"},{"name":"说到做到","say":"好！你等到了，给你！"},{"name":"称赞等这件事","say":"你刚刚等了好久，很厉害！"}],"reactions":[{"if":"孩子等不到就哭","then":"缩短时间，短到他一定成功。宁可从三秒开始，也不要让他一直失败。"},{"if":"孩子一直催","then":"指着沙漏说「你看，快流完了」。把注意力放在看得见的进度上。"},{"if":"大人临时有事没办法兑现","then":"一定要说明并补上。食言一次，之前的努力就白费了。"}],"mistakes":["一开始就要求等太久，孩子一直失败。","说等一下却食言，等待从此失去意义。","称赞「你好乖」而不是「你等到了」，重点就偏了。"],"down":"从三到五秒开始，并由大人陪着一起数或一起看沙漏。","up":"等待一分钟以上不催不闹，并能在等待时自己找事做。","progress":["能等多久。","等待时会不会一直催。","有没有开始自己说「我可以等」。"],"outro":"从五秒开始，用沙漏让时间看得见。最重要的是——说等多久就等多久，绝不食言。"}' AS JSON))
WHERE `id` = 'A208';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '练习接受变化，不因为「跟说好的不一样」就崩溃。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"提前预告变化：「本来要去公园，可是下雨了」。"},{"imageUrl":null,"instruction":"给替代方案：「我们改在家里玩帐篷」。"},{"imageUrl":null,"instruction":"从很小的变化开始练。"},{"imageUrl":null,"instruction":"接受了就肯定「你今天好有弹性」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '接受一个小变化'),
  `harder` = COALESCE(`harder`, '自己说出「那换个也可以」。'),
  `tip` = COALESCE(`tip`, '变化要**提前预告＋给替代方案**——突然改变对孩子来说很难接受，但预告过的变化就容易多了。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"说好要去公园却下雨了——有些孩子会因此崩溃。今天练的是弹性：先预告，再给替代方案。","principles":["有些孩子对变化特别敏感，因为可预测性带给他们安全感。","计划改变等于安全感被抽走，所以反应会很大。","这不是任性，是调适能力还没发展好。","要练弹性，必须从很小的变化开始，小到他承受得住。","提前预告是关键：突然告知会让冲击加倍。","预告的同时一定要给替代方案，不能只说不行。","有替代方案，孩子的注意力才有地方去。","接受了要明确肯定：「你今天好有弹性。」把这个能力命名。","被命名的能力才会被孩子意识到，然后才能被重复。"],"prep":{"场地":"日常生活中，计划有变动的当下。","器材":"不需要任何东西；事先想好一两个替代方案。","安全检查":"无特殊风险。不刻意制造变化来「训练」孩子，用真实发生的就好。","大人位置":"大人蹲下与孩子同高，先说变化再说替代。"},"shots":[{"name":"预告变化","say":"本来我们要去公园，可是下雨了。"},{"name":"接住失望","say":"你一定很失望。"},{"name":"给替代方案","say":"我们改在家里搭帐篷好不好？"},{"name":"孩子考虑","say":"（孩子犹豫一下点头）"},{"name":"明确肯定","say":"你今天好有弹性！"},{"name":"从小变化练起","say":"（快剪几个小变化：换路线、换点心）"}],"reactions":[{"if":"孩子完全无法接受","then":"先不急着说服。接住情绪，等他平静一点再提替代方案。"},{"if":"孩子接受了又反悔","then":"正常。再说一次替代方案的好处，并陪他开始做，做起来就好了。"},{"if":"孩子对所有变化都很敏感","then":"那就把预告做得更提前、更详细，并建立固定的日常流程当基础。"}],"mistakes":["临时才说，没有预告，冲击加倍。","只说不行，没有给替代方案。","用「有什么好哭的」否定他的失望。"],"down":"从最小的变化练起（换一条回家的路），并事先预告两次。","up":"孩子自己说出「那我们换个别的也可以」，主动提出替代方案。","progress":["面对小变化的反应强度。","接受替代方案的速度。","会不会自己提出替代方案。"],"outro":"先预告，再给替代方案，接受了要明确说「你好有弹性」。从很小的变化开始练——小到他承受得住。"}' AS JSON))
WHERE `id` = 'A209';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '稍有难度的任务'),
  `trains` = COALESCE(`trains`, '遇到太难的事，学会拆成小块一块块做。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子说「太难了」时，示范「我们先做这一半就好」。"},{"imageUrl":null,"instruction":"把任务切成两三块。"},{"imageUrl":null,"instruction":"完成一块就打个勾。"},{"imageUrl":null,"instruction":"做完发现「原来做得到」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人帮他切'),
  `harder` = COALESCE(`harder`, '自己说「我先做到这里」。'),
  `tip` = COALESCE(`tip`, '「切小」是应付挫折最实用的一招——大任务让人想逃，小任务让人想试。这个方法能用一辈子。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子说「太难了」就放弃——他不是懒，是那件事在他眼里是一整块。今天教他切开来。","principles":["面对一大块任务，孩子会被整体的难度吓退。","切成小块之后，每一块都变得可以处理。","这个方法叫做任务分解，是执行功能最重要的策略之一。","大人先示范怎么切：「我们先做这一半就好。」","示范几次之后，孩子会开始自己切。","完成一块就打个勾，让进度看得见。","看得见的进度会产生动力，这比口头鼓励有效得多。","做完之后回头看，孩子会发现「原来我做得到」。","这个发现会累积成自我效能感，也就是「我可以」的信心。"],"prep":{"场地":"桌边，孩子正在做有难度的事情时。","器材":"孩子正在挑战的任务；纸笔用来打勾。","安全检查":"无特殊风险。任务难度要在他伸手可及的范围，不用远超能力的任务。","大人位置":"大人坐在旁边，用手或纸把任务实际划分出来。"},"shots":[{"name":"孩子说太难了","say":"（孩子推开拼图说「太难了」）"},{"name":"示范切小","say":"我们先做这一半就好。"},{"name":"完成第一块","say":"（孩子完成一半）"},{"name":"打个勾","say":"第一块完成，打勾！"},{"name":"再做下一块","say":"那我们再做这一块。"},{"name":"回头看","say":"你看，整个都做完了。"}],"reactions":[{"if":"孩子切完还是说难","then":"再切一次，切到他一定做得到为止。小到可笑也没关系。"},{"if":"孩子做完一块就想停","then":"那就停。完成一块也是成功，不要要求一次做完。"},{"if":"孩子不让你帮忙切","then":"那就让他自己试。他说不行的时候再问「要不要先做一点点就好？」"}],"mistakes":["直接帮孩子做完，他学不到分解的方法。","切得不够小，孩子还是做不到。","要求一口气做完所有小块，切了等于没切。"],"down":"切到只剩一个动作（只放一片拼图），完成就算成功。","up":"自己说出「我先做到这里」，并能自己规划分几次完成。","progress":["会不会接受切小之后再试。","有没有开始自己说「先做一点点」。","说「太难了」就放弃的次数有没有减少。"],"outro":"切到他一定做得到为止，小到可笑也没关系。完成一块就打个勾——看得见的进度，比一百句加油有用。"}' AS JSON))
WHERE `id` = 'A210';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子正在挑战的事'),
  `trains` = COALESCE(`trains`, '失败了愿意再试，是最重要的学习态度。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子失败时说「好可惜，再试一次！」"},{"imageUrl":null,"instruction":"第二次给一点点协助，让他成功。"},{"imageUrl":null,"instruction":"夸「你再试了一次」比夸「你成功了」更重要。"},{"imageUrl":null,"instruction":"慢慢减少协助。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人鼓励下再试'),
  `harder` = COALESCE(`harder`, '自己主动再试。'),
  `tip` = COALESCE(`tip`, '夸「再试一次」的勇气，而不只是夸结果——这样孩子才不会为了保护面子而不敢挑战。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子失败了，你要夸的不是「你成功了」，而是「你再试了一次」。这一句话，决定他以后敢不敢挑战。","principles":["愿意再试一次，是所有学习能力的底层。","不敢再试的孩子，能力再好也会停在原地。","孩子会不会再试，取决于失败之后发生了什么。","如果失败带来的是责备或失望，他就会避开挑战。","如果失败带来的是「好可惜，再试一次」，他就敢继续。","第二次要给一点点协助，让他成功，成功的经验才留得住。","但协助要慢慢减少，否则会变成依赖。","夸「你再试了一次」比夸「你成功了」重要，因为前者他可以控制。","这叫做历程取向的称赞，长期下来培养出的是不怕失败的孩子。"],"prep":{"场地":"孩子正在挑战某件事的场景。","器材":"孩子正在挑战的东西（积木、拼图、扣扣子）。","安全检查":"无特殊风险。不用超出能力太多的任务让孩子反复失败。","大人位置":"大人在旁边不出手，等他失败了再决定要不要给一点协助。"},"shots":[{"name":"失败了","say":"（积木倒了，孩子愣住）"},{"name":"好可惜","say":"好可惜！再试一次！"},{"name":"给一点协助","say":"（大人用手扶住底座）"},{"name":"成功了","say":"（这次成功了）"},{"name":"夸再试这件事","say":"你刚刚再试了一次，这最厉害！"},{"name":"慢慢减少协助","say":"（下一次大人的手离开一点）"}],"reactions":[{"if":"孩子失败就发脾气","then":"先接住情绪：「好可惜，你很想做到。」情绪过了再谈再试。"},{"if":"孩子完全不肯再试","then":"不勉强。改成大人做、他看，或改天再来。逼出来的尝试没有价值。"},{"if":"孩子每次都要人帮","then":"把协助减到最少（只用一根手指碰一下），让成功仍然属于他。"}],"mistakes":["失败时说「我就说吧」，孩子会记住这种感觉。","直接接手做完，孩子学不到再试。","只夸结果不夸过程，孩子会开始避开可能失败的事。"],"down":"第二次给足够多的协助，确保一定成功，先建立「再试会更好」的经验。","up":"失败后自己主动再试，不需要大人提示。","progress":["失败后愿不愿意再试。","需要的协助有没有减少。","有没有开始自己主动再试。"],"outro":"夸「你再试了一次」，比夸「你成功了」更重要——因为再试这件事，是他自己可以决定的。"}' AS JSON))
WHERE `id` = 'A211';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '卡住的时候会求助，不是硬撑也不是崩溃。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"孩子卡住快烦躁时，提示「说：帮帮我」。"},{"imageUrl":null,"instruction":"他一说就马上帮。"},{"imageUrl":null,"instruction":"帮完再陪他试一次。"},{"imageUrl":null,"instruction":"告诉他「求助是聪明的做法」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着说「帮帮我」'),
  `harder` = COALESCE(`harder`, '主动求助而不是发脾气。'),
  `tip` = COALESCE(`tip`, '会求助的孩子，挫折不容易变成崩溃。「求助不丢脸，是聪明」——这句话要常常说给他听。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"有些孩子卡住了宁可崩溃也不开口。今天要传达一件事——求助不是认输，求助是聪明的做法。","principles":["求助是一种能力，不是弱点，但很多孩子并不这么认为。","不敢求助的孩子，会用硬撑、放弃或发脾气来处理困难。","这三种方式都比求助费力，而且效果都不好。","时机很重要：要在他快烦躁、还没爆炸的时候提示。","已经爆了才教，他听不进去，那时候只能先安抚。","他一说「帮帮我」就要立刻帮，让求助的效果非常明确。","帮完再陪他试一次，让他知道求助之后事情会变好。","而且要明确说出来：「求助是聪明的做法。」","这句话会重新定义求助这件事，把它从丢脸变成能力。"],"prep":{"场地":"孩子正在做有难度的事情时，任何地方。","器材":"不需要任何东西；利用当下真实的困难。","安全检查":"任务难度要设在他差一点点就做得到的位置，不用远超能力的任务制造挫折。","大人位置":"大人在旁边，手随时可以伸过去，但先不动。"},"shots":[{"name":"卡住了","say":"（孩子转不开瓶盖，开始皱眉）"},{"name":"抓住时机","say":"说：帮帮我。"},{"name":"立刻帮","say":"（孩子说了，大人马上伸手）"},{"name":"陪他再试一次","say":"我们一起再转一次。"},{"name":"重新定义","say":"求助是聪明的做法喔。"},{"name":"主动求助","say":"（另一次，孩子自己说「帮帮我」）"}],"reactions":[{"if":"孩子宁可摔东西也不求助","then":"先安抚，事后在平静时用玩偶演一次求助的过程，压力最小。"},{"if":"孩子求助后大人没空马上帮","then":"也要回应：「我听到了，等我十秒。」不能让求助落空。"},{"if":"孩子什么都马上求助","then":"加一句「你先试三下，试完再叫我」，在求助前留一点尝试。"}],"mistakes":["说「这么简单还要人帮」，求助立刻变成丢脸。","等孩子崩溃了才开始教，时机错了。","孩子求助了却拖着不帮，工具就失效了。"],"down":"孩子只要把东西递过来或看你一眼就当作求助，立刻帮并替他说出那句话。","up":"卡住时主动求助，并能说清楚需要什么协助：「这个太紧了，可以帮我转吗？」","progress":["卡住时会不会求助而不是发脾气。","求助的方式有没有从手势变成说话。","会不会说清楚需要什么帮忙。"],"outro":"时机在爆炸之前，回应要立刻。还有一句一定要说出口：求助是聪明的做法——这句话会改变他对求助的看法。"}' AS JSON))
WHERE `id` = 'A212';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '体验成就感，累积「我可以」的自信。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"安排他一定做得到的小任务。"},{"imageUrl":null,"instruction":"完成了一起说「我做到了！」"},{"imageUrl":null,"instruction":"具体说出他做到什么：「你自己把鞋穿好了」。"},{"imageUrl":null,"instruction":"每天至少一次成功经验。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '完成简单任务'),
  `harder` = COALESCE(`harder`, '完成有点挑战的任务。'),
  `tip` = COALESCE(`tip`, '每天保护一次「他一定做得到」的成功经验——成就感是抗挫折的燃料，累积够了才有力气面对困难。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"每天至少安排一次他一定做得到的事。不是为了完成什么，是为了让他每天都听见自己说：我做到了。","principles":["成就感不是天生的，是靠一次一次的成功经验累积出来的。","每天至少一次成功，孩子心里的「我可以」才会长出来。","所以任务要刻意安排成他一定做得到的难度。","不是放水，是让他有机会真的成功，而不是一直在失败边缘。","完成了要一起说出来：「我做到了！」说出口比默默完成有力得多。","称赞要具体：「你自己把鞋穿好了」，而不是笼统的「你好棒」。","具体的称赞让他知道自己到底做对了什么，下次才能重复。","笼统的称赞听久了会失效，孩子也分不出自己好在哪里。","这些小成功累积起来，就是面对困难时的底气。"],"prep":{"场地":"日常生活中，穿鞋、收玩具、倒水都可以。","器材":"不需要任何东西；利用真实的生活任务。","安全检查":"任务不涉及热水、刀具、高处；倒水使用小水壶与防滑垫。","大人位置":"大人在旁边不出手，等他完成再回应。"},"shots":[{"name":"安排一个小任务","say":"你可以自己把鞋穿好吗？"},{"name":"他自己做","say":"（孩子专心穿鞋，大人不出手）"},{"name":"完成了","say":"（穿好了，抬头看大人）"},{"name":"一起说出来","say":"我做到了！"},{"name":"具体称赞","say":"你自己把鞋穿好了，两只都对。"},{"name":"每天一次","say":"（快剪几天不同的小任务）"}],"reactions":[{"if":"孩子做到一半做不下去","then":"给一点协助让他完成，成功比独立更重要，独立可以慢慢来。"},{"if":"孩子完成了没什么反应","then":"由大人先说「我做到了！」多示范几次他会跟上。"},{"if":"孩子只想做很难的事","then":"那就让他试，但同时安排一件简单的当保底，确保每天有成功。"}],"mistakes":["只说「你好棒」，孩子不知道自己好在哪里。","任务安排得太难，每天都在失败。","孩子快完成时大人抢着帮忙，成功感就没了。"],"down":"任务小到只有一个步骤（把一只鞋放进鞋柜），并由大人带着做一半。","up":"完成有点挑战的任务，并能自己说出「我做到了，我自己……」。","progress":["每天有没有至少一次成功经验。","完成后会不会说「我做到了」。","愿不愿意尝试稍微难一点的任务。"],"outro":"称赞要具体：「你自己把鞋穿好了」，不要只说「你好棒」。每天一次成功，累积起来就是他的底气。"}' AS JSON))
WHERE `id` = 'A213';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一本小册子或一张纸'),
  `trains` = COALESCE(`trains`, '把做到的事记下来，让进步看得见。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"准备一本小册子。"},{"imageUrl":null,"instruction":"孩子做到什么就记下来或贴张贴纸。"},{"imageUrl":null,"instruction":"「今天自己穿鞋」「今天蹲十下」。"},{"imageUrl":null,"instruction":"不开心时拿出来看看自己有多棒。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '贴贴纸'),
  `harder` = COALESCE(`harder`, '自己说出今天做到了什么。'),
  `tip` = COALESCE(`tip`, '看得见的进步最有说服力——孩子说「我不行」的时候，翻开本子给他看：「你以前也说不行，后来做到了」。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把做到的事记下来，进步就看得见了。心情不好的时候翻一翻——这是孩子自己给自己的证据。","principles":["孩子对自己的进步没有概念，因为进步是慢慢发生的。","把做到的事记下来，抽象的进步就变成看得见的累积。","看得见的累积会产生动力，也会产生自信。","记录的内容要具体：「今天自己穿鞋」比「今天很棒」有力得多。","贴纸对年纪小的孩子最好用，不需要写字。","重点是每天都有东西可以记，所以标准要订得低一点。","心情不好时翻出来看，是很有效的自我安慰方式。","因为那是他自己的证据，不是别人说的安慰话。","一段时间后回头看，孩子会自己发现「我以前不会，现在会了」。"],"prep":{"场地":"固定的位置，睡前一起记录。","器材":"一本小册子或一张贴在墙上的纸；贴纸或彩色笔。","安全检查":"使用无毒贴纸；剪裁由大人完成。","大人位置":"大人和孩子一起记，让他决定今天要记什么。"},"shots":[{"name":"准备小本本","say":"这是你的成就小本本。"},{"name":"今天做到什么","say":"今天你做到什么？"},{"name":"具体写下来","say":"今天自己穿鞋。"},{"name":"贴张贴纸","say":"（孩子贴上一张贴纸）"},{"name":"累积起来","say":"（翻页呈现好几天的记录）"},{"name":"不开心时翻一翻","say":"心情不好的时候，看看自己有多棒。"}],"reactions":[{"if":"孩子想不到今天做到什么","then":"由大人提醒：「你今天自己吃完饭了呀。」标准可以订得很低。"},{"if":"孩子只想贴贴纸不想说","then":"贴纸就好。形式不重要，累积的感觉才重要。"},{"if":"孩子有几天什么都没记","then":"不追。隔天继续就好，不要让它变成必须完成的功课。"}],"mistakes":["标准订太高，很多天都没东西可以记。","用它来要求孩子表现（没做到就不能贴），变成奖惩工具。","只记大事，忽略每天的小进步。"],"down":"只贴贴纸不写字，由大人口头说出今天做到什么。","up":"自己说出并写下今天做到的事，并能在心情不好时主动拿出来看。","progress":["会不会每天记录。","能不能自己说出今天做到什么。","心情不好时会不会想到翻出来看。"],"outro":"标准订低一点，每天都要有东西可以记。这本册子是他自己的证据——不开心的时候，比任何安慰的话都有用。"}' AS JSON))
WHERE `id` = 'A214';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '任何简单的游戏'),
  `trains` = COALESCE(`trains`, '玩之前先建立心理准备：谁都可能输。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"每次玩游戏前一起念「有输有赢才是游戏！」"},{"imageUrl":null,"instruction":"问「等下谁可能赢？」答案是「都可能」。"},{"imageUrl":null,"instruction":"大人输了要示范平静：「哎呀我输了，有输有赢嘛」。"},{"imageUrl":null,"instruction":"每次玩都念一遍。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着念口号'),
  `harder` = COALESCE(`harder`, '开局前自己说出来。'),
  `tip` = COALESCE(`tip`, '预告过的输，杀伤力小一半——这句赛前口号是整个输赢教育的地基，每次都别省略。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十三（团体游戏·规则与胜负）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"输不起的孩子，其实是因为没有人事先告诉他「可能会输」。今天在开局前先念一句口号。","principles":["输不起通常不是脾气问题，是预期落差太大。","孩子开局时只想着赢，输了就变成一个意外的打击。","开局前先说「有输有赢才是游戏」，等于先做心理准备。","预期被调整过了，输的冲击就小很多。","再问一句「等下谁可能赢」，答案是「都可能」，把不确定性说清楚。","大人输了要示范平静：「哎呀我输了，有输有赢嘛。」","孩子学的是大人输的样子，不是大人讲的道理。","所以大人绝对不能假输，也不能输了就不玩。","每次玩都念一遍，变成固定的开场仪式，效果才会累积。"],"prep":{"场地":"桌边或地板，全家围坐。","器材":"任何简单快速的游戏（牌类、掷骰、抢椅子）。","安全检查":"选回合短的游戏，避免长时间累积紧张；肢体类游戏注意周围净空。","大人位置":"大人正常玩，不刻意放水，也不刻意压制孩子。"},"shots":[{"name":"开局前的口号","say":"一起念——有输有赢才是游戏！"},{"name":"问谁可能赢","say":"等下谁可能赢？（都可能！）"},{"name":"开始玩","say":"（快速进行一局）"},{"name":"大人输了","say":"哎呀我输了，有输有赢嘛。"},{"name":"孩子输了","say":"（孩子输了，看了大人一眼）"},{"name":"每次都念","say":"（下一局开始前又念一次）"}],"reactions":[{"if":"孩子输了还是崩溃","then":"先接住情绪，不在这时讲道理。下一局开始前再念一次口号。"},{"if":"孩子要求大人放水","then":"不放水但可以调整规则（他多一次机会），公开说明比偷偷放水好。"},{"if":"孩子赢了就嘲笑别人","then":"当场温和制止，并示范赢的说法：「好险，你很厉害。」"}],"mistakes":["大人一直放水，孩子从来没机会练习输。","孩子输了就说「这有什么好哭的」，情绪没被接住。","大人自己输了就不玩了，示范的就是输不起。"],"down":"玩纯运气的游戏（掷骰比大小），输赢和能力无关，接受度最高。","up":"在竞技性较强的游戏中也能平静接受输，并主动说出口号。","progress":["开局前会不会跟着念口号。","输了之后的情绪强度。","有没有开始自己说「有输有赢嘛」。"],"outro":"开局前先念一遍，让他知道可能会输。然后最重要的是——大人自己输的时候，要示范给他看。"}' AS JSON))
WHERE `id` = 'A215';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '小游戏'),
  `trains` = COALESCE(`trains`, '输了有固定的三步可以走，不会瘫在原地。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一步：说出来「好可惜！」"},{"imageUrl":null,"instruction":"第二步：深呼吸三次。"},{"imageUrl":null,"instruction":"第三步：喊「再来一局！」"},{"imageUrl":null,"instruction":"马上开新局，让他知道机会立刻回来。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着走三步'),
  `harder` = COALESCE(`harder`, '自己完成并平静地开新局。'),
  `tip` = COALESCE(`tip`, '把三步写下来贴在游戏角——输了有路可走，孩子就不会崩溃。先共情「输了真的很难受」，再走流程。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十三（团体游戏·规则与胜负）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"输了之后孩子会瘫在原地，因为他不知道接下来要做什么。今天给他三个固定的步骤。","principles":["输了之后的空白时间，是情绪最容易失控的时候。","有固定的步骤可以走，就不会瘫在那里让情绪发酵。","第一步说出来「好可惜！」——把感受讲出来，本身就有调节作用。","第二步深呼吸三次——用身体的方法把激动降下来。","第三步喊「再来一局！」——把注意力转向下一次机会。","三步很短，短到情绪来的时候还记得住。","关键在于第三步之后要马上开新局，让机会真的立刻回来。","如果说了再来一局却没有下一局，这个步骤就失效了。","练熟之后，这三步会变成输了之后的自动反应。"],"prep":{"场地":"桌边，玩一个回合很短的游戏。","器材":"任何一局只要一两分钟的小游戏。","安全检查":"无特殊风险。孩子已经崩溃时先安抚，不硬走三步。","大人位置":"大人和孩子一起走三步，自己输的时候也照做。"},"shots":[{"name":"输了","say":"（孩子输了，表情垮下来）"},{"name":"第一步说出来","say":"好可惜！"},{"name":"第二步深呼吸","say":"（吸——吐——三次）"},{"name":"第三步再来一局","say":"再来一局！"},{"name":"马上开新局","say":"（立刻发牌开始）"},{"name":"大人也走三步","say":"（大人输了照走一次）"}],"reactions":[{"if":"孩子输了直接大哭","then":"先安抚，等平静一点再带着走三步。崩溃时走不了流程。"},{"if":"孩子跳过深呼吸直接要再来","then":"可以。三步中最重要的是有事可做，顺序可以有弹性。"},{"if":"孩子喊了再来一局却没有时间玩","then":"那就约定下次的时间，并且一定要兑现。"}],"mistakes":["只教口号不马上开新局，第三步就落空了。","孩子崩溃时硬要他走三步，反而更激动。","大人自己输了不走三步，示范不完整。"],"down":"只做第一步和第三步（说出来、再来一局），省略深呼吸。","up":"自己完整走完三步，并能平静地开始新的一局。","progress":["输了之后会不会走这三步。","需不需要大人提示。","走完之后能不能平静地继续玩。"],"outro":"三步：说出来、深呼吸、再来一局。最重要的是第三步之后要马上开新局——让机会真的立刻回来。"}' AS JSON))
WHERE `id` = 'A216';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '小游戏'),
  `trains` = COALESCE(`trains`, '输了还能恭喜对方，是很高级的能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人先示范：输了鼓掌说「恭喜你，你真厉害！」"},{"imageUrl":null,"instruction":"他输时提示「给赢的人拍拍手」。"},{"imageUrl":null,"instruction":"做到了大力肯定「你输得真有风度！」"},{"imageUrl":null,"instruction":"赢的时候也教「不说你好菜」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '提示下拍手'),
  `harder` = COALESCE(`harder`, '主动说「恭喜你」。'),
  `tip` = COALESCE(`tip`, '大人输了游戏要真诚地给孩子鼓掌——输家的风度，孩子是看着学的，不是听着学的。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十三（团体游戏·规则与胜负）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"输了还能恭喜对方，这是很高级的能力——连大人都不一定做得到。所以今天大人先做给他看。","principles":["输了还能替对方高兴，需要同时处理自己的失落和别人的喜悦。","这对孩子来说是很高难度的整合，所以不能急。","大人先示范是唯一有效的方法，讲道理没有用。","示范要具体：输了鼓掌，说「恭喜你，你真厉害」。","孩子看多了，会知道原来输了可以是这个样子。","他做到了要大力肯定，而且要用「有风度」这个词。","这个词会给他一个身份认同：我是有风度的人。","赢的时候也要教：不说「你好菜」，赢了也要给对方留面子。","这两面合起来，才是完整的运动家精神。"],"prep":{"场地":"桌边或客厅，全家一起玩。","器材":"任何有明确输赢的小游戏。","安全检查":"无特殊风险。避免在孩子情绪已经很差时进行这个练习。","大人位置":"大人正常玩，输了立刻示范鼓掌与恭喜。"},"shots":[{"name":"大人输了","say":"（大人输了，先鼓掌）"},{"name":"说恭喜","say":"恭喜你，你真厉害！"},{"name":"孩子看见了","say":"（孩子愣了一下）"},{"name":"换孩子输","say":"给赢的人拍拍手。"},{"name":"他做到了","say":"你输得真有风度！"},{"name":"赢的时候也要教","say":"赢了不说「你好菜」喔。"}],"reactions":[{"if":"孩子做不到鼓掌","then":"不勉强。他只要不说难听的话就已经很好，鼓掌可以慢慢来。"},{"if":"孩子勉强鼓掌但很不情愿","then":"仍然肯定：「你还是拍手了，这很不容易。」肯定行为不评价心情。"},{"if":"孩子赢了嘲笑别人","then":"当场温和制止，并示范：「你可以说——好险，你很厉害。」"}],"mistakes":["要求孩子要「真心」恭喜，做到行为就已经够了。","只在孩子输时要求风度，赢时的态度却不管。","大人自己输了脸色很差，示范就是反面的。"],"down":"只要求不说难听的话，不要求鼓掌或恭喜。","up":"主动说「恭喜你」，并能在输的当下真诚地肯定对方。","progress":["输了会不会拍手。","会不会说出恭喜。","赢的时候会不会给对方留面子。"],"outro":"这一招连大人都不一定做得到，所以一定要大人先做。做到了就说「你输得真有风度」——这个词，会变成他的身份。"}' AS JSON))
WHERE `id` = 'A217';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一张「暂停卡」'),
  `trains` = COALESCE(`trains`, '觉察自己快爆了，主动喊停。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"做一张暂停卡，谁都可以用。"},{"imageUrl":null,"instruction":"孩子情绪上头时提示「要不要暂停一下？」"},{"imageUrl":null,"instruction":"暂停就是：离开一下、喝口水、深呼吸。"},{"imageUrl":null,"instruction":"平静了自己说「我好了」再回来。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人提示下暂停'),
  `harder` = COALESCE(`harder`, '自己觉察主动喊停。'),
  `tip` = COALESCE(`tip`, '用了暂停卡要大力称赞——「你会照顾自己的情绪了」。这是很高阶的能力，大人也该学。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"最高阶的情绪能力，是在爆炸之前自己喊停。今天做一张暂停卡——而且大人也可以用。","principles":["自己察觉「我快炸了」并主动暂停，是情绪调节的最高阶表现。","它需要身体觉察、自我监控和执行控制三样能力一起运作。","所以这个活动要放在这个模组的后面，前面的基础要先打好。","做一张实体的暂停卡，让这个抽象的动作有具体的载体。","谁都可以用，包括大人——这一点非常重要。","如果只有孩子能用，那它就变成另一种处罚。","暂停就是三件事：离开一下、喝口水、深呼吸。","平静了自己说「我好了」再回来，主导权在他手上。","有主导权的暂停，孩子才会愿意用。"],"prep":{"场地":"客厅或餐桌，暂停卡放在大家拿得到的地方。","器材":"一张自制的暂停卡（画一个手掌或暂停符号）。","安全检查":"暂停不等于隔离，大人要保持在视线内；不用暂停卡当处罚工具。","大人位置":"大人和孩子一起做卡片，并且大人要真的用过它。"},"shots":[{"name":"一起做卡片","say":"我们来做一张暂停卡。"},{"name":"谁都可以用","say":"你可以用，妈妈也可以用。"},{"name":"情绪上头","say":"（孩子声音变大、身体紧绷）"},{"name":"提示暂停","say":"要不要暂停一下？"},{"name":"暂停三件事","say":"离开一下、喝口水、深呼吸。"},{"name":"自己说我好了","say":"（孩子回来说「我好了」）"}],"reactions":[{"if":"孩子拒绝暂停","then":"不强迫。大人自己用一次暂停卡，示范给他看。"},{"if":"孩子用暂停卡逃避该做的事","then":"暂停可以，但事情还在。回来之后温和地说「我们刚刚在做……」。"},{"if":"孩子暂停很久不回来","then":"去看一眼但不催。真的太久就过去陪着，不要求他立刻回来。"}],"mistakes":["把暂停卡变成大人叫孩子「去冷静」的工具，那就是处罚。","只有孩子能用，大人不用，示范不完整。","暂停中还一直说话讲道理，暂停就没有意义了。"],"down":"由大人提示才暂停，并全程陪着一起做三件事。","up":"自己察觉快要爆了，主动拿出暂停卡，平静后自己回来。","progress":["经提示会不会接受暂停。","暂停之后情绪有没有降下来。","有没有开始自己主动喊停。"],"outro":"暂停卡谁都可以用，大人也一样。平静了自己说「我好了」再回来——主导权在他手上，他才会愿意用。"}' AS JSON))
WHERE `id` = 'A218';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '大人示范怎么处理自己的情绪。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人有情绪时说出来：「妈妈现在有点烦，我需要深呼吸一下」。"},{"imageUrl":null,"instruction":"做给孩子看：深呼吸、离开一下、平静后再回来。"},{"imageUrl":null,"instruction":"事后可以说「刚才妈妈太大声了，对不起」。"},{"imageUrl":null,"instruction":"让孩子知道大人也在练习。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出自己的情绪'),
  `harder` = COALESCE(`harder`, '完整示范平静的过程。'),
  `tip` = COALESCE(`tip`, '孩子学的是我们「做」什么，不是我们「说」什么。大人先冷静下来，才教得动孩子——这条最难，也最重要。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"这一支影片是拍给大人看的。孩子学的不是你讲的道理，是你生气时的样子。","principles":["孩子的情绪处理方式，绝大部分是从大人身上学来的。","不是从大人说的话学，是从大人做的事学。","所以大人有情绪的时候，本身就是最好的教材。","第一步是说出来：「妈妈现在有点烦，我需要深呼吸一下。」","这一句同时示范了命名情绪和宣告自己的需要。","第二步是做给他看：深呼吸、离开一下、平静后再回来。","完整走过一次，孩子就看到情绪是可以被处理的。","如果刚才太大声了，事后要道歉：「刚才妈妈太大声了，对不起。」","道歉不会让大人失去权威，反而示范了承担责任的样子。"],"prep":{"场地":"家中真实发生情绪的场景。","器材":"不需要任何东西。","安全检查":"大人情绪强烈时先确保孩子安全，必要时请另一位大人接手；分享内容避免涉及夫妻冲突。","大人位置":"大人蹲下与孩子同高说明，再自行离开处理。"},"shots":[{"name":"大人有情绪","say":"（大人皱眉、深吸一口气）"},{"name":"说出来","say":"妈妈现在有点烦，我需要深呼吸一下。"},{"name":"做给他看","say":"（深呼吸三次）"},{"name":"离开一下","say":"我去阳台站一下就回来。"},{"name":"平静后回来","say":"我好多了，我们来说说刚刚的事。"},{"name":"必要时道歉","say":"刚才妈妈太大声了，对不起。"}],"reactions":[{"if":"孩子因为大人生气而害怕","then":"先安抚：「妈妈是在生气那件事，不是不要你。」把事和人分开。"},{"if":"大人已经吼出来了","then":"事后道歉并说明。修补本身就是最好的示范，不必假装没发生。"},{"if":"孩子模仿大人说「我需要深呼吸」","then":"太好了。立刻肯定他，并让他真的去做。"}],"mistakes":["假装自己从来不生气，孩子会以为只有他有问题。","生气时把情绪发在孩子身上，事后也不说明。","道歉时加上「但是你也不对」，道歉就变成了指责。"],"down":"只做第一步：说出自己的情绪，不要求完整走完流程。","up":"完整示范命名、暂停、平静、回来处理的全过程，并在必要时道歉。","progress":["大人有没有开始说出自己的情绪。","孩子看到之后的反应。","孩子有没有开始模仿这些说法。"],"outro":"孩子学的不是你讲的道理，是你生气时的样子。吼出来了也没关系——事后道歉，那就是最好的一课。"}' AS JSON))
WHERE `id` = 'A219';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸笔'),
  `trains` = COALESCE(`trains`, '整理出属于自己的几招平静方法。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"和孩子一起列：情绪来的时候我可以做什么？"},{"imageUrl":null,"instruction":"从这个模组挑三招他最有用的（深呼吸、去平静角、捶抱枕、画画）。"},{"imageUrl":null,"instruction":"画成一张「情绪工具卡」贴在墙上。"},{"imageUrl":null,"instruction":"情绪来时指着卡片问「用哪一招？」"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '会用一招'),
  `harder` = COALESCE(`harder`, '自己选出合适的一招使用。'),
  `tip` = COALESCE(`tip`, '每个孩子有效的方法不一样——让他自己挑出「我的三招」，用起来才顺手。工具箱做好了，情绪就有地方去。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组四（情绪调节·挫折与成就感）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"这是模组十一的收尾。从这二十个活动里挑三招他最有用的，画成一张卡贴在墙上——这就是他的工具箱。","principles":["工具很多没有用，能在情绪来的时候想起来的才有用。","所以要精选，三招就够，多了反而记不住。","而且必须是他自己觉得有效的，不是大人指定的。","自己挑的工具，他才会愿意用。","画成一张卡贴在墙上，情绪来的时候看得到。","看得到才想得起来，这是所有情绪工具的共同条件。","情绪来时不要说「你去深呼吸」，而是指着卡片问「用哪一招？」","问句把选择权交回给他，命令句只会引起对抗。","这张卡会跟着孩子长大，工具可以随时换掉或加上去。"],"prep":{"场地":"桌边一起制作，完成后贴在孩子看得到的墙面。","器材":"纸、彩色笔；可以把前面活动的照片贴上去。","安全检查":"使用无毒画笔；张贴使用不伤墙的胶带，避免图钉。","大人位置":"大人和孩子一起回顾这个模组，由孩子决定挑哪三招。"},"shots":[{"name":"一起回顾","say":"情绪来的时候，你可以做什么？"},{"name":"列出所有招数","say":"深呼吸、平静角、抱抱、数到十、捶抱枕、画画……"},{"name":"挑三招","say":"哪三招你觉得最有用？"},{"name":"画成一张卡","say":"（一起画三个图案）"},{"name":"贴在墙上","say":"贴在这里，看得到。"},{"name":"情绪来时用问的","say":"用哪一招？"}],"reactions":[{"if":"孩子挑的招数大人觉得没用","then":"尊重他的选择。他觉得有用的才真的有用，无效的他自己会换掉。"},{"if":"孩子三招都想不起来用","then":"那就由大人指着卡片提示。提示几十次之后他会开始自己看。"},{"if":"孩子想挑很多招","then":"先挑三招放在卡上，其他的写在背面当备选。"}],"mistakes":["大人指定要用哪一招，孩子就不会主动使用。","工具挑太多，情绪来的时候一个都想不起来。","情绪来时用命令的口气叫他用，引发对抗。"],"down":"只挑一招，练到非常熟再加第二招。","up":"能根据情绪的种类和强度选择不同的招数，并说出为什么选这一招。","progress":["会不会使用至少一招。","经提示会不会去看卡片。","有没有开始自己选招数使用。"],"outro":"三招就够，而且要他自己挑。情绪来的时候记得用问的——「用哪一招？」而不是「你去深呼吸」。"}' AS JSON))
WHERE `id` = 'A220';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会最基本的社交开关：打招呼和道别。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"见人时示范挥手说「你好」。"},{"imageUrl":null,"instruction":"离开时说「再见」。"},{"imageUrl":null,"instruction":"小小孩可以先只挥手。"},{"imageUrl":null,"instruction":"每天进出门、视频通话都练。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '挥手＋跟着说'),
  `harder` = COALESCE(`harder`, '见人主动打招呼。'),
  `tip` = COALESCE(`tip`, '「你好」开启互动、「再见」好好收尾——这两句练熟了，社交就有了头和尾。别强迫害羞的孩子，先挥手也很好。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组五（社交进入·打招呼与加入）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"打招呼是社交的第一个动作，但不要逼孩子说。今天示范怎么练——从挥手开始就好。","principles":["打招呼和道别，是社交互动的开场与收尾，缺了会让人觉得突兀。","这两句都是固定句型，不需要临场组织，是社交技巧里最好学的。","但很多孩子会卡住，不是不会说，是当下紧张。","所以小小孩可以先只挥手，动作先出来，声音慢慢跟上。","强迫孩子打招呼会有反效果，他会更抗拒，甚至躲起来。","大人自己每次都确实做到，是最有效的教法。","孩子看你做了几百次，自然会跟着做。","每天进出门、视频通话，一天就有好几次自然的机会。","不需要额外安排时间，这是这个活动最大的优点。"],"prep":{"场地":"家门口、电梯、视频通话时，都是现成场景。","器材":"不需要任何东西。","安全检查":"不强迫孩子与陌生人互动；孩子躲起来时不当众批评。","大人位置":"大人先做给孩子看，每一次自己都确实说出口。"},"shots":[{"name":"大人先做","say":"（遇到邻居，大人挥手）你好！"},{"name":"孩子挥手","say":"（孩子跟着挥手，没出声）"},{"name":"慢慢加上声音","say":"（另一天，孩子小声说「你好」）"},{"name":"道别","say":"再见！明天见！"},{"name":"视频通话也练","say":"（对着萤幕挥手说你好）"},{"name":"不强迫","say":"（孩子躲起来，大人不勉强）"}],"reactions":[{"if":"孩子躲起来不肯打招呼","then":"由大人代打：「他今天有点害羞。」不当众指责，事后也不检讨。"},{"if":"孩子只对熟人打招呼","then":"很正常。先把熟人练稳，陌生人不急。"},{"if":"孩子说得很小声","then":"不要求大声。有说就肯定，音量会随信心一起长。"}],"mistakes":["当众说「怎么这么没礼貌」，孩子下次更抗拒。","强迫孩子跟陌生人打招呼，容易造成反效果。","大人自己不打招呼，却要求孩子做到。"],"down":"只做动作：挥手或点头，完全不要求出声。","up":"见到人主动打招呼，并能加上称呼（阿姨好、老师好）。","progress":["会不会挥手或点头。","会不会说出招呼语。","有没有开始主动打招呼。"],"outro":"小小孩先挥手就好，声音会慢慢跟上。千万不要当众说他没礼貌——那会让他下次躲得更远。"}' AS JSON))
WHERE `id` = 'A221';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要（可用玩偶）'),
  `trains` = COALESCE(`trains`, '会说出自己的名字，是自我介绍的第一句。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"问「你叫什么名字？」教他答「我叫××」。"},{"imageUrl":null,"instruction":"对镜子、对玩偶、对家人轮流练。"},{"imageUrl":null,"instruction":"玩「小记者采访」。"},{"imageUrl":null,"instruction":"真的有人问时轻声提示。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出名字'),
  `harder` = COALESCE(`harder`, '完整说「我叫××，我×岁」。'),
  `tip` = COALESCE(`tip`, '再加一句「我喜欢××」——共同的喜好是孩子之间最快的握手方式。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组五（社交进入·打招呼与加入）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「你叫什么名字？」——这是每个孩子在外面最常被问到的一句。先在家里练熟，外面就不会卡住。","principles":["说出自己的名字，是自我介绍的第一句，也是社交的入场券。","被问到却说不出来，孩子会尴尬，大人也会替他紧张。","所以要在家里先练到脱口而出，压力最小的时候练。","对镜子、对玩偶、对家人轮流练，难度一层一层往上。","对玩偶说话完全没有压力，是最好的起点。","「小记者采访」的游戏形式让练习变得好玩，孩子愿意重复。","真的有人问的时候，大人在旁边轻声提示就好，不要代答。","代答会剥夺他的练习机会，久了他会习惯让大人讲。","进阶是加上年龄，把一句变成两句的自我介绍。"],"prep":{"场地":"家里任何地方；镜子前效果更好。","器材":"不需要任何东西；玩偶或玩具麦克风可以增加趣味。","安全检查":"教孩子不主动对陌生人说出全名、住址与就读学校。","大人位置":"大人面对孩子发问，问完等待，不急着替他回答。"},"shots":[{"name":"先对玩偶练","say":"（拿玩偶问）你叫什么名字？"},{"name":"教完整句","say":"我叫××。"},{"name":"对镜子练","say":"（对着镜子说一次）"},{"name":"小记者采访","say":"请问你叫什么名字？几岁呀？"},{"name":"真实场合轻声提示","say":"（有人问，大人在旁小声说「我叫……」）"},{"name":"安全提醒","say":"（字幕：不主动告诉陌生人全名和学校）"}],"reactions":[{"if":"孩子不敢开口","then":"退回对玩偶练。压力小的场合先成功，再慢慢往真实场合推。"},{"if":"孩子只说小名","then":"可以。小名也是名字，等他习惯开口了再教全名。"},{"if":"大人忍不住替他答了","then":"答完补一句：「你要不要自己说一次？」把机会还给他。"}],"mistakes":["每次都由大人代答，孩子永远没机会练。","孩子说不出来时当场催促，压力更大。","只在真实场合才练，没有事先在家演练过。"],"down":"只对玩偶说，而且由大人先说一次他跟着说。","up":"完整说出「我叫××，我×岁」，并能在不熟悉的场合主动介绍。","progress":["会不会说出自己的名字。","在真实场合敢不敢说。","能不能加上年龄说成两句。"],"outro":"在家先练到脱口而出。真的有人问的时候，在旁边轻声提示就好——不要代答，那是他的练习机会。"}' AS JSON))
WHERE `id` = 'A222';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子＋公园'),
  `need` = COALESCE(`need`, '不需要（有小朋友的场合）'),
  `trains` = COALESCE(`trains`, '加入游戏的第一步：先观察。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"带孩子到有小朋友的地方。"},{"imageUrl":null,"instruction":"陪他在旁边看一会儿。"},{"imageUrl":null,"instruction":"轻声解说「他们在玩沙子，用铲子挖」。"},{"imageUrl":null,"instruction":"看懂了再考虑要不要加入。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '陪着看并听解说'),
  `harder` = COALESCE(`harder`, '自己说出别人在玩什么。'),
  `tip` = COALESCE(`tip`, '孩子只看不玩别急着催——「旁观」是正式的发展阶段，他正在收集情报。看懂了，进去才不突兀。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组五（社交进入·打招呼与加入）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子冲进去就被拒绝？多半是因为他不知道人家在玩什么。加入之前，先站在旁边看一会儿。","principles":["成功加入一个团体，第一步不是开口，是观察。","要先知道他们在玩什么、玩到哪里、规则是什么。","看懂了，才知道自己可以从哪里加进去。","没看清楚就冲进去，很容易打断别人，也就容易被拒绝。","所以陪孩子在旁边看一会儿，是最值得投资的时间。","大人轻声解说：「他们在玩沙子，用铲子挖一个洞。」","解说等于示范怎么观察，孩子会学到要看哪些东西。","看懂之后再决定要不要加入，也是一种自主选择。","有些孩子看完决定不加入，那也完全可以，观察本身就是能力。"],"prep":{"场地":"公园、游戏场或任何有其他孩子在玩的场合。","器材":"不需要任何东西。","安全检查":"户外注意场地安全与其他孩子的活动动线；不让孩子站在游具的移动路径上。","大人位置":"大人和孩子站在几步远的地方，蹲下与孩子同高一起看。"},"shots":[{"name":"先不急着进去","say":"我们先在这边看一下。"},{"name":"轻声解说","say":"他们在玩沙子，用铲子挖一个洞。"},{"name":"看规则","say":"那个小朋友在装沙，那个在倒水。"},{"name":"换孩子说","say":"你看他们在做什么？"},{"name":"看懂了再决定","say":"你想加入吗？还是我们先玩别的？"},{"name":"不加入也可以","say":"（孩子摇头，两人去玩别的）"}],"reactions":[{"if":"孩子等不及要冲进去","then":"轻轻拉住，说「我们看三下就好」，用很短的时间建立观察的习惯。"},{"if":"孩子看了很久都不动","then":"不催。有些孩子需要很长的暖机时间，那是他的节奏。"},{"if":"孩子说不出别人在玩什么","then":"由大人说，说得具体一点。示范几次之后他会开始自己看。"}],"mistakes":["直接把孩子推进去，「去跟他们玩呀」。","观察时间太长，错过了加入的时机。","孩子决定不加入就说他胆小，下次他更不敢。"],"down":"只陪着看，由大人全程解说，不要求孩子说出观察内容。","up":"自己说出别人在玩什么、玩到哪里，并判断可以从哪里加入。","progress":["愿不愿意先看一会儿再行动。","能不能说出别人在玩什么。","有没有开始自己判断加入的时机。"],"outro":"冲进去之前，先在旁边看一会儿。看懂了再决定要不要加入——决定不加入，也完全可以。"}' AS JSON))
WHERE `id` = 'A223';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子演练＋真实'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会加入游戏的黄金句。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"在家先演练：大人假装在玩，孩子走过来问「我可以一起玩吗？」"},{"imageUrl":null,"instruction":"大人答「可以呀！」让他体验成功。"},{"imageUrl":null,"instruction":"练到脱口而出。"},{"imageUrl":null,"instruction":"真实场合大人陪着用。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '在家演练会说'),
  `harder` = COALESCE(`harder`, '真实场合主动问。'),
  `tip` = COALESCE(`tip`, '这一句是打开同伴世界的钥匙——在家练熟、真实场合先由大人陪着问，成功几次孩子就敢自己开口了。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组五（社交进入·打招呼与加入）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"加入游戏有一句黄金句：「我可以一起玩吗？」但不要等到公园才教——在家先练到脱口而出。","principles":["加入别人的游戏，需要一句明确的请求，孩子才不会只是站在旁边。","「我可以一起玩吗」是最通用的一句，几乎任何场合都能用。","在真实场合临时教，孩子紧张，学不起来。","所以要在家里先演练，压力最小的时候练熟。","演练时大人要答「可以呀」，让他体验成功。","成功的经验会给他勇气，在外面才敢开口。","练到脱口而出，这句话才会在需要的时候自动出现。","真实场合大人陪着一起去，站在他后面一点的位置。","大人在场会给他安全感，但不要替他说。"],"prep":{"场地":"在家客厅演练；真实场合在公园或游戏场。","器材":"不需要任何东西；演练时大人手上拿个玩具假装在玩。","安全检查":"真实场合中若对方明显不愿意，立刻带开，不僵持。","大人位置":"演练时大人假装在玩；真实场合站在孩子后方一两步。"},"shots":[{"name":"在家演练","say":"（大人假装在玩积木）"},{"name":"说出黄金句","say":"我可以一起玩吗？"},{"name":"大人答可以","say":"可以呀！来！"},{"name":"练到脱口而出","say":"（快剪几次演练）"},{"name":"真实场合","say":"（公园里孩子走向其他小朋友）"},{"name":"大人在后面","say":"（大人站在两步远，不出声）"}],"reactions":[{"if":"孩子不敢开口","then":"大人陪着一起走过去，由大人先说一次，再邀请他说。"},{"if":"孩子说得太小声对方没听到","then":"轻声提醒「再说一次，大声一点」，不要替他说。"},{"if":"孩子被接纳后不知道怎么玩","then":"那就回到观察：「他们在做什么？你也做一样的。」"}],"mistakes":["在真实场合才第一次教这句话，孩子紧张学不会。","大人替孩子问，他永远不用自己开口。","演练时大人拒绝他，第一次就受挫，之后更不敢。"],"down":"只在家里对大人或玩偶演练，不要求在真实场合使用。","up":"在不熟悉的场合主动开口，并能针对不同情境调整说法。","progress":["在家演练会不会说。","真实场合敢不敢开口。","开口的音量和主动性有没有提高。"],"outro":"在家先练到脱口而出，真实场合你站在他后面两步——陪着，但不要替他说。"}' AS JSON))
WHERE `id` = 'A224';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子演练'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '被拒绝时有办法应对，不会崩溃。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"演练：他问「可以一起玩吗」，大人说「现在不行」。"},{"imageUrl":null,"instruction":"教三步：说「好吧」→等一会儿再问→或找别的玩。"},{"imageUrl":null,"instruction":"强调「不行」常常只是「现在不行」。"},{"imageUrl":null,"instruction":"换他当拒绝的人，体会对方也有理由。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '演练中说「好吧」'),
  `harder` = COALESCE(`harder`, '真的被拒也能平静转向。'),
  `tip` = COALESCE(`tip`, '在家先演过「被拒绝」，真的遇到就不会那么受伤。让他当一次拒绝的人，他就懂了：拒绝里通常没有恶意。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组五（社交进入·打招呼与加入）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"被拒绝一定会发生。所以比起教他怎么问，更重要的是教他——被说不行的时候，接下来做什么。","principles":["被拒绝是社交中一定会遇到的事，躲不掉。","没有准备的孩子会崩溃，或从此不敢再问。","所以要事先演练，在安全的情境里先经历一次被拒绝。","三步很好记：说「好吧」→ 等一会儿再问 → 或找别的玩。","有步骤可以走，孩子就不会瘫在那里。","要特别强调一件事：「不行」常常只是「现在不行」。","孩子往往会把拒绝理解成「他们不喜欢我」，那是过度解读。","换他当拒绝的人，会发现自己拒绝别人也是有理由的。","这个角色互换是理解对方最快的方法。"],"prep":{"场地":"在家客厅演练，气氛轻松。","器材":"不需要任何东西。","安全检查":"演练拒绝时语气要平和，不模仿嘲笑或恶意的拒绝方式。","大人位置":"大人当被问的人，先示范温和的拒绝。"},"shots":[{"name":"演练被拒绝","say":"（孩子问「可以一起玩吗」，大人说「现在不行」）"},{"name":"第一步说好吧","say":"好吧。"},{"name":"第二步等一下再问","say":"那我等一下再来问你。"},{"name":"第三步找别的玩","say":"或者我先去玩溜滑梯。"},{"name":"不行常常只是现在不行","say":"他说现在不行，不是不喜欢你。"},{"name":"换他当拒绝的人","say":"换你说不行，我来问。"}],"reactions":[{"if":"孩子演练时就哭了","then":"停下来抱抱，说「这只是演习」。然后把拒绝的语气放得更温和再试。"},{"if":"孩子说「他们不喜欢我」","then":"先接住这个感受，再说「他现在正在玩，等一下可能就可以了」。"},{"if":"孩子被拒绝就不想再去","then":"不勉强。那天就玩别的，下次再试，不要在挫折上加压力。"}],"mistakes":["演练时把拒绝演得太凶或带嘲笑，孩子会更怕。","孩子被拒绝时说「没关系啦」，感受没被接住。","只教怎么问，没教被拒绝怎么办。"],"down":"只练第一步（说好吧）和第三步（找别的玩），省略等一下再问。","up":"真实场合被拒绝也能平静转向，并会自己选择等一下再问或换别的。","progress":["演练中能不能说出「好吧」。","真实被拒绝时的情绪强度。","会不会自己转向别的活动。"],"outro":"告诉他一件事：「不行」常常只是「现在不行」，不是不喜欢你。三步走完，就有下一个地方可以去。"}' AS JSON))
WHERE `id` = 'A225';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子＋同伴'),
  `need` = COALESCE(`need`, '和现场一样的玩具'),
  `trains` = COALESCE(`trains`, '不用开口也能加入的方法。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"看别人玩了一会儿后，给他同款的玩具。"},{"imageUrl":null,"instruction":"在几步远的地方玩一样的。"},{"imageUrl":null,"instruction":"模仿对方的玩法。"},{"imageUrl":null,"instruction":"常常玩着玩着就并到一起了。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '远一点玩同款'),
  `harder` = COALESCE(`harder`, '玩法也跟着对方变。'),
  `tip` = COALESCE(`tip`, '出门带一套「同款装备」（小铲子、泡泡水）——对开口困难的孩子，这条路一样通向朋友。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组九（游戏发展·从独自到合作）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"不敢开口的孩子，还有一条路可以加入——不用说话，在旁边玩一样的东西就好。","principles":["不是所有加入都需要开口，平行游戏是很自然的一种方式。","在几步远的地方玩同样的东西，本身就是一种社交邀请。","这对害羞或语言能力还不够的孩子特别友善。","玩一样的东西，会自然产生共同话题和共同注意。","模仿对方的玩法，是在传达「我对你在做的事有兴趣」。","对方通常会注意到，然后自然地并到一起。","距离要从远到近，一开始远一点，让双方都没有压力。","这也是幼儿游戏发展的正常阶段，不是退步。","从平行游戏走到合作游戏，是自然的发展顺序。"],"prep":{"场地":"公园沙坑、游戏区，有其他孩子在玩的地方。","器材":"和现场孩子在玩的同款玩具（铲子、小车、球）。","安全检查":"保持适当距离避免碰撞；不擅自拿别人的玩具。","大人位置":"大人陪在孩子旁边一起玩，降低他的紧张感。"},"shots":[{"name":"先看一会儿","say":"（观察别人在玩沙）"},{"name":"给他同款玩具","say":"（大人拿出一把一样的铲子）"},{"name":"在几步远玩","say":"（孩子在旁边挖沙）"},{"name":"模仿玩法","say":"（对方在挖洞，孩子也挖洞）"},{"name":"距离慢慢靠近","say":"（孩子不知不觉挪近）"},{"name":"自然并到一起","say":"（两个孩子开始一起挖同一个洞）"}],"reactions":[{"if":"对方没有注意到孩子","then":"没关系。平行玩本身就是练习，不一定要变成一起玩。"},{"if":"孩子想靠更近但不敢","then":"大人陪着往前挪一点，用你的在场当他的安全基地。"},{"if":"对方拒绝或走开","then":"轻描淡写带过：「他去玩别的了，我们继续挖。」不放大这件事。"}],"mistakes":["一开始就靠太近，双方都有压力。","拿别人的玩具来玩，很容易引发冲突。","一直催孩子「去跟他说话呀」，破坏了平行游戏的自然性。"],"down":"距离拉远一点，大人全程陪着一起玩，不期待任何互动发生。","up":"玩法跟着对方变化，并在自然的时机开口说一句话。","progress":["愿不愿意在旁边玩同款玩具。","距离有没有慢慢靠近。","有没有出现眼神交流或简单互动。"],"outro":"不用开口也能加入——在旁边玩一样的就好。距离从远到近，常常玩着玩着就并到一起了。"}' AS JSON))
WHERE `id` = 'A226';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个玩具'),
  `trains` = COALESCE(`trains`, '练最基本的轮流。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿一个玩具，说「轮到宝宝」给他玩一下。"},{"imageUrl":null,"instruction":"说「轮到妈妈」拿回来玩一下（时间很短）。"},{"imageUrl":null,"instruction":"边玩边说「轮到你／轮到我」。"},{"imageUrl":null,"instruction":"轮次先短，再慢慢拉长。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '几秒钟的轮次'),
  `harder` = COALESCE(`harder`, '等较长的轮次也不抢。'),
  `tip` = COALESCE(`tip`, '「我的轮次会回来」——有了这个信心，孩子才愿意把手上的东西暂时放开。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组六（轮流等待·互动规则）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"轮流是所有社交游戏的基础。今天从最短的轮次开始——短到他几乎不用等。","principles":["轮流是社交游戏最基本的结构，没有它，一起玩就成立不了。","轮流难在等待，等待对幼儿来说是很费力的事。","所以轮次要从非常短开始，短到他几乎感觉不到在等。","大人拿回来玩的时间只要两三秒，马上还回去。","成功几次之后再慢慢拉长，这个顺序不能反。","边玩边说「轮到你、轮到我」，把抽象的规则变成听得见的口令。","语言标记会帮助孩子预测接下来会发生什么。","可预测，等待就变得容易忍受。","这个基础打好，后面的桌游、沙漏轮流才玩得起来。"],"prep":{"场地":"地板或桌边，两人面对面坐着。","器材":"一个孩子喜欢但不是最珍爱的玩具。","安全检查":"玩具无小零件；不使用孩子最依恋的物品做轮流练习，避免过度焦虑。","大人位置":"大人坐在孩子对面，手可以直接递到他面前。"},"shots":[{"name":"轮到宝宝","say":"轮到宝宝！"},{"name":"玩一下","say":"（孩子玩几秒）"},{"name":"轮到妈妈","say":"轮到妈妈。"},{"name":"很短就还回去","say":"（大人玩两秒就还）轮到宝宝！"},{"name":"边玩边说","say":"轮到你——轮到我——"},{"name":"慢慢拉长","say":"（大人玩的时间稍微变长）"}],"reactions":[{"if":"孩子不肯交出玩具","then":"缩到极短：你只碰一下就还。先让他体验「交出去会回来」。"},{"if":"孩子交出后就哭","then":"立刻还给他，并说「轮到宝宝」。不要用哭来考验他的忍耐。"},{"if":"孩子愿意交但会一直盯着","then":"很正常。缩短你拿着的时间，同时说「快好了，马上还你」。"}],"mistakes":["大人拿着玩很久，孩子等到崩溃。","用最珍爱的玩具来练，焦虑太高。","没有说口令，孩子不知道现在轮到谁。"],"down":"大人只碰一下就还回去，轮次短到一秒。","up":"能等较长的轮次（十秒以上）不抢，并会自己说「轮到你了」。","progress":["愿不愿意交出玩具。","能等多长的轮次。","会不会自己说出轮流的口令。"],"outro":"轮次先短，短到他几乎不用等。成功几次之后再慢慢拉长——顺序反过来，就练不起来。"}' AS JSON))
WHERE `id` = 'A227';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或同伴'),
  `need` = COALESCE(`need`, '沙漏或计时器＋一个抢手的玩具'),
  `trains` = COALESCE(`trains`, '用计时器公平地轮流。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"两人想玩同一个玩具时拿出沙漏。"},{"imageUrl":null,"instruction":"「沙漏漏完就换人」。"},{"imageUrl":null,"instruction":"时间到练习把玩具交给对方。"},{"imageUrl":null,"instruction":"交接时说「给你」「谢谢」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人主持交接'),
  `harder` = COALESCE(`harder`, '时间到主动交出。'),
  `tip` = COALESCE(`tip`, '计时器是「中立的裁判」——孩子不是输给对方，只是时间到了，交出去就没那么难。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组六（轮流等待·互动规则）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"两个孩子抢同一个玩具，讲道理没用。拿出沙漏——让规则来当坏人，大人就不用当了。","principles":["抢玩具的冲突，核心是「什么时候轮到我」没有答案。","有了沙漏，时间就变成看得见、摸得到的东西。","看得见的时间让等待变得可以忍受，因为进度是清楚的。","而且规则是沙漏定的，不是大人偏心，冲突就少了很多。","大人从裁判变成主持人，孩子的对立感会下降。","时间到要练习把玩具交给对方，这是最难的一刻。","交接时说「给你」「谢谢」，把交接变成一个有礼貌的小仪式。","仪式会让交出去这件事感觉比较好，不像被夺走。","一开始由大人主持交接，熟了再让孩子自己完成。"],"prep":{"场地":"地板或桌边，两个孩子都坐得下的位置。","器材":"沙漏或计时器，加上一个抢手的玩具。","安全检查":"沙漏使用塑胶材质，不用玻璃制品；计时器音量不要太刺耳。","大人位置":"大人坐在两个孩子中间，负责主持交接。"},"shots":[{"name":"两人都想玩","say":"（两个孩子伸手抢同一个玩具）"},{"name":"拿出沙漏","say":"沙漏漏完就换人。"},{"name":"一人先玩","say":"（一个孩子玩，另一个盯着沙漏）"},{"name":"时间到","say":"漏完了，换人！"},{"name":"交接仪式","say":"给你。——谢谢。"},{"name":"规则当坏人","say":"（大人不用说不行，指着沙漏就好）"}],"reactions":[{"if":"时间到孩子不肯交","then":"大人温和地伸手接过来交给对方，并说「沙漏漏完了」。用规则而不是情绪。"},{"if":"等待的孩子一直催","then":"指着沙漏说「你看，快好了」。把注意力放在进度上。"},{"if":"孩子想改沙漏时间","then":"可以一起商量时间长短，但定了就要照做。事前商量，事中不改。"}],"mistakes":["大人自己当裁判说「给弟弟玩」，冲突变成对大人的不满。","时间设太长，等待的孩子撑不住。","时间到了不执行，规则就失去效力。"],"down":"沙漏时间设得很短（三十秒），并由大人全程主持交接。","up":"时间到主动交出，并能自己完成「给你、谢谢」的交接。","progress":["时间到肯不肯交出。","等待时的情绪强度。","会不会自己主动交接。"],"outro":"让规则当坏人，大人就不用当。时间到了指着沙漏就好——交接的时候记得说「给你」「谢谢」。"}' AS JSON))
WHERE `id` = 'A228';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '可以分的食物或玩具'),
  `trains` = COALESCE(`trains`, '从分食物开始学分享。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把饼干掰一半，示范「分你一半！」"},{"imageUrl":null,"instruction":"引导他也分你一半。"},{"imageUrl":null,"instruction":"你吃到就夸张地开心「谢谢你！好好吃！」"},{"imageUrl":null,"instruction":"分给家里每个人。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '在引导下分'),
  `harder` = COALESCE(`harder`, '主动把好东西分给别人。'),
  `tip` = COALESCE(`tip`, '分出去的是饼干，收回来的是「谢谢」和笑脸——让孩子体验到分享的好处，比说「要分享」有用。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组八（分享与合作入门）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"分享不是用教的，是用体验的。从掰一半饼干开始——重点在你吃到的时候要多开心。","principles":["分享对幼儿来说是违反直觉的，因为东西给出去就少了。","所以要让他体验到，分享会换来另一种更好的东西。","那个东西就是对方的开心，还有被感谢的感觉。","大人吃到的时候要夸张地开心，这一步是全部的关键。","如果大人接过来只是淡淡地说谢谢，分享就没有回馈。","从食物开始最容易，因为食物的分享结果是立即可见的。","掰一半这个动作很具体，孩子一看就懂什么叫分。","分给家里每个人，让分享变成日常的一部分。","不要求他分掉最珍爱的东西，那是下一个阶段的事。"],"prep":{"场地":"餐桌或点心时间，全家都在最好。","器材":"可以掰开的食物（饼干、水果）或可以分的玩具。","安全检查":"注意食物过敏与噎呛风险；三岁以下不给坚硬或圆形整颗的食物。","大人位置":"大人先示范掰一半分给孩子，接到时反应要夸张。"},"shots":[{"name":"大人先分","say":"分你一半！"},{"name":"引导他分","say":"那你要不要也分我一半？"},{"name":"夸张地开心","say":"谢谢你！好好吃！"},{"name":"孩子看见了","say":"（孩子笑起来）"},{"name":"分给每个人","say":"也分给爸爸、分给奶奶。"},{"name":"不逼分珍爱的","say":"（字幕：不要求他分掉最宝贝的东西）"}],"reactions":[{"if":"孩子不肯分","then":"不勉强。大人继续分给他，示范多几次，不要用交换条件逼他。"},{"if":"孩子分了又后悔","then":"还给他。分享是自愿的，后悔了也可以拿回去，这样他下次才敢分。"},{"if":"孩子只分不喜欢的东西","then":"完全可以。那也是分享的起点，慢慢会扩到别的东西。"}],"mistakes":["接到分享时反应太淡，孩子感受不到回馈。","强迫孩子分享最珍爱的玩具。","用「你不分就是小气」这种话，分享变成道德压力。"],"down":"只由大人分给孩子，不要求他回分，先体验被分享的感觉。","up":"主动把好东西分给别人，并能在没有提示的情况下想到分享。","progress":["愿不愿意分出一半。","有没有开始主动分。","分享的对象和物品范围有没有扩大。"],"outro":"你吃到的时候要多开心一点——分享的回馈就是从这里来的。不要逼他分掉最宝贝的东西，那是下一步的事。"}' AS JSON))
WHERE `id` = 'A229';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子演练＋真实'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '想要别人的东西时用问的，替代直接抢。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"演练：他想要你手上的东西，教他问「借我玩一下好吗？」"},{"imageUrl":null,"instruction":"问了就借给他，让他体验「问的有用」。"},{"imageUrl":null,"instruction":"教配套：拿到说谢谢、玩完还回去。"},{"imageUrl":null,"instruction":"也练被拒绝怎么办。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '演练会问'),
  `harder` = COALESCE(`harder`, '真实场合先问不先抢。'),
  `tip` = COALESCE(`tip`, '孩子伸手要抢时按住节奏，先教他问——问来的玩具玩得安稳，还赚到人缘。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组八（分享与合作入门）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子伸手就抢，不是没礼貌，是他不知道还有别的办法。今天给他一句话，替代那只手。","principles":["抢东西是最原始的取得方式，孩子一开始只会这个。","要换掉它，必须给一个同样有效的替代方式。","「借我玩一下好吗」就是那个替代方式。","演练时他一问就借给他，让他体验「问的比抢的有用」。","如果问了拿不到，他就会退回去用抢的，因为抢比较快。","配套动作要一起教：拿到说谢谢，玩完还回去。","这三步合起来才是完整的借用流程。","也要练被拒绝：不是每次问了都能借到。","这样他才不会因为一次被拒绝就放弃这个方法。"],"prep":{"场地":"在家演练；真实场合在公园或亲友家。","器材":"不需要特别准备，用当下的玩具即可。","安全检查":"真实场合中对方拒绝就立刻带开，不僵持不争夺。","大人位置":"演练时大人手上拿着孩子想要的东西。"},"shots":[{"name":"孩子伸手要抢","say":"（孩子伸手去拿大人手上的玩具）"},{"name":"给他那句话","say":"说：借我玩一下好吗？"},{"name":"问了就借","say":"好呀，借你！"},{"name":"拿到说谢谢","say":"谢谢。"},{"name":"玩完还回去","say":"玩好了，还你。"},{"name":"也练被拒绝","say":"（大人说「我现在还在玩」）好吧，我等一下。"}],"reactions":[{"if":"孩子直接抢走","then":"温和地把东西拿回来，说「用问的」，等他问了再给。"},{"if":"孩子问了却没拿到","then":"在演练阶段一定要给。真实场合拿不到就带他做「被拒绝三步」。"},{"if":"孩子借了不还","then":"到时间温和地说「玩好了，我们还给他」，并陪他一起走过去。"}],"mistakes":["演练时也拒绝孩子，他学到问了没用。","只教问，没教说谢谢和归还。","孩子抢了就骂，但没有给他替代的方法。"],"down":"只练「借我」两个字，并由大人立刻给予。","up":"真实场合先问不先抢，并完整做到谢谢与归还。","progress":["会不会用问的而不是抢的。","拿到后会不会说谢谢。","玩完会不会主动归还。"],"outro":"演练的时候，他一问你就要给——让他确认问的有用。配套两件事别忘了：拿到说谢谢，玩完要还回去。"}' AS JSON))
WHERE `id` = 'A230';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–5岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子的玩具'),
  `trains` = COALESCE(`trains`, '建立分享的信任：给出去不等于失去。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"请他把玩具「给妈妈看一下」。"},{"imageUrl":null,"instruction":"拿到手看两秒，马上还「谢谢，还给你！」"},{"imageUrl":null,"instruction":"反复玩，慢慢延长拿的时间。"},{"imageUrl":null,"instruction":"每次都守信归还。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '给出两秒就还'),
  `harder` = COALESCE(`harder`, '给出较久也不焦虑。'),
  `tip` = COALESCE(`tip`, '孩子不肯分享，多半是怕「给了就没了」。上百次说到做到的归还，比一百句「要分享」有用。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组八（分享与合作入门）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子死抓着玩具不放，是因为他还不确定给出去会不会回来。今天用一个小游戏，把这件事证明给他看。","principles":["幼儿分不清「借出去」和「永远失去」，所以抓得很紧。","这不是自私，是物体恒存概念在社交场景中的延伸还不成熟。","要建立信任，必须用大量的成功经验来证明。","请他把玩具给你看一下，拿到手两秒就还。","两秒短到他还来不及焦虑，成功就发生了。","反复玩，慢慢延长拿在手上的时间。","每一次都必须守信归还，一次都不能例外。","只要有一次没还，之前累积的信任就会打折。","这个基础建立好，后面的分享和轮流才有可能。"],"prep":{"场地":"地板或桌边，两人面对面。","器材":"孩子的玩具，从他没那么在意的开始。","安全检查":"不使用孩子最依恋的安抚物做这个练习；孩子明显焦虑就立刻归还。","大人位置":"大人坐在孩子正对面，伸手接、伸手还，动作清楚。"},"shots":[{"name":"请他给你看","say":"给妈妈看一下好吗？"},{"name":"他交出来","say":"（孩子犹豫地递过来）"},{"name":"两秒就还","say":"谢谢，还给你！"},{"name":"反复玩","say":"（快剪几次来回）"},{"name":"慢慢拉长","say":"（这次拿了五秒才还）"},{"name":"每次都守信","say":"（每一次都确实还回去）"}],"reactions":[{"if":"孩子不肯给","then":"改成你只用一根手指碰一下就说谢谢。从零风险开始建立。"},{"if":"孩子给了立刻要回去","then":"马上还。他要回去就是还没准备好，缩短时间重来。"},{"if":"孩子给了之后开始哭","then":"立刻归还并抱抱。这个练习绝对不能变成焦虑来源。"}],"mistakes":["拿着不还，想「训练」他忍耐，信任就毁了。","用他最依恋的安抚物来练，焦虑太高。","一开始就拿太久，孩子还没建立信任。"],"down":"大人只碰一下、看一眼就还，时间接近于零。","up":"能把玩具给出去较长时间（十秒以上）不焦虑，并主动拿给别人看。","progress":["愿不愿意把玩具给出去。","能忍受多长的时间。","有没有开始主动拿东西给人看。"],"outro":"两秒就还，每一次都守信。给出去会回来这件事，要用几十次的成功经验来证明——一次都不能例外。"}' AS JSON))
WHERE `id` = 'A231';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '稍大的箱子或垫子'),
  `trains` = COALESCE(`trains`, '两个人合力做一件事，体验合作。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"找一件一个人不好拿的东西。"},{"imageUrl":null,"instruction":"「我们一起抬！」一人一边。"},{"imageUrl":null,"instruction":"喊口令「一、二、走！」"},{"imageUrl":null,"instruction":"抬到目的地一起欢呼「我们做到了！」"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '短距离合抬'),
  `harder` = COALESCE(`harder`, '要转弯或上台阶。'),
  `tip` = COALESCE(`tip`, '一个人抬不动、两个人就行——合作的好处一秒就懂，不用解释。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组八（分享与合作入门）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"合作最好懂的形式，就是一个人做不到、两个人可以。今天找一样东西一起抬。","principles":["合作这个概念很抽象，但一起抬一个箱子是具体的。","一个人抬不动、两个人抬得动，因果非常清楚。","孩子会直接体验到「加上你，事情就成了」。","喊口令「一、二、走」让两个人的动作同步。","同步的动作会产生连结感，这是合作的情感基础。","过程中必须互相配合速度和方向，这就是协调。","抬到目的地一起欢呼，把成果明确地归给「我们」。","「我们做到了」这句话，比「你好棒」更适合合作情境。","难度可以从直线走，进到转弯、上台阶，协调要求越来越高。"],"prep":{"场地":"客厅到房间的一段路，地面清空防滑。","器材":"一个孩子一个人搬不动、但两人可以的箱子或软垫（不要太重）。","安全检查":"物品重量以孩子能轻松分担为准；不抬会压伤脚的重物；路线上无门槛与障碍物。","大人位置":"大人在另一端，主动承担大部分重量。"},"shots":[{"name":"一个人抬不动","say":"（孩子一个人搬不动箱子）"},{"name":"我们一起抬","say":"我们一起抬！"},{"name":"喊口令","say":"一、二、走！"},{"name":"一起走","say":"（两人抬着走）"},{"name":"放下来","say":"到了，放下来——"},{"name":"一起欢呼","say":"我们做到了！"}],"reactions":[{"if":"孩子抬不动或松手","then":"大人多承担一点重量，让他只需要扶着就好。成功比出力重要。"},{"if":"两人步调不一致","then":"放慢速度，喊口令喊得更清楚：「慢——慢——走。」"},{"if":"孩子觉得无聊","then":"加一点挑战：绕过椅子、走到指定的地方，任务感会提高兴趣。"}],"mistakes":["东西太重，孩子出不了力也不安全。","大人一个人抬完，孩子变成旁观者。","完成后说「你好棒」而不是「我们做到了」，合作感就散了。"],"down":"东西轻一点、距离短一点，孩子只要扶着一边就算参与。","up":"路线需要转弯或上台阶，两人必须更多沟通与协调。","progress":["愿不愿意参与一起抬。","能不能配合对方的速度。","会不会自己喊口令或提出方向。"],"outro":"一个人做不到、两个人可以——这就是合作最好懂的形式。完成的时候说「我们做到了」，不要说「你好棒」。"}' AS JSON))
WHERE `id` = 'A232';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或同伴'),
  `need` = COALESCE(`need`, '积木'),
  `trains` = COALESCE(`trains`, '两个人轮流盖同一个作品。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"宣布「我们一起搭一座塔」。"},{"imageUrl":null,"instruction":"你放一块、我放一块，轮流加高。"},{"imageUrl":null,"instruction":"倒了一起笑、一起重来。"},{"imageUrl":null,"instruction":"搭好一起欣赏「我们的塔！」"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '轮流放块'),
  `harder` = COALESCE(`harder`, '商量着搭出造型。'),
  `tip` = COALESCE(`tip`, '从「我的塔」到「我们的塔」——共同完成的作品，成就感是双份的。倒了一起笑着重来，比塔本身珍贵。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组八（分享与合作入门）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"两个人盖同一个作品，比各盖各的难得多——因为你要接受别人放的那一块。","principles":["一起做同一件作品，是比一起抬东西更高一阶的合作。","因为成果是共享的，过程中必须接受别人的决定。","轮流放积木，每一次都在练「等」和「接受」。","别人放的位置不一定是你想要的，这就是合作的真实样貌。","塔倒了一起笑、一起重来，是很重要的一课。","因为共同的失败会加强连结，而不是互相指责。","搭好了一起欣赏，用「我们的塔」来命名成果。","这个命名让孩子体会到共同拥有的感觉。","进阶是商量着搭出造型，那就需要沟通和协商了。"],"prep":{"场地":"地板或矮桌，两人都伸得到的位置。","器材":"积木，数量足够两人轮流放。","安全检查":"使用大颗积木避免吞入；塔倒时注意不要砸到脸，高度不超过孩子坐着的头顶。","大人位置":"大人坐在孩子对面或旁边，严格遵守轮流。"},"shots":[{"name":"宣布一起搭","say":"我们一起搭一座塔。"},{"name":"轮流放","say":"你一块、我一块。"},{"name":"接受别人的位置","say":"（大人放的位置孩子不太满意但接受了）"},{"name":"塔倒了","say":"（塔倒了，两人一起笑）"},{"name":"一起重来","say":"再来一次！"},{"name":"我们的塔","say":"你看，我们的塔！"}],"reactions":[{"if":"孩子想把大人放的拿掉","then":"温和地说「那是我放的，我们一起留着」。这就是合作要练的部分。"},{"if":"塔倒了孩子生气","then":"先笑给他看。你的反应决定他的反应，倒了是好玩不是失败。"},{"if":"孩子只想自己盖","then":"那就让他盖，你在旁边盖自己的。平行玩也可以，不必强求合作。"}],"mistakes":["大人一直调整孩子放的位置，合作就变成大人主导。","塔倒了露出可惜或责怪的反应，孩子会怕失败。","完成后说「我盖的比较好」，共同拥有的感觉就没了。"],"down":"只要求轮流放块，不要求造型，倒了也不重要。","up":"商量着搭出指定的造型（桥、房子），过程中需要沟通协调。","progress":["能不能轮流不抢着放。","接不接受别人放的位置。","塔倒了的反应。"],"outro":"合作最难的部分，是接受别人放的那一块。塔倒了记得先笑——你的反应，决定他怎么看待失败。"}' AS JSON))
WHERE `id` = 'A233';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '全家'),
  `need` = COALESCE(`need`, '简单的桌游'),
  `trains` = COALESCE(`trains`, '在规则游戏里练轮流、守规则、面对输赢。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选规则很简单的游戏。"},{"imageUrl":null,"instruction":"明确顺序「爸爸→宝宝→妈妈」。"},{"imageUrl":null,"instruction":"轮到才能玩，别人玩时看着等。"},{"imageUrl":null,"instruction":"玩完整局，不半途而废。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三人短局'),
  `harder` = COALESCE(`harder`, '安静等轮、完成整局。'),
  `tip` = COALESCE(`tip`, '桌游是轮流、等待、守规则的最好教室，还是高质量的亲子时间。每周一次家庭桌游夜。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组六（轮流等待·互动规则）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"桌游是练社交最划算的工具——轮流、守规则、面对输赢，三件事一次练到。但游戏要选对。","principles":["桌游把社交规则压缩在一个小小的框架里，练习密度很高。","一局游戏里，轮流会发生十几次，比日常生活密集得多。","守规则也是在练，因为规则是外在的、不能因为不喜欢就改。","输赢在游戏里是必然的，所以也在练面对结果。","选游戏很关键：规则要非常简单，一局要很短。","规则复杂孩子会卡在理解上，练不到社交。","一局太长，等待的时间就太久，孩子会撑不住。","明确宣告顺序「爸爸→宝宝→妈妈」，让轮流看得见。","玩完整局不半途而废，是在练完成和承担结果。"],"prep":{"场地":"餐桌或地板，全家围坐，彼此都看得到。","器材":"规则极简、一局三到五分钟的桌游（掷骰前进、配对翻牌）。","安全检查":"小零件游戏不给三岁以下孩子；避免长时间久坐，每局之间起来动一动。","大人位置":"大人当主持人，明确宣告顺序与规则，自己也遵守。"},"shots":[{"name":"选对游戏","say":"规则要简单，一局要短。"},{"name":"宣告顺序","say":"爸爸→宝宝→妈妈，这样轮。"},{"name":"轮到才能玩","say":"（孩子伸手，大人指着说「还没轮到」）"},{"name":"别人玩时看着等","say":"（孩子看着别人操作）"},{"name":"大人也守规则","say":"（大人也等自己的回合）"},{"name":"玩完整局","say":"我们把它玩完。"}],"reactions":[{"if":"孩子等不到自己的回合","then":"给他一个等待时的任务：帮忙数点数、帮忙洗牌。有事做就等得住。"},{"if":"孩子想改规则","then":"开局前可以一起商量规则，但开始之后就照原本的走。"},{"if":"孩子中途想退出","then":"先问是不是太久了。可以缩短这一局，但尽量走到结束。"}],"mistakes":["选规则太复杂的游戏，孩子卡在理解上。","一局太长，孩子等到失去耐性。","大人自己不守规则或一直放水。"],"down":"三个人玩、一局两分钟以内，并让孩子在等待时有小任务。","up":"四人以上、局数较长的游戏，能安静等待并完整走完。","progress":["能不能等到自己的回合。","会不会遵守规则不擅自更改。","能不能玩完整局不中途离开。"],"outro":"游戏要选对：规则简单、一局要短。等待的时候给他一个小任务——有事做，就等得住。"}' AS JSON))
WHERE `id` = 'A234';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子演练'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '冲突时的第一条规则：手停住、脚停住。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"教口诀「生气了？停！」配一个停止手势。"},{"imageUrl":null,"instruction":"演练：抢玩具的情境，喊「停」他就定住。"},{"imageUrl":null,"instruction":"停住后深呼吸一口。"},{"imageUrl":null,"instruction":"真的冲突时用同一个手势提示。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '听提示停住'),
  `harder` = COALESCE(`harder`, '自己在动手前刹住。'),
  `tip` = COALESCE(`tip`, '冲突里的第一秒最关键——刹得住车，后面才有得谈。这个反射要在平静时反复练。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十一（冲突与修复）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"冲突发生的那一秒，讲道理来不及。要先有一个动作能把手停住——今天练这个动作。","principles":["冲突当下的第一优先是停止动作，不是讲道理。","手停住、脚停住，伤害就不会发生，后面才有空间处理。","所以要先练一个简单、能立刻执行的停止反应。","口诀「生气了？停！」加上一个固定的手势，越简单越好。","手势比语言快，在吵闹的环境里也看得到。","要在平静的时候演练，而且要演得像游戏一样好玩。","练熟了，真实冲突时同一个手势才叫得住他。","停住之后加一口深呼吸，把身体的冲动往下压。","这一招不解决问题，但它买到了处理问题需要的那几秒。"],"prep":{"场地":"客厅有空间的地方，可以跑动。","器材":"不需要任何东西；可以用玩具模拟抢夺情境。","安全检查":"演练时不真的推挤或抢夺；孩子已经动手时先用身体温和隔开再用手势。","大人位置":"大人做出清楚的停止手势，声音短促有力但不吼。"},"shots":[{"name":"教口诀与手势","say":"生气了？停！"},{"name":"玩定格游戏","say":"（跑一跑，喊停就定住）"},{"name":"模拟抢玩具","say":"（两人同时伸手拿同一个玩具）"},{"name":"喊停","say":"停！"},{"name":"深呼吸一口","say":"吸——吐——"},{"name":"真实冲突时用同一个手势","say":"（真实场合举起同样的手势）"}],"reactions":[{"if":"孩子停不住","then":"大人用身体温和挡在中间，先确保安全，再做手势。安全永远优先。"},{"if":"孩子觉得被凶","then":"把声音放短不放大。停止靠的是明确，不是音量。"},{"if":"孩子停住后立刻又动","then":"那就先在停住的姿势里做一次深呼吸，给身体一点时间。"}],"mistakes":["用吼的代替手势，孩子学到的是被吓住不是自己停住。","只在真实冲突时用，平常没有玩过定格游戏。","每次用不同的手势或说法，孩子来不及反应。"],"down":"只玩定格游戏，不连结到冲突情境，先把「听到停就定住」练熟。","up":"在真实冲突中自己在动手前刹住，不需要大人提示。","progress":["听到口令会不会停住。","看到手势会不会停住。","真实冲突中有没有出现自己刹住的迹象。"],"outro":"手势要固定，声音要短不要大。这一招不解决问题，但它买到了处理问题需要的那几秒。"}' AS JSON))
WHERE `id` = 'A235';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子演练'),
  `need` = COALESCE(`need`, '玩偶'),
  `trains` = COALESCE(`trains`, '冲突时用话表达，替代打人抢夺。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"用玩偶演「被抢玩具」。"},{"imageUrl":null,"instruction":"教几句：「还给我！」「轮到我了」「我不喜欢你这样」。"},{"imageUrl":null,"instruction":"练语气：坚定但不吼。"},{"imageUrl":null,"instruction":"真的冲突时提示「用说的」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着玩偶练句子'),
  `harder` = COALESCE(`harder`, '真实冲突中先说不先动手。'),
  `tip` = COALESCE(`tip`, '打人常是因为「没有别的办法」——给他管用的句子，并确保他说了以后大人会帮忙处理，动手自然就少了。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十一（冲突与修复）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"停住之后呢？要有话可以说。今天给他三句，而且要练语气——坚定，但不是用吼的。","principles":["停住只是第一步，停住之后没有话说，还是会退回动手。","所以要给他具体的句子，而且要练到能脱口而出。","三句就够：「还给我！」「轮到我了。」「我不喜欢你这样。」","这三句涵盖了要回东西、主张权利、表达感受三种情况。","语气很重要：坚定但不吼，太软没有效果，太凶变成攻击。","用玩偶演练最好，因为对玩偶练没有真实的情绪压力。","演练时要把语气练出来，不只是背句子。","真实冲突时大人只要提示两个字「用说的」就好。","提示要短，因为冲突当下孩子的处理能力很有限。"],"prep":{"场地":"客厅地板，两人和玩偶围坐。","器材":"两个玩偶，一个玩具当被抢的对象。","安全检查":"演练不真的抢夺推挤；语气示范不模仿吼叫或辱骂。","大人位置":"大人操作玩偶，示范完整的句子和语气。"},"shots":[{"name":"玩偶被抢了","say":"（一只玩偶抢走另一只的车）"},{"name":"第一句","say":"还给我！"},{"name":"第二句","say":"轮到我了。"},{"name":"第三句","say":"我不喜欢你这样。"},{"name":"练语气","say":"（示范太小声、太凶、刚刚好三种）"},{"name":"真实时只提示两个字","say":"用说的。"}],"reactions":[{"if":"孩子说不出来只会哭","then":"大人替他说一次，让对方听到。示范之后再鼓励他自己说。"},{"if":"孩子用吼的","then":"不纠正内容，只调语气：「同样这句话，小声一点说说看。」"},{"if":"孩子说了对方不理","then":"那就由大人介入处理。说了没用不是他的错，但要让他看到说话是有后续的。"}],"mistakes":["只教不可以打，没有教可以说什么。","句子太长，冲突当下说不出来。","真实冲突时大人说一长串道理，孩子根本听不进去。"],"down":"只练一句「还给我」，并用玩偶演练不连结真实情境。","up":"真实冲突中先说不先动手，并能依情况选用不同的句子。","progress":["演练中说不说得出这些句子。","语气坚定但不吼吗。","真实冲突中有没有先说。"],"outro":"三句话：还给我、轮到我了、我不喜欢你这样。语气要坚定但不用吼——真实冲突时，你只要说两个字：用说的。"}' AS JSON))
WHERE `id` = 'A236';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或同伴'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '用公平的办法解决「谁先」的争执。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"两人都想先玩时，用石头剪刀布决定。"},{"imageUrl":null,"instruction":"输的一方练习说「好吧，你先」。"},{"imageUrl":null,"instruction":"下一轮自动轮换。"},{"imageUrl":null,"instruction":"定了就认账。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '会用猜拳决定'),
  `harder` = COALESCE(`harder`, '输了也爽快认。'),
  `tip` = COALESCE(`tip`, '「谁先」是孩子冲突的第一大案——家里立个规矩「争谁先就猜拳」，很多架根本吵不起来。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十一（冲突与修复）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「我先！」「我先！」——这种争执不用讲理，用猜拳。让运气来决定，谁都不用输给对方。","principles":["「谁先」的争执几乎每天都会发生，而且没有谁对谁错。","所以不需要讲道理，需要的是一个公平的决定方式。","猜拳是最好的工具：快、公平、而且结果没有人能操控。","输给运气，比输给对方容易接受得多。","这就是这个方法最大的价值：保住了双方的面子。","输的一方练习说「好吧，你先」，把接受说出口。","说出口的接受，比闷着不说更能真的放下。","下一轮自动轮换，让输的人知道机会马上就来。","最重要的一条：定了就认账，不能重猜。"],"prep":{"场地":"任何地方，两人面对面。","器材":"不需要任何东西。","安全检查":"无特殊风险。避免用猜拳决定重要或不可逆的事。","大人位置":"大人示范猜拳流程，并示范输了怎么说。"},"shots":[{"name":"两人都想先","say":"（两个孩子同时喊「我先」）"},{"name":"用猜拳决定","say":"我们猜拳决定。"},{"name":"猜拳","say":"石头、剪刀、布！"},{"name":"输的人说好吧","say":"好吧，你先。"},{"name":"下一轮轮换","say":"下一次换你先。"},{"name":"定了就认账","say":"（孩子想重猜，大人摇头）"}],"reactions":[{"if":"孩子输了要重猜","then":"温和坚持：「我们说好猜一次。」下一轮很快就来，这一点要讲清楚。"},{"if":"孩子不会猜拳","then":"先教手势，或改用更简单的方法（抽签、数数字）。"},{"if":"孩子输了还是很不甘","then":"接住情绪：「你很想先玩。」再提醒下一轮马上就到。"}],"mistakes":["大人直接指定谁先，另一方会觉得不公平。","允许重猜，猜拳就失去了公信力。","输了没有下一轮，孩子会觉得输就没机会了。"],"down":"用更简单的方式决定（抽签、比谁生日近），并由大人主持。","up":"输了爽快认账，并能自己提议用猜拳解决争执。","progress":["会不会用猜拳解决争执。","输了能不能说出「好吧，你先」。","有没有要求重猜。"],"outro":"输给运气，比输给对方容易接受。输的人要说出口「好吧，你先」——而且定了就认账，不能重猜。"}' AS JSON))
WHERE `id` = 'A237';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子演练'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会道歉和接受道歉。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"道歉不只说「对不起」，还要说错在哪：「我不该抢你的车」。"},{"imageUrl":null,"instruction":"再加一个补救：「还给你」。"},{"imageUrl":null,"instruction":"接受道歉的人说「没关系」。"},{"imageUrl":null,"instruction":"说完就翻篇，不再翻旧账。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说「对不起」'),
  `harder` = COALESCE(`harder`, '说清错处并主动补救。'),
  `tip` = COALESCE(`tip`, '逼一句敷衍的「对不起」没有用——带他走完「说抱歉＋说错在哪＋想办法补」，关系才真的修好。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十一（冲突与修复）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"只说三个字「对不起」是不够的。完整的道歉有三个部分——今天把它拆开来教。","principles":["只说「对不起」，孩子不一定知道自己错在哪。","所以道歉要说清楚错处：「我不该抢你的车。」","说出错处，才代表他真的理解发生了什么。","第三个部分是补救：「还给你。」","有补救的道歉才完整，光说不做，对方感受不到诚意。","接受道歉的人说「没关系」，让这件事有个明确的结束。","说完就翻篇，不再翻旧账，这一点大人尤其要做到。","如果大人事后还一直提，孩子会觉得道歉没有用。","不要强迫孩子道歉，被逼出来的对不起没有意义。"],"prep":{"场地":"客厅演练；真实冲突后在双方都平静时进行。","器材":"玩偶或实际发生冲突的物品。","安全检查":"不强押孩子道歉；孩子情绪未平复时先安抚，不当场逼迫。","大人位置":"大人示范完整的三段式道歉，包括自己对孩子道歉。"},"shots":[{"name":"发生冲突","say":"（玩偶抢走另一只的车）"},{"name":"第一段对不起","say":"对不起。"},{"name":"第二段说错处","say":"我不该抢你的车。"},{"name":"第三段补救","say":"还给你。"},{"name":"对方说没关系","say":"没关系。"},{"name":"说完就翻篇","say":"（两人继续玩，不再提）"}],"reactions":[{"if":"孩子不肯道歉","then":"不强押。先安抚情绪，等平静了再谈。被逼出来的道歉没有意义。"},{"if":"孩子只说对不起不说错处","then":"由大人帮他说一次：「他是说不该抢你的车。」示范完整版本。"},{"if":"对方不肯说没关系","then":"尊重。原谅需要时间，可以说「他现在还有点难过，等一下」。"}],"mistakes":["强押孩子说对不起，他学到的是敷衍。","道歉之后大人还一直翻旧账，道歉就失去意义。","只教道歉不教接受道歉，另一半没有练到。"],"down":"只说「对不起」三个字，加上一个补救的动作（把东西还回去）。","up":"完整说出三段，并能在没有提示的情况下主动道歉。","progress":["愿不愿意道歉。","会不会说清楚错在哪。","有没有主动做出补救的动作。"],"outro":"完整的道歉有三段：对不起、说清楚错在哪、做一个补救。还有最重要的一条——说完就翻篇，大人也不要再提。"}' AS JSON))
WHERE `id` = 'A238';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或同伴'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '给和好一个看得见的仪式。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"道歉原谅之后，加一个动作：拉钩、击掌、抱一下。"},{"imageUrl":null,"instruction":"一起说「我们和好啦！」"},{"imageUrl":null,"instruction":"然后马上一起玩点什么。"},{"imageUrl":null,"instruction":"家里吵架也用同一个仪式收尾。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '做和好的动作'),
  `harder` = COALESCE(`harder`, '主动发起和好。'),
  `tip` = COALESCE(`tip`, '和好仪式是冲突的「关门声」——咔哒一下，两个人都知道这页翻过去了，不用再猜「我们还好吗」。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十一（冲突与修复）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"道歉完了，气氛还是怪怪的？那是因为缺一个收尾的动作。给和好一个仪式，事情才真的过去。","principles":["道歉和原谅之后，常常还留着一点尴尬。","因为语言上结束了，但身体和情绪还没有转换。","一个动作可以完成这个转换：拉钩、击掌、抱一下。","身体的接触会让情绪真的翻页，这不只是形式。","一起说「我们和好啦」，把结束明确地宣告出来。","有明确的结束，孩子就知道这件事过去了。","然后马上一起玩点什么，用新的正向经验覆盖掉冲突。","家里大人吵架也用同一个仪式收尾，孩子会学到修复关系是正常的。","看过大人修复关系的孩子，比较不怕冲突。"],"prep":{"场地":"冲突发生的地方，双方都平静之后。","器材":"不需要任何东西。","安全检查":"不强迫肢体接触；孩子不愿意就改成击掌或点头即可。","大人位置":"大人主持仪式，并在自己与孩子冲突后也照做。"},"shots":[{"name":"道歉原谅之后","say":"（两人刚说完对不起、没关系）"},{"name":"加一个动作","say":"我们来拉钩。"},{"name":"一起说出来","say":"我们和好啦！"},{"name":"换个动作也可以","say":"（击掌、抱一下）"},{"name":"马上一起玩","say":"我们来玩球！"},{"name":"大人也用","say":"（爸妈争执后也做同样的动作）"}],"reactions":[{"if":"孩子不愿意做动作","then":"不强迫。改成击掌或只是点点头，形式可以简化。"},{"if":"和好之后又吵起来","then":"正常。再走一次流程就好，孩子需要很多次练习。"},{"if":"孩子只跟大人和好不跟同伴和好","then":"先从大人练起。熟悉这个仪式之后再推到同伴。"}],"mistakes":["强迫拥抱，孩子还没准备好会更抗拒。","和好之后大人还板着脸，仪式就没有说服力。","只做仪式不接着一起玩，情绪没有真的转过来。"],"down":"只做最简单的动作（击掌一次），不要求说话。","up":"主动发起和好，并能在冲突后自己走完道歉与和好的流程。","progress":["愿不愿意做和好的动作。","会不会一起说「我们和好啦」。","有没有开始主动发起和好。"],"outro":"给和好一个看得见的动作，然后马上一起玩点什么。家里大人吵架也用同一个仪式——孩子会学到，关系是可以修复的。"}' AS JSON))
WHERE `id` = 'A239';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子＋同伴'),
  `need` = COALESCE(`need`, '约一个小伙伴'),
  `trains` = COALESCE(`trains`, '把学到的都用到真实的同伴互动里。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"约一个孩子来家里玩，或去公园找伙伴。"},{"imageUrl":null,"instruction":"出发前定一个小目标（今天练打招呼／练问「可以一起玩吗」）。"},{"imageUrl":null,"instruction":"大人退后一点，让他们自己玩。"},{"imageUrl":null,"instruction":"回家夸一件他做得好的事。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '能和一个熟悉的伙伴玩在一起'),
  `harder` = COALESCE(`harder`, '加入不熟的小朋友。'),
  `tip` = COALESCE(`tip`, '每次只定一个小目标，比什么都要求有效。一个固定的好玩伴，胜过十次陌生的聚会——帮孩子「选对人」比练技巧见效更快。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组五～九（社交进入 · 规则 · 维持 · 分享 · 游戏发展）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"前面十九个活动都是准备，这一个才是正式上场。出发前定一个小目标，然后——大人退后一点。","principles":["所有社交技巧最终都要在真实的同伴互动里才算数。","所以一定要安排真实的机会，光在家演练不够。","出发前定一个小目标，让这次玩有明确的焦点。","目标要小：今天只练打招呼，或只练问「可以一起玩吗」。","目标太大孩子达不到，反而变成压力。","大人退后一点，是这个活动最关键的一步。","大人一直在旁边指导，孩子就没有真正的互动空间。","让他们自己玩，包括让他们自己处理小摩擦。","回家夸一件他做得好的事，具体地说出来。"],"prep":{"场地":"家里（约一个孩子来玩）或公园、游戏场。","器材":"准备两份同款玩具，减少争抢；准备点心。","安全检查":"家中环境先做安全检查；全程大人在视线范围内；有肢体冲突风险时立即介入。","大人位置":"大人退到几步远的位置，看得到但不介入，除非有安全问题。"},"shots":[{"name":"出发前定目标","say":"今天我们只练一件事：跟他打招呼。"},{"name":"见面","say":"（孩子挥手说你好）"},{"name":"大人退后","say":"（大人走到几步远坐下）"},{"name":"他们自己玩","say":"（两个孩子自己互动）"},{"name":"小摩擦自己处理","say":"（有点争执，大人观望没有立刻介入）"},{"name":"回家具体称赞","say":"你今天一见面就跟他说你好，很棒。"}],"reactions":[{"if":"孩子全程黏着大人","then":"不推开。陪着他站近一点，等他准备好。有些孩子需要好几次才敢。"},{"if":"两个孩子起冲突","then":"先观望几秒看他们能不能自己解决；有推打就立刻介入并分开。"},{"if":"这次完全没达成目标","then":"不检讨。找一件他做到的小事来夸，下次再约。"}],"mistakes":["大人一直在旁边指挥，孩子没有真正的互动。","目标定太大，孩子压力大反而退缩。","回家检讨他哪里做不好，下次他就不想去了。"],"down":"只约一个非常熟悉的伙伴，时间短（三十分钟），目标只有一个动作。","up":"加入不熟悉的小朋友，并能自己完成加入、轮流与冲突处理。","progress":["愿不愿意接近其他孩子。","有没有达成这次设定的小目标。","能和同伴持续玩多久。"],"outro":"出发前定一个很小的目标，然后大人退后几步。回家只夸他做到的那一件事——不检讨，下次他才愿意再去。"}' AS JSON))
WHERE `id` = 'A240';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '成对的图卡或扑克牌'),
  `trains` = COALESCE(`trains`, '记住卡片的位置，练视觉记忆。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把成对的卡片盖着摊开。"},{"imageUrl":null,"instruction":"轮流翻两张，一样就拿走。"},{"imageUrl":null,"instruction":"不一样就盖回去，记住位置。"},{"imageUrl":null,"instruction":"看谁配对最多。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '四对（八张）'),
  `harder` = COALESCE(`harder`, '八对以上。'),
  `tip` = COALESCE(`tip`, '从四对开始，太多会挫折。翻牌时轻声说出位置（「左上是苹果」），记得会更牢——这个方法可以教给孩子。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组八（记忆力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"翻牌配对看起来只是游戏，其实练的是一项很重要的能力——把看到的东西暂时存在脑袋里。","principles":["翻牌配对练的是视觉工作记忆，也就是把看到的位置暂时记住。","工作记忆是学习的核心能力，日后读题、计算、抄写都靠它。","孩子必须记住「刚才那张在哪里」，同时还要判断现在这张配不配。","两件事同时进行，所以这个游戏比看起来难。","张数一定要从少开始，四对八张对幼儿刚好。","张数太多孩子记不住，会变成乱翻，就练不到记忆了。","成功了再慢慢加，每次加一两对就好。","大人不要故意输，但可以偶尔「忘记」某张的位置。","这个游戏一局很短，很适合每天玩一两次累积。"],"prep":{"场地":"桌面或地板，卡片摊得开的平面。","器材":"四到八对图卡或扑克牌；图案差异要明显。","安全检查":"卡片使用圆角或护贝，避免纸缘割手；不使用太小的卡片给三岁以下孩子。","大人位置":"大人坐在孩子对面或旁边，轮流翻，不抢先提示。"},"shots":[{"name":"摊开卡片","say":"我们来玩翻牌配对。"},{"name":"翻两张","say":"（孩子翻开两张）"},{"name":"不一样盖回去","say":"不一样，盖回去——记住位置喔。"},{"name":"配对成功","say":"一样！拿走！"},{"name":"从四对开始","say":"（画面显示只有八张牌）"},{"name":"慢慢加","say":"下次我们加两对。"}],"reactions":[{"if":"孩子一直乱翻记不住","then":"减少张数到三对。张数超过能力就只是乱翻，练不到记忆。"},{"if":"孩子翻到不对就生气","then":"先接住情绪，并示范「我也常常忘记」。让失误变成正常的事。"},{"if":"孩子每次都赢不了","then":"适度调整：让他先翻，或大人偶尔翻已经翻过的。不必刻意输到明显。"}],"mistakes":["一开始就摊出太多张，孩子记不住就乱翻。","在孩子思考时急着提示位置。","把它当成测验，一直问「你记不记得」。"],"down":"只用三对六张，并且第一轮全部翻开看过一次再开始。","up":"八对以上，或加入相似度高的图案增加辨识难度。","progress":["一局能配对几对。","会不会记住翻过的位置。","能处理的张数有没有增加。"],"outro":"张数一定要从少开始——四对刚刚好。超过他记得住的范围，就只是在乱翻，什么都没练到。"}' AS JSON))
WHERE `id` = 'A241';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几样小东西＋一块布'),
  `trains` = COALESCE(`trains`, '记住看过的东西，发现少了哪一样。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"桌上摆三样东西，让孩子看十秒。"},{"imageUrl":null,"instruction":"用布盖住，偷偷拿走一样。"},{"imageUrl":null,"instruction":"打开问「少了什么？」"},{"imageUrl":null,"instruction":"慢慢加到五六样。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三样、差异大'),
  `harder` = COALESCE(`harder`, '六样以上，或改变位置。'),
  `tip` = COALESCE(`tip`, '答对了追问「你怎么记住的？」——让孩子发现自己用的方法，记忆力会进步得更快。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"桌上摆三样东西，看十秒，盖起来——少了什么？这个游戏不用买教具，家里什么都能玩。","principles":["这个游戏练的是视觉记忆中的「记住整体」再比对差异。","孩子必须先把三样东西记下来，才发现得出少了哪一样。","这需要主动记忆，而不是被动看过去。","所以看的那十秒要引导他真的去看：「你看，有杯子、有汤匙、有球。」","说出来会大幅提高记住的机会，这叫做语言编码。","数量从三样开始，差异要大，成功率才高。","成功几次再慢慢加到五六样。","进阶玩法是不拿走，只改变位置，那更难。","这个能力和日后找东西、检查作业、发现错字都有关。"],"prep":{"场地":"桌面，物品摆得开、孩子坐得舒服的位置。","器材":"三到六样日常小物（杯子、汤匙、小车、积木）＋一块布。","安全检查":"不使用可吞入的小物给三岁以下孩子；布料轻薄不厚重，不盖住孩子的脸。","大人位置":"大人坐在孩子对面，负责盖布和拿走物品。"},"shots":[{"name":"摆出三样","say":"你看，有杯子、有汤匙、有球。"},{"name":"看十秒","say":"看清楚喔，十、九、八……"},{"name":"盖上布","say":"（用布盖住）"},{"name":"偷偷拿走一样","say":"（大人从布下抽走一样）"},{"name":"打开问","say":"少了什么？"},{"name":"慢慢加数量","say":"下次我们摆五样。"}],"reactions":[{"if":"孩子完全想不起来","then":"减到两样，并在看的时候一起把名称念一遍。"},{"if":"孩子说错","then":"把布掀开一起核对：「我们看看原本有什么。」不直接给答案。"},{"if":"孩子想自己当出题的人","then":"太好了。当出题者要记得更清楚，练习效果更强。"}],"mistakes":["看的时间太短，孩子还没记住就盖起来。","一开始就摆太多样，孩子挫折。","孩子答不出来就直接公布答案，少了思考的机会。"],"down":"只摆两样，差异极大，并在观看时一起念出名称。","up":"摆六样以上，或不拿走只改变位置，要求找出哪里不一样。","progress":["能记住几样东西。","需不需要念出名称才记得住。","能不能发现位置的改变。"],"outro":"看的时候一起把名字念出来，记住的机会会大很多。从三样开始，成功了再慢慢加。"}' AS JSON))
WHERE `id` = 'A242';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '房间里的东西'),
  `trains` = COALESCE(`trains`, '记住环境的样子，发现变化。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子看一下房间的某个角落。"},{"imageUrl":null,"instruction":"请他闭眼，你移走或移动一样东西。"},{"imageUrl":null,"instruction":"张开眼睛找出哪里不一样。"},{"imageUrl":null,"instruction":"换他来藏、你来找。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '拿走明显的大东西'),
  `harder` = COALESCE(`harder`, '只移动位置或换个小东西。'),
  `tip` = COALESCE(`tip`, '这个游戏不需要任何道具，随时都能玩——等餐、坐车的时候特别好用。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把整个房间当成记忆卡片——这个游戏不用准备任何东西，而且难度可以一直往上加。","principles":["比起桌上的三样东西，整个空间的讯息量大得多。","所以这个游戏练的是更接近真实生活的视觉记忆。","孩子必须建立一个「原本的样子」的心理图像。","有了这个图像，才比对得出哪里不一样。","一开始要限定范围：先看这个角落就好，不是整间房。","范围太大孩子抓不住重点，会变成乱看。","难度可以分三阶：拿走大东西、拿走小东西、只移动位置。","只移动位置最难，因为东西还在，只是不在原处。","换孩子来藏、大人来找，他会更认真观察原本的样子。"],"prep":{"场地":"孩子熟悉的房间，先限定一个角落或一张桌面。","器材":"房间里现有的东西，不需要额外准备。","安全检查":"不移动会倒下或易碎的物品；不让孩子爬高去拿或藏东西。","大人位置":"大人负责移动物品，动作要在孩子闭眼时完成。"},"shots":[{"name":"限定范围","say":"我们只看这个书架就好。"},{"name":"看清楚","say":"看清楚它原本的样子。"},{"name":"闭眼","say":"闭上眼睛数到五。"},{"name":"找不一样","say":"张开眼睛，哪里不一样？"},{"name":"三个难度","say":"拿走大的、拿走小的、只换位置。"},{"name":"换他来藏","say":"换你藏，我来找。"}],"reactions":[{"if":"孩子找不出来","then":"缩小范围，或改拿走更明显的大东西。范围和难度要一起调。"},{"if":"孩子乱猜","then":"提示一个方向：「在上面那一层。」教他一区一区看，不要乱找。"},{"if":"孩子藏得太难","then":"笑着承认「我找不到，给我一个提示」。示范求助也是可以的。"}],"mistakes":["一开始就用整个房间，范围太大。","移动太多样，孩子不知道要找几个。","孩子找不到就催促，压力让他更看不见。"],"down":"范围缩到一张桌面，拿走一样很明显的大东西。","up":"只移动位置不拿走，或同时改变两处。","progress":["能不能找出被拿走的东西。","能处理的范围有多大。","能不能发现只是位置改变的变化。"],"outro":"先限定范围，从一个角落开始。难度有三阶：拿走大的、拿走小的、只换位置——最后一阶最难。"}' AS JSON))
WHERE `id` = 'A243';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '记住听到的一串东西并说出来，练听觉记忆。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说三样东西：「苹果、汽车、小狗」。"},{"imageUrl":null,"instruction":"让孩子复述一遍。"},{"imageUrl":null,"instruction":"对了就加到四样、五样。"},{"imageUrl":null,"instruction":"也可以说数字串。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三样'),
  `harder` = COALESCE(`harder`, '五样以上，或倒着说回来。'),
  `tip` = COALESCE(`tip`, '听觉记忆好的孩子，上课听讲比较轻松。饭桌上就能玩，一次两分钟。参考值：三岁记三样、五岁记四五样。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组八（记忆力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"苹果、汽车、小狗——请你说一遍。这个游戏练的是听觉记忆，和上课听讲、听懂指令是同一条肌肉。","principles":["听觉记忆是在教室里最常被用到的能力。","老师说的话没有画面，孩子必须靠听就记住。","复述一串词，就是最直接的听觉记忆训练。","从三样开始，多数三到四岁的孩子可以记住三样。","对了再加一样，每次加一个，不要跳。","说的时候语速要慢、间隔要清楚，让每个词都进得去。","说太快孩子听不清楚，练的就不是记忆而是听力了。","数字串也可以，效果一样，而且更接近日后的数学需求。","进阶是倒着说回来，那需要在脑中重新排序，难度高很多。"],"prep":{"场地":"安静的地方，没有背景音干扰。","器材":"不需要任何东西。","安全检查":"无特殊风险。不在孩子疲倦时做，记忆表现会失真。","大人位置":"大人面对孩子，语速放慢，每个词之间停一拍。"},"shots":[{"name":"说三样","say":"苹果、汽车、小狗。"},{"name":"孩子复述","say":"（孩子重复一遍）"},{"name":"对了就加","say":"很好，这次四样。"},{"name":"语速要慢","say":"（示范慢速与快速的差别）"},{"name":"换数字串","say":"三、七、二。"},{"name":"倒着说","say":"这次倒过来说回来。"}],"reactions":[{"if":"孩子只记得最后一样","then":"减到两样。也可以让他一边听一边用手指比数量，帮助记忆。"},{"if":"孩子顺序说错","then":"先肯定他记住了内容，再一起复习顺序，不要一次要求两件事。"},{"if":"孩子觉得无聊","then":"换成有趣的组合（大象、冰淇淋、恐龙），或让他出题考大人。"}],"mistakes":["说得太快，孩子听不清楚就记不住。","一次加太多样，孩子一直失败。","在吵杂的环境玩，练的变成听力不是记忆。"],"down":"只说两样，并在说的时候配合手指比出数量。","up":"五样以上，或要求倒着说回来。","progress":["能复述几样。","顺序对不对。","能不能倒着说回来。"],"outro":"说慢一点，每个词之间停一拍。对了再加一样——一次加一个，不要跳。"}' AS JSON))
WHERE `id` = 'A244';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '接龙式记忆游戏，越玩记得越多。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一个人说「我去买东西，买了苹果」。"},{"imageUrl":null,"instruction":"第二个人说「买了苹果和牛奶」。"},{"imageUrl":null,"instruction":"一直接下去，每次要复述全部再加一样。"},{"imageUrl":null,"instruction":"忘了就重新开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三四样'),
  `harder` = COALESCE(`harder`, '七八样以上。'),
  `tip` = COALESCE(`tip`, '这个游戏全家都能玩，大人也会忘——孩子发现「大人也记不住」，压力就小了。开车、排队时最好玩。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组八（记忆力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「我去买东西，买了苹果。」「买了苹果和牛奶。」——越接越长，这是全家都能玩的记忆游戏。","principles":["接龙式的记忆游戏，每一轮都要复述全部再加一项。","这种反复复述叫做复诵，是最有效的记忆策略之一。","孩子在游戏中自然学会了复诵，不需要特别教。","而且项目是自己加的，参与感高，记得也更牢。","前面的项目会被重复很多次，所以越前面的越好记。","中间的最容易忘，这是记忆的正常现象。","全家一起玩会有同侪压力，也有互相提示的温暖。","忘了就重新开始，不要变成惩罚。","这个游戏不需要任何道具，排队、坐车都能玩。"],"prep":{"场地":"任何地方：餐桌、车上、排队时。","器材":"不需要任何东西。","安全检查":"无特殊风险。忘记时不取笑，保持轻松。","大人位置":"大人控制节奏，必要时给一点提示。"},"shots":[{"name":"开场","say":"我去买东西，买了苹果。"},{"name":"接下去","say":"我去买东西，买了苹果和牛奶。"},{"name":"越接越长","say":"苹果、牛奶、面包、西瓜……"},{"name":"有人忘了","say":"（有人卡住，大家笑）"},{"name":"给一点提示","say":"第一样是水果……"},{"name":"重新开始","say":"我们重来一局！"}],"reactions":[{"if":"孩子记不住三样以上","then":"先玩短版：只接到三样就换新局。短而成功，比长而挫折好。"},{"if":"孩子忘了很挫折","then":"轻松带过：「大人也常常忘。」并示范自己也忘记的样子。"},{"if":"孩子想用写的","then":"那就变成另一个游戏了。可以玩，但要说明这一局练的是用脑记。"}],"mistakes":["忘了就出局，游戏变成淘汰赛。","项目加太快，孩子跟不上。","大人展现超强记忆力，孩子觉得自己很差。"],"down":"只接到三样就完成一局，并允许旁人给提示。","up":"接到七八样以上，或规定必须按顺序不能乱说。","progress":["能接到几样。","需不需要提示。","会不会自己使用复诵的方法。"],"outro":"越前面的越好记，中间的最容易忘——这是正常的。忘了就重来一局，不要变成淘汰赛。"}' AS JSON))
WHERE `id` = 'A245';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几个小玩具'),
  `trains` = COALESCE(`trains`, '记住东西藏在哪里，练空间记忆。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"当着孩子的面把三样东西藏起来。"},{"imageUrl":null,"instruction":"过一会儿（或转个圈）请他找出来。"},{"imageUrl":null,"instruction":"记住位置才找得到。"},{"imageUrl":null,"instruction":"慢慢增加数量或延长间隔。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '藏两样、马上找'),
  `harder` = COALESCE(`harder`, '藏五样、隔一会儿再找。'),
  `tip` = COALESCE(`tip`, '藏的时候让他看着，找的时候不给提示——记不住没关系，多玩几次就有进步。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组八（记忆力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"当着他的面藏三样东西，转个圈再找——练的是空间记忆，也就是记住「东西在哪里」。","principles":["空间记忆和物品记忆不一样，它记的是位置关系。","这个能力在日常生活中非常实用：找鞋子、找书包、记得东西放哪。","当着孩子的面藏，是为了让他有机会把位置记下来。","如果背着他藏，那就变成搜寻游戏，练的是别的东西。","转个圈或数到十，是制造一个短暂的间隔。","间隔让记忆从「还在眼前」变成「要从脑袋里调出来」。","数量从两样开始，间隔从很短开始。","慢慢增加数量或延长间隔，两者不要同时加。","找到的时候让他说出位置，语言会强化空间记忆。"],"prep":{"场地":"客厅或房间，有几个可以藏东西的地方。","器材":"两到五个小玩具。","安全检查":"不藏在需要爬高、开抽屉夹手或伸进缝隙的地方；不使用可吞入的小物给三岁以下孩子。","大人位置":"大人当着孩子的面藏，动作放慢让他看清楚。"},"shots":[{"name":"当面藏","say":"你看，我把小熊放在这里。"},{"name":"藏三样","say":"（依序藏三样在不同位置）"},{"name":"转个圈","say":"转三圈！"},{"name":"去找","say":"去找找看。"},{"name":"说出位置","say":"它在哪里找到的？（在椅子下面）"},{"name":"加难度","say":"下次藏五样，或等久一点再找。"}],"reactions":[{"if":"孩子只找得到最后一样","then":"减到两样。也可以在藏的时候一起说出位置，帮助编码。"},{"if":"孩子乱找","then":"提示区域：「在客厅里。」教他有系统地找，不要到处乱翻。"},{"if":"孩子想自己藏","then":"很好。藏的人也要记住位置，练习效果一样强。"}],"mistakes":["背着孩子藏，那就练不到记忆了。","一次藏太多样，孩子记不住。","藏在太隐密的地方，变成找东西不是记位置。"],"down":"只藏两样，藏完马上就找，不制造间隔。","up":"藏五样以上，或隔几分钟再找。","progress":["能找回几样。","能承受多长的间隔。","会不会说出东西的位置。"],"outro":"一定要当着他的面藏，不然练的就不是记忆了。数量和间隔不要同时加——一次只调一个。"}' AS JSON))
WHERE `id` = 'A246';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '说停就停，练冲动控制。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一人当鬼喊「一、二、三，木头人！」"},{"imageUrl":null,"instruction":"其他人趁机往前走，喊完立刻定住。"},{"imageUrl":null,"instruction":"动了的回起点。"},{"imageUrl":null,"instruction":"轮流当鬼。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '慢慢走、定两秒'),
  `harder` = COALESCE(`harder`, '跑着走、定五秒不晃。'),
  `tip` = COALESCE(`tip`, '这个游戏练的是「刹车」——先想一下再动的能力，对上课坐得住、排队等得了都有帮助。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组九（抑制控制）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"这个老游戏，其实是最好的冲动控制训练——因为要停住，比要前进难得多。","principles":["说停就停，练的是抑制控制，也就是踩煞车的能力。","抑制控制是执行功能的核心，影响专注、学习和情绪管理。","这个游戏把煞车这件事变成好玩的挑战。","孩子在兴奋、想前进的状态下要突然定住，难度刚好。","定住的时间可以调整：先两秒，再拉长到五秒。","定住时身体不能晃，那需要更精细的控制。","动了要回起点，这个后果很清楚但不严厉。","轮流当鬼很重要，当鬼的时候要观察别人，也在练注意力。","这个游戏一局很短，随时可以玩，而且全家都能参与。"],"prep":{"场地":"客厅或户外，有一段可以走动的距离，地面清空防滑。","器材":"不需要任何东西。","安全检查":"路线上清除桌角与障碍物；地面防滑，孩子穿防滑袜或赤脚；避免奔跑撞墙，设定终点线离墙一段距离。","大人位置":"大人第一轮当鬼示范，之后轮流。"},"shots":[{"name":"说明规则","say":"我喊完你们就要定住。"},{"name":"喊口令","say":"一、二、三，木头人！"},{"name":"定住","say":"（大家瞬间定格）"},{"name":"动了回起点","say":"你动了，回起点。"},{"name":"拉长定住时间","say":"这次要定住五秒。"},{"name":"轮流当鬼","say":"换你当鬼。"}],"reactions":[{"if":"孩子完全停不住","then":"缩短定住时间到一秒，并改成慢慢走不用跑。"},{"if":"孩子被抓到就生气","then":"把回起点讲成游戏的一部分，大人自己也被抓一次并笑着回去。"},{"if":"孩子不想当鬼","then":"不勉强。当鬼需要观察和等待，有些孩子要熟悉之后才愿意。"}],"mistakes":["定住时间太长，孩子撑不住就放弃。","被抓到时语气太严厉，游戏变成处罚。","只让孩子当木头人，不让他当鬼，少掉观察的练习。"],"down":"慢慢走、定住一到两秒，大人陪着一起当木头人。","up":"跑着前进、定住五秒且身体不晃，或加入单脚站的姿势。","progress":["能不能听到口令就停住。","能定住多久不晃。","愿不愿意当鬼观察别人。"],"outro":"停住比前进难——这个游戏练的就是煞车。定住的时间慢慢拉长，被抓到就笑着回起点。"}' AS JSON))
WHERE `id` = 'A247';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '听清楚规则再行动，练抑制冲动。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"说「老师说摸头」大家摸头。"},{"imageUrl":null,"instruction":"只说「摸鼻子」（没有「老师说」）就不能动。"},{"imageUrl":null,"instruction":"动了的笑一笑重来。"},{"imageUrl":null,"instruction":"轮流当老师。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '慢速、指令明显'),
  `harder` = COALESCE(`harder`, '快速连续，容易上当。'),
  `tip` = COALESCE(`tip`, '练的是「先想一下再动」——很多冲动的孩子玩几次就会明显进步。速度由慢到快，先让他成功几次。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组九（抑制控制）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「老师说摸头」——摸头。「摸鼻子」——不能动！这个游戏练的是：听清楚规则再行动。","principles":["这个游戏要求孩子先判断，再决定要不要动。","判断的依据是有没有「老师说」这三个字。","所以他必须听完整句话，不能听到动作就冲动照做。","这正是冲动控制加上选择性注意的组合。","上当是必然的，而且上当的那一刻最好笑。","所以气氛一定要轻松，上当了笑一笑重来就好。","速度可以调整：慢速容易，快速连续最容易上当。","轮流当老师，出题的人要想清楚自己的指令，也在练。","这个游戏和课堂上「听懂指令再动作」是同一种能力。"],"prep":{"场地":"客厅，大家站得开的位置。","器材":"不需要任何东西。","安全检查":"指令限于原地小动作（摸头、举手），不下达跑跳或危险动作的指令。","大人位置":"大人先当老师示范几轮，语速由慢到快。"},"shots":[{"name":"说明规则","say":"有说「老师说」才能动喔。"},{"name":"正确的指令","say":"老师说——摸头！"},{"name":"陷阱","say":"摸鼻子！"},{"name":"上当笑一笑","say":"（大家笑成一团）"},{"name":"加快速度","say":"（快速连续下指令）"},{"name":"换他当老师","say":"换你当老师。"}],"reactions":[{"if":"孩子一直上当很沮丧","then":"放慢速度，并在「老师说」三个字加重语气，先让他成功几次。"},{"if":"孩子当老师时忘了规则","then":"在旁边小声提示「要说老师说喔」，不接手替他讲。"},{"if":"孩子只想当老师不想玩","then":"可以。当老师也在练，而且要监督别人有没有上当，注意力要求更高。"}],"mistakes":["一开始就快速连续，孩子一直上当会失去兴趣。","上当时说「你怎么又没听清楚」，游戏变成检讨。","指令包含跑跳等大动作，容易受伤也失焦。"],"down":"语速很慢，并在「老师说」三个字加重语气与停顿。","up":"快速连续下指令，或加入相似的干扰句型（「老师想要你摸头」）。","progress":["能不能听完整句再动作。","上当的次数有没有减少。","当老师时能不能正确出题。"],"outro":"上当是必然的，而且上当最好笑。气氛轻松，笑一笑重来——这个游戏练的是听完整句再动作。"}' AS JSON))
WHERE `id` = 'A248';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '听到指令做相反的动作，是更难的自我控制。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"约定规则：我说「站起来」你就坐下，我说「举手」你就放下。"},{"imageUrl":null,"instruction":"一开始慢慢来。"},{"imageUrl":null,"instruction":"做对了加快速度。"},{"imageUrl":null,"instruction":"换他出题。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两组相反动作'),
  `harder` = COALESCE(`harder`, '四组以上，或快速切换。'),
  `tip` = COALESCE(`tip`, '要「压住第一个反应、做出另一个」——这是很高阶的能力，做错很正常，笑一笑再来。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组九（抑制控制）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"我说站起来，你要坐下。这个游戏比木头人更难——因为不只要停住，还要做出相反的动作。","principles":["反向动作需要同时抑制原本的反应，并启动另一个反应。","这比单纯的停止困难，是更高阶的执行功能训练。","孩子必须先压住自动反应，再从记忆中取出规则。","两个步骤都在脑中同时发生，所以很费力。","一开始只用两组相反动作，负荷才不会太大。","规则要在开始前说清楚，并复述一次确认他记住了。","速度先慢，做对了再加快，加快会让抑制更难。","换孩子出题，他要自己记住规则还要监督大人，难度更高。","这个能力和日后改正错误习惯、遵守新规则直接相关。"],"prep":{"场地":"客厅，孩子站得开、坐得下的位置。","器材":"不需要任何东西；可用椅子方便坐下站起。","安全检查":"动作限于站坐、举手放手等安全动作；椅子稳固不滑动，不用有轮子的椅子。","大人位置":"大人站在孩子对面下指令，自己不做动作避免视觉干扰。"},"shots":[{"name":"说明规则","say":"我说站起来，你要坐下。"},{"name":"确认他记住","say":"那我说举手，你要做什么？"},{"name":"慢速开始","say":"站——起——来。"},{"name":"做对了","say":"对！你坐下了。"},{"name":"加快速度","say":"（快速连续下指令）"},{"name":"换他出题","say":"换你出题考我。"}],"reactions":[{"if":"孩子一直做成正向","then":"放慢到极慢，并在下指令后停两秒让他想。抑制需要时间。"},{"if":"孩子混淆两组规则","then":"减到只有一组（站起来／坐下），练熟再加第二组。"},{"if":"孩子出题时自己也搞混","then":"很正常，笑一笑一起重新确认规则。"}],"mistakes":["一开始就用四组动作，负荷太大。","下完指令立刻要求反应，没有给思考的时间。","大人自己做动作，孩子会跟着模仿反而混乱。"],"down":"只用一组相反动作，并在下指令后停两秒再要求反应。","up":"四组以上的相反动作，并快速切换。","progress":["能不能做出相反的动作。","能同时记住几组规则。","速度加快后还做得对吗。"],"outro":"下完指令要停两秒，让他有时间想——抑制需要时间。做对了再加快，不要一开始就冲。"}' AS JSON))
WHERE `id` = 'A249';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '安静下来专注听，练听觉专注。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一起闭上眼睛安静一分钟。"},{"imageUrl":null,"instruction":"听听看能听到几种声音（车声、鸟叫、冷气、脚步）。"},{"imageUrl":null,"instruction":"张开眼睛说出来。"},{"imageUrl":null,"instruction":"比一比谁听到的多。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '听三十秒、说出两三种'),
  `harder` = COALESCE(`harder`, '听一分钟、说出五种以上。'),
  `tip` = COALESCE(`tip`, '这个游戏还能让躁动的孩子安静下来——睡前、生气后都很好用，兼具专注训练和情绪缓和。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组七（注意力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"闭上眼睛，安静一分钟——你会发现原来周围有这么多声音。这是最简单的专注力练习。","principles":["闭上眼睛之后，视觉的干扰消失，听觉会变得敏锐。","这时候要做的事只有一件：听。","单一任务、单一感官，是最容易进入专注状态的条件。","孩子会发现平常没注意到的声音，这个发现本身很有趣。","有趣，他才愿意重复，重复才有训练效果。","时间从三十秒开始，一分钟对幼儿已经不短了。","张开眼睛说出听到的声音，是把注意力的成果具体化。","比一比谁听到的多，会让孩子下次听得更仔细。","这个练习也有平静的效果，适合在情绪起伏后使用。"],"prep":{"场地":"任何地方都可以，室内室外各有不同的声音。","器材":"不需要任何东西。","安全检查":"户外进行时确保位置安全，大人在旁；不在马路边闭眼。","大人位置":"大人和孩子并排坐着，一起闭眼一起听。"},"shots":[{"name":"一起闭眼","say":"我们闭上眼睛，安静听三十秒。"},{"name":"环境音","say":"（画面静止，只有环境声）"},{"name":"张开眼睛","say":"你听到什么？"},{"name":"说出来","say":"车子声、鸟叫、冷气声。"},{"name":"比一比","say":"我听到四种，你呢？"},{"name":"换个地方再玩","say":"（户外版本）"}],"reactions":[{"if":"孩子闭不住眼睛","then":"改成低头看地板，或用手轻轻盖住眼睛。重点是减少视觉干扰。"},{"if":"孩子撑不到三十秒","then":"缩短到十秒。短而成功，比长而失败好。"},{"if":"孩子说不出听到什么","then":"由大人先说一个：「我听到冷气的声音。」示范之后他会跟上。"}],"mistakes":["时间设太长，孩子坐不住就失败。","在太安静的地方玩，没有声音可以听。","孩子说错就纠正，这个游戏没有标准答案。"],"down":"只听十秒，并由大人在结束后先说出一种声音示范。","up":"听一分钟以上，说出五种声音，并能说出声音来自哪个方向。","progress":["能安静听多久。","能说出几种声音。","能不能分辨声音的方向或远近。"],"outro":"闭上眼睛，只做一件事：听。时间从十秒开始就好——短而成功，比长而失败有用。"}' AS JSON))
WHERE `id` = 'A250';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '图画书或一张有很多东西的图'),
  `trains` = COALESCE(`trains`, '在一堆东西里找出指定的，练视觉专注和搜寻。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"翻开一张东西很多的图。"},{"imageUrl":null,"instruction":"说「找出所有的红色东西」或「找到三只小狗」。"},{"imageUrl":null,"instruction":"让他一个一个指出来。"},{"imageUrl":null,"instruction":"教他一区一区看，不要乱找。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '目标少而明显'),
  `harder` = COALESCE(`harder`, '目标多、藏在复杂背景里。'),
  `tip` = COALESCE(`tip`, '教「有方法地找」（从左到右、一排一排）——这个习惯将来在课本上找答案、在黑板上找位置都用得上。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"在一堆东西里找出指定的目标——重点不是找到，是教他「一区一区看」，不要乱找。","principles":["视觉搜寻是阅读的前置能力，找字、找行都靠它。","乱找的孩子会一直重复看同一区，效率很差。","有系统地一区一区看，是可以教的策略。","教法很简单：用手指着，从左上往右下扫。","这个扫视路径和日后阅读的方向一致，一举两得。","目标数量要明确：「找出三只小狗」，让他知道什么时候结束。","不明确的目标（找找看有什么）会让孩子失焦。","找到的一个一个指出来，避免重复计算。","背景越复杂难度越高，可以从简单的图慢慢换到复杂的。"],"prep":{"场地":"桌边，两人一起看得到图的位置。","器材":"一本图画很多的绘本，或一张寻宝图。","安全检查":"无特殊风险。注意光线充足，避免长时间近距离用眼。","大人位置":"大人坐在孩子旁边，手可以示范扫视的路径。"},"shots":[{"name":"翻开一张复杂的图","say":"这张图里有好多东西。"},{"name":"明确的目标","say":"找出三只小狗。"},{"name":"教扫视路径","say":"从这边开始，一区一区看。"},{"name":"一个一个指","say":"一只、两只……"},{"name":"找到了","say":"三只都找到了！"},{"name":"加难度","say":"这次找红色的东西，有几个？"}],"reactions":[{"if":"孩子乱找找不到","then":"用手遮住其他区域，一次只露一小块。缩小范围就找得到了。"},{"if":"孩子重复数同一个","then":"教他找到一个就用手指压着，或用便利贴标记。"},{"if":"孩子很快就找完想换","then":"加难度：增加目标数量，或改找两种条件（红色而且圆的）。"}],"mistakes":["目标不明确（找找看有什么），孩子不知道要找什么。","没有教扫视方法，孩子一直乱找很挫折。","图太复杂，超过他能处理的讯息量。"],"down":"用手遮住其他区域，一次只露一小块；目标只有一个。","up":"目标多、藏在复杂背景里，或需要两个条件同时符合。","progress":["能不能找出指定的目标。","有没有使用一区一区看的方法。","会不会重复计算或遗漏。"],"outro":"教他一区一区看，从左上往右下——这个扫视方向，和以后阅读的方向是一样的。"}' AS JSON))
WHERE `id` = 'A251';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一堆小东西'),
  `trains` = COALESCE(`trains`, '专心数完不重复不遗漏，练持续专注。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给一堆小东西（十到二十个）。"},{"imageUrl":null,"instruction":"让孩子数出总数。"},{"imageUrl":null,"instruction":"教他数过的放到一边，避免重复。"},{"imageUrl":null,"instruction":"数完再检查一次。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '十个以内'),
  `harder` = COALESCE(`harder`, '二十个以上，或数完要说出总数。'),
  `tip` = COALESCE(`tip`, '「数过的移开」是很重要的策略——不然孩子会重复数。教方法比要求他专心有效。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组七（注意力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"给他一堆二十个小东西，数出总数——这个任务最难的不是数数，是不重复、不遗漏地数完。","principles":["数一堆散乱的东西，需要持续专注到最后一个。","中途分心就会重复或遗漏，结果就错了。","所以这个活动练的是持续性注意力，不只是数概念。","最好用的策略是：数过的放到一边。","把已数和未数在空间上分开，就不会搞混。","这是一个可以教、可以迁移的策略，日后检查作业也用得到。","数量从十个以内开始，成功了再加。","数完要再检查一次，养成核对的习惯。","检查这件事很重要，很多孩子不会回头确认。"],"prep":{"场地":"桌面，有空间把东西分成两堆。","器材":"十到二十个小东西（积木、钮扣、豆子）。","安全检查":"三岁以下不使用可吞入的小物，改用大颗积木；全程大人在旁。","大人位置":"大人坐在旁边，示范「数过的放这边」的动作。"},"shots":[{"name":"一堆小东西","say":"数数看这里有几个。"},{"name":"直接数会乱","say":"（孩子数着数着重复了）"},{"name":"教策略","say":"数过的放到这边来。"},{"name":"一个一个移","say":"一、二、三……"},{"name":"说出总数","say":"一共十五个。"},{"name":"再检查一次","say":"我们再数一次确认。"}],"reactions":[{"if":"孩子数到一半分心","then":"减少数量，或分成两批数再相加。任务长度要配合他的续航力。"},{"if":"孩子不肯用分堆的方法","then":"先让他用自己的方法数一次，错了再示范策略，对比最有说服力。"},{"if":"孩子数完不想检查","then":"把检查变成游戏：「我们比比看两次结果一不一样。」"}],"mistakes":["数量太多，超过他的专注时间。","孩子数错就直接说答案，少了发现错误的机会。","不教策略，只要求他更专心。"],"down":"十个以内，并由大人帮忙把东西排成一列再数。","up":"二十个以上，或数完要说出总数并在不重排的情况下检查。","progress":["能不能数完不重复不遗漏。","会不会使用分堆的策略。","数完会不会主动检查。"],"outro":"教他一个可以带走的方法：数过的放到一边。数完再检查一次——这个习惯，以后写作业都用得上。"}' AS JSON))
WHERE `id` = 'A252';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '积木或彩色小物'),
  `trains` = COALESCE(`trains`, '照着范例做出一样的，练观察和专注。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人排一个简单的样式（红蓝红蓝）。"},{"imageUrl":null,"instruction":"让孩子照着排一样的。"},{"imageUrl":null,"instruction":"样式慢慢变复杂。"},{"imageUrl":null,"instruction":"做完一起核对。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三四块、简单交替'),
  `harder` = COALESCE(`harder`, '多块、有上下排列。'),
  `tip` = COALESCE(`tip`, '「照着做出一样的」将来在抄黑板、照说明书组装时都要用——是很实用的能力。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"红蓝红蓝——照着排一样的。这个游戏练的是观察和对照，而且是日后抄写的基础。","principles":["照着范例做出一样的，需要反复在范例和自己的作品之间来回看。","这个来回对照的动作，正是抄写黑板、抄联络簿时在做的事。","孩子必须记住刚才看到的顺序，再转到自己这边做出来。","中间有一个短暂的记忆保存，所以也练到工作记忆。","样式从最简单的两色交替开始，规律越明显越好抓。","规律太复杂，孩子看不出规则就只能一个一个照抄，负荷大。","做完一起核对，一个一个比，找出不一样的地方。","核对的过程比做出来更有价值，那是在练检查。","进阶可以加上下两排，空间关系变复杂，难度明显提高。"],"prep":{"场地":"桌面，两人的作品可以并排比较。","器材":"积木或彩色小物，每种颜色数量要够两份。","安全检查":"使用大颗物件避免吞入；桌面稳固不晃动。","大人位置":"大人先排出范例，放在孩子看得到但不会碰到的位置。"},"shots":[{"name":"排出范例","say":"我排一个，你排一个一样的。"},{"name":"孩子照着排","say":"（孩子一边看一边排）"},{"name":"来回对照","say":"（特写眼神来回）"},{"name":"一起核对","say":"我们一个一个比。"},{"name":"找出不一样","say":"这里不太一样喔。"},{"name":"加难度","say":"这次有上下两排。"}],"reactions":[{"if":"孩子排错顺序","then":"不直接指出来。说「我们一起比比看」，让他自己发现。"},{"if":"孩子看一眼就凭印象排","then":"把范例盖住一半，逼他多看几次。多看几次才是练习。"},{"if":"孩子觉得太简单","then":"加长样式、加颜色种类，或改成上下两排的二维排列。"}],"mistakes":["范例太复杂，孩子看不出规律。","孩子排错就直接改好，少了核对的练习。","范例放太远，来回看太费力。"],"down":"只用三四块、两色交替，并把范例放在正前方。","up":"多块、多色，或有上下两排的二维排列。","progress":["能不能排出一样的。","会不会来回对照范例。","核对时能不能自己找出不一样的地方。"],"outro":"做完一定要一起核对，一个一个比。核对的过程，比做出来更有价值——那是在练检查。"}' AS JSON))
WHERE `id` = 'A253';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '拼图'),
  `trains` = COALESCE(`trains`, '完成一件需要坐得住的事，练持续专注。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选块数适中的拼图（太难会放弃）。"},{"imageUrl":null,"instruction":"教他先找边角、再拼中间。"},{"imageUrl":null,"instruction":"卡住给一点提示，别直接帮他拼。"},{"imageUrl":null,"instruction":"完成了一起欣赏。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '六到十块'),
  `harder` = COALESCE(`harder`, '三十块以上。'),
  `tip` = COALESCE(`tip`, '块数要选「他努力一下就能完成」的——太难会放弃，太简单没成就感。拼完的成就感是专注力最好的奖励。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"拼图是最经典的静态专注活动。但选错块数，它会变成挫折来源——今天先讲怎么选。","principles":["拼图需要持续坐着、反复尝试，是很好的专注力训练。","但块数选错，孩子会在挫折中放弃，反而讨厌拼图。","判断标准很简单：他能在十五分钟内完成的块数。","完成的经验比挑战的难度重要，尤其是刚开始的时候。","教他策略：先找边角，边角只有两个直边，最好认。","有边框之后，中间的范围就缩小了。","这是一个可以迁移的策略：先做确定的，再做不确定的。","卡住的时候给提示，不要直接帮他拼。","提示可以是「找找看有没有蓝色的」，把范围缩小就好。"],"prep":{"场地":"桌面或地板，有空间摊开所有拼图块。","器材":"块数适中的拼图；六到三十块视年龄而定。","安全检查":"拼图块不可过小（三岁以下用大块拼图）；注意纸质拼图的边缘。","大人位置":"大人坐在旁边，手不要伸进去，只用嘴巴提示。"},"shots":[{"name":"选对块数","say":"块数要选他十五分钟能拼完的。"},{"name":"全部摊开","say":"先全部翻过来，图案朝上。"},{"name":"先找边角","say":"先找边边和角角。"},{"name":"围出边框","say":"（边框拼好了）"},{"name":"卡住给提示","say":"找找看有没有蓝色的。"},{"name":"完成欣赏","say":"完成了！我们一起看。"}],"reactions":[{"if":"孩子拼不下去要放弃","then":"换更少块数的拼图。完成一次的经验，比挑战失败十次有价值。"},{"if":"孩子要大人帮忙拼","then":"只给语言提示：「这块的颜色和哪一块像？」手不要伸进去。"},{"if":"孩子拼很快想要更难的","then":"加块数，或选图案重复性高的（天空、草地）增加难度。"}],"mistakes":["块数选太多，孩子在挫折中放弃。","大人忍不住直接帮他拼好，成就感就没了。","要求一次拼完，孩子累了也不让停。"],"down":"六到十块的大块拼图，并由大人先把边框拼好。","up":"三十块以上，或图案重复性高、辨识度低的拼图。","progress":["能专注多久不离开。","会不会使用先找边角的策略。","能完成多少块数的拼图。"],"outro":"块数选他十五分钟拼得完的就好。卡住的时候给提示，不要直接帮他拼——手不要伸进去。"}' AS JSON))
WHERE `id` = 'A254';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '计时器或沙漏'),
  `trains` = COALESCE(`trains`, '在固定时间内专心做一件事，练时间概念和坚持。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"定一个短时间（五分钟）。"},{"imageUrl":null,"instruction":"这段时间只做一件事，不做别的。"},{"imageUrl":null,"instruction":"计时器响了就休息。"},{"imageUrl":null,"instruction":"时间慢慢拉长。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '专心三五分钟'),
  `harder` = COALESCE(`harder`, '专心十五分钟以上。'),
  `tip` = COALESCE(`tip`, '「做五分钟休息一下」比「一直做到完」有效——看得见的时间让孩子有安全感，知道快结束了就撑得住。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组七（注意力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"专心不是无限延长的，是一段一段的。用计时器切出五分钟——响了就休息，这一点一定要做到。","principles":["专注力是有限的资源，会消耗也需要恢复。","所以与其要求孩子「专心一点」，不如把时间切成小段。","五分钟对多数学龄前孩子是可行的起点。","计时器让时间变成看得见、听得到的东西。","有明确的终点，孩子比较撑得住，因为他知道快结束了。","这段时间内只做一件事，其他事情都先放着。","响了就休息，这一点大人一定要守信。","如果响了还要求继续，下次孩子就不相信计时器了。","时间慢慢拉长，但要在他成功几次之后才加。"],"prep":{"场地":"书桌或餐桌，环境干扰少。","器材":"计时器或沙漏；视觉型的计时器（看得到剩余时间）最好。","安全检查":"无特殊风险。避免连续长时间用眼，每段之间要真的休息。","大人位置":"大人设定计时器，并在响的时候确实喊停。"},"shots":[{"name":"设定时间","say":"我们专心五分钟。"},{"name":"只做一件事","say":"这五分钟只做这一件事。"},{"name":"专心中","say":"（孩子专心做事）"},{"name":"时间到","say":"（计时器响）"},{"name":"响了就休息","say":"时间到，休息！"},{"name":"慢慢拉长","say":"下次我们试七分钟。"}],"reactions":[{"if":"孩子五分钟都撑不住","then":"缩短到三分钟。起点要设在他做得到的地方。"},{"if":"孩子想在时间内做别的事","then":"温和提醒「这五分钟只做这一件」，其他的写下来等一下再做。"},{"if":"时间到孩子还想继续","then":"很好，但还是先休息一下再继续。守信比多做几分钟重要。"}],"mistakes":["时间设太长，孩子一直失败。","响了还要求继续，计时器就失去公信力。","休息时间给手机或电视，反而更累。"],"down":"从三分钟开始，并由大人陪在旁边一起做事。","up":"十五分钟以上，并能自己设定计时器开始。","progress":["能专心多久。","这段时间内会不会跑去做别的。","会不会自己主动使用计时器。"],"outro":"响了就休息，这一点一定要做到。守信比多做那几分钟重要——不然下次计时器就没用了。"}' AS JSON))
WHERE `id` = 'A255';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '书桌'),
  `trains` = COALESCE(`trains`, '减少干扰，帮专注力一把。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"做事之前先把桌面清空。"},{"imageUrl":null,"instruction":"只留下现在要用的东西。"},{"imageUrl":null,"instruction":"玩具、零食都收起来。"},{"imageUrl":null,"instruction":"做完再收拾。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人帮忙清'),
  `harder` = COALESCE(`harder`, '自己养成先整理的习惯。'),
  `tip` = COALESCE(`tip`, '很多孩子不是不专心，是环境太吸引人——桌上少一样玩具，专注就多一分。这招立竿见影。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十五（作息时间安排与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"专注力最便宜的帮手，是一张干净的桌子。开始做事之前，先花一分钟清空它。","principles":["桌上每一样多余的东西，都在分掉一点注意力。","对容易分心的孩子来说，这个影响特别明显。","清空桌面是最省力、最立即有效的环境调整。","只留下现在要用的东西，其他全部收起来。","玩具和零食尤其要收，那是最强的干扰源。","清桌子本身也是一个仪式，代表「我要开始了」。","仪式会帮助孩子切换状态，从玩转到做事。","一开始大人帮忙清，慢慢变成他自己的习惯。","做完再收拾，让桌面回到干净的状态，下次开始更容易。"],"prep":{"场地":"书桌或孩子固定做事的桌面。","器材":"一个收纳盒或篮子，用来暂放被收起来的东西。","安全检查":"收纳盒不放在头顶上方的层架；不让孩子搬动过重的物品。","大人位置":"大人和孩子一起清，第一次示范什么该留什么该收。"},"shots":[{"name":"乱的桌面","say":"（桌上堆满玩具、零食、纸张）"},{"name":"只留要用的","say":"现在要画画，所以只留纸和笔。"},{"name":"其他收起来","say":"其他的先放进这个篮子。"},{"name":"干净的桌面","say":"（桌面清空）"},{"name":"当成开始的仪式","say":"桌子干净了，我们开始。"},{"name":"做完再收","say":"做完把桌子收回去。"}],"reactions":[{"if":"孩子不想收","then":"大人一起收，并把它变成三十秒的竞赛：「我们比谁收得快。」"},{"if":"孩子收了又拿出来","then":"温和地放回篮子，说「等一下再玩」。不多解释，动作明确就好。"},{"if":"孩子说这样很无聊","then":"可以留一样他喜欢但不干扰的东西（一个小摆饰），保留一点自主。"}],"mistakes":["大人全部收好，孩子没有参与，就养不成习惯。","桌面留着手机或平板，那是最强的干扰源。","只在孩子分心时才要求收桌子，变成处罚。"],"down":"大人帮忙清，孩子只负责把一两样东西放进篮子。","up":"自己在开始前主动清空桌面，并在结束后收拾干净。","progress":["愿不愿意一起清桌面。","清完之后专注时间有没有变长。","有没有开始自己主动清。"],"outro":"开始之前先花一分钟清空桌子。这不只是整理，它是一个仪式——告诉他，我要开始了。"}' AS JSON))
WHERE `id` = 'A256';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '用身体活动帮助恢复专注。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"专心一段时间后，起来动一动。"},{"imageUrl":null,"instruction":"跳十下、推推墙、伸个懒腰。"},{"imageUrl":null,"instruction":"一两分钟就好。"},{"imageUrl":null,"instruction":"再回来继续。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每十分钟动一下'),
  `harder` = COALESCE(`harder`, '能自己察觉「我需要动一动了」。'),
  `tip` = COALESCE(`tip`, '孩子坐不住时别急着骂——让他动一动再回来，效率反而更高。**动完再学，比逼着坐着有效**。'),
  `deeper` = COALESCE(`deeper`, '物理治疗册 模组十二（肌力与耐力训练）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"孩子坐不住不一定是不专心，可能是身体需要动一动了。动一两分钟再回来，通常比硬撑有效。","principles":["专注力会随着时间下降，这是生理现象，不是态度问题。","身体活动可以提高警醒度，帮助注意力恢复。","短暂的动态活动之后，接下来的专注品质通常会更好。","所以中间休息不是浪费时间，是投资。","活动要短：一两分钟就够，太长会难以收回来。","推墙、跳跃这类需要出力的活动效果最好。","因为深层的本体感觉输入有助于组织神经系统。","固定在每隔一段时间就动一下，比等到崩溃才动好。","最终目标是孩子能自己察觉「我需要动一动了」。"],"prep":{"场地":"桌边旁有一小块空间可以站起来活动。","器材":"不需要任何东西；一面结实的墙。","安全检查":"推墙用手掌不用拳头，不推玻璃门或隔间板；跳跃时地面防滑、周围净空。","大人位置":"大人和孩子一起做，动作示范清楚。"},"shots":[{"name":"开始坐不住","say":"（孩子开始扭动、东张西望）"},{"name":"起来动一动","say":"我们起来动一下。"},{"name":"跳十下","say":"跳十下！"},{"name":"推推墙","say":"用手掌推墙，推十秒。"},{"name":"伸个懒腰","say":"伸——个——懒腰。"},{"name":"回来继续","say":"好，我们回来。"}],"reactions":[{"if":"孩子动完收不回来","then":"缩短活动时间，并选静态出力的动作（推墙）取代跳跃。"},{"if":"孩子不想动","then":"不勉强。可以改成坐着推桌子、握拳放松这类小动作。"},{"if":"孩子每隔两分钟就要动","then":"那可能是任务太难或太久。检查任务本身，不是一直加休息。"}],"mistakes":["休息时间太长，孩子玩开了收不回来。","用手机或电视当休息，反而更难回到任务。","等到孩子完全失控才让他动。"],"down":"只做静态出力的动作（推墙、握拳放松），时间三十秒。","up":"能自己察觉需要活动并主动提出，动完自己回到任务。","progress":["动完之后专注有没有恢复。","能不能在一两分钟内收回来。","有没有开始自己察觉需要动一动。"],"outro":"坐不住不一定是不专心，可能是身体需要动。一两分钟就够——推墙这类出力的动作，效果最好。"}' AS JSON))
WHERE `id` = 'A257';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会一次专心做一件事，做完再做下一件。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"交代事情时一次只说一件。"},{"imageUrl":null,"instruction":"「先把积木收好」——做完了再说下一件。"},{"imageUrl":null,"instruction":"做完打个勾。"},{"imageUrl":null,"instruction":"慢慢增加到两件。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '一次一件'),
  `harder` = COALESCE(`harder`, '一次两三件还能记得。'),
  `tip` = COALESCE(`tip`, '一口气交代三件事，孩子通常只记得最后一件——一次一件，做完再说下一件，双方都轻松。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十四（执行功能）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「去把积木收好、然后洗手、然后来吃饭」——孩子站在原地不动。不是他不听，是一次太多了。","principles":["一次交代太多件事，超过孩子的工作记忆容量。","记不住的结果不是做一半，而是整个卡住不动。","大人常常会误以为他在故意拖延，其实他是当机了。","一次只说一件，孩子就有办法执行。","做完了再说下一件，这样每一件都完成得了。","做完打个勾，让完成变成看得见的事。","看得见的完成会累积成就感，也让下一件更容易开始。","慢慢增加到两件，等两件稳了再试三件。","这个容量会随年龄增加，不用急着推进。"],"prep":{"场地":"日常生活中需要交代事情的场景。","器材":"不需要任何东西；纸笔用来打勾。","安全检查":"无特殊风险。交代的事项不涉及热源、刀具或高处。","大人位置":"大人走到孩子面前说，确认他有听到再说内容。"},"shots":[{"name":"一次说太多","say":"去收积木、洗手、然后来吃饭。"},{"name":"其实是当机了","say":"（字幕：不是不听，是记不住）"},{"name":"一次只说一件","say":"先把积木收好。"},{"name":"他做到了","say":"（孩子去收积木）"},{"name":"打个勾","say":"收好了，打勾！"},{"name":"再说下一件","say":"接下来去洗手。"}],"reactions":[{"if":"孩子一件也没做","then":"确认他有听到：走到面前、眼神接触再说一次。距离太远他可能没接收到。"},{"if":"孩子做到一半忘了","then":"温和提醒那一件事，不加新的。提醒不是责备。"},{"if":"孩子两件事做得到了","then":"可以试三件，但要让他复述一次确认记住了。"}],"mistakes":["隔着房间大声交代，孩子根本没接收到。","一次说三四件，孩子直接当机。","孩子没动就说他不听话，误解了原因。"],"down":"一次一件，并且大人陪着他一起去做。","up":"一次交代两三件，让他复述后自己完成。","progress":["一次能记住并完成几件事。","需不需要中途提醒。","会不会自己复述确认。"],"outro":"孩子站着不动，常常不是不听，是记不住。一次说一件，做完再说下一件——这样每一件都完成得了。"}' AS JSON))
WHERE `id` = 'A258';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '记住并完成几件要做的事，练工作记忆。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"交代三件小事：「把杯子放厨房、拿一条毛巾、关灯」。"},{"imageUrl":null,"instruction":"让他复述一遍再去做。"},{"imageUrl":null,"instruction":"做完检查有没有漏。"},{"imageUrl":null,"instruction":"慢慢增加件数。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两件事'),
  `harder` = COALESCE(`harder`, '四件以上，或要走到别的房间。'),
  `tip` = COALESCE(`tip`, '「复述一遍再去做」是关键——说出来的过程会帮他记住。这个方法在学校听老师交代事情时也很好用。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组八（记忆力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"「把杯子放厨房、拿一条毛巾、关灯」——这个任务练的是工作记忆，也就是边记边做的能力。","principles":["工作记忆是边记住内容、边执行动作的能力。","它和单纯的记忆不同，因为中间还要做事，很容易被干扰。","这是学校里最常被用到的能力之一：听完指令去完成。","关键技巧是让他先复述一遍再去做。","复述会把讯息从听觉转成自己的语言，记得更牢。","没有复述就直接去做，走到一半常常就忘了。","做完检查有没有漏，漏了不责备，只是一起补上。","件数从两件开始，稳了再加。","进阶是要走到别的房间，因为移动本身就是干扰。"],"prep":{"场地":"家里，任务分散在不同位置更有挑战性。","器材":"不需要任何东西；用日常的小任务即可。","安全检查":"任务不涉及热水、瓦斯、刀具或高处；关灯的开关高度要孩子构得到。","大人位置":"大人蹲下与孩子同高，说完要求他复述。"},"shots":[{"name":"交代三件事","say":"把杯子放厨房、拿一条毛巾、关灯。"},{"name":"请他复述","say":"你说一次给我听。"},{"name":"孩子复述","say":"（孩子重复三件事）"},{"name":"去执行","say":"（跟拍孩子完成三件事）"},{"name":"回来检查","say":"三件都做了吗？"},{"name":"漏了不责备","say":"还有灯喔，我们一起去关。"}],"reactions":[{"if":"孩子只做了第一件","then":"减到两件。也可以在他出发前再复述一次，加强记忆。"},{"if":"孩子复述不出来","then":"那就是件数太多了。减少到他复述得出来的数量。"},{"if":"孩子做完忘了回来报告","then":"不苛求。重点是三件事有没有完成，报告可以之后再练。"}],"mistakes":["不让孩子复述就直接派他去做。","件数太多，孩子走到一半全忘了。","漏了就责备，孩子下次会更紧张更记不住。"],"down":"只交代两件事，并让他复述两次再出发。","up":"四件以上，或需要走到不同房间完成。","progress":["能记住并完成几件事。","复述得出来吗。","需不需要中途提醒。"],"outro":"让他先复述一遍再去做——这一步不能省。漏了一起去补，不要责备，紧张只会让他更记不住。"}' AS JSON))
WHERE `id` = 'A259';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '卡片、小东西'),
  `trains` = COALESCE(`trains`, '把这个模组的能力串起来玩一轮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：翻牌配对找出四对。"},{"imageUrl":null,"instruction":"第二关：记住三样东西并复述。"},{"imageUrl":null,"instruction":"第三关：玩一次「老师说」不上当。"},{"imageUrl":null,"instruction":"第四关：专心拼完一个拼图。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关降低标准'),
  `harder` = COALESCE(`harder`, '加上计时或提高数量。'),
  `tip` = COALESCE(`tip`, '专心不是逼出来的，是被有趣的事吸引出来的。孩子在他喜欢的事情上能专心多久，那才是他真正的专注力。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组七～九（注意力 · 记忆力 · 抑制控制）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"这是模组十三的总复习，四关。走完你会知道——他是记不住，还是停不下来。","principles":["这个模组练的其实是两组能力：记忆和抑制。","记忆包括视觉记忆、听觉记忆和工作记忆。","抑制包括停住冲动、忽略干扰、持续专注。","四关刚好把这两组能力都测过一遍。","第一关翻牌配对，测视觉记忆。","第二关复述三样，测听觉记忆。","第三关玩老师说，测抑制控制。","第四关拼完一个拼图，测持续专注。","哪一关最吃力，就知道接下来要回去补哪几个活动。"],"prep":{"场地":"桌边，一个不受打扰的半小时。","器材":"成对卡片、几样小东西、一个拼图。","安全检查":"无特殊风险。孩子累了就分两天做完；不把结果当成评价。","大人位置":"大人当主持人，每关先说明规则，必要时给提示。"},"shots":[{"name":"宣布四关","say":"今天四关，一关一关来。"},{"name":"第一关翻牌","say":"找出四对。"},{"name":"第二关复述","say":"苹果、汽车、小狗——你说一次。"},{"name":"第三关老师说","say":"老师说摸头！"},{"name":"第四关拼图","say":"把这个拼完。"},{"name":"收尾","say":"四关都完成了！"}],"reactions":[{"if":"某一关明显吃力","then":"降低标准让他过关，记下来，之后回去单独练那几个活动。"},{"if":"孩子没耐心走完","then":"分两天做完。完成比连续重要。"},{"if":"孩子表现比平常差","then":"检查是不是累了或饿了。记忆和专注很容易受生理状态影响。"}],"mistakes":["把它当成测验，孩子有压力表现就失真。","四关硬要一次走完，最后草草结束。","在孩子疲倦时进行，结果没有参考价值。"],"down":"每关都降低数量与标准，只要求参与。","up":"加上计时或提高数量，四关全部独立完成。","progress":["四关各自的表现。","是记忆类的关卡吃力，还是抑制类的关卡吃力。","和一个月前比有没有进步。"],"outro":"四关分成两组：前两关测记忆，后两关测停得下来。哪一组吃力，接下来就补哪一组。"}' AS JSON))
WHERE `id` = 'A260';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '1–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '家里的东西（袜子、积木、餐具）'),
  `trains` = COALESCE(`trains`, '把相同的东西配成对或归成一堆，是分类的起点。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把成对的东西打乱。"},{"imageUrl":null,"instruction":"让孩子把一样的放一起。"},{"imageUrl":null,"instruction":"收衣服时配袜子最好玩。"},{"imageUrl":null,"instruction":"配对时说出名称。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三对、差异大'),
  `harder` = COALESCE(`harder`, '多对、或颜色形状相近。'),
  `tip` = COALESCE(`tip`, '收衣服时让孩子配袜子——家务和学习一起完成，他还觉得自己在帮忙。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"把一样的放一起——这是分类的起点，也是所有数学概念的第一块砖。而且配袜子就能练。","principles":["把相同的东西配成对，是最早出现的分类行为。","孩子必须先看出「这两个一样」，才谈得上后面的分类和数量。","一样这个概念看似简单，其实需要比较多个属性才判断得出来。","配袜子最好玩，因为袜子成双、花色明显、而且是真实的家务。","真实的任务会让孩子觉得自己在帮忙，动机比玩教具高。","配对时把名称说出来，同时练到词汇和概念。","从差异大的开始：红袜子和蓝袜子，一眼就分得出来。","熟了再用颜色相近的，难度自然提高。","这个能力练稳了，后面的分类、排序、比较才做得起来。"],"prep":{"场地":"地板或床上，衣服摊得开的地方。","器材":"成对的袜子、成对的积木或餐具。","安全检查":"避免使用有细绳或小配件的衣物给三岁以下孩子；小件物品不放入口。","大人位置":"大人和孩子一起坐在衣服堆旁，一件一件拿。"},"shots":[{"name":"打乱的袜子","say":"袜子都混在一起了。"},{"name":"找一样的","say":"找找看哪两只是一样的。"},{"name":"配成一对","say":"一样！配成一对。"},{"name":"说出名称","say":"这是红色的袜子。"},{"name":"全部配完","say":"（一排配好的袜子）"},{"name":"换积木也可以","say":"（换成积木或餐具配对）"}],"reactions":[{"if":"孩子配错","then":"不说错。把两只并排放：「我们比比看，一样吗？」让他自己发现。"},{"if":"孩子只想乱丢袜子","then":"先让他玩一下。玩够了再开始，家务本身不必一开始就很严肃。"},{"if":"孩子很快配完","then":"加入花色相近的袜子，或加上「配完要说出颜色」的要求。"}],"mistakes":["一次倒出太多，孩子看了就放弃。","孩子配错就直接换掉，少了比较的机会。","只用教具不用真实物品，动机会低很多。"],"down":"只放三双、颜色差异极大的袜子，并由大人先配一双示范。","up":"花色相近的多双袜子，或改配有细微差异的物品。","progress":["能不能把一样的配在一起。","能处理的数量和相似度。","配对时会不会说出名称或颜色。"],"outro":"配袜子就是最好的教具——真实、成双、而且他会觉得自己在帮忙。从差异大的开始，慢慢用花色相近的。"}' AS JSON))
WHERE `id` = 'A261';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '混在一起的物品'),
  `trains` = COALESCE(`trains`, '按一个标准把东西分类。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把东西分成两类：吃的／玩的、大的／小的、红的／蓝的。"},{"imageUrl":null,"instruction":"一次只用一个标准。"},{"imageUrl":null,"instruction":"分好了说出为什么这样分。"},{"imageUrl":null,"instruction":"收玩具时顺便分类。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两类、差异大'),
  `harder` = COALESCE(`harder`, '三四类，或换个标准再分一次。'),
  `tip` = COALESCE(`tip`, '同一堆东西可以有不同的分法（按颜色、按大小、按用途）——「换个方式再分一次」是很好的思考练习。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一次只用一个标准分类——这是最重要的一条。吃的／玩的，或大的／小的，但不要同时来。","principles":["分类需要先决定一个标准，再依标准把东西分开。","孩子最常卡住的地方，是标准换来换去。","一下按颜色、一下按大小，结果就乱了。","所以一次只用一个标准，是这个活动最重要的原则。","两类比多类容易，因为选项只有两个。","标准差异要大：吃的／玩的，比水果／蔬菜容易得多。","分好之后要问「为什么这样分」，让标准被说出来。","说得出标准，代表他是有意识地分类，不是随手放。","收玩具的时候顺便分类，让这个能力有实际用途。"],"prep":{"场地":"地板或大桌面，有空间分成两堆。","器材":"混在一起的日常物品（玩具、水果、餐具）。","安全检查":"避免玻璃或易碎品；三岁以下不使用可吞入的小物。","大人位置":"大人坐在旁边，先说清楚这次的标准是什么。"},"shots":[{"name":"一堆混在一起","say":"我们来分一分。"},{"name":"说清楚标准","say":"这次只分：可以吃的、不能吃的。"},{"name":"开始分","say":"（孩子一样一样放到两堆）"},{"name":"分好了","say":"（两堆清楚分开）"},{"name":"说出理由","say":"为什么这样分？"},{"name":"换个标准再分","say":"这次换成大的、小的。"}],"reactions":[{"if":"孩子分到一半换标准","then":"温和地提醒这次的标准：「我们这次只看能不能吃。」"},{"if":"孩子分得跟你想的不一样","then":"先问他为什么。说得出理由就是有效的分类，不必只有一个答案。"},{"if":"孩子觉得太简单","then":"换标准再分一次同一堆东西，或增加到三四类。"}],"mistakes":["同时用两个标准，孩子会混乱。","一开始就分四五类，超过他的负荷。","只分不问理由，标准就没有被意识到。"],"down":"只分两类且差异极大（吃的／玩的），并各先放一样当范例。","up":"分三四类，或同一堆东西换不同标准分两次。","progress":["能不能按一个标准分完。","会不会中途换标准。","说不说得出自己的分类理由。"],"outro":"一次只用一个标准，这条最重要。分好了记得问一句「为什么这样分」——说得出标准，才算真的会分类。"}' AS JSON))
WHERE `id` = 'A262';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几样东西或图卡'),
  `trains` = COALESCE(`trains`, '找出不属于这一类的，练分类和推理。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"摆出三样同类的、一样不同类的（苹果、香蕉、橘子、汽车）。"},{"imageUrl":null,"instruction":"问「哪个不一样？」"},{"imageUrl":null,"instruction":"让他说出为什么。"},{"imageUrl":null,"instruction":"慢慢让差异变小。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '差异明显'),
  `harder` = COALESCE(`harder`, '都是同类但有一个属性不同。'),
  `tip` = COALESCE(`tip`, '重点是「说出为什么」——答对了也要问一句，孩子的思考才会被看见和练到。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"苹果、香蕉、橘子、汽车——哪个不一样？重点不是选出来，是他说不说得出为什么。","principles":["找出不同类的东西，需要先看出其他几样的共同点。","所以这个游戏其实是反过来在练分类。","孩子必须在心里形成一个类别，才知道谁不属于它。","选对了只是第一步，说出理由才代表他真的理解。","很多孩子选得对但说不出来，那还在直觉阶段。","所以每一次都要追问「为什么」，把理由说出口。","一开始差异要非常明显：三样水果加一台车。","熟了之后让差异变小：都是水果，但有一个不是圆的。","这是日后逻辑推理和阅读理解的基本功。"],"prep":{"场地":"桌面，四样东西排开的空间。","器材":"几样实物或图卡，三样同类加一样不同类。","安全检查":"三岁以下不使用可吞入的小物；图卡圆角或护贝。","大人位置":"大人排好四样，放在孩子正前方。"},"shots":[{"name":"排出四样","say":"苹果、香蕉、橘子、汽车。"},{"name":"问哪个不一样","say":"哪一个跟别人不一样？"},{"name":"他选出来","say":"（孩子指向汽车）"},{"name":"追问为什么","say":"为什么？"},{"name":"说出理由","say":"因为其他三个都可以吃。"},{"name":"差异变小","say":"这次四个都是水果喔。"}],"reactions":[{"if":"孩子选错","then":"不说错。问「那这三个有什么一样的地方？」引导他找共同点。"},{"if":"孩子选对说不出理由","then":"由你先说一次：「因为这三个都可以吃。」示范理由的说法。"},{"if":"孩子的理由和你想的不同","then":"只要说得通就接受。分类可以有多种角度，这本身就是思考。"}],"mistakes":["只问哪个不一样，不问为什么。","差异一开始就太细，孩子看不出来。","孩子理由不同就说他错，压掉了思考。"],"down":"差异极明显（三样食物加一样家具），并由大人示范一次完整的理由。","up":"四样都同类，只有一个属性不同（颜色、形状、用途）。","progress":["能不能选出不同类的。","说不说得出理由。","能处理多细微的差异。"],"outro":"选对只是第一步，一定要追问一句「为什么」。他说得出其他三个的共同点，才是真的懂了。"}' AS JSON))
WHERE `id` = 'A263';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '家里的东西'),
  `trains` = COALESCE(`trains`, '学会比较，是数学概念的基础。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿两样东西问「哪个大？」"},{"imageUrl":null,"instruction":"再比长短、高矮、多少、轻重。"},{"imageUrl":null,"instruction":"从差很多的开始比。"},{"imageUrl":null,"instruction":"一次只比一种属性。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两样差很多'),
  `harder` = COALESCE(`harder`, '三样以上排序，或差异小。'),
  `tip` = COALESCE(`tip`, '生活中随时可以比：谁的鞋子大、哪根筷子长、哪杯水多——比教具有效得多。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组六（形容词与概念词）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"比较是数学的起点。但有一条规矩：一次只比一种属性——比大小的时候，就不要提长短。","principles":["比较是数学最基本的操作，也是排序和测量的前身。","孩子要先能比两样，才谈得上排三样以上。","一次只比一种属性，否则孩子会把大和长混在一起。","大小、长短、高矮、多少、轻重，每一种都要分开练。","从差异很大的开始，一眼就看得出来，成功率高。","差异小的要靠实际比对，那是下一阶的能力。","比长短可以把两样并排对齐，那是很重要的方法。","对齐起点再比，是日后测量概念的基础。","轻重要用手掂，因为看不出来，必须靠身体感觉。"],"prep":{"场地":"桌面或地板，两样东西放得下的地方。","器材":"家里现有的东西，每种属性各准备一组。","安全检查":"比轻重时不使用过重物品；不让孩子搬抬重物。","大人位置":"大人把两样东西并排放好，问完等他回答。"},"shots":[{"name":"比大小","say":"哪一个比较大？"},{"name":"比长短","say":"哪一个比较长？"},{"name":"对齐再比","say":"我们把头对齐再看。"},{"name":"比多少","say":"哪一堆比较多？"},{"name":"比轻重","say":"两手拿拿看，哪个重？"},{"name":"一次只比一种","say":"（字幕：比大小时不要同时提长短）"}],"reactions":[{"if":"孩子答错","then":"把两样并排对齐再问一次。方法比答案重要。"},{"if":"孩子把大和长搞混","then":"很常见。分开练：今天只比大小，明天只比长短。"},{"if":"孩子觉得太简单","then":"缩小差异，或改成三样以上排序。"}],"mistakes":["同时问大小和长短，孩子混淆。","差异太小，孩子看不出来就猜。","比长短时没有对齐起点，答案会错。"],"down":"两样差异极大，并由大人并排对齐后再问。","up":"三样以上排序，或差异很小需要实际比对。","progress":["能不能正确比出大小。","会不会把两样对齐再比。","能处理多小的差异。"],"outro":"一次只比一种属性。比长短的时候记得把头对齐——这个动作，就是以后测量的基础。"}' AS JSON))
WHERE `id` = 'A264';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '几样大小不同的东西'),
  `trains` = COALESCE(`trains`, '按大小或长短排序，练序列概念。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿三样大小不同的东西。"},{"imageUrl":null,"instruction":"让孩子从大排到小。"},{"imageUrl":null,"instruction":"再从小排到大。"},{"imageUrl":null,"instruction":"数量慢慢增加。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三样、差异大'),
  `harder` = COALESCE(`harder`, '五样以上、差异小。'),
  `tip` = COALESCE(`tip`, '套杯、积木、家人的鞋子都能排——排序是数学里「大小关系」的具体版本。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"从大排到小——这比比较两样难，因为每一样都要同时和前后比。今天从三样开始。","principles":["排序需要同时处理多个比较关系，比两两比较难一阶。","排三样时，中间那样要同时比左边小、比右边大。","这个双重关系是排序真正的难点。","所以从三样开始，而且差异要大。","差异大，比较的判断就容易，孩子才有余力处理关系。","从大排到小之后，再从小排到大，方向反过来也要会。","反方向不是重复，它需要重新组织，不是把答案倒过来念。","数量慢慢增加，五样以上难度明显上升。","排序是序列概念的基础，和数线、时间顺序都相关。"],"prep":{"场地":"桌面或地板，一排放得下的空间。","器材":"三到五样大小明显不同的东西（碗、积木、玩偶）。","安全检查":"不使用易碎或会滚落的物品；三岁以下不使用可吞入的小物。","大人位置":"大人把东西打乱放在孩子面前，不先排好。"},"shots":[{"name":"打乱三样","say":"这三个，从大排到小。"},{"name":"孩子排序","say":"（孩子移动物品）"},{"name":"中间最难","say":"（孩子在中间那样卡住）"},{"name":"排好了","say":"大、中、小。"},{"name":"反方向再排","say":"这次从小排到大。"},{"name":"增加数量","say":"这次五个。"}],"reactions":[{"if":"孩子排不出来","then":"减到两样先比大小，成功了再加第三样。"},{"if":"孩子卡在中间那一样","then":"引导两两比较：「它比这个大吗？比那个呢？」拆成两次比较。"},{"if":"孩子反方向排不出来","then":"不直接把顺序倒过来给他。请他从最小的开始找起，重新组织。"}],"mistakes":["一开始就用五样，孩子负荷太大。","差异太小，比较本身就困难。","反方向时直接帮他倒过来，少了重新组织的练习。"],"down":"只排三样且大小差异极大，并由大人先放好最大的那一样。","up":"五样以上，或大小差异很小需要仔细比对。","progress":["能排好几样。","中间的顺序对不对。","反方向排得出来吗。"],"outro":"排序最难的是中间那一样——它要同时比左边小、比右边大。卡住的时候，拆成两次两两比较就好。"}' AS JSON))
WHERE `id` = 'A265';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '积木或彩色小物'),
  `trains` = COALESCE(`trains`, '发现规律并接下去，是数学推理的开始。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"排一个规律：红蓝红蓝红……"},{"imageUrl":null,"instruction":"问「接下来是什么？」"},{"imageUrl":null,"instruction":"规律慢慢变复杂：红红蓝、红蓝绿。"},{"imageUrl":null,"instruction":"也可以用动作排规律（拍手拍腿拍手拍腿）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两个一循环'),
  `harder` = COALESCE(`harder`, '三个一循环，或自己创造规律。'),
  `tip` = COALESCE(`tip`, '规律是数学思维的核心之一——从颜色、形状到动作、声音，处处都能玩。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"红蓝红蓝红——接下来是什么？找出规律并接下去，这是数学推理真正的开始。","principles":["规律是数学的核心，数字、乘法、代数全都建立在规律上。","孩子要先能看出重复的单位，才接得下去。","所以关键是发现「红蓝」是一组，而不是一个一个看。","可以带着他念出来：红蓝、红蓝、红蓝，念出节奏就抓到了。","从两个一循环开始，那是最容易听出节奏的。","熟了再进到三个一循环，或两长一短这类不对称的。","用动作排规律也很好：拍手拍腿拍手拍腿。","动作版本加上了身体节奏，对听觉型的孩子特别有效。","最后让孩子自己创造规律，那是从辨认走到产出。"],"prep":{"场地":"桌面，一排排得开的空间。","器材":"两三色的积木或彩色小物，每色数量要够。","安全检查":"三岁以下使用大颗积木避免吞入；桌面稳固。","大人位置":"大人排出规律，留一个空位等孩子接。"},"shots":[{"name":"排出规律","say":"红蓝红蓝红……"},{"name":"念出节奏","say":"红蓝、红蓝、红蓝。"},{"name":"接下去","say":"接下来是什么？"},{"name":"换复杂一点","say":"红红蓝、红红蓝……"},{"name":"用动作排","say":"拍手、拍腿、拍手、拍腿。"},{"name":"换他创造","say":"换你排一个规律考我。"}],"reactions":[{"if":"孩子看不出规律","then":"带着他念出来，念三遍。听觉的节奏常常比视觉更容易抓。"},{"if":"孩子随便乱接","then":"把重复的单位圈起来或用手框住：「你看，这两个是一组。」"},{"if":"孩子创造的规律不成立","then":"先照着他的排下去，排到不通时一起发现，不直接指正。"}],"mistakes":["一开始就用三个一循环，孩子抓不到。","只让孩子接，不让他自己创造。","孩子接错就直接纠正，没有用念的帮他抓节奏。"],"down":"两个一循环，并由大人带着念出节奏三遍。","up":"三个以上一循环、不对称的规律，或自己创造并说明规律。","progress":["能不能接出下一个。","能处理几个一循环的规律。","会不会自己创造规律。"],"outro":"看不出来的时候，带着他念出来——红蓝、红蓝、红蓝。节奏一出来，规律就抓到了。"}' AS JSON))
WHERE `id` = 'A266';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '任何可以数的东西'),
  `trains` = COALESCE(`trains`, '一个一个点着数，是真正的「会数数」。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"数楼梯、数饼干、数玩具。"},{"imageUrl":null,"instruction":"一个一个点着数，一个数字对一个东西。"},{"imageUrl":null,"instruction":"数完说「一共三个」。"},{"imageUrl":null,"instruction":"从五以内开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '数三个'),
  `harder` = COALESCE(`harder`, '数十个以上并说出总数。'),
  `tip` = COALESCE(`tip`, '背「1234」和「会数数」是两回事——要能点一下说一个数字、数完知道总数，那才是真的懂。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组六（数学能力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"会背一到十，不代表会数数。真正的会数数，是一个数字对一个东西——而且数完说得出一共几个。","principles":["背数字是语音记忆，数数是数量概念，两件事完全不同。","很多孩子背得很流利，但拿三颗糖给他就数不出来。","真正的数数要做到一对一对应：点一个、说一个。","手指点到哪、嘴巴说到哪，这个同步是关键技巧。","大人可以握着孩子的手，带着他一个一个点。","速度要慢，快了手和嘴就对不上。","数完要说出总数「一共三个」，这叫基数概念。","很多孩子数得出来却答不出一共几个，那代表还没真的懂。","从五以内开始，数量小才容易做到一对一对应。"],"prep":{"场地":"餐桌、楼梯或收玩具的地方。","器材":"饼干、积木、手指、楼梯，任何可以一个一个点的东西。","安全检查":"在楼梯上数数时大人一定站在孩子下方一阶；三岁以下不使用可吞入的小物。","大人位置":"大人握着或轻扶孩子的食指，带着他一个一个点。"},"shots":[{"name":"摆出三个","say":"我们来数饼干。"},{"name":"带着点","say":"一、二、三。"},{"name":"慢一点","say":"（放慢速度，每点一下停一下）"},{"name":"说出总数","say":"一共三个！"},{"name":"数楼梯","say":"一阶、两阶、三阶。"},{"name":"背 vs 数","say":"（对照：快速背数字 vs 慢慢点着数）"}],"reactions":[{"if":"孩子数得比东西多或少","then":"握着他的手带着点，速度放到很慢，让手和嘴同步。"},{"if":"孩子数完答不出总数","then":"你替他说：「一、二、三——一共三个。」多示范几次他会跟上。"},{"if":"孩子只会背不会点","then":"减到两三个，并把东西分开摆，让每一个都很清楚。"}],"mistakes":["以为会背数字就是会数数。","数得太快，手和嘴对不上。","数完不说总数，基数概念就没练到。"],"down":"只数两三个，握着孩子的手带着点，每点一下停一下。","up":"数十个以上，或数完拿走一个再问「现在剩几个」。","progress":["点一个说一个对得上吗。","数完会不会说出总数。","能正确数到几个。"],"outro":"会背一到十，不等于会数数。要能一个一个点着数，而且数完说得出一共几个——先看准确，再看数量。"}' AS JSON))
WHERE `id` = 'A267';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '餐具、点心'),
  `trains` = COALESCE(`trains`, '一对一分配，是数量概念的实作。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"「每个人一个碗」让孩子分。"},{"imageUrl":null,"instruction":"「每个杯子放一根吸管」。"},{"imageUrl":null,"instruction":"分完看看有没有多或少。"},{"imageUrl":null,"instruction":"摆餐桌时天天可以练。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三个人份'),
  `harder` = COALESCE(`harder`, '更多人，或一人分两样。'),
  `tip` = COALESCE(`tip`, '摆餐具就是最好的数学课——一对一对应是数量概念的核心，比数数更根本。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组六（数学能力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"摆餐桌的时候让孩子发碗——每个人一个。这是一对一对应最真实的练习，而且天天都有机会。","principles":["一对一分配，是把数量概念放进真实动作里。","孩子不需要知道有几个人，只要做到「一人一个」。","这个动作本身就在建立一对一对应的概念。","分完看看有没有多或少，就会发现数量的关系。","多了代表东西比人多，少了代表不够，这是最早的数量比较。","摆餐桌是真实任务，孩子会觉得自己在帮忙。","真实任务的动机远高于教具，而且天天都有机会。","进阶是一人分两样（一个碗加一根汤匙），那是二对一。","这是日后乘法概念的远源，但现在只要动手做就好。"],"prep":{"场地":"餐桌边，餐具放在孩子拿得到的地方。","器材":"碗、汤匙、杯子、吸管等可以一人一份的东西。","安全检查":"使用不易破的餐具（塑胶或美耐皿），不让孩子拿玻璃或陶瓷；不搬运热食。","大人位置":"大人在旁边看着，不急着帮忙摆。"},"shots":[{"name":"交代任务","say":"每个人一个碗，你来发。"},{"name":"一人一个","say":"（孩子一个一个放到每个位子）"},{"name":"检查","say":"每个人都有了吗？"},{"name":"多了或少了","say":"咦，多了一个。"},{"name":"一人两样","say":"每个人一个碗、一根汤匙。"},{"name":"天天都能练","say":"（快剪几天的摆餐桌画面）"}],"reactions":[{"if":"孩子漏掉一个位子","then":"不直接指出。请他绕一圈检查：「每个位子都看一下。」"},{"if":"孩子一次放好几个","then":"握着他的手一次拿一个：「一个位子，一个碗。」"},{"if":"孩子觉得太简单","then":"加到一人两样，或请他先数出需要几个再去拿。"}],"mistakes":["大人急着帮忙摆，孩子没有练到。","一开始就一人两样，负荷太大。","孩子放错就直接调整，少了自己检查的机会。"],"down":"只分三个人份，并由大人指着每个位子提示。","up":"更多人份，或一人分两三样，甚至先数出需要几个再去拿。","progress":["能不能做到一人一个不漏不重。","会不会自己检查。","能处理一人几样。"],"outro":"摆餐桌天天都有机会。分完记得问一句「每个人都有了吗」——多了或少了，就是最早的数量比较。"}' AS JSON))
WHERE `id` = 'A268';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '两堆东西'),
  `trains` = COALESCE(`trains`, '比较数量的多少。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"摆两堆东西，问「哪一堆多？」"},{"imageUrl":null,"instruction":"可以一对一排开来比。"},{"imageUrl":null,"instruction":"再问「多几个？」"},{"imageUrl":null,"instruction":"从差很多的开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '差很多、一眼看出'),
  `harder` = COALESCE(`harder`, '数量接近，要数一数才知道。'),
  `tip` = COALESCE(`tip`, '一对一排开来比，孩子马上就看出哪边多——这个方法比直接数更直观，也是数学的重要策略。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组六（数学能力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"哪一堆比较多？看起来简单，但孩子常常被「排得比较开」骗到。今天教他一个方法：一对一排开来比。","principles":["幼儿判断多少常常靠外观，排得开的那堆看起来比较多。","这是正常的发展现象，不是孩子笨。","要突破它，需要一个可靠的方法：一对一排开来比。","两堆排成两列一一对应，多出来的那几个一眼就看得到。","这个方法把「看起来」变成「对得起来」，非常有力。","而且它同时解决了「多几个」这个问题。","从差很多的开始，先让孩子有正确的直觉。","数量接近的时候就必须用方法，那时候方法才显得有用。","这是日后减法和差的概念的具体起点。"],"prep":{"场地":"桌面，两列排得开的空间。","器材":"两堆同样的小东西（积木、钮扣、糖果）。","安全检查":"三岁以下不使用可吞入的小物，改用大颗积木。","大人位置":"大人示范把两堆排成上下两列对齐。"},"shots":[{"name":"两堆东西","say":"哪一堆比较多？"},{"name":"外观会骗人","say":"（孩子指了排得开的那堆）"},{"name":"教方法","say":"我们排成两排比比看。"},{"name":"一眼看出","say":"（多出来的两个很明显）"},{"name":"多几个","say":"多了两个。"},{"name":"数量接近","say":"（换两堆数量很接近的）"}],"reactions":[{"if":"孩子被外观骗到","then":"不说错。直接排成两列一起看，让方法自己说话。"},{"if":"孩子不肯排开","then":"由大人排一次示范，让他看到结果的清楚程度。"},{"if":"孩子已经会数","then":"那就两种方法都用：先数一数，再排开来验证。"}],"mistakes":["只问哪个多，不教比较的方法。","孩子答错就说他不对，没有给他工具。","一开始就用数量接近的，孩子只能猜。"],"down":"两堆数量差很多，并由大人排成两列示范一次。","up":"数量接近需要实际比对，或要求说出多几个。","progress":["能不能正确判断多少。","会不会使用一对一排开的方法。","能不能说出多几个。"],"outro":"孩子被外观骗到很正常。给他一个方法：排成两列对齐——多出来的那几个，一眼就看得到。"}' AS JSON))
WHERE `id` = 'A269';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '步骤图或照片'),
  `trains` = COALESCE(`trains`, '理解事情的先后顺序。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把一件事拆成两三步：洗手（打湿→搓泡泡→擦干）。"},{"imageUrl":null,"instruction":"做成图卡让孩子排顺序。"},{"imageUrl":null,"instruction":"排好了照着做一遍。"},{"imageUrl":null,"instruction":"从最熟悉的流程开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两三步'),
  `harder` = COALESCE(`harder`, '四五步，还要说出顺序。'),
  `tip` = COALESCE(`tip`, '顺序概念是叙事、写作和做事的基础——把每天的流程（起床、洗澡、睡前）都做成步骤图，天天在练。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十五（作息时间安排与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"洗手分成三步：打湿、搓泡泡、擦干。把流程画成图卡排顺序——这是步骤概念最好的练习。","principles":["理解先后顺序，是执行任何多步骤任务的前提。","孩子常常跳步骤，不是不听话，是流程在他脑中不清楚。","把流程拆成两三步，每一步都具体可见。","做成图卡让他排顺序，抽象的流程就变成看得见的东西。","排完照着做一遍，图卡就变成他的提示卡。","从最熟悉的流程开始：洗手、穿衣、刷牙。","熟悉的流程他有经验，排起来才有依据。","陌生的流程要先做过几次，再来排顺序。","这个能力会一路用到写作业、准备书包、做实验。"],"prep":{"场地":"流程发生的地方（洗手台、玄关），以及桌边排图卡。","器材":"自己画或拍的三张步骤图卡。","安全检查":"图卡圆角或护贝；洗手示范时注意水温，不使用热水。","大人位置":"大人和孩子一起拍照或画图，做成属于他的图卡。"},"shots":[{"name":"拆成三步","say":"洗手有三步：打湿、搓泡泡、擦干。"},{"name":"做成图卡","say":"（三张图卡摊在桌上）"},{"name":"打乱排顺序","say":"哪个先？哪个后？"},{"name":"排好了","say":"先打湿、再搓泡泡、最后擦干。"},{"name":"照着做一遍","say":"我们照着做。"},{"name":"贴在洗手台旁","say":"贴在这里，每次都看得到。"}],"reactions":[{"if":"孩子排错顺序","then":"一起实际做一遍，做到那一步时问「现在应该是哪一张？」"},{"if":"孩子不熟悉那个流程","then":"先陪他做几次。没有经验就排不出顺序。"},{"if":"孩子觉得图卡幼稚","then":"改成文字清单，或让他自己画。形式可以变，结构不变。"}],"mistakes":["一开始就用四五步的复杂流程。","只排图卡不实际做，流程没有落地。","用陌生的流程，孩子没有经验可以依据。"],"down":"只有两步（打湿、擦干），并由大人先放好第一张。","up":"四五步的流程，并要求用「先、再、然后、最后」说出来。","progress":["能不能排出正确顺序。","会不会照着流程完成动作。","能处理几步的流程。"],"outro":"从最熟悉的流程开始——他做过，才排得出来。排好的图卡贴在旁边，就变成他每天的提示卡。"}' AS JSON))
WHERE `id` = 'A270';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '三张有先后关系的图'),
  `trains` = COALESCE(`trains`, '排出事情的先后，练逻辑顺序。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"画三张图：种子→发芽→开花，或摔倒→哭→贴OK绷。"},{"imageUrl":null,"instruction":"打乱让孩子排出顺序。"},{"imageUrl":null,"instruction":"排好了说说为什么。"},{"imageUrl":null,"instruction":"再讲成一个小故事。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三张、关系明显'),
  `harder` = COALESCE(`harder`, '四五张，或关系需要推理。'),
  `tip` = COALESCE(`tip`, '简笔画三张图就能玩。排完再让他讲一遍，顺便练了叙事——一个活动两种收获。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"种子、发芽、开花——排出顺序，然后说说为什么。这个游戏练的是因果的逻辑，不只是先后。","principles":["排事件的顺序，需要理解事件之间的因果关系。","不是记住顺序，而是知道为什么这个在前、那个在后。","所以排好之后一定要问「为什么这样排」。","说得出理由，代表他掌握的是逻辑不是记忆。","选材很重要：因果关系要清楚，像种子发芽开花。","摔倒、哭、贴OK绷也很好，因为孩子有亲身经验。","有经验的题材，推理起来才有依据。","排好之后再讲成一个小故事，连结到叙事能力。","这个能力是日后看图作文和阅读理解的基础。"],"prep":{"场地":"桌边，三张图排得开的空间。","器材":"三张有明显因果先后的图（自己画或用绘本影印）。","安全检查":"图卡圆角或护贝；剪裁由大人完成。","大人位置":"大人把图卡打乱放在孩子面前，不给提示。"},"shots":[{"name":"打乱三张图","say":"这三张的顺序乱了。"},{"name":"孩子排序","say":"（孩子移动图卡）"},{"name":"排好了","say":"种子、发芽、开花。"},{"name":"问为什么","say":"为什么这样排？"},{"name":"说出因果","say":"因为要先有种子才会发芽。"},{"name":"讲成故事","say":"我们把它讲成一个故事。"}],"reactions":[{"if":"孩子排错","then":"不直接改。问「这一张之前发生了什么事？」引导他往前推。"},{"if":"孩子排对说不出理由","then":"由你先说一次因果：「因为先有种子，才会发芽。」示范说法。"},{"if":"孩子对题材没兴趣","then":"换成他亲身经历过的事（洗澡、出门、睡前），经验越近越好排。"}],"mistakes":["选的题材孩子没有经验，无从推理。","只排顺序不问理由，练到的只是记忆。","排错就直接帮他改好，少了推理的过程。"],"down":"只用两张图（前和后），并选孩子亲身经历过的事件。","up":"四五张图，或事件关系需要推理而非直接可见。","progress":["能不能排出正确顺序。","说不说得出因果理由。","能处理几张图。"],"outro":"排对了不算完，一定要问「为什么这样排」。说得出因果，练到的才是逻辑，不只是记住顺序。"}' AS JSON))
WHERE `id` = 'A271';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '生活中的事'),
  `trains` = COALESCE(`trains`, '理解事情的原因和结果。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"生活中问「为什么？」：为什么要带伞？为什么冰会融化？"},{"imageUrl":null,"instruction":"答不出来给两个选项。"},{"imageUrl":null,"instruction":"也反过来问「如果不穿外套会怎样？」"},{"imageUrl":null,"instruction":"从最熟悉的因果开始。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '二选一选出原因'),
  `harder` = COALESCE(`harder`, '自己说出「因为……」。'),
  `tip` = COALESCE(`tip`, '因果理解是逻辑思维的核心。孩子问「为什么」的时候，别嫌烦——那是他在建立对世界的理解。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十三（描述·解释与推理语言）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"为什么要带伞？为什么冰会融化？——生活里到处都是因果。但一天问一两个就好，问多了会烦。","principles":["因果理解是科学思考和逻辑推理的核心。","孩子对「为什么」的回答，反映的是他对世界的理解程度。","从最熟悉的生活因果问起，他才有经验可以依据。","带伞、穿外套、洗手，这些他每天都在做。","答不出来就给两个选项，选择比自由回答容易太多。","反过来问「如果不……会怎样」，是从另一个方向练同一件事。","正问和反问合起来，因果的两端都练到了。","一天问一两个就好，问太多会变成疲劳轰炸。","而且要避免用「为什么你又……」这种带责备的问法。"],"prep":{"场地":"生活场景中，事情正在发生的时候。","器材":"不需要任何东西。","安全检查":"无特殊风险。避免用责备语气发问；不用危险的因果做示范实验。","大人位置":"大人和孩子一起做那件事，边做边问。"},"shots":[{"name":"边做边问","say":"今天为什么要带伞？"},{"name":"先示范答法","say":"因为在下雨。"},{"name":"换一题","say":"冰放在外面会怎样？"},{"name":"二选一","say":"因为很热，还是因为很冷？"},{"name":"反过来问","say":"如果不带伞会怎样？"},{"name":"一天一两个","say":"（字幕：问太多会烦）"}],"reactions":[{"if":"孩子说不知道","then":"立刻给两个选项。选对了再由你把完整句说一次。"},{"if":"孩子的答案不合逻辑","then":"先接住他的想法，再说出你的版本让他听，不否定。"},{"if":"孩子被问烦了","then":"停。一天一两个就好，问太多会让他对「为什么」反感。"}],"mistakes":["问太抽象的为什么，孩子没有经验可以连。","答不出来还一直追问，变成压力。","用「为什么你又打翻了」这种责备句，孩子会关起来。"],"down":"只用二选一回答，并由大人把完整句说一次。","up":"自己说出「因为……」，并能回答需要多想一步的因果。","progress":["能不能从选项中选出合理的原因。","会不会自己说出「因为……」。","能处理多抽象的因果。"],"outro":"从他每天都做的事问起，答不出来就给两个选项。一天一两个就好——而且不要用「为什么你又……」。"}' AS JSON))
WHERE `id` = 'A272';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '预测结果，练推理和想象。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"问假设性的问题：「如果下雨我们没带伞会怎样？」"},{"imageUrl":null,"instruction":"「如果把冰放在外面会怎样？」"},{"imageUrl":null,"instruction":"听他的推测，再一起验证。"},{"imageUrl":null,"instruction":"可以真的做做看（冰块实验）。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '结果明显的'),
  `harder` = COALESCE(`harder`, '需要多想一步的。'),
  `tip` = COALESCE(`tip`, '能预测结果的孩子，做事前会先想一下——这也是安全意识和自我控制的基础。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"如果把冰块放在外面会怎样？——先让他猜，然后真的做做看。预测加验证，这就是科学方法。","principles":["预测结果需要把已知的因果往前推一步。","这比解释已经发生的事更难，因为结果还没出现。","所以这是比「为什么」更高一阶的推理。","重点不是猜对，是他有没有根据在推。","猜完之后真的做做看，验证的过程最有价值。","预测、验证、修正，这正是科学方法的雏形。","猜错了更好玩，因为意外的结果最容易记住。","冰块实验很适合：时间短、变化明显、完全安全。","日常生活中随时都能问，不需要准备任何东西。"],"prep":{"场地":"厨房或桌边（冰块实验），或任何生活场景。","器材":"冰块和两个盘子；其他情境不需要器材。","安全检查":"实验限于安全范围：不用火、不用热水、不用刀具；冰块不直接长时间接触皮肤。","大人位置":"大人在旁边，让孩子自己动手放冰块。"},"shots":[{"name":"提出问题","say":"如果把冰块放在外面，会怎样？"},{"name":"让他猜","say":"（孩子说出他的猜测）"},{"name":"真的做做看","say":"我们试试看。"},{"name":"等待与观察","say":"（缩时：冰块慢慢融化）"},{"name":"验证","say":"你猜对了！"},{"name":"猜错也很好","say":"（另一次猜错，两人一起惊讶）"}],"reactions":[{"if":"孩子猜不出来","then":"给两个可能让他选，选完问一句「为什么这样想」。"},{"if":"孩子的猜测天马行空","then":"接受，然后一起验证。验证会自己给出答案。"},{"if":"孩子不想等实验结果","then":"选变化快的实验，或在等待时做别的事，时间到再回来看。"}],"mistakes":["只问不验证，预测就变成空谈。","孩子猜错就说「不对」，下次他不敢猜。","实验涉及火、热水或刀具，不安全也失焦。"],"down":"结果很明显的情境，并给两个可能让他选。","up":"需要多想一步的情境，并要求说出预测的理由。","progress":["愿不愿意说出预测。","预测有没有根据。","会不会想要验证。"],"outro":"猜完一定要真的做做看。预测、验证、修正——这就是科学方法，从一颗冰块就开始了。"}' AS JSON))
WHERE `id` = 'A273';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '从线索推理出答案。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给三个线索：「圆圆的、红红的、可以吃」。"},{"imageUrl":null,"instruction":"让孩子猜。"},{"imageUrl":null,"instruction":"猜对了换他出题。"},{"imageUrl":null,"instruction":"线索从明显到隐晦。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三个明显线索'),
  `harder` = COALESCE(`harder`, '线索少一点或抽象一点。'),
  `tip` = COALESCE(`tip`, '这个游戏同时练了推理和表达——出题的人要想清楚特征，猜的人要综合线索，两边都在动脑。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"圆圆的、红红的、可以吃——从三个线索推出答案。这个游戏练的是把讯息整合起来的能力。","principles":["从线索推理，需要把好几条讯息同时放在脑中整合。","单一线索通常不够，必须综合起来才缩得到一个答案。","这正是阅读理解和解题时在做的事。","三个线索是不错的起点：一个太少，五个太多。","线索的顺序也有讲究：从大范围到小范围。","先说形状或颜色，再说用途，范围会一步步缩小。","猜对了换他出题，出题比猜更难。","因为他要先想好答案，再反推有哪些线索。","线索从明显到隐晦，难度自然提高。"],"prep":{"场地":"任何地方：餐桌、车上、排队时。","器材":"不需要任何东西。","安全检查":"无特殊风险。避免用孩子不熟悉的东西出题造成挫折。","大人位置":"大人先出题示范，线索一条一条给。"},"shots":[{"name":"给第一个线索","say":"我想到一样东西，它是圆圆的。"},{"name":"第二个线索","say":"它是红红的。"},{"name":"第三个线索","say":"而且可以吃。"},{"name":"孩子猜","say":"（孩子喊「苹果！」）"},{"name":"线索的顺序","say":"（字幕：从大范围到小范围）"},{"name":"换他出题","say":"换你出题考我。"}],"reactions":[{"if":"孩子三个线索还猜不到","then":"再加一个更明确的线索。不要让他一直卡住。"},{"if":"孩子出题时线索太模糊","then":"诚实说「我猜不到，再给一个提示」。回馈比纠正有效。"},{"if":"孩子出题时直接说出答案","then":"笑着说「那我就猜到啦」，再玩一次。用游戏提醒规则。"}],"mistakes":["线索太隐晦，孩子一直猜不到就没兴趣。","用孩子不熟悉的东西出题。","只让孩子猜，不让他出题，少掉更难的那一半。"],"down":"三个非常明显的线索，并限定在眼前看得到的东西。","up":"线索少一点或抽象一点，或描述一件事情而不是东西。","progress":["几个线索之后能猜到。","会不会整合多条线索。","出题时线索够不够清楚。"],"outro":"线索从大范围到小范围给。猜不到就再加一个——重点是他有在把线索凑起来想。"}' AS JSON))
WHERE `id` = 'A274';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '家里的东西'),
  `trains` = COALESCE(`trains`, '认识基本形状，也练观察。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"找家里的圆形（盘子、时钟）、方形（书、窗）、三角形（三明治）。"},{"imageUrl":null,"instruction":"出门也玩「找形状」。"},{"imageUrl":null,"instruction":"再练画出这些形状。"},{"imageUrl":null,"instruction":"一次专注一种形状。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '认三种基本形状'),
  `harder` = COALESCE(`harder`, '找出复杂东西里的形状。'),
  `tip` = COALESCE(`tip`, '形状认知是几何和认字的基础——把家里变成寻宝场，比看形状卡有趣。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十一（视知觉）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"今天只找圆形。盘子、时钟、轮子——一次专注一种形状，孩子才分得清楚。","principles":["形状是几何概念的起点，也是视知觉的重要成分。","孩子必须把形状从物体本身抽离出来才学得会。","盘子既是盘子，也是圆形，这个双重身份不容易。","一次专注一种形状，孩子才能发现「这些东西不一样，但形状一样」。","从圆形开始最容易，因为圆形没有角、辨识度最高。","再来是方形，最后是三角形。","出门玩「找形状」，把概念带到不同情境，泛化才算学会。","再练画出这些形状，从辨认走到产出。","画形状同时也练到手部动作和视觉动作整合。"],"prep":{"场地":"家里各处，以及出门散步时。","器材":"家里现有的东西；纸笔用于最后画形状。","安全检查":"找形状时不让孩子爬高或拉扯桌布；画画使用无毒画笔。","大人位置":"大人和孩子一起走动找，不坐着指挥。"},"shots":[{"name":"宣布主题","say":"今天我们只找圆形。"},{"name":"一起找","say":"圆圆的盘子、圆圆的时钟。"},{"name":"排在一起","say":"你看，全部都是圆的。"},{"name":"换方形","say":"今天找方形——书、窗户。"},{"name":"出门找","say":"看到圆形就喊圆形！"},{"name":"画出来","say":"我们来画一个圆形。"}],"reactions":[{"if":"孩子把形状说错","then":"直接示范正确说法，并用手沿着边缘描一遍，让他感觉形状。"},{"if":"孩子只会指不会说","then":"指对就代表认得了。名称由你说出来，多听几次自然会。"},{"if":"孩子画不出形状","then":"先用手指在空中比划，或握着他的手画一次。"}],"mistakes":["一次教三四种形状，孩子混在一起。","只用形状积木，没有连到生活中的真实物品。","要求画得标准，孩子会因此不想画。"],"down":"只认圆形一种，并用手沿着边缘描一遍加强触觉。","up":"找出复杂物品中的形状（车轮是圆的、车窗是方的），或组合形状作画。","progress":["能不能指出指定的形状。","会不会说出形状的名称。","能不能在复杂物品中找出形状。"],"outro":"一次只找一种形状。用手沿着边缘描一遍，让他用摸的感觉形状——比只用眼睛看有效。"}' AS JSON))
WHERE `id` = 'A275';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–6岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '玩具和盒子'),
  `trains` = COALESCE(`trains`, '理解空间位置词。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把玩具放在盒子上面、里面、下面、旁边。"},{"imageUrl":null,"instruction":"问「小熊在哪里？」"},{"imageUrl":null,"instruction":"再换他照指令放：「放在盒子后面」。"},{"imageUrl":null,"instruction":"收东西时也说位置。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '上面、里面'),
  `harder` = COALESCE(`harder`, '前面后面、左边右边。'),
  `tip` = COALESCE(`tip`, '空间词是数学（图形、方位）和阅读（左到右）的基础——藏东西找东西的游戏最好练。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组六（形容词与概念词）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"上面、里面、下面、旁边——这些位置词是听懂指令的基础。用一个盒子和一个玩具就能练。","principles":["位置词是空间概念的语言形式，认知和语言都牵涉到。","听懂位置词，孩子才听得懂「把书放在桌子上面」。","这类指令在家里和学校每天都会出现。","用盒子和玩具练最清楚，因为位置关系一目了然。","先练理解：大人放，孩子说位置。","再练表达：大人说，孩子照着放。","理解永远走在表达前面，顺序不能颠倒。","难度顺序是：上面、里面最容易，前面后面次之，左右最难。","左右通常要到五六岁才稳定，不必急。"],"prep":{"场地":"桌面或地板，盒子和玩具放得下的空间。","器材":"一个盒子和一个小玩偶。","安全检查":"盒子无锐利边缘；不使用会盖住孩子头部的大纸箱。","大人位置":"大人坐在孩子旁边，放的动作要慢让他看清楚。"},"shots":[{"name":"放在上面","say":"小熊在盒子上面。"},{"name":"放在里面","say":"现在呢？在里面。"},{"name":"换他说","say":"小熊在哪里？"},{"name":"换他放","say":"放在盒子后面。"},{"name":"难度顺序","say":"（字幕：上下里外 → 前后 → 左右）"},{"name":"收东西时也说","say":"鞋子放在鞋柜下面。"}],"reactions":[{"if":"孩子只会指不会说","then":"指对就代表听懂了。位置词由你说出来，多听几次。"},{"if":"孩子把上下搞混","then":"用身体演一次：把玩具举高说上面、放地上说下面。"},{"if":"孩子左右一直搞错","then":"那很正常。先不练左右，把上下里外前后练稳再说。"}],"mistakes":["一次教太多位置词。","一开始就练左右，超过发展年龄。","只练理解不练表达，或反过来。"],"down":"只练上面和里面两个词，并由大人放、孩子指。","up":"加入前后、中间、旁边，并要求说出完整句「在盒子的下面」。","progress":["听到位置词能不能正确放。","会不会自己说出位置词。","能处理到哪几个位置词。"],"outro":"难度是有顺序的：上下里外最容易，前后次之，左右最难。左右要到五六岁才稳，不用急。"}' AS JSON))
WHERE `id` = 'A276';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '待整理的玩具或抽屉'),
  `trains` = COALESCE(`trains`, '在真实的整理中运用分类能力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"选一个要整理的地方（玩具箱、抽屉）。"},{"imageUrl":null,"instruction":"一起决定要分成几类。"},{"imageUrl":null,"instruction":"按类别收好。"},{"imageUrl":null,"instruction":"收好后欣赏成果。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '分两类'),
  `harder` = COALESCE(`harder`, '分四五类，还要自己决定分类标准。'),
  `tip` = COALESCE(`tip`, '「自己决定怎么分」比照着大人的分法收更有价值——分类的逻辑是他自己想出来的，才会记得住、用得上。'),
  `deeper` = COALESCE(`deeper`, '作业治疗册 模组十五（作息时间安排与组织）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"整理玩具箱，就是分类能力的实战。而且这一次，让孩子自己决定要分成哪几类。","principles":["整理是分类能力最真实的应用场景。","前面练的分类如果不能用在生活里，就只是游戏。","让孩子自己决定分类标准，是这个活动的重点。","自己决定的标准，他才会记得住、用得上。","大人决定的标准，他下次还是不知道怎么分。","一起决定要分成几类，从两类开始最好。","分好之后按类别收进不同的箱子或格子。","收好后一起欣赏成果，让整理这件事有正向结尾。","下次要找东西时会发现分类的好处，动机就建立了。"],"prep":{"场地":"玩具箱、抽屉或书架前，有空间摊开分类。","器材":"待整理的玩具或物品；几个空箱子或分隔盒。","安全检查":"不搬动过重的收纳箱；箱子不堆高；避免让孩子接触尖锐或细小零件。","大人位置":"大人陪着一起分，但让孩子决定分类标准。"},"shots":[{"name":"乱的玩具箱","say":"（玩具全部混在一起）"},{"name":"全部倒出来","say":"我们先全部倒出来看看。"},{"name":"他决定标准","say":"你想分成哪几类？"},{"name":"分类","say":"（孩子一样一样归类）"},{"name":"收进箱子","say":"（各类收进不同的箱子）"},{"name":"一起欣赏","say":"你看，整齐多了。"}],"reactions":[{"if":"孩子的分类标准很奇怪","then":"只要说得出理由就接受。他的逻辑不一定是你的逻辑。"},{"if":"孩子分到一半放弃","then":"缩小范围，只整理一个小区块。完成一小块比半途而废好。"},{"if":"孩子想分很多类","then":"先分两三类，太多类会分不完，也不好维持。"}],"mistakes":["大人决定所有的分类标准，孩子学不到决策。","一次整理太大的范围，孩子做到累。","整理完就结束，没有一起欣赏成果。"],"down":"只分两类，范围缩到一个小盒子，由大人陪着一起分。","up":"分四五类，并由孩子自己决定标准与说明理由。","progress":["能不能自己决定分类标准。","能分成几类。","能不能完成整个范围。"],"outro":"让他自己决定分成哪几类——自己决定的标准，他才记得住。分完一起欣赏，整理才有好的结尾。"}' AS JSON))
WHERE `id` = 'A277';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子＋超市'),
  `need` = COALESCE(`need`, '购物的机会'),
  `trains` = COALESCE(`trains`, '在真实情境中用数学。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"请孩子帮忙拿「三个苹果」「两瓶牛奶」。"},{"imageUrl":null,"instruction":"数一数篮子里有几样。"},{"imageUrl":null,"instruction":"大一点的孩子可以看价钱、算一算。"},{"imageUrl":null,"instruction":"结账时让他递钱。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '拿指定数量的东西'),
  `harder` = COALESCE(`harder`, '比较价钱或算简单的总数。'),
  `tip` = COALESCE(`tip`, '超市是最好的数学教室——数量、比较、金钱、分类全都用得上，而且是真的在用。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组六（数学能力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"超市是最好的数学教室。请他拿三个苹果、两瓶牛奶——真实的任务，真实的数量。","principles":["在真实情境中用数学，孩子才知道数学是有用的。","拿三个苹果，需要一边数一边控制数量，比纸上作业难。","而且有明确的对错：多拿或少拿一眼就知道。","这种即时的回馈是最好的学习条件。","数一数篮子里有几样，练的是点数和总数。","大一点的孩子可以看价钱、比较贵便宜，进到量的概念。","结账时让他递钱，是货币概念的第一次接触。","整个过程孩子都在帮忙，动机比任何教具都高。","而且每次采买都能练，不需要额外安排时间。"],"prep":{"场地":"超市或市场，人潮不要太多的时段。","器材":"购物清单；一个孩子提得动的小篮子。","安全检查":"超市中全程牵好或在视线内；不让孩子独自跑动或碰触玻璃瓶罐；不让孩子推大推车。","大人位置":"大人在旁边，交代任务后让孩子自己去拿。"},"shots":[{"name":"交代任务","say":"帮我拿三个苹果。"},{"name":"孩子去拿","say":"（孩子一个一个数着放进袋子）"},{"name":"检查数量","say":"三个了吗？我们数一数。"},{"name":"数篮子里有几样","say":"篮子里有几样东西？"},{"name":"看价钱","say":"哪一个比较便宜？"},{"name":"结账递钱","say":"（孩子把钱递给收银员）"}],"reactions":[{"if":"孩子拿错数量","then":"一起数一遍，多的放回去。不说错，只一起核对。"},{"if":"孩子想拿别的东西","then":"先完成任务，再说「我们今天只买清单上的」。任务感要维持。"},{"if":"超市人多孩子分心","then":"改在人少的时段来，或缩短任务只拿一样。"}],"mistakes":["一次交代太多样，孩子记不住。","孩子拿错就直接自己拿，少了核对的机会。","在人潮拥挤的时段进行，安全和专注都成问题。"],"down":"一次只拿一样，数量在三个以内，大人陪着一起走过去。","up":"一次拿两三样不同数量的东西，或比较价钱、估算总数。","progress":["能不能拿到正确的数量。","一次能记住几样任务。","会不会注意到价钱。"],"outro":"超市是最好的数学教室。一次交代一样、数量三个以内开始——拿错了一起数一遍就好。"}' AS JSON))
WHERE `id` = 'A278';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '做点心的机会'),
  `trains` = COALESCE(`trains`, '在烹饪中体验数量、顺序和变化。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"一起做点心：数几个鸡蛋、量几杯面粉。"},{"imageUrl":null,"instruction":"按顺序完成步骤。"},{"imageUrl":null,"instruction":"观察变化（液体变固体、小变大）。"},{"imageUrl":null,"instruction":"做好一起分：一人几块？"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '数材料、跟着做'),
  `harder` = COALESCE(`harder`, '自己量、自己按顺序完成。'),
  `tip` = COALESCE(`tip`, '厨房里有数量、顺序、变化、分配——一次做点心，把这个模组的概念全用上了，最后还能吃。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组六（数学能力）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"做点心的时候，数量、顺序、变化全都在里面。而且最后还有一题：做好了，一人几块？","principles":["烹饪把好几种数学概念放进同一个活动里。","数材料是点数，量面粉是测量，按步骤做是顺序。","观察液体变固体、面团变大，是变化和因果。","最后分食物，是除法概念最早的具体经验。","而且成果可以吃，动机强得不得了。","按顺序完成步骤，同时也在练执行功能。","孩子要记住现在做到哪一步，下一步是什么。","大人的角色是准备好安全的环境，让他自己动手。","这个活动一次涵盖了这个模组大部分的概念。"],"prep":{"场地":"厨房，孩子站得稳的高度（可用稳固的踏凳）。","器材":"简单的点心材料、量杯、搅拌碗；不需要用火的食谱最好。","安全检查":"不让孩子接触炉火、烤箱内部、热锅与刀具；踏凳要稳固防滑；生蛋接触后立即洗手；注意食物过敏。","大人位置":"大人负责所有加热与切割的步骤，孩子只做安全的部分。"},"shots":[{"name":"数材料","say":"我们需要两个蛋。"},{"name":"量面粉","say":"量一杯面粉。"},{"name":"按顺序","say":"先搅蛋，再加面粉。"},{"name":"观察变化","say":"你看，变得黏黏的了。"},{"name":"加热由大人负责","say":"（大人操作烤箱，孩子在安全距离外看）"},{"name":"一人几块","say":"做好了六块，我们三个人，一人几块？"}],"reactions":[{"if":"孩子把材料弄得到处都是","then":"那很正常。先把桌面铺好，让弄乱这件事成本降低。"},{"if":"孩子想靠近炉火或烤箱","then":"明确划一条线：「这条线以内是大人的工作。」界线要一致。"},{"if":"孩子中途失去兴趣","then":"让他做他有兴趣的那几步就好，其他由大人完成。"}],"mistakes":["让孩子接触炉火、热锅或刀具。","步骤太复杂，孩子跟不上就失去兴趣。","大人全部做完，孩子只是旁观。"],"down":"只做不需要加热的点心，孩子只负责数材料和搅拌。","up":"自己量材料、自己按顺序完成，并计算分配的数量。","progress":["能不能数对材料的数量。","会不会按顺序完成步骤。","能不能算出一人几块。"],"outro":"数量、顺序、变化，还有最后的一人几块——一次做点心，这个模组的概念全都用上了。"}' AS JSON))
WHERE `id` = 'A279';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '日常物品'),
  `trains` = COALESCE(`trains`, '把这个模组的概念串起来玩一轮。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"第一关：把一堆东西分成三类。"},{"imageUrl":null,"instruction":"第二关：从大到小排好。"},{"imageUrl":null,"instruction":"第三关：数一数每类有几个。"},{"imageUrl":null,"instruction":"第四关：说出「哪一类最多」。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每关降低难度'),
  `harder` = COALESCE(`harder`, '自己决定分类标准，并说出理由。'),
  `tip` = COALESCE(`tip`, '这些概念不必用教材教——收玩具、买菜、做饭、洗衣服，生活里处处都是数学和逻辑课，而且孩子学得更牢。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组六 · 模组十八（数学能力 · 逻辑推理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"这是模组十四的总复习，四关：分类、排序、点数、比较——这个模组的四根柱子。","principles":["这个模组练的是四种基本的认知操作。","分类是把东西归成一类，排序是排出顺序。","点数是算出数量，比较是判断多少大小。","这四样是所有数学概念的地基。","四关刚好把这四样各测一次。","而且四关用同一堆东西完成，前后连贯。","先分类，再在每一类里排序，再数每类几个，最后比较哪类最多。","这个流程本身就展示了四种操作怎么串起来用。","哪一关卡住，就回去补对应的那几个活动。"],"prep":{"场地":"桌面或地板，一堆东西摊得开的空间。","器材":"一堆日常物品，种类和大小都要有变化。","安全检查":"三岁以下不使用可吞入的小物；不使用易碎物品。","大人位置":"大人当主持人，每关先说明，必要时给提示。"},"shots":[{"name":"宣布四关","say":"今天四关：分类、排序、数数、比较。"},{"name":"第一关分类","say":"把这一堆分成三类。"},{"name":"第二关排序","say":"每一类里，从大排到小。"},{"name":"第三关点数","say":"数一数每一类有几个。"},{"name":"第四关比较","say":"哪一类最多？"},{"name":"收尾","say":"四关都完成了！"}],"reactions":[{"if":"某一关明显吃力","then":"降低标准让他过关，记下来，之后回去单独练那几个活动。"},{"if":"孩子没耐心走完","then":"分两天做完。四关不必一次走完。"},{"if":"孩子想用自己的方式分类","then":"完全可以。只要说得出理由，那就是有效的分类。"}],"mistakes":["把它当成测验，孩子有压力就表现失真。","四关硬要一次走完，最后草草结束。","坚持只有一种正确的分类方式。"],"down":"每关都降低数量与标准，并由大人给提示。","up":"自己决定分类标准，并说出每一关的理由。","progress":["四关各自的表现。","哪一关最需要提示。","能不能说出自己的理由。"],"outro":"四关用同一堆东西走完：先分类、再排序、再数数、最后比较。哪一关卡住，就回去补那几个活动。"}' AS JSON))
WHERE `id` = 'A280';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '放高一点的东西'),
  `trains` = COALESCE(`trains`, '遇到困难先想办法，而不是直接放弃或哭。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"把他想要的东西放在拿不到的地方。"},{"imageUrl":null,"instruction":"别马上帮他，问「你觉得可以怎么办？」"},{"imageUrl":null,"instruction":"等他想（搬椅子、拿棍子、找大人帮忙）。"},{"imageUrl":null,"instruction":"任何办法都先肯定，再一起试试看。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '给两个选项让他选'),
  `harder` = COALESCE(`harder`, '完全自己想出办法。'),
  `tip` = COALESCE(`tip`, '大人「忍住不帮」的那几十秒，就是孩子长出解决能力的时候。求助也是一种好办法，别否定它。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十四（执行功能）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"东西拿不到，孩子哭了——这是最好的学习时刻。先别帮他，问一句：你觉得可以怎么办？","principles":["解决问题的能力，只能在真的遇到问题时才练得到。","大人太快出手，等于把学习的机会拿走了。","「你觉得可以怎么办」这一句，把问题交回给他。","交回去的那一刻，他才从求助者变成思考者。","要留时间让他想，三到五秒的沉默是必要的。","任何办法都先肯定，哪怕听起来行不通。","因为被否定的孩子，下次就不想出主意了。","肯定之后一起试试看，不成再想下一个。","难度要刚好：差一点点就拿得到，太高会直接崩溃。"],"prep":{"场地":"客厅或房间，有稳固的矮凳或椅子可用。","器材":"孩子想要的东西，放在他差一点点拿不到的高度。","安全检查":"物品不放在会砸到人的位置；不放在需要爬柜子、踩桌子的高度；提供稳固的矮凳，不使用有轮子的椅子。","大人位置":"大人在旁边不出手，但随时可以接住。"},"shots":[{"name":"拿不到","say":"（孩子伸手构不到架上的玩具）"},{"name":"先别帮","say":"（大人站在旁边没有动）"},{"name":"把问题交回去","say":"你觉得可以怎么办？"},{"name":"留时间给他想","say":"（沉默三到五秒）"},{"name":"他想到了","say":"（孩子去搬小凳子）"},{"name":"先肯定再试","say":"这个办法不错，我们试试看！"}],"reactions":[{"if":"孩子直接哭了","then":"先安抚情绪，等他平静一点再问。情绪来的时候想不出办法。"},{"if":"孩子完全想不出来","then":"给两个选项：「搬凳子，还是找大人帮忙？」选择也是一种思考。"},{"if":"孩子的办法行不通","then":"还是先肯定，然后一起试。失败的尝试也是在学。"}],"mistakes":["太快帮他拿下来，学习机会就没了。","问完不等就自己说出答案。","否定他的办法：「那样不行啦。」下次他就不想了。"],"down":"给两个办法让他选，并陪着他一起执行。","up":"完全自己想出办法并执行，不成功还能想第二个。","progress":["遇到困难会不会先想而不是先哭。","想不想得出办法。","一个办法不成会不会想第二个。"],"outro":"先别帮，问一句「你觉得可以怎么办」，然后等三到五秒。任何办法都先肯定——被否定过的孩子，下次就不想了。"}' AS JSON))
WHERE `id` = 'A281';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '一个问题想出好几种办法，练思考的弹性。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"提一个小问题：「纸箱怎么变成好玩的东西？」"},{"imageUrl":null,"instruction":"让孩子想一个办法。"},{"imageUrl":null,"instruction":"再问「还有别的方法吗？」"},{"imageUrl":null,"instruction":"把所有点子都记下来，不评价好坏。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '想出一个办法'),
  `harder` = COALESCE(`harder`, '想出三个以上不同的方法。'),
  `tip` = COALESCE(`tip`, '「还有别的方法吗」这一句，能把孩子的思考从一条路变成一片田。先不评价好坏，点子才出得来。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十五（创造力与高阶思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"想出一个办法不难，难的是想出第二个、第三个。今天练的是思考的弹性。","principles":["很多孩子想到第一个办法就停了，认为问题已经解决。","但真实世界里，第一个办法常常行不通。","能想出好几种办法的人，卡住的机会小很多。","「还有别的方法吗」这一句，就是在撑开思考的空间。","关键是不评价好坏，全部先记下来。","一评价，孩子就会开始自我审查，点子就变少了。","发散阶段要广，收敛阶段才挑好的，两个阶段要分开。","把点子写下来或画下来，看得见会让他想得更多。","这个习惯日后在写作文、做专题、解难题时都用得上。"],"prep":{"场地":"桌边，两人一起看得到纸的位置。","器材":"纸笔用来记录点子；一个待解决的小问题。","安全检查":"无特殊风险。点子若涉及危险操作，记下来但注明不实行。","大人位置":"大人负责记录，全程不评价好坏。"},"shots":[{"name":"提出问题","say":"这个纸箱可以变成什么？"},{"name":"第一个点子","say":"（孩子说「车子」）"},{"name":"追问","say":"还有别的方法吗？"},{"name":"点子越来越多","say":"房子、船、山洞、机器人……"},{"name":"不评价","say":"（大人只记录，不说好不好）"},{"name":"最后再挑","say":"那我们今天先做哪一个？"}],"reactions":[{"if":"孩子只想得出一个","then":"由大人抛一个很夸张的点子，打开他的想象空间。"},{"if":"孩子的点子不合理","then":"照样写下来。发散阶段不评价，合不合理等一下再谈。"},{"if":"孩子说没有了","then":"换一个角度问：「如果把它倒过来呢？」换角度常常会冒出新点子。"}],"mistakes":["第一个点子就开始评价，思考马上收紧。","只问一次就结束，没有追问第二个。","大人主导想点子，孩子变成旁听。"],"down":"想出一个办法就好，由大人示范再加一个。","up":"想出三个以上不同方向的办法，并说明各自的优缺点。","progress":["能想出几个办法。","点子之间有没有差异（还是同一类的变形）。","会不会自己主动想第二个。"],"outro":"全部记下来，先不要评价好坏。发散的时候要广，挑选是后面的事——两个阶段分开，点子才出得来。"}' AS JSON))
WHERE `id` = 'A282';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '坏掉的小东西'),
  `trains` = COALESCE(`trains`, '面对问题先找原因，再想办法。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"玩具不动了、积木倒了、拼图少一块。"},{"imageUrl":null,"instruction":"先问「为什么会这样？」"},{"imageUrl":null,"instruction":"再问「可以怎么办？」"},{"imageUrl":null,"instruction":"一起动手试试他的方法。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '找出明显的原因'),
  `harder` = COALESCE(`harder`, '想出解决办法并试成功。'),
  `tip` = COALESCE(`tip`, '「先找原因、再想办法」是解决问题的固定套路——教会这个顺序，比帮他修好有价值得多。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"玩具不动了、积木倒了——先别急着修。问两句：为什么会这样？可以怎么办？","principles":["解决问题有两个步骤：先找原因，再想办法。","很多孩子（和大人）跳过第一步，直接乱试。","没有找原因就动手，常常越弄越糟。","所以第一句一定是「为什么会这样」。","找原因需要观察和推理，这本身就是重要的练习。","找到原因之后，办法通常就浮出来了。","一起动手试他的方法，让思考和行动连起来。","试失败也没关系，那代表原因可能猜错了，回头再找。","这个「找原因—想办法—试—回头修正」的循环，就是解决问题的完整流程。"],"prep":{"场地":"桌边，光线足够看清楚细节。","器材":"真的坏掉或卡住的小东西（电池没电的玩具、倒掉的积木、少一块的拼图）。","安全检查":"不拆解电器或插电产品；不让孩子接触电池液、锐利断口或小零件；拆装由大人主导。","大人位置":"大人坐在旁边，手不先动，让孩子先观察。"},"shots":[{"name":"东西坏了","say":"（玩具不动了）"},{"name":"先问原因","say":"为什么会这样？"},{"name":"一起观察","say":"我们看看开关、看看电池。"},{"name":"再问办法","say":"那可以怎么办？"},{"name":"动手试","say":"（换上电池）"},{"name":"成功或失败","say":"（玩具动了，或还是不动，再想）"}],"reactions":[{"if":"孩子说不出原因","then":"一起把可能的地方一个一个看过：「开关？电池？还是卡住了？」"},{"if":"孩子直接说要买新的","then":"先试试修：「我们先看看能不能修好。」修理本身就是练习。"},{"if":"真的修不好","then":"那也很好。一起说出「我们试了三个方法都不行」，过程比结果有价值。"}],"mistakes":["跳过找原因，直接动手乱试。","大人一手包办修好，孩子只是旁观。","让孩子拆解电器或接触电池，这不安全。"],"down":"原因很明显的状况（积木没对齐），并由大人指出观察的方向。","up":"自己找出原因、想出办法并成功修好，或能说出试过哪些方法。","progress":["会不会先找原因再动手。","能不能说出可能的原因。","想不想得出解决办法。"],"outro":"两句话的顺序不能反：先问「为什么会这样」，再问「可以怎么办」。跳过第一步，通常会越弄越糟。"}' AS JSON))
WHERE `id` = 'A283';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '2–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '一个纸箱'),
  `trains` = COALESCE(`trains`, '一样东西想出很多用法，练创造力。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"给孩子一个纸箱。"},{"imageUrl":null,"instruction":"问「这可以变成什么？」"},{"imageUrl":null,"instruction":"车子、房子、船、山洞、机器人都行。"},{"imageUrl":null,"instruction":"一起动手做出来。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '想出一种玩法'),
  `harder` = COALESCE(`harder`, '想出三种以上，并动手改造。'),
  `tip` = COALESCE(`tip`, '纸箱是最棒的玩具——没有固定玩法，孩子的想象力才有地方去。别急着买玩具，先给他一个箱子。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十五（创造力与高阶思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"一个纸箱，可以是车子、房子、船、山洞、机器人。给他一个纸箱，然后什么都别说。","principles":["开放性的材料没有固定玩法，创造力才有空间。","纸箱是最好的开放性材料：大、可改造、而且免费。","问「这可以变成什么」，把定义权交给孩子。","定义权在他手上，他才会真的去想。","大人不要先给建议，那会限制他的想象。","想到什么就一起动手做出来，让想法落地。","动手的过程中会遇到问题，那又是解决问题的练习。","做出来的东西不必好看，能玩就好。","同一个纸箱可以改造好几次，每次都是新的。"],"prep":{"场地":"客厅或阳台，有空间摊开改造的地方。","器材":"一个够大的纸箱；胶带、蜡笔，剪刀由大人使用。","安全检查":"剪裁一律由大人操作；纸箱不套住头部；箱内游戏时不密封开口，保持通风与视线。","大人位置":"大人负责剪裁与安全，创意完全交给孩子。"},"shots":[{"name":"给他一个纸箱","say":"这个可以变成什么？"},{"name":"大人什么都不说","say":"（大人安静等待）"},{"name":"他的想法","say":"（孩子说「变成车子」）"},{"name":"一起动手","say":"那车子需要什么？（轮子！）"},{"name":"大人负责剪","say":"（大人拿剪刀剪窗户）"},{"name":"玩起来","say":"（孩子坐进纸箱车里）"}],"reactions":[{"if":"孩子想不出来","then":"不给答案，改成给问题：「它有洞，可以做什么？」用特征引发想象。"},{"if":"孩子的想法做不出来","then":"一起简化：「那我们先做一部分。」不要否定原本的构想。"},{"if":"孩子做到一半想改","then":"完全可以。同一个纸箱改造好几次，本来就是这个活动的乐趣。"}],"mistakes":["大人先说「我们来做一台车吧」，创意就被定型了。","追求成品好看，孩子的参与感就没了。","让孩子自己用剪刀，这不安全。"],"down":"由大人问一个引导性问题（这个洞可以做什么），孩子想出一种玩法就好。","up":"想出三种以上不同的用途，并自己规划改造的步骤。","progress":["能想出几种用途。","会不会自己规划怎么做。","遇到做不出来时会不会调整。"],"outro":"给他一个纸箱，然后什么都别说。大人只负责剪刀和安全——创意的部分，完全交给他。"}' AS JSON))
WHERE `id` = 'A284';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '日常物品'),
  `trains` = COALESCE(`trains`, '跳脱物品原本的用途，练发散思考。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"拿一样东西（汤匙、毛巾、瓶子）。"},{"imageUrl":null,"instruction":"问「除了原本的用途，还能拿来做什么？」"},{"imageUrl":null,"instruction":"汤匙可以当铲子、当乐器、当镜子。"},{"imageUrl":null,"instruction":"越天马行空越好。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出一个新用法'),
  `harder` = COALESCE(`harder`, '说出三五个。'),
  `tip` = COALESCE(`tip`, '「不合理」的答案也要接住——创造力需要一个不怕说错的环境才长得出来。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十五（创造力与高阶思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"汤匙除了吃饭，还能做什么？当铲子、当乐器、当镜子——今天练的是跳出原本用途的思考。","principles":["每样东西都有一个「本来的用途」，那会限制思考。","心理学上叫功能固着，大人比小孩更容易被困住。","跳出原本用途，是创造力最基本的动作。","汤匙当铲子、当乐器、当镜子，都是把属性重新利用。","孩子其实很擅长这件事，只是常常被大人纠正回去。","所以越天马行空越要接住，不要说「那不是拿来这样用的」。","可以引导他看属性：它是硬的、弯的、会反光的。","从属性出发，新用途就冒出来了。","这个能力和日后解决问题时的资源运用直接相关。"],"prep":{"场地":"任何地方；家里现有的东西就是题目。","器材":"日常物品（汤匙、毛巾、瓶子、纸盘）。","安全检查":"排除会造成危险的用法（不当武器、不放入口鼻）；不用玻璃或锐利物品出题。","大人位置":"大人拿出一样东西，问完就等，不急着补充。"},"shots":[{"name":"拿出一样东西","say":"这是汤匙，除了吃饭还能做什么？"},{"name":"第一个新用途","say":"（孩子说「挖土」）"},{"name":"从属性出发","say":"它硬硬的、弯弯的、还会反光。"},{"name":"更多用途","say":"当乐器、当镜子、当杠杆。"},{"name":"越夸张越好","say":"（孩子说出很夸张的用法，大人笑着接住）"},{"name":"换一样东西","say":"那毛巾呢？"}],"reactions":[{"if":"孩子只说得出原本的用途","then":"从属性提示：「它是硬的，硬的东西可以做什么？」"},{"if":"孩子说出危险的用法","then":"笑着接住想法，但明确说「这个我们只用想的，不做」。"},{"if":"孩子想不出更多","then":"大人抛一个很夸张的，通常他就接得下去了。"}],"mistakes":["纠正孩子「那不是拿来这样用的」，思考马上关掉。","只问一次就换东西，没有追问更多。","用玻璃或锐利物品出题，不安全。"],"down":"从属性给提示，想出一个新用途就算成功。","up":"一样东西说出三五个不同用途，并能说明为什么可以这样用。","progress":["能说出几个新用途。","会不会从属性去想。","会不会被原本的用途困住。"],"outro":"越天马行空越要接住。想不出来的时候，从属性提示他——它是硬的、弯的、会反光的。"}' AS JSON))
WHERE `id` = 'A285';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '积木、纸、书'),
  `trains` = COALESCE(`trains`, '用手边的材料解决一个具体问题。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"出题：「小车要过河，怎么办？」"},{"imageUrl":null,"instruction":"让孩子用积木或书搭一座桥。"},{"imageUrl":null,"instruction":"桥要够稳、够长。"},{"imageUrl":null,"instruction":"塌了就一起想为什么、再改进。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '搭一座短桥'),
  `harder` = COALESCE(`harder`, '桥要跨得更远，或能承重。'),
  `tip` = COALESCE(`tip`, '塌掉是最好的学习时刻——问「为什么会塌？」而不是直接帮他扶好。失败一次学到的，比成功三次还多。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"小车要过河，怎么办？给他积木和书，让他自己搭一座桥——塌了更好，那才是学习开始的地方。","principles":["有明确目标的任务，比自由玩更能练到解决问题。","目标很清楚：车要过去，桥要够长够稳。","孩子必须在限制条件下想办法，这就是工程思维。","塌了不是失败，是回馈——它告诉你哪里不够。","所以塌了要问「为什么会塌」，而不是「再来一次」。","找出原因再改进，这个循环才是核心。","常见的发现：底座要宽、要对齐、中间要有支撑。","这些原理不用教，让他在尝试中自己发现最有价值。","成功之后加难度：跨得更远，或要能承重。"],"prep":{"场地":"地板或大桌面，有空间摆开材料。","器材":"积木、几本书、纸板；一台小车当测试工具。","安全检查":"不叠高过孩子坐着的头顶；不使用玻璃或重物当桥面；塌落时注意脚部。","大人位置":"大人坐在旁边不出手，只在孩子求助时给提示。"},"shots":[{"name":"出题","say":"小车要过河，怎么办？"},{"name":"他开始搭","say":"（孩子架起纸板）"},{"name":"塌了","say":"（桥塌下来）"},{"name":"问为什么","say":"为什么会塌？"},{"name":"改进","say":"（孩子加宽底座或加支撑）"},{"name":"车过去了","say":"成功了！"}],"reactions":[{"if":"孩子一直塌一直沮丧","then":"缩短距离，让它先成功一次。成功之后再把距离拉远。"},{"if":"孩子要大人帮忙搭","then":"只给提示：「你觉得哪里不够稳？」手不要伸进去。"},{"if":"孩子随便搭不想改进","then":"用小车来测试：「我们让车开过去看看。」让任务本身给回馈。"}],"mistakes":["大人直接搭好一座桥给他看，学习机会就没了。","塌了只说「再来一次」，没有问为什么。","距离设太远，孩子一直失败就放弃。"],"down":"距离很短，并提供稳固的材料（厚书、大积木）。","up":"距离拉远、桥面要能承重，或限制只能用某几种材料。","progress":["塌了会不会去想原因。","会不会调整结构再试。","能搭多长多稳的桥。"],"outro":"塌了不是失败，是回馈。要问的是「为什么会塌」，不是「再来一次」——找出原因再改，那才是学习。"}' AS JSON))
WHERE `id` = 'A286';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '积木或杯子'),
  `trains` = COALESCE(`trains`, '在动手尝试中发现原理。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"让孩子把积木叠高。"},{"imageUrl":null,"instruction":"倒了问「怎样才不会倒？」"},{"imageUrl":null,"instruction":"试试看：大的放下面、对齐、底座宽一点。"},{"imageUrl":null,"instruction":"发现方法后再挑战更高。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '叠三块不倒'),
  `harder` = COALESCE(`harder`, '叠十块以上，或用不规则的东西叠。'),
  `tip` = COALESCE(`tip`, '孩子在一次次倒塌中会自己发现「大的要放下面」——这种自己发现的道理，记得最牢。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"积木叠高就倒——倒了正好。问一句「怎样才不会倒」，让他自己发现里面的原理。","principles":["叠高是孩子最爱的活动之一，也是最好的物理实验。","倒了会立刻给回馈，不需要大人评分。","这种即时的自然回馈，是最好的学习条件。","问「怎样才不会倒」，把注意力从结果转到方法。","孩子会开始注意到几个原理：大的放下面、要对齐、底座要宽。","这些原理不用教，让他自己试出来记得最牢。","大人的角色是提出问题，不是给答案。","发现方法之后再挑战更高，成就感会推着他继续。","用不规则的东西叠（水果、书、玩具）难度会明显提高。"],"prep":{"场地":"平坦稳固的桌面或地板。","器材":"积木、纸杯或其他可以堆叠的物品。","安全检查":"不叠高过孩子坐着的头顶；倒塌方向避开脸部；不使用玻璃或重物堆叠。","大人位置":"大人坐在旁边，只提问不出手。"},"shots":[{"name":"开始叠","say":"我们来叠高高。"},{"name":"倒了","say":"（塔倒下来）"},{"name":"问方法","say":"怎样才不会倒？"},{"name":"试试看","say":"大的放下面试试看。"},{"name":"对齐","say":"对齐一点、底座宽一点。"},{"name":"挑战更高","say":"这次叠十块！"}],"reactions":[{"if":"孩子倒了就生气","then":"先笑给他看。倒了是这个游戏的一部分，不是失败。"},{"if":"孩子想不出方法","then":"并排做两个示范：一个大的在下、一个小的在下，让他比较。"},{"if":"孩子只想叠很快","then":"改成计时赛的反向玩法：比谁叠得稳，撑得久才赢。"}],"mistakes":["大人直接告诉他「大的要放下面」，发现的乐趣就没了。","倒了就说「你太粗鲁了」，孩子会怕失败。","叠得太高，倒下来会砸到人。"],"down":"只叠三块，并使用底面大、好堆叠的积木。","up":"叠十块以上，或使用不规则的物品（水果、书、玩偶）。","progress":["能叠几块不倒。","会不会自己调整方法。","说不说得出为什么会稳。"],"outro":"倒了正好，那就是最好的回馈。你只要问一句「怎样才不会倒」——原理让他自己发现，记得最牢。"}' AS JSON))
WHERE `id` = 'A287';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '孩子会的一件事'),
  `trains` = COALESCE(`trains`, '把会的东西教给别人，是最高级的理解。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"请孩子教你一件他会的事（穿鞋、玩一个游戏）。"},{"imageUrl":null,"instruction":"你装作不会，让他一步步教。"},{"imageUrl":null,"instruction":"故意做错让他纠正。"},{"imageUrl":null,"instruction":"教完谢谢他。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '教一个简单动作'),
  `harder` = COALESCE(`harder`, '教一个有好几步的事。'),
  `tip` = COALESCE(`tip`, '能教别人，代表是真的懂了——而且当老师的感觉，会让孩子对学习更有兴趣。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十七（学习策略与元认知）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"请孩子教你一件他会的事。能把事情教会别人，代表他是真的懂了——这是理解的最高层次。","principles":["要教会别人，必须先把步骤在脑中理清楚。","所以教学是检验理解最严格的方式。","孩子在教的过程中，会发现自己有些地方其实没那么清楚。","这个发现本身就是学习。","大人要装作不会，让他一步一步教。","装得越像，他需要说得越清楚。","故意做错一步，让他纠正，那会逼他注意细节。","教完要谢谢他，让这个角色是被尊重的。","被当成老师的孩子，自信和表达能力都会跟着长。"],"prep":{"场地":"任何地方，看孩子要教什么而定。","器材":"依教学内容而定（鞋子、玩具、游戏）。","安全检查":"不请孩子教涉及危险的事（用刀、开火、用电）；示范内容限于安全动作。","大人位置":"大人认真扮演学生，不抢话不补充。"},"shots":[{"name":"请他当老师","say":"你教我怎么绑鞋带好不好？"},{"name":"他开始教","say":"（孩子一步一步说明）"},{"name":"大人装不会","say":"然后呢？我这样对吗？"},{"name":"故意做错","say":"（大人故意穿反）"},{"name":"他纠正你","say":"（孩子说「不对，要这样」）"},{"name":"谢谢老师","say":"谢谢老师，我学会了！"}],"reactions":[{"if":"孩子说不清楚步骤","then":"问具体的问题：「第一步要做什么？」用问题帮他分步。"},{"if":"孩子直接动手帮你做","then":"把手收回来：「我自己做，你告诉我怎么做。」教是用说的。"},{"if":"孩子不想教","then":"换一件他很拿手又很喜欢的事，动机会高很多。"}],"mistakes":["大人一边被教一边补充说明，角色就乱了。","孩子说不清楚就接手做完。","请孩子教涉及危险的事。"],"down":"教一个只有一两步的简单动作，并由大人提问引导分步。","up":"教一件有好几个步骤的事，并能在大人做错时说明哪里错了。","progress":["能不能说出步骤。","步骤的顺序清不清楚。","大人做错时会不会指出来。"],"outro":"装作不会，让他一步一步教你。故意做错一步让他纠正——教得会别人，才是真的懂了。"}' AS JSON))
WHERE `id` = 'A288';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '任何要动手的活动'),
  `trains` = COALESCE(`trains`, '动手之前先想一下计划。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"做事前问「你打算怎么做？」"},{"imageUrl":null,"instruction":"让他说出计划再动手。"},{"imageUrl":null,"instruction":"做的过程中对照计划。"},{"imageUrl":null,"instruction":"做完聊聊「跟原本想的一样吗？」"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出第一步'),
  `harder` = COALESCE(`harder`, '说出完整的计划步骤。'),
  `tip` = COALESCE(`tip`, '「先想再做」能减少很多挫折——想清楚了再动手，比做错了重来快得多。这个习惯将来在写作业时特别有用。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十四（执行功能）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"动手之前先问一句「你打算怎么做」。这一句，把冲动的孩子变成有计划的孩子。","principles":["很多孩子做事是边做边想，结果常常做到一半卡住。","先想再做，是执行功能中很重要的计划能力。","「你打算怎么做」这一句，就是在启动计划。","说出来的计划比脑中的计划清楚，因为语言会逼他理清楚。","做的过程中对照计划，会发现哪里和想的不一样。","这个对照就是监控，是执行功能的另一个成分。","做完聊「跟原本想的一样吗」，那是反思。","计划、监控、反思，这三步合起来就是完整的自我调节。","一开始只要说出第一步就好，不必完整。"],"prep":{"场地":"任何要动手的活动之前。","器材":"依活动而定（画画、堆积木、做劳作）。","安全检查":"无特殊风险。活动本身的安全依该活动规定。","大人位置":"大人在动手前问一句，然后不打断他执行。"},"shots":[{"name":"动手之前","say":"你打算怎么做？"},{"name":"他说出计划","say":"（孩子说「我要先画天空」）"},{"name":"开始做","say":"（孩子动手）"},{"name":"中途对照","say":"现在跟你想的一样吗？"},{"name":"计划改了也可以","say":"（孩子说「我改成先画树」）"},{"name":"做完聊一聊","say":"跟原本想的一样吗？"}],"reactions":[{"if":"孩子说不出计划","then":"只问第一步：「你要先做什么？」一步也是计划。"},{"if":"孩子做到一半完全变了","then":"不纠正。问一句「你改成这样了对吗」，让他意识到改变。"},{"if":"孩子觉得被打断","then":"那就只在开始前问，中途不问。时机比次数重要。"}],"mistakes":["要求完整的计划，孩子说不出来就放弃。","中途一直打断，破坏专注。","计划改了就说他没恒心，孩子会不敢说计划。"],"down":"只问第一步要做什么，不要求完整计划。","up":"说出完整的步骤计划，并在做完后比较计划与实际的差异。","progress":["动手前会不会先想。","说不说得出步骤。","做完能不能比较计划与实际。"],"outro":"动手前问一句「你打算怎么做」，做完再问一句「跟原本想的一样吗」。计划、监控、反思，三步就齐了。"}' AS JSON))
WHERE `id` = 'A289';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '任何小任务'),
  `trains` = COALESCE(`trains`, '学会「准备→做→收拾检查」的完整流程。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"做任何事都走三步：拿出要用的→完成它→收好检查。"},{"imageUrl":null,"instruction":"画一张三步的图贴在桌边。"},{"imageUrl":null,"instruction":"每一步做完再进下一步。"},{"imageUrl":null,"instruction":"三步都做完才算完成。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '跟着提示走三步'),
  `harder` = COALESCE(`harder`, '自己完整走完不用提醒。'),
  `tip` = COALESCE(`tip`, '很多孩子做完事情东西丢一桌——不是懒，是不知道「收拾也是任务的一部分」。三步图一贴，问题就少一半。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十四（执行功能）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"做任何事都走三步：拿出要用的、完成它、收好检查。这三步一旦变成习惯，孩子做事会完全不一样。","principles":["很多孩子做事有头没尾：开始很快，收尾没有。","因为在他的概念里，「做完」就是主要的事情做完了。","准备和收拾没有被算进任务里。","所以要把任务定义成三步：准备、执行、收拾检查。","三步都做完才算完成，这个定义要讲清楚。","画一张三步图贴在桌边，让流程看得见。","每一步做完再进下一步，不要跳。","这个结构可以套用在任何任务上，通用性很高。","养成之后，孩子做事的完整度会明显提高。"],"prep":{"场地":"孩子固定做事的桌面或活动区。","器材":"纸笔画三步图；一个小任务。","安全检查":"无特殊风险。收拾时不搬重物、不爬高放东西。","大人位置":"大人第一次带着走完三步，之后只指着图提示。"},"shots":[{"name":"画三步图","say":"准备、做、收好检查。"},{"name":"第一步准备","say":"先拿出要用的东西。"},{"name":"第二步做","say":"（专心完成任务）"},{"name":"第三步收好","say":"收好、检查一下。"},{"name":"三步都做完才算完成","say":"（字幕强调这句）"},{"name":"贴在桌边","say":"贴在这里，每次都看得到。"}],"reactions":[{"if":"孩子做完就跑走","then":"不责备，指着三步图说「还有第三步」。用图提示比用嘴唠叨有效。"},{"if":"孩子觉得收拾很麻烦","then":"和他一起收，并把收拾时间控制在两分钟内。"},{"if":"孩子跳过准备直接开始","then":"停下来一起补：「我们先看看需要什么。」准备省不得。"}],"mistakes":["只要求收拾，没有把它纳入任务的定义。","大人帮忙收拾，孩子就学不会第三步。","三步图只画一次就收起来，没有贴出来。"],"down":"大人带着走完三步，第三步只要求收一样东西。","up":"自己完整走完三步不用提醒，并能套用到不同的任务上。","progress":["会不会做准备的动作。","做完会不会收拾。","需不需要提醒。"],"outro":"三步都做完，才算完成——这个定义要讲清楚。图贴在桌边，提醒的时候用指的，不用唠叨。"}' AS JSON))
WHERE `id` = 'A290';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '任何完成的作品或任务'),
  `trains` = COALESCE(`trains`, '养成检查的习惯。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"完成后问「检查一下，有没有漏掉的？」"},{"imageUrl":null,"instruction":"教他从头看一遍。"},{"imageUrl":null,"instruction":"找到漏掉的就补上。"},{"imageUrl":null,"instruction":"检查出来了要大力称赞。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '大人带着检查'),
  `harder` = COALESCE(`harder`, '自己主动检查并找出问题。'),
  `tip` = COALESCE(`tip`, '「自己检查出来」比「被大人挑出来」有价值得多——发现错误也要称赞，孩子才不会怕犯错。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十七（学习策略与元认知）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"做完了先别收——检查一下，有没有漏掉的？检查这件事，是可以教也必须教的习惯。","principles":["很多孩子不会检查，因为他们不知道检查要看什么。","所以不能只说「检查一下」，要教他怎么检查。","最简单的方法是从头看一遍，一项一项对。","有清单的话就照着清单核对，那更可靠。","找到漏掉的要大力称赞，称赞的是「你检查出来了」。","如果找到错误却被责备，孩子下次就不敢检查了。","检查出错误是好事，这个态度要非常明确。","一开始由大人带着检查，慢慢变成他自己做。","这个习惯会一路影响到写作业、考试和日后的工作。"],"prep":{"场地":"任务完成的地方。","器材":"刚完成的作品或任务；有清单更好。","安全检查":"无特殊风险。检查时不重新拆解已完成的成品造成挫折。","大人位置":"大人和孩子一起从头看一遍，不先指出问题。"},"shots":[{"name":"做完了","say":"（孩子完成一件事）"},{"name":"先别收","say":"检查一下，有没有漏掉的？"},{"name":"教怎么检查","say":"我们从头看一遍。"},{"name":"找到漏掉的","say":"（孩子发现少了一样）"},{"name":"大力称赞","say":"你检查出来了，太厉害了！"},{"name":"补上","say":"我们把它补上。"}],"reactions":[{"if":"孩子说不用检查","then":"一起检查一次，并让他亲自发现一个漏掉的。发现的经验最有说服力。"},{"if":"孩子检查不出来","then":"给范围：「你看看左边这一区。」缩小范围就找得到。"},{"if":"孩子找到错误很沮丧","then":"明确说「找到错误是好事，不是坏事」。态度要非常清楚。"}],"mistakes":["只说「检查一下」，没有教怎么检查。","找到错误就责备，孩子下次不敢检查。","大人替他检查并改好，习惯就养不成。"],"down":"大人带着从头看一遍，并把范围缩小到一小块。","up":"自己主动检查、自己找出问题并修正。","progress":["做完会不会检查。","会不会从头一项一项看。","能不能自己找出问题。"],"outro":"不能只说「检查一下」，要教他从头一项一项看。找到错误一定要称赞——找到错误是好事。"}' AS JSON))
WHERE `id` = 'A291';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '纸笔'),
  `trains` = COALESCE(`trains`, '为想做的事列一个简单计划。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"问「今天想做什么？」"},{"imageUrl":null,"instruction":"一起列出要做的两三件事。"},{"imageUrl":null,"instruction":"排出先后顺序。"},{"imageUrl":null,"instruction":"做完一件打个勾。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '列两件事'),
  `harder` = COALESCE(`harder`, '列五件并自己排顺序。'),
  `tip` = COALESCE(`tip`, '打勾的成就感会让孩子想继续——从两件小事开始，别一开始就排满整天。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十四（执行功能）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"今天想做什么？一起列两三件，排个顺序，做完打勾。这是孩子人生第一份待办清单。","principles":["把想做的事写下来，脑中的模糊就变成具体的项目。","写下来之后，他才看得见今天要做多少事。","两三件是很好的起点，太多会变成压力。","排先后顺序是另一层能力：判断哪个先做。","做完打勾的动作很重要，那是完成的仪式。","打勾会带来明确的成就感，推动下一件。","清单也让他看见自己一天做了多少事。","不一定要写字，用画的一样有效。","这个习惯会一路用到学生时代和成年之后。"],"prep":{"场地":"桌边，早上或前一天晚上都可以。","器材":"纸笔或小白板；贴纸用来打勾也可以。","安全检查":"无特殊风险。计划内容不含需要大人陪同却无人在场的活动。","大人位置":"大人陪着列，但项目由孩子决定。"},"shots":[{"name":"今天想做什么","say":"今天你想做哪几件事？"},{"name":"列两三件","say":"（孩子说，一起写或画下来）"},{"name":"排顺序","say":"哪个先做？"},{"name":"完成第一件","say":"（孩子做完第一件事）"},{"name":"打勾","say":"打勾！"},{"name":"看看今天做了多少","say":"你看，三件都完成了。"}],"reactions":[{"if":"孩子列了十件事","then":"一起挑出今天最想做的三件，其他的放到明天的清单。"},{"if":"孩子做不完","then":"不责备。没做完的移到明天，清单是工具不是考核。"},{"if":"孩子不想写字","then":"用画的，或用贴纸代表。形式不重要。"}],"mistakes":["大人决定清单内容，孩子就没有主导权。","项目太多，孩子做不完会挫折。","没做完就责备，清单变成压力来源。"],"down":"只列两件事，并由大人代写，孩子负责打勾。","up":"列五件并自己排顺序，还能说明为什么这样排。","progress":["能不能说出想做的事。","会不会排先后顺序。","完成率如何。"],"outro":"两三件就好，太多会变成压力。做完打个勾——那个勾，是他人生第一次看见自己完成了什么。"}' AS JSON))
WHERE `id` = 'A292';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '学会排优先级。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"有几件事要做时，一起讨论「哪个先做？」"},{"imageUrl":null,"instruction":"问「哪个最重要／最急？」"},{"imageUrl":null,"instruction":"定好顺序照着做。"},{"imageUrl":null,"instruction":"做完聊聊这个顺序好不好。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '两件事排先后'),
  `harder` = COALESCE(`harder`, '三四件并说出理由。'),
  `tip` = COALESCE(`tip`, '排优先级是很实用的能力——先写作业还是先玩，讨论出来的顺序比命令的顺序，孩子执行得更甘愿。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十四（执行功能）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"有三件事要做，先做哪一个？判断优先级，是大人都不一定做得好的能力——今天从两件事开始。","principles":["排优先级需要比较事情的重要性和急迫性。","这对孩子来说很抽象，所以要给具体的判断标准。","两个问题最好用：哪个最重要？哪个最急？","重要和急迫不一样，这个区分本身就是学习。","从两件事开始，选项少才容易比较。","定好顺序就照着做，不中途换来换去。","做完聊聊「这个顺序好不好」，那是反思。","有时候会发现顺序排错了，那也是很好的经验。","这个能力会一路用到写作业、准备考试和工作。"],"prep":{"场地":"有几件事要做的时候，任何地方。","器材":"不需要任何东西；纸笔可以把事情写下来比较。","安全检查":"无特殊风险。安全相关的事（吃药、就医）不开放排序，由大人决定。","大人位置":"大人陪着讨论，但让孩子做决定。"},"shots":[{"name":"有几件事","say":"今天要收玩具、洗澡、看绘本。"},{"name":"问哪个先","say":"你觉得哪个先做？"},{"name":"两个判断标准","say":"哪个最重要？哪个最急？"},{"name":"定好顺序","say":"（标上1、2、3）"},{"name":"照着做","say":"（依序完成）"},{"name":"做完反思","say":"这个顺序好不好？"}],"reactions":[{"if":"孩子想把最好玩的排第一","then":"那也可以试一次。做完一起看结果，经验比说教有效。"},{"if":"孩子说不出理由","then":"用两个问题引导：「这个不做会怎样？那个呢？」"},{"if":"孩子中途想换顺序","then":"温和地说「我们先照原本的走完」，做完再一起检讨。"}],"mistakes":["大人直接指定顺序，孩子学不到判断。","一次排四五件，超过他的比较能力。","顺序排错就说他不会想，下次他不敢决定。"],"down":"只排两件事，并由大人提供两个判断问题。","up":"排三四件并说出理由，做完能检讨顺序是否合理。","progress":["能不能排出顺序。","说不说得出理由。","做完能不能检讨。"],"outro":"两个问题就够：哪个最重要？哪个最急？排错了也没关系，做完一起看结果——那比说教有用。"}' AS JSON))
WHERE `id` = 'A293';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '综合线索推理出答案。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"出简单的谜语：「四条腿，不会走，可以坐」。"},{"imageUrl":null,"instruction":"让孩子猜。"},{"imageUrl":null,"instruction":"猜对了换他出题。"},{"imageUrl":null,"instruction":"线索由明显到隐晦。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '三个明显线索'),
  `harder` = COALESCE(`harder`, '线索抽象一点。'),
  `tip` = COALESCE(`tip`, '出谜语比猜谜语更难——孩子要想清楚特征、还要组织成线索。两边都在动脑，全家一起玩最好。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十八（逻辑推理与数理思维）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"四条腿，不会走，可以坐——是什么？谜语是最古老的推理游戏，而且全家都能玩。","principles":["谜语要求把好几条线索整合起来，缩小到一个答案。","每一条线索单独看都不够，必须合起来想。","这正是推理最核心的动作。","谜语的线索通常带有转折，需要跳出字面意思。","「不会走」但有「四条腿」，这个矛盾就是线索的巧妙处。","一开始用线索很明显的，让孩子有成功经验。","猜对了换他出题，出题比猜难得多。","因为他要先选定答案，再反推有哪些特征可以当线索。","全家一起玩会有更多角度，孩子也在听别人怎么想。"],"prep":{"场地":"餐桌、车上、睡前，任何地方。","器材":"不需要任何东西。","安全检查":"无特殊风险。谜底选孩子熟悉的东西，避免造成挫折。","大人位置":"大人先出题示范，线索一条一条给。"},"shots":[{"name":"出谜语","say":"四条腿，不会走，可以坐。"},{"name":"孩子想","say":"（孩子皱眉思考）"},{"name":"提示","say":"我们家里就有喔。"},{"name":"猜对了","say":"（孩子喊「椅子！」）"},{"name":"讲解线索","say":"四条腿是椅脚，不会走因为它不是动物。"},{"name":"换他出题","say":"换你出一个考我。"}],"reactions":[{"if":"孩子猜不到","then":"给范围提示：「在客厅里」「是家具」。缩小范围比给答案好。"},{"if":"孩子出的谜语说不清","then":"诚实说「我猜不到，再给一条线索」。回馈会教他。"},{"if":"孩子出题时直接说答案","then":"笑着说「那我就知道啦」，再玩一次。"}],"mistakes":["谜语太难，孩子一直猜不到就没兴趣。","猜中之后不讲解线索怎么对上，推理没有被看见。","只让孩子猜，不让他出题。"],"down":"三条明显的线索，并限定在眼前的房间里。","up":"线索抽象一点，或让孩子自己创作谜语。","progress":["几条线索之后能猜到。","会不会整合多条线索。","出题时线索够不够清楚。"],"outro":"猜中之后记得讲一下线索怎么对上的——让推理的过程被看见，他下次才会用同样的方法想。"}' AS JSON))
WHERE `id` = 'A294';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '轮流编故事，练想象和逻辑。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"大人开头：「从前有一只小熊，他走进森林……」"},{"imageUrl":null,"instruction":"孩子接一句。"},{"imageUrl":null,"instruction":"轮流接下去。"},{"imageUrl":null,"instruction":"故事再天马行空都接住。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '接一两句'),
  `harder` = COALESCE(`harder`, '接出有前后关系的完整故事。'),
  `tip` = COALESCE(`tip`, '接得不合逻辑也别打断——先让故事玩下去，孩子的想象力才敢跑。睡前、坐车时都能玩。'),
  `deeper` = COALESCE(`deeper`, '语言册 模组十二（叙事与复述）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"从前有一只小熊，他走进森林……然后呢？轮流接故事，再天马行空都要接住。","principles":["轮流编故事同时练到想象和逻辑。","想象负责产出新情节，逻辑负责让它接得上。","两者必须同时运作，所以这个游戏比看起来难。","大人开头要留下明确的悬念，孩子才好接。","接不上的时候给一个问句：「他遇到了谁？」","问句比提示好，因为它保留了孩子的创作权。","再天马行空都要接住，这是这个游戏的第一原则。","一旦开始纠正合不合理，孩子就不敢编了。","全家轮流会让故事的方向更意外，也更好玩。"],"prep":{"场地":"睡前床边、餐桌、车上都可以。","器材":"不需要任何东西。","安全检查":"无特殊风险。避免恐怖或暴力情节，尤其睡前。","大人位置":"大人开头并控制节奏，不主导情节方向。"},"shots":[{"name":"大人开头","say":"从前有一只小熊，他走进森林……"},{"name":"孩子接","say":"（孩子接一句）"},{"name":"轮流接","say":"（大人再接一句）"},{"name":"天马行空也接住","say":"（孩子说出很夸张的情节，大人照接）"},{"name":"卡住就给问句","say":"那他遇到了谁？"},{"name":"一起收尾","say":"最后小熊回家了。"}],"reactions":[{"if":"孩子接不下去","then":"给一个问句：「他看到了什么？」问句会打开方向，又不抢他的创作。"},{"if":"孩子的情节完全不合理","then":"照样接住。可以顺着它发展，逻辑会在过程中自己出现。"},{"if":"故事一直不结束","then":"用一句话收：「天黑了，小熊要回家了。」给一个自然的终点。"}],"mistakes":["纠正孩子的情节不合理，创作就停了。","大人主导整个故事的方向，孩子变成配角。","睡前编出恐怖情节，影响入睡。"],"down":"孩子只接一两句，其余由大人推动。","up":"接出有前后因果的完整故事，并能自己收尾。","progress":["愿不愿意接。","接的内容和前面有没有关系。","能不能自己把故事收尾。"],"outro":"第一原则：再天马行空都要接住。卡住的时候给一个问句，不要给提示——创作权要留在他手上。"}' AS JSON))
WHERE `id` = 'A295';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子或全家'),
  `need` = COALESCE(`need`, '手边的东西'),
  `trains` = COALESCE(`trains`, '自己创造玩法和规则。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"用手边的东西发明一个新游戏。"},{"imageUrl":null,"instruction":"每个人贡献一条规则。"},{"imageUrl":null,"instruction":"试玩、发现问题、一起改。"},{"imageUrl":null,"instruction":"给游戏起个名字。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '贡献一条规则'),
  `harder` = COALESCE(`harder`, '主导设计并说明玩法。'),
  `tip` = COALESCE(`tip`, '自己发明的游戏，孩子守规则守得最甘愿——因为那是「我们的」规则。这也是最高级的创造活动。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十二（合作任务·团体动力入门）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"用手边的东西发明一个新游戏，每个人贡献一条规则——这是创造力和协商能力一起上场。","principles":["发明游戏是很高阶的创造活动，因为要凭空建立规则。","规则必须自洽、可执行，还要好玩，条件不少。","每个人贡献一条规则，让这变成共同创作。","共同创作就会有协商，因为规则可能互相冲突。","试玩是关键：玩过才知道规则行不行得通。","发现问题一起改，这就是迭代。","创造、测试、修正，这个循环和工程设计是一样的。","给游戏起个名字，让它成为一个真正的作品。","之后还可以再玩、再改，游戏会跟着孩子长大。"],"prep":{"场地":"客厅或餐桌，有空间试玩。","器材":"手边现有的东西：球、纸杯、积木、抱枕。","安全检查":"规则不得包含奔跑撞击、丢掷硬物或爬高；试玩前清空场地；有肢体动作的规则由大人确认安全。","大人位置":"大人参与贡献规则，但不主导设计。"},"shots":[{"name":"找材料","say":"我们用这些东西发明一个游戏。"},{"name":"每人一条规则","say":"我出第一条：球要滚进杯子。"},{"name":"孩子的规则","say":"（孩子说「进了得一分」）"},{"name":"试玩","say":"我们试试看。"},{"name":"发现问题一起改","say":"太简单了，我们把杯子放远一点。"},{"name":"起名字","say":"这个游戏叫什么名字？"}],"reactions":[{"if":"孩子想不出规则","then":"从已知游戏改编：「像保龄球，但我们用……」改编比凭空创造容易。"},{"if":"规则互相冲突","then":"那正好。一起讨论要留哪一条，这就是协商。"},{"if":"游戏不好玩","then":"很正常。问「哪里不好玩？」然后一起改。修正才是重点。"}],"mistakes":["大人主导设计，孩子只是执行。","规则订完不试玩，问题都没发现。","规则包含奔跑撞击或丢硬物，不安全。"],"down":"从一个已知游戏改一条规则就好，不必从零开始。","up":"主导整个游戏的设计，并能向别人说明完整玩法。","progress":["能不能贡献规则。","试玩后会不会想修正。","能不能向别人说明玩法。"],"outro":"规则订完一定要试玩，不好玩就一起改。创造、测试、修正——这个循环，比游戏本身更有价值。"}' AS JSON))
WHERE `id` = 'A296';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '5–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '生活中的小状况'),
  `trains` = COALESCE(`trains`, '从别人的角度想问题。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"聊一个小状况：「弟弟抢你的玩具，他为什么这样做？」"},{"imageUrl":null,"instruction":"问「如果你是他，你会怎么想？」"},{"imageUrl":null,"instruction":"再问「有什么办法两个人都开心？」"},{"imageUrl":null,"instruction":"一起想双赢的办法。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出对方可能的想法'),
  `harder` = COALESCE(`harder`, '想出双方都能接受的办法。'),
  `tip` = COALESCE(`tip`, '「有没有两个人都开心的办法？」——这一句能把争执变成合作，是很值得教给孩子的思考方式。'),
  `deeper` = COALESCE(`deeper`, '社交情绪册 模组十（理解他人·观点与同理）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"弟弟抢你的玩具，他为什么这样做？——这个问题不是要他原谅，是要他先理解，才想得出办法。","principles":["冲突中的孩子只看得到自己的立场，这是正常的。","要解决冲突，必须先理解对方为什么这样做。","理解不等于同意，这一点要讲清楚。","「如果你是他，你会怎么想」，把视角切换过去。","视角切换之后，对方的行为就有了脉络。","有了脉络，才想得出双方都能接受的办法。","所以最后一定要问：「有什么办法两个人都开心？」","这是从理解走到解决，也是双赢思维的起点。","这个讨论要在平静的时候进行，冲突当下做不到。"],"prep":{"场地":"安静的地方，冲突过后双方都平静时。","器材":"不需要任何东西。","安全检查":"不在冲突当下进行这个讨论；不要求孩子立刻原谅或让步。","大人位置":"大人坐在孩子旁边，用讨论的语气而非评理。"},"shots":[{"name":"聊一个小状况","say":"刚才弟弟抢你的玩具。"},{"name":"先接住他的感受","say":"你一定很生气。"},{"name":"问对方的想法","say":"他为什么这样做？"},{"name":"切换视角","say":"如果你是他，你会怎么想？"},{"name":"理解不等于同意","say":"（字幕：理解他，不代表他做对了）"},{"name":"想双赢的办法","say":"有什么办法两个人都开心？"}],"reactions":[{"if":"孩子说「我不管他怎么想」","then":"先接住情绪，今天就到这里。理解需要余裕，情绪没消化完做不到。"},{"if":"孩子觉得你在帮对方说话","then":"明确说「我不是说他对，我是想知道发生什么事」。立场要讲清楚。"},{"if":"孩子想不出双赢的办法","then":"一起想两三个，哪怕不完美。想的过程比答案重要。"}],"mistakes":["在冲突当下要求孩子理解对方。","把理解讲成「你要让他」，孩子会觉得不公平。","大人直接给出解决办法，孩子没有参与。"],"down":"只做到说出对方可能的想法，不要求想解决办法。","up":"想出双方都能接受的办法，并能主动在下次冲突时使用。","progress":["能不能说出对方可能的想法。","知不知道理解不等于同意。","想不想得出双赢的办法。"],"outro":"理解他，不代表他做对了——这个区分一定要讲清楚。先理解，才想得出两个人都开心的办法。"}' AS JSON))
WHERE `id` = 'A297';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '4–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '回想并说出今天的收获，练反思。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"睡前问「今天学到什么新东西？」"},{"imageUrl":null,"instruction":"不一定是学校的事，玩到的、发现的都算。"},{"imageUrl":null,"instruction":"大人也分享自己今天学到的。"},{"imageUrl":null,"instruction":"答不出来给线索。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '说出一件事'),
  `harder` = COALESCE(`harder`, '说出学到什么以及怎么学到的。'),
  `tip` = COALESCE(`tip`, '「回想一下」的习惯很有价值——会反思的孩子，学习效率会越来越高。大人也分享，孩子才觉得这不是考试。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组十七（学习策略与元认知）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"今天学到什么新东西？——不一定是学校的事。玩到的、发现的、失败的，通通都算。","principles":["反思是把经验变成学习的关键一步。","没有反思，经验就只是经过，不会累积。","睡前问一句，就是给反思一个固定的时间。","「学到什么」的定义要放宽：玩到的、发现的都算。","定义太窄（只算学校的事），孩子常常答不出来。","答不出来就给线索：「今天玩了什么？有没有发现什么？」","大人也分享自己今天学到的，示范大人也在学。","这会传达一个重要讯息：学习是一辈子的事。","进阶是说出「怎么学到的」，那是对学习方法的觉察。"],"prep":{"场地":"睡前床边，灯光调暗。","器材":"不需要任何东西。","安全检查":"无特殊风险。不把这个问题变成检查学习成果。","大人位置":"大人坐或躺在孩子旁边，不看手机。"},"shots":[{"name":"睡前问一句","say":"今天学到什么新东西？"},{"name":"定义放宽","say":"玩到的、发现的都算喔。"},{"name":"孩子想","say":"（孩子回想）"},{"name":"给线索","say":"今天玩了什么？有没有发现什么？"},{"name":"大人也分享","say":"我今天学会了一个新食谱。"},{"name":"怎么学到的","say":"你是怎么发现的？"}],"reactions":[{"if":"孩子说没有","then":"给具体线索。或由大人先说自己的，示范之后他通常会跟上。"},{"if":"孩子说的是很小的事","then":"那更好。小事被看见，学习的定义才会放宽。"},{"if":"孩子把它当成考试","then":"改成大人先分享，并明确说「这不是考试，只是聊聊」。"}],"mistakes":["把「学到什么」限定在学校的课业。","孩子答不出来就说他今天都在玩。","变成检查学习成果，孩子会开始编答案。"],"down":"只问「今天有什么好玩的」，不用「学到」这个词。","up":"说出学到什么以及是怎么学到的，并能连到之前的经验。","progress":["能不能说出一件事。","说的内容范围有没有变广。","能不能说出怎么学到的。"],"outro":"定义要放宽：玩到的、发现的、失败的都算。大人也分享自己今天学到的——让他知道，学习是一辈子的事。"}' AS JSON))
WHERE `id` = 'A298';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '3–8岁'),
  `people` = COALESCE(`people`, '亲子'),
  `need` = COALESCE(`need`, '记录本或照片'),
  `trains` = COALESCE(`trains`, '看见自己的进步，建立成长的信心。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"翻出以前的画、照片、记录。"},{"imageUrl":null,"instruction":"比一比现在和以前。"},{"imageUrl":null,"instruction":"说「你以前不会，现在会了」。"},{"imageUrl":null,"instruction":"定一个下一个想学会的事。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '看出一样进步'),
  `harder` = COALESCE(`harder`, '说出自己怎么变厉害的。'),
  `tip` = COALESCE(`tip`, '孩子说「我不行」的时候，翻出以前的记录给他看——「你以前也说不行，后来做到了」。这是最有力的鼓励。'),
  `deeper` = COALESCE(`deeper`, '游戏册 模组二十（表达展示与成长反思）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"2 分钟","intro":"翻出半年前的画，和现在的放在一起——你以前不会，现在会了。这句话，比一百句加油有力量。","principles":["孩子看不见自己的进步，因为进步是慢慢发生的。","每天看自己，变化太小，察觉不到。","把以前和现在放在一起，差距就一目了然。","这个对比会带来非常强的自我效能感。","「你以前不会，现在会了」，说的是事实，不是安慰。","事实比鼓励有力量，因为它有证据。","所以平常要留纪录：画、照片、影片、成就本本。","看完之后定一个下一个想学会的事，把视线往前。","回顾加上展望，成长的感觉才完整。"],"prep":{"场地":"安静的地方，两人一起看得到纪录的位置。","器材":"以前的画、照片、影片或成就记录本。","安全检查":"无特殊风险。避免拿别的孩子来比较。","大人位置":"大人事先找出对比明显的两份纪录。"},"shots":[{"name":"翻出旧纪录","say":"这是你半年前画的。"},{"name":"和现在比","say":"这是你现在画的。"},{"name":"说出事实","say":"你以前不会，现在会了。"},{"name":"孩子的反应","say":"（孩子惊讶地看着两张画）"},{"name":"其他纪录","say":"（影片、照片、成就本本）"},{"name":"定下一个目标","say":"接下来你想学会什么？"}],"reactions":[{"if":"孩子觉得以前的很丑","then":"不否认，但把焦点放在变化：「所以你进步了好多对不对？」"},{"if":"孩子看不出差别","then":"指出具体的地方：「你看，以前没有手指，现在有五根。」"},{"if":"孩子想不出下一个目标","then":"给两个选项让他选。目标由他决定，动机才会在。"}],"mistakes":["拿别的孩子来比较，进步的焦点就歪了。","没有留纪录，就没有对比的材料。","只回顾不展望，成长的感觉不完整。"],"down":"只比一样具体的能力（会写自己的名字了），由大人指出差别。","up":"自己说出进步在哪里，以及自己是怎么变厉害的。","progress":["能不能看出自己的进步。","会不会说出进步在哪里。","能不能定出下一个目标。"],"outro":"平常要留纪录，才有材料可以比。「你以前不会，现在会了」——这是事实，比一百句加油有力量。"}' AS JSON))
WHERE `id` = 'A299';

UPDATE `activities` SET
  `age_label` = COALESCE(`age_label`, '全龄／收官'),
  `people` = COALESCE(`people`, '全家'),
  `need` = COALESCE(`need`, '不需要任何东西'),
  `trains` = COALESCE(`trains`, '把这 300 个活动的精神，变成每天的日常。'),
  `steps` = IF(JSON_LENGTH(`steps`) = 0, CAST('[{"imageUrl":null,"instruction":"每天动一动、说说话、玩一玩、抱一抱。"},{"imageUrl":null,"instruction":"让孩子多做一点自己的事。"},{"imageUrl":null,"instruction":"遇到问题多问一句「你觉得可以怎么办？」"},{"imageUrl":null,"instruction":"每天留一段只属于你们的时间。"},{"imageUrl":null,"instruction":"慢一点、不完美，都没关系。"}]' AS JSON), `steps`),
  `easier` = COALESCE(`easier`, '每天做到一两件'),
  `harder` = COALESCE(`harder`, '变成全家的生活方式。'),
  `tip` = COALESCE(`tip`, '这 300 个活动的重点从来不是「练完」，而是让陪伴变得更有方向。孩子需要的不是完美的训练，是一个愿意陪他玩、等他慢慢来的大人。你已经是了。'),
  `deeper` = COALESCE(`deeper`, '森心康另有五册共 1500 个活动的完整体系（游戏 · 语言 · 作业治疗 · 社交情绪 · 物理治疗）'),
  `guide` = COALESCE(`guide`, CAST('{"length":"3 分钟","intro":"这是第三百个活动，也是最后一个。它没有教具、没有步骤——它要说的是：这三百个活动的精神，其实只有几句话。","principles":["三百个活动，说到底是在做五件事。","每天动一动：身体好，脑子才好，情绪也才稳。","每天说说话：不是教他说话，是跟他说话。","每天玩一玩：玩就是幼儿的学习方式，不是学习之外的事。","每天抱一抱：安全感是所有能力发展的底座。","每天让他多做一点自己的事：会自己做，孩子才有自信。","还有一句贯穿全部三百个活动的话：遇到问题，多问一句「你觉得可以怎么办？」","最后一件事最重要——每天留一段只属于你们的时间。","慢一点、不完美，都没关系。孩子需要的不是完美的父母，是愿意陪的父母。"],"prep":{"场地":"家里任何角落；这一支影片拍的是日常。","器材":"不需要任何东西。","安全检查":"无特殊风险。孩子的发展有个别差异，若有明显落后或退步，请寻求专业评估。","大人位置":"大人不是老师，是同伴。"},"shots":[{"name":"每天动一动","say":"每天动一动。"},{"name":"每天说说话","say":"每天说说话。"},{"name":"每天玩一玩","say":"每天玩一玩。"},{"name":"每天抱一抱","say":"每天抱一抱。"},{"name":"多让他自己做","say":"多让他做一点自己的事。"},{"name":"只属于你们的时间","say":"每天留一段，只属于你们的时间。"}],"reactions":[{"if":"家长觉得做不到每天","then":"一周三次也很好。频率不是重点，持续才是。"},{"if":"家长觉得孩子进步太慢","then":"每个孩子的节奏不一样。看的是他和自己比，不是和别人比。"},{"if":"家长担心孩子的发展","then":"相信你的直觉。有疑虑就带去做专业评估，早发现早处理。"}],"mistakes":["把这三百个活动当成课表，每天赶进度。","拿孩子和别人比较，焦虑会传给孩子。","追求每个活动都做到完美，反而失去了陪伴本身。"],"down":"每天做到一两件就好，不必五件都做。","up":"把这几件事变成全家的生活方式，不再需要刻意提醒。","progress":["每天有没有一段专心陪伴的时间。","孩子会不会主动找你玩、找你说话。","遇到问题时，你有没有多问那一句「你觉得可以怎么办？」"],"outro":"三百个活动，说到底就是这几句：每天动一动、说说话、玩一玩、抱一抱，多让他自己做，遇到问题多问一句「你觉得可以怎么办」。慢一点、不完美，都没关系——孩子需要的不是完美的父母，是愿意陪的父母。"}' AS JSON))
WHERE `id` = 'A300';
-- ── 內容 END

-- ── 验证 ──────────────────────────────────────────────────────
-- _gone 必须回 0（migrate.mjs 的命名约定）。

-- 十一个新栏位一个都不能少。算的是「缺几个」，同 2026-09-11 的写法。
SELECT 11 - COUNT(*) AS activity_content_columns_missing_gone
  FROM information_schema.COLUMNS
 WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'activities'
   AND COLUMN_NAME IN ('age_label', 'people', 'need', 'trains', 'easier', 'harder', 'tip', 'deeper',
                       'guide', 'poster_url', 'video_seconds');

-- 三百张卡都写进去了。
SELECT COUNT(*) AS activity_content_unfilled_gone
  FROM `activities`
 WHERE `id` BETWEEN 'A001' AND 'A300'
   AND (`age_label` IS NULL OR `people` IS NULL OR `need` IS NULL OR `trains` IS NULL
        OR `easier` IS NULL OR `harder` IS NULL OR `tip` IS NULL OR `deeper` IS NULL);

-- 模组一的二十支都有脚本。
SELECT COUNT(*) AS activity_guides_unfilled_gone
  FROM `activities`
 WHERE `id` BETWEEN 'A001' AND 'A020' AND `guide` IS NULL;

-- 三百支都有步骤（手册的「怎么玩」，或内容团队在后台写的）。
SELECT COUNT(*) AS activity_steps_empty_gone
  FROM `activities`
 WHERE `id` BETWEEN 'A001' AND 'A300' AND JSON_LENGTH(`steps`) = 0;
